     */
    const YENI_MUSTERI_BASLANGIC = '2026-06-11 00:00:00';


    /**
     * Create a new controller instance.
     *
     * @return void
     */
    public function __construct()
    {
        $this->middleware(function ($request, $next) {
            // SELF-HEAL (impersonation kopma fix): cok-sekme/oturum-race isletmeyonetim
            // login'ini silmis olabilir. Dayanikli 'imp_iy' cookie'sinden ANINDA geri kur
            // (cookie oturum-race'e tabi degil). Hangi sekme ne yazarsa yazsin salon
            // oturumu kendini onarir, kullanici atilmaz.
            if (!Auth::guard('isletmeyonetim')->check() && !Auth::guard('satisortakligi')->check()) {
                $imp = $request->cookie('imp_iy');
                if ($imp && strpos($imp, '|') !== false) {
                    try {
                        list($yid, $lid) = explode('|', $imp, 2);
                        $y = \App\IsletmeYetkilileri::find($yid);
                        if ($y) {
                            $g = Auth::guard('isletmeyonetim');
                            session()->put($g->getName(), $y->getAuthIdentifier());
                            $g->setUser($y);
                            session()->put('sysadmin_impersonation_id', $lid);
                            session()->put('password_hash_isletmeyonetim', $y->getAuthPassword());
                            @file_put_contents(storage_path('logs/imptest.log'),
                                date('H:i:s') . ' [HEAL] iy geri kuruldu yetkili=' . $yid . ' /' . $request->path() . "\n", FILE_APPEND);
                        }
                    } catch (\Throwable $e) {}
                }
            }
            if (!Auth::guard('isletmeyonetim')->check() && !Auth::guard('satisortakligi')->check()) {
                // GECICI TESHIS: neden isletmeyonetim authed degil? (impersonation atma sorunu)
                try {
                    $iyKey = Auth::guard('isletmeyonetim')->getName();
                    $keys = array_values(array_filter(array_keys(session()->all()), function ($k) {
                        return strpos($k, 'login_') === 0 || strpos($k, 'impersonation') !== false || strpos($k, 'password_hash') !== false;
                    }));
                    @file_put_contents(storage_path('logs/imptest.log'),
                        date('H:i:s') . ' [KICK] ' . $request->method() . ' /' . $request->path()
                        . ' ajax=' . (($request->ajax() || $request->wantsJson()) ? 1 : 0)
                        . ' sid=' . substr((string) session()->getId(), 0, 10)
                        . ' sistem=' . (Auth::guard('sistemyonetim')->id() ?: '-')
                        . ' iy_key=' . (session()->has($iyKey) ? 'VAR(' . session($iyKey) . ')' : 'YOK')
                        . ' keys=[' . implode(',', $keys) . ']' . "\n", FILE_APPEND);
                } catch (\Throwable $e) {}
                if ($request->ajax() || $request->wantsJson() || $request->expectsJson()) {
                    return response()->json([
                        'error'    => 'session_expired',
                        'message'  => 'Oturumunuz sonlanmıştır. Tekrar giriş yapmanız gerekmektedir.',
                        'redirect' => url('/isletmeyonetim/girisyap'),
                    ], 401);
                }
                return redirect('/isletmeyonetim/girisyap')
                    ->with('session_expired', 'Oturumunuz sonlanmıştır. Tekrar giriş yapmanız gerekmektedir.');
            }

            return $next($request);
        })->except(['uygulamaIndir', 'seansDokumuPdf']); // uygulamaIndir: QR public; seansDokumuPdf: mobil API (oturumsuz) erisir

    }
    /**
     * Show the application dashboard.
     *
     * @return \Illuminate\Http\Response
     */
    /**
     * TL formatındaki fiyat string'ini ("1.234,56" veya "113,00") float'a çevirir.
     * Sayısal değerleri olduğu gibi döner. Örn: "1.234,56" → 1234.56, "113" → 113.0
     */
    public static function parseFiyat($val)
    {
        if($val === null || $val === '') return 0.0;
        if(is_numeric($val)) return (float) $val;
        $s = (string) $val;
        if(strpos($s, ',') !== false){
            return (float) str_replace(',', '.', str_replace('.', '', $s));
        }
        return (float) $s;
    }

    // Performans: e_asistan gibi sayfalarda 5-6 kez cagriliyor. Her cagri
    // user relation + (eskiden) loop icinde Salonlar query atiyordu. Cache.
    private static $_mevcutsubeCache = [];
    public function mevcutsube($request)
    {
        if(isset($request->sube))
            return $request->sube;

        // Request'siz cagri olabilir, host + auth user id'ye gore cache key
        $authId = Auth::guard('isletmeyonetim')->check()
            ? Auth::guard('isletmeyonetim')->user()->id
            : (Auth::guard('satisortakligi')->check() ? 'satisortakligi' : 'guest');
        $cacheKey = ($_SERVER['HTTP_HOST'] ?? '').'|'.$authId;
        if (array_key_exists($cacheKey, self::$_mevcutsubeCache)) {
            return self::$_mevcutsubeCache[$cacheKey];
        }

        $sube = "";
        $subeler = array();
        if(Auth::guard('satisortakligi')->check())
            $subeler = [15];
        else
            $subeler = Auth::guard('isletmeyonetim')->user()->yetkili_olunan_isletmeler->pluck('salon_id')->toArray();

        $apiHosts = ['app.randevumcepte.com.tr','apptest.randevumcepte.com.tr','demoapp.randevumcepte.com.tr','randevu.randevumcepte.com.tr'];
        if(!in_array($_SERVER['HTTP_HOST'] ?? '', $apiHosts, true)){
            // Eskiden loop icinde her iterasyonda ayni Salonlar query atiliyordu.
            // Tek seferde cek, sonra match et.
            $hostSalonId = Salonlar::where('domain',$_SERVER['HTTP_HOST'] ?? '')->value('id');
            foreach($subeler as $sube_list)
                if($hostSalonId == $sube_list)
                    $sube = $sube_list;
        }
        else
            $sube = $subeler[0] ?? '';

        return self::$_mevcutsubeCache[$cacheKey] = $sube;
    }
    public function carkifelek(Request $request){
        $isletmeler = '';
        $isletme='';
        if(Auth::guard('satisortakligi')->check())
        {
            $isletmeler = [15];
            $isletme = Salonlar::where('id',15)->first();
        }
        else{
            $isletmeler = Auth::guard('isletmeyonetim')->user()->yetkili_olunan_isletmeler->where('aktif',1)->pluck('salon_id')->toArray();
            $isletme= Salonlar::where('id',self::mevcutsube($request))->first();
        }
        
        
        if(!in_array(self::mevcutsube($request),$isletmeler ))
        {
            return view('isletmeadmin.yetkisizerisim');
            exit(0);
        }
        if(str_contains(self::lisans_sure_kontrol($request),'-'))
        {
            return view('isletmeadmin.lisanssurebitti',['isletme'=>$isletme]);
            exit(0);
        }
        
       
        if(count($isletmeler)>1 && !isset($_GET['sube']))
        {
            return view('isletmeadmin.isletmesec',['isletmeler'=>$isletmeler,'isletme'=>$isletme]);
            exit(0);
        }
        // Yetki: cark yonet kapali ise 403
        $_authUser = Auth::guard('isletmeyonetim')->user();
        if ($_authUser && !\App\Services\PersonelYetkiServisi::yetkiliYetkiVar($_authUser->id, self::mevcutsube($request), 'pazarlama.cark_yonet')) {
            return view('isletmeadmin.yetkisizerisim');
            exit(0);
        }
        $paketler = self::paket_liste_getir('',true,$request);
        $kalan_uyelik_suresi = self::lisans_sure_kontrol($request);
        return view('isletmeadmin.carkifelek',['bildirimler'=>self::bildirimgetir($request), 'paketler'=>$paketler,'sayfa_baslik'=>'Çarkıfelek','pageindex' => 500,'isletme'=>$isletme,'kalan_uyelik_suresi'=>$kalan_uyelik_suresi,'urun_drop'=>self::urundropliste($request),
            'yetkiliolunanisletmeler'=>$isletmeler]);
    }

    /**
     * Giriş yapan yetkilinin uygulama yapabileceği (yetkili olduğu) AKTİF şube id'leri.
     * Çoklu şube "şube seçimi"nde owner grubu yerine bu küme kullanılır: kullanıcı
     * yalnızca yetkisi olan şubelere çark/ödül/reklam uygulayabilir. Boşsa çağıran
     * taraf kardeş-şube grubuna düşer (güvenli varsayılan).
     */
    private function yetkiliSubeIdler()
    {
        try {
            $u = Auth::guard('isletmeyonetim')->user();
            if ($u) {
                return $u->yetkili_olunan_isletmeler->where('aktif', 1)
                    ->pluck('salon_id')
                    ->map(function ($v) { return (int) $v; })
                    ->filter(function ($v) { return $v > 0; })
                    ->unique()->values()->toArray();
            }
        } catch (\Exception $e) {}
        return [];
    }

    // Çarkıfelek dilim ekleme/güncelleme fonksiyonu
public function carkdilimekle(Request $request)
{
    if($r = self::yetkiYoksa403($request, 'pazarlama.cark_yonet')) return $r;
    try {
        $salon_id = $request->input('sube', self::mevcutsube($request));
        
        Log::info('Çark dilim ekleme - Salon ID: ' . $salon_id);
        Log::info('Tüm request verisi:', $request->all());
        
        // Salon kontrolü
        $salon = Salonlar::where('id', $salon_id)->first();
        if (!$salon) {
            return response()->json([
                'success' => false,
                'message' => 'Salon bulunamadı!'
            ]);
        }
        
        // Gelen dilimleri al
        $dilimler = $request->input('dilimler', []);
        
        // JSON string olarak gelmişse decode et
        if (is_string($dilimler)) {
            $dilimler = json_decode($dilimler, true);
        }
        
        Log::info('Gelen dilimler (işlenmiş):', $dilimler);
        
        // Dilim sayısı kontrolü
        if (count($dilimler) < 6) {
            return response()->json([
                'success' => false,
                'message' => 'En az 6 dilim olmalıdır!'
            ]);
        }
        
        // Dilimleri temizle ve kontrol et
        $cleanedDilimler = [];
        $totalProbability = 0;
        
        foreach ($dilimler as $index => $dilim) {
            // Olasılık değerini temizle
            $probability = $dilim['probability'] ?? 0;
            
            // String'den number'a çevir
            if (is_string($probability)) {
                $probability = str_replace(',', '.', $probability);
                $probability = (float) filter_var($probability, FILTER_SANITIZE_NUMBER_FLOAT, FILTER_FLAG_ALLOW_FRACTION);
            }
            
            $probability = (int) round($probability);
            
            if ($probability < 0 || $probability > 100) {
                return response()->json([
                    'success' => false,
                    'message' => 'Geçersiz olasılık değeri: ' . ($dilim['probability'] ?? 'undefined') . '. 0-100 arası tam sayı olmalıdır!'
                ]);
            }
            
            $totalProbability += $probability;
            
            // Dilim tipi ve değeri
            $validTips = ['puan', 'hizmet_indirimi', 'urun_indirimi', 'paket_indirimi', 'tekrar_dene', 'bos'];
            $tip   = isset($dilim['tip']) && in_array($dilim['tip'], $validTips)
                     ? $dilim['tip'] : 'bos';
            $deger = in_array($tip, ['puan', 'hizmet_indirimi', 'urun_indirimi', 'paket_indirimi'])
                     ? (isset($dilim['deger']) && $dilim['deger'] !== null ? (float)$dilim['deger'] : null)
                     : null;

            // kupon_mu: indirim tiplerinde otomatik 1
            $kupon_mu = in_array($tip, ['hizmet_indirimi', 'urun_indirimi', 'paket_indirimi']) ? 1 : 0;

            // indirim_tipi: sadece indirim dilimlerinde anlamli. Salon sahibi % (yuzde) veya sabit ₺ (tutar) secer.
            $indirim_tipi = ($kupon_mu && isset($dilim['indirim_tipi']) && $dilim['indirim_tipi'] === 'tutar')
                            ? 'tutar' : 'yuzde';

            $cleanedDilimler[] = [
                'name'         => $dilim['name'] ?? 'Ödül ' . ($index + 1),
                'color'        => $dilim['color'] ?? $this->getRandomColor($index),
                'probability'  => $probability,
                'tip'          => $tip,
                'deger'        => $deger,
                'indirim_tipi' => $indirim_tipi,
                'kupon_mu'     => $kupon_mu,
            ];
        }
        
        Log::info('Temizlenmiş dilimler:', $cleanedDilimler);
        Log::info('Toplam olasılık: ' . $totalProbability);
        
        // Kazanan dilim kontrolü: tam olarak bir dilim 100, gerisi 0 olmalı
        $kazananSayisi = collect($cleanedDilimler)->where('probability', 100)->count();
        if ($kazananSayisi !== 1 || $totalProbability !== 100) {
            return response()->json([
                'success' => false,
                'message' => 'Lütfen tam olarak bir dilimi kazanan olarak seçin.'
            ]);
        }
        
        // kullanim_kurallari kolonu yoksa runtime'da ekle (migration çalışmamış olabilir)
        if (!\Schema::hasColumn('carkifelek_sistemi', 'kullanim_kurallari')) {
            try {
                \Schema::table('carkifelek_sistemi', function ($t) {
                    $t->text('kullanim_kurallari')->nullable();
                });
            } catch (\Exception $e) {
                Log::warning('kullanim_kurallari kolonu eklenemedi: ' . $e->getMessage());
            }
        }
        $hasKurallar = \Schema::hasColumn('carkifelek_sistemi', 'kullanim_kurallari');
        $kurallar    = $request->has('kurallar') ? trim((string) $request->input('kurallar')) : null;

        // Kupon geçerlilik süreleri (işletme insiyatifinde). 0/null → süresiz kupon.
        $hasCarkGun = \Schema::hasColumn('carkifelek_sistemi', 'kupon_cark_gecerlilik_gun');
        $hasPuanGun = \Schema::hasColumn('carkifelek_sistemi', 'kupon_puan_gecerlilik_gun');
        $carkGun = $request->has('kupon_cark_gecerlilik_gun')
            ? (int) $request->input('kupon_cark_gecerlilik_gun') : null;
        $puanGun = $request->has('kupon_puan_gecerlilik_gun')
            ? (int) $request->input('kupon_puan_gecerlilik_gun') : null;
        if ($carkGun !== null && $carkGun < 0) $carkGun = 0;
        if ($puanGun !== null && $puanGun < 0) $puanGun = 0;

        // tip/deger kolonlarının tabloda var mı kontrol et (migration yoksa skip)
        $hasTip         = \Schema::hasColumn('carkifelek_dilimleri', 'tip');
        $hasDeger       = \Schema::hasColumn('carkifelek_dilimleri', 'deger');
        $hasIndirimTipi = \Schema::hasColumn('carkifelek_dilimleri', 'indirim_tipi');
        $hasGecerli     = \Schema::hasColumn('carkifelek_sistemi', 'gecerli_salonlar');

        // Çoklu şube "şube seçimi": salon_ids gönderildiyse çark SADECE seçilen
        // şubelere yazılır (owner'ın kardeş şube grubuyla sınırlı — güvenlik).
        // Gönderilmezse eski davranış: yalnız bu şube. Seçilen grup her satırın
        // gecerli_salonlar'ına yazılır; kazanılan kupon bu grubu miras alır.
        // Yetki: yalnızca giriş yapanın yetkili olduğu şubelere uygulanır (yoksa owner grubu).
        $yetkili = $this->yetkiliSubeIdler() ?: \App\Personeller::kardesSalonIdler($salon_id);
        $secili = \App\Personeller::salonIdListesiCoz($request->input('salon_ids'));
        $hedefSubeler = !empty($secili) ? array_values(array_intersect($secili, $yetkili)) : [(int) $salon_id];
        if (empty($hedefSubeler)) $hedefSubeler = [(int) $salon_id];
        $gecerliJson = json_encode($hedefSubeler);
        $anaHedef = in_array((int) $salon_id, $hedefSubeler, true) ? (int) $salon_id : (int) $hedefSubeler[0];

        $carkifelek = null;
        $savedSlices = [];
        foreach ($hedefSubeler as $hedefSalon) {
            $cs = CarkifelekSistemi::where('salon_id', $hedefSalon)->first();
            if (!$cs) {
                $payload = [
                    'aktifmi'    => $request->input('aktifmi', 1),
                    'salon_id'   => $hedefSalon,
                    'created_at' => now(),
                    'updated_at' => now(),
                ];
                if ($hasKurallar && $request->has('kurallar')) $payload['kullanim_kurallari'] = $kurallar;
                if ($hasCarkGun && $carkGun !== null) $payload['kupon_cark_gecerlilik_gun'] = $carkGun ?: null;
                if ($hasPuanGun && $puanGun !== null) $payload['kupon_puan_gecerlilik_gun'] = $puanGun ?: null;
                if ($hasGecerli) $payload['gecerli_salonlar'] = $gecerliJson;
                $cs = CarkifelekSistemi::create($payload);
            } else {
                $cs->aktifmi = $request->input('aktifmi', $cs->aktifmi);
                if ($hasKurallar && $request->has('kurallar')) $cs->kullanim_kurallari = $kurallar;
                if ($hasCarkGun && $carkGun !== null) $cs->kupon_cark_gecerlilik_gun = $carkGun ?: null;
                if ($hasPuanGun && $puanGun !== null) $cs->kupon_puan_gecerlilik_gun = $puanGun ?: null;
                if ($hasGecerli) $cs->gecerli_salonlar = $gecerliJson;
                $cs->updated_at = now();
                $cs->save();
            }

            CarkifelekDilimleri::where('cark_id', $cs->id)->delete();
            $birincil = ((int) $cs->salon_id === $anaHedef);
            foreach ($cleanedDilimler as $index => $dilim) {
                $row = [
                    'cark_id'        => $cs->id,
                    'dilim_ismi'     => $dilim['name'],
                    'dilim_olasilik' => $dilim['probability'],
                    'renk_kodu'      => $dilim['color'],
                    'kupon_mu'       => $dilim['kupon_mu'],
                    'sira'           => $index + 1,
                    'created_at'     => now(),
                    'updated_at'     => now(),
                ];
                if ($hasTip)         $row['tip']          = $dilim['tip'];
                if ($hasDeger)       $row['deger']        = $dilim['deger'];
                if ($hasIndirimTipi) $row['indirim_tipi'] = $dilim['indirim_tipi'];

                $slice = CarkifelekDilimleri::create($row);
                if ($birincil) {
                    $savedSlices[] = [
                        'id'             => $slice->id,
                        'dilim_ismi'     => $slice->dilim_ismi,
                        'dilim_olasilik' => (int)$slice->dilim_olasilik,
                        'renk_kodu'      => $slice->renk_kodu,
                        'tip'            => $hasTip   ? $slice->tip   : 'bos',
                        'deger'          => $hasDeger ? $slice->deger : null,
                        'indirim_tipi'   => $hasIndirimTipi ? ($slice->indirim_tipi ?? 'yuzde') : 'yuzde',
                        'kupon_mu'       => (int)$slice->kupon_mu,
                        'sira'           => $slice->sira,
                    ];
                }
            }
            if ($birincil) $carkifelek = $cs;
        }
        Log::info('Çark kaydedildi. Şubeler: ' . implode(',', $hedefSubeler));

        // Audit
        SalonAudit::log($salon_id, 'cark_dilim_kaydet', 'cark', $carkifelek->id,
            count($savedSlices).' dilim',
            'Çark dilimleri (ödüller) güncellendi',
            ['aktifmi'=>$carkifelek->aktifmi, 'dilim_sayisi'=>count($savedSlices), 'kazanan'=>collect($savedSlices)->firstWhere('dilim_olasilik',100)]);

        return response()->json([
            'success' => true,
            'message' => 'Dilimler başarıyla kaydedildi!',
            'data' => [
                'carkifelek' => [
                    'id' => $carkifelek->id,
                    'aktifmi' => $carkifelek->aktifmi,
                    'salon_id' => $carkifelek->salon_id
                ],
                'dilimler' => $savedSlices
            ]
        ]);
        
    } catch (\Exception $e) {
        Log::error('Çark dilim ekleme hatası: ' . $e->getMessage());
        Log::error('Hata detayı: ' . $e->getTraceAsString());
        
        return response()->json([
            'success' => false,
            'message' => 'Dilimler kaydedilirken hata oluştu: ' . $e->getMessage()
        ], 500);
    }
}

// Rastgele renk üretme fonksiyonu (controller'a ekleyin)
private function getRandomColor($index)
{
    $colors = [
        '#6c5ce7', '#a29bfe', '#fd79a8', '#fdcb6e', '#00b894', 
        '#e17055', '#74b9ff', '#55efc4', '#ffeaa7', '#fab1a0',
        '#a29bfe', '#81ecec', '#dfe6e9', '#b2bec3', '#636e72',
        '#0984e3', '#00b894', '#fdcb6e', '#e17055', '#d63031'
    ];
    
    return $colors[$index % count($colors)];
}
public function carkverilerigetir(Request $request)
{
    try {
        $salon_id = self::mevcutsube($request);
        
        $carkifelek = CarkifelekSistemi::where('salon_id', $salon_id)->first();
        
        if (!$carkifelek) {
            return response()->json([
                'success' => false,
                'message' => 'Çarkıfelek sistemi bulunamadı!'
            ]);
        }
        
        $hasTip         = \Schema::hasColumn('carkifelek_dilimleri', 'tip');
        $hasDeger       = \Schema::hasColumn('carkifelek_dilimleri', 'deger');
        $hasIndirimTipi = \Schema::hasColumn('carkifelek_dilimleri', 'indirim_tipi');

        $dilimler = CarkifelekDilimleri::where('cark_id', $carkifelek->id)
            ->orderBy('sira', 'asc')
            ->get()
            ->map(function ($dilim) use ($hasTip, $hasDeger, $hasIndirimTipi) {
                return [
                    'name'         => $dilim->dilim_ismi,
                    'probability'  => (int)$dilim->dilim_olasilik,
                    'color'        => $dilim->renk_kodu,
                    'tip'          => $hasTip   ? ($dilim->tip ?? 'bos') : 'bos',
                    'deger'        => $hasDeger && $dilim->deger !== null ? (float)$dilim->deger : null,
                    'indirim_tipi' => $hasIndirimTipi ? ($dilim->indirim_tipi ?? 'yuzde') : 'yuzde',
                    'kupon_mu'     => (int)$dilim->kupon_mu,
                    'sira'         => $dilim->sira
                ];
            })
            ->values();
        
        $hasKurallar = \Schema::hasColumn('carkifelek_sistemi', 'kullanim_kurallari');
        $kurallar    = $hasKurallar ? trim((string) ($carkifelek->kullanim_kurallari ?? '')) : '';
        // Henüz kural girilmemişse koruyucu varsayılanı göster (salon sahibi düzenleyebilir)
        if ($kurallar === '') {
            $kurallar = CarkifelekSistemi::VARSAYILAN_KURALLAR;
        }

        $carkGun = \Schema::hasColumn('carkifelek_sistemi', 'kupon_cark_gecerlilik_gun')
            ? (int) ($carkifelek->kupon_cark_gecerlilik_gun ?? 0) : 0;
        $puanGun = \Schema::hasColumn('carkifelek_sistemi', 'kupon_puan_gecerlilik_gun')
            ? (int) ($carkifelek->kupon_puan_gecerlilik_gun ?? 0) : 0;

        return response()->json([
            'success' => true,
            'data' => [
                'aktifmi'                     => $carkifelek->aktifmi,
                'kurallar'                    => $kurallar,
                'kupon_cark_gecerlilik_gun'   => $carkGun,
                'kupon_puan_gecerlilik_gun'   => $puanGun,
                'dilimler'                    => $dilimler
            ]
        ]);

    } catch (\Exception $e) {
        return response()->json([
            'success' => false,
            'message' => 'Veriler getirilirken hata oluştu: ' . $e->getMessage()
        ]);
    }
}

    /**
     * Çarkıfelek hatırlatma ayar tablolarını runtime'da garanti et.
     */
    private function carkHatirlatmaTabloGaranti()
    {
        if (!\Schema::hasTable('cark_hatirlatma_ayarlari')) {
            \Schema::create('cark_hatirlatma_ayarlari', function ($t) {
                $t->increments('id');
                $t->unsignedInteger('salon_id')->unique();
                $t->tinyInteger('aktif')->default(0);
                $t->time('saat_1')->default('10:00:00');
                $t->time('saat_2')->default('15:00:00');
                $t->time('saat_3')->default('20:00:00');
                $t->time('saat_son')->default('22:30:00');
                $t->string('mesaj_1', 300)->default('🎡 Bugün çark hakkınız var, hediyeler sizi bekliyor!');
                $t->string('mesaj_2', 300)->default('⏰ Çark hakkınız hâlâ duruyor — son birkaç saat!');
                $t->string('mesaj_3', 300)->default('🚨 Son 4 saat! Çarkı çevirmeyi unutmayın');
                $t->string('mesaj_son', 300)->default('🎯 Son 90 dakika! Çevirmek için tek tık');
                $t->json('gonderim_gunleri')->nullable();
                $t->timestamps();
            });
        }
        if (!\Schema::hasTable('cark_hatirlatma_loglari')) {
            \Schema::create('cark_hatirlatma_loglari', function ($t) {
                $t->increments('id');
                $t->unsignedInteger('salon_id');
                $t->unsignedInteger('user_id');
                $t->tinyInteger('asama');
                $t->date('tarih');
                $t->timestamp('gonderim_tarihi')->nullable();
                $t->string('durum', 20)->default('gonderildi');
                $t->timestamps();
                $t->index(['salon_id', 'user_id', 'tarih', 'asama'], 'cark_hat_log_idx');
            });
        }
        // Eski tablolari yeni kolonlarla guncelle (geriye uyumlu)
        foreach (['aktif_1', 'aktif_2', 'aktif_3', 'aktif_son'] as $col) {
            if (!\Schema::hasColumn('cark_hatirlatma_ayarlari', $col)) {
                \Schema::table('cark_hatirlatma_ayarlari', function ($t) use ($col) {
                    $t->tinyInteger($col)->default(1);
                });
            }
        }
        foreach (['baslik_1', 'baslik_2', 'baslik_3'] as $col) {
            if (!\Schema::hasColumn('cark_hatirlatma_ayarlari', $col)) {
                \Schema::table('cark_hatirlatma_ayarlari', function ($t) use ($col) {
                    $t->string($col, 80)->nullable();
                });
            }
        }
        foreach (['altyazi_1', 'altyazi_2', 'altyazi_3'] as $col) {
            if (!\Schema::hasColumn('cark_hatirlatma_ayarlari', $col)) {
                \Schema::table('cark_hatirlatma_ayarlari', function ($t) use ($col) {
                    $t->string($col, 120)->nullable();
                });
            }
        }
    }

    /**
     * Admin: Hatırlatma ayarları sayfası (full page)
     */
    public function carkHatirlatma(Request $request)
    {
        $this->carkHatirlatmaTabloGaranti();
        $salon_id = self::mevcutsube($request);
        $isletme  = Salonlar::where('id', $salon_id)->first();

        $yetkiler = Auth::guard('isletmeyonetim')->check()
            ? Auth::guard('isletmeyonetim')->user()->yetkili_olunan_isletmeler->where('aktif', 1)->pluck('salon_id')->toArray()
            : [];
        if (!in_array($salon_id, $yetkiler) && !Auth::guard('satisortakligi')->check()) {
            return view('isletmeadmin.yetkisizerisim');
        }

        $ayar = CarkHatirlatmaAyarlari::firstOrCreate(['salon_id' => $salon_id]);
        $bugun = CarkHatirlatmaLoglari::where('salon_id', $salon_id)->whereDate('tarih', now()->toDateString())->count();

        $paketler = self::paket_liste_getir('', true, $request);
        $kalan_uyelik_suresi = self::lisans_sure_kontrol($request);

        return view('isletmeadmin.cark_hatirlatma', [
            'bildirimler'          => self::bildirimgetir($request),
            'paketler'             => $paketler,
            'sayfa_baslik'         => 'Çarkıfelek Hatırlatma',
            'pageindex'            => 503,
            'isletme'              => $isletme,
            'kalan_uyelik_suresi'  => $kalan_uyelik_suresi,
            'urun_drop'            => self::urundropliste($request),
            'yetkiliolunanisletmeler' => $yetkiler,
            'ayar'                 => $ayar,
            'bugun'                => $bugun,
        ]);
    }

