    /**
     * Admin: Hatırlatma ayarlarını kaydet (AJAX)
     */
    public function carkHatirlatmaKaydet(Request $request)
    {
        if($r = self::yetkiYoksa403($request, 'pazarlama.cark_yonet')) return $r;
        $this->carkHatirlatmaTabloGaranti();
        $salon_id = self::mevcutsube($request);
        $a = CarkHatirlatmaAyarlari::firstOrNew(['salon_id' => $salon_id]);
        $a->aktif    = (int) $request->input('aktif', 0);
        $a->saat_1   = $request->input('saat_1', '10:00');
        $a->saat_2   = $request->input('saat_2', '15:00');
        $a->saat_3   = $request->input('saat_3', '20:00');
        $a->mesaj_1   = trim($request->input('mesaj_1', ''));
        $a->mesaj_2   = trim($request->input('mesaj_2', ''));
        $a->mesaj_3   = trim($request->input('mesaj_3', ''));
        if (\Schema::hasColumn('cark_hatirlatma_ayarlari', 'aktif_1')) {
            $a->aktif_1   = (int) $request->input('aktif_1', 1);
            $a->aktif_2   = (int) $request->input('aktif_2', 1);
            $a->aktif_3   = (int) $request->input('aktif_3', 1);
            $a->aktif_son = 0; // Eski 4. slot kapali
        }
        if (\Schema::hasColumn('cark_hatirlatma_ayarlari', 'baslik_1')) {
            $a->baslik_1  = trim($request->input('baslik_1', '')) ?: null;
            $a->baslik_2  = trim($request->input('baslik_2', '')) ?: null;
            $a->baslik_3  = trim($request->input('baslik_3', '')) ?: null;
            $a->altyazi_1 = trim($request->input('altyazi_1', '')) ?: null;
            $a->altyazi_2 = trim($request->input('altyazi_2', '')) ?: null;
            $a->altyazi_3 = trim($request->input('altyazi_3', '')) ?: null;
        }
        $gun = $request->input('gonderim_gunleri');
        $a->gonderim_gunleri = is_array($gun) ? $gun : null;
        $a->save();
        // Audit
        SalonAudit::log($salon_id, 'cark_hatirlatma_kaydet', 'cark_hatirlatma', $a->id,
            $a->aktif ? 'Aktif' : 'Pasif',
            'Çark hatırlatma ayarları kaydedildi',
            ['aktif'=>$a->aktif, 'saatler'=>[$a->saat_1,$a->saat_2,$a->saat_3], 'gunler'=>$a->gonderim_gunleri]);
        return response()->json(['success' => true]);
    }

    /**
     * Admin: Çarkıfelek kazananlar ve kuponlar listesi.
     */
    public function carkKazananlar(Request $request)
    {
        $salon_id = self::mevcutsube($request);
        $isletme  = Salonlar::where('id', $salon_id)->first();

        $yetkiler = Auth::guard('isletmeyonetim')->check()
            ? Auth::guard('isletmeyonetim')->user()->yetkili_olunan_isletmeler->where('aktif', 1)->pluck('salon_id')->toArray()
            : [];
        if (!in_array($salon_id, $yetkiler) && !Auth::guard('satisortakligi')->check()) {
            return view('isletmeadmin.yetkisizerisim');
        }

        $filtre = $request->input('filtre', 'tumu');

        $loglar = CarkifelekCevirmeLoglari::where('salon_id', $salon_id)
            ->orderByDesc('created_at')
            ->limit(500)
            ->get();

        $q = CarkifelekOdulleri::where('salon_id', $salon_id);
        if ($filtre === 'gecerli') {
            $q->where('kullanildi', 0)
              ->where(function ($w) {
                  $w->whereNull('gecerlilik_tarihi')->orWhere('gecerlilik_tarihi', '>=', now()->toDateString());
              });
        } elseif ($filtre === 'kullanildi') {
            $q->where('kullanildi', 1);
        } elseif ($filtre === 'sure_doldu') {
            $q->where('kullanildi', 0)
              ->whereNotNull('gecerlilik_tarihi')
              ->where('gecerlilik_tarihi', '<', now()->toDateString());
        }
        $odulluler = $q->orderByDesc('created_at')->limit(500)->get();

        $userIds = $loglar->pluck('user_id')->merge($odulluler->pluck('user_id'))->unique()->filter();
        $users   = User::whereIn('id', $userIds)->get()->keyBy('id');

        $ozet = [
            'toplam_cevirme'   => CarkifelekCevirmeLoglari::where('salon_id', $salon_id)->count(),
            'bugun_cevirme'    => CarkifelekCevirmeLoglari::where('salon_id', $salon_id)->whereDate('created_at', now()->toDateString())->count(),
            'kullanilmamis'    => CarkifelekOdulleri::where('salon_id', $salon_id)->where('kullanildi', 0)->count(),
            'kullanilmis'      => CarkifelekOdulleri::where('salon_id', $salon_id)->where('kullanildi', 1)->count(),
        ];

        $paketler = self::paket_liste_getir('', true, $request);
        $kalan_uyelik_suresi = self::lisans_sure_kontrol($request);

        return view('isletmeadmin.cark_kazananlar', [
            'bildirimler'          => self::bildirimgetir($request),
            'paketler'             => $paketler,
            'sayfa_baslik'         => 'Çarkıfelek Kazananlar',
            'pageindex'            => 501,
            'isletme'              => $isletme,
            'kalan_uyelik_suresi'  => $kalan_uyelik_suresi,
            'urun_drop'            => self::urundropliste($request),
            'yetkiliolunanisletmeler' => $yetkiler,
            'loglar'               => $loglar,
            'odulluler'            => $odulluler,
            'users'                => $users,
            'ozet'                 => $ozet,
            'filtre'               => $filtre,
        ]);
    }

    /**
     * Admin: Puan Ödülleri yönetim sayfası (puan merdiveni)
     */
    public function puanOdulleri(Request $request)
    {
        // Tablo yoksa oluştur (migration çalıştırılmamış ortamlar için)
        if (!\Schema::hasTable('salon_puan_odulleri')) {
            \Schema::create('salon_puan_odulleri', function ($table) {
                $table->increments('id');
                $table->unsignedInteger('salon_id');
                $table->integer('puan_esigi');
                $table->string('baslik', 150);
                $table->string('aciklama', 300)->nullable();
                $table->string('tip', 50);
                $table->decimal('deger', 10, 2)->nullable();
                $table->tinyInteger('aktif')->default(1);
                $table->integer('sira')->default(0);
                $table->timestamps();
                $table->index(['salon_id', 'aktif']);
            });
        }

        $salon_id = self::mevcutsube($request);
        $isletme  = Salonlar::where('id', $salon_id)->first();

        $yetkiler = Auth::guard('isletmeyonetim')->check()
            ? Auth::guard('isletmeyonetim')->user()->yetkili_olunan_isletmeler->where('aktif', 1)->pluck('salon_id')->toArray()
            : [];
        if (!in_array($salon_id, $yetkiler) && !Auth::guard('satisortakligi')->check()) {
            return view('isletmeadmin.yetkisizerisim');
        }

        $odulSeviyeleri = SalonPuanOdulleri::where('salon_id', $salon_id)
            ->orderBy('puan_esigi')
