            'sayfa_baslik'          => 'Puan Ödülleri',
            'pageindex'             => 502,
            'isletme'               => $isletme,
            'kalan_uyelik_suresi'   => $kalan_uyelik_suresi,
            'urun_drop'             => self::urundropliste($request),
            'yetkiliolunanisletmeler' => $yetkiler,
            'odulSeviyeleri'        => $odulSeviyeleri,
        ]);
    }

    /**
     * Admin: Puan ödülü kaydet (yeni veya güncelleme)
     */
    public function puanOdulKaydet(Request $request)
    {
        $salon_id = self::mevcutsube($request);
        $id       = (int) $request->input('id', 0);

        $data = [
            'salon_id'   => $salon_id,
            'puan_esigi' => max(1, (int) $request->input('puan_esigi', 0)),
            'baslik'     => trim($request->input('baslik', '')),
            'aciklama'   => trim($request->input('aciklama', '')) ?: null,
            'tip'        => $request->input('tip', 'hizmet_indirimi'),
            'deger'      => $request->input('deger') !== null && $request->input('deger') !== '' ? (float) $request->input('deger') : null,
            'aktif'      => (int) $request->input('aktif', 1),
            'sira'       => (int) $request->input('sira', 0),
        ];

        if ($data['baslik'] === '' || $data['puan_esigi'] < 1) {
            return response()->json(['success' => false, 'message' => 'Başlık ve puan eşiği zorunlu.']);
        }

        // Çoklu şube "şube seçimi": yalnızca giriş yapanın yetkili olduğu şubelere
        // uygulanır (yoksa owner grubu); grup gecerli_salonlar'a yazılır, kupon miras alır.
        $hasGecerli = \Schema::hasColumn('salon_puan_odulleri', 'gecerli_salonlar');
        $yetkili    = $this->yetkiliSubeIdler() ?: \App\Personeller::kardesSalonIdler($salon_id);
        $secili     = \App\Personeller::salonIdListesiCoz($request->input('salon_ids'));
        $hedefSubeler = !empty($secili) ? array_values(array_intersect($secili, $yetkili)) : [(int) $salon_id];
        if (empty($hedefSubeler)) $hedefSubeler = [(int) $salon_id];

        if ($id > 0) {
            $m = SalonPuanOdulleri::where('id', $id)->whereIn('salon_id', $yetkili)->first();
            if (!$m) return response()->json(['success' => false, 'message' => 'Kayıt bulunamadı.']);
            // gecerli_salonlar YALNIZCA açık seçim varsa güncellenir (mevcut grup korunur).
            if ($hasGecerli && !empty($secili)) $data['gecerli_salonlar'] = json_encode($hedefSubeler);
            $m->update($data);
            // Audit
            SalonAudit::log($salon_id, 'cark_puan_odulu_guncelle', 'cark_puan_odulu', $m->id,
                $data['baslik'].' — '.$data['puan_esigi'].' puan',
                'Puan merdiveni ödülü güncellendi',
                $data);
        } else {
            if ($hasGecerli) $data['gecerli_salonlar'] = json_encode($hedefSubeler);
            $anaId = null;
            foreach ($hedefSubeler as $hedefSalon) {
                $_new = SalonPuanOdulleri::create(array_merge($data, ['salon_id' => (int) $hedefSalon]));
                if ($anaId === null || (int) $hedefSalon === (int) $salon_id) $anaId = $_new->id;
            }
            // Audit
            SalonAudit::log($salon_id, 'cark_puan_odulu_ekle', 'cark_puan_odulu', $anaId,
                $data['baslik'].' — '.$data['puan_esigi'].' puan',
                'Yeni puan merdiveni ödülü eklendi (' . count($hedefSubeler) . ' şube)',
                $data);
        }

        return response()->json(['success' => true]);
    }

    /**
     * Admin: 6 örnek puan ödülü ekler (sadece liste boşsa).
     */
    public function puanOrneklerEkle(Request $request)
    {
        $salon_id = self::mevcutsube($request);

        if (!\Schema::hasTable('salon_puan_odulleri')) {
            \Schema::create('salon_puan_odulleri', function ($table) {
                $table->increments('id');
                $table->unsignedInteger('salon_id');
                $table->integer('puan_esigi');
                $table->string('baslik', 150);
                $table->string('aciklama', 300)->nullable();
                $table->string('tip', 50);
                $table->decimal('deger', 10, 2)->nullable();
                $table->tinyInteger('aktif')->default(1);
                $table->integer('sira')->default(0);
                $table->timestamps();
                $table->index(['salon_id', 'aktif']);
            });
        }

        $varOlan = SalonPuanOdulleri::where('salon_id', $salon_id)->count();
        if ($varOlan > 0) {
            return response()->json(['success' => false, 'message' => 'Bu salonda zaten ödüller var.']);
        }

        $ornekler = [
            ['puan_esigi' => 100,  'baslik' => '%10 Hizmet İndirimi', 'aciklama' => 'Bir sonraki hizmet alımınızda %10 indirim kazanın.', 'tip' => 'hizmet_indirimi', 'deger' => 10,   'sira' => 1, 'aktif' => 1, 'salon_id' => $salon_id],
            ['puan_esigi' => 250,  'baslik' => '%20 Hizmet İndirimi', 'aciklama' => 'Sevdiğiniz hizmeti %20 indirimli alın.',                'tip' => 'hizmet_indirimi', 'deger' => 20,   'sira' => 2, 'aktif' => 1, 'salon_id' => $salon_id],
            ['puan_esigi' => 400,  'baslik' => '%15 Ürün İndirimi',   'aciklama' => 'Tüm bakım ürünlerinde geçerli %15 indirim.',           'tip' => 'urun_indirimi',   'deger' => 15,   'sira' => 3, 'aktif' => 1, 'salon_id' => $salon_id],
            ['puan_esigi' => 600,  'baslik' => '%30 Hizmet İndirimi', 'aciklama' => 'Premium hizmet indirimi — sınırlı zaman.',             'tip' => 'hizmet_indirimi', 'deger' => 30,   'sira' => 4, 'aktif' => 1, 'salon_id' => $salon_id],
            ['puan_esigi' => 1000, 'baslik' => 'Ücretsiz Saç Bakımı', 'aciklama' => 'Tamamen ücretsiz profesyonel saç bakımı paketi.',      'tip' => 'hediye',          'deger' => null, 'sira' => 5, 'aktif' => 1, 'salon_id' => $salon_id],
            ['puan_esigi' => 1500, 'baslik' => 'Ücretsiz Cilt Bakımı','aciklama' => 'Yüz analizi + cilt bakımı (50 dk) hediyemizdir.',      'tip' => 'hediye',          'deger' => null, 'sira' => 6, 'aktif' => 1, 'salon_id' => $salon_id],
        ];

        $sayac = 0;
        foreach ($ornekler as $o) {
            try {
                SalonPuanOdulleri::create($o);
                $sayac++;
            } catch (\Exception $e) {
                return response()->json(['success' => false, 'message' => 'Hata: ' . $e->getMessage()]);
            }
        }

        return response()->json(['success' => true, 'sayac' => $sayac]);
    }

    /**
     * Admin: Puan ödülü sil
     */
    public function puanOdulSil(Request $request)
    {
        $salon_id = self::mevcutsube($request);
        $id       = (int) $request->input('id', 0);
        $m = SalonPuanOdulleri::where('id', $id)->where('salon_id', $salon_id)->first();
        if (!$m) return response()->json(['success' => false, 'message' => 'Kayıt bulunamadı.']);
        // Audit
        SalonAudit::log($salon_id, 'cark_puan_odulu_sil', 'cark_puan_odulu', $m->id,
            ($m->baslik ?? '').' — '.$m->puan_esigi.' puan',
            'Puan merdiveni ödülü silindi');
        $m->delete();
        return response()->json(['success' => true]);
    }

    /**
     * Admin: Kupon kodu ile doğrulama — müşteri salona geldiğinde
     *        kodu giriyor, detayları gösteriyoruz.
     */
    public function carkKuponDogrula(Request $request)
    {
        $salon_id = self::mevcutsube($request);
        $kod = strtoupper(trim($request->input('kod', '')));

        if ($kod === '') {
            return response()->json(['success' => false, 'message' => 'Kod boş olamaz.']);
        }

        $odul = CarkifelekOdulleri::where('kod', $kod)->first();
        if (!$odul) {
            return response()->json(['success' => false, 'message' => 'Bu kod sisteme kayıtlı değil.']);
        }

        // Çoklu şube: kupon yalnızca uygulandığı şube grubunda (gecerli_salonlar)
        // geçerli. Bu POS şubesi o grupta değilse reddet.
        if (!in_array((int) $salon_id, $odul->gecerliSubeler(), true)) {
            return response()->json(['success' => false, 'message' => 'Bu kupon bu şubede geçerli değil.']);
        }

        $user = User::find($odul->user_id);
        $gecmis = $odul->gecerlilik_tarihi && \Carbon\Carbon::parse($odul->gecerlilik_tarihi)->isPast();

        $durum = $odul->kullanildi ? 'kullanildi'
               : ($gecmis ? 'sure_doldu' : 'gecerli');

        return response()->json([
            'success' => true,
            'odul' => [
                'id'                => $odul->id,
                'kod'               => $odul->kod,
                'baslik'            => $odul->baslik,
                'tip'               => $odul->tip,
                'deger'             => $odul->deger,
                'musteri_adi'       => $user->name ?? ('#'.$odul->user_id),
                'musteri_email'     => $user->email ?? null,
                'musteri_tel'       => $user->cep_telefon ?? ($user->telefon ?? null),
                'kazanma_tarihi'    => $odul->created_at ? $odul->created_at->format('d.m.Y H:i') : null,
                'gecerlilik'        => $odul->gecerlilik_tarihi ? \Carbon\Carbon::parse($odul->gecerlilik_tarihi)->format('d.m.Y') : 'Süresiz',
                'kullanildi'        => (int) $odul->kullanildi,
                'kullanim_tarihi'   => $odul->kullanim_tarihi ? \Carbon\Carbon::parse($odul->kullanim_tarihi)->format('d.m.Y H:i') : null,
                'durum'             => $durum,
            ],
        ]);
    }

    /**
     * Admin: Kupon kullanıldı olarak işaretle / geri al.
     */
    public function carkKuponKullan(Request $request)
    {
        $salon_id = self::mevcutsube($request);
        $odul_id  = (int) $request->input('odul_id');
        $aksiyon  = $request->input('aksiyon', 'kullan'); // kullan | geri_al

        // Çoklu şube: kupon yalnızca uygulandığı şube grubunda işaretlenebilir.
        $odul = CarkifelekOdulleri::where('id', $odul_id)->first();
        if (!$odul || !in_array((int) $salon_id, $odul->gecerliSubeler(), true)) {
            return response()->json(['success' => false, 'message' => 'Ödül bulunamadı.']);
        }

        if ($aksiyon === 'geri_al') {
            $odul->kullanildi = 0;
            $odul->kullanim_tarihi = null;
        } else {
            $odul->kullanildi = 1;
            $odul->kullanim_tarihi = now();
        }
        $odul->save();

        // Audit
        $_audit_user = User::where('id',$odul->user_id)->value('name') ?? 'Müşteri #'.$odul->user_id;
        SalonAudit::log($salon_id, $aksiyon === 'geri_al' ? 'cark_kupon_geri_al' : 'cark_kupon_kullan', 'cark_kupon', $odul->id,
            $odul->kod.' — '.$_audit_user,
            $aksiyon === 'geri_al' ? 'Çark kuponu kullanım geri alındı' : 'Çark kuponu kullanıldı olarak işaretlendi',
            ['baslik'=>$odul->baslik, 'tip'=>$odul->tip, 'deger'=>$odul->deger, 'user_id'=>$odul->user_id]);

        return response()->json([
            'success'          => true,
            'kullanildi'       => (int) $odul->kullanildi,
            'kullanim_tarihi'  => $odul->kullanim_tarihi ? $odul->kullanim_tarihi->format('d.m.Y H:i') : null,
        ]);
    }

