    private function dashCacheKey($salonId, $key)
    {
        return 'dash:'.$salonId.':'.$key;
    }

    private function dashSalonId(Request $request)
    {
        $salonId = self::mevcutsube($request);
        $yetkili = Auth::guard('isletmeyonetim')->check()
            ? Auth::guard('isletmeyonetim')->user()->yetkili_olunan_isletmeler->where('aktif',1)->pluck('salon_id')->toArray()
            : [15];
        if(!in_array($salonId, $yetkili)){
            return null;
        }
        return (int) $salonId;
    }

    /**
     * Ozet (dashboard) veri uclari icin yetki kontrolu. dashSalonId() zaten salon
     * uyeligini dogruladi; burada bilesenin gerektirdigi yetki anahtari kontrol edilir.
     * Yetki yoksa 403 JSON doner, varsa null. Birden fazla anahtar verilirse OR mantigi.
     * Kullanim: if($r=self::dashYetkiYoksa403($salonId,'rapor.kasa')) return $r;
     */
    private function dashYetkiYoksa403($salonId, $yetkiAnahtarlari)
    {
        $_au = Auth::guard('isletmeyonetim')->user();
        if (!$_au || !$salonId) return null;
        foreach ((array) $yetkiAnahtarlari as $_key) {
            if (\App\Services\PersonelYetkiServisi::yetkiliYetkiVar($_au->id, $salonId, $_key)) {
                return null; // en az bir yetki var
            }
        }
        return response()->json(['error' => 'forbidden'], 403);
    }

    private function dashPeriodDates($period)
    {
        $bugun = date('Y-m-d');
        switch($period){
            case '7d':
                return [date('Y-m-d', strtotime('-6 days')), $bugun];
            case '30d':
                return [date('Y-m-d', strtotime('-29 days')), $bugun];
            case 'daily':
            default:
                return [$bugun, $bugun];
        }
    }

    public function dashboardKasa(Request $request)
    {
        $salonId = $this->dashSalonId($request);
        if(!$salonId) return response()->json(['error'=>'forbidden'], 403);
        // Yetki: rapor.kasa VEYA personel.kendi_ciro_gor.
        if($r = self::dashYetkiYoksa403($salonId, ['rapor.kasa', 'personel.kendi_ciro_gor'])) return $r;

        // Personel rolunde ve rapor.kasa yoksa personel_id filtresi uygulanir
        // (yalniz kendi adisyon kalemlerinden gelen tahsilatlar).
        $_authUid = Auth::guard('isletmeyonetim')->user()->id;
        $personelFiltre = null;
        if (!\App\Services\PersonelYetkiServisi::yetkiliYetkiVar($_authUid, $salonId, 'rapor.kasa')
            && \App\Services\PersonelYetkiServisi::yetkiliYetkiVar($_authUid, $salonId, 'personel.kendi_ciro_gor')) {
            $personelFiltre = Personeller::where('salon_id', $salonId)
                ->where('yetkili_id', $_authUid)->value('id') ?: -1;
        }

        $period = $request->input('period','daily');
        list($t1, $t2) = $this->dashPeriodDates($period);

        // Cache anahtarina tahsilat "parmak izi" gom: satir eklenince/silinince (app,
        // query-builder YA DA direkt SQL fark etmez) COUNT/MAX degisir -> anahtar degisir
        // -> bayat toplam gosterilmez. Aralik hem sum ([t1,t2]) hem sparkline (son 7 gun) kapsar.
        $fpStart = min($t1, date('Y-m-d', strtotime('-6 days')));
        $fp = DB::table('tahsilatlar')
            ->where('salon_id', $salonId)
            ->whereBetween('odeme_tarihi', [$fpStart.' 00:00:00', $t2.' 23:59:59'])
            ->selectRaw('COUNT(*) as c, COALESCE(MAX(updated_at), 0) as u, COALESCE(MAX(id), 0) as m')
            ->first();
        $sig = $fp->c.'-'.$fp->u.'-'.$fp->m;

        $cacheKey = 'kasa:'.$period.':'.$sig.($personelFiltre ? (':p'.$personelFiltre) : '');
        return \Cache::remember($this->dashCacheKey($salonId, $cacheKey), now()->addSeconds(60), function() use ($salonId, $t1, $t2, $period, $personelFiltre) {
            // Ortak tahsilat_id secici — personel filtresi varsa sadece o
            // personelin adisyon kalemlerinden gelen tahsilat id'leri.
            $tahsilatIdCallback = null;
            if ($personelFiltre) {
                $tahsilatIdCallback = function ($sub) use ($personelFiltre) {
                    $sub->select('tahsilat_hizmetler.tahsilat_id')->from('tahsilat_hizmetler')
                        ->join('adisyon_hizmetler', 'adisyon_hizmetler.id', '=', 'tahsilat_hizmetler.adisyon_hizmet_id')
                        ->where('adisyon_hizmetler.personel_id', $personelFiltre)
                        ->union(
                            DB::table('tahsilat_urunler')
                                ->select('tahsilat_urunler.tahsilat_id')
                                ->join('adisyon_urunler', 'adisyon_urunler.id', '=', 'tahsilat_urunler.adisyon_urun_id')
                                ->where('adisyon_urunler.personel_id', $personelFiltre)
                        )
                        ->union(
                            DB::table('tahsilat_paketler')
                                ->select('tahsilat_paketler.tahsilat_id')
                                ->join('adisyon_paketler', 'adisyon_paketler.id', '=', 'tahsilat_paketler.adisyon_paket_id')
                                ->where('adisyon_paketler.personel_id', $personelFiltre)
                        );
                };
            }

            $rowsQ = DB::table('tahsilatlar')
                ->leftJoin('odeme_yontemleri','tahsilatlar.odeme_yontemi_id','=','odeme_yontemleri.id')
                ->where('tahsilatlar.salon_id', $salonId)
                ->whereBetween('tahsilatlar.odeme_tarihi', [$t1.' 00:00:00', $t2.' 23:59:59']);
            if ($tahsilatIdCallback) {
                $rowsQ->whereIn('tahsilatlar.id', $tahsilatIdCallback);
            }
            $rows = $rowsQ
                ->select('odeme_yontemleri.odeme_yontemi as yontem', DB::raw('SUM(tahsilatlar.tutar) as toplam'))
                ->groupBy('odeme_yontemleri.odeme_yontemi')
                ->get();

            $nakit = 0; $kart = 0; $havale = 0; $diger = 0; $toplam = 0;
            foreach($rows as $r){
                $tutar = (float) $r->toplam;
                $toplam += $tutar;
                $yontem = mb_strtolower($r->yontem ?? '', 'UTF-8');
                if(strpos($yontem,'nakit') !== false || strpos($yontem,'cash') !== false){
                    $nakit += $tutar;
                } elseif(strpos($yontem,'kart') !== false || strpos($yontem,'kredi') !== false || strpos($yontem,'pos') !== false || strpos($yontem,'card') !== false){
                    $kart += $tutar;
                } elseif(strpos($yontem,'havale') !== false || strpos($yontem,'eft') !== false || strpos($yontem,'transfer') !== false || strpos($yontem,'iban') !== false){
                    $havale += $tutar;
                } else {
                    $diger += $tutar;
                }
            }

            $sparkline = [];
            $sparkQ = DB::table('tahsilatlar')
                ->where('salon_id', $salonId)
                ->where('odeme_tarihi','>=', date('Y-m-d 00:00:00', strtotime('-6 days')));
            if ($tahsilatIdCallback) {
                $sparkQ->whereIn('id', $tahsilatIdCallback);
            }
            $sparkRows = $sparkQ
                ->select(DB::raw('DATE(odeme_tarihi) as gun'), DB::raw('SUM(tutar) as toplam'))
                ->groupBy('gun')
                ->get()
                ->keyBy('gun');
            for($i=6; $i>=0; $i--){
                $g = date('Y-m-d', strtotime('-'.$i.' days'));
                $sparkline[] = [
                    'tarih' => $g,
                    'tutar' => isset($sparkRows[$g]) ? (float) $sparkRows[$g]->toplam : 0,
                ];
            }

            return response()->json([
                'period' => $period,
                'nakit' => $nakit,
                'kart' => $kart,
                'havale' => $havale,
                'diger' => $diger,
                'toplam' => $toplam,
                'sparkline' => $sparkline,
            ]);
        });
    }

    public function dashboardRandevuOzet(Request $request)
    {
        $salonId = $this->dashSalonId($request);
        if(!$salonId) return response()->json(['error'=>'forbidden'], 403);
        if($r = self::dashYetkiYoksa403($salonId, 'randevu.takvim_gor')) return $r;
        $period = $request->input('period','daily');
        list($t1, $t2) = $this->dashPeriodDates($period);

        return \Cache::remember($this->dashCacheKey($salonId, 'randevuozet:'.$period), now()->addSeconds(60), function() use ($salonId, $t1, $t2) {
            $olusturulan = DB::table('randevular')
                ->where('salon_id', $salonId)
                ->whereBetween('tarih', [$t1, $t2])
                ->count();
            // Sonuclanan = musteri geldi (durum=1 AND randevuya_geldi=true)
            $sonuclanan = DB::table('randevular')
                ->where('salon_id', $salonId)
                ->whereBetween('tarih', [$t1, $t2])
                ->where('durum', 1)
                ->where('randevuya_geldi', true)
                ->count();
            // Sonuclanmayan = iptal (2,3) veya gelmedi (durum=1 AND randevuya_geldi=false)
            $sonuclanmayan = DB::table('randevular')
                ->where('salon_id', $salonId)
                ->whereBetween('tarih', [$t1, $t2])
                ->where(function($q){
                    $q->whereIn('durum', [2,3])
                      ->orWhere(function($qq){
                          $qq->where('durum', 1)->where('randevuya_geldi', false);
                      });
                })
                ->count();

            $isletme = Salonlar::where('id', $salonId)->first();
            $randevuSuresi = max(15, (int) ($isletme->randevu_araligi ?? 30));
            $personelSay = max(1, DB::table('salon_personelleri')->where('salon_id', $salonId)->where('aktif', 1)->count());

            $gunler = max(1, (strtotime($t2) - strtotime($t1)) / 86400 + 1);
            $calismaSaat = 10;
            $kapasite = $personelSay * $calismaSaat * (60 / $randevuSuresi) * $gunler;
            $doluluk = $kapasite > 0 ? min(100, round(($olusturulan / $kapasite) * 100)) : 0;

            $kaynak = DB::table('randevular')
                ->where('salon_id', $salonId)
                ->whereBetween('tarih', [$t1, $t2])
                ->selectRaw('SUM(CASE WHEN salon=1 THEN 1 ELSE 0 END) as isletme_say, SUM(CASE WHEN web=1 THEN 1 ELSE 0 END) as web_say, SUM(CASE WHEN uygulama=1 THEN 1 ELSE 0 END) as uygulama_say')
                ->first();

            return response()->json([
                'olusturulan' => $olusturulan,
                'sonuclanan' => $sonuclanan,
                'sonuclanmayan' => $sonuclanmayan,
                'doluluk' => $doluluk,
                'kaynak' => [
                    'isletme' => (int) ($kaynak->isletme_say ?? 0),
                    'web' => (int) ($kaynak->web_say ?? 0),
                    'uygulama' => (int) ($kaynak->uygulama_say ?? 0),
                ],
            ]);
        });
    }

    public function dashboardTakvim(Request $request)
    {
        $salonId = $this->dashSalonId($request);
        if(!$salonId) return response()->json(['error'=>'forbidden'], 403);
        if($r = self::dashYetkiYoksa403($salonId, 'randevu.takvim_gor')) return $r;
        $year = (int) $request->input('year', date('Y'));
        $month = (int) $request->input('month', date('n'));
        $month = max(1, min(12, $month));
        $year = max(2020, min(2099, $year));

        return \Cache::remember($this->dashCacheKey($salonId, 'takvim:'.$year.'-'.$month), now()->addSeconds(120), function() use ($salonId, $year, $month) {
            $t1 = sprintf('%04d-%02d-01', $year, $month);
            $t2 = date('Y-m-t', strtotime($t1));
            $rows = DB::table('randevular')
                ->where('salon_id', $salonId)
                ->whereBetween('tarih', [$t1, $t2])
                ->select(DB::raw('DATE(tarih) as gun'), DB::raw('COUNT(*) as adet'))
                ->groupBy('gun')
                ->get();
            $gunler = [];
            foreach($rows as $r){
                $gun = (int) date('j', strtotime($r->gun));
                $gunler[$gun] = (int) $r->adet;
            }
            return response()->json([
                'year' => $year,
                'month' => $month,
                'gunler' => $gunler,
            ]);
        });
    }

    public function dashboardAnket(Request $request)
    {
        $salonId = $this->dashSalonId($request);
        if(!$salonId) return response()->json(['error'=>'forbidden'], 403);
        if($r = self::dashYetkiYoksa403($salonId, 'pazarlama.anket_yonet')) return $r;
        $period = $request->input('period','30d');
        $gunSay = $period === '7d' ? 7 : ($period === '90d' ? 90 : 30);
        $bas = date('Y-m-d 00:00:00', strtotime('-'.($gunSay-1).' days'));
        $bit = date('Y-m-d 23:59:59');

        return \Cache::remember($this->dashCacheKey($salonId, 'anket:'.$period), now()->addSeconds(120), function() use ($salonId, $bas, $bit) {
            $base = DB::table('anket_gonderimleri')
                ->where('salon_id', $salonId)
                ->whereBetween('gonderim_zamani', [$bas, $bit]);

            $toplamGonderim = (clone $base)->count();
            $toplamCevap = (clone $base)->where('cevaplandi', 1)->count();
            $cevapOrani = $toplamGonderim > 0 ? round(($toplamCevap / $toplamGonderim) * 100, 1) : 0;

            $cevaplar = DB::table('anket_gonderimleri')
                ->where('salon_id', $salonId)
                ->whereBetween('gonderim_zamani', [$bas, $bit])
                ->where('cevaplandi', 1);

            $promoter = (clone $cevaplar)->whereNotNull('nps_skoru')->where('nps_skoru', '>=', 9)->count();
            $passive = (clone $cevaplar)->whereNotNull('nps_skoru')->where('nps_skoru', '>=', 7)->where('nps_skoru', '<=', 8)->count();
            $detractor = (clone $cevaplar)->whereNotNull('nps_skoru')->where('nps_skoru', '<=', 6)->count();
            $npsToplam = $promoter + $passive + $detractor;
            $npsSkor = $npsToplam > 0 ? round((($promoter - $detractor) / $npsToplam) * 100) : null;

            $csatOrt = (clone $cevaplar)->whereNotNull('csat_skoru')->avg('csat_skoru');
            $csatOrt = $csatOrt !== null ? round($csatOrt, 2) : null;

            $sonYorumlar = DB::table('anket_gonderimleri')
                ->where('salon_id', $salonId)
                ->whereBetween('gonderim_zamani', [$bas, $bit])
                ->where('cevaplandi', 1)
                ->whereNotNull('genel_yorum')
                ->where('genel_yorum', '!=', '')
                ->orderByDesc('cevap_zamani')
                ->limit(3)
                ->get(['ad_soyad','genel_yorum','nps_skoru','csat_skoru','cevap_zamani']);

            return response()->json([
                'period_gun' => (int) ((strtotime($bit) - strtotime($bas)) / 86400 + 1),
                'toplam_gonderim' => $toplamGonderim,
                'toplam_cevap' => $toplamCevap,
                'cevap_orani' => $cevapOrani,
                'nps' => [
                    'skor' => $npsSkor,
                    'promoter' => $promoter,
                    'passive' => $passive,
                    'detractor' => $detractor,
                    'toplam' => $npsToplam,
                ],
                'csat_ort' => $csatOrt,
                'son_yorumlar' => $sonYorumlar,
            ]);
        });
    }

    public function isletmeRaporlari(Request $request)
    {
        $isletmeler = '';
        $isletme = '';
        if(Auth::guard('satisortakligi')->check())
        {
            $isletmeler = [15];
            $isletme = Salonlar::where('id',15)->first();
        }
        else{
            $isletmeler = Auth::guard('isletmeyonetim')->user()->yetkili_olunan_isletmeler->where('aktif',1)->pluck('salon_id')->toArray();
            $isletme = Salonlar::where('id',self::mevcutsube($request))->first();
        }
        if(!in_array(self::mevcutsube($request),$isletmeler))
        {
            return view('isletmeadmin.yetkisizerisim');
        }
        // Isletme Raporlari: rapor.satis zorunlu (menu ile ayni; Sekreter vb. ozel
        // yetkili hesaplar da dahil — personelmi() sadece rol-5'i engelliyordu).
        $_rapAu = Auth::guard('isletmeyonetim')->user();
        if($_rapAu && !\App\Services\PersonelYetkiServisi::yetkiliYetkiVar($_rapAu->id, self::mevcutsube($request), 'rapor.satis')){
            return view('isletmeadmin.yetkisizerisim');
        }
        if(str_contains(self::lisans_sure_kontrol($request),'-'))
        {
            return view('isletmeadmin.lisanssurebitti',['isletme'=>$isletme]);
        }
        if(!Auth::guard('satisortakligi')->check()){
            if(self::personelmi($request)){
                return redirect()->route('isletmeadmin.randevular');
            }
        }
        if(count($isletmeler)>1 && !isset($_GET['sube'])){
            return view('isletmeadmin.isletmesec',['isletmeler'=>$isletmeler,'isletme'=>$isletme]);
        }
        $view = ($request->input('stil') === 'klasik')
            ? 'isletmeadmin.isletme_raporlari_klasik'
            : 'isletmeadmin.isletme_raporlari';
        return view($view,[
            'sayfa_baslik' => 'İşletme Raporları',
            'title' => 'İşletme Raporları | '.$isletme->salon_adi,
            'pageindex' => 600,
            'isletme' => $isletme,
            'bildirimler' => self::bildirimgetir($request),
            'kalan_uyelik_suresi' => self::lisans_sure_kontrol($request),
            'yetkiliolunanisletmeler' => $isletmeler,
        ]);
    }

    private function raporPeriodDates($request)
    {
        $period = $request->input('period', 'bugun');
        $bugun = date('Y-m-d');
        if($period === 'custom'){
            $bas = $request->input('bas') ? date('Y-m-d', strtotime($request->input('bas'))) : $bugun;
            $bit = $request->input('bit') ? date('Y-m-d', strtotime($request->input('bit'))) : $bugun;
            return [$bas, $bit, 'custom'];
        }
        if($period === 'hafta'){
            $haftaBas = date('Y-m-d', strtotime('monday this week'));
            $haftaBit = date('Y-m-d', strtotime('sunday this week'));
            return [$haftaBas, $haftaBit, 'hafta'];
        }
        if($period === 'ay'){
            return [date('Y-m-01'), date('Y-m-t'), 'ay'];
        }
        return [$bugun, $bugun, 'bugun'];
    }

    public function isletmeRaporlariOzet(Request $request)
    {
        if($r = self::yetkiYoksa403($request, 'rapor.satis')) return $r;
        $salonId = $this->dashSalonId($request);
        if(!$salonId) return response()->json(['error'=>'forbidden'], 403);
        list($t1, $t2, $periodKey) = $this->raporPeriodDates($request);
        $cacheKey = 'rapor:isletme:'.$periodKey.':'.$t1.':'.$t2;

        return \Cache::remember($this->dashCacheKey($salonId, $cacheKey), 60, function() use ($salonId, $t1, $t2) {
            $toplamRandevu = DB::table('randevular')
                ->where('salon_id', $salonId)
                ->whereBetween('tarih', [$t1, $t2])
                ->count();

            $toplamAdisyon = DB::table('adisyonlar')
                ->where('salon_id', $salonId)
                ->whereBetween('created_at', [$t1.' 00:00:00', $t2.' 23:59:59'])
                ->count();

            $satilanUrun = DB::table('adisyon_urunler')
                ->join('adisyonlar','adisyonlar.id','=','adisyon_urunler.adisyon_id')
                ->where('adisyonlar.salon_id', $salonId)
                ->whereBetween('adisyonlar.created_at', [$t1.' 00:00:00', $t2.' 23:59:59'])
                ->count();

            $uygulananHizmet = DB::table('adisyon_hizmetler')
                ->join('adisyonlar','adisyonlar.id','=','adisyon_hizmetler.adisyon_id')
                ->where('adisyonlar.salon_id', $salonId)
                ->whereBetween('adisyonlar.created_at', [$t1.' 00:00:00', $t2.' 23:59:59'])
                ->count();

            $tahsilatRows = DB::table('tahsilatlar')
                ->leftJoin('odeme_yontemleri','tahsilatlar.odeme_yontemi_id','=','odeme_yontemleri.id')
                ->where('tahsilatlar.salon_id', $salonId)
                ->whereBetween('tahsilatlar.odeme_tarihi', [$t1.' 00:00:00', $t2.' 23:59:59'])
                ->select('odeme_yontemleri.odeme_yontemi as yontem', DB::raw('SUM(tahsilatlar.tutar) as toplam'))
                ->groupBy('odeme_yontemleri.odeme_yontemi')
                ->get();

            $nakit = 0; $kart = 0; $havale = 0; $diger = 0; $toplamGelir = 0;
            foreach($tahsilatRows as $r){
                $tutar = (float) $r->toplam;
                $toplamGelir += $tutar;
                $yontem = mb_strtolower($r->yontem ?? '', 'UTF-8');
                if(strpos($yontem,'nakit') !== false || strpos($yontem,'cash') !== false){
                    $nakit += $tutar;
                } elseif(strpos($yontem,'kart') !== false || strpos($yontem,'kredi') !== false || strpos($yontem,'pos') !== false || strpos($yontem,'card') !== false){
                    $kart += $tutar;
                } elseif(strpos($yontem,'havale') !== false || strpos($yontem,'eft') !== false || strpos($yontem,'transfer') !== false || strpos($yontem,'iban') !== false){
                    $havale += $tutar;
                } else {
                    $diger += $tutar;
                }
            }

            // Odenen gelir = toplam tahsilat (zaten tahsilatlar tablosunda kayitli olan = odenen)
            $odenenGelir = $toplamGelir;

            return response()->json([
                'tarih_bas' => $t1,
                'tarih_bit' => $t2,
                'toplam_randevu' => $toplamRandevu,
                'toplam_adisyon' => $toplamAdisyon,
                'satilan_urun' => $satilanUrun,
                'uygulanan_hizmet' => $uygulananHizmet,
                'toplam_gelir' => $toplamGelir,
                'nakit' => $nakit,
                'kart' => $kart,
                'havale' => $havale,
                'diger' => $diger,
                'odenen' => $odenenGelir,
            ]);
        });
    }

    public function isletmeRaporlariHizmet(Request $request)
    {
        if($r = self::yetkiYoksa403($request, 'rapor.satis')) return $r;
        $salonId = $this->dashSalonId($request);
        if(!$salonId) return response()->json(['error'=>'forbidden'], 403);
        list($t1, $t2, $periodKey) = $this->raporPeriodDates($request);
        $cacheKey = 'rapor:hizmet:'.$periodKey.':'.$t1.':'.$t2;

        return \Cache::remember($this->dashCacheKey($salonId, $cacheKey), 60, function() use ($salonId, $t1, $t2) {
            $rows = DB::table('adisyon_hizmetler as ah')
                ->join('adisyonlar as a','a.id','=','ah.adisyon_id')
                ->join('hizmetler as h','h.id','=','ah.hizmet_id')
                ->where('a.salon_id', $salonId)
                ->whereBetween('a.created_at', [$t1.' 00:00:00', $t2.' 23:59:59'])
                ->select('h.id','h.hizmet_adi',
                    DB::raw('COUNT(*) as adet'),
                    DB::raw('SUM(ah.fiyat - COALESCE(ah.indirim_tutari,0)) as ciro'))
                ->groupBy('h.id','h.hizmet_adi')
                ->orderByDesc('ciro')
                ->limit(20)
                ->get();

            $toplamAdet = 0; $toplamCiro = 0;
            foreach($rows as $r){ $toplamAdet += (int)$r->adet; $toplamCiro += (float)$r->ciro; }
            $ortFiyat = $toplamAdet > 0 ? round($toplamCiro / $toplamAdet, 2) : 0;

            return response()->json([
                'toplam_adet' => $toplamAdet,
                'toplam_ciro' => $toplamCiro,
                'ortalama_fiyat' => $ortFiyat,
                'hizmetler' => $rows,
            ]);
        });
    }

