    public function isletmeRaporlariPersonel(Request $request)
    {
        if($r = self::yetkiYoksa403($request, 'rapor.personel_performans')) return $r;
        $salonId = $this->dashSalonId($request);
        if(!$salonId) return response()->json(['error'=>'forbidden'], 403);
        list($t1, $t2, $periodKey) = $this->raporPeriodDates($request);
        $cacheKey = 'rapor:personel:'.$periodKey.':'.$t1.':'.$t2;

        return \Cache::remember($this->dashCacheKey($salonId, $cacheKey), 60, function() use ($salonId, $t1, $t2) {
            $hizmetRows = DB::table('adisyon_hizmetler as ah')
                ->join('adisyonlar as a','a.id','=','ah.adisyon_id')
                ->where('a.salon_id', $salonId)
                ->whereBetween('a.created_at', [$t1.' 00:00:00', $t2.' 23:59:59'])
                ->whereNotNull('ah.personel_id')
                ->select('ah.personel_id',
                    DB::raw('COUNT(*) as hizmet_say'),
                    DB::raw('SUM(ah.fiyat - COALESCE(ah.indirim_tutari,0)) as ciro'))
                ->groupBy('ah.personel_id')
                ->get()
                ->keyBy('personel_id');

            $randevuRows = DB::table('randevu_hizmetler as rh')
                ->join('randevular as r','r.id','=','rh.randevu_id')
                ->where('r.salon_id', $salonId)
                ->whereBetween('r.tarih', [$t1, $t2])
                ->whereNotNull('rh.personel_id')
                ->where(function($q){ $q->where('rh.yardimci_personel','!=',true)->orWhereNull('rh.yardimci_personel'); })
                ->select('rh.personel_id', DB::raw('COUNT(DISTINCT r.id) as randevu_say'))
                ->groupBy('rh.personel_id')
                ->get()
                ->keyBy('personel_id');

            $personeller = DB::table('salon_personelleri')
                ->where('salon_id', $salonId)
                ->where('aktif', 1)
                ->select('id','personel_adi')
                ->get();

            $sonuc = [];
            foreach($personeller as $p){
                $h = $hizmetRows[$p->id] ?? null;
                $r = $randevuRows[$p->id] ?? null;
                $sonuc[] = [
                    'id' => $p->id,
                    'personel_adi' => $p->personel_adi,
                    'randevu_say' => $r ? (int)$r->randevu_say : 0,
                    'hizmet_say' => $h ? (int)$h->hizmet_say : 0,
                    'ciro' => $h ? (float)$h->ciro : 0,
                ];
            }
            usort($sonuc, function($a,$b){ return $b['ciro'] <=> $a['ciro']; });

            return response()->json(['personeller' => $sonuc]);
        });
    }

    public function isletmeRaporlariMusteri(Request $request)
    {
        if($r = self::yetkiYoksa403($request, 'rapor.musteri')) return $r;
        $salonId = $this->dashSalonId($request);
        if(!$salonId) return response()->json(['error'=>'forbidden'], 403);
        list($t1, $t2, $periodKey) = $this->raporPeriodDates($request);
        $cacheKey = 'rapor:musteri:'.$periodKey.':'.$t1.':'.$t2;

        return \Cache::remember($this->dashCacheKey($salonId, $cacheKey), 60, function() use ($salonId, $t1, $t2) {
            $aktifMusteriler = DB::table('randevular')
                ->where('salon_id', $salonId)
                ->whereBetween('tarih', [$t1, $t2])
                ->distinct()
                ->pluck('user_id');
            $toplamAktif = $aktifMusteriler->count();

            $yeniMusteri = 0;
            if(\Schema::hasTable('musteri_portfoy')){
                $yeniMusteri = DB::table('musteri_portfoy')
                    ->where('salon_id', $salonId)
                    ->whereBetween('created_at', [$t1.' 00:00:00', $t2.' 23:59:59'])
                    ->count();
            }
            $tekrarGelen = max(0, $toplamAktif - $yeniMusteri);

            $cinsiyet = ['kadin'=>0,'erkek'=>0,'belirsiz'=>0];
            if($aktifMusteriler->count() > 0){
                $cinsiyetRows = DB::table('users')
                    ->whereIn('id', $aktifMusteriler)
                    ->select('cinsiyet', DB::raw('COUNT(*) as adet'))
                    ->groupBy('cinsiyet')
                    ->get();
                foreach($cinsiyetRows as $c){
                    $cins = mb_strtolower($c->cinsiyet ?? '', 'UTF-8');
                    if(strpos($cins,'kad') !== false || $cins === 'k' || $cins === 'female' || $cins === 'f'){
                        $cinsiyet['kadin'] += (int)$c->adet;
                    } elseif(strpos($cins,'erk') !== false || $cins === 'e' || $cins === 'male' || $cins === 'm'){
                        $cinsiyet['erkek'] += (int)$c->adet;
                    } else {
                        $cinsiyet['belirsiz'] += (int)$c->adet;
                    }
                }
            }

            $topMusteriler = DB::table('tahsilatlar as t')
                ->join('users as u','u.id','=','t.user_id')
                ->where('t.salon_id', $salonId)
                ->whereBetween('t.odeme_tarihi', [$t1.' 00:00:00', $t2.' 23:59:59'])
                ->select('u.id','u.name','u.cep_telefon', DB::raw('SUM(t.tutar) as toplam'), DB::raw('COUNT(t.id) as islem_say'))
                ->groupBy('u.id','u.name','u.cep_telefon')
                ->orderByDesc('toplam')
                ->limit(10)
                ->get();

            return response()->json([
                'toplam_aktif' => $toplamAktif,
                'yeni_musteri' => $yeniMusteri,
                'tekrar_gelen' => $tekrarGelen,
                'cinsiyet' => $cinsiyet,
                'top_musteriler' => $topMusteriler,
            ]);
        });
    }

    public function isletmeRaporlariRandevu(Request $request)
    {
        if($r = self::yetkiYoksa403($request, 'rapor.satis')) return $r;
        $salonId = $this->dashSalonId($request);
        if(!$salonId) return response()->json(['error'=>'forbidden'], 403);
        list($t1, $t2, $periodKey) = $this->raporPeriodDates($request);
        $cacheKey = 'rapor:randevu:'.$periodKey.':'.$t1.':'.$t2;

        return \Cache::remember($this->dashCacheKey($salonId, $cacheKey), 60, function() use ($salonId, $t1, $t2) {
            $toplam = DB::table('randevular')
                ->where('salon_id', $salonId)
                ->whereBetween('tarih', [$t1, $t2])
                ->count();
            $sonuclanan = DB::table('randevular')
                ->where('salon_id', $salonId)->whereBetween('tarih',[$t1,$t2])
                ->where('durum',1)->where('randevuya_geldi',true)->count();
            $gelmedi = DB::table('randevular')
                ->where('salon_id', $salonId)->whereBetween('tarih',[$t1,$t2])
                ->where('durum',1)->where('randevuya_geldi',false)->count();
            $iptal = DB::table('randevular')
                ->where('salon_id', $salonId)->whereBetween('tarih',[$t1,$t2])
                ->whereIn('durum',[2,3])->count();
            $bekleyen = DB::table('randevular')
                ->where('salon_id', $salonId)->whereBetween('tarih',[$t1,$t2])
                ->where('durum',0)->count();

            $kaynak = DB::table('randevular')
                ->where('salon_id', $salonId)->whereBetween('tarih',[$t1,$t2])
                ->selectRaw('SUM(CASE WHEN salon=1 THEN 1 ELSE 0 END) as isletme, SUM(CASE WHEN web=1 THEN 1 ELSE 0 END) as web, SUM(CASE WHEN uygulama=1 THEN 1 ELSE 0 END) as uygulama')
                ->first();

            $saatRows = DB::table('randevular')
                ->where('salon_id', $salonId)->whereBetween('tarih',[$t1,$t2])
                ->select(DB::raw('HOUR(saat) as h'), DB::raw('COUNT(*) as adet'))
                ->groupBy('h')
                ->get()
                ->keyBy('h');
            $saatDagilim = [];
            for($i=0; $i<24; $i++){
                $saatDagilim[] = [
                    'saat' => sprintf('%02d', $i),
                    'adet' => isset($saatRows[$i]) ? (int)$saatRows[$i]->adet : 0,
                ];
            }

            $gunRows = DB::table('randevular')
                ->where('salon_id', $salonId)->whereBetween('tarih',[$t1,$t2])
                ->select(DB::raw('DAYOFWEEK(tarih) as g'), DB::raw('COUNT(*) as adet'))
                ->groupBy('g')
                ->get()
                ->keyBy('g');
            $gunSira = [2,3,4,5,6,7,1];
            $gunAdlari = ['Pts','Sal','Çar','Per','Cum','Cts','Paz'];
            $gunDagilim = [];
            foreach($gunSira as $idx => $g){
                $gunDagilim[] = [
                    'gun' => $gunAdlari[$idx],
                    'adet' => isset($gunRows[$g]) ? (int)$gunRows[$g]->adet : 0,
                ];
            }

            return response()->json([
                'toplam' => $toplam,
                'sonuclanan' => $sonuclanan,
                'gelmedi' => $gelmedi,
                'iptal' => $iptal,
                'bekleyen' => $bekleyen,
                'kaynak' => [
                    'isletme' => (int)($kaynak->isletme ?? 0),
                    'web' => (int)($kaynak->web ?? 0),
                    'uygulama' => (int)($kaynak->uygulama ?? 0),
                ],
                'saat_dagilim' => $saatDagilim,
                'gun_dagilim' => $gunDagilim,
            ]);
        });
    }

    public function dashboardCark(Request $request)
    {
        $salonId = $this->dashSalonId($request);
        if(!$salonId) return response()->json(['error'=>'forbidden'], 403);
        if($r = self::dashYetkiYoksa403($salonId, 'pazarlama.cark_yonet')) return $r;
        $period = $request->input('period','30d');
        $gunSay = $period === '7d' ? 7 : ($period === '90d' ? 90 : 30);
        $bas = date('Y-m-d 00:00:00', strtotime('-'.($gunSay-1).' days'));
        $bit = date('Y-m-d 23:59:59');

        return \Cache::remember($this->dashCacheKey($salonId, 'cark:'.$period), 120, function() use ($salonId, $bas, $bit) {
            $cark = null;
            if(\Schema::hasTable('carkifelek_cevirme_loglari')){
                $base = DB::table('carkifelek_cevirme_loglari')
                    ->where('salon_id', $salonId)
                    ->whereBetween('created_at', [$bas, $bit]);

                $toplamCevrim = (clone $base)->count();
                $kazanan = (clone $base)->where('tip', '!=', 'bos')->count();
                $bos = $toplamCevrim - $kazanan;
                $kazanmaOrani = $toplamCevrim > 0 ? round(($kazanan / $toplamCevrim) * 100, 1) : 0;

                $tipDagilim = DB::table('carkifelek_cevirme_loglari')
                    ->where('salon_id', $salonId)
                    ->whereBetween('created_at', [$bas, $bit])
                    ->where('tip', '!=', 'bos')
                    ->select('tip', DB::raw('COUNT(*) as adet'))
                    ->groupBy('tip')
                    ->get();

                $sonKazananlar = DB::table('carkifelek_cevirme_loglari as l')
                    ->leftJoin('users','users.id','=','l.user_id')
                    ->where('l.salon_id', $salonId)
                    ->whereBetween('l.created_at', [$bas, $bit])
                    ->where('l.tip', '!=', 'bos')
                    ->select('users.name as musteri','l.dilim_ismi','l.tip','l.deger','l.created_at')
                    ->orderByDesc('l.id')
                    ->limit(3)
                    ->get();

                $kupon = ['verilen'=>0,'kullanilan'=>0,'orani'=>0];
                if(\Schema::hasTable('carkifelek_odulleri')){
                    $kupon['verilen'] = DB::table('carkifelek_odulleri')
                        ->where('salon_id', $salonId)
                        ->whereBetween('created_at', [$bas, $bit])
                        ->count();
                    $kupon['kullanilan'] = DB::table('carkifelek_odulleri')
                        ->where('salon_id', $salonId)
                        ->whereBetween('created_at', [$bas, $bit])
                        ->where('kullanildi', 1)
                        ->count();
                    $kupon['orani'] = $kupon['verilen'] > 0 ? round(($kupon['kullanilan']/$kupon['verilen'])*100, 1) : 0;
                }

                $cark = [
                    'toplam_cevrim' => $toplamCevrim,
                    'kazanan' => $kazanan,
                    'bos' => $bos,
                    'kazanma_orani' => $kazanmaOrani,
                    'tip_dagilim' => $tipDagilim,
                    'son_kazananlar' => $sonKazananlar,
                    'kupon' => $kupon,
                ];
            }
            return response()->json($cark ?: [
                'toplam_cevrim' => 0,'kazanan' => 0,'bos' => 0,'kazanma_orani' => 0,
                'tip_dagilim' => [],'son_kazananlar' => [],'kupon' => ['verilen'=>0,'kullanilan'=>0,'orani'=>0],
            ]);
        });
    }

    public function dashboardBugun(Request $request)
    {
        $salonId = $this->dashSalonId($request);
        if(!$salonId) return response()->json(['error'=>'forbidden'], 403);
        if($r = self::dashYetkiYoksa403($salonId, 'randevu.takvim_gor')) return $r;

        return \Cache::remember($this->dashCacheKey($salonId, 'bugun'), 30, function() use ($salonId) {
            $rows = DB::table('randevular')
                ->leftJoin('users','randevular.user_id','=','users.id')
                ->leftJoin('randevu_hizmetler','randevu_hizmetler.randevu_id','=','randevular.id')
                ->leftJoin('hizmetler','randevu_hizmetler.hizmet_id','=','hizmetler.id')
                ->leftJoin('salon_personelleri','randevu_hizmetler.personel_id','=','salon_personelleri.id')
                ->where('randevular.salon_id', $salonId)
                ->where('randevular.tarih', date('Y-m-d'))
                ->select(
                    'randevular.id as randevu_id',
                    'randevular.saat',
                    'randevular.durum',
                    'users.name as musteri',
                    'users.cep_telefon as telefon',
                    'hizmetler.hizmet_adi as hizmet',
                    'salon_personelleri.personel_adi as personel'
                )
                ->orderBy('randevular.saat')
                ->limit(50)
                ->get();
            return response()->json(['liste' => $rows]);
        });
    }

    public function dashboardSekme(Request $request)
    {
        $salonId = $this->dashSalonId($request);
        if(!$salonId) return response()->json(['error'=>'forbidden'], 403);
        $tab = $request->input('tab','online-talep');

        // Her sekme kendi yetkisine bagli (acik adisyon = para, alacak = finans vb.)
        $_sekmeYetki = [
            'online-talep'     => 'randevu.takvim_gor',
            'bugunku-randevu'  => 'randevu.takvim_gor',
            'acik-adisyon'     => 'satis.tum_satis_gor',
            'alacak'           => 'finans.alacak_yonet',
            'dogum-gunu'       => 'musteri.liste_gor',
        ];
        if (isset($_sekmeYetki[$tab]) && ($r = self::dashYetkiYoksa403($salonId, $_sekmeYetki[$tab]))) {
            return $r;
        }

        return \Cache::remember($this->dashCacheKey($salonId, 'sekme:'.$tab), 30, function() use ($salonId, $tab) {
            $data = [];
            switch($tab){
                case 'online-talep':
                    $data = DB::table('randevular')
                        ->leftJoin('users','randevular.user_id','=','users.id')
                        ->leftJoin('randevu_hizmetler','randevu_hizmetler.randevu_id','=','randevular.id')
                        ->leftJoin('hizmetler','randevu_hizmetler.hizmet_id','=','hizmetler.id')
                        ->where('randevular.salon_id', $salonId)
                        ->whereIn('randevular.durum', [0,1])
                        ->where(function($q){
                            $q->where('randevular.web', 1)->orWhere('randevular.uygulama', 1);
                        })
                        ->where('randevular.tarih','>=', date('Y-m-d'))
                        ->select('randevular.id','randevular.tarih','randevular.saat','users.name as musteri','users.cep_telefon as telefon','hizmetler.hizmet_adi as hizmet')
                        ->orderBy('randevular.tarih')
                        ->limit(30)
                        ->get();
                    break;
                case 'acik-adisyon':
                    $sonOtuzGun = date('Y-m-d 00:00:00', strtotime('-30 days'));
                    $data = DB::table('adisyonlar')
                        ->leftJoin('users','adisyonlar.user_id','=','users.id')
                        ->where('adisyonlar.salon_id', $salonId)
                        ->where('adisyonlar.created_at', '>=', $sonOtuzGun)
                        ->select(
                            'adisyonlar.id',
                            'adisyonlar.adisyon_no',
                            'adisyonlar.created_at',
                            'users.name as musteri',
                            'users.cep_telefon as telefon',
                            DB::raw('((SELECT COALESCE(SUM(fiyat-COALESCE(indirim_tutari,0)),0) FROM adisyon_hizmetler WHERE adisyon_id=adisyonlar.id)
                                    + (SELECT COALESCE(SUM(fiyat-COALESCE(indirim_tutari,0)),0) FROM adisyon_urunler WHERE adisyon_id=adisyonlar.id)
                                    + (SELECT COALESCE(SUM(fiyat-COALESCE(indirim_tutari,0)),0) FROM adisyon_paketler WHERE adisyon_id=adisyonlar.id)) as toplam_tutar'),
                            DB::raw('(SELECT COALESCE(SUM(tutar),0) FROM tahsilatlar WHERE adisyon_id=adisyonlar.id) as odenen_tutar')
                        )
                        ->havingRaw('toplam_tutar > odenen_tutar AND toplam_tutar > 0')
                        ->orderByDesc('adisyonlar.created_at')
                        ->limit(30)
                        ->get()
                        ->map(function($r){
                            $r->kalan = (float) $r->toplam_tutar - (float) $r->odenen_tutar;
                            return $r;
                        });
                    break;
                case 'alacak':
                    $data = DB::table('alacaklar')
                        ->leftJoin('users','alacaklar.user_id','=','users.id')
                        ->where('alacaklar.salon_id', $salonId)
                        ->select('alacaklar.id','alacaklar.planlanan_odeme_tarihi','alacaklar.tutar','users.name as musteri','users.cep_telefon as telefon')
                        ->orderBy('alacaklar.planlanan_odeme_tarihi')
                        ->limit(30)
                        ->get();
                    break;
                case 'dogum-gunu':
                    $bugun = date('m-d');
                    $artiOnGun = date('m-d', strtotime('+10 days'));
                    $data = DB::table('users')
                        ->join('musteri_portfoy','musteri_portfoy.user_id','=','users.id')
                        ->where('musteri_portfoy.salon_id', $salonId)
                        ->whereNotNull('users.dogum_tarihi')
                        ->whereRaw("DATE_FORMAT(users.dogum_tarihi, '%m-%d') >= ?", [$bugun])
                        ->whereRaw("DATE_FORMAT(users.dogum_tarihi, '%m-%d') <= ?", [$artiOnGun])
                        ->select('users.name as musteri','users.cep_telefon as telefon','users.dogum_tarihi')
                        ->orderByRaw("DATE_FORMAT(users.dogum_tarihi, '%m-%d')")
                        ->limit(30)
                        ->get();
                    break;
                case 'bugunku-randevu':
                    $data = DB::table('randevular')
                        ->leftJoin('users','randevular.user_id','=','users.id')
                        ->leftJoin('randevu_hizmetler','randevu_hizmetler.randevu_id','=','randevular.id')
                        ->leftJoin('hizmetler','randevu_hizmetler.hizmet_id','=','hizmetler.id')
                        ->leftJoin('salon_personelleri','randevu_hizmetler.personel_id','=','salon_personelleri.id')
                        ->where('randevular.salon_id', $salonId)
                        ->where('randevular.tarih', date('Y-m-d'))
                        ->select('randevular.id','randevular.saat','randevular.durum','users.name as musteri','users.cep_telefon as telefon','hizmetler.hizmet_adi as hizmet','salon_personelleri.personel_adi as personel')
                        ->orderBy('randevular.saat')
                        ->limit(50)
                        ->get();
                    break;
            }
            return response()->json(['tab' => $tab, 'liste' => $data]);
        });
    }

    public function dashboardTimeline(Request $request)
    {
        $salonId = $this->dashSalonId($request);
        if(!$salonId) return response()->json(['error'=>'forbidden'], 403);
        // Timeline tahsilat tutarlarini (₺) icerir → kasa gorme yetkisi gerekir
        if($r = self::dashYetkiYoksa403($salonId, 'rapor.kasa')) return $r;

        return \Cache::remember($this->dashCacheKey($salonId, 'timeline'), 30, function() use ($salonId) {
            $bugun = date('Y-m-d');
            $randevular = DB::table('randevular')
                ->leftJoin('users','randevular.user_id','=','users.id')
                ->where('randevular.salon_id', $salonId)
                ->where('randevular.tarih', $bugun)
                ->select('randevular.id','randevular.saat','randevular.durum','users.name as musteri')
                ->orderBy('randevular.saat')
                ->get()
                ->map(function($r){
                    return [
                        'tip' => 'randevu',
                        'saat' => substr($r->saat, 0, 5),
                        'baslik' => $r->musteri ?: 'Randevu',
                        'durum' => (int) $r->durum,
                        'id' => $r->id,
                    ];
                });

            $tahsilatlar = DB::table('tahsilatlar')
                ->leftJoin('users','tahsilatlar.user_id','=','users.id')
                ->where('tahsilatlar.salon_id', $salonId)
                ->whereBetween('tahsilatlar.odeme_tarihi', [$bugun.' 00:00:00', $bugun.' 23:59:59'])
                ->select('tahsilatlar.id','tahsilatlar.odeme_tarihi','tahsilatlar.tutar','users.name as musteri')
                ->get()
                ->map(function($r){
                    return [
                        'tip' => 'tahsilat',
                        'saat' => date('H:i', strtotime($r->odeme_tarihi)),
                        'baslik' => ($r->musteri ?: 'Müşteri').' — '.number_format($r->tutar,0,',','.').' ₺',
                        'id' => $r->id,
                    ];
                });

            $birlesik = collect($randevular)->merge($tahsilatlar)->sortBy('saat')->values();
            return response()->json(['liste' => $birlesik, 'simdi' => date('H:i')]);
        });
    }

    public function dashboardPersonelDurum(Request $request)
    {
        $salonId = $this->dashSalonId($request);
        if(!$salonId) return response()->json(['error'=>'forbidden'], 403);
        if($r = self::dashYetkiYoksa403($salonId, ['personel.liste_gor','rapor.personel_performans'])) return $r;

        return \Cache::remember($this->dashCacheKey($salonId, 'personel'), 30, function() use ($salonId) {
            $personeller = DB::table('salon_personelleri')
                ->where('salon_id', $salonId)
                ->where('aktif', 1)
                ->select('id','personel_adi')
                ->get();
            $bugun = date('Y-m-d');
            $sonuc = [];
            foreach($personeller as $p){
                $bugunRandevu = DB::table('randevu_hizmetler')
                    ->join('randevular','randevu_hizmetler.randevu_id','=','randevular.id')
                    ->where('randevular.salon_id', $salonId)
                    ->where('randevular.tarih', $bugun)
                    ->where('randevu_hizmetler.personel_id', $p->id)
                    // yardimci_personel NULL tuzagi: asil kalemlerde bu kolon set edilmez,
                    // "!= true" NULL satirlari da eleyip doluluk'u dusuk/0 gosteriyordu.
                    ->whereRaw('COALESCE(randevu_hizmetler.yardimci_personel,0) != 1')
                    ->count();
                $kapasite = 16;
                $doluluk = $kapasite > 0 ? min(100, round(($bugunRandevu / $kapasite) * 100)) : 0;
                $sonuc[] = [
                    'id' => $p->id,
                    'ad' => $p->personel_adi,
                    'randevu' => $bugunRandevu,
                    'doluluk' => $doluluk,
                ];
            }
            usort($sonuc, function($a,$b){ return $b['doluluk'] - $a['doluluk']; });
            return response()->json(['personeller' => array_slice($sonuc, 0, 12)]);
        });
    }

