    public function oda_secimi(Request $request)
    {
        $search = $request->input('query');
        $salonid = $request->input('sube');
        // hizmet_id veya hizmet_ids[] geldiyse: yalnizca o hizmet(ler)i veren odalar
        $hizmetIdleri = [];
        if ($request->filled('hizmet_id')) {
            $hizmetIdleri = is_array($request->hizmet_id) ? $request->hizmet_id : [$request->hizmet_id];
        } elseif ($request->filled('hizmet_ids')) {
            $hizmetIdleri = is_array($request->hizmet_ids) ? $request->hizmet_ids : [$request->hizmet_ids];
        }
        $hizmetIdleri = array_values(array_filter(array_map('intval', $hizmetIdleri)));

        $q = DB::table('odalar')
            ->select('odalar.id as id','odalar.oda_adi as oda_adi')
            ->where('odalar.oda_adi', 'LIKE', "%{$search}%")
            ->where('odalar.salon_id', $salonid)
            ->where('odalar.aktifmi',1);

        if (!empty($hizmetIdleri) && Schema::hasTable('oda_sunulan_hizmetler')) {
            $q->whereIn('odalar.id', function($sub) use($hizmetIdleri){
                $sub->from('oda_sunulan_hizmetler')
                    ->select('oda_id')
                    ->whereIn('hizmet_id', $hizmetIdleri);
            });
        }

        return response()->json($q->orderBy('odalar.takvim_sirasi','asc')->limit(50)->get());
    }
    public function musteridanisanarama(Request $request)
    {
        $isletme = Salonlar::where('id',self::mevcutsube($request))->first();
        $html = '<option  value="0">';
        if($isletme->salon_turu_id==15 || $isletme->salon_turu_id==28||$isletme->salon_turu_id==29)
            $html .= 'Danışan ';
        else
            $html .= 'Müşteri ';
        $html .= 'Arayın...</option>';
        // Personel "musteri.telefon_gor" yetkisi yoksa numarayi maskele
        $u = \Auth::guard('isletmeyonetim')->user();
        $gor = $u && $isletme && $isletme->id
            ? \App\Services\PersonelYetkiServisi::yetkiliYetkiVar($u->id, $isletme->id, 'musteri.telefon_gor')
            : true;
        foreach(MusteriPortfoy::where('salon_id',$isletme->id)->where('aktif',true)->get() as $mevcutmusteri){
            $html .= '<option value="/isletmeyonetim/musteridetay/'.$mevcutmusteri->user_id;
            if(isset($_GET['sube']))
                $html .= '?sube='.$isletme->id;
            $html .= '">'.$mevcutmusteri->users->name;
            if($mevcutmusteri->users->cep_telefon != '' && $mevcutmusteri->users->cep_telefon !== null) {
                $telGoster = $gor ? $mevcutmusteri->users->cep_telefon : \App\PersonelYetkiSabitleri::telefonMaskele($mevcutmusteri->users->cep_telefon);
                $html .= '('.$telGoster.')';
            }
            $html .='</option>';
        }
        return $html;
    }
    public function acikadisyonlar(Request $request){
        $acik_adisyonlar = DB::table('randevu_hizmetler')->join('randevular','randevu_hizmetler.randevu_id','=','randevular.id')->join('hizmetler','randevu_hizmetler.hizmet_id','=','hizmetler.id')->join('users','randevular.user_id','=','users.id')->leftJoin('urun_satislari','urun_satislari.randevu_id','=','randevular.id')->join('salon_personelleri','randevu_hizmetler.personel_id','=','salon_personelleri.id')->leftJoin('urunler','urun_satislari.urun_id','=','urunler.id')->select(
                    'users.name as musteri',
                    DB::raw("CONCAT(GROUP_CONCAT(hizmetler.hizmet_adi),' (', GROUP_CONCAT(salon_personelleri.personel_adi), ')') as hizmetler"),
                    DB::raw('GROUP_CONCAT(urunler.urun_adi) as urunler'),
                    DB::raw('SUM(randevu_hizmetler.fiyat) + COALESCE(SUM(urun_satislari.fiyat), 0) as toplam'),
                    'randevular.tarih as tarih',
                    DB::raw('CONCAT("<a title=\"Detaylı Bilgi\" href=\"/isletmeyonetim/musteridetay/",randevular.id," type=\"button\" class=\"btn btn-info\"><i class=\"dw dw-eye\"></i></a>") as islemler'),
                )->where('randevular.salon_id',self::mevcutsube($request))->where('randevular.acik',true)->whereMonth('randevular.tarih','=',date('m'))->groupBy('randevu_hizmetler.randevu_id')->orderBy('randevular.id','desc')->get();
        return $acik_adisyonlar;
    }
    public function randevular(Request $request){

         $isletmeler = '';
        $isletme='';
        if(Auth::guard('satisortakligi')->check())
        {
            $isletmeler = [15];
            $isletme = Salonlar::where('id',15)->first();
        }
        else{
            $isletmeler = Auth::guard('isletmeyonetim')->user()->yetkili_olunan_isletmeler->where('aktif',1)->pluck('salon_id')->toArray();
            $isletme= Salonlar::where('id',self::mevcutsube($request))->first();
        }


        if(!in_array(self::mevcutsube($request),$isletmeler ))
        {
            return view('isletmeadmin.yetkisizerisim');
            exit(0);
        }

        // Yetki: 'randevu.takvim_gor' kapaliysa sayfa acilmaz.
        $authUser = Auth::guard('isletmeyonetim')->user();
        if ($authUser && !\App\Services\PersonelYetkiServisi::yetkiliYetkiVar(
            $authUser->id, self::mevcutsube($request), 'randevu.takvim_gor'
        )) {
            return view('isletmeadmin.yetkisizerisim');
            exit(0);
        }
        if(str_contains(self::lisans_sure_kontrol($request),'-'))
        {
            return view('isletmeadmin.lisanssurebitti',['isletme'=>$isletme]);
            exit(0);
        }
        
       
        if(count($isletmeler)>1 && !isset($_GET['sube']))
        {
            return view('isletmeadmin.isletmesec',['isletmeler'=>$isletmeler,'isletme'=>$isletme]);
            exit(0);
        }
        $randevular = '';
        if(self::personelmi($request, 'randevu.tum_personel_gor'))
            $randevular = self::randevuyukle($request,1,date('Y-m-d'),date('Y-m-d'));
        else
            $randevular = self::randevuyukle($request,Salonlar::where('id',self::mevcutsube($request))->value('randevu_takvim_turu'),date('Y-m-d'),date('Y-m-d'));
        $kalan_uyelik_suresi =
             self::lisans_sure_kontrol($request);

        // Aktif gap kampanyalari — takvim ustunde bilgi seridi icin
        $gapKampanyalari = $this->_gapKampanyalariListesi(self::mevcutsube($request));

        return view('isletmeadmin.randevular',['bildirimler'=>self::bildirimgetir($request),  'sayfa_baslik'=>'Randevu Takvimi','pageindex' => 2,'randevular'=>$randevular,'isletme'=>$isletme,'kalan_uyelik_suresi'=>$kalan_uyelik_suresi,'yetkiliolunanisletmeler'=>$isletmeler,'gapKampanyalari'=>$gapKampanyalari]);
    }

    /**
     * Yeni tasarim (v2) randevu modali icin test takvim sayfasi.
     * randevular() ile ayni context, sadece view dosyasi farkli.
     */
    public function randevularyenitakvim(Request $request){
        $isletmeler = '';
        $isletme = '';
        if(Auth::guard('satisortakligi')->check()) {
            $isletmeler = [15];
            $isletme = Salonlar::where('id',15)->first();
        } else {
            $isletmeler = Auth::guard('isletmeyonetim')->user()->yetkili_olunan_isletmeler->where('aktif',1)->pluck('salon_id')->toArray();
            $isletme = Salonlar::where('id',self::mevcutsube($request))->first();
        }

        if(!in_array(self::mevcutsube($request),$isletmeler)) {
            return view('isletmeadmin.yetkisizerisim');
        }

        $authUser = Auth::guard('isletmeyonetim')->user();
        if ($authUser && !\App\Services\PersonelYetkiServisi::yetkiliYetkiVar(
            $authUser->id, self::mevcutsube($request), 'randevu.takvim_gor'
        )) {
            return view('isletmeadmin.yetkisizerisim');
        }
        if(str_contains(self::lisans_sure_kontrol($request),'-')) {
            return view('isletmeadmin.lisanssurebitti',['isletme'=>$isletme]);
        }
        if(count($isletmeler)>1 && !isset($_GET['sube'])) {
            return view('isletmeadmin.isletmesec',['isletmeler'=>$isletmeler,'isletme'=>$isletme]);
        }

        $randevular = '';
        if(self::personelmi($request, 'randevu.tum_personel_gor'))
            $randevular = self::randevuyukle($request,1,date('Y-m-d'),date('Y-m-d'));
        else
            $randevular = self::randevuyukle($request,Salonlar::where('id',self::mevcutsube($request))->value('randevu_takvim_turu'),date('Y-m-d'),date('Y-m-d'));

        $kalan_uyelik_suresi = self::lisans_sure_kontrol($request);
        $gapKampanyalari = $this->_gapKampanyalariListesi(self::mevcutsube($request));

        return view('isletmeadmin.randevularyenitakvim',[
            'bildirimler'=>self::bildirimgetir($request),
            'sayfa_baslik'=>'Yeni Takvim (v2)',
            'pageindex' => 2,
            'randevular'=>$randevular,
            'isletme'=>$isletme,
            'kalan_uyelik_suresi'=>$kalan_uyelik_suresi,
            'yetkiliolunanisletmeler'=>$isletmeler,
            'gapKampanyalari'=>$gapKampanyalari
        ]);
    }

    /**
     * Aktif [gap:KEY] etiketli kampanyalari blade icin liste halinde dondurur.
     */
    private function _gapKampanyalariListesi($salonId)
    {
        $now = Carbon::now()->toDateTimeString();
        $kampanyalar = SalonKampanyalar::where('salon_id', $salonId)
            ->where('onayli', 1)
            ->where('kampanya_bitis_tarihi', '>=', $now)
            ->where('kampanya_detay', 'like', '%[gap:%')
            ->get(['id', 'kampanya_baslik', 'kampanya_aciklama', 'kampanya_detay']);

        $defaults = [
            'morning'   => [9, 12, 'Sabah',         '#F59E0B'],
            'afternoon' => [12, 17, 'Öğleden sonra', '#EA580C'],
            'evening'   => [17, 20, 'Akşam',         '#7C3AED'],
        ];

        $out = [];
        $seenKey = [];
        foreach ($kampanyalar as $k) {
            if (!preg_match('/\[gap:([a-z]+)\]/', $k->kampanya_detay ?? '', $m)) continue;
            $gk = $m[1];
            if (!isset($defaults[$gk]) || isset($seenKey[$gk])) continue;

            $startHour = $defaults[$gk][0];
            $endHour   = $defaults[$gk][1];
            if (preg_match('/\((\d{2}):\d{2}-(\d{2}):\d{2}\)/', $k->kampanya_aciklama ?? '', $hm)) {
                $startHour = (int) $hm[1];
                $endHour   = (int) $hm[2];
            }

            $disc = 0;
            if (preg_match('/%%?(\d{1,2})\s*indirim/iu', $k->kampanya_aciklama ?? '', $dm)) {
                $disc = (int) $dm[1];
            } elseif (preg_match('/%%?(\d{1,2})/u', $k->kampanya_baslik ?? '', $dm)) {
                $disc = (int) $dm[1];
            }
            if ($disc <= 0) continue;

            $seenKey[$gk] = true;
            $out[] = [
                'gapKey'    => $gk,
                'gapLabel'  => $defaults[$gk][2],
                'color'     => $defaults[$gk][3],
                'startHour' => $startHour,
                'endHour'   => $endHour,
                'discount'  => $disc,
            ];
        }

        usort($out, function ($a, $b) { return $a['startHour'] <=> $b['startHour']; });
        return $out;
    }
