        $info['sirt'] = $islem->sirt;
        $info['biyik'] = $islem->biyik;
        $info['favori'] = $islem->favori;
        $info['ense'] = $islem->ense;
        $info['ten_rengi'] = $islem->ten_rengi;
        $info['kil_yapisi'] = $islem->kil_yapisi;
        return $info;
