    public function toplusmsgonder(Request $request){
        $isletmeler = '';
        $isletme='';
        if(Auth::guard('satisortakligi')->check())
        {
            $isletmeler = [15];
            $isletme = Salonlar::where('id',15)->first();
        }
        else{
            $isletmeler = Auth::guard('isletmeyonetim')->user()->yetkili_olunan_isletmeler->where('aktif',1)->pluck('salon_id')->toArray();
            $isletme= Salonlar::where('id',self::mevcutsube($request))->first();
        }


        if(!in_array(self::mevcutsube($request),$isletmeler ))
        {
            return view('isletmeadmin.yetkisizerisim');
            exit(0);
        }
        if(str_contains(self::lisans_sure_kontrol($request),'-'))
        {
            return view('isletmeadmin.lisanssurebitti',['isletme'=>$isletme]);
            exit(0);
        }
        // Yetki: bu sayfanin gerektirdigi yetki yoksa 403
        $_authUser = Auth::guard('isletmeyonetim')->user();
        if ($_authUser && !(
            \App\Services\PersonelYetkiServisi::yetkiliYetkiVar($_authUser->id, self::mevcutsube($request), 'pazarlama.sms_gonder')
            || \App\Services\PersonelYetkiServisi::yetkiliYetkiVar($_authUser->id, self::mevcutsube($request), 'pazarlama.toplu_sms')
        )) {
            return view('isletmeadmin.yetkisizerisim');
            exit(0);
        }
        if(!Auth::guard('satisortakligi')->check()){
             if(self::personelmi($request, 'pazarlama.toplu_sms'))
            {
                    return redirect()->route('isletmeadmin.randevular');
                    exit(0);
            }
        }
       
        if(count($isletmeler)>1 && !isset($_GET['sube']))
        {
            return view('isletmeadmin.isletmesec',['isletmeler'=>$isletmeler,'isletme'=>$isletme]);
            exit(0);
        }
         
         
        $sms_ayarlari = SalonSMSAyarlari::where('salon_id',self::mevcutsube($request))->orderBy('ayar_id','asc')->get();
        $taslaklar = SMSTaslaklari::where('salon_id',self::mevcutsube($request))->orWhere('salon_id',null)->get();
        $paketler = self::paket_liste_getir("",true,$request);
        $grup=self::grup_sms_liste_getir($request);
       
        $raporlar = self::sms_raporlari($request);
        $portfoy = MusteriPortfoy::where('salon_id',self::mevcutsube($request))->groupBy('user_id')->get();
        $karaliste = DB::table('users')->join('musteri_portfoy','musteri_portfoy.user_id','=','users.id')->select(
            'users.name as ad_soyad',
            'users.cep_telefon as telefon',
            DB::raw('DATE_FORMAT(musteri_portfoy.updated_at,"%d.%m.%Y") as eklenme_tarihi'),
            DB::raw('CONCAT("<button class=\"btn btn-primary\" name=\"numara_karalisteden_kaldir\" data-value=\"",users.id,"\">Numarayı Listeden Kaldır</button>") AS islemler')
        )->where('musteri_portfoy.salon_id',self::mevcutsube($request))->where('musteri_portfoy.kara_liste',1)->get();
        // Personel "musteri.telefon_gor" yetkisi yoksa telefon maskeli
        $karaliste = $karaliste->map(function ($r) {
            if (isset($r->telefon)) {
                $r->telefon = \App\PersonelYetkiSabitleri::telefonGoster($r->telefon);
            }
            return $r;
        });

        return view('isletmeadmin.toplusmsgonder',['portfoy' => $portfoy,'paketler'=>$paketler,'bildirimler'=>self::bildirimgetir($request),'title' => 'Toplu SMS Gönder','pageindex' => 106,'isletme'=>$isletme,'taslaklar'=>$taslaklar,'grup'=>$grup,'sms_ayarlari'=>$sms_ayarlari,'raporlar'=>$raporlar,'karaliste'=>$karaliste, 'sayfa_baslik'=>'SMS Yönetimi' , 'kalan_uyelik_suresi' => self::lisans_sure_kontrol($request),'urun_drop'=>self::urundropliste($request),'hizmet_drop'=>self::hizmetdropliste($request),'yetkiliolunanisletmeler'=>$isletmeler,'musteridanisansecimi'=>self::musteriportfoydropliste($request)]);
    }
     public function e_asistan(Request $request){
        $isletmeler = '';
        $isletme='';    
        if(Auth::guard('satisortakligi')->check())
        {
            $isletmeler = [15];
            $isletme = Salonlar::where('id',15)->first();
        }
        else{
            $isletmeler = Auth::guard('isletmeyonetim')->user()->yetkili_olunan_isletmeler->where('aktif',1)->pluck('salon_id')->toArray();
            $isletme= Salonlar::where('id',self::mevcutsube($request))->first();
        }
        
        
        if(!in_array(self::mevcutsube($request),$isletmeler ))
        {
            return view('isletmeadmin.yetkisizerisim');
            exit(0);
        }
        if(str_contains(self::lisans_sure_kontrol($request),'-'))
        {
            return view('isletmeadmin.lisanssurebitti',['isletme'=>$isletme]);
            exit(0);
        }
        if(!Auth::guard('satisortakligi')->check()){
             if(self::personelmi($request))
            {
                    return redirect()->route('isletmeadmin.randevular');
                    exit(0);
            }
        }
       
        if(count($isletmeler)>1 && !isset($_GET['sube']))
        {
            return view('isletmeadmin.isletmesec',['isletmeler'=>$isletmeler,'isletme'=>$isletme]);
            exit(0);
        }
        $isletme = Salonlar::where('id',self::mevcutsube($request))->first();
       
        $e_asistan_ayarlari = SalonEAsistanAyarlari::where('salon_id',self::mevcutsube($request))->get();

        // Not: paket_liste_getir() onceden burada cagriliyordu fakat e_asistan view'i
        // ne de layout'taki paketler bolumu (paketler_bolumu CSS sinifi) $paketler
        // degiskenini kullaniyor. Yalnizca pageindex=13'te kullanildigi icin
        // burada yuklemiyoruz; view'in kontrol akisinda hata cikmamasi icin bos
        // bir struct gonderiyoruz.
        $paketler = ['status'=>'','paket_liste'=>[]];
        if($e_asistan_ayarlari->count()==0)
        {
            for($i=1;$i<=8;$i++){
                $asistanAyar = new SalonEAsistanAyarlari();
                $asistanAyar->salon_id=self::mevcutsube($request);
                $asistanAyar->ayar_id=$i;
                $asistanAyar->acik_kapali=1;
                $asistanAyar->save();

            }
            // Yeni eklenen ayarlari geri yukle ki view'deki index erisimleri patlamasin
            $e_asistan_ayarlari = SalonEAsistanAyarlari::where('salon_id',self::mevcutsube($request))->get();
            $isletme->e_asistan_hatirlatma=1;
            $isletme->save();

        }

        // E-Asistan tablosu artik server-side DataTables. Sayfa yuklemede
        // easistandata() cagrilmiyor; frontend tablo asagidaki AJAX endpoint
        // ile veri ceker: /isletmeyonetim/easistandata_ajax/{0|1}
        return view('isletmeadmin.e_asistan',['paketler'=>$paketler,'bildirimler'=>self::bildirimgetir($request),'title' => 'E-Asistan','pageindex' => 60,'isletme'=>$isletme,'e_asistan_ayarlari'=>$e_asistan_ayarlari,'sayfa_baslik'=>'E-Asistan' , 'kalan_uyelik_suresi' => self::lisans_sure_kontrol($request),'urun_drop'=>self::urundropliste($request), 'easistandata'=>collect(), 'easistanYarinYapilacak'=>collect(),
           'yetkiliolunanisletmeler'=>$isletmeler]);
    }
