    public function ayarlar(Request $request){
       $isletmeler = '';
        $isletme='';
        if(Auth::guard('satisortakligi')->check())
        {
            $isletmeler = [15];
            $isletme = Salonlar::where('id',15)->first();
        }
        else{
            $isletmeler = Auth::guard('isletmeyonetim')->user()->yetkili_olunan_isletmeler->where('aktif',1)->pluck('salon_id')->toArray();
            $isletme= Salonlar::where('id',self::mevcutsube($request))->first();
        }
        
        
        if(!in_array(self::mevcutsube($request),$isletmeler ) ||  $_SERVER['HTTP_HOST']=='randevu.randevumcepte.com.tr')
        {
            return view('isletmeadmin.yetkisizerisim');
            exit(0);
        }
        if(str_contains(self::lisans_sure_kontrol($request),'-'))
        {
            return view('isletmeadmin.lisanssurebitti',['isletme'=>$isletme]);
            exit(0);
        }
        // Yetki: Ayarlar kategorisindeki herhangi bir yetki acikken sayfa
        // acilabilir. Hicbiri yoksa yetkisiz erisim. Ayrica secilen tab
        // (?p=...) yetki disindaysa ilk yetkili tab'a redirect.
        if(!Auth::guard('satisortakligi')->check()){
            $authUser = Auth::guard('isletmeyonetim')->user();
            $salonId = self::mevcutsube($request);
            if ($authUser) {
                // Tab -> yetki mapping (sirasi sidebar/blade ile ayni)
                $tabYetki = [
                    'temelbilgiler'        => ['ayar.salon_bilgi'],
                    'subeler'              => ['ayar.sube_yonet'],
                    'calismasaatleri'      => ['ayar.salon_bilgi'],
                    'cihazlar'             => ['ayar.cihaz_oda_yonet'],
                    'hizmetler'            => ['hizmet.tanim_olustur', 'hizmet.kategori_yonet'],
                    'odalar'               => ['ayar.cihaz_oda_yonet'],
                    'randevuayarlari'      => ['randevu.online_ayar'],
                    'musteri_indirimleri'  => ['satis.indirim_uygula'],
                ];
                $has = function($keys) use ($authUser, $salonId) {
                    foreach ((array)$keys as $k) {
                        if (\App\Services\PersonelYetkiServisi::yetkiliYetkiVar($authUser->id, $salonId, $k)) return true;
                    }
                    return false;
                };

                $secilenTab = $request->p ?? 'temelbilgiler';
                $secilenYetkili = isset($tabYetki[$secilenTab]) && $has($tabYetki[$secilenTab]);

                // Hicbir tab yetkisi yoksa → yetkisiz erisim
                $ilkYetkili = null;
                foreach ($tabYetki as $tab => $keys) {
                    if ($has($keys)) { $ilkYetkili = $tab; break; }
                }
                if ($ilkYetkili === null) {
                    return view('isletmeadmin.yetkisizerisim');
                    exit(0);
                }

                // Secilen tab yetkisi yoksa ilk yetkili tab'a yonlendir
                if (!$secilenYetkili) {
                    $subeParam = isset($_GET['sube']) ? '&sube='.((int)$_GET['sube']) : '';
                    return redirect('/isletmeyonetim/ayarlar?p='.$ilkYetkili.$subeParam);
                }
            }
        }

        if(count($isletmeler)>1 && !isset($_GET['sube']))
        {
            return view('isletmeadmin.isletmesec',['isletmeler'=>$isletmeler,'isletme'=>$isletme]);
            exit(0);
        }
        $isletme = Salonlar::where('id',self::mevcutsube($request))->first();
        $subeler =  Salonlar::whereIn('id',$isletmeler)->get();
        $salonhizmetler = SalonHizmetler::where('salon_id',self::mevcutsube($request))->get();
        $personeller = self::personel_liste_getir($request);
        $saloncalismasaatleri = SalonCalismaSaatleri::where('salon_id',self::mevcutsube($request))->orderBy('haftanin_gunu','asc')->get();
        $salonmolasaatleri = SalonMolaSaatleri::where('salon_id',self::mevcutsube($request))->orderBy('haftanin_gunu','asc')->get();
        $salongorselleri = SalonGorselleri::where('salon_id',self::mevcutsube($request))->where('kapak_fotografi','!=',1)->get();
        $gorseller_html = self::salon_gorselleri($request);
        $salongorselkapak = SalonGorselleri::where('salon_id',self::mevcutsube($request))->where('kapak_fotografi',1)->first();
        $etiketler = AramaTerimleri::where('salon_id',self::mevcutsube($request))->orderBy('id','asc')->get();
        $isletmeturu = SalonTuru::all();
        $hizmetler = Hizmetler::all();
        $isletmeturu_html = "";
        $aramaterimleri = AramaTerimleri::where('salon_id',self::mevcutsube($request))->get();
        $hizmetlistesi_html = "";
         foreach ($hizmetler as $key => $value) {
             $hizmetlistesi_html.="<option value='".$value->id."'>".$value->hizmet_adi."</option>";
        }
        foreach ($isletmeturu as $key => $value) {
            if($value->id ==$isletme->salon_turu_id)
                $isletmeturu_html .= "<option selected value='".$value->id."'>".$value->salon_turu_adi."</option>";
            else
                $isletmeturu_html .= "<option value='".$value->id."'>".$value->salon_turu_adi."</option>";
        }
        $urunler = self::urun_liste_getir($request,"");
        $hizmetler = self::hizmet_liste_getir($request,"","");
        $paketler = self::paket_liste_getir("",true,$request);
        $paketler_liste = self::paket_liste_getir("",false,$request);
        $cihazlar=self::cihaz_liste_getir($request,"");
        $odalar=self::oda_liste_getir($request,'');

        // Hizmet Yönetimi sekmesi için gruplu veri (performans için eager + 3 toplu sorgu)
        $isletmeid_hy = self::mevcutsube($request);
        $kategoriler_hy = Hizmet_Kategorisi::all();
        $salon_hizmetler_hy = SalonHizmetler::with('hizmetler:id,hizmet_adi,hizmet_kategori_id,cinsiyet,ozel_hizmet,salon_id')
            ->where('salon_id',$isletmeid_hy)
            ->where('aktif',1)
            ->whereNull('santral_hizmeti')
            ->get();
        $hizmet_ids_hy = $salon_hizmetler_hy->pluck('hizmet_id')->toArray();

        $personel_map = [];
        if(!empty($hizmet_ids_hy)){
            $personel_rows = \DB::table('personel_sunulan_hizmetler')
                ->join('salon_personelleri','personel_sunulan_hizmetler.personel_id','=','salon_personelleri.id')
                ->where('salon_personelleri.salon_id',$isletmeid_hy)
                ->whereIn('personel_sunulan_hizmetler.hizmet_id',$hizmet_ids_hy)
                ->select('personel_sunulan_hizmetler.hizmet_id','salon_personelleri.personel_adi')
                ->get();
            foreach($personel_rows as $pr){
                $personel_map[$pr->hizmet_id] = ($personel_map[$pr->hizmet_id] ?? '').$pr->personel_adi.', ';
            }
            $cihaz_rows = \DB::table('cihaz_sunulan_hizmetler')
                ->join('cihazlar','cihaz_sunulan_hizmetler.cihaz_id','=','cihazlar.id')
                ->where('cihazlar.salon_id',$isletmeid_hy)
                ->whereIn('cihaz_sunulan_hizmetler.hizmet_id',$hizmet_ids_hy)
                ->select('cihaz_sunulan_hizmetler.hizmet_id','cihazlar.cihaz_adi')
                ->get();
            foreach($cihaz_rows as $cr){
                $personel_map[$cr->hizmet_id] = ($personel_map[$cr->hizmet_id] ?? '').$cr->cihaz_adi.', ';
            }
        }

        $hizmet_gruplari = [];
        foreach($salon_hizmetler_hy as $sh){
            $kategori_id = $sh->hizmet_kategori_id ?? ($sh->hizmetler ? $sh->hizmetler->hizmet_kategori_id : null);
            if(!$kategori_id) continue;
            if(!isset($hizmet_gruplari[$kategori_id])) $hizmet_gruplari[$kategori_id] = [];
            // Havuz hizmeti mi, ozel hizmet mi? (ozel_hizmet=true ve salon_id bu isletme ise duzenlenebilir)
            $is_ozel = false;
            if($sh->hizmetler){
                $is_ozel = ($sh->hizmetler->ozel_hizmet == 1 || $sh->hizmetler->ozel_hizmet === true) && $sh->hizmetler->salon_id == $isletmeid_hy;
            }
            $hizmet_gruplari[$kategori_id][] = [
                'id' => $sh->id,
                'hizmet_id' => $sh->hizmet_id,
                'hizmet_adi' => $sh->hizmetler ? $sh->hizmetler->hizmet_adi : 'Bilinmeyen',
                'sure_dk' => $sh->sure_dk,
                'fiyat' => $sh->baslangic_fiyat,
                'personeller' => rtrim($personel_map[$sh->hizmet_id] ?? '', ', '),
                'cinsiyet' => $sh->hizmetler ? $sh->hizmetler->cinsiyet : null,
                'ozel_hizmet' => $is_ozel,
            ];
        }

        $aktif_personel_sayisi = Personeller::where('salon_id',$isletmeid_hy)->where('aktif',1)->count();

        // Sistemden eklenebilir hizmetler: 50-100 sorguyu 2 sorguya indir
        // Sadece sistem havuzu hizmetleri (salon_id=null) + bu salonun kendi ozel hizmetleri
        // Baska isletmelerin ozel hizmetleri LISTELENMEZ
        $aktif_hizmet_idleri = SalonHizmetler::where('salon_id',$isletmeid_hy)->where('aktif',true)->pluck('hizmet_id')->toArray();
        $eklenebilir_hizmetler = Hizmetler::where(function($q) use ($isletmeid_hy, $aktif_hizmet_idleri){
                // Bu isletmenin ozel hizmetleri (aktif olmayanlar)
                $q->where('ozel_hizmet', true)
                  ->where('salon_id', $isletmeid_hy)
                  ->whereNotIn('id', $aktif_hizmet_idleri);
            })->orWhere(function($q) use ($aktif_hizmet_idleri){
                // Sistem havuzu hizmetleri (salon_id null, ozel_hizmet=false/null)
                $q->whereNull('salon_id')
                  ->where(function($q2){
                      $q2->where('ozel_hizmet', false)->orWhereNull('ozel_hizmet');
                  })
                  ->whereNotIn('id', $aktif_hizmet_idleri)
                  ->where('id', '!=', 463);
            })
            ->select('id','hizmet_adi','hizmet_kategori_id')
            ->orderBy('hizmet_kategori_id')
            ->orderBy('hizmet_adi')
            ->get()
            ->groupBy('hizmet_kategori_id');

        // Personel & cihaz ham veri (view icindeki foreach icin)
        $personeller_raw = Personeller::where('salon_id',$isletmeid_hy)->where('aktif',1)->get(['id','personel_adi']);
        $cihazlar_raw = \App\Cihazlar::where('salon_id',$isletmeid_hy)->where('aktifmi',1)->get(['id','cihaz_adi']);
        // Oda modali icin: salona aktif hizmetler (oda-hizmet pivotunda secilebilir)
        $hizmetler_raw = SalonHizmetler::with('hizmetler:id,hizmet_adi')
            ->where('salon_id',$isletmeid_hy)->where('aktif',1)
            ->get()
            ->map(function($sh){
                return [
                    'id' => $sh->hizmet_id,
                    'hizmet_adi' => $sh->hizmetler ? $sh->hizmetler->hizmet_adi : 'Bilinmeyen',
                ];
            })
            ->sortBy('hizmet_adi')
            ->values();

        return view('isletmeadmin.ayarlar',['hizmetler'=>$hizmetler,'hizmet_gruplari'=>$hizmet_gruplari,'kategoriler'=>$kategoriler_hy,'aktif_personel_sayisi'=>$aktif_personel_sayisi,'eklenebilir_hizmetler'=>$eklenebilir_hizmetler,'personeller_raw'=>$personeller_raw,'cihazlar_raw'=>$cihazlar_raw,'hizmetler_raw'=>$hizmetler_raw,'bildirimler'=>self::bildirimgetir($request),'sayfa_baslik' => 'Hesap Ayarları','pageindex' => 9,'salongorselleri'=> $salongorselleri,'saloncalismasaatleri'=>$saloncalismasaatleri,'personeller' => $personeller, 'salonhizmetler' => $salonhizmetler,'isletme'=> $isletme,'sayfa_baslik' => $isletme->salon_adi.' | Detayları & Düzenle', 'etiketler' => $etiketler,'isletmeturulistesi' => $isletmeturu_html,'gorseller_html' => $gorseller_html,'hizmetlistesi'=>$hizmetlistesi_html,'salongorselkapak'=>$salongorselkapak,'subeler'=>$subeler,'salonmolasaatleri'=>$salonmolasaatleri,'urunler'=> $urunler,'paketler'=>$paketler,'paketler_liste'=>$paketler_liste,'roller'=>Role::all(),'cihazlar'=>$cihazlar,'odalar'=>$odalar,'aramaterimleri'=>$aramaterimleri, 'kalan_uyelik_suresi' => self::lisans_sure_kontrol($request),'urun_drop'=>self::urundropliste($request),
            'yetkiliolunanisletmeler'=>$isletmeler]);
    }
    public function randevuyukle(Request $request,$takvim_turu,$tarih1,$tarih2){
    // PERF: Her takvim yuklemesinde (10sn poll) calisan Log::info ve Schema::hasColumn
    // self-heal kaldirildi — gorusme_konusu kolonu uretimde zaten mevcut (migration 2026_04_26).
    $isletmeId = self::mevcutsube($request);

    $personel_idler = Auth::guard('isletmeyonetim')->check() ? Auth::guard('isletmeyonetim')->user()->yetkili_olunan_isletmeler->where('salon_id',$isletmeId)->pluck('id')->toArray() : array();

    // ROL bir kez hesaplanir (eski kod her satir icin tekrar sorguluyordu)
    $rol = Personeller::where('salon_id',$isletmeId)
        ->where('yetkili_id', Auth::guard('isletmeyonetim')->user()->id ?? 0)
        ->value('role_id');

    // WhatsApp bagli mi? Bir kez hesapla, randevu detay modalindaki WhatsApp butonu icin kullan (per-row N+1 yok)
    // Paylasilan oturum: 416 icin 246'nin salonunu kontrol et.
    $_waSalonRaw = Salonlar::find($isletmeId);
    $_waSalon = $_waSalonRaw ? \App\Services\WhatsAppService::resolveWaSalon($_waSalonRaw) : null;
    $_waSaglayici = $_waSalon->whatsapp_saglayici ?? 'baileys';
    $_waBagli = $_waSalon && ($_waSaglayici === 'cloud_api'
        ? (!empty($_waSalon->cloud_api_token) && !empty($_waSalon->cloud_api_phone_number_id))
        : (($_waSalon->whatsapp_aktif ?? 0) && ($_waSalon->whatsapp_durum ?? '') === 'connected'));

    // Randevu detay kartinda "Memnuniyet Anketi Gonder" butonu icin yetki (musteri kartindaki ile ayni: pazarlama.anket_yonet)
    $_anketAu = Auth::guard('isletmeyonetim')->user();
    $_anketYetki = (!$_anketAu || !$isletmeId)
        ? true
        : \App\Services\PersonelYetkiServisi::yetkiliYetkiVar($_anketAu->id, $isletmeId, 'pazarlama.anket_yonet');

    // Renk haritalarini bir kez yukle, id->renk dictionary olarak tut (per-row N+1 yerine)
    $kategoriRenkMap = [];
    $cihazRenkMap    = [];
    $odaRenkMap      = [];
    if($takvim_turu == 0){
        foreach(SalonHizmetKategoriRenkleri::where('salon_id',$isletmeId)->get() as $rk){
            if($rk->renkduzeni) $kategoriRenkMap[$rk->hizmet_kategori_id] = $rk->renkduzeni->renk;
        }
    }
    if($takvim_turu == 2){
        foreach(SalonCihazRenkleri::where('salon_id',$isletmeId)->get() as $rk){
            if($rk->renkduzeni) $cihazRenkMap[$rk->cihaz_id] = $rk->renkduzeni->renk;
        }
    }
    if($takvim_turu == 3){
        foreach(OdaRenkleri::where('salon_id',$isletmeId)->get() as $rk){
            if($rk->renkduzeni) $odaRenkMap[$rk->oda_id] = $rk->renkduzeni->renk;
        }
    }

    // Yetki kontrolu: personel rolu + 'randevu.tum_personel_gor' kapali ise
    // sadece kendi randevulari filtrelenir (mobile akisinin aynisi).
    $kendiPersonelIdFiltre = null;
    if (self::personelmi($request, 'randevu.tum_personel_gor')) {
        $authUserId = Auth::guard('isletmeyonetim')->user()->id ?? 0;
        $kendiPersonelIdFiltre = Personeller::where('yetkili_id', $authUserId)
            ->where('salon_id', $isletmeId)
            ->value('id');
    }

    // Yetkisiz personel (sadece KENDI randevularini gorur) icin: salon oda/cihaz/
    // kategori modunda bile takvimi ODA/CIHAZ kolonlarina dokme — kendi randevularini
    // gordugu icin bu kolonlara gerek yok. Efektif takvim turunu PERSONEL (1) yap:
    // boylece resourceId, resources, renk ve bos-slot mantigi tek personel kolonu
    // uzerinden tutarli calisir (mobil ApiController@randevular ile ayni yaklasim).
    if ($kendiPersonelIdFiltre && $takvim_turu != 1) {
        $takvim_turu = 1;
    }

    // "Saati geçen randevular görünmesin" ayari (sadece randevu.randevumcepte.com.tr girisleri).
    // Tarih alt sinirini bugune cekiyoruz (indeks kullanimi icin) + bugunun saati gecmis
    // randevulari asagida whereHas icinde eliyoruz. Aralik tamamen gecmiste kalirsa
    // $tarih1 > $tarih2 olur ve sorgu dogal olarak bos doner; takvimin geri kalan yapisi
    // (resource/calisma saatleri) bozulmaz.
    $_gecmisGizle = self::gecmisRandevuGizlensinMi($isletmeId);
    $_simdi = date('Y-m-d H:i:s');
    if ($_gecmisGizle && $tarih1 < date('Y-m-d')) {
        $tarih1 = date('Y-m-d');
    }

    $randevu_hizmetler_raw = RandevuHizmetler::with([
        'hizmetler',
        'personeller.trenk',
        'cihaz',
        'oda',
        'randevu.users',
        'randevu.olusturan_personel',
        'randevu.ongorusme.paket',
        'randevu.ongorusme.hizmet',
        'randevu.ongorusme.urun',
        'randevu.ongorusme.personel',
        'randevu.hizmetler', // partial icindeki yardimci personel taramasi N+1'ini engellemek icin
    ])->where('sure_dk','>',0)
    ->whereHas('randevu', function ($q)  use($isletmeId,$tarih1,$tarih2,$_gecmisGizle,$_simdi){
        $q->where('durum', '<', 2);
        $q->where('tarih','>=',$tarih1);
        $q->where('tarih','<=',$tarih2);
        $q->where('salon_id',$isletmeId);
        if ($_gecmisGizle) {
            // Korelasyonlu alt sorgu — randevu_hizmetler kolonlari burada erisilebilir.
            // Kalem saati NULL ise randevunun kendi saatine dus (ApiController ile ayni mantik).
            $q->whereRaw(
                "CONCAT(randevular.tarih,' ',COALESCE(randevu_hizmetler.saat, randevular.saat)) >= ?",
                [$_simdi]
            );
        }
    })
    ->when($kendiPersonelIdFiltre, function ($q) use ($kendiPersonelIdFiltre) {
        $q->where('personel_id', $kendiPersonelIdFiltre);
    })
    ->get();

    // Tum randevu_id'ler icin AdisyonPaketSeanslar'i tek seferde cek, randevu_id'ye gore grupla
    $randevuIds = $randevu_hizmetler_raw->pluck('randevu_id')->unique()->values()->toArray();
    $seanslarByRandevu = !empty($randevuIds)
        ? AdisyonPaketSeanslar::whereIn('randevu_id', $randevuIds)->get()->groupBy('randevu_id')
        : collect();
    // Toplu seans kayitlarindan ihtiyac duyulan adisyon_paket_id ve adisyon_hizmet_id'leri batch yukle
    $adisyonPaketIds  = $seanslarByRandevu->flatten(1)->pluck('adisyon_paket_id')->filter()->unique()->values()->toArray();
    $adisyonHizmetIds = $seanslarByRandevu->flatten(1)->pluck('adisyon_hizmet_id')->filter()->unique()->values()->toArray();
    $adisyonPaketMap  = !empty($adisyonPaketIds)
        ? AdisyonPaketler::with('paket')->whereIn('id', $adisyonPaketIds)->get()->keyBy('id')
        : collect();
    $adisyonHizmetMap = !empty($adisyonHizmetIds)
        ? AdisyonHizmetler::whereIn('id', $adisyonHizmetIds)->get()->keyBy('id')
        : collect();

    // Tahsilat butonu icin: hangi randevu_id'lerin AdisyonPaketSeanslar veya AdisyonHizmetler kayitlari var
    $randevuIdsHasSeans = !empty($randevuIds)
        ? AdisyonPaketSeanslar::whereIn('randevu_id', $randevuIds)->pluck('randevu_id')->unique()->flip()
        : collect();
    $randevuIdsHasAdisyonHizmet = !empty($randevuIds)
        ? AdisyonHizmetler::whereIn('randevu_id', $randevuIds)->pluck('randevu_id')->unique()->flip()
        : collect();

    // KARMA randevu tespiti (mobil ApiController ile ayni mantik):
    //   'tumu'  => "(PAKET)"  — tum hizmetler paketten dusuluyor
    //   'karma' => "(KARMA)"  — en az bir hizmet paketsiz
    //   yoksa etiket yok. Web tarafinda takvim UI'sinin karma randevularda
    //   tahsilat butonunu dogru gostermesi icin.
    $paketHizmetIdsByRandevu = [];
    foreach($seanslarByRandevu as $rid => $seansList) {
        foreach($seansList as $sv) {
            $paketBirlesmesi = false;
            if($sv->adisyon_paket_id) $paketBirlesmesi = true;
            elseif($sv->adisyon_hizmet_id) {
                $ah = $adisyonHizmetMap->get($sv->adisyon_hizmet_id);
                if($ah && (int)$ah->seans_sayisi > 0) $paketBirlesmesi = true;
            }
            if(!$paketBirlesmesi) continue;
            if(!isset($paketHizmetIdsByRandevu[$rid])) $paketHizmetIdsByRandevu[$rid] = [];
            if($sv->hizmet_id) $paketHizmetIdsByRandevu[$rid][(int)$sv->hizmet_id] = true;
        }
    }
    $randevuHizmetTotalById = [];
    foreach($randevu_hizmetler_raw as $rh) {
        if($rh->yardimci_personel) continue;
        if(!isset($randevuHizmetTotalById[$rh->randevu_id])) {
            $randevuHizmetTotalById[$rh->randevu_id] = [];
        }
        if($rh->hizmet_id) $randevuHizmetTotalById[$rh->randevu_id][(int)$rh->hizmet_id] = true;
    }
    $paketDurumuByRandevu = [];
    foreach($paketHizmetIdsByRandevu as $rid => $paketSet) {
        $paketAdet = count($paketSet);
        $toplam = isset($randevuHizmetTotalById[$rid]) ? count($randevuHizmetTotalById[$rid]) : 0;
        if($paketAdet <= 0) continue;
        $paketDurumuByRandevu[$rid] = ($toplam > 0 && $paketAdet >= $toplam) ? 'tumu' : 'karma';
    }

    $randevu_hizmetler = $randevu_hizmetler_raw
    ->map(function ($rh) use($takvim_turu,$isletmeId,$rol,$_waBagli,$_anketYetki,$kategoriRenkMap,$cihazRenkMap,$odaRenkMap,$seanslarByRandevu,$adisyonPaketMap,$adisyonHizmetMap,$randevuIdsHasSeans,$randevuIdsHasAdisyonHizmet,$paketDurumuByRandevu,$paketHizmetIdsByRandevu) {

        $start = Carbon::parse($rh->randevu->tarih . ' ' . $rh->saat)->toIso8601String();

        $end = Carbon::parse($rh->randevu->tarih . ' ' . $rh->saat_bitis)->toIso8601String();
        $title = "";
        $color = "";
        $resourceId = "";
        $duzenleButon= "";
        $gelecek = false;
        $paketAdi = '';
        // Kapali Saat dahil tum kollarda ihtiyac duyulan bilgi (paket kaynagi hesabi):
        $seansVar = $seanslarByRandevu->get($rh->randevu_id, collect());
        if($rh->randevu->user_id == 2012)
        {
            $title = "Kapalı Saat";
            $modalTitle = "Kapalı Saat";
            $color = "#000000";
            $resourceId = $rh->personel_id;
        }
        else
        {
            if(($rh->randevu->randevuya_geldi !== null && $rh->randevu->randevuya_geldi === 1 ) || ($rh->seansa_geldi !== null && $rh->seansa_geldi === 1 )){

                $color =  "#008000";
            }
            elseif(($rh->randevu->randevuya_geldi !== null && $rh->randevu->randevuya_geldi === 0)|| ($rh->seansa_geldi !== null && $rh->seansa_geldi === 0 ))
                $color = "#ff0000";
            elseif($rh->randevu->durum === 0)
                $color = '#ffc107';
            elseif($rh->randevu->randevuya_gelecek !== null && $rh->randevu->randevuya_gelecek === 1 && $rh->randevu->randevuya_geldi === null)
            {
                $gelecek = true;
                $color = "#EF7400";
            }
            elseif($rh->iptal)
            {
                $color = "#000000";
            }
            else{

                if($takvim_turu == 0){
                    if($rh->hizmetler && isset($kategoriRenkMap[$rh->hizmetler->hizmet_kategori_id])){
                        $color = $kategoriRenkMap[$rh->hizmetler->hizmet_kategori_id];
                    }
                }
                if($takvim_turu == 1)
                {
                        if($rh->personel_id != 183){

                            $color = ($rh->personeller && $rh->personeller->trenk) ? $rh->personeller->trenk->renk : '';
                        }
                }
                if($takvim_turu == 2)
                {
                    if(isset($cihazRenkMap[$rh->cihaz_id])){
                        $color = $cihazRenkMap[$rh->cihaz_id];
                    }
                }
                if($takvim_turu == 3){
                    if(isset($odaRenkMap[$rh->oda_id])){
                        $color = $odaRenkMap[$rh->oda_id];
                    }
                }
            }
            $resourceId = "";
            if($takvim_turu==0)
                $resourceId = $rh->hizmetler ? $rh->hizmetler->hizmet_kategori_id : 0;
            if($takvim_turu==1)
                $resourceId = $rh->personel_id ?? 0;
            if($takvim_turu==2){
                $resourceId = $rh->cihaz_id ?? 0;
            }
            if($takvim_turu==3)
                $resourceId = $rh->oda_id ?? 0;

            $title = $rh->randevu->users->name;
            $_musteriAdi = $rh->randevu->users->name;
            $_modalSubtitle = '';
            $seansVar = $seanslarByRandevu->get($rh->randevu_id, collect());
            // "Paket Randevusu" yalnizca gercek paket (adisyon_paket_id dolu) ya da
            // adisyon_hizmetler tablosunda seans sayisi KAYITLI olan (seans_sayisi > 0)
            // hizmet satislari icin gosterilir. Seans sayisi kayitli olmayan
            // (NULL / bos / 0) hizmet satislari da seans kaydi olusturuyor; bunlari
            // paket saymak yanlis "(PAKET)" etiketine yol aciyordu (issue: salon 204 / user 53153).
            // Per-hizmet paket etiketi: sadece BU spesifik hizmet paketten
            // dusuluyorsa "(PAKET)" ekle. Karma randevuda paketsiz hizmet
            // kartlarina etiket eklenmez, tahsilat butonu dogru gorunur.
            $buHizmetPaketli = isset($paketHizmetIdsByRandevu[$rh->randevu_id][(int)$rh->hizmet_id]);
            if($buHizmetPaketli){
                $title .= " (PAKET)";
                $_modalSubtitle = 'Paket Randevusu';
                $duzenleButon .= '<a data-toggle="modal" data-target="#randevu-duzenle-modal" name="randevu_duzenle" href="#" class="btn btn-primary" data-value="'.$rh->randevu_id.'" data-index-number="'.$rh->hizmet_id.'"><i class="fa fa-edit"></i> Düzenle</a><a href="/isletmeyonetim/musteridetay/'.$rh->randevu->user_id.'?sube='.$rh->randevu->salon_id.'" class="btn btn-info btn-sm musteri-detay-btn">Müşteri Detay</a>';
            }

            elseif($rh->randevu->on_gorusme_id  !== null){
                $duzenleButon .= '<a onclick="modalbaslikata(\"Ön Görüşme Düzenleme\",\"\" )" class="btn btn-primary" href="#" data-toggle="modal" data-target="#ongorusme-modal" name="ongorusme_duzenle" data-value="'.$rh->randevu->on_gorusme_id.'"><i class="fa fa-edit"></i> Düzenle</a><a href="/isletmeyonetim/musteridetay/'.$rh->randevu->user_id.'?sube='.$rh->randevu->salon_id.'" class="btn btn-info btn-sm musteri-detay-btn">Müşteri Detay</a>';
                $title .= " (ÖN GÖRÜŞME)\nÖn Görüşme Nedeni: ";
                $_modalSubtitle = 'Ön Görüşme Randevusu';
                $_og = $rh->randevu->ongorusme;
                if($_og && $_og->paket)
                    $title .= $_og->paket->paket_adi;
                elseif($_og && $_og->hizmet)
                    $title .= $_og->hizmet->hizmet_adi;
                elseif($_og && $_og->urun)
                    $title .= $_og->urun->urun_adi;
                else
                    $title .= "—";
            }
            else{
                 $duzenleButon .= '<a data-toggle="modal" data-target="#randevu-duzenle-modal" name="randevu_duzenle" href="#" class="btn btn-primary" data-value="'.$rh->randevu_id.'" data-index-number="'.$rh->hizmet_id.'"><i class="fa fa-edit"></i> Düzenle</a><a href="/isletmeyonetim/musteridetay/'.$rh->randevu->user_id.'?sube='.$rh->randevu->salon_id.'" class="btn btn-info btn-sm musteri-detay-btn">Müşteri Detay</a>';

                $_modalSubtitle = 'Randevu';
            }

            // WhatsApp mesaj butonu — header'da Duzenle / Musteri Detay yaninda (sadece telefon varsa)
            $_waTelH = $rh->randevu->users->cep_telefon ?? '';
            if(!empty($_waTelH)){
                $duzenleButon .= '<a href="#" class="btn btn-success btn-sm whatsapp-mesaj-ac"'
                    .' data-userid="'.($rh->randevu->user_id ?? '').'"'
                    .' data-telefon="'.htmlspecialchars($_waTelH, ENT_QUOTES).'"'
                    .' data-ad="'.htmlspecialchars($rh->randevu->users->name ?? '', ENT_QUOTES).'"'
                    .' data-onay="'.(int)($rh->randevu->users->whatsapp_onay ?? 0).'"'
                    .' data-bagli="'.($_waBagli ? 1 : 0).'"><i class="fa fa-whatsapp"></i> WhatsApp</a>';
            }

            // Memnuniyet Anketi Gonder butonu — musteri kartindakinin ayni (on gorusme haric)
            if($_anketYetki && $rh->randevu->on_gorusme_id === null && !empty($rh->randevu->user_id)){
                $duzenleButon .= '<a href="#" class="btn btn-sm anket-hizli-gonder-btn" style="background:#17a589;color:#fff;"'
                    .' data-userid="'.($rh->randevu->user_id ?? '').'"'
                    .' data-sube="'.($rh->randevu->salon_id ?? '').'"><i class="fa fa-comments"></i> Anket Gönder</a>';
            }

            if($seansVar->count() > 0){
                $apIds = $seansVar->pluck('adisyon_paket_id')->filter()->values();
                $ahIds = $seansVar->pluck('adisyon_hizmet_id')->filter()->values();
                $paketVar  = $apIds->isNotEmpty() ? $adisyonPaketMap->get($apIds->first()) : null;
                $hizmetVar = $ahIds->isNotEmpty() ? $adisyonHizmetMap->get($ahIds->first()) : null;
                if($paketVar && $paketVar->paket){
                    $title .= "\n".$paketVar->paket->paket_adi;
                    $paketAdi = $paketVar->paket->paket_adi;
                }
                if($hizmetVar && $rh->hizmetler)
                    $title .= "\n".$rh->hizmetler->hizmet_adi;
            }
            elseif($rh->hizmetler)
                $title .= "\n".$rh->hizmetler->hizmet_adi;
            

            $modalTitle = '<span class="rd-mt-name">'.htmlspecialchars($_musteriAdi).'</span><span class="rd-mt-sub">'.$_modalSubtitle.' Detayları</span>';

            $title .= "\nOluşturan:";
            if($rh->randevu->web == true)
                $title .= "Web";
            if($rh->randevu->salon == true) 
                $title .= $rh->randevu->olusturan_personel_id !== null ? $rh->randevu->olusturan_personel->name : "";
            if($rh->randevu->uygulama == true)
                $title .= "Uygulama";
            if($rh->randevu->easistan == true)
                $title .= "Asistan";

             if($gelecek)
                $title .= "\nRANDEVUYA GELECEK";


        }
        // $rol disaridan dondurulen closure scope degiskeni; her satir icin tekrar sorguya gerek yok
        $hasPaketTahsilat = isset($randevuIdsHasSeans[$rh->randevu_id]) || isset($randevuIdsHasAdisyonHizmet[$rh->randevu_id]);

        // MERGE icin "paket kaynagi": bu RandevuHizmetler (hizmet_id ozelinde)
        // hangi adisyon_paket / adisyon_hizmet'e bagli? Ayni kaynak + ayni resource
        // olan hizmetler tek bara birlestirilir. Bagli olmayanlar 'single-'+id (asla merge).
        $_paketSource = 'single-'.$rh->id;
        foreach($seansVar as $__sv){
            if((int)$__sv->hizmet_id !== (int)$rh->hizmet_id) continue;
            if($__sv->adisyon_paket_id){ $_paketSource = 'AP:'.$__sv->adisyon_paket_id; break; }
            if($__sv->adisyon_hizmet_id){ $_paketSource = 'AH:'.$__sv->adisyon_hizmet_id; break; }
        }

        return [
            'id' => $rh->id,
            'title' => $title,
            'start' => $start,
            'end' => $end,
            // PERF: Bu 3 agir Blade partial artik toplu yuklemede render EDILMIYOR.
            // randevu basina 3 render x her poll cok pahaliydi (yogun salonda binlerce render).
            // Bos birakiliyor; kullanici randevuya tiklayinca/hover'da
            // /isletmeyonetim/randevu-event-detay endpoint'inden tek randevu icin cekiliyor.
            'eventbuttons'=> '',
            'description' => '',
            'hoverHtml' => '',
            'color' => $color,
            'randevuId'=>$rh->randevu_id,
            'resourceId' =>  $resourceId,
            'personelId' => $rh->personel_id,
            'odaId'=> $rh->odaId,
            'odaAdi'=>$rh->oda ? $rh->oda->oda_adi : '',
            'resourceTitle'=> "",
            "textColor"=> "",
            'modal_title' => $modalTitle,
            'duzenle_buton'=>$duzenleButon,
            '_paketSource' => $_paketSource, // merge icin
        ];
    });

    // ============================================================
    // MERGE: Ayni paket kaynagi (adisyon_paket_id / adisyon_hizmet_id) +
    // ayni resource (personel/oda/cihaz kolonu) icindeki hizmetler tek bara
    // birlestirilir. Paket randevusu tek blok gorunsun diye.
    //
    // - APS'siz hizmetler (paket randevusu degil) HER ZAMAN ayri bar
    //   ('single-'+rh_id key ile unique kalir)
    // - Farkli paket kaynaklari (farkli AP/AH id) ayri bar
    // - Ayni paket + farkli resource kolonu (or. paket icinde farkli personel)
    //   ayri bar
    // - Ayni paket + ayni resource: birlestirilir. start = min, end = max.
    //
    // Onceki tarihce:
    // - a66f9bc3 (05-Haz): randevu_id bazli merge (paket 1 blok, ama farkli
    //   personel ikinci event kayboluyor)
    // - 8bf8dc7c (24-Haz): randevu_id + resource bazli (paket 1 blok +
    //   farkli personel ayri; AMA APS'siz sirali 2 hizmet de birlesiyor)
    // - b8c29898 (21-Tem): merge tamamen kaldirildi (mobil ile ayni akis,
    //   paket bile satirlara bolundu)
    // - Simdi: paket kaynagi + resource bazli (paket 1 blok, digerleri
    //   ayri) — kullanicinin istedigi.
    // ============================================================
    if($randevu_hizmetler instanceof \Illuminate\Support\Collection && $randevu_hizmetler->count() > 0){
        $grouped = $randevu_hizmetler->groupBy(function($e){
            $src = $e['_paketSource'] ?? ('single-'.($e['id'] ?? uniqid()));
            $res = $e['resourceId'] ?? '';
            return $src.'|'.$res;
        });
        $merged = collect();
        foreach($grouped as $key => $events){
            if($events->count() > 1){
                $sorted = $events->sortBy('start')->values();
                $first  = $sorted->first();
                $first['end'] = $sorted->max('end');
                unset($first['_paketSource']);
                $merged->push($first);
            } else {
                foreach($events as $e){
                    unset($e['_paketSource']);
                    $merged->push($e);
                }
            }
        }
        $randevu_hizmetler = $merged;
    }

    $emptySlots = [];
    $startDate = Carbon::parse($tarih1 . " 07:00:00");
    $endDate = Carbon::parse($tarih2 . " 23:00:00");

    $odalar = Odalar::where('salon_id', $isletmeId)->get()->keyBy('id');
    $personeller = Personeller::where('salon_id', $isletmeId)->get()->keyBy('id');
    
    // Oda personellerini önceden yükle (performans için) - Sadece ilk personeli al
    $odaPersonelleri = OdaPersonelleri::where('salon_id', $isletmeId)
        ->with('personel')
        ->orderBy('id', 'asc') // İlk kayıt ilk personel olacak
        ->get()
        ->groupBy('oda_id')
        ->map(function ($personeller) {
            // Her oda için sadece ilk personeli al
            $firstPersonel = $personeller->first();
            return $firstPersonel ?: null;
        });

    // randevu_hizmetler'i resourceId bazli grupla — empty slot kontrolunde O(n) yerine O(per_resource) tarama
    $randevu_hizmetler2_by_resource = [];
    foreach ($randevu_hizmetler as $item) {
        $rid = $item['resourceId'] ?? $item->resourceId;
        if($rid === '' || $rid === null) continue;
        $randevu_hizmetler2_by_resource[$rid][] = (object)[
            'start' => Carbon::parse($item['start'] ?? $item->start),
            'end'   => Carbon::parse($item['end']   ?? $item->end),
        ];
    }
    
    $resources = "";
    if($takvim_turu == 1 || self::personelmi($request, 'randevu.tum_personel_gor')) {
        $resources = Personeller::join('renk_duzenleri','salon_personelleri.renk','=','renk_duzenleri.id')
                    ->where(function($q) use($request,$personel_idler, $isletmeId){
                        if(self::personelmi($request, 'randevu.tum_personel_gor')) {
                            $q->whereIn('salon_personelleri.id',$personel_idler);
                        }
                        else{
                            // Sadece bu salonun kendi personelleri kolon olarak gorunsun.
                            // (Eskiden sabit 'orWhere id=183' vardi; bu, 183 no'lu personeli
                            //  HER salonun takvimine sizdiriyordu — personel listesinde olmayan
                            //  bir isim takvimde kolon olarak cikiyordu. Kaldirildi.)
                            $q->where('salon_personelleri.salon_id', $isletmeId);
                        }
                    })->where('salon_personelleri.aktif',true)
                    ->where('salon_personelleri.takvimde_gorunsun',true)->orderBy('salon_personelleri.takvim_sirasi','asc')
                    ->get(['salon_personelleri.id as id',
                        DB::raw('CONCAT(salon_personelleri.personel_adi, " (", (SELECT COUNT(*) FROM randevu_hizmetler inner join randevular on randevu_hizmetler.randevu_id = randevular.id where randevu_hizmetler.personel_id = salon_personelleri.id and randevular.tarih <= "'.$tarih2.'" and randevular.tarih>= "'.$tarih1.'"AND randevular.durum <= 1 ) ,")") as title'),  
                        'renk_duzenleri.renk as bgcolor']);
    }
    
    if($takvim_turu == 0) {
        $resources = DB::table('salon_sunulan_hizmetler')
            ->join('hizmet_kategorisi', 'salon_sunulan_hizmetler.hizmet_kategori_id', '=', 'hizmet_kategorisi.id')
            ->join('salon_hizmet_kategori_renkleri', 'salon_hizmet_kategori_renkleri.hizmet_kategori_id', '=', 'hizmet_kategorisi.id')
            ->join('renk_duzenleri', 'salon_hizmet_kategori_renkleri.renk_id', '=', 'renk_duzenleri.id')
            ->select([
                'salon_sunulan_hizmetler.hizmet_kategori_id as id',
                'hizmet_kategorisi.hizmet_kategorisi_adi',
                'renk_duzenleri.renk as bgcolor',
                DB::raw('CONCAT(hizmet_kategorisi.hizmet_kategorisi_adi, " (", (
                    SELECT COUNT(DISTINCT randevu_hizmetler.id) 
                    FROM randevu_hizmetler 
                    INNER JOIN randevular ON randevu_hizmetler.randevu_id = randevular.id 
                    INNER JOIN hizmetler ON randevu_hizmetler.hizmet_id = hizmetler.id
                    WHERE hizmetler.hizmet_kategori_id = hizmet_kategorisi.id 
                    AND randevular.salon_id = salon_sunulan_hizmetler.salon_id
                    AND randevular.tarih <= "'.$tarih2.'" 
                    AND randevular.tarih >= "'.$tarih1.'" 
                    AND randevular.durum <= 1
                ), ")") AS title')
            ])
            ->where('salon_sunulan_hizmetler.aktif', true)
            ->where('salon_sunulan_hizmetler.salon_id', $isletmeId)
            ->groupBy(
                'salon_sunulan_hizmetler.hizmet_kategori_id',
                'hizmet_kategorisi.hizmet_kategorisi_adi',
                'renk_duzenleri.renk',
                'salon_sunulan_hizmetler.salon_id'
            )
            ->get();
    }
    
    if($takvim_turu == 2) {
        $resources = DB::table('cihazlar')
            ->join('salon_cihaz_renkleri','salon_cihaz_renkleri.cihaz_id','=','cihazlar.id')
            ->join('renk_duzenleri','salon_cihaz_renkleri.renk_id','=','renk_duzenleri.id')
            ->select(['cihazlar.id as id',
                DB::raw('CONCAT(cihazlar.cihaz_adi, " (", (
                    SELECT COUNT(*) 
                    FROM randevu_hizmetler 
                    INNER JOIN randevular ON randevu_hizmetler.randevu_id = randevular.id 
                    WHERE randevu_hizmetler.cihaz_id = cihazlar.id 
                    AND randevular.tarih <= "'.$tarih2.'" 
                    AND randevular.tarih >= "'.$tarih1.'" 
                    AND randevular.durum <= 1
                ), ")") AS title'),
                'renk_duzenleri.renk as bgcolor'
            ])->where('cihazlar.salon_id',$isletmeId)->where('cihazlar.aktifmi',true)->orderBy('takvim_sirasi','asc')->get();
    }
    
    if($takvim_turu == 3) {
        $resources = DB::table('odalar')
            ->join('salon_oda_renkleri','salon_oda_renkleri.oda_id','=','odalar.id')
            ->join('renk_duzenleri','salon_oda_renkleri.renk_id','=','renk_duzenleri.id')
            ->select(['odalar.id as id',
                DB::raw('CONCAT(odalar.oda_adi, " (", (
                    SELECT COUNT(*) 
                    FROM randevu_hizmetler 
                    INNER JOIN randevular ON randevu_hizmetler.randevu_id = randevular.id 
                    WHERE randevu_hizmetler.oda_id = odalar.id 
                    AND randevular.tarih <= "'.$tarih2.'" 
                    AND randevular.tarih >= "'.$tarih1.'" 
                    AND randevular.durum <= 1
                ), ")") AS title'),
                'renk_duzenleri.renk as bgcolor'
            ])->where('odalar.salon_id',$isletmeId)->where('odalar.aktifmi',true)->orderBy('takvim_sirasi','asc')->get();
    }

    // Boş slotları oluştur
    foreach ($resources as $resource) {
        $currentTime = $startDate->copy();
        // Sadece bu resource'a ait randevu pencereleri (cok daha kucuk liste)
        $resourceEvents = $randevu_hizmetler2_by_resource[$resource->id] ?? [];

        while ($currentTime < $endDate) {
            $overlapping = null;
            foreach ($resourceEvents as $event) {
                if ($currentTime >= $event->start && $currentTime < $event->end) {
                    $overlapping = $event;
                    break;
                }
            }

            if (!$overlapping) {
                $personelId = '';
                $personelAdi = '';
                $odaId = '';
                $odaAdi = '';

                // Eğer bu bir oda takvimi ise (takvim_turu == 3)
                if ($takvim_turu == 3) {
                    // Odaya ait personelleri OdaPersonelleri tablosundan al - sadece ilk personeli al
                    if (isset($odaPersonelleri[$resource->id]) && $odaPersonelleri[$resource->id]) {
                        $odaPersonel = $odaPersonelleri[$resource->id];
                        if ($odaPersonel->personel) {
                            $personelId = $odaPersonel->personel_id;
                            $personelAdi = $odaPersonel->personel->personel_adi;
                        }
                    }
                    
                    // Oda bilgilerini al
                    $oda = $odalar->get($resource->id);
                    if ($oda) {
                        $odaId = $oda->id;
                        $odaAdi = $oda->oda_adi;
                    }
                } 
                // Eğer personel takvimi ise (takvim_turu == 1)
                elseif ($takvim_turu == 1) {
                    $personel = $personeller->get($resource->id);
                    if ($personel) {
                        $personelId = $personel->id;
                        $personelAdi = $personel->personel_adi;
                        
                        // Bu personele ait oda varsa al (ilk oda)
                        $odaMatching = $odalar->firstWhere('personel_id', $personel->id);
                        if ($odaMatching) {
                            $odaId = $odaMatching->id;
                            $odaAdi = $odaMatching->oda_adi;
                        }
                    }
                }
                // Diğer takvim türleri için (hizmet kategorisi, cihaz)
                else {
                    // Bu takvim türlerinde personel ve oda bilgisi olmayabilir
                    // Eğer resource ID bir oda ID'si ise
                    $oda = $odalar->get($resource->id);
                    if ($oda) {
                        // Odaya ait personelleri OdaPersonelleri tablosundan al - sadece ilk personeli al
                        if (isset($odaPersonelleri[$oda->id]) && $odaPersonelleri[$oda->id]) {
                            $odaPersonel = $odaPersonelleri[$oda->id];
                            if ($odaPersonel->personel) {
                                $personelId = $odaPersonel->personel_id;
                                $personelAdi = $odaPersonel->personel->personel_adi;
                            }
                        }
                        
                        $odaId = $oda->id;
                        $odaAdi = $oda->oda_adi;
                    }
                }

                $emptySlots[] = [
                    'id' => 'empty-' . $resource->id . '-' . $currentTime->format('His'),
                    'start' => $currentTime->format('Y-m-d H:i:s'),
                    'end' => $currentTime->copy()->addMinutes(15)->format('Y-m-d H:i:s'),
                    'resourceId' => $resource->id,
                    'personelId' => $personelId,
                    'randevuId' => '',
                    'personelAdi' => $personelAdi,
                    'odaId' => $odaId,
                    'odaAdi' => $odaAdi,
                    'title' => 'Boş slot',
                    'resourceTitle' => $resource->title ?? '',
                    'color' => 'transparent',
                    'textColor' => 'transparent',
                    'eventbuttons' => '',
                    'modal_title' => '',
                ];
            }

            $currentTime->addMinutes(15);
        }
    }
    
    $calismasaatleri = array();
    foreach(SalonCalismaSaatleri::where('salon_id',$isletmeId)->get() as $calisma_saati) {
        if($calisma_saati->calisiyor) {
            array_push($calismasaatleri, array(
                'dow'=>[($calisma_saati->haftanin_gunu==7)? '0' : $calisma_saati->haftanin_gunu],
                'start'=>date('H:i',strtotime($calisma_saati->baslangic_saati)),
                'end'=>date('H:i',strtotime($calisma_saati->bitis_saati))
            ));
        }
    }
    
    $takvim_baslangic_saat = '';
    $takvim_bitis_saat = '';
    $tarih = date('Y-m-d');
    if(isset($request->takvimtarih))
        $tarih = $request->takvimtarih;
    
    $baslangic_saatleri = array();
    $bitis_saatleri = array();
    $baslangic_saatleri_tarihli = array();
    $bitis_saatleri_tarihili = array();
    
    foreach($randevu_hizmetler as $randevu) {
        if(date('Y-m-d', strtotime($randevu['start'])) == $tarih) {
            array_push($baslangic_saatleri, date('H:i:s', strtotime($randevu['start'])));
            array_push($baslangic_saatleri_tarihli, $randevu['start']);
        }
        if(date('Y-m-d', strtotime($randevu['end'])) == $tarih) {
            array_push($bitis_saatleri, date('H:i:s', strtotime($randevu['end'])));
            array_push($bitis_saatleri_tarihili, $randevu['end']);
        }
    }
    
    $day=0;
    if(date('D', strtotime($tarih))=='Mon') $day=1;
    else if(date('D', strtotime($tarih))=='Tue') $day=2;
    else if(date('D', strtotime($tarih))=='Wed') $day=3;
    else if(date('D', strtotime($tarih))=='Thu') $day=4;
    else if(date('D', strtotime($tarih))=='Fri') $day=5;
    else if(date('D', strtotime($tarih))=='Sat') $day=6;
    else if(date('D', strtotime($tarih))=='Sun') $day=7;
    
    $calismasaatibaslangic = SalonCalismaSaatleri::where('salon_id',$isletmeId)->where('haftanin_gunu',$day)->value('baslangic_saati');
    $calismasaatibitis = SalonCalismaSaatleri::where('salon_id',$isletmeId)->where('haftanin_gunu',$day)->value('bitis_saati');
    
    if($calismasaatibaslangic == '00:00:00')
        $calismasaatibaslangic = "06:00:00";
    if($calismasaatibitis == '00:00:00')
        $calismasaatibitis = "20:00:00";
    
    if(!empty($baslangic_saatleri) && strtotime(min($baslangic_saatleri)) < strtotime($calismasaatibaslangic))
        $takvim_baslangic_saat = min($baslangic_saatleri);
    else
        $takvim_baslangic_saat = $calismasaatibaslangic;
    
    if(!empty($bitis_saatleri) && strtotime(max($bitis_saatleri)) > strtotime($calismasaatibitis))
        $takvim_bitis_saat = max($bitis_saatleri);
    else
        $takvim_bitis_saat = $calismasaatibitis;
    
    $randevu_sayisi = $randevu_hizmetler->count();
    Log::info('randevu yükleme bitti');

    return array(
        'randevu' => array_merge($randevu_hizmetler->toArray(), $emptySlots),
        'resource' => $resources,
        'baslangic' => $takvim_baslangic_saat,
        'bitis' => $takvim_bitis_saat,
        'calismasaatleri' => $calismasaatleri,
        'baslangic_saatleri' => $baslangic_saatleri,
        'bitis_saatleri' => $takvim_bitis_saat,
        'randevu_sayisi' => $randevu_sayisi,
    );
}

    public function kasadefteri(Request $request){
       $isletmeler = '';
        $isletme='';
        if(Auth::guard('satisortakligi')->check())
        {
            $isletmeler = [15];
            $isletme = Salonlar::where('id',15)->first();
        }
        else{
            $isletmeler = Auth::guard('isletmeyonetim')->user()->yetkili_olunan_isletmeler->where('aktif',1)->pluck('salon_id')->toArray();
            $isletme= Salonlar::where('id',self::mevcutsube($request))->first();
        }


        if(!in_array(self::mevcutsube($request),$isletmeler ) || $_SERVER['HTTP_HOST'] == "randevu.randevumcepte.com.tr")
        {
            return view('isletmeadmin.yetkisizerisim');
            exit(0);
        }
        if(str_contains(self::lisans_sure_kontrol($request),'-'))
        {
            return view('isletmeadmin.lisanssurebitti',['isletme'=>$isletme]);
            exit(0);
        }
        // Yetki: bu sayfanin gerektirdigi yetki yoksa 403
        $_authUser = Auth::guard('isletmeyonetim')->user();
        if ($_authUser && !(
            \App\Services\PersonelYetkiServisi::yetkiliYetkiVar($_authUser->id, self::mevcutsube($request), 'rapor.kasa')
            || \App\Services\PersonelYetkiServisi::yetkiliYetkiVar($_authUser->id, self::mevcutsube($request), 'finans.kasa_giris_cikis')
            || \App\Services\PersonelYetkiServisi::yetkiliYetkiVar($_authUser->id, self::mevcutsube($request), 'finans.masraf_gor')
            || \App\Services\PersonelYetkiServisi::yetkiliYetkiVar($_authUser->id, self::mevcutsube($request), 'finans.masraf_ekle')
            || \App\Services\PersonelYetkiServisi::yetkiliYetkiVar($_authUser->id, self::mevcutsube($request), 'finans.alacak_yonet')
        )) {
            return view('isletmeadmin.yetkisizerisim');
            exit(0);
        }

        if(count($isletmeler)>1 && !isset($_GET['sube']))
        {
            return view('isletmeadmin.isletmesec',['isletmeler'=>$isletmeler,'isletme'=>$isletme]);
            exit(0);
        }
        $isletme = Salonlar::where('id',self::mevcutsube($request))->first();
        $kasa = self::kasa_raporu_getir($request,'');
        return view('isletmeadmin.kasadefteri',['sayfa_baslik'=>'Kasa Raporu', 'title'=> 'Kasa Defteri | '.$isletme->salon_adi.' İşletme Yönetim Paneli',   'pageindex' => 103, 'bildirimler'=>self::bildirimgetir($request),'isletme'=>$isletme,'kasa'=>$kasa, 'kalan_uyelik_suresi' => self::lisans_sure_kontrol($request),'urun_drop'=>self::urundropliste($request),
            'yetkiliolunanisletmeler'=>$isletmeler]);
    }
    public function kasa_raporu_filtre(Request $request)
    {
        if($r = self::yetkiYoksa403($request, 'rapor.kasa')) return $r;
        return self::kasa_raporu_getir($request,'');
    }
    
public function kasa_raporu_getir(Request $request,$returntext)
{
    $tarih_baslangic = date('Y-m-01');
    $tarih_bitis = date('Y-m-d');
    $odeme_yontemi = '';
    
    // Tarih filtreleri
    if(isset($request->kasa_baslangic_tarihi))
    {
        if($request->kasa_baslangic_tarihi!='')
            $tarih_baslangic = $request->kasa_baslangic_tarihi;
    }
    if(isset($request->kasa_bitis_tarihi)){
        if($request->kasa_bitis_tarihi!='')
            $tarih_bitis = $request->kasa_bitis_tarihi;
    }
    Log::info('başlangıç '.$tarih_baslangic);
     Log::info('bitis '.$tarih_bitis);
    if(isset($request->baslangic_bitis_tarihi))
    {
        if($request->baslangic_bitis_tarihi != 'ozel'){
            $tarih = explode(' / ',$request->baslangic_bitis_tarihi);
            $tarih_baslangic = $tarih[0];
            $tarih_bitis = $tarih[1];
        }
    }
    if(isset($request->odeme_yontemi))
        $odeme_yontemi = $request->odeme_yontemi;
    
    // Salon ID'si
    $salon_id = self::mevcutsube($request);

    // Sistem-wide faturasiz gizle: aktifse SADECE faturali adisyon kalemlerine
    // ait tahsilat tutarlari dahil edilir. Bir POS tahsilati birden fazla
    // adisyon kalemini odeyebildigi icin: tahsilat HEADER tutari kullanilmaz,
    // tahsilat_hizmetler/urunler/paketler DETAY tablolarindan **faturali
    // kalemlere dusen** kismi hesaplanir.
    $_faturasizGizle = (bool) Salonlar::where('id', $salon_id)->value('faturasiz_gizle');
    $_faturaliTahsilatIds = null;
    $_faturaliKisimMap = [];
    if ($_faturasizGizle) {
        $_faturaliAdisyonIds = Adisyonlar::where('salon_id', $salon_id)
            ->where('fatura_kesildi', 1)->pluck('id');
        // her DETAY satiri: tahsilat_id => tutar
        $_dHizmet = DB::table('tahsilat_hizmetler')
            ->whereIn('adisyon_hizmet_id', function($q) use($_faturaliAdisyonIds){
                $q->select('id')->from('adisyon_hizmetler')->whereIn('adisyon_id', $_faturaliAdisyonIds);
            })->select('tahsilat_id','tutar')->get();
        $_dUrun = DB::table('tahsilat_urunler')
            ->whereIn('adisyon_urun_id', function($q) use($_faturaliAdisyonIds){
                $q->select('id')->from('adisyon_urunler')->whereIn('adisyon_id', $_faturaliAdisyonIds);
            })->select('tahsilat_id','tutar')->get();
        $_dPaket = DB::table('tahsilat_paketler')
            ->whereIn('adisyon_paket_id', function($q) use($_faturaliAdisyonIds){
                $q->select('id')->from('adisyon_paketler')->whereIn('adisyon_id', $_faturaliAdisyonIds);
            })->select('tahsilat_id','tutar')->get();
        // tahsilat_id => faturali kisim toplami
        foreach ([$_dHizmet, $_dUrun, $_dPaket] as $_set) {
            foreach ($_set as $_r) {
                $_faturaliKisimMap[$_r->tahsilat_id] = ($_faturaliKisimMap[$_r->tahsilat_id] ?? 0) + (float) $_r->tutar;
            }
        }
        $_faturaliTahsilatIds = array_keys($_faturaliKisimMap);
        if (empty($_faturaliTahsilatIds)) $_faturaliTahsilatIds = [0];
    }

    // Filtrelenmiş tahsilatlar (seçilen tarih aralığı için)
    // odeme_tarihi bir DATETIME oldugu icin gun sinirlari 00:00:00 / 23:59:59
    // olmali; aksi halde aralik bitis gununun saatli kayitlari dusuyordu.
    $tahsilatlar = Tahsilatlar::where('salon_id', $salon_id)
        ->where('odeme_tarihi','>=',$tarih_baslangic.' 00:00:00')
        ->where('odeme_tarihi','<=',$tarih_bitis.' 23:59:59')
        ->where(function($q) use($odeme_yontemi){
            if($odeme_yontemi != '') $q->where('odeme_yontemi_id',$odeme_yontemi);
        })
        ->when($_faturasizGizle, fn($q) => $q->whereIn('id', $_faturaliTahsilatIds))
        ->orderBy('odeme_tarihi','desc')
        ->get();

    // Goruntulenecek tutar: toggle acikken faturali kisim, kapaliyken tahsilat header
    $_gosterTutar = function($t) use($_faturasizGizle, $_faturaliKisimMap) {
        if ($_faturasizGizle) return (float) ($_faturaliKisimMap[$t->id] ?? 0);
        return (float) $t->tutar;
    };
    $_donem_gelir = 0;
    foreach ($tahsilatlar as $_t) { $_donem_gelir += $_gosterTutar($_t); }

    // TÜM ZAMANLARIN TAHŞİLAT TOPLAMI (filtrelerden bağımsız ama faturasiz_gizle uygulanir)
    if ($_faturasizGizle) {
        $tum_tahsilatlar_toplam = array_sum($_faturaliKisimMap);
    } else {
        $tum_tahsilatlar_toplam = Tahsilatlar::where('salon_id', $salon_id)->sum('tutar');
    }

    $tahsilat_liste = '';
    foreach($tahsilatlar as $tahsilat){
        $_gostTutar = $_gosterTutar($tahsilat);
        $tahsilat_liste .= '<tr class="rc-kd-gelir-row" data-tahsilat-id="'.$tahsilat->id.'" title="Detayları görüntülemek için tıklayın">
                        <td>'.date('d.m.Y',strtotime($tahsilat->odeme_tarihi)).'</td>
                        <td>';
        if($tahsilat->user_id !== null)
        {
            $tahsilat_liste .= $tahsilat->musteri ? $tahsilat->musteri->name : '';
        }
        $tahsilat_liste .= '</td>';
        $tahsilat_liste .= '<td>'.($tahsilat->olusturan? $tahsilat->olusturan->personel_adi : '').'</td>';
        $tahsilat_liste .='</td>
                        <td>'.$tahsilat->notlar.'</td>
                        <td>'.$tahsilat->odeme_yontemi->odeme_yontemi.($tahsilat->banka_id !== null ? '<br>'.$tahsilat->banka->banka : '').'</td>
                        <td>'.number_format($_gostTutar,2,',','.').'</td>';
        if($tahsilat->para_girisi == true)
            $tahsilat_liste .= '<td>
                      <button style="line-height:5px;padding:5px"  class="btn btn-danger" href="#" title="Para Ekleme Sil"  name="para_ekleme_sil" data-value="'.$tahsilat->id.'"><i class="fa fa-times"></i></button></td>';
        elseif($tahsilat->adisyon_id === null && $tahsilat->para_cikisi != true)
            $tahsilat_liste .= '<td>
                      <button style="line-height:5px;padding:5px"  class="btn btn-danger" href="#" title="Bağımsız Tahsilatı Sil"  name="bagimsiz_tahsilat_sil" data-value="'.$tahsilat->id.'"><i class="fa fa-times"></i></button></td>';

        $tahsilat_liste .= '</tr>';
    }
    
    // Filtrelenmiş masraflar (seçilen tarih aralığı için)
    $masraflar = Masraflar::where('salon_id', $salon_id)
        ->where('tarih','>=',$tarih_baslangic.' 00:00:00')
        ->where('tarih','<=',$tarih_bitis.' 23:59:59')
        ->where(function($q) use($odeme_yontemi){
            if($odeme_yontemi != '') $q->where('odeme_yontemi_id',$odeme_yontemi);
        })
        ->orderBy('tarih','desc')
        ->get();
    
    // TÜM ZAMANLARIN MASRAF TOPLAMI (filtrelerden bağımsız)
    $tum_masraflar_toplam = Masraflar::where('salon_id', $salon_id)
        ->sum('tutar');
    
    $masraf_liste = '';
    foreach($masraflar as $masraf){
        // Gider turu rozeti: personel gideri (turuncu) / maas-prim odemesi (indigo) /
        // digerleri normal isletme masrafi (kirmizi).
        if($masraf->personel_gideri)
            $_giderRozet = ' <span style="background:#f59e0b;color:#fff;border-radius:6px;padding:1px 7px;font-size:11px;white-space:nowrap">Personel Gideri</span>';
        elseif($masraf->personel_maas_odemesi_id)
            $_giderRozet = ' <span style="background:#6366f1;color:#fff;border-radius:6px;padding:1px 7px;font-size:11px;white-space:nowrap">Personel Ödemesi</span>';
        else
            $_giderRozet = ' <span style="background:#dc2626;color:#fff;border-radius:6px;padding:1px 7px;font-size:11px;white-space:nowrap">İşletme Masrafı</span>';
        // Aciklama bos ise kategori adini goster (isletme masraflarinda cogu zaman aciklama girilmez)
        $_masrafAciklama = $masraf->aciklama;
        if(trim((string)$_masrafAciklama) === '' && $masraf->masraf_kategorisi)
            $_masrafAciklama = $masraf->masraf_kategorisi->kategori;
        $masraf_liste .= '<tr>
                        <td>'.date('d.m.Y',strtotime($masraf->tarih)).'</td>
                        <td>'.($masraf->harcayan_id ? $masraf->harcayan->personel_adi : 'Kasa').$_giderRozet.'</td>
                        <td>'.$_masrafAciklama.'</td>
                        <td>'.$masraf->odeme_yontemi->odeme_yontemi.'</td>
                        <td>'.number_format($masraf->tutar,2,',','.').'</td>
                        <td><button style="line-height:5px;padding:5px" title="Düzenle"   name="masraf_duzenle" type="button" data-toggle="modal" data-target="#yeni_masraf_modal" onclick="modalbaslikata(\'Masraf Düzenleme\',\'\')" data-value="'.$masraf->id.'"  class="btn btn-primary"><i class="fa fa-edit"></i>
                        </button>
                      <button style="line-height:5px;padding:5px"  class="btn btn-danger" href="#" title="Masrafı Sil"  name="masraf_sil" data-value="'.$masraf->id.'"><i class="fa fa-times"></i></button>
</td>
                        ';
    }

    // TOPLAM CİRO HESAPLAMA (Filtrelerden bağımsız - tüm zamanların net karı)
    $toplam_ciro = $tum_tahsilatlar_toplam - $tum_masraflar_toplam;

    // Filtrelenmiş dönem için net kar (faturasiz_gizle aktifken sadece faturali kisim)
    $donem_net_kar = $_donem_gelir - $masraflar->sum('tutar');

    return array(
        'tahsilatlar'=>$tahsilat_liste,
        'masraflar'=>$masraf_liste,
        'gelir'=>number_format($_donem_gelir,2,',','.'),
        'gider'=>number_format($masraflar->sum('tutar'),2,',','.'),
        'toplam'=>number_format($donem_net_kar,2,',','.'), // Filtrelenmiş dönem için net kar
        'toplam_ciro'=>number_format($toplam_ciro,2,',','.'), // Tüm zamanlar için toplam ciro
        'mesaj'=>$returntext
    );
}

/**
 * GÜN SONU RAPORU — seçilen gün/tarih araligi icin finansal ozet.
 * Cekirdek (Saloon Appy pariteli): odeme yontemine gore GELIR / MASRAF / NET kirilimi.
 * Ekstra: islem-musteri sayisi, ortalama sepet, personel bazli ciro, en cok satan hizmet/urun.
 * Kasa raporu sayfasindaki "Gün Sonu" butonu bu endpoint'i AJAX ile cagirir.
 */
public function gun_sonu_raporu(Request $request)
{
    if($r = self::yetkiYoksa403($request, 'rapor.kasa')) return $r;
    $salon_id = self::mevcutsube($request);

    // Tarih araligi — varsayilan BUGÜN
    $b   = ($request->baslangic && $request->baslangic != '') ? $request->baslangic : date('Y-m-d');
    $bit = ($request->bitis && $request->bitis != '')         ? $request->bitis     : $b;

    // ---- faturasiz_gizle: aktifse gelirde SADECE faturali kisim sayilir
    // (kasa_raporu_getir ile ayni mantik; rakamlar sayfa kartlariyla tutarli kalsin) ----
    $_faturasizGizle = (bool) Salonlar::where('id', $salon_id)->value('faturasiz_gizle');
    $_faturaliKisimMap = [];
    $_faturaliTahsilatIds = [0];
    if ($_faturasizGizle) {
        $_faturaliAdisyonIds = Adisyonlar::where('salon_id', $salon_id)->where('fatura_kesildi', 1)->pluck('id');
        $_dHizmet = DB::table('tahsilat_hizmetler')->whereIn('adisyon_hizmet_id', function($q) use($_faturaliAdisyonIds){
            $q->select('id')->from('adisyon_hizmetler')->whereIn('adisyon_id', $_faturaliAdisyonIds);
        })->select('tahsilat_id','tutar')->get();
        $_dUrun = DB::table('tahsilat_urunler')->whereIn('adisyon_urun_id', function($q) use($_faturaliAdisyonIds){
            $q->select('id')->from('adisyon_urunler')->whereIn('adisyon_id', $_faturaliAdisyonIds);
        })->select('tahsilat_id','tutar')->get();
        $_dPaket = DB::table('tahsilat_paketler')->whereIn('adisyon_paket_id', function($q) use($_faturaliAdisyonIds){
            $q->select('id')->from('adisyon_paketler')->whereIn('adisyon_id', $_faturaliAdisyonIds);
        })->select('tahsilat_id','tutar')->get();
        foreach ([$_dHizmet, $_dUrun, $_dPaket] as $_set) {
            foreach ($_set as $_r) {
                $_faturaliKisimMap[$_r->tahsilat_id] = ($_faturaliKisimMap[$_r->tahsilat_id] ?? 0) + (float) $_r->tutar;
            }
        }
        $_faturaliTahsilatIds = array_keys($_faturaliKisimMap);
        if (empty($_faturaliTahsilatIds)) $_faturaliTahsilatIds = [0];
    }

    // ---- GELIR: odeme yontemine gore (para girisi de gelir sayilir) ----
    // odeme_tarihi bir DATETIME oldugu icin gun sinirlari 00:00:00 / 23:59:59 olmali,
    // aksi halde aralik bitis gununun saatli kayitlari (ozellikle "Bugün") duser.
    $tahsilatlar = Tahsilatlar::where('salon_id', $salon_id)
        ->where('odeme_tarihi','>=',$b.' 00:00:00')->where('odeme_tarihi','<=',$bit.' 23:59:59')
        ->when($_faturasizGizle, function($q) use($_faturaliTahsilatIds){ return $q->whereIn('id', $_faturaliTahsilatIds); })
        ->with(['musteri','olusturan','odeme_yontemi'])
        ->orderBy('odeme_tarihi','asc')
        ->get();

    $gelir = ['nakit'=>0,'kredikarti'=>0,'havale'=>0,'online'=>0,'diger'=>0];
    $islem_say = 0; $gercek_gelir = 0; $musteriler = [];
    $satislar = []; // Tam Detay (saglama) icin kalem kalem satis listesi
    foreach ($tahsilatlar as $t) {
        $tutar = $_faturasizGizle ? (float)($_faturaliKisimMap[$t->id] ?? 0) : (float)$t->tutar;
        switch ((int)$t->odeme_yontemi_id) {
            case 1: $gelir['nakit']      += $tutar; break;
            case 2: $gelir['kredikarti'] += $tutar; break;
            case 3: $gelir['havale']     += $tutar; break;
            case 4: $gelir['online']     += $tutar; break;
            default: $gelir['diger']     += $tutar; break;
        }
        // Islem/musteri metrikleri: elle para girisini hesaba katma
        if (!$t->para_girisi) {
            $islem_say++;
            $gercek_gelir += $tutar;
            if ($t->user_id) $musteriler[$t->user_id] = true;
        }
        $satislar[] = [
            'saat'        => date('H:i', strtotime($t->odeme_tarihi)),
            'musteri'     => $t->para_girisi ? 'Kasa Girişi' : ($t->musteri ? $t->musteri->name : '-'),
            'tahsil_eden' => $t->olusturan ? $t->olusturan->personel_adi : '',
            'yontem'      => $t->odeme_yontemi ? $t->odeme_yontemi->odeme_yontemi : '',
            'para_girisi' => (bool)$t->para_girisi,
            'tutar'       => $tutar,
        ];
    }
    $gelir_toplam = array_sum($gelir);

    // ---- MASRAF: odeme yontemine gore (kasadan para alma da masraf olarak kayitli) ----
    $masraflar = Masraflar::where('salon_id', $salon_id)
        ->where('tarih','>=',$b.' 00:00:00')->where('tarih','<=',$bit.' 23:59:59')
        ->with(['harcayan','odeme_yontemi'])
        ->orderBy('tarih','asc')->orderBy('id','asc')->get();
    $masraf = ['nakit'=>0,'kredikarti'=>0,'havale'=>0,'online'=>0,'diger'=>0];
    // Tam Detay (saglama): isletme masraflari vs personel gider/odemeleri ayri listelenir
    $isletme_masraflari = []; $personel_giderleri = [];
    $isletme_masraf_toplam = 0; $personel_gider_toplam = 0;
    foreach ($masraflar as $m) {
        $mt = (float)$m->tutar;
        switch ((int)$m->odeme_yontemi_id) {
            case 1: $masraf['nakit']      += $mt; break;
            case 2: $masraf['kredikarti'] += $mt; break;
            case 3: $masraf['havale']     += $mt; break;
            case 4: $masraf['online']     += $mt; break;
            default: $masraf['diger']     += $mt; break;
        }
        $_mAciklama = $m->aciklama;
        if(trim((string)$_mAciklama) === '' && $m->masraf_kategorisi)
            $_mAciklama = $m->masraf_kategorisi->kategori;
        $_row = [
            'harcayan' => $m->harcayan_id ? ($m->harcayan ? $m->harcayan->personel_adi : '') : 'Kasa',
            'aciklama' => $_mAciklama,
            'yontem'   => $m->odeme_yontemi ? $m->odeme_yontemi->odeme_yontemi : '',
            'tutar'    => $mt,
        ];
        if ($m->personel_gideri || $m->personel_maas_odemesi_id) {
            $_row['tip'] = $m->personel_gideri ? 'Personel Gideri' : 'Personel Ödemesi';
            $personel_giderleri[] = $_row;
            $personel_gider_toplam += $mt;
        } else {
            $isletme_masraflari[] = $_row;
            $isletme_masraf_toplam += $mt;
        }
    }
    $masraf_toplam = array_sum($masraf);

    // ---- NET (Toplam) = gelir - masraf, yontem bazinda ----
    $net = [];
    foreach (['nakit','kredikarti','havale','online','diger'] as $k) {
        $net[$k] = $gelir[$k] - $masraf[$k];
    }
    $net_toplam = $gelir_toplam - $masraf_toplam;

    // ---- Ekstra metrikler ----
    $musteri_say = count($musteriler);
    $ort_sepet   = $islem_say > 0 ? ($gercek_gelir / $islem_say) : 0;

    // ---- Personel bazli ciro (TAHSILAT bazli: donemde tahsil edilen hizmet parasi,
    //      personelin yaptigi hizmete gore). Kasa geliriyle ayni temele (odeme_tarihi) oturur;
    //      odemesi bugun olan ama baska gun acilan adisyonlar da yakalanir. ----
    $personelRows = DB::table('tahsilat_hizmetler as th')
        ->join('tahsilatlar as t','t.id','=','th.tahsilat_id')
        ->join('adisyon_hizmetler as ah','ah.id','=','th.adisyon_hizmet_id')
        ->join('salon_personelleri as p','p.id','=','ah.personel_id')
        ->where('t.salon_id', $salon_id)
        ->whereBetween('t.odeme_tarihi', [$b.' 00:00:00', $bit.' 23:59:59'])
        ->whereNotNull('ah.personel_id')
        ->select('p.personel_adi',
            DB::raw('COUNT(DISTINCT th.id) as adet'),
            DB::raw('SUM(th.tutar) as ciro'))
        ->groupBy('p.id','p.personel_adi')
        ->orderByDesc('ciro')
        ->limit(15)->get();

    // ---- En cok satan hizmet (ilk 5) — tahsilat bazli ----
    $topHizmet = DB::table('tahsilat_hizmetler as th')
        ->join('tahsilatlar as t','t.id','=','th.tahsilat_id')
        ->join('adisyon_hizmetler as ah','ah.id','=','th.adisyon_hizmet_id')
        ->join('hizmetler as h','h.id','=','ah.hizmet_id')
        ->where('t.salon_id', $salon_id)
        ->whereBetween('t.odeme_tarihi', [$b.' 00:00:00', $bit.' 23:59:59'])
        ->select('h.hizmet_adi',
            DB::raw('COUNT(DISTINCT th.id) as adet'),
            DB::raw('SUM(th.tutar) as ciro'))
        ->groupBy('h.id','h.hizmet_adi')
        ->orderByDesc('ciro')
        ->limit(5)->get();

    // ---- En cok satan urun (ilk 5) — tahsilat bazli ----
    $topUrun = DB::table('tahsilat_urunler as tu')
        ->join('tahsilatlar as t','t.id','=','tu.tahsilat_id')
        ->join('adisyon_urunler as au','au.id','=','tu.adisyon_urun_id')
        ->leftJoin('urunler as u','u.id','=','au.urun_id')
        ->where('t.salon_id', $salon_id)
        ->whereBetween('t.odeme_tarihi', [$b.' 00:00:00', $bit.' 23:59:59'])
        ->select(DB::raw("COALESCE(u.urun_adi,'Silinmiş Ürün') as urun_adi"),
            DB::raw('COUNT(DISTINCT tu.id) as adet'),
            DB::raw('SUM(tu.tutar) as ciro'))
        ->groupBy('u.id','u.urun_adi')
        ->orderByDesc('ciro')
        ->limit(5)->get();

    return response()->json([
        'durum'      => 'ok',
        'baslangic'  => $b,
        'bitis'      => $bit,
        'tek_gun'    => ($b === $bit),
        'gelir'          => $gelir,
        'gelir_toplam'   => $gelir_toplam,
        'masraf'         => $masraf,
        'masraf_toplam'  => $masraf_toplam,
        'net'            => $net,
        'net_toplam'     => $net_toplam,
        'islem_say'      => $islem_say,
        'musteri_say'    => $musteri_say,
        'ort_sepet'      => $ort_sepet,
        'personeller'    => $personelRows,
        'top_hizmet'     => $topHizmet,
        'top_urun'       => $topUrun,
        // Tam Detay (saglama)
        'satislar'                => $satislar,
        'isletme_masraflari'      => $isletme_masraflari,
        'personel_giderleri'      => $personel_giderleri,
        'isletme_masraf_toplam'   => $isletme_masraf_toplam,
        'personel_gider_toplam'   => $personel_gider_toplam,
    ]);
}
public function devredenAylar(Request $request)
{
    $salon_id = self::mevcutsube($request);
    $yil = $request->yil ?? date('Y');
    
    $aylar = [];
    
    // Tüm ayları döngüye al
    for ($ay = 1; $ay <= 12; $ay++) {
        $tarih_baslangic = $yil . '-' . str_pad($ay, 2, '0', STR_PAD_LEFT) . '-01';
        $tarih_bitis = date('Y-m-t', strtotime($tarih_baslangic));
        
        // Aylık tahsilatlar
        $tahsilatlar = Tahsilatlar::where('salon_id', $salon_id)
            ->where('odeme_tarihi', '>=', $tarih_baslangic.' 00:00:00')
            ->where('odeme_tarihi', '<=', $tarih_bitis.' 23:59:59')
            ->sum('tutar');

        // Aylık masraflar
        $masraflar = Masraflar::where('salon_id', $salon_id)
            ->where('tarih', '>=', $tarih_baslangic.' 00:00:00')
            ->where('tarih', '<=', $tarih_bitis.' 23:59:59')
            ->sum('tutar');
        
        // Dönem net karı
        $donem_net_kar = $tahsilatlar - $masraflar;
        
        // Ay adını Türkçe yap
        $ay_adi = date('F', strtotime($tarih_baslangic));
        $ay_adi_tr = $this->ayAdiCevir($ay_adi);
        
        $aylar[] = [
            'ay' => $ay,
            'ay_adi' => $ay_adi_tr,
            'yil' => $yil,
            'tahsilatlar' => $tahsilatlar,
            'masraflar' => $masraflar,
            'donem_net_kar' => $donem_net_kar
        ];
    }
    
    return response()->json([
        'success' => true,
        'data' => $aylar
    ]);
}

// Ay adı çevirme fonksiyonu (Controller içinde)
private function ayAdiCevir($ingilizceAy)
{
    $aylar = [
        'January' => 'OCAK',
        'February' => 'ŞUBAT',
        'March' => 'MART',
        'April' => 'NİSAN',
        'May' => 'MAYIS',
        'June' => 'HAZİRAN',
        'July' => 'TEMMUZ',
        'August' => 'AĞUSTOS',
        'September' => 'EYLÜL',
        'October' => 'EKİM',
        'November' => 'KASIM',
        'December' => 'ARALIK'
    ];
    
    return $aylar[$ingilizceAy] ?? $ingilizceAy;
}
    public function isletme(){
        $isletmeler = '';
        $isletme='';
        if(Auth::guard('satisortakligi')->check())
        {
            $isletmeler = [15];
            $isletme = Salonlar::where('id',15)->first();
        }
        else{
            $isletmeler = Auth::guard('isletmeyonetim')->user()->yetkili_olunan_isletmeler->where('aktif',1)->pluck('salon_id')->toArray();
            $isletme= Salonlar::where('id',self::mevcutsube($request))->first();
        }
        
        
        if(!in_array(self::mevcutsube($request),$isletmeler ))
        {
            return view('isletmeadmin.yetkisizerisim');
            exit(0);
        }
        if(str_contains(self::lisans_sure_kontrol($request),'-'))
        {
            return view('isletmeadmin.lisanssurebitti',['isletme'=>$isletme]);
            exit(0);
        }
        if(!Auth::guard('satisortakligi')->check()){
             if(self::personelmi($request))
            {
                    return redirect()->route('isletmeadmin.randevular');
                    exit(0);
            }
        }
       
        if(count($isletmeler)>1 && !isset($_GET['sube']))
        {
            return view('isletmeadmin.isletmesec',['isletmeler'=>$isletmeler,'isletme'=>$isletme]);
            exit(0);
        }
        $id = Auth::guard('isletmeyonetim')->user()->salon_id;
        $isletme = Salonlar::where('id',$id)->first();
        $subeler = Subeler::where('salon_id',$id)->get();
        $salonhizmetler = SalonHizmetler::where('salon_id',$id)->get();
        $personeller = Personeller::where('salon_id',$id)->get();
        $saloncalismasaatleri = SalonCalismaSaatleri::where('salon_id',$id)->orderBy('haftanin_gunu','asc')->get();
        $salongorselleri = SalonGorselleri::where('salon_id',$id)->where('kapak_fotografi','!=',1)->get();
        $salongorselkapak = SalonGorselleri::where('salon_id',$id)->where('kapak_fotografi',1)->first();
        $etiketler = AramaTerimleri::where('salon_id',$id)->orderBy('id','asc')->get();
        $isletmeturu = SalonTuru::all();
        $hizmetler = Hizmetler::all();
        $isletmeturu_html = "";
        $gorseller_html = "";
        $hizmetlistesi_html = "";
         foreach ($hizmetler as $key => $value) {
             $hizmetlistesi_html.="<option value='".$value->id."'>".$value->hizmet_adi."</option>";
        }
        foreach ($isletmeturu as $key => $value) {
            if($value->id ==$isletme->salon_turu_id)
                $isletmeturu_html .= "<option selected value='".$value->id."'>".$value->salon_turu_adi."</option>";
            else
                $isletmeturu_html .= "<option value='".$value->id."'>".$value->salon_turu_adi."</option>";
        }
        foreach($salongorselleri as $key => $value){
            $gorselindex = $key+1;
            $gorseller_html .= " <div class='item'>
              <div class='photo'>
                <div class='img'><img id='gorsel".$gorselindex."' src='/".$value->salon_gorseli."' alt='Salon Görseli'>
                  <div class='over'>
                    <div class='info-wrapper'>
                      <div class='info'>
                        <div class='func'><a id='gorsellink".$gorselindex."' href='/".$value->salon_gorseli."' class='image-zoom'><i class='icon mdi mdi-search'></i></a> <a style='cursor:pointer' name='gorsel' title='Kaldır' data-value='".$value->id."'><i class='icon mdi mdi-delete'></i></a></div>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </div>";
        }
        if($salongorselleri->count()<12){
            for($i=$salongorselleri->count()+1;$i<=12;$i++){
