    public function personelekleduzenle(Request $request){
        if($r = self::yetkiYoksa403($request, 'personel.ekle_duzenle')) return $r;
        $result = '';
        $swaltitle = '';
        $swalstat  ='';
        $yenihesapacma = false;
        $yeniekleme = false;
        $olusturulansifre = '';
        $personel = '';
        $yetkili = '';
        $rol_id='';
        $isDuzenleme = !empty($request->personel_id);
        // YENI EKLEMEDE telefon zaten varsa uyari ver
        if(!$isDuzenleme && Personeller::where('cep_telefon',$request->cep_telefon)->where('salon_id',$request->sube)->count() >= 1 ){
            $result = 'Girmiş olduğunuz cep telefonu ile sistemde '.IsletmeYetkilileri::where('gsm1',$request->cep_telefon)->value('name').' isimli kayıt zaten mevcut. Lütfen başka bir kayıt giriniz';
            $swaltitle = 'Uyarı';
            $swalstat  = 'warning';
        }
        else{
            $sistemyetkisi = '';
            if(isset($request->sistem_yetki))
                $sistemyetkisi = $request->sistem_yetki;
            else
                $sistemyetkisi = 'Hesap Sahibi';
            $rol_id = DB::table('roles')->where('name',$sistemyetkisi)->value('id');

            if($isDuzenleme){
                // DUZENLEME: personel'i id ile bul, yetkili'sini yetkili_id ile bul
                $personel = Personeller::where('id',$request->personel_id)->where('salon_id',$request->sube)->first();
                if($personel && $personel->yetkili_id){
                    $yetkili = IsletmeYetkilileri::where('id',$personel->yetkili_id)->first();
                }
                if(!$yetkili){
                    // Personel'in yetkili'si yoksa, gsm ile dene
                    $yetkili = IsletmeYetkilileri::where('gsm1',$request->cep_telefon)->first();
                    if(!$yetkili){
                        $yetkili = new IsletmeYetkilileri();
                        $yenihesapacma = true;
                    }
                }
            } else {
                // YENI EKLEME: yetkili'yi gsm ile bul/olustur
                $existing = IsletmeYetkilileri::where('gsm1',$request->cep_telefon)->first();
                if(!$existing){
                    $yetkili = new IsletmeYetkilileri();
                    $yenihesapacma = true;
                } else {
                    $yetkili = $existing;
                }
                $personel = new Personeller();
                $yeniekleme = true;
                $personel->aktif=true;
                $personel->takvimde_gorunsun = true;
                $personel->takvim_sirasi = Personeller::where('salon_id',$request->sube)->orderBy('takvim_sirasi','desc')->value('takvim_sirasi') + 1;
                $son_eklenen_personel = Personeller::where('salon_id',$request->sube)->orderBy('id','desc')->first();
                if($son_eklenen_personel && $son_eklenen_personel->renk == 10)
                        $personel->renk = 1;
                else
                        $personel->renk = ($son_eklenen_personel ? $son_eklenen_personel->renk : 0) + 1;
            }
           
         
            $yetkili->unvan = $request->unvan;
            $yetkili->cinsiyet = $request->cinsiyet;
            $yetkili->profil_resim = '/public/isletmeyonetim_assets/img/avatar.png';
            $yetkili->name = $request->personel_adi;
            $yetkili->gsm1 = $request->cep_telefon;
            if($yenihesapacma)
            {
                $random = str_shuffle('abcdefghjklmnopqrstuvwxyzABCDEFGHJKLMNOPQRSTUVWXYZ1234567890');
                $olusturulansifre = substr($random, 0, 6);
                $yetkili->password = Hash::make($olusturulansifre);
                $yetkili->aktif=true;
            }
            $yetkili->save();
            $personel->personel_adi = $request->personel_adi;
            $personel->cep_telefon = $request->cep_telefon;
            $personel->salon_id = $request->sube;
            $personel->cinsiyet = $request->cinsiyet;
            $personel->maas = $request->personel_maas;
            $personel->unvan = $request->unvan;
            $personel->hizmet_prim_yuzde = $request->hizmet_prim_yuzde;
            $personel->urun_prim_yuzde = $request->urun_prim_yuzde;
            $personel->paket_prim_yuzde = $request->paket_prim_yuzde;
            // Detayli (kalem bazli) prim anahtarlari — checkbox isaretsizse gelmez
            if(\Schema::hasColumn('salon_personelleri','hizmet_prim_detayli')){
                $personel->hizmet_prim_detayli = $request->has('hizmet_prim_detayli') ? 1 : 0;
                $personel->urun_prim_detayli   = $request->has('urun_prim_detayli') ? 1 : 0;
                $personel->paket_prim_detayli  = $request->has('paket_prim_detayli') ? 1 : 0;
            }
            $personel->yetkili_id = $yetkili->id;
            $personel->role_id = $rol_id;
            // Tanitim sayfasi icin eklenen alanlar (nullable)
            if ($request->has('uzmanlik'))       $personel->uzmanlik       = $request->uzmanlik;
            if ($request->has('aciklama'))       $personel->aciklama       = $request->aciklama;
            if ($request->has('yillik_tecrube')) $personel->yillik_tecrube = $request->yillik_tecrube ?: null;
            if ($request->has('instagram'))      $personel->instagram      = $request->instagram;
            // Takvimde gorunsun (checkbox isaretli degilse $_POST'a gelmez)
            $personel->takvimde_gorunsun = $request->has('takvimde_gorunsun') ? 1 : 0;
            $personel->save();

            // Detayli (kalem bazli) prim oranlarini kaydet — sadece deger girilen kalemler tutulur
            if(\Schema::hasTable('personel_prim_oranlari')){
                $primKalemMap = [
                    'hizmet' => $request->input('hizmet_prim_kalem', []),
                    'urun'   => $request->input('urun_prim_kalem', []),
                    'paket'  => $request->input('paket_prim_kalem', []),
                ];
                foreach($primKalemMap as $tur => $kalemler){
                    if(!is_array($kalemler)) $kalemler = [];
                    // Bu turdeki mevcut kayitlari temizleyip yeniden yaz (en sade upsert)
                    PersonelPrimOrani::where('personel_id',$personel->id)->where('tur',$tur)->delete();
                    foreach($kalemler as $kalemId => $yuzde){
                        $kalemId = (int)$kalemId;
                        $yuzde = (float)str_replace(',', '.', $yuzde);
                        if($kalemId <= 0 || $yuzde <= 0) continue; // bos/0 satir kaydedilmez
                        PersonelPrimOrani::create([
                            'personel_id' => $personel->id,
                            'salon_id'    => $personel->salon_id,
                            'tur'         => $tur,
                            'kalem_id'    => $kalemId,
                            'yuzde'       => $yuzde,
                        ]);
                    }
                }
            }

            PersonelCalismaSaatleri::where('personel_id',$personel->id)->delete();
            for($i=1;$i<=7;$i++){
                    $personelcalismasaatleri = new PersonelCalismaSaatleri();
                    $personelcalismasaatleri->haftanin_gunu = $i;
                    $personelcalismasaatleri->personel_id = $personel->id;
                    if(isset($_POST['calisiyor'.$i])){
                        $personelcalismasaatleri->calisiyor = 1;
                    }
                    else{
                        $personelcalismasaatleri->calisiyor = 0;
                    }
                     if($i==1){
                             $personelcalismasaatleri->baslangic_saati = $request->baslangicsaati1;
                             $personelcalismasaatleri->bitis_saati = $request->bitissaati1;
                        }
                         if($i==2){
                             $personelcalismasaatleri->baslangic_saati = $request->baslangicsaati2;
                             $personelcalismasaatleri->bitis_saati = $request->bitissaati2;
                        }
                         if($i==3){
                             $personelcalismasaatleri->baslangic_saati = $request->baslangicsaati3;
                             $personelcalismasaatleri->bitis_saati = $request->bitissaati3;
                        }
                         if($i==4){
                             $personelcalismasaatleri->baslangic_saati = $request->baslangicsaati4;
                             $personelcalismasaatleri->bitis_saati = $request->bitissaati4;
                        }
                         if($i==5){
                             $personelcalismasaatleri->baslangic_saati = $request->baslangicsaati5;
                             $personelcalismasaatleri->bitis_saati = $request->bitissaati5;
                        }
                         if($i==6){
                             $personelcalismasaatleri->baslangic_saati = $request->baslangicsaati6;
                             $personelcalismasaatleri->bitis_saati = $request->bitissaati6;
                        }
                         if($i==7){
                             $personelcalismasaatleri->baslangic_saati = $request->baslangicsaati7;
                             $personelcalismasaatleri->bitis_saati = $request->bitissaati7;
                        }
                        $personelcalismasaatleri->save();
            }
            PersonelMolaSaatleri::where('personel_id',$personel->id)->delete();
            for($i=1;$i<=7;$i++){
                    $personelmolasaatleri = new PersonelMolaSaatleri();
                    $personelmolasaatleri->haftanin_gunu = $i;
                    $personelmolasaatleri->personel_id = $personel->id;
                    if(isset($_POST['molavar'.$i])){
                        $personelmolasaatleri->mola_var = 1;
                    }
                    else{
                        $personelmolasaatleri->mola_var = 0;
                    }
                     if($i==1){
                             $personelmolasaatleri->baslangic_saati = $request->molabaslangicsaati1;
                             $personelmolasaatleri->bitis_saati = $request->molabitissaati1;
                        }
                         if($i==2){
                             $personelmolasaatleri->baslangic_saati = $request->molabaslangicsaati2;
                             $personelmolasaatleri->bitis_saati = $request->molabitissaati2;
                        }
                         if($i==3){
                             $personelmolasaatleri->baslangic_saati = $request->molabaslangicsaati3;
                             $personelmolasaatleri->bitis_saati = $request->molabitissaati3;
                        }
                         if($i==4){
                             $personelmolasaatleri->baslangic_saati = $request->molabaslangicsaati4;
                             $personelmolasaatleri->bitis_saati = $request->molabitissaati4;
                        }
                         if($i==5){
                             $personelmolasaatleri->baslangic_saati = $request->molabaslangicsaati5;
                             $personelmolasaatleri->bitis_saati = $request->molabitissaati5;
                        }
                         if($i==6){
                             $personelmolasaatleri->baslangic_saati = $request->molabaslangicsaati6;
                             $personelmolasaatleri->bitis_saati = $request->molabitissaati6;
                        }
                         if($i==7){
                             $personelmolasaatleri->baslangic_saati = $request->molabaslangicsaati7;
                             $personelmolasaatleri->bitis_saati = $request->molabitissaati7;
                        }
                        $personelmolasaatleri->save();
            }
            if($yeniekleme){
                    $mesajlar = array();
                    array_push($mesajlar, array("to"=>$yetkili->gsm1,"message"=> "Sayın ".$yetkili->name.". Randevu sistemi şifreniz : ".$olusturulansifre));
                    self::sms_gonder_bildirimli($request,$mesajlar,false,1,false);
            }
            $yetkili->roles()->detach();
            DB::insert('insert into model_has_roles (role_id, model_type,model_id,salon_id) values ('.$rol_id.', "App\\\IsletmeYetkilileri",'.$yetkili->id.','.$request->sube.')');
            $result = 'Personel başarıyla kaydedildi';
            $swaltitle = 'Başarılı';
            $swalstat = 'success';

            // Audit
            SalonAudit::log($request->sube, $yeniekleme ? 'personel_ekle' : 'personel_guncelle', 'personel', $personel->id,
                $personel->personel_adi,
                $yeniekleme ? 'Yeni personel eklendi' : 'Personel bilgileri güncellendi',
                ['rol'=>$sistemyetkisi, 'unvan'=>$request->unvan]);
        }
        return array(
            'swaltitle' => $swaltitle,
            'swalstat'=>$swalstat,
            'sonuc'=>$result,
            'personeller'=>self::personel_liste_getir($request)
        );
    }
    public function personel_liste_getir(Request $request)
    {
        $isletmeId = self::mevcutsube($request);
        // Aktifler once, pasifler en altta. Tie-breaker olarak id ASC kullan ki
        // takvim_sirasi'da olusabilecek tekrar/bosluklar deterministik cozulsun.
        // Arsivli (silinmis) personeller listede gozukmesin.
        $personeller = Personeller::where('salon_id',$isletmeId)
            ->where(function($q){ $q->where('arsivli',false)->orWhereNull('arsivli'); })
            ->orderByDesc('aktif')
            ->orderBy('takvim_sirasi','asc')
            ->orderBy('id','asc')
            ->get();

        // Self-heal: takvim_sirasi degerlerini 0..n-1 olarak yeniden numaralandir.
        // Boylece kalip kalmis duplicate veya bosluklar bu cagri ile temizlenir.
        foreach($personeller as $i => $p){
            if((int)$p->takvim_sirasi !== $i){
                Personeller::where('id',$p->id)->update(['takvim_sirasi'=>$i]);
                $p->takvim_sirasi = $i;
            }
        }

        $aktif_count = $personeller->where('aktif',1)->count();

        // Performans: yetkili ve rol bilgilerini tek sorguda cek (N+1 kaldirildi)
        $yetkili_idleri = $personeller->pluck('yetkili_id')->filter()->unique()->values()->all();
        $yetkililer_map = [];
        $roller_map = [];
        if(!empty($yetkili_idleri)){
            $yetkililer_map = IsletmeYetkilileri::whereIn('id',$yetkili_idleri)->get()->keyBy('id');
            $roller_rows = DB::table('roles')
                ->join('model_has_roles','model_has_roles.role_id','=','roles.id')
                ->whereIn('model_has_roles.model_id',$yetkili_idleri)
                ->where('model_has_roles.salon_id',$isletmeId)
                ->select('model_has_roles.model_id','roles.name')
                ->get();
            foreach($roller_rows as $r){ $roller_map[$r->model_id] = $r->name; }
        }

        $formatted = $personeller->map(function($personel, $index) use($request,$personeller,$isletmeId,$yetkililer_map,$roller_map,$aktif_count){
            $isActive = (bool)$personel->aktif;
            // Siralama butonlari yalniz aktif personeller arasinda anlam tasir
            $isFirst  = $isActive && ($index === 0);
            $isLast   = $isActive && ($index === $aktif_count - 1);
            $isMiddle = $isActive && !$isFirst && !$isLast;
            $yetkili = isset($yetkililer_map[$personel->yetkili_id]) ? $yetkililer_map[$personel->yetkili_id] : null;
            $personel_adi = $yetkili ? $yetkili->name : $personel->personel_adi;
            $telefon = $yetkili ? $yetkili->gsm1 : '';
            $hesapturu = '';
            if($yetkili)
                $hesapturu = $roller_map[$yetkili->id] ?? '';
            $durum = $personel->aktif ? '<button class="btn btn-success">Aktif</button>' : '<button class="btn btn-danger">Pasif</button>';
            $takvimdeGor = (bool)$personel->takvimde_gorunsun;
            $takvimToggle = '<button type="button" class="pyo-takvim-toggle '.($takvimdeGor?'is-on':'is-off').'" name="personel_takvim_toggle" data-value="'.$personel->id.'" data-state="'.($takvimdeGor?1:0).'" title="'.($takvimdeGor?'Takvimde gizle':'Takvimde göster').'">'
                .'<i class="fa '.($takvimdeGor?'fa-eye':'fa-eye-slash').'"></i> '
