    public function randevuguncelle(Request $request)
    {
        if($r = self::yetkiYoksa403($request, 'randevu.duzenle_iptal')) return $r;
        $randevu_tarihleri = array();
        array_push($randevu_tarihleri, $request->tarih);
        $cakisma_varmi = '';
        
        if (!isset($request->cakisanrandevuekle)) {
            $cakisma_varmi = self::cakisan_randevu_kontrol($request, $randevu_tarihleri);
        }
        
        if ($cakisma_varmi != '' && !isset($request->cakisanrandevuekle)) {
            return array('cakismavar' => $cakisma_varmi);
        } else {
            if ($cakisma_varmi == '' || $request->cakisanrandevuekle == 1) {
                // Start database transaction
                DB::beginTransaction();
                
                try {
                    // Mevcut randevuyu kontrol et
                    $mevcutRandevu = Randevular::where('id', $request->randevu_id)->first();
                    
                    if (!$mevcutRandevu) {
                        throw new \Exception("Randevu bulunamadı!");
                    }
                    
                    // ESKİ randevu bilgilerini kaydet (karşılaştırma için)
                    $eskiRandevuBilgileri = [
                        'tarih' => $mevcutRandevu->tarih,
                        'saat' => $mevcutRandevu->saat,
                        'personeller' => [],
                        'cihazlar' => [],
                        'odalari' => [],
                        'hizmetler' => []
                    ];
                    
                    // Eski randevu hizmet bilgilerini topla
                    $eskiHizmetler = RandevuHizmetler::where('randevu_id', $mevcutRandevu->id)->get();
                    foreach ($eskiHizmetler as $eskiHizmet) {
                        $eskiRandevuBilgileri['personeller'][] = $eskiHizmet->personel_id;
                        $eskiRandevuBilgileri['cihazlar'][] = $eskiHizmet->cihaz_id;
                        $eskiRandevuBilgileri['odalari'][] = $eskiHizmet->oda_id;
                        $eskiRandevuBilgileri['hizmetler'][] = $eskiHizmet->hizmet_id;
                    }
                    
                    // YENİ randevu bilgilerini topla
                    $yeniRandevuBilgileri = [
                        'tarih' => $request->tarih,
                        'saat' => $request->saat,
                        'personeller' => $request->randevupersonelleriyeni ?? [],
                        'cihazlar' => $request->randevucihazlariyeni ?? [],
                        'odalari' => $request->randevuodalariyeni ?? [],
                        'hizmetler' => $request->randevuhizmetleriyeni ?? []
                    ];
                    
                    // Tarih ve saat değişikliği kontrolü (SADECE bu ikisi için)
                    $tarihDegisti = false;
                    $saatDegisti = false;
                    $tarihSaatDegisti = false;
                    
                    // Tarih formatlarını karşılaştırmak için normalizasyon
                    $eskiTarihNormalized = date('Y-m-d', strtotime($eskiRandevuBilgileri['tarih']));
                    $yeniTarihNormalized = date('Y-m-d', strtotime($yeniRandevuBilgileri['tarih']));
                    
                    // SADECE tarih değişimi kontrolü
                    if ($eskiTarihNormalized != $yeniTarihNormalized) {
                        $tarihDegisti = true;
                    }
                    
                    // SADECE saat değişimi kontrolü
                    // NOT: DB TIME alani "HH:MM:SS" donerken form "HH:MM" gonderir;
                    // direkt string karsilastirmasi false-positive verip her guncellemede
                    // SMS/WhatsApp tetikliyordu. Iki tarafi da "HH:MM" formatina indirgiyoruz.
                    $_normalizeSaat = function($v){
                        $s = trim((string)$v);
                        if ($s === '') return '';
                        $ts = strtotime($s);
                        return $ts ? date('H:i', $ts) : substr($s, 0, 5);
                    };
                    $eskiSaatNorm = $_normalizeSaat($eskiRandevuBilgileri['saat']);
                    $yeniSaatNorm = $_normalizeSaat($yeniRandevuBilgileri['saat']);
                    if ($eskiSaatNorm !== $yeniSaatNorm) {
                        $saatDegisti = true;
                    }
                    
                    // Tarih VEYA saat değiştiyse
                    if ($tarihDegisti || $saatDegisti) {
                        $tarihSaatDegisti = true;
                    }
                    
                    // Personel, cihaz, oda veya hizmet değişikliği kontrolü
                    $personelDegisti = false;
                    $cihazDegisti = false;
                    $odaDegisti = false;
                    $hizmetDegisti = false;
                    
                    // Personel değişimi kontrolü
                    $eskiPersonellerSorted = sort($eskiRandevuBilgileri['personeller']);
                    $yeniPersonellerSorted = sort($yeniRandevuBilgileri['personeller']);
                    if ($eskiPersonellerSorted != $yeniPersonellerSorted) {
                        $personelDegisti = true;
                    }
                    
                    // Cihaz değişimi kontrolü
                    $eskiCihazlarSorted = sort($eskiRandevuBilgileri['cihazlar']);
                    $yeniCihazlarSorted = sort($yeniRandevuBilgileri['cihazlar']);
                    if ($eskiCihazlarSorted != $yeniCihazlarSorted) {
                        $cihazDegisti = true;
                    }
                    
                    // Oda değişimi kontrolü
                    $eskiOdalarSorted = sort($eskiRandevuBilgileri['odalari']);
                    $yeniOdalarSorted = sort($yeniRandevuBilgileri['odalari']);
                    if ($eskiOdalarSorted != $yeniOdalarSorted) {
                        $odaDegisti = true;
                    }
                    
                    // Hizmet değişimi kontrolü
                    $eskiHizmetlerSorted = sort($eskiRandevuBilgileri['hizmetler']);
                    $yeniHizmetlerSorted = sort($yeniRandevuBilgileri['hizmetler']);
                    if ($eskiHizmetlerSorted != $yeniHizmetlerSorted) {
                        $hizmetDegisti = true;
                    }
                    
                    $seansVar = AdisyonPaketSeanslar::where('randevu_id', $request->randevu_id)
                        ->where('hizmet_id', $request->randevuhizmetleriyeni[0])
                        ->first();
                    
                    $hizmetAdi = "";
                    $randevu = $mevcutRandevu; // Mevcut randevuyu kullan

                    $salonId = $randevu->salon_id;
                    $userId = $randevu->user_id;

                    // KALDIRILDI: ($seansVar var ise $randevu = new Randevular()) blogu.
                    // Bug: paketli/seansli randevu duzenlenince YENI randevu olusturuyor,
                    // eskisi degisik halde kaliyor, eski RandevuHizmetler kayitlari
                    // 'silinmis gibi' gozukup duzenli liste sayfasinda bos satirlar ciktiyordu.
                    // Duzenleme her zaman mevcut randevuyu update etmeli.
                    if ($seansVar) {
                        $hizmetAdi = $seansVar->hizmet->hizmet_adi ?? '';
                    }
                    
                    // Randevu bilgilerini güncelle
                    $randevu->salon = 1;
                    $randevu->hatirlatma_aramasi_yapildi = null;
                    $randevu->hatirlatma_gorevi_iptal = null;
                    $randevu->user_id = $userId;
                    $randevu->hatirlatma_ulasilamadi = null;
                    $randevu->salon_id = $salonId;
                    $randevu->tekrar_arama_tarih_saat = "0000-00-00 00:00:00";
                    $randevu->hatirlatma_gorevi_iptal = null;
                    $randevu->arama_saat = null;
                    $randevu->tekrar_arandi = null;
                    $randevu->tekrar_aranacak = null;
                    
                    $eskitarihsaat = date('d.m.y H:i', strtotime($eskiRandevuBilgileri['tarih'] . ' ' . $eskiRandevuBilgileri['saat']));
                    $randevu->tarih = $yeniRandevuBilgileri['tarih'];
                    $randevu->saat = $yeniRandevuBilgileri['saat'];
                    
                    if (isset($request->notlar)) {
                        $randevu->notlar = $request->notlar;
                    }
                    
                    if (isset($request->personel_notu)) {
                        $randevu->personel_notu = $request->personel_notu;
                    }
                    
                    $randevu->sms_hatirlatma = $request->sms_hatirlatma;
                    $hizmet_sureleri_okunan = array();
                    $randevu->save();
                    
                    $eskiSeansRandevusu = "";
                    if ($seansVar) {
                        $eskiSeansRandevusu = $seansVar->randevu_id;
                    }
                    
                    if ($seansVar) {
                        $seansVar->seans_tarih = $yeniRandevuBilgileri['tarih'];
                        $seansVar->seans_saat = $yeniRandevuBilgileri['saat'];
                        $seansVar->randevu_id = $randevu->id;
                        $seansVar->personel_id = $yeniRandevuBilgileri['personeller'][0];
                        $seansVar->cihaz_id = $yeniRandevuBilgileri['cihazlar'][0];
                        $seansVar->oda_id = $yeniRandevuBilgileri['odalari'][0];
                        $seansVar->save();
                    }
                    
                    $totalsure = 0;
                    $yenisaatbaslangic = $yeniRandevuBilgileri['saat'];

                    // Eski hizmet satirlarini HER ZAMAN sil (eskiden seansVar varsa
                    // silmiyordu; bu, eski satirlarin yeni durumla atil kalmasina ve
                    // listede 'bos hizmetler' gozukmesine yol aciyordu).
                    RandevuHizmetler::where('randevu_id', $randevu->id)->delete();

                    // EKSIK SEANS KAYDI INSERT'I icin: bu randevudaki mevcut APS kayitlarini
                    // hizmet_id bazinda grupla. Asagidaki foreach'ta her satir icin havuzdan
                    // bir kayit tuketiriz; havuz bitince paket adisyonundan yeni APS insert ederiz.
                    $_mevcutSeanslar = AdisyonPaketSeanslar::where('randevu_id', $randevu->id)
                        ->get()
                        ->groupBy('hizmet_id');
                    $_tuketilenSeansSayisi = []; // hizmet_id => count

                    \Log::info('[randevuguncelle/RAW]', [
                        'randevu_id'        => $request->randevu_id,
                        'tarih'             => $request->tarih,
                        'saat'              => $request->saat,
                        'hizmetler_raw'     => $request->randevuhizmetleriyeni,
                        'hizmetler_yeni'    => $yeniRandevuBilgileri['hizmetler'],
                        'personeller_raw'   => $request->randevupersonelleriyeni,
                        'hizmet_suresi_raw' => $request->hizmet_suresi,
                        'hizmet_fiyat_raw'  => $request->hizmet_fiyat,
                        'birlestir_keys'    => array_keys(array_filter($request->all(), function($k){ return strpos($k,'birlestir')===0; }, ARRAY_FILTER_USE_KEY)),
                    ]);

                    foreach ($yeniRandevuBilgileri['hizmetler'] as $key => $value) {
                        \Log::info('[randevuguncelle/LOOP]', [
                            'key'   => $key,
                            'value (hizmet_id)' => $value,
                            'personel' => $yeniRandevuBilgileri['personeller'][$key] ?? null,
                            'sure_used' => $request->hizmet_suresi[$key] ?? null,
                            'fiyat_used' => $request->hizmet_fiyat[$key] ?? null,
                        ]);
                        array_push($hizmet_sureleri_okunan, $request->hizmet_suresi[$key]);

                        // Eski RandevuHizmetler kayitlari yukarida silindi -> her satir TEMIZ yeni.
                        // (Eskiden $seansVar varsa AYNI satiri fetch edip her iterde overrride
                        // edip kaydediyordu -> 2 hizmet vermek istesen son iterin verisi kalip
                        // ilk hizmet kaybolup gidiyordu.)
                        $yenirandevuhizmetpersonel = new RandevuHizmetler();
                        
                        $yenirandevuhizmetpersonel->randevu_id = $randevu->id;
                        $yenirandevuhizmetpersonel->hizmet_id = $value;
                        $yenirandevuhizmetpersonel->cihaz_id = $yeniRandevuBilgileri['cihazlar'][$key];
                        $yenirandevuhizmetpersonel->personel_id = $yeniRandevuBilgileri['personeller'][$key];
                        // Oda: manuel seçim varsa onu kullan, yoksa hizmete uygun ilk müsait
                        $duzenleOdaId = $yeniRandevuBilgileri['odalari'][$key] ?? null;
                        if (!$duzenleOdaId) {
                            $_baslangic = ($key == 0) ? $yeniRandevuBilgileri['saat'] : $yenisaatbaslangic;
                            $_bitis = date("H:i", strtotime('+' . (int)$request->hizmet_suresi[$key] . ' minutes', strtotime($_baslangic)));
                            $duzenleOdaId = \App\Services\OdaAtamaServisi::uygunOdaSec(
                                (int) $randevu->salon_id,
                                (int) $value,
                                $yeniRandevuBilgileri['tarih'],
                                $_baslangic,
                                $_bitis
                            );
                        }
                        $yenirandevuhizmetpersonel->oda_id = $duzenleOdaId;
                        $yenirandevuhizmetpersonel->sure_dk = $request->hizmet_suresi[$key];
                        $yenirandevuhizmetpersonel->fiyat = self::parseFiyat($request->hizmet_fiyat[$key]);
                        // Salonun girdigi dusum miktari ("Geldi" popup'unda default olur)
                        if (isset($request->hizmet_miktari[$key]) && $request->hizmet_miktari[$key] !== '') {
                            $yenirandevuhizmetpersonel->dusum_miktari = max(1, (int) $request->hizmet_miktari[$key]);
                        }

                        $birsonraki = $key + 1;

                        if ($key == 0) {
                            $yenirandevuhizmetpersonel->saat = $yeniRandevuBilgileri['saat'];
                            $yenirandevuhizmetpersonel->saat_bitis = date("H:i", strtotime('+' . $request->hizmet_suresi[$key] . ' minutes', strtotime($yeniRandevuBilgileri['saat'])));

                            if (!isset($request->{"birlestir{$birsonraki}"})) {
                                $yenisaatbaslangic = date("H:i", strtotime('+' . $request->hizmet_suresi[$key] . ' minutes', strtotime($yeniRandevuBilgileri['saat'])));
                            }
                        } else {
                            $yenirandevuhizmetpersonel->saat = $yenisaatbaslangic;
                            $yenirandevuhizmetpersonel->saat_bitis = date("H:i", strtotime('+' . $request->hizmet_suresi[$key] . ' minutes', strtotime($yenisaatbaslangic)));

                            if (!isset($request->{"birlestir{$birsonraki}"})) {
                                $yenisaatbaslangic = date("H:i", strtotime('+' . $request->hizmet_suresi[$key] . ' minutes', strtotime($yenisaatbaslangic)));
                            }
                        }

                        $yenirandevuhizmetpersonel->save();

                        // EKSIK ADISYON_PAKET_SEANSLAR INSERT'I
                        // Bu hizmet satiri icin halihazirda APS kaydi var mi? Havuzdan tuket.
                        // Yoksa: musterinin paket/hizmet adisyonundan kaynak bulup yeni APS olustur.
                        // (yenirandevuekle akisinin birebir karsiligi — DRY icin gelecekte service'e
                        // tasinabilir.)
                        try {
                            $_hzmtId = (int) $value;
                            $_tuk = $_tuketilenSeansSayisi[$_hzmtId] ?? 0;
                            $_pool = $_mevcutSeanslar->get($_hzmtId) ?: collect();
                            $_zatenVar = $_pool->count() > $_tuk;
                            $_tuketilenSeansSayisi[$_hzmtId] = $_tuk + 1;

                            // Mevcut APS varsa: yeni saat/personel/cihaz/oda ile guncelle.
                            if ($_zatenVar) {
                                $_apsKayit = $_pool->values()[$_tuk] ?? null;
                                if ($_apsKayit) {
                                    $_aps = AdisyonPaketSeanslar::find($_apsKayit->id);
                                    if ($_aps) {
                                        $_aps->seans_tarih = $yeniRandevuBilgileri['tarih'];
                                        $_aps->seans_saat  = $yenirandevuhizmetpersonel->saat;
                                        $_aps->personel_id = $yenirandevuhizmetpersonel->personel_id;
                                        $_aps->cihaz_id    = $yenirandevuhizmetpersonel->cihaz_id;
                                        $_aps->oda_id      = $yenirandevuhizmetpersonel->oda_id;
                                        $_aps->save();
                                    }
                                }
                            }

                            if (!$_zatenVar) {
                                // Aday adisyon_hizmet: sadece seans_sayisi > 0 olanlar (gercek paket satisi).
                                // seans_sayisi NULL/0 olanlar tek seferlik hizmet satisi -> APS'ye baglanmamali;
                                // ornek 163360 musteri, hizmet 3805: iki adisyon_hizmet var (biri NULL=tek satis,
                                // digeri seans=10=paket). Eski kod NULL olana APS yaziyordu, takvim etiketi
                                // gostermiyordu (etiket seans_sayisi>0 sartiyor).
                                $_hizmetAdaylar = DB::table('adisyon_hizmetler')
                                    ->join('adisyonlar', 'adisyon_hizmetler.adisyon_id', '=', 'adisyonlar.id')
                                    ->where('adisyon_hizmetler.hizmet_id', $_hzmtId)
                                    ->where('adisyonlar.user_id', $userId)
                                    ->where('adisyonlar.salon_id', $salonId)
                                    ->where('adisyon_hizmetler.seans_sayisi', '>', 0)
                                    ->where(function($q){
                                        $q->whereNull('adisyon_hizmetler.otomatik_randevu_olusturuldu')
                                          ->orWhere('adisyon_hizmetler.otomatik_randevu_olusturuldu', '!=', 1);
                                    })
                                    ->orderBy('adisyonlar.tarih', 'asc')
                                    ->select('adisyon_hizmetler.id', 'adisyon_hizmetler.seans_sayisi',
                                             'adisyon_hizmetler.kullanilan_seans', 'adisyon_hizmetler.kullanilmayan_seans',
                                             'adisyonlar.tarih as adisyon_tarih')
                                    ->get();
                                $_hizmetSecili = null;
                                foreach ($_hizmetAdaylar as $__h) {
                                    $__kul = (int) DB::table('adisyon_paket_seanslar')
                                        ->where('adisyon_hizmet_id', $__h->id)
                                        ->count();
                                    if ($__kul < (int) $__h->seans_sayisi) { $_hizmetSecili = $__h; break; }
                                }

                                // Aday adisyon_paket: sadece seans_sayisi > 0 olanlar, ve bu hizmet bolgesi kalanli olanlar
                                $_paketAdaylar = DB::table('adisyon_paketler')
                                    ->join('adisyonlar', 'adisyon_paketler.adisyon_id', '=', 'adisyonlar.id')
                                    ->join('paket_hizmetler', 'paket_hizmetler.paket_id', '=', 'adisyon_paketler.paket_id')
                                    ->where('paket_hizmetler.hizmet_id', $_hzmtId)
                                    ->where('adisyonlar.user_id', $userId)
                                    ->where('adisyonlar.salon_id', $salonId)
                                    ->where('adisyon_paketler.seans_sayisi', '>', 0)
                                    ->where(function($q){
                                        $q->whereNull('adisyon_paketler.otomatik_randevu_olusturuldu')
                                          ->orWhere('adisyon_paketler.otomatik_randevu_olusturuldu', '!=', 1);
                                    })
                                    ->orderBy('adisyonlar.tarih', 'asc')
                                    ->select('adisyon_paketler.id', 'adisyon_paketler.seans_sayisi',
                                             'adisyon_paketler.kullanilan_seans', 'adisyon_paketler.kullanilmayan_seans',
                                             'adisyonlar.tarih as adisyon_tarih')
                                    ->distinct()
                                    ->get();
                                $_paketSecili = null;
                                foreach ($_paketAdaylar as $__p) {
                                    $__kul = (int) DB::table('adisyon_paket_seanslar')
                                        ->where('adisyon_paket_id', $__p->id)
                                        ->where('hizmet_id', $_hzmtId)
                                        ->count();
                                    if ($__kul < (int) $__p->seans_sayisi) { $_paketSecili = $__p; break; }
                                }

                                // Tarih karsilastirma: ikisi de varsa eski tarihliyi sec
                                $_hizmetIsle = false; $_paketIsle = false;
                                if ($_hizmetSecili && $_paketSecili) {
                                    if (date('Y-m-d', strtotime($_hizmetSecili->adisyon_tarih)) < date('Y-m-d', strtotime($_paketSecili->adisyon_tarih))) {
                                        $_hizmetIsle = true;
                                    } else {
                                        $_paketIsle = true;
                                    }
                                } else {
                                    if ($_hizmetSecili) $_hizmetIsle = true;
                                    if ($_paketSecili)  $_paketIsle  = true;
                                }

                                if ($_hizmetIsle) {
                                    $_seansKaydi = new AdisyonPaketSeanslar();
                                    $_seansKaydi->seans_tarih = $yeniRandevuBilgileri['tarih'];
                                    $_seansKaydi->seans_saat  = $yenirandevuhizmetpersonel->saat;
                                    $_seansKaydi->personel_id = $yenirandevuhizmetpersonel->personel_id;
                                    $_seansKaydi->cihaz_id    = $yenirandevuhizmetpersonel->cihaz_id;
                                    $_seansKaydi->oda_id      = $yenirandevuhizmetpersonel->oda_id;
                                    $_seansKaydi->randevu_id  = $randevu->id;
                                    $_seansKaydi->seans_no    = ((int)($_hizmetSecili->kullanilan_seans ?? 0)) + ((int)($_hizmetSecili->kullanilmayan_seans ?? 0)) + 1;
                                    $_seansKaydi->adisyon_hizmet_id = $_hizmetSecili->id;
                                    $_seansKaydi->hizmet_id   = $_hzmtId;
                                    $_seansKaydi->save();
                                } elseif ($_paketIsle) {
                                    $_seansKaydi = new AdisyonPaketSeanslar();
                                    $_seansKaydi->seans_tarih = $yeniRandevuBilgileri['tarih'];
                                    $_seansKaydi->seans_saat  = $yenirandevuhizmetpersonel->saat;
                                    $_seansKaydi->personel_id = $yenirandevuhizmetpersonel->personel_id;
                                    $_seansKaydi->cihaz_id    = $yenirandevuhizmetpersonel->cihaz_id;
                                    $_seansKaydi->oda_id      = $yenirandevuhizmetpersonel->oda_id;
                                    $_seansKaydi->randevu_id  = $randevu->id;
                                    $_seansKaydi->seans_no    = ((int)($_paketSecili->kullanilan_seans ?? 0)) + ((int)($_paketSecili->kullanilmayan_seans ?? 0)) + 1;
                                    $_seansKaydi->adisyon_paket_id = $_paketSecili->id;
                                    $_seansKaydi->hizmet_id   = $_hzmtId;
                                    $_seansKaydi->save();
                                }
                            }
                        } catch (\Throwable $e) {
                            \Log::warning('randevuguncelle APS insert hata: '.$e->getMessage(), [
                                'randevu_id' => $randevu->id ?? null,
                                'hizmet_id'  => $value,
                                'key'        => $key,
                            ]);
                        }

                        if (isset($request->{"randevuyardimcipersonelleriyeni_{$key}"})) {
                            foreach ($request->{"randevuyardimcipersonelleriyeni_{$key}"} as $yardimci_personel_id) {
                                if ($yardimci_personel_id != '') {
                                    $yardimci_personel = new RandevuHizmetler();
                                    $yardimci_personel->randevu_id = $randevu->id;
                                    $yardimci_personel->hizmet_id = $value;
                                    $yardimci_personel->cihaz_id = $yeniRandevuBilgileri['cihazlar'][$key];
                                    $yardimci_personel->personel_id = $yardimci_personel_id;
                                    $yardimci_personel->oda_id = $duzenleOdaId;
                                    $yardimci_personel->sure_dk = $request->hizmet_suresi[$key];
                                    $yardimci_personel->fiyat = self::parseFiyat($request->hizmet_fiyat[$key]);
                                    $yardimci_personel->saat = $yenirandevuhizmetpersonel->saat;
                                    $yardimci_personel->saat_bitis = $yenirandevuhizmetpersonel->saat_bitis;
                                    $yardimci_personel->yardimci_personel = true;
                                    $yardimci_personel->save();
                                }
                            }
                        }
                    }
                    
                    // SMS gönderme işlemi - SADECE TARİH VEYA SAAT DEĞİŞTİĞİNDE
                    $mesajlar = array();
                    
                    // DEBUG: Hangi değişikliklerin olduğunu logla (opsiyonel)
                    /*
                    \Log::info('Randevu Güncelleme Değişiklikleri:', [
                        'tarihDegisti' => $tarihDegisti,
                        'saatDegisti' => $saatDegisti,
                        'tarihSaatDegisti' => $tarihSaatDegisti,
                        'personelDegisti' => $personelDegisti,
                        'cihazDegisti' => $cihazDegisti,
                        'odaDegisti' => $odaDegisti,
                        'hizmetDegisti' => $hizmetDegisti,
                        'eskiTarih' => $eskiRandevuBilgileri['tarih'],
                        'yeniTarih' => $yeniRandevuBilgileri['tarih'],
                        'eskiSaat' => $eskiRandevuBilgileri['saat'],
                        'yeniSaat' => $yeniRandevuBilgileri['saat'],
                        'eskiPersoneller' => $eskiRandevuBilgileri['personeller'],
                        'yeniPersoneller' => $yeniRandevuBilgileri['personeller']
                    ]);
                    */
                    
                    if ($tarihSaatDegisti) {
                        // Müşteriye gönder (WhatsApp-first + SMS fallback)
                        $musteriMesaji = $randevu->salonlar->salon_adi . " tarafından " . $eskitarihsaat . " " . ($seansVar ? $hizmetAdi : "") . " randevunuz " . date('d.m.Y', strtotime($randevu->tarih)) . '-' . $randevu->saat . ' olarak güncellenmiştir. Detaylı bilgi için bize ulaşın. 0' . $randevu->salonlar->telefon_1;
                        $this->smsVeyaWhatsappGonder($randevu->salonlar, $randevu->users->cep_telefon, $musteriMesaji, 14, 'musteri', $randevu->id, $randevu->user_id, $mesajlar);
                        // Musteri push (SMS metniyle birebir)
                        if($randevu->user_id){
                            try {
                                NotificationService::toCustomer((int)$randevu->user_id, (int)$randevu->salon_id)
                                    ->type(NotificationTypes::APPOINTMENT_TIME_CHANGED)
                                    ->title('Randevunuz Güncellendi')
                                    ->body($musteriMesaji)
                                    ->randevu((int)$randevu->id)
                                    ->deepLink('appointment_detail', ['randevu_id' => $randevu->id])
                                    ->send();
                            } catch (\Throwable $e) { \Log::warning('musteri randevu guncelleme push: '.$e->getMessage()); }
                        }

                        // Personellere gönder (WhatsApp-first + SMS fallback)
                        foreach ($randevu->hizmetler as $hizmet) {
                            $yetkiliid = Personeller::where('id', $hizmet->personel_id)->value('yetkili_id');
                            $personelTel = IsletmeYetkilileri::where('id', $yetkiliid)->value('gsm1');
                            $personelMesaji = $randevu->users->name . " isimli müşterinin " . $hizmet->hizmetler->hizmet_adi . " randevusu " . date('d.m.Y', strtotime($randevu->tarih)) . " - " . date('H:i', strtotime($hizmet->saat)) . " olarak " . Auth::guard('isletmeyonetim')->user()->name . " tarafından güncellenmiştir.";
                            $this->smsVeyaWhatsappGonder($randevu->salonlar, $personelTel, $personelMesaji, 14, 'personel', $randevu->id, null, $mesajlar);
                        }
                    }
                    
                    // Bildirim ekleme (SMS'ten bağımsız, her zaman yapılır)
                    foreach ($randevu->hizmetler as $hizmet) {
                        $mesaj = $randevu->users->name . " isimli müşterinin " . $hizmet->hizmetler->hizmet_adi . " randevusu " . date('d.m.Y', strtotime($randevu->tarih)) . " - " . date('H:i', strtotime($hizmet->saat)) . " olarak " . Auth::guard('isletmeyonetim')->user()->name . " tarafından güncellenmiştir.";
                        
                        self::bildirimekle($request, $randevu->salon_id, $mesaj, "#", $hizmet->personel_id, null, Auth::guard('isletmeyonetim')->user()->profil_resim, $randevu->id);
                        if($hizmet->personel_id){
                            try {
                                NotificationService::toStaff((int)$hizmet->personel_id, (int)$randevu->salon_id)
                                    ->type(NotificationTypes::APPOINTMENT_TIME_CHANGED)
                                    ->title('Randevu Güncellendi')
                                    ->body($mesaj)
                                    ->randevu((int)$randevu->id)
                                    ->deepLink('appointment_detail', ['randevu_id' => $randevu->id])
                                    ->send();
                            } catch (\Throwable $e) { \Log::warning('randevu guncelleme push: '.$e->getMessage()); }
                        }
                    }
                    
                    // Eğer tarih/saat değiştiyse ve gönderilecek mesaj varsa SMS gönder
                    if ($tarihSaatDegisti && count($mesajlar) > 0) {
                        self::sms_gonder_bildirimli($request, $mesajlar, false, 1, false);
                    }
                    
                    $butonlar = '';
                    $randevuguncellendi = array();
                    
                    if (!isset($request->takvim_sayfasi)) {
                        $butonlar .= "<a class='btn btn-primary btn-lg btn-block' href='/isletmeyonetim/randevular?sube=" . $randevu->salon_id . "'>Takvime Git</a>" .
                            "<a class='btn btn-primary btn-lg btn-block' href='/isletmeyonetim/randevular-liste?sube=" . $randevu->salon_id . "'>Randevu Listesine Git</a>";
                        $randevuguncellendi['timer'] = 30000;
                    } else {
                        $randevuguncellendi['timer'] = 3000;
                    }
                    
                    $randevuguncellendi['success'] = '<p>Randevu bilgileri başarıyla güncellendi.</p>' . $butonlar;

                    // Commit transaction if everything is successful
                    DB::commit();

                    // Audit
                    $_audit_musteriAdi = optional($mevcutRandevu->users)->name ?? 'Müşteri #'.$mevcutRandevu->user_id;
                    $_audit_label = $_audit_musteriAdi.' — '.date('d.m.Y',strtotime($request->tarih)).' '.substr($request->saat,0,5);
                    SalonAudit::log($mevcutRandevu->salon_id, 'randevu_guncelle', 'randevu', $mevcutRandevu->id, $_audit_label,
                        'Randevu güncellendi',
                        ['eski' => $eskiRandevuBilgileri, 'yeni' => $yeniRandevuBilgileri]);

                    return $randevuguncellendi;
                } catch (\Exception $e) {
                    // Rollback transaction on error
                    DB::rollBack();
                    
                    return [
                        'error' => 'Randevu güncellenirken bir hata oluştu: ' . $e->getMessage(),
                        'timer' => 5000
                    ];
                }
            }
        }
    }
    public function randevu_resize_drop(Request $request)
    {
        if($r = self::yetkiYoksa403($request, 'randevu.duzenle_iptal')) return $r;

        $randevu_eski = Randevular::where('id',$request->randevu_id)->first();
        $baslangic = explode('T',$request->start);
        $bitis = explode('T',$request->end);
        $hizmet = '';
        $randevu = '';

        $hizmetEski = RandevuHizmetler::where('id',$request->id)->first();
        $seans = null;
        if($hizmetEski){
            $seans = AdisyonPaketSeanslar::where('randevu_id',$randevu_eski->id)
                ->where('hizmet_id',$hizmetEski->hizmet_id)
                ->first();
        }

        $randevu = new Randevular();
        $randevu->user_id = $randevu_eski->user_id;
        $randevu->salon_id = $randevu_eski->salon_id;
        $randevu->tarih = $baslangic[0];
        $randevu->saat = $baslangic[1];
        $randevu->durum = $randevu_eski->durum;
        $randevu->salon = true;
        $randevu->sms_hatirlatma = $randevu_eski->sms_hatirlatma;
        $randevu->notlar = $randevu_eski->notlar;

        $randevu->personel_notu = $randevu_eski->personel_notu;
        $randevu->olusturan_personel_id = Auth::guard('isletmeyonetim')->user()->id;
        $randevu->save();
        $hizmet = RandevuHizmetler::where('id',$request->id)->first();
        $eskitarih = $randevu_eski->tarih;
        $eskisaat = $hizmet->saat;
        $hizmet->randevu_id = $randevu->id;
        if($request->personel_id!=''){
            $hizmet->personel_id = $request->personel_id;
            if(Odalar::where('personel_id',$request->personelid)->first())
                $hizmet->oda_id = Odalar::where('personel_id',$request->personel_id)->value('id');
        }
        if($request->cihaz_id !='')
            $hizmet->cihaz_id = $request->cihaz_id;
        if($request->oda_id !=''){
            $hizmet->oda_id = $request->oda_id;
            if(Odalar::where('id',$request->oda_id)->value('personel_id')!== null)
                $hizmet->personel_id = Odalar::where('id',$request->oda_id)->value('personel_id');
        }
        if($request->yeni_hizmet_id != '' && !$seans)
            $hizmet->hizmet_id = $request->yeni_hizmet_id;
        $hizmet->saat = $baslangic[1];
        $hizmet->saat_bitis = $bitis[1];
        $hizmet->save();

        // PAKET RANDEVUSU: paket randevularinda ayni randevu_id altinda birden cok
        // randevu_hizmetler satiri olur (ilkinde sure_dk>0, digerlerinde 0). Takvim
        // sorgusu (sure_dk>0) yalnizca sure'li kalemi event olarak gosterdiginden,
        // surukleme yapildiginda 0 sureli kardes kalemler eski randevuda kalip
        // paketten KOPUYOR ve seanslari da eski randevu_id'de takili kaliyordu.
        // Cozum: surulen hizmet + 0 sureli kardes kalemleri birlikte yeni randevuya
        // tasi; eski randevu_id'ye bagli tum ilgili seanslari yeni randevuya + yeni
        // tarih/saate guncelle. Diger sure_dk>0 kalemler kendi event'leri oldugundan
        // dokunulmaz.
        $tasinanServisIds = [(int)$hizmet->hizmet_id];
        $sifirSureliKardesler = RandevuHizmetler::where('randevu_id',$randevu_eski->id)
            ->where('id','!=',$hizmet->id)
            ->where(function($q){ $q->whereNull('sure_dk')->orWhere('sure_dk','<=',0); })
            ->get();
        foreach($sifirSureliKardesler as $kardes){
            $kardes->randevu_id = $randevu->id;
            $kardes->saat = $baslangic[1];
            $kardes->saat_bitis = $bitis[1];
            $kardes->save();
            $tasinanServisIds[] = (int)$kardes->hizmet_id;
        }
        $tasinanServisIds = array_values(array_unique($tasinanServisIds));

        // Tasinan kalemlere ait TUM seanslari yeni randevuya + yeni tarih/saate guncelle
        AdisyonPaketSeanslar::where('randevu_id',$randevu_eski->id)
            ->whereIn('hizmet_id',$tasinanServisIds)
            ->update([
                'randevu_id'  => $randevu->id,
                'seans_tarih' => $baslangic[0],
                'seans_saat'  => $baslangic[1],
                'personel_id' => $hizmet->personel_id,
                'cihaz_id'    => $hizmet->cihaz_id,
                'oda_id'      => $hizmet->oda_id,
            ]);
        // Saat/tarih degisti — SMS Ayarlari ayar_id=14 (Randevu Guncelleme) musteri/personel
        // toggle'ina gore WhatsApp-first (salon WA aktifse) yoksa SMS gonderilir.
        // randevuguncelle ile ayni davranis.
        $saatDegisti = ($eskitarih !== $randevu->tarih) || ($eskisaat !== $hizmet->saat);
        if ($saatDegisti) {
            $mesajlar = [];

            // Musteri mesaji
            $musteriSmsMesaj = $randevu->salonlar->salon_adi . " için oluşturulan "
                . ($hizmet->personeller ? $hizmet->personeller->personel_adi . ' ile ' : '')
                . ($hizmet->hizmetler ? $hizmet->hizmetler->hizmet_adi . ' ' : '')
                . date('d.m.Y H:i', strtotime($eskitarih.' '.$eskisaat))
                . " tarihli randevunuz " . date('d.m.Y', strtotime($randevu->tarih)) . " - "
                . date('H:i', strtotime($hizmet->saat))
                . " olarak güncellenmiştir. Detaylı bilgi için bize ulaşın. 0" . $randevu->salonlar->telefon_1;
            $this->smsVeyaWhatsappGonder(
                $randevu->salonlar,
                optional($randevu->users)->cep_telefon,
                $musteriSmsMesaj, 14, 'musteri',
                $randevu->id, $randevu->user_id, $mesajlar
            );

            // Personel mesaji
            if ($hizmet->personel_id) {
                $yetkiliid = Personeller::where('id', $hizmet->personel_id)->value('yetkili_id');
                $personelTel = IsletmeYetkilileri::where('id', $yetkiliid)->value('gsm1');
                $personelSmsMesaj = (optional($randevu->users)->name ?? 'Musteri') . " isimli müşterinin "
                    . (optional($hizmet->hizmetler)->hizmet_adi ?? 'hizmet') . " randevusu "
                    . date('d.m.Y', strtotime($randevu->tarih)) . " - " . date('H:i', strtotime($hizmet->saat))
                    . " olarak " . Auth::guard('isletmeyonetim')->user()->name . " tarafından güncellenmiştir.";
                $this->smsVeyaWhatsappGonder(
                    $randevu->salonlar, $personelTel,
                    $personelSmsMesaj, 14, 'personel',
                    $randevu->id, null, $mesajlar
                );
            }

            if (count($mesajlar) > 0) {
                // salon_id ACIKCA gec — multi-branch kullanicida mevcutsube
                // yanlis salon (kullanicinin ilk yetkili sube'si) donerdi.
                self::sms_gonder_bildirimli($request, $mesajlar, false, 1, false, $randevu->salon_id);
            }
        }

        // Push bildirim (SMS Ayarlari'ndan bagimsiz, BildirimKimlikleri varsa her zaman gider)
        $personelMesaji = ($randevu->users ? $randevu->users->name : 'Musteri') . " isimli müşterinin "
            . ($hizmet->hizmetler ? $hizmet->hizmetler->hizmet_adi : 'hizmet') . " randevusu "
            . date('d.m.Y', strtotime($randevu->tarih)) . " - " . date('H:i', strtotime($hizmet->saat))
            . " olarak " . Auth::guard('isletmeyonetim')->user()->name . " tarafından güncellenmiştir.";

        // Panel bildirimi (DB - zil ikonunda görünür)
        if ($hizmet->personel_id) {
            self::bildirimekle($request, $randevu->salon_id, $personelMesaji, "#", $hizmet->personel_id, null, Auth::guard('isletmeyonetim')->user()->profil_resim, $randevu->id);
        }

        // Personel push
        if ($hizmet->personel_id) {
            try {
                NotificationService::toStaff((int)$hizmet->personel_id, (int)$randevu->salon_id)
                    ->type(NotificationTypes::APPOINTMENT_TIME_CHANGED)
                    ->title('Randevu Güncellendi')
                    ->body($personelMesaji)
                    ->randevu((int)$randevu->id)
                    ->deepLink('appointment_detail', ['randevu_id' => $randevu->id])
                    ->send();
            } catch (\Throwable $e) {
                \Log::warning('randevu_resize_drop personel push: '.$e->getMessage());
            }
        }

        // Musteri push
        if ($randevu->user_id) {
            $musteriMesaji = $randevu->salonlar->salon_adi . " için oluşturulan "
                . date('d.m.Y H:i', strtotime($eskitarih.' '.$eskisaat)) . " tarihli randevunuz "
                . date('d.m.Y', strtotime($randevu->tarih)) . ' - ' . date('H:i', strtotime($hizmet->saat))
                . ' olarak güncellenmiştir.';
            try {
                NotificationService::toCustomer((int)$randevu->user_id, (int)$randevu->salon_id)
                    ->type(NotificationTypes::APPOINTMENT_TIME_CHANGED)
                    ->title('Randevunuz Güncellendi')
                    ->body($musteriMesaji)
                    ->randevu((int)$randevu->id)
                    ->deepLink('appointment_detail', ['randevu_id' => $randevu->id])
                    ->send();
            } catch (\Throwable $e) {
                \Log::warning('randevu_resize_drop musteri push: '.$e->getMessage());
            }
        }

        if(RandevuHizmetler::where('randevu_id',$randevu_eski->id)->count()==0)
            $randevu_eski->delete();

        // Audit (takvimde sürükle-bırak)
        $_audit_musteriAdi = optional($randevu->users)->name ?? 'Müşteri #'.$randevu->user_id;
        $_audit_label = $_audit_musteriAdi.' — '.date('d.m.Y',strtotime($randevu->tarih)).' '.date('H:i',strtotime($hizmet->saat));
        SalonAudit::log($randevu->salon_id, 'randevu_takvim_tasi', 'randevu', $randevu->id, $_audit_label,
            'Randevu takvimde sürüklenip taşındı',
            ['eski_tarih'=>$eskitarih.' '.$eskisaat, 'yeni_tarih'=>$randevu->tarih.' '.$hizmet->saat]);

        return 'Randevu başarıyla güncellendi';
    }
    public function randevuiptalet(Request $request){
        if($r = self::yetkiYoksa403($request, 'randevu.duzenle_iptal')) return $r;

        $randevu = Randevular::where('id',$request->randevuid)->first();
         
        $red = false;
        if($randevu->durum == 0)
            $red = true;
        
        $seanslar = AdisyonPaketSeanslar::where('randevu_id',$randevu->id)->get();
        foreach($seanslar as $seans)
        {
            
            $seans->delete();

        }
        
        
        $randevu->durum = 2;
        $randevu->save();

        // Audit
        $_audit_musteriAdi = optional($randevu->users)->name ?? 'Müşteri #'.$randevu->user_id;
        $_audit_label = $_audit_musteriAdi.' — '.date('d.m.Y',strtotime($randevu->tarih)).' '.date('H:i',strtotime($randevu->saat));
        SalonAudit::log($randevu->salon_id, $red ? 'randevu_reddet' : 'randevu_iptal', 'randevu', $randevu->id, $_audit_label,
            $red ? 'Bekleyen randevu talebi reddedildi' : 'Randevu iptal edildi',
            ['eski_durum' => $red ? 0 : 1]);

        $isletme = Salonlar::where('id',$randevu->salon_id)->first();
        $mesajlar = array();
        if($red)
        {
            $musteriMesaji = $isletme->salon_adi." için oluşturduğunuz ".date('d.m.Y',strtotime($randevu->tarih)) ." ". date('H:i',strtotime($randevu->saat)) ." tarihli randevu talebiniz reddedilmiştir. Detaylı bilgi için bize ulaşın. 0".$isletme->telefon_1;
            $this->smsVeyaWhatsappGonder($randevu->salonlar, $randevu->users->cep_telefon, $musteriMesaji, 3, 'musteri', $randevu->id, $randevu->user_id, $mesajlar);
            if($randevu->user_id){
                try {
                    NotificationService::toCustomer((int)$randevu->user_id, (int)$randevu->salon_id)
                        ->type(NotificationTypes::APPOINTMENT_CANCELLED)
                        ->title('Randevu Talebiniz Reddedildi')
                        ->body($musteriMesaji)
                        ->randevu((int)$randevu->id)
                        ->deepLink('appointment_detail', ['randevu_id' => $randevu->id])
                        ->extra(['islem' => 'red'])
                        ->send();
                } catch (\Throwable $e) { \Log::warning('musteri randevu red push: '.$e->getMessage()); }
            }

            foreach($randevu->hizmetler as $hizmet)
            {
                $hizmetAdi = ($hizmet->hizmetler && isset($hizmet->hizmetler->hizmet_adi)) ? $hizmet->hizmetler->hizmet_adi : '';
                $mesaj = $randevu->users->name .' isimli müşterinin yarın '.date('H:i',strtotime($hizmet->saat)).' saatli '.$hizmetAdi.' randevusu '.Auth::guard('isletmeyonetim')->user()->name.' tarafından reddedilmiştir.';
                $yetkiliid = Personeller::where('id',$hizmet->personel_id)->value('yetkili_id');
                $personelTel = IsletmeYetkilileri::where('id',$yetkiliid)->value('gsm1');
                $this->smsVeyaWhatsappGonder($randevu->salonlar, $personelTel, $mesaj, 3, 'personel', $randevu->id, null, $mesajlar);

                self::bildirimekle($request,$randevu->salon_id,$mesaj,"#",$hizmet->personel_id,null, Auth::guard('isletmeyonetim')->user()->profil_resim,$randevu->id);
                if($hizmet->personel_id){
                    try {
                        NotificationService::toStaff((int)$hizmet->personel_id, (int)$randevu->salon_id)
                            ->type(NotificationTypes::APPOINTMENT_CANCELLED)
                            ->title('Randevu Reddedildi')
                            ->body($mesaj)
                            ->randevu((int)$randevu->id)
                            ->deepLink('appointment_detail', ['randevu_id' => $randevu->id])
                            ->extra(['islem' => 'red'])
                            ->send();
                    } catch (\Throwable $e) { \Log::warning('randevu red push: '.$e->getMessage()); }
                }
            }
        }
        else
        {
            $musteriMesaji = $isletme->salon_adi." için oluşturulan ".date('d.m.Y',strtotime($randevu->tarih)) ." ". date('H:i',strtotime($randevu->saat)) ." tarihli randevunuz iptal edilmiştir. Detaylı bilgi için bize ulaşın. 0".$isletme->telefon_1;
            $this->smsVeyaWhatsappGonder($randevu->salonlar, $randevu->users->cep_telefon, $musteriMesaji, 3, 'musteri', $randevu->id, $randevu->user_id, $mesajlar);
            if($randevu->user_id){
                try {
                    NotificationService::toCustomer((int)$randevu->user_id, (int)$randevu->salon_id)
                        ->type(NotificationTypes::APPOINTMENT_CANCELLED)
                        ->title('Randevunuz İptal Edildi')
                        ->body($musteriMesaji)
                        ->randevu((int)$randevu->id)
                        ->deepLink('appointment_detail', ['randevu_id' => $randevu->id])
                        ->extra(['islem' => 'iptal'])
                        ->send();
                } catch (\Throwable $e) { \Log::warning('musteri randevu iptal push: '.$e->getMessage()); }
            }

            foreach($randevu->hizmetler as $hizmet)
            {
                $yetkiliid = Personeller::where('id',$hizmet->personel_id)->value('yetkili_id');
                $personelTel = IsletmeYetkilileri::where('id',$yetkiliid)->value('gsm1');
                $hizmetAdi = ($hizmet->hizmetler && isset($hizmet->hizmetler->hizmet_adi)) ? $hizmet->hizmetler->hizmet_adi : '';
                $mesaj = $randevu->users->name .' isimli müşterinin yarın '.date('H:i',strtotime($hizmet->saat)).' saatli '.$hizmetAdi.' randevusu '.Auth::guard('isletmeyonetim')->user()->name.' tarafından iptal edilmiştir.';
                $this->smsVeyaWhatsappGonder($randevu->salonlar, $personelTel, $mesaj, 3, 'personel', $randevu->id, null, $mesajlar);

                self::bildirimekle($request,$randevu->salon_id,$mesaj,"#",$hizmet->personel_id,null, Auth::guard('isletmeyonetim')->user()->profil_resim,$randevu->id);
                if($hizmet->personel_id){
                    try {
                        NotificationService::toStaff((int)$hizmet->personel_id, (int)$randevu->salon_id)
                            ->type(NotificationTypes::APPOINTMENT_CANCELLED)
                            ->title('Randevu İptal Edildi')
                            ->body($mesaj)
                            ->randevu((int)$randevu->id)
                            ->deepLink('appointment_detail', ['randevu_id' => $randevu->id])
                            ->extra(['islem' => 'iptal'])
                            ->send();
                    } catch (\Throwable $e) { \Log::warning('randevu iptal push: '.$e->getMessage()); }
                }
            }
        }
        if(count($mesajlar)>0)
            // salon_id ACIKCA gec — multi-branch kullanicida mevcutsube
            // yanlis salon (kullanicinin ilk yetkili sube'si) donerdi.
            self::sms_gonder_bildirimli($request,$mesajlar,false,1,false,$randevu->salon_id);
        if(is_numeric($request->musteriid))
        {
            return self::randevu_liste_getir($request, date('Y-m-d'), // tarih1: bugün
    date('Y-m-d'),'','','','',self::mevcutsube($request),$request->musteriid);
            exit;
        }
        else{
           return self::randevu_liste_getir(
    $request,
    date('Y-m-d'), // tarih1: bugün
    date('Y-m-d'), // tarih2: bugün
    '', '', '', '', 
    self::mevcutsube($request), 
    ''
);
            exit;
        }
    }
     public function randevuonayla(Request $request){
        $randevu = Randevular::where('id',$request->randevuid)->first();
        if (!$randevu) {
            return response()->json(['error' => 'Randevu bulunamadı'], 404);
        }
        $randevu->durum = 1;
        $randevu->save();

        // Audit (light)
        $musteriAdi = optional($randevu->users)->name ?? 'Müşteri #'.$randevu->user_id;
        $label = $musteriAdi.' — '.date('d.m.Y',strtotime($randevu->tarih)).' '.date('H:i',strtotime($randevu->saat));
        SalonAudit::log($randevu->salon_id, 'randevu_onayla', 'randevu', $randevu->id, $label, 'Randevu onaylandı');

        // Yanit verilerini hazirla:
        //  - JS ?withlist=1 gonderirse (liste sayfasinda) DataTable icin tum liste donulur
        //  - Diger (takvim/popup) durumlarda minimum response (cok daha hizli)
        $istekListeIstiyor = (bool) $request->input('withlist', false);
        if ($istekListeIstiyor) {
            $listResponse = self::randevu_liste_getir(
                $request,
                date('Y-m-d'),
                date('Y-m-d'),
                '', '', '', '',
                self::mevcutsube($request),
                ''
            );
        } else {
            $listResponse = ['success' => true, 'randevu_id' => $randevu->id, 'durum' => 1];
        }

        // Yaniti hemen flush et — SMS ve bildirim arka planda calisacak
        $kullaniciId = Auth::guard('isletmeyonetim')->id();
        $kullaniciAdi = Auth::guard('isletmeyonetim')->user()->name ?? '';
        $kullaniciResim = Auth::guard('isletmeyonetim')->user()->profil_resim ?? null;

        $payload = json_encode($listResponse);
        if (function_exists('fastcgi_finish_request')) {
            // PHP-FPM: yaniti hemen flush et, geri kalan kod baglanti kapali calisir
            ignore_user_abort(true);
            header('Content-Type: application/json');
            header('Content-Length: '.strlen($payload));
            echo $payload;
            session_write_close();
            fastcgi_finish_request();
        } else {
            // Generic fallback - yine de baglantiyi kapat sinyali gonder
            ignore_user_abort(true);
            header('Content-Type: application/json');
            header('Content-Length: '.strlen($payload));
            header('Connection: close');
            echo $payload;
            if (function_exists('ob_end_flush')) { @ob_end_flush(); }
            @flush();
        }

        // === BACKGROUND: SMS + Bildirim ===
        try {
            $isletme = Salonlar::where('id',$randevu->salon_id)->first();
            $mesajlar = array();

            $musteriOnayMesaji = $isletme->salon_adi." için oluşturduğunuz ".date('d.m.Y',strtotime($randevu->tarih))." ".date('H:i',strtotime($randevu->saat))." tarihli randevu talebiniz onaylanmıştır. Randevunuza 15 dk önce gelmenizi rica ederiz. Detaylı bilgi için bize ulaşın. 0".$randevu->salonlar->telefon_1;
            if (SalonSMSAyarlari::where('ayar_id',2)->where('salon_id',$randevu->salon_id)->value('musteri') == 1) {
                $mesajlar[] = [
                    'to' => $randevu->users->cep_telefon,
                    'message' => $musteriOnayMesaji
                ];
            }
            // Musteri push (SMS metniyle birebir, SMS ayarindan bagimsiz)
            if($randevu->user_id){
                try {
                    NotificationService::toCustomer((int)$randevu->user_id, (int)$randevu->salon_id)
                        ->type(NotificationTypes::APPOINTMENT_APPROVED)
                        ->title('Randevunuz Onaylandı')
                        ->body($musteriOnayMesaji)
                        ->randevu((int)$randevu->id)
                        ->deepLink('appointment_detail', ['randevu_id' => $randevu->id])
                        ->send();
                } catch (\Throwable $e) { \Log::warning('musteri randevu onay push: '.$e->getMessage()); }
            }
            if (SalonSMSAyarlari::where('ayar_id',2)->where('salon_id',$randevu->salon_id)->value('personel') == 1) {
                foreach ($randevu->hizmetler as $hizmet) {
                    $yetkiliid = Personeller::where('id',$hizmet->personel_id)->value('yetkili_id');
                    $mesaj = $randevu->users->name.' isimli müşterinin yarın '.date('H:i',strtotime($hizmet->saat)).' saatli '.$hizmet->hizmetler->hizmet_adi.' randevusu '.$kullaniciAdi.' tarafından onaylanmıştır.';
                    $mesajlar[] = [
                        'to' => IsletmeYetkilileri::where('id',$yetkiliid)->value('gsm1'),
                        'message' => $mesaj,
                    ];
                    self::bildirimekle($request, $randevu->salon_id, $mesaj, "#", $hizmet->personel_id, null, $kullaniciResim, $randevu->id);
                    if($hizmet->personel_id){
                        try {
                            NotificationService::toStaff((int)$hizmet->personel_id, (int)$randevu->salon_id)
                                ->type(NotificationTypes::APPOINTMENT_APPROVED)
                                ->title('Randevu Onaylandı')
                                ->body($mesaj)
                                ->randevu((int)$randevu->id)
                                ->deepLink('appointment_detail', ['randevu_id' => $randevu->id])
                                ->send();
                        } catch (\Throwable $e) { \Log::warning('randevu onay push: '.$e->getMessage()); }
                    }
                }
            }
            if (count($mesajlar) > 0) {
                self::sms_gonder_bildirimli($request, $mesajlar, false, 1, false);
            }
        } catch (\Throwable $e) {
            \Log::error('[randevuonayla background] SMS/bildirim hata: '.$e->getMessage(), ['randevu_id' => $randevu->id]);
        }

        // PHP daha fazla output yapmasin
        exit;
     }
    public function randevubilgiguncelle(Request $request){
        $randevu = Randevular::where('id',$request->randevuid)->first();
        $randevu->tarih = $request->randevutarihi;
        $randevu->saat = $request->randevusaati;
        $randevu->saat_bitis = $request->randevusaatibitis;
        $musteriid = $randevu->user_id;
        $randevu->save();
         $randevueklenen = Randevular::where('id',$randevu->id)->first();
                $randevuguncel['newevent']['id'] =  $randevueklenen->id;
                $randevuguncel['newevent']['title'] = User::where('id',$musteriid)->value('name');
                $randevuguncel['newevent']['start'] = $randevueklenen->tarih .' '.$randevueklenen->saat;
                $randevuguncel['newevent']['end'] = $randevueklenen->tarih .' '.$randevueklenen->saat_bitis;
                if($randevueklenen->durum == 2)
                    $randevuguncel['newevent']['color'] = "#FF0000";
                else if($randevueklenen->durum == 1)
                    $randevuguncel['newevent']['color'] = "#34a853";
                else if($randevueklenen->durum ==0 || $randevueklenen->durum=='' ||$randevueklenen->durum == null)
                   $randevuguncel['newevent']['color'] = "#FF4E00";
               $randevuguncel['newevent']['eposta'] = User::where('id',$musteriid)->value('email');
               $randevuguncel['newevent']['telefoncep'] = User::where('id',$musteriid)->value('cep_telefon');
               $randevuguncel['newevent']['telefonev'] = User::where('id',$musteriid)->value('ev_telefon');
                $randevuhizmetler = RandevuHizmetler::where('randevu_id',$randevueklenen->id)->get();
               foreach ($randevuhizmetler as $key2 => $value2) {
                    $randevuguncel['newevent']['hizmet'][$key2] = Hizmetler::where('id',$value2->hizmet_id)->value('hizmet_adi');
                    $randevuguncel['newevent']['personel'][$key2] = Personeller::where('id',$value2->personel_id)->value('personel_adi');
                    $randevuguncel['newevent']['hizmetid'][$key2] = Hizmetler::where('id',$value2->hizmet_id)->value('id');
                    $randevuguncel['newevent']['personelid'][$key2] = Personeller::where('id',$value2->personel_id)->value('id');
               }
               $randevuguncel['newevent']['data-modal'] = "md-scale";
          $randevuguncel['success'] = 'Randevu başarı ile güncellendi';
           return json_encode($randevuguncel);
    }
