     public function gorselsil(Request $request){
        $gorsel = SalonGorselleri::where('id',$request->gorselid)->first();
        if($gorsel){
            // Dosyayi guvenli sil: yol yanlis/dosya yoksa unlink warning'i 500'e donmesin
            $rel = preg_replace('#^/public#','',$gorsel->salon_gorseli);
            foreach([public_path($rel), '/home/webfirma/randevumcepteweb2'.$gorsel->salon_gorseli] as $yol){
                if(is_file($yol)){ @unlink($yol); break; }
            }
            $gorsel->delete();
        }
        $gorseller_html = self::salon_gorselleri($request);
        echo $gorseller_html;
    }
    public function yenirandevu(){
       $isletmeler = '';
        $isletme='';
        if(Auth::guard('satisortakligi')->check())
        {
            $isletmeler = [15];
            $isletme = Salonlar::where('id',15)->first();
        }
        else{
            $isletmeler = Auth::guard('isletmeyonetim')->user()->yetkili_olunan_isletmeler->where('aktif',1)->pluck('salon_id')->toArray();
            $isletme= Salonlar::where('id',self::mevcutsube($request))->first();
        }


        if(!in_array(self::mevcutsube($request),$isletmeler ))
        {
            return view('isletmeadmin.yetkisizerisim');
            exit(0);
        }
        if(str_contains(self::lisans_sure_kontrol($request),'-'))
        {
            return view('isletmeadmin.lisanssurebitti',['isletme'=>$isletme]);
            exit(0);
        }
        if(!Auth::guard('satisortakligi')->check()){
             if(self::personelmi($request, 'randevu.tum_personel_gor'))
            {
                    return redirect()->route('isletmeadmin.randevular');
                    exit(0);
            }
        }
       
        if(count($isletmeler)>1 && !isset($_GET['sube']))
        {
            return view('isletmeadmin.isletmesec',['isletmeler'=>$isletmeler,'isletme'=>$isletme]);
            exit(0);
        }
        $isletme = Salonlar::where('id',Auth::guard('isletmeyonetim')->user()->salon_id)->first();
        $personeller = Personeller::where('salon_id',Auth::guard('isletmeyonetim')->user()->salon_id)->get();
        $sunulanhizmetler = SalonHizmetler::where('salon_id',Auth::guard('isletmeyonetim')->user()->salon_id)->get();
        $mevcutmusteriler = Randevular::join('users','randevular.user_id','=','users.id')->where('randevular.salon_id',Auth::guard('isletmeyonetim')->user()->salon_id)->groupBy('randevular.user_id')->get();
        return view('isletmeadmin.yenirandevu',[ 'title' =>  'Yeni Randevu Ekle | randevumcepte.com.tr','pageindex' => 102,'isletme'=>$isletme,'personeller'=> $personeller, 'sunulanhizmetler'=> $sunulanhizmetler,'mevcutmusteriler'=>$mevcutmusteriler, 'kalan_uyelik_suresi' => self::lisans_sure_kontrol($request),'portfoy_drop'=>self::musteriportfoydropliste($request),'urun_drop'=>self::urundropliste($request),'hizmet_drop'=>self::hizmetdropliste($request),
            'personel_drop'=>self::personeldropliste($request,array()),'yetkiliolunanisletmeler'=>$isletmeler] );
    }
    public function randevupersonelgetir(Request $request){
        $personelhizmetler = PersonelHizmetler::join('salon_personelleri','personel_sunulan_hizmetler.personel_id','=','salon_personelleri.id')->where('salon_personelleri.salon_id',Auth::guard('isletmeyonetim')->user()->salon_id)->where('personel_sunulan_hizmetler.hizmet_id',$request->hizmet_id)->get();
        $hizmet = Hizmetler::where('id',$request->hizmetid)->value('hizmet_adi');
        $personeller = Personeller::where('salon_id',Auth::guard('isletmeyonetim')->user()->salon_id)->get();
        $personelsechtml = "<div class='col-xs-6 col-sm-6 col-md-6 col-lg-6'>
                                  <div class='form-group'>
                                    <label>".$hizmet." İçin Personel Seçin</label>
                                        <select required name='yenirandevupersonelleri[]' class='form-control'>";
       foreach ($personelhizmetler as $key => $value) {
             $personelsechtml .= "<option value='".$value->personel_id."'>".$value->personel_adi."</option>";
       }
       if($personelhizmetler->count()==0){
           foreach ($personeller as $key => $value) {
               $personelsechtml .= "<option value='".$value->id."'>".$value->personel_adi."</option>";
           }
        }
        $personelsechtml .="  </select>
                                  </div></div>";
      echo $personelsechtml;
    }
       public function yenirandevuekle(Request $request){
    if($r = self::yetkiYoksa403($request, 'randevu.olustur')) return $r;
    try {
    // Debug log: gelen istegi izle (hizli paket randevu hatalarini cozmek icin)
    \Log::info('[yenirandevuekle] istek', [
        'adsoyad' => $request->adsoyad,
        'tarih' => $request->tarih,
        'saat' => $request->saat,
        'sube' => $request->sube,
        'pers_yeni' => $request->randevupersonelleriyeni,
        'cihaz_yeni' => $request->randevucihazlariyeni,
        'oda_yeni' => $request->randevuodalariyeni,
        'hizmet_keys' => array_filter(array_keys($request->all()), function($k){ return strpos($k, 'randevuhizmetleriyeni_') === 0; }),
    ]);
    $musteriid = $request->adsoyad;
    $tarihler = "";
    $randevu_tarihleri = array();
    array_push($randevu_tarihleri,$request->tarih);
    $eklenecek_tarih = $request->tarih;
    
    if(isset($request->tekrarlayan)){
        for($t=1;$t<$request->tekrar_sayisi;$t++)
        {
            $eklenecek_tarih = date('Y-m-d', strtotime($request->tekrar_sikligi, strtotime($eklenecek_tarih)));
            array_push($randevu_tarihleri,$eklenecek_tarih);
        }
    }
    
    $cakisma_varmi = '';
    if(!isset($request->cakisanrandevuekle))
        $cakisma_varmi = self::cakisan_randevu_kontrol($request,$randevu_tarihleri);
        
    if($cakisma_varmi != '' && !isset($request->cakisanrandevuekle))
    {
        return array('cakismavar'=>$cakisma_varmi);
        exit();
    }
    elseif(Salonlar::where('id',$request->sube)->value('demo_hesabi') == 1 && Randevular::where('salon_id',$request->sube)->count()>95)
    {
        return array('sube'=>Randevular::where('salon_id',$request->sube)->count(),'eklenemez'=>'<p>Deneme hesabında en fazla 5 randevu eklenebilir. Devam etmek için lütfen "Üyelik" bölümünden paket üyeliği başlatınız.</p><a href="/isletmeyonetim/uyelik?sube="'.$request->sube.' class="btn btn-primary">Paketleri İncele</a>');
    }
    else
    {
        if($cakisma_varmi == '' || $request->cakisanrandevuekle==1)
        {
            foreach($randevu_tarihleri as $tarihler){
                /*$totalsure = 0;
                foreach($request->hizmet_suresi as $key => $value)
                {
                    $totalsure += $value;
                }*/
                
                // Ana randevuyu oluştur
                $yenirandevu = [
                    'user_id' => $musteriid,
                    'salon_id' => $request->sube,
                    'tarih' => $tarihler,
                    'saat' => $request->saat,
                    'salon' => true,
                    'olusturan_personel_id' => Auth::guard('isletmeyonetim')->user()->id,
                    'saat_bitis' => null,//date("H:i", strtotime('+'.$totalsure.' minutes', strtotime($request->saat))),
                    'durum' => 1,
                    'personel_notu' => $request->personel_notu,
                ];
                
                $yenirandevu = Randevular::create($yenirandevu);
                // Audit
                $musteriAdi = \App\User::where('id',$musteriid)->value('name') ?? 'Müşteri #'.$musteriid;
                SalonAudit::log($request->sube, 'randevu_olustur', 'randevu', $yenirandevu->id,
                    $musteriAdi.' — '.date('d.m.Y',strtotime($tarihler)).' '.substr($request->saat,0,5),
                    'Yeni randevu oluşturuldu');

                $hizmet_id = "";
                $yenisaatbaslangic = $request->saat;
                $hizmet_sureleri_okunan = array();
                
                foreach ($request->randevupersonelleriyeni as $key2 => $value) {
                   
                    
                    // Personel ID kontrolü - null olabileceği için özel kontrol
                    $personel_id = null;
                    if(isset($request->randevupersonelleriyeni[$key2]) && $request->randevupersonelleriyeni[$key2] != '') {
                        $personel_id = $request->randevupersonelleriyeni[$key2];
                    }
                    
                    // Cihaz ID kontrolü
                    $cihaz_id = null;
                    if(isset($request->randevucihazlariyeni[$key2]) && $request->randevucihazlariyeni[$key2] != '') {
                        $cihaz_id = $request->randevucihazlariyeni[$key2];
                    }
                    
                    // Oda ID kontrolü (manuel seçim varsa override; yoksa hizmet bazında otomatik atanır)
                    $oda_id = null;
                    if(isset($request->randevuodalariyeni[$key2]) && $request->randevuodalariyeni[$key2] != '') {
                        $oda_id = $request->randevuodalariyeni[$key2];
                    }
                    $hizmetlerToplami = 0;
                    $rHizmetler = $request->{"randevuhizmetleriyeni_{$key2}"};
                    if(!is_array($rHizmetler) || empty($rHizmetler)) {
                        // Hizmetsiz randevu: hizmet secilmeden, sadece "Paket Süresi (dk)" girilmisse
                        // tek bir hizmet_id=NULL satiri olustur (genel sure tek kez uygulanir -> sadece ilk satir).
                        if($key2 == 0 && (int)($request->randevusuz_sure ?? 0) > 0) {
                            $hizmetsizSure = (int) $request->randevusuz_sure;
                            $rhSuresiz = new RandevuHizmetler();
                            $rhSuresiz->randevu_id  = $yenirandevu->id;
                            $rhSuresiz->hizmet_id   = null;
                            $rhSuresiz->cihaz_id    = $cihaz_id;
                            $rhSuresiz->personel_id = $personel_id;
                            $rhSuresiz->oda_id      = $oda_id;
                            $rhSuresiz->sure_dk     = $hizmetsizSure;
                            $rhSuresiz->saat        = $yenisaatbaslangic;
                            $rhSuresiz->saat_bitis  = date("H:i", strtotime('+'.$hizmetsizSure.' minutes', strtotime($yenisaatbaslangic)));
                            $rhSuresiz->save();
                        }
                        continue;
                    }
                    foreach($rHizmetler as $_key=>  $rHizmet)
                    {
                        array_push($hizmet_sureleri_okunan,$request->{"hizmet_sureleri-$rHizmet"});
                        // Otomatik oda atama: manuel oda seçili değilse hizmete uygun ilk müsait oda
                        $hizmetOdaId = $oda_id;
                        if(!$hizmetOdaId) {
                            $hSure = (int) ($request->{"hizmet_sureleri-$rHizmet"} ?? 0);
                            $hBitis = $hSure > 0
                                ? date("H:i", strtotime('+'.$hSure.' minutes', strtotime($yenisaatbaslangic)))
                                : $yenisaatbaslangic;
                            $hizmetOdaId = \App\Services\OdaAtamaServisi::uygunOdaSec(
                                (int) $request->sube,
                                (int) $rHizmet,
                                $tarihler,
                                $yenisaatbaslangic,
                                $hBitis
                            );
                        }
                        $yenirandevuhizmetpersonel = new RandevuHizmetler();
                        $yenirandevuhizmetpersonel->randevu_id = $yenirandevu->id;
                        $yenirandevuhizmetpersonel->hizmet_id = $rHizmet;
                        $yenirandevuhizmetpersonel->cihaz_id = $cihaz_id;
                        $yenirandevuhizmetpersonel->personel_id = $personel_id;
                        $yenirandevuhizmetpersonel->oda_id = $hizmetOdaId;
                        $yenirandevuhizmetpersonel->sure_dk = $request->{"hizmet_sureleri-$rHizmet"};
                        $yenirandevuhizmetpersonel->fiyat = self::parseFiyat($request->{"hizmet_fiyatlari-$rHizmet"});
                        // Salonun girdigi dusum miktari (paketten kac seans/dakika).
                        // NULL ise "Geldi" popup'unda default 1 gelir; doluysa o deger default olur.
                        $_miktar = $request->{"hizmet_miktarlari-$rHizmet"} ?? null;
                        if ($_miktar !== null && $_miktar !== '') {
                            $yenirandevuhizmetpersonel->dusum_miktari = max(1, (int) $_miktar);
                        }
                        
                         
                        $yenirandevuhizmetpersonel->saat = $yenisaatbaslangic;
                        $yenirandevuhizmetpersonel->saat_bitis = date("H:i", strtotime('+'.$request->{"hizmet_sureleri-$rHizmet"}.' minutes', strtotime($yenisaatbaslangic)));   
                        

                        $birsonraki = $key2+1;
                        $hizmetlerToplami += $request->{"hizmet_sureleri-$rHizmet"};


                        if($_key == count($request->{"randevuhizmetleriyeni_{$key2}"}) - 1)
                        {
                            if($key2 == 0){
                                
                                //$yenirandevuhizmetpersonel->saat_bitis = date("H:i", strtotime('+'.$request->{"hizmet_sureleri-$rHizmet"}.' minutes', strtotime($request->saat)));
                                if(!isset($request->{"birlestir{$birsonraki}"}))
                                    $yenisaatbaslangic = date("H:i", strtotime('+'.$hizmetlerToplami.' minutes', strtotime($yenisaatbaslangic)));
                            }
                            else{
                                $yenirandevuhizmetpersonel->saat = $yenisaatbaslangic;
                                $yenirandevuhizmetpersonel->saat_bitis = date("H:i", strtotime('+'.$hizmetlerToplami.' minutes', strtotime($yenisaatbaslangic)));
                                if(!isset($request->{"birlestir{$birsonraki}"}))
                                    $yenisaatbaslangic = date("H:i", strtotime('+'.$hizmetlerToplami.' minutes', strtotime($yenisaatbaslangic)));
                            }
                        }
                        else
                            $yenisaatbaslangic = date("H:i", strtotime('+'.$request->{"hizmet_sureleri-$rHizmet"}.' minutes', strtotime($yenisaatbaslangic)));
                       
                        
                        $yenirandevuhizmetpersonel->save();

                        // [DUSUM-DEBUG] dusum_miktari kaydoluyor mu? (gecici tani)
                        try {
                            \Log::info('[DUSUM-DEBUG] yenirandevuekle', [
                                'rh_id'          => $yenirandevuhizmetpersonel->id,
                                'hizmet_id'      => $rHizmet,
                                'miktar_request' => $request->{"hizmet_miktarlari-$rHizmet"} ?? 'YOK',
                                'dusum_set'      => $yenirandevuhizmetpersonel->dusum_miktari,
                                'has_column'     => \Schema::hasColumn('randevu_hizmetler','dusum_miktari'),
                                'dusum_db'       => \DB::table('randevu_hizmetler')->where('id',$yenirandevuhizmetpersonel->id)->value('dusum_miktari'),
                            ]);
                        } catch(\Throwable $e){ \Log::warning('[DUSUM-DEBUG] hata: '.$e->getMessage()); }

                        // Yardımcı personelleri ekle
                        if(isset($request->{"randevuyardimcipersonelleriyeni_{$key2}"}) && is_array($request->{"randevuyardimcipersonelleriyeni_{$key2}"})) {
                            foreach($request->{"randevuyardimcipersonelleriyeni_{$key2}"} as $yardimci_personel_id) {
                                if($yardimci_personel_id != '') {
                                    $yardimci_personel = new RandevuHizmetler();
                                    $yardimci_personel->randevu_id = $yenirandevu->id;
                                    $yardimci_personel->hizmet_id = $rHizmet;
                                    $yardimci_personel->cihaz_id = $cihaz_id;
                                    $yardimci_personel->personel_id = $yardimci_personel_id;
                                    $yardimci_personel->oda_id = $hizmetOdaId;
                                    $yardimci_personel->sure_dk = $request->{"hizmet_sureleri-$rHizmet"};
                                    $yardimci_personel->fiyat = $request->{"hizmet_fiyatlari-$rHizmet"};
                                    $yardimci_personel->saat = $yenirandevuhizmetpersonel->saat;
                                    $yardimci_personel->saat_bitis = $yenirandevuhizmetpersonel->saat_bitis;
                                    $yardimci_personel->yardimci_personel = true;
                                    $yardimci_personel->save();
                                }
                            }
                        }

                        // ADISYON_HIZMET / ADISYON_PAKET araması: paketVarmiKontrolu ile ayni mantik.
                        // - Sadece seans_sayisi > 0 olan (gercek paket satisi) adaylar
                        // - Kalan (seans_sayisi - COUNT(APS)) > 0 olanlar
                        // - Ilk uygun olani sec; hicbiri yoksa APS yazma (paket randevusu degil).
                        //
                        // Onceki kodun bugu: 'whereHas' + '->first()' NULL seans_sayisi'li adisyon_hizmet'e
                        // takiliyordu (ornek: musteri 163360, hizmet 3805 icin iki adisyon_hizmet;
                        // biri NULL biri 10 seans; APS NULL olana bagliniyordu, takvim etiketi
                        // 'seans_sayisi > 0' arayan mantiga takilip PAKET etiketini gostermiyordu).
                        $_hizmetSecili = null;
                        foreach (DB::table('adisyon_hizmetler')
                            ->join('adisyonlar', 'adisyon_hizmetler.adisyon_id', '=', 'adisyonlar.id')
                            ->where('adisyon_hizmetler.hizmet_id', $rHizmet)
                            ->where('adisyonlar.user_id', $musteriid)
                            ->where('adisyonlar.salon_id', $request->sube)
                            ->where('adisyon_hizmetler.seans_sayisi', '>', 0)
                            ->where(function($q){
                                $q->whereNull('adisyon_hizmetler.otomatik_randevu_olusturuldu')
                                  ->orWhere('adisyon_hizmetler.otomatik_randevu_olusturuldu', '!=', 1);
                            })
                            ->orderBy('adisyonlar.tarih', 'asc')
                            ->select('adisyon_hizmetler.id', 'adisyon_hizmetler.seans_sayisi',
                                     'adisyon_hizmetler.kullanilan_seans', 'adisyon_hizmetler.kullanilmayan_seans',
                                     'adisyonlar.tarih as adisyon_tarih')
                            ->get() as $__h) {
                            $__kul = (int) DB::table('adisyon_paket_seanslar')
                                ->where('adisyon_hizmet_id', $__h->id)
                                ->count();
                            if ($__kul < (int) $__h->seans_sayisi) { $_hizmetSecili = $__h; break; }
                        }

                        $_paketSecili = null;
                        foreach (DB::table('adisyon_paketler')
                            ->join('adisyonlar', 'adisyon_paketler.adisyon_id', '=', 'adisyonlar.id')
                            ->join('paket_hizmetler', 'paket_hizmetler.paket_id', '=', 'adisyon_paketler.paket_id')
                            ->where('paket_hizmetler.hizmet_id', $rHizmet)
                            ->where('adisyonlar.user_id', $musteriid)
                            ->where('adisyonlar.salon_id', $request->sube)
                            ->where('adisyon_paketler.seans_sayisi', '>', 0)
                            ->where(function($q){
                                $q->whereNull('adisyon_paketler.otomatik_randevu_olusturuldu')
                                  ->orWhere('adisyon_paketler.otomatik_randevu_olusturuldu', '!=', 1);
                            })
                            ->orderBy('adisyonlar.tarih', 'asc')
                            ->select('adisyon_paketler.id', 'adisyon_paketler.seans_sayisi',
                                     'adisyon_paketler.kullanilan_seans', 'adisyon_paketler.kullanilmayan_seans',
                                     'adisyonlar.tarih as adisyon_tarih')
                            ->distinct()
                            ->get() as $__p) {
                            $__kul = (int) DB::table('adisyon_paket_seanslar')
                                ->where('adisyon_paket_id', $__p->id)
                                ->where('hizmet_id', $rHizmet)
                                ->count();
                            if ($__kul < (int) $__p->seans_sayisi) { $_paketSecili = $__p; break; }
                        }

                        // Tarih karsilastirma: ikisi de varsa eski tarihli olani sec
                        $hizmetAdisyonundanIsle = false;
                        $paketAdisyonundanIsle = false;
                        if ($_hizmetSecili && $_paketSecili) {
                            if (date('Y-m-d', strtotime($_hizmetSecili->adisyon_tarih)) < date('Y-m-d', strtotime($_paketSecili->adisyon_tarih))) {
                                $hizmetAdisyonundanIsle = true;
                            } else {
                                $paketAdisyonundanIsle = true;
                            }
                        } else {
                            if ($_hizmetSecili) $hizmetAdisyonundanIsle = true;
                            if ($_paketSecili)  $paketAdisyonundanIsle = true;
                        }

                        if ($hizmetAdisyonundanIsle) {
                            $seansKaydi = new AdisyonPaketSeanslar();
                            $seansKaydi->seans_tarih = $tarihler;
                            $seansKaydi->seans_saat = $yenisaatbaslangic;
                            $seansKaydi->personel_id = $personel_id;
                            $seansKaydi->cihaz_id = $cihaz_id;
                            $seansKaydi->oda_id = $hizmetOdaId;
                            $seansKaydi->randevu_id = $yenirandevu->id;
                            $seansKaydi->seans_no = ((int)($_hizmetSecili->kullanilan_seans ?? 0)) + ((int)($_hizmetSecili->kullanilmayan_seans ?? 0)) + 1;
                            $seansKaydi->adisyon_hizmet_id = $_hizmetSecili->id;
                            $seansKaydi->hizmet_id = $rHizmet;
                            $seansKaydi->save();
                        } elseif ($paketAdisyonundanIsle) {
                            $seansKaydi = new AdisyonPaketSeanslar();
                            $seansKaydi->seans_tarih = $tarihler;
                            $seansKaydi->seans_saat = $yenisaatbaslangic;
                            $seansKaydi->personel_id = $personel_id;
                            $seansKaydi->cihaz_id = $cihaz_id;
                            $seansKaydi->oda_id = $hizmetOdaId;
                            $seansKaydi->randevu_id = $yenirandevu->id;
                            $seansKaydi->seans_no = ((int)($_paketSecili->kullanilan_seans ?? 0)) + ((int)($_paketSecili->kullanilmayan_seans ?? 0)) + 1;
                            $seansKaydi->adisyon_paket_id = $_paketSecili->id;
                            $seansKaydi->hizmet_id = $rHizmet;
                            $seansKaydi->save();
                        }
                    }
                    
                    
                   
                    
                }
            }

            // SMS ve bildirim işlemleri
            $isletme = Salonlar::where('id',$request->sube)->first();
            $musteribilgi = User::where('id',$musteriid)->first();
            $gsm = $musteribilgi->cep_telefon;
            $mesajlar = array();
            
            $musteriYeniRandevuMesaji = $isletme->salon_adi . " tarafından ".date('d.m.Y',strtotime($request->tarih)) .'-'.$request->saat .' olarak randevunuz oluşturulmuştur. Randevunuza 15 dk önce gelmenizi rica ederiz. Detaylı bilgi için bize ulaşın. 0'.$isletme->telefon_1;

            // WA icin zenginlestirilmis format (SMS aynen kisa kalir)
            $_hizmetAdlari = collect();
            foreach ($yenirandevu->hizmetler as $_h) {
                $_hAd = optional($_h->hizmetler)->hizmet_adi;
                if ($_hAd) $_hizmetAdlari->push($_hAd);
            }
            $musteriYeniRandevuMesajiWA = \App\Services\WhatsAppMesajFormat::randevuOlusturuldu(
                $isletme,
                $musteribilgi->name ?? '',
                date('d.m.Y', strtotime($request->tarih)),
                $request->saat,
                $_hizmetAdlari->unique()->values()->implode(', ')
            );

            $musteriToggle = SalonSMSAyarlari::where('ayar_id',12)->where('salon_id',$yenirandevu->salon_id)->value('musteri') == 1;

            // Kritik bypass: ERTESI GUN icin + saat 19:00 sonra olusturulan + <24h kala
            // randevularda toggle KAPALI bile olsa musteriye gitsin (1-gun-once cron'un
            // 17-19 penceresi gectigi icin baska sansi olmaz, musteri hicbir bildirim
            // almadan randevuya gelmek zorunda kalmasin).
            $_now = time();
            $_hour = (int) date('G', $_now);
            $_yarinTarih = date('Y-m-d', strtotime('+1 day'));
            $_randevuTarihi = date('Y-m-d', strtotime($request->tarih));
            $_randevuTs = strtotime($request->tarih . ' ' . $request->saat);
            $_kalanSaat = ($_randevuTs - $_now) / 3600;
            $_kritikBypass = ($_randevuTarihi === $_yarinTarih)
                          && ($_hour >= 19)
                          && ($_kalanSaat > 0)
                          && ($_kalanSaat < 24);

            if ($musteriToggle || $_kritikBypass) {
                array_push($mesajlar, array(
                    "to" => $gsm,
                    "message" => $musteriYeniRandevuMesaji,       // SMS'e giden kisa metin
                    "wa_message" => $musteriYeniRandevuMesajiWA,  // WA'ya giden zengin metin
                ));
                if (!$musteriToggle && $_kritikBypass) {
                    \Log::info('[RND-CREATE] kritik bypass (toggle kapali, 19 sonra ertesi gun <24h kala)', [
                        'salon_id' => $yenirandevu->salon_id,
                        'randevu_id' => $yenirandevu->id,
                        'tarih_saat' => $request->tarih . ' ' . $request->saat,
                        'kalan_saat' => round($_kalanSaat, 2),
                    ]);
                }
            }
            // Musteri push (SMS metniyle birebir)
            if($musteriid){
                try {
                    NotificationService::toCustomer((int)$musteriid, (int)$yenirandevu->salon_id)
                        ->type(NotificationTypes::APPOINTMENT_CREATED)
                        ->title('Yeni Randevunuz Oluşturuldu')
                        ->body($musteriYeniRandevuMesaji)
                        ->randevu((int)$yenirandevu->id)
                        ->deepLink('appointment_detail', ['randevu_id' => $yenirandevu->id])
                        ->send();
                } catch (\Throwable $e) { \Log::warning('musteri yeni randevu push: '.$e->getMessage()); }
            }
            
            foreach($yenirandevu->hizmetler as $hizmet) {
                $mesaj = "";
                if(SalonSMSAyarlari::where('ayar_id',12)->where('salon_id',$yenirandevu->salon_id)->value('personel')==1 && $hizmet->personel_id) {
                    $mesaj = $yenirandevu->users->name." isimli müşterinin ". date('d.m.Y',strtotime($yenirandevu->tarih)) ." - ". date('H:i',strtotime($hizmet->saat)) ." ".$hizmet->hizmetler->hizmet_adi." randevusu ".Auth::guard('isletmeyonetim')->user()->name." tarafından oluşturulmuştur.";
                    $yetkiliid = Personeller::where('id',$hizmet->personel_id)->value('yetkili_id');
                    array_push($mesajlar, array("to"=>IsletmeYetkilileri::where('id',$yetkiliid)->value('gsm1'),"message"=>$mesaj));
                }
                
                // Personel ID null olabileceği için kontrol ekledim
                if($hizmet->personel_id) {
                    self::bildirimekle($request,$yenirandevu->salon_id,$mesaj,"#",$hizmet->personel_id,null, Auth::guard('isletmeyonetim')->user()->profil_resim,$yenirandevu->id);
                    try {
                        NotificationService::toStaff((int)$hizmet->personel_id, (int)$yenirandevu->salon_id)
                            ->type(NotificationTypes::APPOINTMENT_CREATED)
                            ->title('Yeni Randevu')
                            ->body($mesaj)
                            ->randevu((int)$yenirandevu->id)
                            ->deepLink('appointment_detail', ['randevu_id' => $yenirandevu->id])
                            ->send();
                    } catch (\Throwable $e) { \Log::warning('yeni randevu push: '.$e->getMessage()); }
                }
            }
            
            if(count($mesajlar)>0)
                // salon_id ACIKCA gec — multi-branch kullanicida mevcutsube
                // yanlis salon (kullanicinin ilk yetkili sube'si) donerdi.
                self::sms_gonder_bildirimli($request,$mesajlar,false,1,false,$yenirandevu->salon_id);

            $butonlar = '';
            $randevu = array();
            if(!isset($request->takvim_sayfasi) ){
                $butonlar .= "<a class='btn btn-primary btn-lg btn-block' href='/isletmeyonetim/randevular?sube=".$request->sube."'>"
                                      ."Takvime Git</a>".
                                      "<a class='btn btn-primary btn-lg btn-block' href='/isletmeyonetim/randevular-liste?sube=".$request->sube."'>"
                                      ."Randevu Listesine Git</a>";
                $randevu['timer'] = 30000;
            }
            else
                 $randevu['timer'] = 3000;
                 
            $randevu['success'] = '<p>Randevu başarı ile oluşturuldu.</p>'.$butonlar;
            return $randevu;
            exit();
        }
    }
    } catch (\Throwable $e) {
        \Log::error('[yenirandevuekle] istisna', [
            'msg' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'trace' => $e->getTraceAsString(),
            'request_keys' => array_keys($request->all()),
        ]);
        return response()->json([
            'error' => true,
            'eklenemez' => 'Randevu oluşturulurken hata: ' . $e->getMessage() . ' (' . basename($e->getFile()) . ':' . $e->getLine() . ')',
        ], 500);
    }
}
    public function personel_cihaz_oda($id,$salonid)
    {
        $durum = 0;
        if(Personeller::where('id',$id)->where('salon_id',$salonid)->count()==1)
            $durum=1;
        if(Cihazlar::where('id',$id)->where('salon_id',$salonid)->count()==1)
            $durum=2;
        if(Odalar::where('id',$id)->where('salon_id',$salonid)->count()==1)
            $durum=3;
        return $durum;
    }
    public function saatkapamaekle(Request $request){
        try {
            $tarihler = "";
            $randevu_tarihleri = array();
            if (empty($request->tarih)) {
                return response()->json(['error' => 'Tarih zorunlu'], 422);
            }
            array_push($randevu_tarihleri,$request->tarih);
            $eklenecek_tarih = $request->tarih;
            if(isset($request->tekrarlayan) && (int)($request->tekrar_sayisi ?? 0) > 0){
                for($t=1;$t<$request->tekrar_sayisi;$t++){
                    $eklenecek_tarih = date('Y-m-d', strtotime($request->tekrar_sikligi, strtotime($eklenecek_tarih)));
                    array_push($randevu_tarihleri,$eklenecek_tarih);
                    $tarihler .= $eklenecek_tarih." - ";
                }
            }
            $kayitSayisi = 0;
            foreach($randevu_tarihleri as $tarihler){
                $yenirandevu = new Randevular();
                $yenirandevu->user_id = 2012;
                $yenirandevu->salon_id = self::mevcutsube($request);
                $yenirandevu->durum = 1;
                $yenirandevu->tarih = $tarihler;

                $yenirandevuhizmetpersonel = new RandevuHizmetler();
                $baslangicStr = null;
                $bitisStr     = null;
                if(!empty($request->saat) && !empty($request->saat_bitis)){
                    $baslangicStr = $request->saat;
                    $bitisStr     = $request->saat_bitis;
                } else {
                    // Tarih -> haftanin gunu (Mon=1..Sun=7)
                    $day = (int)date('N', strtotime($tarihler));
                    $cs = SalonCalismaSaatleri::where('salon_id', $request->sube)
                        ->where('haftanin_gunu', $day)
                        ->first();
                    if($cs){
                        $baslangicStr = $cs->baslangic_saati;
                        $bitisStr     = $cs->bitis_saati;
                    }
                }
                // Hala bulunamadiysa makul bir default
                if(empty($baslangicStr)) $baslangicStr = '09:00:00';
                if(empty($bitisStr))     $bitisStr     = '18:00:00';
                // H:i ise H:i:s'e tamamla
                if(strlen($baslangicStr) == 5) $baslangicStr .= ':00';
                if(strlen($bitisStr) == 5)     $bitisStr     .= ':00';

                $yenirandevu->saat       = $baslangicStr;
                $yenirandevu->saat_bitis = $bitisStr;
                $yenirandevuhizmetpersonel->saat       = $baslangicStr;
                $yenirandevuhizmetpersonel->saat_bitis = $bitisStr;

                try {
                    $baslangicSaati = Carbon::parse($baslangicStr);
                    $bitisSaati     = Carbon::parse($bitisStr);
                } catch (\Exception $e) {
                    \Log::warning('Saat kapama Carbon parse hatasi', ['baslangic'=>$baslangicStr,'bitis'=>$bitisStr,'err'=>$e->getMessage()]);
                    continue;
                }

                $yenirandevu->personel_notu = $request->personel_notu;
                $yenirandevu->olusturan_personel_id = Auth::guard('isletmeyonetim')->user()->id ?? null;
                $yenirandevu->save();

                $yenirandevuhizmetpersonel->randevu_id = $yenirandevu->id;
                $yenirandevuhizmetpersonel->hizmet_id  = 463;
                $yenirandevuhizmetpersonel->personel_id = !empty($request->personel) ? $request->personel : null;
                $sureDk = (int)$baslangicSaati->diffInMinutes($bitisSaati);
                if($sureDk <= 0) $sureDk = 15; // takvimde gorunsun (where sure_dk > 0 filtresi var)
                $yenirandevuhizmetpersonel->sure_dk = $sureDk;
                $yenirandevuhizmetpersonel->fiyat = 0;
                $yenirandevuhizmetpersonel->save();
                $kayitSayisi++;
            }
            return response()->json(['message' => "Saat kapama başarıyla eklendi ({$kayitSayisi} kayit)"]);
        } catch (\Throwable $e) {
            \Log::error('saatkapamaekle hatasi', ['err'=>$e->getMessage(), 'line'=>$e->getLine(), 'file'=>$e->getFile()]);
            return response()->json(['error' => 'Saat kapama eklenemedi: '.$e->getMessage()], 500);
        }
    }
    public function kapalisaatsil(Request $request)
    {
        Randevular::where('id',$request->randevu_id)->delete();
        RandevuHizmetler::where('randevu_id',$request->randevu_id)->delete();
        return 'Saat kapama başarıyla kaldırldı';
    }
    public function calismasaatigetir(Request $request){
       $tarih = $request->randevutarihi;
          $day = 0;
          if(date('D', strtotime($tarih))=='Mon') $day=1;
          else if(date('D', strtotime($tarih))=='Tue') $day=2;
          else if(date('D', strtotime($tarih))=='Wed') $day=3;
          else if(date('D', strtotime($tarih))=='Thu') $day=4;
          else if(date('D', strtotime($tarih))=='Fri') $day=5;
          else if(date('D', strtotime($tarih))=='Sat') $day=6;
          else if(date('D', strtotime($tarih))=='Sun') $day=7;
          $nowtime = date('H:i');
          $html = "<label>Başlangıç Saati</label><select name='saatbaslangic' id='saatbaslangic' class='form-control'>";
          $html_saat_bitis = "<label>Bitiş Saati</label><select name='saatbitis' id='saatbitis' class='form-control'>";
          $randevusaataraligi = Salonlar::where('id',Auth::guard('isletmeyonetim')->user()->salon_id)->value('randevu_saat_araligi');
          $mesaibaslangic =  SalonCalismaSaatleri::where('salon_id',Auth::guard('isletmeyonetim')->user()->salon_id)->where('calisiyor',1)->where('haftanin_gunu',$day)->value('baslangic_saati');
          $mesaibitis = SalonCalismaSaatleri::where('salon_id',Auth::guard('isletmeyonetim')->user()->salon_id)->where('calisiyor',1)->where('haftanin_gunu',$day)->value('bitis_saati');
          $dolusaatler = array();
          $musaitolmayansaatler = Randevular::join('randevu_hizmetler','randevu_hizmetler.randevu_id','=','randevular.id')->where('randevular.tarih',$request->randevutarihi)->where('durum',1)->groupBy('randevular.saat')->select('randevular.*')->get();
          foreach ($musaitolmayansaatler as $musaitolmayansaat) {
               $dolusaatler[] = date('H:i' ,strtotime($musaitolmayansaat->saat));
          }
          $saatindex = 0;
          for($j = strtotime(date('H:i', strtotime($mesaibaslangic) )) ; $j < strtotime(date('H:i', strtotime($mesaibitis))); $j+=($randevusaataraligi * 60)){
                // if( (date('H:i',$j) > $nowtime && date('Y-m-d') == date('Y-m-d', strtotime($request->randevutarihi)))  || date('Y-m-d') < date('Y-m-d', strtotime($request->randevutarihi)) )
                    if(!in_array(date('H:i',$j), $dolusaatler)||in_array(date('H:i',$j), $dolusaatler)){
                         $html .= '<option value="'.date('H:i',$j).'">'. date('H:i',$j).'</div>';
                      $html_saat_bitis .= '<option value="'.date('H:i',$j).'">'. date('H:i',$j).'</div>';
                    }
             $saatindex ++;
          }
          if($saatindex != 0){
              $html .="</select>";
              $html_saat_bitis .="</select>";
          }
          $htmlarray['saatbaslangic'] = array();
          $htmlarray['saatbitis'] =array();
          array_push($htmlarray['saatbaslangic'], $html);
           array_push($htmlarray['saatbitis'], $html_saat_bitis);
        return $htmlarray;
    }
