    public function toplusmsgonderme(Request $request){
        if($r = self::yetkiYoksa403($request, 'pazarlama.toplu_sms')) return $r;

        $isletme = Salonlar::where('id',self::mevcutsube($request))->first();

        $musteriIdler = $request->input('musteri_idler');
        if (is_string($musteriIdler)) {
            $decoded = json_decode($musteriIdler, true);
            $musteriIdler = is_array($decoded) ? $decoded : [];
        }
        if (!is_array($musteriIdler) || count($musteriIdler) === 0) {
            $musteriIdler = is_array($request->duallistbox_demo2) ? $request->duallistbox_demo2 : [];
        }
        $musteriIdler = array_values(array_unique(array_filter(array_map('intval', $musteriIdler))));

        if (count($musteriIdler) === 0) {
            return array(
                'text' => 'Lütfen en az 1 müşteri seçiniz!',
                'title' => 'Uyarı',
                'status' => 'warning',
            );
        }

        // Audit
        SalonAudit::log($isletme->id, 'toplu_sms_gonder', 'toplu_sms', null,
            count($musteriIdler).' alıcı',
            'Toplu SMS / WhatsApp gönderimi başlatıldı',
            ['alici_sayisi'=>count($musteriIdler), 'mesaj_ozet'=>mb_substr((string)$request->smsmesaj,0,140)]);

        if($isletme->yeni_sms==1)
        {
            $telefonlar = MusteriPortfoy::whereIn('user_id',$musteriIdler)->whereHas('users',function($q){
                $q->whereNotNull('cep_telefon');
            })->where('salon_id',$request->sube)->with('users:id,cep_telefon')->get()->pluck('users.cep_telefon')->flatten();
            $smsController = app()->make(SMSController::class);
            $gonderildi = $smsController->cokluSMSGonderVoiceTelekom($telefonlar,$request->smsmesaj,$isletme->id,'Toplu SMS');
            if($gonderildi)
            {
                return array(
                    'title' => 'Başarılı',
                    'status' => 'success',
                    'text' => 'Mesajlar başarıyla alıcılarınıza gönderildi.'
                );
            }
            else
                return array(
                    'title' => 'Hata',
                    'status' => 'error',
                    'text' => 'Mesajlarınız gönderilirken bir hata oluştu. Hata : '.$gonderildi,
                );
        }
        else
        {
            $mesajlar=array();
            foreach ($musteriIdler as $musteri) {
                $toplumusteri = User::where('id',$musteri)->first();
                if(!$toplumusteri) continue;
                if(MusteriPortfoy::where('user_id',$toplumusteri->id)->where('salon_id',$isletme->id)->value('kara_liste')!=1)
                    array_push($mesajlar, array("to"=>$toplumusteri->cep_telefon,"message"=> $request->smsmesaj));
            }
            if(count($mesajlar) > 0){
                return self::sms_gonder_bildirimli($request,$mesajlar,true,4,false);
            }
            else
            {
                return array(
                    'text' => 'Seçili müşteriler karalistenizde olduğu için mesajınız gönderilmemiştir',
                    'title' => 'Hata',
                    'status' => 'error',
                );
            }
        }

    }
    public function musteriliste(Request $request){
        $isletmeler = '';
        $isletme='';
        if(Auth::guard('satisortakligi')->check()) {
            $isletmeler = [15];
            $isletme = Salonlar::where('id',15)->first();
        } else {
            $isletmeler = Auth::guard('isletmeyonetim')->user()->yetkili_olunan_isletmeler->where('aktif',1)->pluck('salon_id')->toArray();
            $isletme= Salonlar::where('id',self::mevcutsube($request))->first();
        }
        
        if(!in_array(self::mevcutsube($request),$isletmeler)) {
            return view('isletmeadmin.yetkisizerisim');
            exit(0);
        }
        if(str_contains(self::lisans_sure_kontrol($request),'-')) {
            return view('isletmeadmin.lisanssurebitti',['isletme'=>$isletme]);
            exit(0);
        }
        // Yetki: bu sayfanin gerektirdigi yetki yoksa 403
        $_authUser = Auth::guard('isletmeyonetim')->user();
        if ($_authUser && !\App\Services\PersonelYetkiServisi::yetkiliYetkiVar($_authUser->id, self::mevcutsube($request), 'musteri.liste_gor')) {
            return view('isletmeadmin.yetkisizerisim');
            exit(0);
        }
        // Eski yonlendirme kaldirildi: personel rolu + 'musteri.tum_portfoy_gor'
        // yoksa kullanici musteri sayfasini ACABILMELI (kendi portfoyunu gorur).
        // Sayfa icindeki listeleme/butonlar zaten 'musteri.liste_gor' /
        // 'tum_portfoy_gor' yetkilerine gore davranir.

        if(count($isletmeler)>1 && !isset($_GET['sube'])) {
            return view('isletmeadmin.isletmesec',['isletmeler'=>$isletmeler,'isletme'=>$isletme]);
            exit(0);
        }
        
        $salonId = self::mevcutsube($request);
        $isletme = Salonlar::where('id', $salonId)->first();

        // Yetki: 'musteri.tum_portfoy_gor' kapaliysa personel sadece
        // kendi olusturdugu + satislarinda yer aldigi musterileri gorur.
        // Sayilar da bu filtreye uymali.
        $kendiPortfoyUserIds = \App\Services\PersonelYetkiServisi::musteriPortfoyKisitlamasi($request, $salonId, 'isletmeyonetim');

        // Durumlara göre müşteri sayılarını hesapla
        $tumMusteriSayisi = DB::table('musteri_portfoy')
            ->where('salon_id', $salonId)
            ->where('aktif', true)
            ->when($kendiPortfoyUserIds !== null, function ($q) use ($kendiPortfoyUserIds) {
                $q->whereIn('user_id', $kendiPortfoyUserIds ?: [0]);
            })
            ->count();

        $odemeYapmayanlarSayisi = DB::table('musteri_portfoy')
            ->join('users', 'musteri_portfoy.user_id', '=', 'users.id')
            ->where('musteri_portfoy.salon_id', $salonId)
            ->where('musteri_portfoy.aktif', true)
            ->when($kendiPortfoyUserIds !== null, function ($q) use ($kendiPortfoyUserIds) {
                $q->whereIn('musteri_portfoy.user_id', $kendiPortfoyUserIds ?: [0]);
            })
            ->whereNotExists(function ($q) use ($salonId) {
                $q->select(DB::raw(1))
                    ->from('tahsilatlar')
                    ->whereRaw('tahsilatlar.user_id = users.id')
                    ->where('tahsilatlar.salon_id', $salonId);
            })->count();

        $azIslemYapanlarSayisi = DB::table('musteri_portfoy')
            ->join('users', 'musteri_portfoy.user_id', '=', 'users.id')
            ->where('musteri_portfoy.salon_id', $salonId)
            ->where('musteri_portfoy.aktif', true)
            ->when($kendiPortfoyUserIds !== null, function ($q) use ($kendiPortfoyUserIds) {
                $q->whereIn('musteri_portfoy.user_id', $kendiPortfoyUserIds ?: [0]);
            })
            ->whereExists(function ($q) use ($salonId) {
                $q->select(DB::raw(1))
                    ->from('tahsilatlar')
                    ->whereRaw('tahsilatlar.user_id = users.id')
                    ->where('tahsilatlar.salon_id', $salonId)
                    ->groupBy('tahsilatlar.user_id')
                    ->havingRaw('COUNT(*) <= 2');
            })->count();

        $sadikMusterilerSayisi = DB::table('musteri_portfoy')
            ->join('users', 'musteri_portfoy.user_id', '=', 'users.id')
            ->where('musteri_portfoy.salon_id', $salonId)
            ->where('musteri_portfoy.aktif', true)
            ->when($kendiPortfoyUserIds !== null, function ($q) use ($kendiPortfoyUserIds) {
                $q->whereIn('musteri_portfoy.user_id', $kendiPortfoyUserIds ?: [0]);
            })
            ->whereExists(function ($q) use ($salonId) {
                $q->select(DB::raw(1))
                    ->from('tahsilatlar')
                    ->whereRaw('tahsilatlar.user_id = users.id')
                    ->where('tahsilatlar.salon_id', $salonId)
                    ->groupBy('tahsilatlar.user_id')
                    ->havingRaw('COUNT(*) >= 3');
            })->count();

        // Yeni eklenen müşteriler: başlangıç tarihinden sonra portföye eklenenler
        $yeniMusteriSayisi = DB::table('musteri_portfoy')
            ->where('salon_id', $salonId)
            ->where('aktif', true)
            ->where('created_at', '>=', self::YENI_MUSTERI_BASLANGIC)
            ->when($kendiPortfoyUserIds !== null, function ($q) use ($kendiPortfoyUserIds) {
                $q->whereIn('user_id', $kendiPortfoyUserIds ?: [0]);
            })
            ->count();

        $paketler = self::paket_liste_getir('',true,$request);
        return view('isletmeadmin.musteriler',[
            'bildirimler' => self::bildirimgetir($request),
            'paketler' => $paketler,
            'sayfa_baslik' => 'Müşteriler',
            'pageindex' => 4,
            'isletme' => $isletme,
            'kalan_uyelik_suresi' => self::lisans_sure_kontrol($request),
            'yetkiliolunanisletmeler' => $isletmeler,
            'tumMusteriSayisi' => $tumMusteriSayisi,
            'odemeYapmayanlarSayisi' => $odemeYapmayanlarSayisi,
            'azIslemYapanlarSayisi' => $azIslemYapanlarSayisi,
            'sadikMusterilerSayisi' => $sadikMusterilerSayisi,
            'yeniMusteriSayisi' => $yeniMusteriSayisi
        ]);
    }
