   public function musteri_liste_getir(Request $request, $durum)
    {
        $length = $request->input('length', 10);
        $start = $request->input('start', 0);
        $searchValue = $request->input('search.value');
        $currentPage = ($start / $length) + 1;
        $salonId = self::mevcutsube($request);

        // Yetki: 'musteri.tum_portfoy_gor' kapaliysa personel sadece
        // (a) kendi olusturdugu + (b) adisyon hizmet/urun/paket'lerinde
        // yer aldigi musterileri gorur.
        $kendiPortfoyUserIds = \App\Services\PersonelYetkiServisi::musteriPortfoyKisitlamasi($request, $salonId, 'isletmeyonetim');

        // Temel müşteri bilgilerini al
        $query = DB::table('musteri_portfoy')
            ->join('users', 'musteri_portfoy.user_id', '=', 'users.id')
            ->join('salonlar', 'musteri_portfoy.salon_id', '=', 'salonlar.id')
            ->select(
                'users.id',
                'users.name as ad_soyad',
                'users.cep_telefon as telefon',
                DB::raw('DATE_FORMAT(musteri_portfoy.created_at,"%d.%m.%Y") as kayit_tarihi'),
                'musteri_portfoy.id as portfoy_id'
            )
            ->where('musteri_portfoy.salon_id', $salonId)
            ->where('musteri_portfoy.aktif', true)
            ->where('salonlar.id', $salonId)
            ->when($kendiPortfoyUserIds !== null, function ($q) use ($kendiPortfoyUserIds) {
                // Bos liste -> hicbir musteri eslesmez (whereIn empty -> no rows)
                $q->whereIn('musteri_portfoy.user_id', $kendiPortfoyUserIds ?: [0]);
            });
    
        // Duruma göre filtreleme
        switch ($durum) {
            case 0: // Ödeme yapmayanlar
                $query->whereNotExists(function ($q) use ($salonId) {
                    $q->select(DB::raw(1))
                        ->from('tahsilatlar')
                        ->whereRaw('tahsilatlar.user_id = users.id')
                        ->where('tahsilatlar.salon_id', $salonId);
                });
                break;
                
            case 1: // Az işlem yapanlar
                $query->whereExists(function ($q) use ($salonId) {
                    $q->select(DB::raw(1))
                        ->from('tahsilatlar')
                        ->whereRaw('tahsilatlar.user_id = users.id')
                        ->where('tahsilatlar.salon_id', $salonId)
                        ->groupBy('tahsilatlar.user_id')
                        ->havingRaw('COUNT(*) <= 2');
                });
                break;
                
            case 2: // Uzun süredir gelmeyenler
                $query->whereExists(function ($q) use ($salonId) {
                    $q->select(DB::raw(1))
                        ->from('tahsilatlar')
                        ->whereRaw('tahsilatlar.user_id = users.id')
                        ->where('tahsilatlar.salon_id', $salonId)
                        ->groupBy('tahsilatlar.user_id')
                        ->havingRaw('COUNT(*) >= 3');
                        
                });
                break;
                
            case 3: // Tüm müşteriler
                // Ek filtre gerekmez
                break;

            case 4: // Yeni eklenen müşteriler (başlangıç tarihinden itibaren, en yeniden eskiye)
                // Toplu import edilen eski kayıtları hariç tut; sadece belirlenen
                // başlangıç tarihinden sonra portföye eklenenler listelenir.
                $query->where('musteri_portfoy.created_at', '>=', self::YENI_MUSTERI_BASLANGIC);
                break;
        }

        // Arama filtresi
        if ($searchValue) {
            $query->where(function($q) use ($searchValue) {
                $q->where('users.name', 'like', '%'.$searchValue.'%')
                  ->orWhere('users.cep_telefon', 'like', '%'.$searchValue.'%');
            });
        }

        // Sıralama ve sayfalama
        if ($durum == 4) {
            // En yeni eklenen müşteri en üstte
            $query->orderBy('musteri_portfoy.created_at', 'desc')
                  ->orderBy('musteri_portfoy.id', 'desc');
        } else {
            $query->orderBy('users.id', 'desc');
        }
        $musteriler = $query->paginate($length, ['*'], 'page', $currentPage);
    
        // Toplu randevu bilgilerini al (N+1 problemini önlemek için)
        $userIds = collect($musteriler->items())->pluck('id')->toArray();
        
        if (!empty($userIds)) {
            $randevuBilgileri = DB::table('randevular')
                ->select(
                    'user_id',
                    DB::raw('COUNT(*) as randevu_sayisi'),
                    DB::raw('MAX(tarih) as son_randevu_tarihi')
                )
                ->whereIn('user_id', $userIds)
                ->where('salon_id', $salonId)
                ->groupBy('user_id')
                ->get()
                ->keyBy('user_id');
    
            // Ödeme bilgilerini al
            $odemeBilgileri = DB::table('tahsilatlar')
                ->select(
                    'user_id',
                    DB::raw('SUM(tutar) as toplam_odeme')
                )
                ->whereIn('user_id', $userIds)
                ->where('salon_id', $salonId)
                ->groupBy('user_id')
                ->get()
                ->keyBy('user_id');
    
            // Yetki kontrolleri: telefon mask + islemler dropdown linkleri
            $u = \Auth::guard('isletmeyonetim')->user();
            $telGor = $u && $salonId
                ? \App\Services\PersonelYetkiServisi::yetkiliYetkiVar($u->id, $salonId, 'musteri.telefon_gor')
                : true;
            $detayGor   = $u && $salonId
                ? \App\Services\PersonelYetkiServisi::yetkiliYetkiVar($u->id, $salonId, 'musteri.detay_gor')
                : true;
            $duzenleVar = $u && $salonId
                ? \App\Services\PersonelYetkiServisi::yetkiliYetkiVar($u->id, $salonId, 'musteri.ekle_duzenle')
                : true;
            $silVar     = $u && $salonId
                ? \App\Services\PersonelYetkiServisi::yetkiliYetkiVar($u->id, $salonId, 'musteri.sil')
                : true;
            $anketVar   = $u && $salonId
                ? \App\Services\PersonelYetkiServisi::yetkiliYetkiVar($u->id, $salonId, 'pazarlama.anket_yonet')
                : true;

            // Verileri birleştir
            $musteriler->getCollection()->transform(function ($item) use ($randevuBilgileri, $odemeBilgileri,$salonId,$telGor,$detayGor,$duzenleVar,$silVar,$anketVar) {
                $randevu = $randevuBilgileri[$item->id] ?? null;
                $odeme = $odemeBilgileri[$item->id] ?? null;

                if (!$telGor && isset($item->telefon)) {
                    $item->telefon = \App\PersonelYetkiSabitleri::telefonMaskele($item->telefon);
                }

                $item->randevu_sayisi = $randevu ? $randevu->randevu_sayisi : 0;
                $item->son_randevu_tarihi = $randevu && $randevu->son_randevu_tarihi ?
                    date('d.m.Y', strtotime($randevu->son_randevu_tarihi)) : '-';
                $item->odenen = $odeme ?
                    '<button class="btn btn-success btn-block" style="line-height:5px">' .
                    number_format($odeme->toplam_odeme, 2, ',', '.') . '</button>' :
                    '<button class="btn btn-success btn-block" style="line-height:5px">0,00</button>';

                // Yetki bazli linkleri kos
                $detayItem = $detayGor
                    ? '<a class="dropdown-item" href="/isletmeyonetim/musteridetay/'.$item->id.'?sube='.$salonId.'"><i class="fa fa-eye"></i> Detaylı Bilgi</a>'
                    : '';
                $duzenleItem = $duzenleVar
                    ? '<a class="dropdown-item" href="#" data-toggle="modal" data-target="#musteri-bilgi-modal" name="musteri_duzenle" data-value="'.$item->id.'"><i class="fa fa-edit"></i> Düzenle</a>'
                    : '';
                $silItem = $silVar
                    ? '<a class="dropdown-item" href="#" name="musteri_sil" data-value="'.$item->portfoy_id.'"><i class="fa fa-minus"></i> Sil</a>'
                    : '';
                $anketItem = $anketVar
                    ? '<a class="dropdown-item" href="#" onclick="anketHizliGonderListe('.$item->id.', this); return false;" style="color:#25D366;"><i class="fa fa-comments"></i> Anket Gönder</a>'
                    : '';

                // Hicbir aksiyon yoksa dropdown gosterme
                if ($detayItem === '' && $duzenleItem === '' && $silItem === '' && $anketItem === '') {
                    $item->islemler = '';
                } else {
                    $item->islemler = '<div class="dropdown">
                        <a class="btn btn-link font-24 p-0 line-height-1 no-arrow dropdown-toggle" href="#" role="button" data-toggle="dropdown">
                            <i class="dw dw-more"></i>
                        </a>
                        <div class="dropdown-menu dropdown-menu-right dropdown-menu-icon-list">'
                        .$detayItem.$duzenleItem.$anketItem.$silItem.
                        '</div></div>';
                }

                return $item;
            });
        }
    
        return response()->json([
            'data' => $musteriler->items(),
            'draw' => $request->input('draw'),
            'recordsTotal' => $musteriler->total(),
            'recordsFiltered' => $musteriler->total(),
        ]);
    }
    public function musteribilgiguncelle(Request $request){
         $musteri = User::where('id',$request->musteriid)->first();
         $_eski = ['ad'=>$musteri->name,'tel'=>$musteri->cep_telefon,'email'=>$musteri->email];
         $musteri->name = $request->adsoyad;
         $musteri->cep_telefon = $request->telefon;
         $musteri->dogum_tarihi = $request->dogum_tarihi;
         $musteri->cinsiyet = $request->cinsiyet;
         $musteri->email = $request->email;
         $musteri->adres = $request->adres;
         // TC Kimlik No: duzenleme formundan gelirse kaydet (bos gelirse mevcut degeri koru)
         if ($request->has('tc_kimlik_no')) {
             $_tc = trim((string) $request->tc_kimlik_no);
             $musteri->tc_kimlik_no = $_tc !== '' ? $_tc : null;
         }
         $musteri->save();
         // Audit
         SalonAudit::log(self::mevcutsube($request), 'musteri_bilgi_guncelle', 'musteri', $musteri->id,
             $musteri->name,
             'Müşteri kişisel bilgileri güncellendi',
             ['eski'=>$_eski, 'yeni'=>['ad'=>$musteri->name,'tel'=>$musteri->cep_telefon,'email'=>$musteri->email]]);
    }
    public function musteriportfoykaldir(Request $request){
        $portfoymusteri = MusteriPortfoy::where('user_id',$request->musteriid)->where('salon_id',self::mevcutsube($request))->first();
        $result['sonuc'] = array();
        $result['liste'] = array();
        $result['toplammusteri'] = array();
        if($portfoymusteri){
            $adsoyad = $portfoymusteri->users->name;
            // Audit
            SalonAudit::log(self::mevcutsube($request), 'musteri_portfoy_kaldir', 'musteri', $request->musteriid,
                $adsoyad ?: ('Müşteri #'.$request->musteriid),
                'Müşteri portföyden kaldırıldı (hard delete)');
            $portfoymusteri->delete();
            array_push($result['sonuc'], $adsoyad .' isimli müşteri portföyünüzden başarıyla kaldırıldı');
        }
        $portfoy = MusteriPortfoy::where('salon_id',self::mevcutsube($request))->get();
        $portfoytablohtml = "";
        $musteriprofilresim = "";
        foreach ($portfoy as $key => $value) {
            $user = User::where('id',$value->user_id)->first();
            $cinsiyet = "";
            $tur = "";
            $renk1 = "";
            if($user->profil_resim!= null ||$user->profil_resim != '' )
                $musteriprofilresim = $user->profil_resim;
            else
                $musteriprofilresim = 'public/isletmeyonetim_assets/img/avatar.png';
            if($user->cinsiyet == '0')
                $cinsiyet = 'Bayan';
            else if($user->cinsiyet == '1')
                $cinsiyet = 'Bay';
            else
                $cinsiyet = '';
            if($value->tur == 1){
                $tur = 'A';
                $renk1 = '#FF4E00';
            }
            else if($value->tur == 0){
                $tur = 'KM';
                $renk1 = '#1266f1';
            }
            $portfoytablohtml .= '<tr><td class="user-avatar"><img src="http://'.$_SERVER['HTTP_HOST'].'/'.$musteriprofilresim.'" alt="Profil Resmi"></td><td>'.$user->name.'</td><td>'.$cinsiyet.'</td><td style="color:white"><span style="position:relative;float:left;width:30px; text-align:center;background-color:'.$renk1.';padding:5px">'.$tur.'</span></td>
            <td>'.$user->email.'</td>
            <td>'.$user->cep_telefon.'</td>
            <td>'.Randevular::where('user_id',$user->id)->count().'</td>';
            if(SalonPuanlar::where('user_id',$user->id)->value('puan') == null || SalonPuanlar::where('user_id',$user->id)->value('puan') == '')
             $portfoytablohtml .= '<td>0</td>';
             else
                $portfoytablohtml .= '<td>'.SalonPuanlar::where('user_id',$user->id)->value('puan').'</td>';
            $portfoytablohtml .= '<td>
                        <a class="btn btn-space btn-success btn-xs" data-value="'.$user->id.'" href="/isletmeyonetim/musteridetay/'.$user->id.'"><span class="icon mdi mdi-settings"></span> Detaylar</a>
                  <button class="btn btn-space btn-danger btn-xs" data-value="'.$user->id.'" name="musterikaldir"><span class="icon mdi mdi-delete"></span> Kaldır</button>
            </td></tr>';
        }
        array_push($result['toplammusteri'], $portfoy->count());
        array_push($result['liste'], $portfoytablohtml);
        return $result;
    }
   public function yenimusterilistesiekle(Request $request)
   {
    $isletmeler = Auth::guard('isletmeyonetim')->user()->yetkili_olunan_isletmeler->where('aktif',1)->pluck('salon_id')->toArray();
    $resulthtml['sonuc'] = [];
    $resulthtml['liste'] = [];
    $resulthtml['toplammusteri'] = [];
    $portfoytablohtml = "";
    if ($request->hasFile('listedosyasi_yeni_musteri')) {
        $file = $request->file('listedosyasi_yeni_musteri');
        // Dosyayı belirli bir yere kaydetme
        $hedef = $file->storeAs('public/listeler', str_replace(' ', '_', $file->getClientOriginalName()));
        // Excel verilerini işle
        $import = new MusteriImport($_POST['sube']);
        Excel::import($import, $hedef);
        $count = $import->getImportedCount();
        if (count($isletmeler) > 1) {
            array_push($resulthtml['sonuc'], "$count adet müşteri listenize başarı ile eklendi.");
            array_push($resulthtml['liste'], self::musteri_liste_getir($request, 3));
            array_push($resulthtml['toplammusteri'], $count);
        }
    } else {
        array_push($resulthtml['sonuc'], 'Lütfen excel dosyası yükleyiniz');
        array_push($resulthtml['liste'], $portfoytablohtml);
    }
    return $resulthtml;
   }

    /**
     * Mevcut subedeki cinsiyeti bos musterilerin cinsiyetini ad-soyaddan otomatik tespit eder.
     * Sadece bos olanlar guncellenir, dolu olanlara dokunulmaz.
     */
    public function cinsiyetOtomatikDoldur(Request $request)
    {
        $sube = self::mevcutsube($request);
        if (!$sube) {
            return response()->json(['status' => 'error', 'mesaj' => 'Sube bulunamadi'], 400);
        }

        $userIds = MusteriPortfoy::where('salon_id', $sube)
            ->where('aktif', true)
            ->pluck('user_id')
            ->unique()
            ->values()
            ->toArray();

        if (empty($userIds)) {
            return response()->json([
                'status' => 'success',
                'guncellenen' => 0,
                'kalan_bos' => 0,
                'mesaj' => 'Bu subede aktif musteri bulunamadi.'
            ]);
        }

        $guncellenen = 0;
        $kalanBos = 0;

        User::whereIn('id', $userIds)
            ->where(function ($q) {
                $q->whereNull('cinsiyet')->orWhere('cinsiyet', '');
            })
            ->select('id', 'name', 'cinsiyet')
            ->chunkById(500, function ($users) use (&$guncellenen, &$kalanBos) {
                foreach ($users as $user) {
                    $tahmin = \App\Helpers\CinsiyetTahmin::tahmin($user->name);
                    if ($tahmin !== null) {
                        $user->cinsiyet = $tahmin;
                        $user->save();
                        $guncellenen++;
                    } else {
                        $kalanBos++;
                    }
                }
            });

        return response()->json([
            'status' => 'success',
            'guncellenen' => $guncellenen,
            'kalan_bos' => $kalanBos,
            'mesaj' => "{$guncellenen} müşterinin cinsiyeti otomatik olarak belirlendi. {$kalanBos} müşterinin adı sözlükte bulunmadığı için belirsiz kaldı."
        ]);
    }

    public function musteridetay(Request $request,$id){
         $isletmeler = '';
        $isletme='';
        if(Auth::guard('satisortakligi')->check())
        {
            $isletmeler = [15];
            $isletme = Salonlar::where('id',15)->first();
        }
        else{
            $isletmeler = Auth::guard('isletmeyonetim')->user()->yetkili_olunan_isletmeler->where('aktif',1)->pluck('salon_id')->toArray();
            $isletme= Salonlar::where('id',self::mevcutsube($request))->first();
        }


        if(!in_array(self::mevcutsube($request),$isletmeler ))
        {
            return view('isletmeadmin.yetkisizerisim');
            exit(0);
        }
        if(str_contains(self::lisans_sure_kontrol($request),'-'))
        {
            return view('isletmeadmin.lisanssurebitti',['isletme'=>$isletme]);
            exit(0);
        }
        // Yetki: detay sayfasi musteri.detay_gor ile acilir; ANCAK sadece not yazma
        // (not_yaz) veya gecmis satis gorme (gecmis_satis_gor) yetkisi olan personel de
        // bu yetkilerini kullanabilmek icin sayfayi acabilmeli. Sayfa icindeki hassas
        // bolumler (gecmis satis, duzenle) blade'de kendi yetkileriyle gizlenir.
        $_authUser = Auth::guard('isletmeyonetim')->user();
        if ($_authUser) {
            $_sube = self::mevcutsube($request);
            $_detayErisim = \App\Services\PersonelYetkiServisi::yetkiliYetkiVar($_authUser->id, $_sube, 'musteri.detay_gor')
                || \App\Services\PersonelYetkiServisi::yetkiliYetkiVar($_authUser->id, $_sube, 'musteri.not_yaz')
                || \App\Services\PersonelYetkiServisi::yetkiliYetkiVar($_authUser->id, $_sube, 'musteri.gecmis_satis_gor');
            if (!$_detayErisim) {
                return view('isletmeadmin.yetkisizerisim');
                exit(0);
            }
        }
        // Eski yonlendirme kaldirildi — musteridetay yetki kontrolu blade'de
        // ve listede filtreleniyor. Personel detaya gelebildiyse erisim olur.

        if(count($isletmeler)>1 && !isset($_GET['sube']))
        {
            return view('isletmeadmin.isletmesec',['isletmeler'=>$isletmeler,'isletme'=>$isletme]);
            exit(0);
        }
        $isletme = Salonlar::where('id',self::mevcutsube($request))->first();
        $randevular_liste = self::randevu_liste_getir($request,'','','','','','',self::mevcutsube($request),$id);

        // Eager loading ile N+1 sorunu onlendi
        $randevular = Randevular::where('user_id',$id)
            ->where('salon_id',self::mevcutsube($request))
            ->with(['hizmetler' => function($q){ $q->with('hizmetler'); }])
            ->orderBy('tarih','desc')
            ->get();

        $portfoy = MusteriPortfoy::where("user_id",$id)->where('salon_id',$isletme->id)->first();
        $paketler = self::paket_liste_getir('',true,$request);

        // Arsiv: tek sorgu, PHP tarafinda filtreleme (5 sorgu yerine 1)
        $form = self::arsiv_liste_getir($request,'',$id);
        $form_onayli = self::arsiv_liste_getir($request,0,$id);
        $form_iptal = self::arsiv_liste_getir($request,1,$id);
        $form_beklenen = self::arsiv_liste_getir($request,2,$id);
        $form_harici = self::arsiv_liste_getir($request,3,$id);

        $seanslar = ''/*self::seans_getir($request,0,'1970-01-01 00:00:00',date('Y-m-d 23:59:59'),$id);*/;
        // Isletme izolasyonu: sadece bu subenin gorselleri.
        // salon_id NULL olan eski kayitlar (etiketlenmeden yuklenmis) her subede
        // gorunmeye devam eder; yeni yuklemeler artik salon_id ile etiketleniyor.
        $islemler = Islemler::where('user_id',$id)
            ->where(function($q) use ($isletme){
                $q->where('salon_id',$isletme->id)
                  ->orWhereNull('salon_id');
            })
            ->get();

        // Blade'de tekrarlanan sorgular burada bir kez calistirilir
        $tahsilatlar_count = \App\Tahsilatlar::where('user_id',$id)->where('salon_id',$isletme->id)->count();
        $son_tahsilat_tarihi = \App\Tahsilatlar::where('user_id',$id)->where('salon_id',$isletme->id)->orderBy('id','desc')->value('created_at');
        $kara_liste = $portfoy ? $portfoy->kara_liste : 0;
        $is_personel_rolu = \DB::table('model_has_roles')->where('role_id',5)->where('model_id',Auth::guard('isletmeyonetim')->user()->id)->where('salon_id',$isletme->id)->count() > 0;
        $odeme_yontemleri = \App\OdemeYontemleri::all();
        $bankalar = \App\SatisOrtakligiModel\Bankalar::all();

        // Harici tahsilat modali icin salon bazli hizmet/urun/paket listeleri
        $harici_hizmetler = DB::table('salon_sunulan_hizmetler')
            ->join('hizmetler','salon_sunulan_hizmetler.hizmet_id','=','hizmetler.id')
            ->where('salon_sunulan_hizmetler.salon_id',$isletme->id)
            ->where('salon_sunulan_hizmetler.aktif',true)
            ->select('hizmetler.id as id','hizmetler.hizmet_adi as ad',
                DB::raw('COALESCE(salon_sunulan_hizmetler.son_fiyat, salon_sunulan_hizmetler.baslangic_fiyat, hizmetler.fiyat, 0) as fiyat'))
            ->orderBy('hizmetler.hizmet_adi')->get();
        $harici_urunler = DB::table('urunler')
            ->where('salon_id',$isletme->id)->where('aktif',true)
            ->select('id','urun_adi as ad','fiyat')->orderBy('urun_adi')->get();
        $harici_paketler = DB::table('paketler')
            ->where('salon_id',$isletme->id)
            ->select('id','paket_adi as ad','fiyat')->orderBy('paket_adi')->get();

        return view('isletmeadmin.musteridetay',[
            'harici_hizmetler'=>$harici_hizmetler,
            'harici_urunler'=>$harici_urunler,
            'harici_paketler'=>$harici_paketler,
            'harici_sabit_musteri_id'=>$portfoy->users->id,
            'harici_sabit_musteri_adi'=>$portfoy->users->name,
            'bildirimler'=>self::bildirimgetir($request),
            'paketler'=>$paketler,
            'pageindex'=>41,
            'sayfa_baslik'=> $portfoy->users->name,
            'isletme'=>$isletme,
            'portfoy'=>$portfoy,
            'arsiv'=>$form,
            'musteri_bilgi'=>$portfoy->users,
            'randevular'=>$randevular,
            'kalan_uyelik_suresi' => self::lisans_sure_kontrol($request),
            'arsiv_onayli'=>$form_onayli,
            'arsiv_iptal'=>$form_iptal,
            'arsiv_beklenen'=>$form_beklenen,
            'arsiv_harici'=>$form_harici,
            'randevular_liste'=>$randevular_liste,
            'urun_drop'=>self::urundropliste($request),
            'islemler'=>$islemler,
            'yetkiliolunanisletmeler'=>$isletmeler,
            'seanslar'=>$seanslar,
            // Performans: blade icindeki sorgular kaldirildi
            'tahsilatlar_count'=>$tahsilatlar_count,
            'son_tahsilat_tarihi'=>$son_tahsilat_tarihi,
            'kara_liste'=>$kara_liste,
            'is_personel_rolu'=>$is_personel_rolu,
            'odeme_yontemleri'=>$odeme_yontemleri,
            'bankalar'=>$bankalar,
        ]);
    }

    public function musteriexceleaktar(){
        $musteriler = MusteriPortfoy::where('salon_id',self::mevcutsube($request))->get();
        $musteri_array[] = array('Ad Soyad','Cinsiyet','Tür','E-posta','Cep Telefon','Randevu Sayısı','Puanlama');
        foreach ($musteriler as $key => $value) {
            $user=User::where('id',$value->user_id)->first();
            $tur = "";
            $cinsiyet = "";
            if($value->tur == 1)
                    $tur = 'randevumcepte.com.tr';
            else if($value->tur == 0)
                $tur = 'Ekleme & Kendi Müşterilerim';
            if($user->cinsiyet == 0)
                $cinsiyet = 'Bayan';
            else if($user->cinsiyet == 1)
                $cinsiyet = 'Bay';
            $musteri_array[] = array(
                'Ad Soyad' => $user->name,
                'Cinsiyet' => $cinsiyet,
                'Tür' => $tur,
                'E-posta' => $user->email,
                'Cep Telefon' => $user->cep_telefon,
                'Randevu Sayısı' => Randevular::where('user_id',$user->id)->count(),
                'Puanlama' => SalonPuanlar::where('user_id',$user->id)->value('puan'),
            );
        }
         Excel::create('Müşteri Data',function($excel) use($musteri_array){
                $excel->setTitle('Müşteri Data');
                $excel->sheet('Müşteri Data',function($sheet) use($musteri_array){
                    $sheet->fromArray($musteri_array,null,'A1',false,false);
                });
        })->export('xlsx');
    }
    public function avantajraporgetir(Request $request){
        $avantajlar = SalonKampanyalar::where('salon_id',Auth::guard('isletmeyonetim')->user()->salon_id)->get();
        $raporhtml = "";
        foreach ($avantajlar as $key => $value) {
            $toplamsatis = SatinAlinanKampanyalar::where('kampanya_id',$value->id)->where('odeme_yapildi',1)->where('created_at','>=',date('Y-m-d',strtotime($request->tarihbaslangic)))->where('created_at','<=',date('Y-m-d',strtotime($request->tarihbitis)))->count();
            $kullanilan = SatinAlinanKampanyalar::where('kampanya_id',$value->id)->where('odeme_yapildi',1)->where('kullanildi',1)->where('created_at','>=',date('Y-m-d',strtotime($request->tarihbaslangic)))->where('created_at','<=',date('Y-m-d',strtotime($request->tarihbitis)))->count();
             $kullanilmayan = SatinAlinanKampanyalar::where('kampanya_id',$value->id)->where('odeme_yapildi',1)->where('kullanildi','!=',1)->where('created_at','>=',date('Y-m-d',strtotime($request->tarihbaslangic)))->where('created_at','<=',date('Y-m-d',strtotime($request->tarihbitis)))->count();
            $raporhtml .= "<tr><td>".$value->kampanya_aciklama."</td><td>".$toplamsatis."</td><td>".$kullanilan."</td><td>".$kullanilmayan."</td>";
            if($value->onayli == 1)
                $raporhtml .= "<td style='color:green;font-weight:bold'>Aktif</td>";
            if($value->onayli == 0)
                $raporhtml .= "<td style='color:red;font-weight:bold'>Pasif</td>";
            $raporhtml .="</tr>";
        }
        echo $raporhtml;
    }
