    /**
     * Stok Yonetimi v2 — web blade'i icin JSON proxy.
     * Salon_id otomatik enjekte edilir, StokController metodlari cagrilir.
     */
    public function stokApi(Request $request, $action)
    {
        $salonid = self::mevcutsube($request);

        // Yetki: sube client'tan geliyor; sadece kullanicinin yetkili oldugu
        // isletmeye izin ver (baska isletmenin stogunu okuma/yazmayi engelle).
        $isletmeler = Auth::guard('satisortakligi')->check()
            ? [15]
            : Auth::guard('isletmeyonetim')->user()->yetkili_olunan_isletmeler->pluck('salon_id')->toArray();
        if (!in_array($salonid, $isletmeler)) {
            return response()->json(['status' => 'error', 'mesaj' => 'Bu isletme icin yetkiniz yok'], 403);
        }

        // Yazma aksiyonlari icin aksiyona ozel yetki kontrolu (her aksiyon kendi anahtarina).
        // Okuma aksiyonlari (ozet/listeler/raporlar) sayfa gate'ine birakildi.
        $_stokYetkiHaritasi = [
            'alis-girisi'      => 'urun.stok_giris',
            'transfer'         => 'urun.stok_giris',
            'manuel-hareket'   => 'urun.stok_giris',
            'sayim'            => 'urun.stok_sayim',
            'tedarikci-kaydet' => 'urun.tedarikci_yonet',
            'tedarikci-sil'    => 'urun.tedarikci_yonet',
            'urun-kaydet'      => 'urun.tanim_olustur',
            'urun-sil'         => 'urun.tanim_olustur',
            'kategori-kaydet'  => 'urun.tanim_olustur',
            'kategori-sil'     => 'urun.tanim_olustur',
            'depo-kaydet'      => 'urun.tanim_olustur',
            'depo-sil'         => 'urun.tanim_olustur',
            'recete-kaydet'    => 'urun.tanim_olustur',
            'recete-sil'       => 'urun.tanim_olustur',
            'hizli-satis'      => 'urun.sat',
        ];
        if (isset($_stokYetkiHaritasi[$action]) && ($r = self::yetkiYoksa403($request, $_stokYetkiHaritasi[$action]))) {
            return $r;
        }

        $stok = new StokController();

        switch ($action) {
            case 'ozet':                return $stok->ozet($request, $salonid);
            case 'dusuk-stok':          return $stok->dusukStokListesi($request, $salonid);
            case 'urunler':             return $stok->urunListesi($request, $salonid);
            case 'urun':                return $stok->urunDetay($request, $request->id);
            case 'urun-barkod':         return $stok->urunBarkodAra($request, $salonid);
            case 'urun-kaydet':         return $stok->urunKaydet($request, $salonid);
            case 'urun-sil':            return $stok->urunSil($request);
            case 'kategoriler':         return $stok->kategoriListesi($request, $salonid);
            case 'kategori-kaydet':     return $stok->kategoriKaydet($request, $salonid);
            case 'kategori-sil':        return $stok->kategoriSil($request);
            case 'depolar':             return $stok->depoListesi($request, $salonid);
            case 'depo-kaydet':         return $stok->depoKaydet($request, $salonid);
            case 'depo-sil':            return $stok->depoSil($request);
            case 'tedarikciler':        return $stok->tedarikciListesi($request, $salonid);
            case 'tedarikci-kaydet':    return $stok->tedarikciKaydet($request, $salonid);
            case 'tedarikci-sil':       return $stok->tedarikciSil($request);
            case 'hareketler':          return $stok->hareketListesi($request, $salonid);
            case 'manuel-hareket':      return $stok->manuelHareket($request, $salonid);
            case 'alis-girisi':         return $stok->alisGirisi($request, $salonid);
            case 'transfer':            return $stok->transfer($request, $salonid);
            case 'sayim':               return $stok->sayimUygula($request, $salonid);
            case 'hizli-satis':         return $stok->hizliSatis($request, $salonid);
            case 'urun-satis-raporu':   return $stok->urunSatisRaporu($request, $request->urun_id);
            case 'receteler':           return $stok->receteListesi($request, $salonid);
            case 'recete-kaydet':       return $stok->receteKaydet($request, $salonid);
            case 'recete-sil':          return $stok->receteSil($request);
            default:
                return response()->json(['status' => 'error', 'mesaj' => 'Bilinmeyen aksiyon: '.$action], 404);
        }
    }
    public function urun_ekle_guncelle(Request $request){
        if($r = self::yetkiYoksa403($request, 'urun.tanim_olustur')) return $r;
        $yeni = false;
        $_eski_urun_snap = null;
        if($request->urun_id == 0){
            $urun = new Urunler();
            $yeni = true;
            $returntext = "Ürün başarıyla eklendi";
        }
        else{
            $urun = Urunler::where('id',$request->urun_id)->first();
            $_eski_urun_snap = ['adi'=>$urun->urun_adi, 'fiyat'=>$urun->fiyat, 'stok'=>$urun->stok_adedi, 'barkod'=>$urun->barkod];
            $returntext = "Ürün başarıyla güncellendi";
        }
        $oncekiStok = (float) ($urun->stok_adedi ?? 0);
        $salonId = self::mevcutsube($request);

        $urun->urun_adi          = $request->urun_adi;
        $urun->fiyat             = $request->fiyat;
        $urun->barkod            = $request->barkod;
        $urun->dusuk_stok_siniri = $request->dusuk_stok_siniri;
        $urun->salon_id          = $salonId;
        $urun->aktif             = true;

        $depo = StokController::varsayilanDepoyuGetirVeyaOlustur((int) $salonId);
        if (empty($urun->varsayilan_depo_id)) {
            $urun->varsayilan_depo_id = $depo->id;
        }
        $urun->save();

        $istenenStok = (float) ($request->stok_adedi ?? $oncekiStok);
        $fark = $istenenStok - $oncekiStok;
        if ($yeni && $istenenStok != 0) {
            StokController::hareketKaydet([
                'salon_id'     => $salonId,
                'urun_id'      => $urun->id,
                'depo_id'      => $urun->varsayilan_depo_id,
                'miktar'       => $istenenStok,
                'hareket_tipi' => 'acilis',
                'aciklama'     => 'Web panel - urun olusturuldu',
            ]);
        } elseif (!$yeni && abs($fark) > 0.0001) {
            StokController::hareketKaydet([
                'salon_id'     => $salonId,
                'urun_id'      => $urun->id,
                'depo_id'      => $urun->varsayilan_depo_id,
                'miktar'       => $fark,
                'hareket_tipi' => 'manuel',
                'aciklama'     => 'Web panel - stok duzeltme',
            ]);
        }

        // Audit
        SalonAudit::log($salonId, $yeni ? 'urun_ekle' : 'urun_guncelle', 'urun', $urun->id,
            $urun->urun_adi,
            $yeni ? 'Yeni ürün eklendi' : 'Ürün güncellendi',
            $yeni ? ['fiyat'=>$urun->fiyat, 'stok'=>$istenenStok] : ['eski'=>$_eski_urun_snap, 'yeni'=>['adi'=>$urun->urun_adi, 'fiyat'=>$urun->fiyat, 'stok'=>$istenenStok, 'barkod'=>$urun->barkod]]);

        return self::urun_liste_getir($request,$returntext);
    }
    public function paket_ekle_guncelle(Request $request){
        if($r = self::yetkiYoksa403($request, 'paket.tanim_olustur')) return $r;
        $paket="";
        $returntext="";
        $_yeni_paket = false;
        if($request->paket_id == 0){
            $paket = new Paketler();
            $returntext = "Paket başarıyla eklendi";
            $_yeni_paket = true;
        }
        else{
            $paket = Paketler::where('id',$request->paket_id)->first();
            $returntext = "Paket başarıyla güncellendi";
        }
        $paket->paket_adi = $request->adpaket;
        $paket->aktif = true;
        $paket->salon_id = $request->sube;
        $paket->fiyat = $request->fiyatlar;
        $paket->sure = $request->paketsure;
        $paket->miktar = $request->seanslar;
        $paket->save();
        // Audit
        SalonAudit::log($request->sube, $_yeni_paket ? 'paket_ekle' : 'paket_guncelle', 'paket', $paket->id,
            $paket->paket_adi,
            $_yeni_paket ? 'Yeni paket eklendi' : 'Paket güncellendi',
            ['fiyat'=>$paket->fiyat, 'seans'=>$paket->miktar, 'sure'=>$paket->sure]);
        $toplamtutar = 0;
        PaketHizmetler::where('paket_id',$paket->id)->delete();
        foreach($request->hizmetler as $key => $paket_hizmet)
        {
            $pakethizmet = new PaketHizmetler();
            $pakethizmet->paket_id = $paket->id;
            $pakethizmet->hizmet_id = $paket_hizmet;
            /*$pakethizmet->seans = $request->seanslar[$key];
            $pakethizmet->fiyat = $request->fiyatlar[$key];
            $toplamtutar += $request->fiyatlar[$key];*/
            $pakethizmet->save();
        }
        return array(
            'paketler' => self::paket_liste_getir($returntext,false,$request),
            'eklenen_paket_id' =>$paket->id,
            'eklenen_paket' => $paket->paket_adi,
            'toplam_tutar' => $toplamtutar
        );
    }
    public function paket_kopyala_salonlar_arasi($kaynak_salon_id, $hedef_salon_id)
    {
        $kaynak_salon_id = (int) $kaynak_salon_id;
        $hedef_salon_id  = (int) $hedef_salon_id;
        if ($kaynak_salon_id <= 0 || $hedef_salon_id <= 0 || $kaynak_salon_id === $hedef_salon_id) {
            return response()->json(['hata' => 'Gecersiz salon id'], 400);
        }

        $kaynak_paketler = Paketler::where('salon_id', $kaynak_salon_id)->get();
        if ($kaynak_paketler->isEmpty()) {
            return response()->json(['hata' => "Kaynak salon ($kaynak_salon_id) icin paket bulunamadi"], 404);
        }

        $eklenen_paket = 0;
        $eklenen_paket_hizmet = 0;
        $detay = [];

        DB::beginTransaction();
        try {
            foreach ($kaynak_paketler as $eski) {
                $yeni = new Paketler();
                $yeni->paket_adi = $eski->paket_adi;
                $yeni->aktif     = $eski->aktif;
                $yeni->salon_id  = $hedef_salon_id;
                $yeni->tip       = $eski->tip;
                $yeni->hizmet_id = $eski->hizmet_id;
                $yeni->fiyat     = $eski->fiyat;
                $yeni->miktar    = $eski->miktar;
                $yeni->sure      = $eski->sure;
                $yeni->save();
                $eklenen_paket++;

                $eski_hizmetler = PaketHizmetler::where('paket_id', $eski->id)->get();
                foreach ($eski_hizmetler as $eh) {
                    $yh = new PaketHizmetler();
                    $yh->paket_id  = $yeni->id;
                    $yh->hizmet_id = $eh->hizmet_id;
                    $yh->fiyat     = $eh->fiyat;
                    $yh->seans     = $eh->seans;
                    $yh->save();
                    $eklenen_paket_hizmet++;
                }

                $detay[] = [
                    'eski_paket_id' => $eski->id,
                    'yeni_paket_id' => $yeni->id,
                    'paket_adi'     => $eski->paket_adi,
                    'hizmet_sayisi' => count($eski_hizmetler),
                ];
            }
            DB::commit();
        } catch (\Exception $e) {
            DB::rollBack();
            return response()->json(['hata' => 'Kopyalama basarisiz: ' . $e->getMessage()], 500);
        }

        return response()->json([
            'durum'                => 'basarili',
            'kaynak_salon_id'      => $kaynak_salon_id,
            'hedef_salon_id'       => $hedef_salon_id,
            'eklenen_paket'        => $eklenen_paket,
            'eklenen_paket_hizmet' => $eklenen_paket_hizmet,
            'detay'                => $detay,
        ]);
    }

    public function paket_hizmetlerini_salona_kopyala($kaynak_salon_id, $hedef_salon_id)
    {
        $kaynak_salon_id = (int) $kaynak_salon_id;
        $hedef_salon_id  = (int) $hedef_salon_id;
        if ($kaynak_salon_id <= 0 || $hedef_salon_id <= 0 || $kaynak_salon_id === $hedef_salon_id) {
            return response()->json(['hata' => 'Gecersiz salon id'], 400);
        }

        $hizmet_idleri = DB::table('paket_hizmetler')
            ->join('paketler', 'paketler.id', '=', 'paket_hizmetler.paket_id')
            ->where('paketler.salon_id', $kaynak_salon_id)
            ->pluck('paket_hizmetler.hizmet_id')
            ->unique()
            ->values();

        if ($hizmet_idleri->isEmpty()) {
            return response()->json(['hata' => "Kaynak salon ($kaynak_salon_id) paketlerinde hizmet bulunamadi"], 404);
        }

        $hedefte_var_olanlar = SalonHizmetler::where('salon_id', $hedef_salon_id)
            ->whereIn('hizmet_id', $hizmet_idleri)
            ->pluck('hizmet_id')
            ->all();
        $hedefte_var_olanlar = array_flip($hedefte_var_olanlar);

        $eklenen = 0;
        $atlandi = 0;
        $kaynak_yok = 0;
        $detay = [];

        DB::beginTransaction();
        try {
            foreach ($hizmet_idleri as $hid) {
                if (isset($hedefte_var_olanlar[$hid])) {
                    $atlandi++;
                    $detay[] = ['hizmet_id' => $hid, 'durum' => 'zaten_var'];
                    continue;
                }

                $kaynak_kayit = SalonHizmetler::where('salon_id', $kaynak_salon_id)
                    ->where('hizmet_id', $hid)
                    ->first();

                $yeni = new SalonHizmetler();
                $yeni->salon_id = $hedef_salon_id;
                $yeni->hizmet_id = $hid;

                if ($kaynak_kayit) {
                    $yeni->hizmet_kategori_id = $kaynak_kayit->hizmet_kategori_id;
                    $yeni->baslangic_fiyat    = $kaynak_kayit->baslangic_fiyat;
                    $yeni->son_fiyat          = $kaynak_kayit->son_fiyat;
                    $yeni->bolum              = $kaynak_kayit->bolum;
                    $yeni->aktif              = $kaynak_kayit->aktif;
                    $yeni->sure_dk            = $kaynak_kayit->sure_dk;
                    $detay_durum = 'eklendi_kaynaktan';
                } else {
                    $hizmet = Hizmetler::where('id', $hid)->first();
                    $yeni->hizmet_kategori_id = $hizmet ? $hizmet->hizmet_kategori_id : null;
                    $yeni->baslangic_fiyat    = 0;
                    $yeni->son_fiyat          = 0;
                    $yeni->bolum              = $hizmet ? $hizmet->cinsiyet : 0;
                    $yeni->aktif              = true;
                    $kaynak_yok++;
                    $detay_durum = 'eklendi_varsayilan';
                }
                $yeni->save();
                $eklenen++;
                $detay[] = ['hizmet_id' => $hid, 'durum' => $detay_durum];
            }
            DB::commit();
        } catch (\Exception $e) {
            DB::rollBack();
            return response()->json(['hata' => 'Kopyalama basarisiz: ' . $e->getMessage()], 500);
        }

        return response()->json([
            'durum'              => 'basarili',
            'kaynak_salon_id'    => $kaynak_salon_id,
            'hedef_salon_id'     => $hedef_salon_id,
            'paket_hizmet_sayisi'=> $hizmet_idleri->count(),
            'eklenen'            => $eklenen,
            'atlandi_zaten_var'  => $atlandi,
            'kaynak_kaydi_yoktu' => $kaynak_yok,
            'detay'              => $detay,
        ]);
    }

    // Bir salonun TUM musterilerini (musteri_portfoy) ve TUM hizmetlerini
    // (salon_sunulan_hizmetler) baska bir salona oldugu gibi kopyalar.
    // Ornek: GET /isletmeyonetim/musterihizmetkopyala/246/416
    public function musteri_hizmet_kopyala_salonlar_arasi($kaynak_salon_id, $hedef_salon_id)
    {
        $kaynak_salon_id = (int) $kaynak_salon_id;
        $hedef_salon_id  = (int) $hedef_salon_id;
        if ($kaynak_salon_id <= 0 || $hedef_salon_id <= 0 || $kaynak_salon_id === $hedef_salon_id) {
            return response()->json(['hata' => 'Gecersiz salon id'], 400);
        }
        if (Salonlar::where('id', $hedef_salon_id)->count() === 0) {
            return response()->json(['hata' => "Hedef salon ($hedef_salon_id) bulunamadi"], 404);
        }

        $sonuc = [
            'musteri' => ['toplam' => 0, 'eklenen' => 0, 'zaten_var' => 0],
            'hizmet'  => ['toplam' => 0, 'eklenen' => 0, 'zaten_var' => 0, 'ozel_klonlandi' => 0],
        ];

        DB::beginTransaction();
        try {
            // 1) HIZMETLER: kaynak salonun sunulan hizmetlerini hedefe kopyala
            $kaynak_hizmetler = SalonHizmetler::where('salon_id', $kaynak_salon_id)->get();
            $sonuc['hizmet']['toplam'] = $kaynak_hizmetler->count();

            foreach ($kaynak_hizmetler as $kaynak_kayit) {
                $hedef_hizmet_id = $kaynak_kayit->hizmet_id;

                // Salona ozel hizmet ise katalog satirini da hedef icin klonla
                $katalog = Hizmetler::where('id', $kaynak_kayit->hizmet_id)->first();
                if ($katalog && $katalog->ozel_hizmet && (int) $katalog->salon_id === $kaynak_salon_id) {
                    $klon = Hizmetler::where('salon_id', $hedef_salon_id)
                        ->where('ozel_hizmet', true)
                        ->where('hizmet_adi', $katalog->hizmet_adi)
                        ->first();
                    if (!$klon) {
                        $klon = new Hizmetler();
                        $klon->hizmet_kategori_id = $katalog->hizmet_kategori_id;
                        $klon->hizmet_adi         = $katalog->hizmet_adi;
                        $klon->fiyat              = $katalog->fiyat;
                        $klon->ozel_hizmet        = true;
                        $klon->salon_id           = $hedef_salon_id;
                        $klon->cinsiyet           = $katalog->cinsiyet;
                        $klon->sure_dk            = $katalog->sure_dk;
                        $klon->save();
                        $sonuc['hizmet']['ozel_klonlandi']++;
                    }
                    $hedef_hizmet_id = $klon->id;
                }

                if (SalonHizmetler::where('salon_id', $hedef_salon_id)->where('hizmet_id', $hedef_hizmet_id)->count() > 0) {
                    $sonuc['hizmet']['zaten_var']++;
                    continue;
                }

                $yeni = new SalonHizmetler();
                $yeni->salon_id          = $hedef_salon_id;
                $yeni->hizmet_id         = $hedef_hizmet_id;
                $yeni->hizmet_kategori_id= $kaynak_kayit->hizmet_kategori_id;
                $yeni->baslangic_fiyat   = $kaynak_kayit->baslangic_fiyat;
                $yeni->son_fiyat         = $kaynak_kayit->son_fiyat;
                $yeni->bolum             = $kaynak_kayit->bolum;
                $yeni->aktif             = $kaynak_kayit->aktif;
                $yeni->sure_dk           = $kaynak_kayit->sure_dk;
                $yeni->save();
                $sonuc['hizmet']['eklenen']++;

                // Kategori rengi hedefte yoksa olustur (mevcut ekleme akisiyla ayni mantik)
                if ($kaynak_kayit->hizmet_kategori_id &&
                    SalonHizmetKategoriRenkleri::where('hizmet_kategori_id', $kaynak_kayit->hizmet_kategori_id)->where('salon_id', $hedef_salon_id)->count() == 0) {
                    $son_renk = SalonHizmetKategoriRenkleri::where('salon_id', $hedef_salon_id)->orderBy('renk_id', 'desc')->first();
                    if ($son_renk === null)          $yeni_renk_id = 1;
                    elseif ($son_renk->renk_id == 10) $yeni_renk_id = 1;
                    else                              $yeni_renk_id = $son_renk->renk_id + 1;
                    $yeni_renk = new SalonHizmetKategoriRenkleri();
                    $yeni_renk->salon_id          = $hedef_salon_id;
                    $yeni_renk->renk_id           = $yeni_renk_id;
                    $yeni_renk->hizmet_kategori_id = $kaynak_kayit->hizmet_kategori_id;
                    $yeni_renk->save();
                }
            }

            // 2) MUSTERILER: kaynak salonun aktif portfoy musterilerini hedefe bagla
            $kaynak_portfoyler = MusteriPortfoy::where('salon_id', $kaynak_salon_id)->where('aktif', 1)->get();
            $sonuc['musteri']['toplam'] = $kaynak_portfoyler->count();

            foreach ($kaynak_portfoyler as $kaynak_portfoy) {
                // Hedefte bu musterinin herhangi bir portfoy kaydi varsa atla (users satiri paylasimli)
                if (MusteriPortfoy::where('salon_id', $hedef_salon_id)->where('user_id', $kaynak_portfoy->user_id)->count() > 0) {
                    $sonuc['musteri']['zaten_var']++;
                    continue;
                }
                $portfoy = new MusteriPortfoy();
                $portfoy->user_id               = $kaynak_portfoy->user_id;
                $portfoy->salon_id              = $hedef_salon_id;
                $portfoy->musteri_tipi          = $kaynak_portfoy->musteri_tipi;
                $portfoy->ozel_notlar           = $kaynak_portfoy->ozel_notlar;
                $portfoy->aktif                 = true;
                $portfoy->kvkk_onay_alindi      = $kaynak_portfoy->kvkk_onay_alindi;
                $portfoy->onay_kodu             = $kaynak_portfoy->onay_kodu;
                $portfoy->olusturan_personel_id = $kaynak_portfoy->olusturan_personel_id;
                $portfoy->save();
                $sonuc['musteri']['eklenen']++;
            }

            DB::commit();
        } catch (\Exception $e) {
            DB::rollBack();
            return response()->json(['hata' => 'Kopyalama basarisiz: ' . $e->getMessage()], 500);
        }

        SalonAudit::log($hedef_salon_id, 'musteri_hizmet_kopyala', 'salon', $kaynak_salon_id,
            "Salon $kaynak_salon_id -> $hedef_salon_id",
            'Musteri ve hizmetler salonlar arasi kopyalandi', $sonuc);

        return response()->json(array_merge([
            'durum'           => 'basarili',
            'kaynak_salon_id' => $kaynak_salon_id,
            'hedef_salon_id'  => $hedef_salon_id,
        ], $sonuc));
    }

    public function salon_sunulan_hizmetleri_kopyala($kaynak_salon_id, $hedef_salon_id)
    {
        $kaynak_salon_id = (int) $kaynak_salon_id;
        $hedef_salon_id  = (int) $hedef_salon_id;
        if ($kaynak_salon_id <= 0 || $hedef_salon_id <= 0 || $kaynak_salon_id === $hedef_salon_id) {
            return response()->json(['hata' => 'Gecersiz salon id'], 400);
        }

        $kaynak_kayitlar = SalonHizmetler::where('salon_id', $kaynak_salon_id)->get();
        if ($kaynak_kayitlar->isEmpty()) {
            return response()->json(['hata' => "Kaynak salon ($kaynak_salon_id) sunulan hizmet bulunamadi"], 404);
        }

        // Hedefte zaten var olan hizmet_id'ler (tekrar eklememek icin)
        $hedefte_var_olanlar = array_flip(
            SalonHizmetler::where('salon_id', $hedef_salon_id)->pluck('hizmet_id')->all()
        );

        $eklenen  = 0;
        $atlandi  = 0;
        $detay    = [];

        DB::beginTransaction();
        try {
            foreach ($kaynak_kayitlar as $kayit) {
                if (isset($hedefte_var_olanlar[$kayit->hizmet_id])) {
                    $atlandi++;
                    $detay[] = ['hizmet_id' => $kayit->hizmet_id, 'durum' => 'zaten_var'];
                    continue;
                }

                $yeni = $kayit->replicate();          // tum kolonlari kopyalar (id haric)
                $yeni->salon_id = $hedef_salon_id;
                $yeni->save();

                $hedefte_var_olanlar[$kayit->hizmet_id] = true; // ayni kaynakta cift kayit varsa tekrar ekleme
                $eklenen++;
                $detay[] = ['hizmet_id' => $kayit->hizmet_id, 'durum' => 'eklendi'];
            }
            DB::commit();
        } catch (\Exception $e) {
            DB::rollBack();
            return response()->json(['hata' => 'Kopyalama basarisiz: ' . $e->getMessage()], 500);
        }

        return response()->json([
            'durum'           => 'basarili',
            'kaynak_salon_id' => $kaynak_salon_id,
            'hedef_salon_id'  => $hedef_salon_id,
            'kaynak_sayisi'   => $kaynak_kayitlar->count(),
            'eklenen'         => $eklenen,
            'atlandi_zaten_var' => $atlandi,
            'detay'           => $detay,
        ]);
    }

