    private function musteri_sifre_olustur($length = 6) {
        return substr(str_shuffle('abcdefghjklmnopqrstuvwxyzABCDEFGHJKLMNOPQRSTUVWXYZ1234567890'), 0, $length);
    }
    private function musteri_olustur($request, $sifre) {
        return User::create([
            'name' => $request->ad_soyad,
            'email' => $request->email,
            'cep_telefon' => $request->telefon,
            'password' => Hash::make($sifre),
            'dogum_tarihi' => $this->dogum_tarihi_formatla($request),
            'cinsiyet' => in_array($request->cinsiyet, [0, 1]) ? $request->cinsiyet : null
        ]);
    }

    private function dogum_tarihi_formatla($request) {
        $gun = $request->dogum_tarihi_gun;
        $ay = $request->dogum_tarihi_ay;
        $yil = $request->dogum_tarihi_yil;
        if (!$gun || !$ay) return null;
        if (!$yil) $yil = '1900';
        $tarih = date('Y-m-d', strtotime("{$yil}-{$ay}-{$gun}"));
        return $tarih && $tarih !== '1970-01-01' ? $tarih : null;
    }
    private function portfoy_ekle_guncelle($userId, $salonId, $tip, $notlar) {
        $portfoy = MusteriPortfoy::firstOrNew([
            'user_id' => $userId,
            'salon_id' => $salonId,
        ]);

        $portfoy->fill([
            'musteri_tipi' => $tip,
            'ozel_notlar' => $notlar,
            'aktif' => true,
        ])->save();
    }
    private function musteri_sms_bilgilendir($musteri, $sifre = null, $subeId) {
        if (!SalonSMSAyarlari::where('salon_id', $subeId)->where('ayar_id', 4)->value('musteri')) return;

        $salon = Salonlar::where('id', $subeId)->first();
        $mesaj = "Sayın {$musteri->name}. {$salon->salon_adi} tarafından müşteri kaydınız oluşturulmuştur.";

        if ($sifre) {
            $mesaj .= " Kullanıcı adınız: {$musteri->cep_telefon}, Şifreniz: {$sifre}";
        }

        if ($salon->uygulamalar_kisa_link) {
            $mesaj .= " Uygulamamızı indirmek için: {$salon->uygulamalar_kisa_link}";
        }

        self::sms_gonder_bildirimli(null, [["to" => $musteri->cep_telefon, "message" => $mesaj]], false, 1, false);
    }
