    public function calismasaatleriduzenle(Request $request){
        if($r = self::yetkiYoksa403($request, 'ayar.salon_bilgi')) return $r;
        $saloncalismasaatlerieski = SalonCalismaSaatleri::where('salon_id',self::mevcutsube($request))->delete();
        $salonmolasaaterieski = SalonMolaSaatleri::where('salon_id',self::mevcutsube($request))->delete();
        for($i=1;$i<=7;$i++){
            $saloncalismasaatleri = new SalonCalismaSaatleri();
            $salonmolasaatleri = new SalonMolaSaatleri();
            $saloncalismasaatleri->haftanin_gunu = $i;
            $salonmolasaatleri->haftanin_gunu = $i;
            $saloncalismasaatleri->salon_id = self::mevcutsube($request);
            $salonmolasaatleri->salon_id = self::mevcutsube($request);
            if(isset($_POST['calisiyor'.$i])){
                $saloncalismasaatleri->calisiyor = 1;
            }
            else{
                $saloncalismasaatleri->calisiyor = 0;
            }
            if(isset($_POST['molavar'.$i])){
                $salonmolasaatleri->mola_var = 1;
            }
            else{
                $salonmolasaatleri->mola_var = 0;
            }
             if($i==1){
                     $saloncalismasaatleri->baslangic_saati = $request->baslangicsaati1;
                     $saloncalismasaatleri->bitis_saati = $request->bitissaati1;
                      $salonmolasaatleri->baslangic_saati = $request->molabaslangicsaati1;
                     $salonmolasaatleri->bitis_saati = $request->molabitissaati1;
                }
                 if($i==2){
                     $saloncalismasaatleri->baslangic_saati = $request->baslangicsaati2;
                     $saloncalismasaatleri->bitis_saati = $request->bitissaati2;
                     $salonmolasaatleri->baslangic_saati = $request->molabaslangicsaati2;
                     $salonmolasaatleri->bitis_saati = $request->molabitissaati2;
                }
                 if($i==3){
                     $saloncalismasaatleri->baslangic_saati = $request->baslangicsaati3;
                     $saloncalismasaatleri->bitis_saati = $request->bitissaati3;
                     $salonmolasaatleri->baslangic_saati = $request->molabaslangicsaati3;
                     $salonmolasaatleri->bitis_saati = $request->molabitissaati3;
                }
                 if($i==4){
                     $saloncalismasaatleri->baslangic_saati = $request->baslangicsaati4;
                     $saloncalismasaatleri->bitis_saati = $request->bitissaati4;
                     $salonmolasaatleri->baslangic_saati = $request->molabaslangicsaati4;
                     $salonmolasaatleri->bitis_saati = $request->molabitissaati4;
                }
                 if($i==5){
                     $saloncalismasaatleri->baslangic_saati = $request->baslangicsaati5;
                     $saloncalismasaatleri->bitis_saati = $request->bitissaati5;
                     $salonmolasaatleri->baslangic_saati = $request->molabaslangicsaati5;
                     $salonmolasaatleri->bitis_saati = $request->molabitissaati5;
                }
                 if($i==6){
                     $saloncalismasaatleri->baslangic_saati = $request->baslangicsaati6;
                     $saloncalismasaatleri->bitis_saati = $request->bitissaati6;
                     $salonmolasaatleri->baslangic_saati = $request->molabaslangicsaati6;
                     $salonmolasaatleri->bitis_saati = $request->molabitissaati6;
                }
                 if($i==7){
                     $saloncalismasaatleri->baslangic_saati = $request->baslangicsaati7;
                     $saloncalismasaatleri->bitis_saati = $request->bitissaati7;
                     $salonmolasaatleri->baslangic_saati = $request->molabaslangicsaati7;
                     $salonmolasaatleri->bitis_saati = $request->molabitissaati7;
                }
                $saloncalismasaatleri->save();
                $salonmolasaatleri->save();
        }
        return "Çalışma saatleri başarıyla kaydedildi";
    }
    public function isletmebilgiguncelle(Request $request){
        if($r = self::yetkiYoksa403($request, 'ayar.salon_bilgi')) return $r;
        $isletme = Salonlar::where('id',$request->sube)->first();
        $eski = [
            'salon_adi' => $isletme->salon_adi,
            'telefon_1' => $isletme->telefon_1,
            'whatsapp'  => $isletme->whatsapp,
        ];
        $isletme->salon_adi = $request->isletme_adi;
        $isletme->adres =$request->isletme_adres;
        $isletme->salon_turu_id = $request->isletme_turu;
         $isletme->telefon_1=$request->isletme_telefon;
        $isletme->vergi_adi = $request->vergi_adi;
        $isletme->vergi_no = $request->vergi_tc_no;
        $isletme->vergi_dairesi = $request->vergi_dairesi;
        $isletme->vergi_adresi = $request->vergi_adresi;
        $isletme->kdv_orani = $request->kdv_orani;
        $isletme->meta_description = $request->seo_description;
        $isletme->aciklama = $request->isletme_aciklama;
        $isletme->facebook_sayfa = $request->facebook_url;
        $isletme->instagram_sayfa = $request->instagram_url;
        $isletme->whatsapp = $request->whatsapp;
        AramaTerimleri::where('salon_id',$isletme->id)->delete();
        foreach($request->anahtar_kelimeler as $anahtar_kelime)
        {
            if($anahtar_kelime != ''){
                $ak = new AramaTerimleri();
                $ak->salon_id = $isletme->id;
                $ak->arama_terimi =$anahtar_kelime;
                $ak->save();
            }
        }
        $isletme->save();
        // Audit
        SalonAudit::log($isletme->id, 'ayarlar_guncelle', 'salon', $isletme->id,
            $isletme->salon_adi, 'Temel ayarlar güncellendi',
            ['eski' => $eski, 'yeni' => ['salon_adi'=>$isletme->salon_adi,'telefon_1'=>$isletme->telefon_1,'whatsapp'=>$isletme->whatsapp]]);
        return "İşletme bilgileri başarıyla kaydedildi";
    }
    public function adisyon_hizmet_sil(Request $request)
    {
        if($r = self::satisYetkiYoksa403($request, 'satis.adisyon_olustur')) return $r;

        $smsDogrulamaVar = SalonSMSAyarlari::where('salon_id',$request->sube)->where('ayar_id',23)->value('personel');
        $hizmet = AdisyonHizmetler::where('id',$request->hizmet_id)->first();

        $dogrulamaKodu = $hizmet->dogrulama_kodu;
        if($smsDogrulamaVar && ($request->dogrulamaKodu == '' || $request->dogrulamaKodu != $dogrulamaKodu))
        {
            if($dogrulamaKodu == null)
            {
                $islemYapan = Personeller::where('yetkili_id',Auth::guard('isletmeyonetim')->user()->id)->where('salon_id',$request->sube)->first();
                $hesapSahibi = Personeller::where('salon_id',$request->sube)->where('role_id',1)->value('yetkili_id');
                $hesapSahibiTel = IsletmeYetkilileri::where('id',$hesapSahibi)->value('gsm1');
                $random = str_shuffle('1234567890');
                $kod = substr($random, 0, 4);
                $hizmet->dogrulama_kodu = $kod;
                $hizmet->save();
                $adisyon = Adisyonlar::where('id',$hizmet->adisyon_id)->first();
                $mesaj = $islemYapan->personel_adi.' '.date('d.m.Y',strtotime($adisyon->tarih)).' tarihli satıştan '.number_format($hizmet->fiyat,2,',','.').' ₺ tutarındaki '.$hizmet->hizmet->hizmet_adi.' hizmetini silmek için onayınızı istiyor. Onay Kodu : '.$kod;

                     
                $mesajlar = array(
                        array("to"=>$hesapSahibiTel,"message"=>$mesaj),
                );
                self::sms_gonder_bildirimli($request,$mesajlar,false,1,true);
                
            }
            return array(
                    'dogrulamaGerekli'=>true,   
            );
        } 
        
        $adisyon_id = $hizmet->adisyon_id;
        $musteriid = Adisyonlar::where('id',$adisyon_id)->value('user_id');
        $tahsilatlar = Tahsilatlar::where('adisyon_id',$adisyon_id)->get();
        $hizmeteaittahsilatvar = false;
        $tahsilatekrani  = false;
        foreach($tahsilatlar as $tahsilat)
        {
            if(TahsilatHizmetler::where('tahsilat_id',$tahsilat->id)->where('adisyon_hizmet_id',$hizmet->id)->count() != 0)
                $hizmeteaittahsilatvar = true;
        }
        if($hizmeteaittahsilatvar){
            return array(
                'silinemez'=>$hizmet->hizmet->hizmet_adi . ' için tahsilat kaydı bulunmakta olduğundan adisyondan silme işlemi gerçekleştirilemiyor. Önce tahsilat kaydının kaldırılması gereklidir.'
            );
            exit;
        }
        elseif($tahsilatekrani)
        {
            return self::musteri_tahsilatlari($request,$musteriid,"",$request->satisDuzenle);
            exit;
        }
        else
        {
            // Audit (silmeden once)
            $hizmetAdi = optional($hizmet->hizmet)->hizmet_adi ?? 'Hizmet #'.$hizmet->id;
            $musteriAdi = \App\User::where('id',$musteriid)->value('name');
            SalonAudit::log($request->sube, 'adisyon_hizmet_sil', 'adisyon_hizmet', $hizmet->id,
                $hizmetAdi.' — '.($musteriAdi ?: ''),
                'Adisyondan hizmet silindi',
                ['adisyon_id'=>$adisyon_id, 'fiyat'=>$hizmet->fiyat, 'hizmet_id'=>$hizmet->hizmet_id]);
            $hizmet->delete();
            /*if(AdisyonHizmetler::where('adisyon_id',$adisyon_id)->count()+AdisyonUrunler::where('adisyon_id',$adisyon_id)->count()+AdisyonPaketler::where('adisyon_id',$adisyon_id)->count()==0)
                Adisyonlar::where('id',$adisyon_id)->delete()*/
            return self::musteri_tahsilatlari($request,$musteriid,"",$request->satisDuzenle);//self::adisyon_detay($request,Adisyonlar::where('id',$adisyon_id)->first(),false,$musteriid);
            exit;
        }
    }

    public function adisyonhizmetekle(Request $request)
    {
            if($r = self::satisYetkiYoksa403($request, 'satis.adisyon_olustur')) return $r;
            $adisyon_id = '';
            if($request->adisyon_id != '')
            {
                $adisyon_id = $request->adisyon_id;
            }
            else
                $adisyon_id = self::yeni_adisyon_olustur($request->musteri_id,$request->sube,'Hizmet Satışı',date('Y-m-d'));
            foreach($request->adisyonhizmetleriyeni as $key=>$adisyon_hizmet){
                $adisyon_hizmet = new AdisyonHizmetler();
                $adisyon_hizmet->adisyon_id = $adisyon_id;
                $adisyon_hizmet->hizmet_id = $request->adisyonhizmetleriyeni[$key];
                $adisyon_hizmet->islem_tarihi = date('Y-m-d',strtotime($request->islemtarihiyeni[$key]));
                $adisyon_hizmet->islem_saati = date('H:i:s',strtotime($request->islemsaatiyeni[$key]));
                $adisyon_hizmet->sure = $request->adisyonhizmetsuresi[$key];
                $adisyon_hizmet->fiyat = $request->adisyonhizmetfiyati[$key];
                $adisyon_hizmet->personel_id = $request->adisyonhizmetpersonelleriyeni[$key];
                // Bos ya da <=1 -> NULL (tekil hizmet); 2+ -> paket satisi sayilir
                $_seansGirilen = isset($request->hizmetseanssayisi[$key]) ? trim((string)$request->hizmetseanssayisi[$key]) : '';
                $_seansSayisi = ($_seansGirilen === '' || (int)$_seansGirilen <= 1) ? null : (int)$_seansGirilen;
                $adisyon_hizmet->seans_sayisi = $_seansSayisi;
                $adisyon_hizmet->bekleyen_seans = $_seansSayisi;
                if(isset($request->hizmetRandevuOlustur))
                        $adisyon_hizmet->otomatik_randevu_olusturuldu=true;
                    else
                        $adisyon_hizmet->otomatik_randevu_olusturuldu=false;
                $adisyon_hizmet->kullanilan_seans = 0;
                $adisyon_hizmet->kullanilmayan_seans = 0;

                $adisyon_hizmet->save();

                // Sarf recetesi varsa otomatik dus (web panel adisyon hizmet ekleme)
                StokController::receteyiUygula(
                    (int) $request->sube,
                    (int) $adisyon_hizmet->hizmet_id,
                    'islem',
                    null,
                    $adisyon_hizmet->personel_id ? (int) $adisyon_hizmet->personel_id : null
                );

                $seanstarih = "";
               
                if(isset($request->hizmetRandevuOlustur))
                {
                     $randevuSMSigitti = false;
                     // Auto-randevu icin: seans_sayisi NULL ise 1 randevu, aksi halde N randevu
                     $_seansForRandevu = $_seansSayisi ?: 1;
                     for($i=1;$i<=$_seansForRandevu;$i++){

                    $request->user_id = $request->musteri_id;
                    
                    if($i == 1)
                        $seanstarih = date('Y-m-d',strtotime($request->islemtarihiyeni[$key]));
                    else
                        $seanstarih = date('Y-m-d',strtotime('+'.$request->hizmetseansperiyodu[$key].' days', strtotime($seanstarih)));
                    $request->tarih = $seanstarih;

                    $request->saat = date('H:i:s',strtotime($request->islemsaatiyeni[$key]));
                    $request->salon= 1;
                    $request->olusturan_personel_id = Auth::guard('isletmeyonetim')->user()->id;
                    $request->durum = 1;
                    $request->salon_id = $request->sube;
                    $request->hizmetler = $request->adisyonhizmetleriyeni;
                    $request->hizmetSuresi = $request->adisyonhizmetsuresi;
                    $request->hizmetFiyati = $request->adisyonhizmetfiyati[$key];
                    $request->randevuPersonelleri = $request->adisyonhizmetpersonelleriyeni; 

                    $randevuId = self::randevuEkle($request);
                    $seans_randevu = Randevular::where('id',$randevuId)->first();
                    if($seans_randevu)
                    {
                        if(!$randevuSMSigitti)
                        {
                            if(SalonSMSAyarlari::where('ayar_id',12)->where('salon_id',$seans_randevu->salon_id)->value('musteri')==1)
                            {
                                    $mesajlar = [];
                                    array_push($mesajlar, array("to"=>$seans_randevu->users->cep_telefon,"message"=>$seans_randevu->salonlar->salon_adi . " tarafından ".date('d.m.Y',strtotime($seans_randevu->tarih)) .'-'.date('H:i', strtotime($seans_randevu->saat)) .' olarak randevunuz oluşturulmuştur. Randevunuza 15 dk önce gelmenizi rica ederiz. Detaylı bilgi için bize ulaşın. 0'.$seans_randevu->salonlar->telefon_1));
                                        self::sms_gonder_bildirimli($request,$mesajlar,false,1,false);
                                    $randevuSMSigitti = true;

                            }

                        }
                    }
                   
                    
                    $adisyon_hizmet_seans = new AdisyonPaketSeanslar();
                    $adisyon_hizmet_seans->adisyon_hizmet_id = $adisyon_hizmet->id;
                    $adisyon_hizmet_seans->seans_no = $i;
                    $adisyon_hizmet_seans->randevu_id = $randevuId;
                    $adisyon_hizmet_seans->hizmet_id =$request->adisyonhizmetleriyeni[$key];
                    $adisyon_hizmet_seans->seans_tarih = $seanstarih;
                    $adisyon_hizmet_seans->seans_saat = date('H:i:s',strtotime($request->islemsaatiyeni[$key]));
                    $adisyon_hizmet_seans->save();
                     
                    
                }
                }
                
            }
            // Audit (toplam adet ve ozet ile)
            $_audit_musteriAdi = \App\User::where('id',$request->musteri_id)->value('name') ?? 'Müşteri #'.$request->musteri_id;
            $_audit_adet = is_array($request->adisyonhizmetleriyeni) ? count($request->adisyonhizmetleriyeni) : 0;
            $_audit_toplam = 0;
            if (is_array($request->adisyonhizmetfiyati)) {
                foreach ($request->adisyonhizmetfiyati as $_f) { $_audit_toplam += (float)$_f; }
            }
            SalonAudit::log($request->sube, 'adisyona_hizmet_ekle', 'adisyon', $adisyon_id,
                $_audit_musteriAdi.' — '.$_audit_adet.' hizmet',
                'Adisyona hizmet eklendi',
                ['hizmet_adedi'=>$_audit_adet, 'toplam_tutar'=>$_audit_toplam, 'hizmet_idler'=>$request->adisyonhizmetleriyeni]);

            //if(isset($request->tahsilatekrani))
            //{

                return self::musteri_tahsilatlari($request,$request->musteri_id,$adisyon_id,$request->satisDuzenle);
              //  exit;
            //}
            //else
            /*{
                  return self::adisyon_detay($request,$request,Adisyonlar::where('id',$adisyon_hizmet->adisyon_id)->first(),false,'');
                  exit;
            }*/
    }
