                'tum_tahsilatlar' => self::musteri_tahsilatlari($request,$musteriid,"",false)
        );
    }
    public function yaklasan_dogumgunleri()
    {
         $salonId = Auth::guard('isletmeyonetim')->user()->salon_id;
         $bugun = date('m-d');
         $bes_gun_sonra = date('m-d', strtotime('+5 days'));

         $query = DB::table('musteri_portfoy')
            ->join('users','musteri_portfoy.user_id','=','users.id')
            ->select('users.name as ad_soyad','users.cep_telefon as telefon', 'users.dogum_tarihi as dogum_tarihi')
            ->where('musteri_portfoy.salon_id', $salonId)
            ->where('musteri_portfoy.aktif', 1)
            ->whereNotNull('users.dogum_tarihi');

         if ($bugun <= $bes_gun_sonra) {
            $query->whereRaw("DATE_FORMAT(users.dogum_tarihi,'%m-%d') BETWEEN ? AND ?", [$bugun, $bes_gun_sonra]);
         } else {
            $query->where(function($q) use ($bugun, $bes_gun_sonra) {
                $q->whereRaw("DATE_FORMAT(users.dogum_tarihi,'%m-%d') >= ?", [$bugun])
                  ->orWhereRaw("DATE_FORMAT(users.dogum_tarihi,'%m-%d') <= ?", [$bes_gun_sonra]);
            });
         }

         $yaklasan_dogumgunleri = $query->orderByRaw("DATE_FORMAT(users.dogum_tarihi,'%m-%d')")->get();
         $yaklasan_dogumgunleri = $yaklasan_dogumgunleri->map(function ($r) {
             if (isset($r->telefon)) {
                 $r->telefon = \App\PersonelYetkiSabitleri::telefonGoster($r->telefon);
             }
             return $r;
         });
         echo $yaklasan_dogumgunleri;
    }

    public function dashboardBugunDogumGunu(Request $request)
    {
        $salonId = $this->dashSalonId($request);
        if(!$salonId) return response()->json(['error'=>'forbidden'], 403);
        if($r = self::dashYetkiYoksa403($salonId, 'musteri.liste_gor')) return $r;

        $bugun = date('m-d');
        $liste = DB::table('users')
            ->join('musteri_portfoy','musteri_portfoy.user_id','=','users.id')
            ->where('musteri_portfoy.salon_id', $salonId)
            ->where('musteri_portfoy.aktif', 1)
            ->whereNotNull('users.dogum_tarihi')
            ->whereRaw("DATE_FORMAT(users.dogum_tarihi, '%m-%d') = ?", [$bugun])
            ->select('users.id','users.name','users.cep_telefon','users.dogum_tarihi')
            ->limit(20)
            ->get();

        // Bugün için zaten gönderim yapılan müşterileri işaretle
        $gonderilenIds = DB::table('dogum_gunu_mesaj_loglari')
            ->where('salon_id', $salonId)
            ->whereDate('gonderim_tarihi', date('Y-m-d'))
            ->pluck('user_id')
            ->toArray();

        $liste = $liste->map(function($r) use ($gonderilenIds) {
            $r->gonderildi = in_array($r->id, $gonderilenIds);
            return $r;
        });

        return response()->json(['liste' => $liste, 'tarih' => date('Y-m-d')]);
    }

    public function dogumGunuMesajGonder(Request $request)
    {
        $salonId = self::mevcutsube($request);
        if(!$salonId) return response()->json(['ok' => false, 'error' => 'forbidden'], 403);
        // Musteriye WhatsApp/SMS gonderimi → en az birinin yetkisi gerekli
        if($r = self::dashYetkiYoksa403($salonId, ['pazarlama.whatsapp_gonder','pazarlama.sms_gonder'])) return $r;

        $musteriId = (int) $request->musteri_id;
        if(!$musteriId) return response()->json(['ok' => false, 'error' => 'musteri_id-gerekli'], 422);

        $musteri = User::where('id', $musteriId)->first();
        if(!$musteri || !$musteri->cep_telefon) {
            return response()->json(['ok' => false, 'error' => 'musteri-bulunamadi'], 404);
        }

        $portfoyVar = MusteriPortfoy::where('user_id', $musteriId)
            ->where('salon_id', $salonId)
            ->where('aktif', 1)
            ->exists();
        if(!$portfoyVar) {
            return response()->json(['ok' => false, 'error' => 'portfoy-disi'], 403);
        }

        $bugunGonderildi = DB::table('dogum_gunu_mesaj_loglari')
            ->where('salon_id', $salonId)
            ->where('user_id', $musteriId)
            ->whereDate('gonderim_tarihi', date('Y-m-d'))
            ->exists();
        if($bugunGonderildi) {
            return response()->json(['ok' => false, 'error' => 'zaten-gonderildi', 'mesaj' => 'Bu müşteriye bugün zaten doğum günü mesajı gönderildi.']);
        }

        $salon = Salonlar::where('id', $salonId)->first();
        $salonAdi = $salon ? $salon->salon_adi : '';
        $mesaj = 'Sayın ' . $musteri->name . ', ' . $salonAdi . ' olarak doğum gününüzü kutlar; sağlıklı, mutlu ve başarı dolu bir yıl dileriz. 🎂';

        // sms_gonder_bildirimli WhatsApp'i once dener (salon WA aktif+connected ise),
        // basarisiz olursa SMS'e duser
        $mesajlar = [[
            'to' => $musteri->cep_telefon,
            'message' => $mesaj,
            'user_id' => $musteri->id,
        ]];

        // Paylasilan oturum: 416 icin 246'nin WA durumunu kontrol et
        $waSalon = $salon ? \App\Services\WhatsAppService::resolveWaSalon($salon) : null;
        $waKanaliAcik = $waSalon && !empty($waSalon->whatsapp_aktif) && ($waSalon->whatsapp_durum ?? null) === 'connected';
        $kanal = 'sms';
        $kanalDetay = '';

        try {
            if ($waKanaliAcik) {
                $wa = app(\App\Services\WhatsAppService::class);
                $sonuc = $wa->sendReminder($salon, $musteri->cep_telefon, $mesaj, null, $musteri->id, null, false, 'dogum_gunu');
                if (!empty($sonuc['ok'])) {
                    $kanal = 'whatsapp';
                    $kanalDetay = 'queued';
                } else {
                    $kanalDetay = 'wa-fail:' . ($sonuc['error'] ?? 'unknown');
                    self::sms_gonder_bildirimli($request, $mesajlar, false, 1, false);
                }
            } else {
                self::sms_gonder_bildirimli($request, $mesajlar, false, 1, false);
            }

            DB::table('dogum_gunu_mesaj_loglari')->insert([
                'salon_id' => $salonId,
                'user_id' => $musteri->id,
                'kanal' => $kanal,
                'mesaj' => mb_substr($mesaj, 0, 500),
                'detay' => mb_substr($kanalDetay, 0, 200),
                'gonderim_tarihi' => now(),
                'created_at' => now(),
                'updated_at' => now(),
            ]);

            return response()->json([
                'ok' => true,
                'kanal' => $kanal,
                'mesaj' => $kanal === 'whatsapp' ? 'WhatsApp üzerinden gönderildi.' : 'SMS olarak gönderildi.',
            ]);
        } catch (\Throwable $e) {
            \Log::error('[DOGUM-GUNU-MANUEL] gonderim hatasi', [
                'salon_id' => $salonId, 'user_id' => $musteri->id, 'err' => $e->getMessage(),
            ]);
            return response()->json(['ok' => false, 'error' => 'gonderim-hatasi', 'mesaj' => 'Mesaj gönderiminde hata oluştu.'], 500);
        }
    }
    public function cacheTemizle(Request $request)
    {
        $cikti = [];
        try { \Artisan::call('view:clear');  $cikti['view']  = trim(\Artisan::output()); } catch(\Throwable $e){ $cikti['view']  = 'HATA: '.$e->getMessage(); }
        try { \Artisan::call('cache:clear'); $cikti['cache'] = trim(\Artisan::output()); } catch(\Throwable $e){ $cikti['cache'] = 'HATA: '.$e->getMessage(); }
        try { \Artisan::call('route:clear'); $cikti['route'] = trim(\Artisan::output()); } catch(\Throwable $e){ $cikti['route'] = 'HATA: '.$e->getMessage(); }
        try { \Artisan::call('config:clear');$cikti['config']= trim(\Artisan::output()); } catch(\Throwable $e){ $cikti['config']= 'HATA: '.$e->getMessage(); }
        $html  = '<html><head><meta charset="utf-8"><title>Cache Temizle</title>';
        $html .= '<style>body{font-family:system-ui;background:#f6f7fb;padding:32px;max-width:640px;margin:auto;}h2{color:#1fbf6f;}pre{background:#fff;padding:16px;border-radius:8px;border:1px solid #e6e9f2;}a{display:inline-block;margin-top:16px;padding:10px 18px;background:#6e4bff;color:#fff;text-decoration:none;border-radius:6px;}</style>';
        $html .= '</head><body><h2>✅ Cache Temizlendi</h2><pre>'.htmlspecialchars(json_encode($cikti, JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE)).'</pre>';
        $html .= '<a href="/isletmeyonetim?sube='.((int) $request->sube).'">Dashboard\'a Dön</a></body></html>';
        return $html;
    }
    public function tahsilatekle(Request $request){
        if($r = self::satisYetkiYoksa403($request, 'satis.tahsilat_al')) return $r;
        $tahsilat = new Tahsilatlar();
        $tahsilat->adisyon_id = $request->adisyon_id;
        $tahsilat->tutar = str_replace('.','',$request->indirimli_toplam_tahsilat_tutari);
        $tahsilat->user_id = $request->tahsilat_musteri_id;
        $tahsilat->odeme_tarihi = $request->tahsilat_tarihi;
        $tahsilat->olusturan_id = Personeller::where('salon_id',$request->sube)->where('yetkili_id',Auth::guard('isletmeyonetim')->user()->id)->value('id');
        $tahsilat->salon_id = $request->sube;
        $tahsilat->yapilan_odeme = str_replace('.','',$request->indirimli_toplam_tahsilat_tutari);
        $tahsilat->odeme_yontemi_id = $request->odeme_yontemi;
        $tahsilat->notlar = $request->tahsilat_notlari;
        if($request->banka != '')
            $tahsilat->banka_id  = $request->banka;
        $tahsilat->save();
        // Audit
        $_audit_musteriAdi = \App\User::where('id',$request->tahsilat_musteri_id)->value('name') ?? 'Müşteri #'.$request->tahsilat_musteri_id;
        $_audit_tutar = number_format((float)$tahsilat->tutar, 2, ',', '.');
        SalonAudit::log($request->sube, 'tahsilat_ekle', 'tahsilat', $tahsilat->id,
            $_audit_musteriAdi.' — '.$_audit_tutar.' ₺',
            'Tahsilat alındı',
            ['adisyon_id' => $request->adisyon_id, 'odeme_yontemi_id' => $request->odeme_yontemi]);
        if(isset($request->adisyon_hizmet_id) && isset($request->adisyon_hizmet_senet_id) && isset($request->adisyon_hizmet_taksitli_tahsilat_id))
        {
            foreach($request->adisyon_hizmet_id as $key=>$hizmet_id)
            {
                $_senet_v = $request->adisyon_hizmet_senet_id[$key] ?? '';
                $_taksit_v = $request->adisyon_hizmet_taksitli_tahsilat_id[$key] ?? '';
                if($_senet_v == '' && $_taksit_v == '')
                {
                    $hizmet_tahsilat_tutar = $request->himzet_tahsilat_tutari_girilen[$key]
                        ?? $request->adisyon_hizmet_tahsilat_tutari[$key]
                        ?? null;
                    if($hizmet_tahsilat_tutar === null || $hizmet_tahsilat_tutar === '')
                        continue;
                    $_tahsilat_tutari = (float) str_replace(['.',','],['','.'],$request->tahsilat_tutari ?? '0');
                    if($_tahsilat_tutari == 0)
                        continue;
                    $odeme = new TahsilatHizmetler();
                    $odeme->adisyon_hizmet_id = $hizmet_id;
                    $odeme->tahsilat_id = $tahsilat->id;
                    $odeme->tutar = (str_replace(['.',','],['','.'],$hizmet_tahsilat_tutar)/$_tahsilat_tutari)*str_replace(['.',','],['','.'],$request->indirimli_toplam_tahsilat_tutari);
                    $odeme->save();
                }
            }
        }
        if(isset($request->adisyon_urun_id) && isset($request->adisyon_urun_senet_id) && isset($request->adisyon_urun_taksitli_tahsilat_id))
        {
            foreach($request->adisyon_urun_id as $key2=>$urun_id)
            {
                $_senet_v2 = $request->adisyon_urun_senet_id[$key2] ?? '';
                $_taksit_v2 = $request->adisyon_urun_taksitli_tahsilat_id[$key2] ?? '';
                if($_senet_v2 == '' && $_taksit_v2 == '')
                {
                    $urun_tahsilat_tutar = $request->urun_tahsilat_tutari_girilen[$key2]
                        ?? $request->adisyon_urun_tahsilat_tutari[$key2]
                        ?? null;
                    if($urun_tahsilat_tutar === null || $urun_tahsilat_tutar === '')
                        continue;
                    $_tahsilat_tutari2 = (float) str_replace(['.',','],['','.'],$request->tahsilat_tutari ?? '0');
                    if($_tahsilat_tutari2 == 0)
                        continue;
                    $odeme = new TahsilatUrunler();
                    $odeme->adisyon_urun_id = $urun_id;
                    $odeme->tahsilat_id = $tahsilat->id;
                    $odeme->tutar = (str_replace(['.',','],['','.'],$urun_tahsilat_tutar)/$_tahsilat_tutari2)*str_replace(['.',','],['','.'],$request->indirimli_toplam_tahsilat_tutari);
                    $odeme->save();
                }
            }
        }
        if(isset($request->adisyon_paket_id)&& isset($request->adisyon_paket_senet_id) && isset($request->adisyon_paket_taksitli_tahsilat_id))
        {
            foreach($request->adisyon_paket_id as $key3=>$paket_id)
            {
                $_senet_v3 = $request->adisyon_paket_senet_id[$key3] ?? '';
                $_taksit_v3 = $request->adisyon_paket_taksitli_tahsilat_id[$key3] ?? '';
                if($_senet_v3 == '' && $_taksit_v3 == ''){
                    $paket_tahsilat_tutar = $request->paket_tahsilat_tutari_girilen[$key3]
                        ?? $request->adisyon_paket_tahsilat_tutari[$key3]
                        ?? null;
                    if($paket_tahsilat_tutar === null || $paket_tahsilat_tutar === '')
                        continue;
                    $_tahsilat_tutari3 = (float) str_replace(['.',','],['','.'],$request->tahsilat_tutari ?? '0');
                    if($_tahsilat_tutari3 == 0)
                        continue;
                    $odeme = new TahsilatPaketler();
                    $odeme->adisyon_paket_id = $paket_id;
                    $odeme->tahsilat_id = $tahsilat->id;
                    $odeme->tutar = (str_replace(['.',','],['','.'],$paket_tahsilat_tutar)/$_tahsilat_tutari3)*str_replace(['.',','],['','.'],$request->indirimli_toplam_tahsilat_tutari);
                    $odeme->save();
                }
            }
        }
        if(isset($request->taksit_vade_id))
        {
            // Ödenecek toplam tutarı float olarak al
            $tahsilatTutari = (float) $tahsilat->tutar;

            foreach($request->taksit_vade_id as $_key => $taksitvadesi)
            {
                $taksit_vade = TaksitVadeleri::find($taksitvadesi);

                // Taksite ödenecek miktar = min(tahsilatTutari, taksit tutarı)
                $kismi_odeme = min($tahsilatTutari, (float)$taksit_vade->tutar);

                // Taksitleri DB’de değiştirme, sadece ödeme bilgisi ekle
                if($kismi_odeme == (float)$taksit_vade->tutar) {
                    $taksit_vade->odendi = true;
                    $taksit_vade->odeme_yontemi_id = $request->odeme_yontemi;
                }

               
                //$taksit_vade->save();

                // Adisyon kalemlerini tek bir array’de topla
                $kalemler = [];

                $kalemler['hizmet'] = AdisyonHizmetler::where('taksitli_tahsilat_id', $taksit_vade->taksitli_tahsilat_id)->get();
                $kalemler['urun'] = AdisyonUrunler::where('taksitli_tahsilat_id', $taksit_vade->taksitli_tahsilat_id)->get();
                $kalemler['paket'] = AdisyonPaketler::where('taksitli_tahsilat_id', $taksit_vade->taksitli_tahsilat_id)->get();

                // Her kalem tipi için ödemeyi yap
                foreach($kalemler as $tip => $items)
                {
                    // Önce toplam kalan borcu hesapla
                    $toplam_kalan_borc = 0;
                    foreach($items as $item)
                    {
                        switch($tip)
                        {
                            case 'hizmet':
                                $onceki = TahsilatHizmetler::where('adisyon_hizmet_id', $item->id)->sum('tutar');
                                $kalan = $item->fiyat - $item->indirim_tutari - $onceki;
                                break;
                            case 'urun':
                                $onceki = TahsilatUrunler::where('adisyon_urun_id', $item->id)->sum('tutar');
                                $kalan = $item->fiyat - $item->indirim_tutari - $onceki;
                                break;
                            case 'paket':
                                $onceki = TahsilatPaketler::where('adisyon_paket_id', $item->id)->sum('tutar');
                                $kalan = $item->fiyat - $item->indirim_tutari - $onceki;
                                break;
                        }

                        $toplam_kalan_borc += $kalan > 0 ? $kalan : 0;
                    }

                    // Şimdi kısmi ödemeyi kalan borca oransal dağıt
                    foreach($items as $item)
                    {
                        switch($tip)
                        {
                            case 'hizmet':
                                $onceki = TahsilatHizmetler::where('adisyon_hizmet_id', $item->id)->sum('tutar');
                                $kalan = $item->fiyat - $item->indirim_tutari - $onceki;
                                $kalan = $kalan > 0 ? $kalan : 0;

                                if($kalan > 0 && $toplam_kalan_borc > 0)
                                {
                                    $odeme_tutari = ($kalan / $toplam_kalan_borc) * $kismi_odeme;

                                    $odeme = new TahsilatHizmetler();
                                    $odeme->adisyon_hizmet_id = $item->id;
                                    $odeme->tahsilat_id = $tahsilat->id;
                                    $odeme->tutar = $odeme_tutari;
                                    $odeme->save();
                                }
                                break;

                            case 'urun':
                                $onceki = TahsilatUrunler::where('adisyon_urun_id', $item->id)->sum('tutar');
                                $kalan = $item->fiyat - $item->indirim_tutari - $onceki;
                                $kalan = $kalan > 0 ? $kalan : 0;

                                if($kalan > 0 && $toplam_kalan_borc > 0)
                                {
                                    $odeme_tutari = ($kalan / $toplam_kalan_borc) * $kismi_odeme;

                                    $odeme = new TahsilatUrunler();
                                    $odeme->adisyon_urun_id = $item->id;
                                    $odeme->tahsilat_id = $tahsilat->id;
                                    $odeme->tutar = $odeme_tutari;
                                    $odeme->aciklama = "(($item->fiyat - $item->indirim_tutari - $onceki)/$toplam_kalan_borc) * $kismi_odeme";
                                    $odeme->save();
                                }
                                break;

                            case 'paket':
                                $onceki = TahsilatPaketler::where('adisyon_paket_id', $item->id)->sum('tutar');
                                $kalan = $item->fiyat - $item->indirim_tutari - $onceki;
                                $kalan = $kalan > 0 ? $kalan : 0;

                                if($kalan > 0 && $toplam_kalan_borc > 0)
                                {
                                    $odeme_tutari = ($kalan / $toplam_kalan_borc) * $kismi_odeme;

                                    $odeme = new TahsilatPaketler();
                                    $odeme->adisyon_paket_id = $item->id;
                                    $odeme->tahsilat_id = $tahsilat->id;
                                    $odeme->tutar = $odeme_tutari;
                                    $odeme->aciklama = "(($item->fiyat - $item->indirim_tutari - $onceki)/$toplam_kalan_borc) * $kismi_odeme";
                                    $odeme->save();
                                }
                                break;
                        }
                    }
                }
                if($taksit_vade->tutar > $tahsilatTutari)
                {
                    $yeniVade = $taksit_vade->replicate();
                    $yeniVade->tutar = $taksit_vade->tutar - $tahsilatTutari;

                    $yeniVade->save();
                    $taksit_vade->tutar = $tahsilatTutari;
                    $taksit_vade->odendi = 1;
                }
                $taksit_vade->save();
                // Tahsilat tutarını güncelle
                $tahsilatTutari -= $kismi_odeme;

                
                if($tahsilatTutari <= 0)
                    break; // Ödeme bitti
            }
        }

        if(isset($request->senet_vade_id))
        {
            foreach($request->senet_vade_id as $senetvadesi)
            {
                $senet_vade = SenetVadeleri::where('id', $senetvadesi)->first();
                $senet_vade->odendi = true;
                $senet_vade->odeme_yontemi_id = $request->odeme_yontemi;
                $senet_vade->save();
                $senet_toplami = SenetVadeleri::where('senet_id',$senet_vade->senet_id)->sum('tutar');
                foreach(AdisyonHizmetler::where('senet_id',$senet_vade->senet_id)->get() as $key=>$hizmet)
                {
                    $oncekitahsilatlar = TahsilatHizmetler::where('adisyon_hizmet_id',$hizmet->id)->sum('tutar');
                    $odeme = new TahsilatHizmetler();
                    $odeme->adisyon_hizmet_id = $hizmet->id;
                    $odeme->tahsilat_id = $tahsilat->id;
                    $hizmet_tahsilat_tutar = $hizmet->fiyat;
                    $odeme->tutar = ((str_replace(['.',','],['','.'],$hizmet_tahsilat_tutar)-$hizmet->indirim_tutari-$oncekitahsilatlar)/str_replace(['.',','],['','.'],$senet_toplami))*str_replace(['.',','],['','.'],$request->indirimli_toplam_tahsilat_tutari);
                    $odeme->save();
                }
                foreach(AdisyonUrunler::where('senet_id',$senet_vade->senet_id)->get() as $key2=>$urun)
                {
                    $oncekitahsilatlar = TahsilatUrunler::where('adisyon_urun_id',$urun->id)->sum('tutar');
                    $odeme = new TahsilatUrunler();
                    $odeme->adisyon_urun_id = $urun->id;
                    $odeme->tahsilat_id = $tahsilat->id;
                    $urun_tahsilat_tutar = $urun->fiyat;
                    $odeme->tutar = ((str_replace(['.',','],['','.'],$urun_tahsilat_tutar)-$urun->indirim_tutari-$oncekitahsilatlar)/str_replace(['.',','],['','.'],$senet_toplami))*str_replace(['.',','],['','.'],$request->indirimli_toplam_tahsilat_tutari);
                    $odeme->save();
                }
                foreach(AdisyonPaketler::where('senet_id',$senet_vade->senet_id)->get() as $key3=>$paket)
                {
                    $oncekitahsilatlar = TahsilatPaketler::where('adisyon_paket_id',$paket->id)->sum('tutar');
                    $odeme = new TahsilatPaketler();
                    $odeme->adisyon_paket_id = $paket->id;
                    $odeme->tahsilat_id = $tahsilat->id;
                    $paket_tahsilat_tutar = $paket->fiyat;
                    $odeme->tutar = ((str_replace(['.',','],['','.'],$paket_tahsilat_tutar)-$paket->indirim_tutari-$oncekitahsilatlar)/str_replace(['.',','],['','.'],$senet_toplami))*str_replace(['.',','],['','.'],$request->indirimli_toplam_tahsilat_tutari);
                    $odeme->save();
                }
            }
        }
        $alacak = str_replace('.','',$request->odenecek_tutar);
        if($alacak != 0)
        {
            $alacak_kaydi = new Alacaklar();
            $alacak_kaydi->salon_id = $request->sube;
            $alacak_kaydi->adisyon_id = $request->adisyon_id;
            $alacak_kaydi->tutar = $alacak;
            $alacak_kaydi->aciklama = $request->tahsilat_notlari;
            $alacak_kaydi->planlanan_odeme_tarihi = $request->planlanan_alacak_tarihi;
            $alacak_kaydi->olusturan_id = Auth::guard('isletmeyonetim')->user()->id;
            $alacak_kaydi->salon_id = $request->sube;
            $alacak_kaydi->user_id = $tahsilat->user_id;
            $alacak_kaydi->save();
        }
        return self::musteri_tahsilatlari($request,$request->tahsilat_musteri_id,$request->adisyon_id,false);
    }
    public function tahsilatdetaygetir(Request $request)
    {
        return DB::table('tahsilatlar')->select('odeme_tarihi as tarih','tutar as tutar','odeme_yontemi_id as odeme_yontemi','notlar as notlar')->where('id',$request->tahsilat_id)->get();
    }

    /**
     * KASA DEFTERI > GELIRLER listesinde bir satira tiklayinca acilan detay popup'inin verisi.
     * Tahsilat header bilgisi + odenen adisyon kalemleri (hizmet/urun/paket) kirilimi doner.
     */
    public function kasaGelirDetay(Request $request)
    {
        $salon_id = self::mevcutsube($request);

        $tahsilat = Tahsilatlar::with([
            'musteri','olusturan','satici','odeme_yontemi','banka','adisyon',
            'hizmet_odemeleri.adisyon_hizmet.hizmet',
            'hizmet_odemeleri.adisyon_hizmet.personel',
            'urun_odemeleri.adisyon_urun.urun',
            'paket_odemeleri.adisyon_paket.paket',
        ])->where('id',$request->tahsilat_id)->where('salon_id',$salon_id)->first();

        if(!$tahsilat){
            return response()->json(['durum'=>'hata','mesaj'=>'Kayit bulunamadi.'],404);
        }

        $kalemler = [];
        foreach($tahsilat->hizmet_odemeleri as $h){
            $ah = $h->adisyon_hizmet;
            $kalemler[] = [
                'tip'      => 'Hizmet',
                'ad'       => ($ah && $ah->hizmet) ? $ah->hizmet->hizmet_adi : '-',
                'personel' => ($ah && $ah->personel) ? $ah->personel->personel_adi : '',
                'adet'     => 1,
                'tutar'    => number_format((float)$h->tutar,2,',','.'),
            ];
        }
        foreach($tahsilat->urun_odemeleri as $u){
            $au = $u->adisyon_urun;
            $kalemler[] = [
                'tip'      => 'Ürün',
                'ad'       => ($au && $au->urun) ? $au->urun->urun_adi : '-',
                'personel' => '',
                'adet'     => $au ? $au->adet : 1,
                'tutar'    => number_format((float)$u->tutar,2,',','.'),
            ];
        }
        foreach($tahsilat->paket_odemeleri as $p){
            $ap = $p->adisyon_paket;
            $kalemler[] = [
                'tip'      => 'Paket',
                'ad'       => ($ap && $ap->paket) ? $ap->paket->paket_adi : '-',
                'personel' => '',
                'adet'     => 1,
                'tutar'    => number_format((float)$p->tutar,2,',','.'),
            ];
        }

        if($tahsilat->para_girisi)        $tip = 'Kasa Para Girişi';
        elseif($tahsilat->para_cikisi)    $tip = 'Kasa Para Çıkışı';
        elseif($tahsilat->adisyon_id)     $tip = 'Satış Tahsilatı';
        else                              $tip = 'Bağımsız Tahsilat';

        return response()->json([
            'durum'         => 'ok',
            'tip'           => $tip,
            'tarih'         => date('d.m.Y', strtotime($tahsilat->odeme_tarihi)),
            'saat'          => date('H:i', strtotime($tahsilat->odeme_tarihi)),
            'musteri'       => $tahsilat->musteri ? $tahsilat->musteri->name : '-',
            'tahsil_eden'   => $tahsilat->olusturan ? $tahsilat->olusturan->personel_adi : '-',
            'satici'        => $tahsilat->satici ? $tahsilat->satici->personel_adi : '',
            'odeme_yontemi' => $tahsilat->odeme_yontemi ? $tahsilat->odeme_yontemi->odeme_yontemi : '-',
            'banka'         => $tahsilat->banka ? $tahsilat->banka->banka : '',
            'notlar'        => $tahsilat->notlar ?: '',
            'tutar'         => number_format((float)$tahsilat->tutar,2,',','.'),
            'adisyon_id'    => $tahsilat->adisyon_id,
            'harici'        => $tahsilat->adisyon ? (int)($tahsilat->adisyon->harici ?? 0) : 0,
            'kalemler'      => $kalemler,
        ]);
    }
    public function adisyonlar(Request $request){
         $isletmeler = '';
        $isletme='';
        if(Auth::guard('satisortakligi')->check())
        {
            $isletmeler = [15];
            $isletme = Salonlar::where('id',15)->first();
        }
        else{
            $isletmeler = Auth::guard('isletmeyonetim')->user()->yetkili_olunan_isletmeler->where('aktif',1)->pluck('salon_id')->toArray();
            $isletme= Salonlar::where('id',self::mevcutsube($request))->first();
        }
        
        
        if(!in_array(self::mevcutsube($request),$isletmeler ) || $_SERVER["HTTP_HOST"]=="randevu.randevumcepte.com.tr")
        {
            return view('isletmeadmin.yetkisizerisim');
            exit(0);
        }
        if(str_contains(self::lisans_sure_kontrol($request),'-'))
        {
            return view('isletmeadmin.lisanssurebitti',['isletme'=>$isletme]);
            exit(0);
        }
        // Yetki: bu sayfanin gerektirdigi yetki yoksa 403
        $_authUser = Auth::guard('isletmeyonetim')->user();
        if ($_authUser && !(
            \App\Services\PersonelYetkiServisi::yetkiliYetkiVar($_authUser->id, self::mevcutsube($request), 'satis.adisyon_olustur')
            || \App\Services\PersonelYetkiServisi::yetkiliYetkiVar($_authUser->id, self::mevcutsube($request), 'satis.tahsilat_al')
            || \App\Services\PersonelYetkiServisi::yetkiliYetkiVar($_authUser->id, self::mevcutsube($request), 'satis.tum_satis_gor')
        )) {
