    public function hareket_ekle(Request $request,$islem)
    {
        $hareketler = new RandevuHareketleri();
        $hareketler->personel_id = Auth::guard('isletmeyonetim')->user()->personel_id;
        $hareketler->randevu_id = $request->randevu_id;
        $hareketler->islem = $islem;
        $hareketler->save();
    }
    public function tahsilatkaldir(Request $request){
        if($r = self::satisYetkiYoksa403($request, 'satis.tahsilat_sil')) return $r;

        $islemYapan = Personeller::where('yetkili_id',Auth::guard('isletmeyonetim')->user()->id)->where('salon_id',$request->sube)->first();
        $hesapSahibi = Personeller::where('salon_id',$request->sube)->where('role_id',1)->first();
        $hesapSahibiYetkili = IsletmeYetkilileri::where('id',$hesapSahibi->yetkili_id)->first();
        $tahsilat = Tahsilatlar::where('id',$request->tahsilatid)->first();
        if($islemYapan->role_id > 1)
        {
            Log::info('işlem yapan hesap sahibi değil');
            $smsAyari = SalonSMSAyarlari::where('salon_id',$request->sube)->where('ayar_id',23)->where('personel',1)->first();
            
            if($smsAyari && ($tahsilat->dogrulama_kodu == null || $request->dogrulama_kodu == ''))
            {
                Log::info('Hesap sahibine kod gitme ayarı açık');
                if($tahsilat->dogrulama_kodu == null)
                {
                    Log::info('Doğrulama kodu gönderilecek');
                    $random = str_shuffle('1234567890');
                    $kod = substr($random, 0, 4);
                    $tahsilat->dogrulama_kodu = $kod;
                    $tahsilat->save();
                    $mesaj = $islemYapan->personel_adi.' '.date('d.m.Y',strtotime($tahsilat->odeme_tarihi)).' tarihli '.number_format($tahsilat->tutar, 2, ',', '.').' ₺ tutarındaki tahsilatı silmek için onayınızı istiyor. Onay Kodu : '.$kod;

                     
                    $mesajlar = array(
                        array("to"=>$hesapSahibiYetkili->gsm1,"message"=>$mesaj),
                    );
                    self::sms_gonder_bildirimli($request,$mesajlar,false,1,true);
                    return array(
                        'dogrulamaGerekli'=>true,
                    
                    );
                }
                else
                {
                    if($tahsilat->dogrulama_kodu != $request->dogrulama_kodu)
                         return array(
                            'dogrulamaGerekli'=>true,
                        
                        );
                }
            }  
        }
        $adisyon_id = $request->adisyon_id;
        // Audit (silmeden once)
        $_audit_adisyon_user_id = Adisyonlar::where('id',$adisyon_id)->value('user_id');
        $_audit_musteriAdi = $_audit_adisyon_user_id ? (\App\User::where('id',$_audit_adisyon_user_id)->value('name') ?? 'Müşteri #'.$_audit_adisyon_user_id) : '-';
        $_audit_tutar = number_format((float)$tahsilat->tutar, 2, ',', '.');
        SalonAudit::log($request->sube, 'tahsilat_sil', 'tahsilat', $tahsilat->id,
            $_audit_musteriAdi.' — '.$_audit_tutar.' ₺',
            'Tahsilat kaydı silindi',
            ['adisyon_id'=>$adisyon_id, 'odeme_yontemi_id'=>$tahsilat->odeme_yontemi_id, 'tutar'=>$tahsilat->tutar]);
        $tahsilat_paketler = TahsilatPaketler::where('tahsilat_id',$request->tahsilatid)->get();
        $tahsilat_urunler = TahsilatUrunler::where('tahsilat_id',$request->tahsilatid)->get();
        $tahsilat_hizmetler = TahsilatHizmetler::where('tahsilat_id',$request->tahsilatid)->get();
        $taksitler = array();
        foreach($tahsilat_paketler as $tahsilat_paket){
            $adisyonPaket = AdisyonPaketler::where('id',$tahsilat_paket->adisyon_paket_id)->first();
            $adisyonPaket->hediye = false;
            $adisyonPaket->indirim_tutari = null;
            $adisyonPaket->save();
            if($adisyonPaket->taksitli_tahsilat_id != null)
                array_push($taksitler, $adisyonPaket->taksitli_tahsilat_id);
            $tahsilat_paket->delete();
           
            //array_push($taksitler, TaksitVadeleri::where(''))
        }
        foreach($tahsilat_urunler as $tahsilat_urun){
            $adisyonUrun = AdisyonUrunler::where('id',$tahsilat_urun->adisyon_urun_id)->first();
            $adisyonUrun->hediye = false;
            $adisyonUrun->indirim_tutari = null;
            $adisyonUrun->save();
            if($adisyonUrun->taksitli_tahsilat_id != null)
                array_push($taksitler,$adisyonUrun->taksitli_tahsilat_id);

            $tahsilat_urun->delete();
        }
        foreach($tahsilat_hizmetler as $tahsilat_hizmet){
            $adisyonHizmet = AdisyonHizmetler::where('id',$tahsilat_hizmet->adisyon_hizmet_id)->first();
            $adisyonHizmet->hediye = false;
            $adisyonHizmet->indirim_tutari = null;
            $adisyonHizmet->save();
            if($adisyonHizmet->taksitli_tahsilat_id != null)
                array_push($taksitler,$adisyonHizmet->taksitli_tahsilat_id);
            $tahsilat_hizmet->delete();

        }
        $taksitliTahsilatlar = TaksitliTahsilatlar::whereIn('id',$taksitler)->get();
        $taksitToplamlari = 0;
        $vadeler = array();
        if($taksitliTahsilatlar->count()>0)
        {
            foreach($taksitliTahsilatlar as $taksitliTahsilat)
            {
                foreach($taksitliTahsilat->vadeler as $taksitVade){
                    $taksitToplamlari += (float) $taksitVade->tutar;
                    array_push($vadeler,$taksitVade->id);
                    if($taksitToplamlari == $tahsilat->tutar)
                        break;

                }
                if($taksitToplamlari == $tahsilat->tutar)
                    break;
            }
            foreach(TaksitVadeleri::whereIn('id',$vadeler)->get() as $_vade)
            {
                $_vade->odendi = false;
                $_vade->save();
            }
        }
        
        


       
         
        
        $musteri_id = $tahsilat->user_id;

        $paraGirisi = $tahsilat->para_girisi;
        $kasadanSil = filter_var($request->kasadan_sil, FILTER_VALIDATE_BOOLEAN);
        $request->sube = $tahsilat->salon_id;
        $tahsilat->delete();

        if($paraGirisi || $kasadanSil){
            return array(
                'mesaj' => $paraGirisi ? 'Para ekleme kaydı başarıyla kaldırıldı' : 'Tahsilat kaydı başarıyla silindi',
                'dogrulamaGerekli'=>false,
                'kasa_raporu'=>self::kasa_raporu_getir($request,'')
            );
            exit;
        }

        else{
            return self::musteri_tahsilatlari($request,$musteri_id,$adisyon_id,false);
            exit;
        }
    }
    public function ongorusmeler(Request $request)
    {
      $isletmeler = '';
        $isletme='';
        if(Auth::guard('satisortakligi')->check())
        {
            $isletmeler = [15];
            $isletme = Salonlar::where('id',15)->first();
        }
        else{
            $isletmeler = Auth::guard('isletmeyonetim')->user()->yetkili_olunan_isletmeler->where('aktif',1)->pluck('salon_id')->toArray();
            $isletme= Salonlar::where('id',self::mevcutsube($request))->first();
        }


        if(!in_array(self::mevcutsube($request),$isletmeler ))
        {
            return view('isletmeadmin.yetkisizerisim');
            exit(0);
        }
        if(str_contains(self::lisans_sure_kontrol($request),'-'))
        {
            return view('isletmeadmin.lisanssurebitti',['isletme'=>$isletme]);
            exit(0);
        }
        // Yetki: bu sayfanin gerektirdigi yetki yoksa 403
        $_authUser = Auth::guard('isletmeyonetim')->user();
        if ($_authUser && !\App\Services\PersonelYetkiServisi::yetkiliYetkiVar($_authUser->id, self::mevcutsube($request), 'gorusme.liste_gor')) {
            return view('isletmeadmin.yetkisizerisim');
            exit(0);
        }

        if(count($isletmeler)>1 && !isset($_GET['sube']))
        {
            return view('isletmeadmin.isletmesec',['isletmeler'=>$isletmeler,'isletme'=>$isletme]);
            exit(0);
        }
        $ongorusmeler = self::ongorusmegetir($request,false);
        $paketler = self::paket_liste_getir('',true,$request);
        return view('isletmeadmin.ongorusmeler',['paketler'=>$paketler,'bildirimler'=>self::bildirimgetir($request),'sayfa_baslik'=>'Ön Görüşmeler','on_gorusmeler'=>$ongorusmeler,'pageindex' => 12,'isletme'=>$isletme, 'kalan_uyelik_suresi' => self::lisans_sure_kontrol($request),'urun_drop'=>self::urundropliste($request),'hizmet_drop'=>self::hizmetdropliste($request),'yetkiliolunanisletmeler'=>$isletmeler]);
    }
    public function ongorusmeekleduzenle(Request $request)
    {
        if($r = self::yetkiYoksa403($request, 'gorusme.ekle_duzenle')) return $r;
        // Self-heal: migration kosulmadiysa gorusme_konusu kolonunu burada ekle
        if (!\Schema::hasColumn('on_gorusmeler', 'gorusme_konusu')) {
            try {
                DB::statement('ALTER TABLE on_gorusmeler ADD COLUMN gorusme_konusu VARCHAR(255) NULL');
                $migName = '2026_04_26_000002_add_gorusme_konusu_to_on_gorusmeler';
                if (!DB::table('migrations')->where('migration', $migName)->count()) {
                    $batch = (int) DB::table('migrations')->max('batch');
                    DB::table('migrations')->insert(['migration' => $migName, 'batch' => $batch ?: 1]);
                }
            } catch (\Exception $e) { /* sessizce gec */ }
        }
        $ongorusme = "";
        if($request->on_gorusme_id != "")
        {
            $ongorusme = OnGorusmeler::where('id',$request->on_gorusme_id)->first();
        }
        else
        {
            $ongorusme = new OnGorusmeler();
        }
        if($request->musteri_id != 0)
            $ongorusme->user_id = $request->musteri_id;
        else
        {
            $user = '';
            $portfoy = '';
            if(User::where('cep_telefon',$request->telefon)->count() > 0){
                $user = User::where('cep_telefon',$request->telefon)->first();
            }
            else
                $user = new User();
            $user->name = $request->ad_soyad;
            $user->cep_telefon = $request->telefon;
            $user->cinsiyet = $request->cinsiyet;
            $user->adres = $request->adres;
            $user->il_id = $request->sehir;
            $user->meslek = $request->meslek;
            $user->email = $request->email;
            $user->save();
            if(MusteriPortfoy::where('user_id',$user->id)->where('salon_id',$request->sube)->count()>0)
                $portfoy = MusteriPortfoy::where('user_id',$user->id)->where('salon_id',$request->sube)->first();
            else
                $portfoy = new MusteriPortfoy();
            $portfoy->salon_id=$request->sube;
            $portfoy->musteri_tipi = $request->musteri_tipi;
            $portfoy->aktif = 1;
            $portfoy->kara_liste = 0;
            $portfoy->user_id = $user->id;
            $portfoy->olusturan_personel_id = \App\Services\PersonelYetkiServisi::authPersonelId($portfoy->salon_id);
            $portfoy->save();
            $ongorusme->user_id = $user->id;
        }
        $ongorusme->salon_id = $request->sube;
        $ongorusme->ad_soyad = $request->ad_soyad;
        $ongorusme->cep_telefon = $request->telefon;
        $ongorusme->email =$request->email;
        $ongorusme->cinsiyet = $request->cinsiyet;
        $ongorusme->adres = $request->adres;
        $ongorusme->aciklama=$request->aciklama;
        $ongorusme->il_id =$request->sehir;
        $ongorusme->musteri_tipi = $request->musteri_tipi;
        $ongorusme->meslek = $request->meslek;
        // Eski paket/urun/hizmet select sistemi — paket_urun degeri "urun-X", "hizmet-X" veya paket_id (numerik)
        $ongorusme->paket_id = null;
        $ongorusme->urun_id = null;
        $ongorusme->hizmet_id = null;
        if(str_contains($request->paket_urun, 'urun')){
            $str = explode('-', $request->paket_urun);
            $ongorusme->urun_id = $str[1] ?? null;
        } elseif(str_contains($request->paket_urun, 'hizmet')) {
            $str = explode('-', $request->paket_urun);
            $ongorusme->hizmet_id = $str[1] ?? null;
        } else {
            $ongorusme->paket_id = is_numeric($request->paket_urun) ? $request->paket_urun : null;
        }
        if (\Schema::hasColumn('on_gorusmeler', 'gorusme_konusu')) {
            $ongorusme->gorusme_konusu = null; // free-text artik kullanilmiyor
        }
        $ongorusme->hatirlatma_tarihi = $request->ongorusme_tarihi;
        $ongorusme->personel_id = $request->gorusmeyi_yapan;
        $ongorusme->save();
        $eskirandevu = Randevular::where('on_gorusme_id',$ongorusme->id)->first();
        if($eskirandevu){
            foreach($eskirandevu->hizmetler as $hizmet){
                $hizmet->delete();
                RandevuHizmetYardimciPersonel::where('randevu_hizmet_id',$hizmet->id)->delete();
            }
            $eskirandevu->delete();
        }
        $randevu = new Randevular();
        $randevu->on_gorusme_id = $ongorusme->id;
        $randevu->user_id = $ongorusme->user_id;
        $randevu->salon_id = $ongorusme->salon_id;
        $randevu->tarih = $request->ongorusme_tarihi;
        $randevu->saat = $request->ongorusme_saati;
        $randevu->salon = true;
        $randevu->sms_hatirlatma = true;
        $randevu->durum = 1;
        $randevu->olusturan_personel_id = Auth::guard('isletmeyonetim')->user()->id;
        $randevu->save();
        $ongorusmehizmeti = new RandevuHizmetler();
        $ongorusmehizmeti->hizmet_id = 0;
        $ongorusmehizmeti->personel_id =  $request->gorusmeyi_yapan;
        $ongorusmehizmeti->saat = $request->ongorusme_saati;
        $ongorusmehizmeti->saat_bitis = date('H:i:s',strtotime('+1 hours',strtotime($request->ongorusme_saati)));
        $ongorusmehizmeti->sure_dk = 60; // Calendar query "sure_dk > 0" filtresi icin
        $ongorusmehizmeti->randevu_id = $randevu->id;
