    public function ongorusmedetay(Request $request){
        return json_encode(
            DB::table('randevular')
                ->join('on_gorusmeler','randevular.on_gorusme_id','=','on_gorusmeler.id')
                ->leftJoin('paketler','on_gorusmeler.paket_id','=','paketler.id')
                ->leftJoin('urunler','on_gorusmeler.urun_id','=','urunler.id')
                ->leftJoin('hizmetler','on_gorusmeler.hizmet_id','=','hizmetler.id')
                ->leftJoin('randevu_hizmetler','randevu_hizmetler.randevu_id','=','randevular.id')
                ->select(
                    'on_gorusmeler.*',
                    'randevular.tarih as tarih',
                    'randevular.saat as saat',
                    'randevu_hizmetler.oda_id as oda_id',
                    'paketler.paket_adi as paket_adi',
                    'urunler.urun_adi as urun_adi',
                    'hizmetler.hizmet_adi as hizmet_adi'
                )
                ->where('on_gorusmeler.id',$request->ongorusme_id)
                ->first()
        );
    }
    public function hatirlatmasmsgonder(Request $request){
        if($r = self::yetkiYoksa403($request, 'pazarlama.sms_gonder')) return $r;
        $ongorusmeler = OnGorusmeler::whereIn('id',$request->on_gorusme_bilgi)->get();
        $mesajlar = array();
        foreach($ongorusmeler as $ongorusme)
        {
            $paketstr = "";
            if($ongorusme->paket->tip == 0)
                $paketstr = "Dakika";
            else
                $paketstr = "Seans";
            array_push($mesajlar, array("to"=>$ongorusme->cep_telefon,"message"=> "Sayın ".$ongorusme->ad_soyad."\n\n". $ongorusme->paket->paket_adi." ile ilgili ön görüşme sağlamıştık. Geri dönüşünüzü beklediğimizi belirtir, iyi günler dileriz."));
        }
        self::sms_gonder_bildirimli($request,$mesajlar,true,1,false);
    }
    public function sms_gonder_bildirimli(Request $request,$mesajlar,$geribildirimgonder,$tur,$dogrulama,$salonOverride=null)
    {
        // $salonOverride: cagri yeri salon_id'yi ACIKCA biliyorsa bunu kullan.
        // Aksi halde mevcutsube — multi-branch kullanicida ilk yetkili salonu doner,
        // bu da yanlis salon'un SMS basligi/WA oturumu kullanilmasina neden olabilir
        // (randevu sahibi salon 397 iken SMS salon 20 basligindan giderdi).
        $aktifSalonId = $salonOverride ?: self::mevcutsube($request);
        $isletme = Salonlar::where('id', $aktifSalonId)->first();

        // WhatsApp pre-filter: salon WA aktif+connected ise her mesaj once WhatsApp'a
        // kuyruga girer. Hemen basarisiz olanlar (4xx/5xx/timeout) SMS yoluyla devam eder;
        // 202 (queued) donen mesajlar listeden cikarilir, webhook fail bildirirse Laravel
        // o noktada SMS fallback'i tetikler (WhatsAppWebhookController::onMessageFailed).
        // Paylasilan oturum: 416 icin 246'nin whatsapp durumuna bakilir.
        $waIsletme = $isletme ? \App\Services\WhatsAppService::resolveWaSalon($isletme) : null;
        $waKanaliAcik = $waIsletme && !empty($waIsletme->whatsapp_aktif) && ($waIsletme->whatsapp_durum ?? null) === 'connected';
        $mesajVarMi = is_array($mesajlar) && count($mesajlar) > 0;
        Log::info('[Transactional WA] pre-filter durumu', [
            'salon_id' => $isletme->id ?? null,
            'wa_session_salon_id' => $waIsletme->id ?? null,
            'salon_var_mi' => (bool) $isletme,
            'wa_aktif' => $waIsletme ? (int) ($waIsletme->whatsapp_aktif ?? 0) : null,
            'wa_durum' => $waIsletme->whatsapp_durum ?? null,
            'wa_kanali_acik' => $waKanaliAcik,
            'mesaj_sayisi' => is_array($mesajlar) ? count($mesajlar) : -1,
            'mesaj_var_mi' => $mesajVarMi,
            'tur' => $tur,
            'caller' => debug_backtrace(DEBUG_BACKTRACE_IGNORE_ARGS, 3)[1]['function'] ?? null,
            'caller2' => debug_backtrace(DEBUG_BACKTRACE_IGNORE_ARGS, 3)[2]['function'] ?? null,
        ]);
        if ($waKanaliAcik && $mesajVarMi) {
            try {
                $wa = app(\App\Services\WhatsAppService::class);
                $kalan = [];
                foreach ($mesajlar as $mesaj) {
                    $to = $mesaj['to'] ?? null;
                    $msg = $mesaj['message'] ?? null;
                    if (!$to || !$msg) { $kalan[] = $mesaj; continue; }
                    // OTP/dogrulama gibi anlik gitmesi gereken mesajlar urgent=true ile
                    // antiban pre-delay/typing/batch/saat kisitini atlar (mesaj basina
                    // 'urgent' bayragi). Aksi halde kod 12-30sn+ kuyrukta bekler.
                    $waUrgent = !empty($mesaj['urgent']);
                    // WA icin cagri yeri farkli metin verebilir (zenginlestirilmis
                    // format). Yoksa SMS metni ile ayni gonderilir (eski davranis).
                    $waMsg = $mesaj['wa_message'] ?? $msg;
                    $sonuc = $wa->sendReminder($isletme, $to, $waMsg, $mesaj['randevu_id'] ?? null, $mesaj['user_id'] ?? null, null, $waUrgent, 'transaksiyonel');
                    if ($sonuc['ok'] ?? false) {
                        Log::info('[Transactional WA] kuyruğa eklendi', [
                            'salon_id' => $isletme->id, 'to' => $to, 'logId' => $sonuc['logId'] ?? null, 'tur' => $tur,
                        ]);
                        continue; // WA kuyruğuna girdi → bu mesajı SMS'e atma
                    }
                    Log::warning('[Transactional WA] başarısız → SMS\'e düşüyor', [
                        'salon_id' => $isletme->id, 'to' => $to, 'err' => $sonuc['error'] ?? 'unknown',
                    ]);
                    $kalan[] = $mesaj;
                }
                $mesajlar = $kalan;
                if (count($mesajlar) === 0) {
                    return $geribildirimgonder ? [
                        'title' => 'Başarılı',
                        'status' => 'success',
                        'text' => 'Mesajınız alıcılarınıza başarıyla iletildi.',
                    ] : null;
                }
            } catch (\Throwable $e) {
                Log::warning('[Transactional WA] istisna, SMS\'e düşülüyor', [
                    'err' => $e->getMessage(), 'salon_id' => $isletme->id ?? null,
                ]);
            }
        }

        if($isletme->yeni_sms == 1)
        {

            require_once app_path('VoiceTelekom/Sms/SmsApi.php');
            require_once app_path('VoiceTelekom/Sms/SendMultiSms.php');
            require_once app_path('VoiceTelekom/Sms/PeriodicSettings.php');

            foreach($mesajlar as $mesaj)
            {
                $smsApi = new \SmsApi("smsvt.voicetelekom.com", $isletme->sms_user_name, $isletme->sms_secret);
                $request = new \SendMultiSms();

                // 1. Benzersiz customID oluştur
                $request->customID = "sms_" . date('Ymd_His') . "_" . substr(md5(microtime()), 0, 8);

                $request->content = $mesaj['message'];
                $turBasliklari = SMSController::VT_TUR_BASLIKLARI;
                $request->title = isset($turBasliklari[$tur]) ? $turBasliklari[$tur] : 'Bildirim';
                $toList = [$mesaj['to']];
                Log::info('To list '.json_encode($toList));

                $request->numbers = $toList;
                $request->encoding = 0;
                $request->sender = $isletme->sms_baslik;
                $request->skipAhsQuery = true; 
                // 2. Ticari gönderim olduğunu belirt
                

                // 3. Gönderim tarihine küçük bir fark ekle (opsiyonel)
                // $request->sendingDate = date('Y-m-d H:i:s', strtotime('+1 minute'));

                Log::info('SMS gönderiliyor. CustomID: ' . $request->customID);

                try {
                    $response = $smsApi->sendMultiSms($request);
                    
                    if($response->err == null){
                        Log::info("MessageId: ".$response->pkgID."\n");
                        
                        if($geribildirimgonder){
                           return array(
                                'title' =>'Başarılı',
                                'status' =>'success',
                                'text'=>'Mesajınız alıcılarınıza başarıyla gönderildi.',
                            );
                        }
                    } else {
                        // ERR_SMS_PKG_DUPLICATION hatası için özel işlem
                        if($response->err->code == 'ERR_SMS_PKG_DUPLICATION'){
                            Log::warning('Duplicate SMS hatası. CustomID: ' . $request->customID);
                            
                            // 1 saniye bekle ve farklı bir customID ile tekrar dene
                            sleep(1);
                            $request->customID = "retry_" . date('Ymd_His') . "_" . rand(10000, 99999);
                            
                            Log::info('Tekrar deneme. Yeni CustomID: ' . $request->customID);
                            $response = $smsApi->sendMultiSms($request);
                            
                            if($response->err == null){
                                Log::info("İkinci deneme başarılı. MessageId: ".$response->pkgID);
                                if($geribildirimgonder){
                                    return array(
                                        'title' =>'Başarılı',
                                        'status' =>'success',
                                        'text'=>'Mesajınız alıcılarınıza başarıyla gönderildi.',
                                    );
                                }
                            }
                        }
                        
                        // Diğer hatalar
                        Log::info("SMS Status: ".$response->err->status."\n");
                        Log::info("Code: ".$response->err->code."\n");
                        Log::info("Message: ".$response->err->message."\n");
                        
                        if($geribildirimgonder){
                            return array(
                                'title' =>'Hata',
                                'status' =>'error',
                                'text'=>'Mesajınız alıcılarınıza gönderilemedi. Hata kodu : '.$response->err->code,
                            );
                        }
                    }
                } catch (\Exception $e) {
                    Log::error('SMS gönderim hatası: ' . $e->getMessage());
                    
                    if($geribildirimgonder){
                        return array(
                            'title' =>'Hata',
                            'status' =>'error',
                            'text'=>'Sistem hatası oluştu.',
                        );
                    }
                }

            }
            
        }
        else{
            if($isletme->sms_baslik !== null && $isletme->sms_apikey !== null)
            {
                $headers = array(
                 'Authorization: Key '.$isletme->sms_apikey,
                 'Content-Type: application/json',
                 'Accept: application/json'
                );
                $postData = json_encode( array( "originator"=> $isletme->sms_baslik, "messages"=> $mesajlar,"encoding"=>"auto") );
                $ch=curl_init();
                curl_setopt($ch,CURLOPT_URL,'https://api.efetech.net.tr/v2/sms/multi');
                curl_setopt($ch,CURLOPT_POSTFIELDS,$postData);
                curl_setopt($ch,CURLOPT_POST,1);
                curl_setopt($ch,CURLOPT_TIMEOUT,5);
                curl_setopt($ch,CURLOPT_RETURNTRANSFER,1);
                curl_setopt($ch,CURLOPT_HTTPHEADER,$headers);
                $response=curl_exec($ch);
                $decoded = json_decode($response,true);
                $iletimdurum = '';
                if(count($decoded["response"])!=0 && $decoded != null){
                    if(!$dogrulama)
                    {
                        $rapor = new SMSIletimRaporlari();
                        $rapor->salon_id = $isletme->id;
                        $rapor->tur = $tur;
                        $aciklama = '';
                        foreach($mesajlar as $mesaj)
                            $aciklama .= $mesaj['message'].'\n';
                        $rapor->aciklama = $aciklama;
                        $rapor->rapor_id = $decoded["response"]["message"]["id"];
                        $rapor->adet = $decoded["response"]["message"]["count"];
                        $rapor->kredi = $decoded["response"]["message"]["total_price"];
                        //sleep(0.5);
                        //$durum = self::sms_rapor_getir($decoded["response"]["message"]["id"],$isletme);
                        $rapor->durum = 0;
                        $rapor->save();
                        $iletimdurum = 0;
                    }
                }
                $returntext = '';
                $statustext = '';
                $titletext = '';
                if($iletimdurum==91){
                    $returntext = 'Mesajınız bakiyeniz yetersiz olduğu için alıcılarınıza gönderilemedi.';
                    $titletext = 'Hata';
                    $statustext ='error';
                }
                elseif($iletimdurum==92){
                    $returntext = 'Mesajınız gönderimlerin sağlayıcımız tarafından durudurulması nedeniyle alıcılarınıza gönderilemedi. Lütfen daha sonra tekrar deneyiniz.';
                    $titletext = 'Hata';
                    $statustext ='error';
                }
                elseif($iletimdurum==93){
                    $returntext = 'Mesajınız teknik bir arıza nedeniye alıcılarınıza gönderilemedi. Lütfen daha sonra tekrar deneyiniz.';
                    $titletext = 'Hata';
                    $statustext ='error';
                }
                elseif($iletimdurum==94){
                    $returntext = 'Mesajınız gönderiminiz engellendiği için alıcılarınıza gönderilemedi. Lütfen sistem yöneticisine başvurunuz.';
                    $titletext = 'Hata';
                    $statustext ='error';
                }
                else{
                    $titletext = 'Başarılı';
                    $returntext = 'Mesajınız alıcılarınıza başarıyla gönderildi.';
                    $statustext ='success';
                }
                if($geribildirimgonder){
                      return array(
                        'title' =>$titletext,
                        'status' =>$statustext,
                        'text'=>$returntext,
                    );
                    exit;
                }
                else
                {
                    return '';
                    exit;
                }
            }
            else
            {
                // SMS ayarlari yapilandirilmamis (sms_baslik / sms_apikey yok) ve
                // WhatsApp da bagli degil → mesaj hicbir kanaldan gonderilemiyor.
                // Bu durumda implicit null donmesin; cagiran metodlar $sms['status']
                // erisiminde "array offset on null" server error'u almasin.
                Log::warning('[sms_gonder_bildirimli] SMS ayarlari yapilandirilmamis, mesaj gonderilemedi', [
                    'salon_id' => $isletme->id ?? null,
                    'tur' => $tur,
                ]);
                if($geribildirimgonder){
                    return array(
                        'title' =>'Hata',
                        'status' =>'error',
                        'text'=>'Mesaj gönderilemedi. İşletmenize ait SMS veya WhatsApp bağlantısı bulunmuyor.',
                    );
                }
                return '';
            }
        }
    }
