            DB::raw('CONCAT("<p style=\"display:none\">",DATE_FORMAT(alacaklar.planlanan_odeme_tarihi,"%Y%m%d") ,"</p><span ", CASE WHEN alacaklar.planlanan_odeme_tarihi < NOW() THEN "class=\"btn btn-danger\">" ELSE "class=\"btn btn-primary\">" END,  DATE_FORMAT(alacaklar.planlanan_odeme_tarihi,"%d.%m.%Y"),"</span>" ) as planlanan_odeme_tarihi'),
            /* DB::raw('CASE WHEN (SELECT senet_vadeleri.vade_tarih FROM senet_vadeleri WHERE senet_vadeleri.odendi=false AND senet_vadeleri.senet_id = senetler.id
                                order by senet_vadeleri.id asc  LIMIT 1) IS NULL THEN "<button class=\"btn btn-warning\">Kapalı Senet</button>" ELSE CONCAT("<p style=\"display:none\">",DATE_FORMAT(
                        (SELECT senet_vadeleri.vade_tarih FROM senet_vadeleri WHERE senet_vadeleri.odendi=false AND senet_vadeleri.senet_id = senetler.id
                                order by senet_vadeleri.id asc  LIMIT 1),"%Y%m%d"
                    ),"</p><span class=\"", CASE WHEN (SELECT senet_vadeleri.vade_tarih FROM senet_vadeleri WHERE senet_vadeleri.odendi=false AND senet_vadeleri.senet_id = senetler.id
                                order by senet_vadeleri.id asc  LIMIT 1) < NOW() THEN "btn btn-danger" ELSE "" END ," \">",DATE_FORMAT(
                        (SELECT senet_vadeleri.vade_tarih FROM senet_vadeleri WHERE senet_vadeleri.odendi=false AND senet_vadeleri.senet_id = senetler.id
                                order by senet_vadeleri.id asc  LIMIT 1),"%d.%m.%Y"
                    ),"</span>") END as yaklasan_vade'),*/
            DB::raw('DATE_FORMAT(alacaklar.created_at,"%d.%m.%Y") as olusturulma'),
            DB::raw('CONCAT("<a href=\"/isletmeyonetim/adisyon/",adisyonlar.id,"\" class=\"btn btn-primary\"> Tahsil Et <i class=\"fa fa-chevron-right\"></i></button>") as islemler')
        )->where('alacaklar.salon_id',self::mevcutsube($request))->get();
        return array(
        'alacaklar'=>$alacaklar,
        'alacaklar_hizmet'=>$alacaklar_hizmet,
         'alacaklar_urun'=>$alacaklar_urun,
          'alacaklar_paket'=>$alacaklar_paket,
          'tum_taksitler'=>self::taksitleri_getir($request,'',''),
        'taksitler_acik'=>self::taksitleri_getir($request,0,''),
        'taksitler_kapali'=>self::taksitleri_getir($request,1,''),
            'taksitler_odenmemis'=>self::taksitleri_getir($request,2,''),
      );
    }
    public function masrafekleduzenle(Request $request)
    {
        if($r = self::yetkiYoksa403($request, 'finans.masraf_ekle')) return $r;
        $masraf = "";
        $guncelleme = false;
        // !empty: form masraf_id'yi her zaman gonderir (yeni kayitta bos string).
        // isset bos string icin de true olabildiginden, kopya olusmasini onlemek icin !empty.
        if(!empty($request->masraf_id))
        {
            $masraf = Masraflar::where('id',$request->masraf_id)->first();
            $guncelleme = true;
        }
        else
            $masraf = new Masraflar();
        // Personel gideri mi? (personel kasadan para aldi -> hakedisten dusulur)
        $personelGideri = !empty($request->personel_gideri) ? 1 : 0;

        // Personel giderinde kategori/odeme yontemi bos gelebilir; masraf listesi bu
        // ikisini INNER JOIN ettiginden bos kalirsa satir listede gorunmez. Bu yuzden
        // makul varsayilanlara dusuruyoruz: kategori -> "Personel Gideri", odeme -> Nakit.
        $kategoriId = $request->masraf_kategorisi;
        $odemeId = $request->masraf_odeme_yontemi;
        if($personelGideri){
            if(empty($kategoriId)){
                $kat = MasrafKategorisi::where('kategori','Personel Gideri')->first();
                if(!$kat){
                    $kat = new MasrafKategorisi();
                    $kat->kategori = 'Personel Gideri';
                    $kat->save();
                }
                $kategoriId = $kat->id;
            }
            if(empty($odemeId)){
                $nakit = \App\OdemeYontemleri::where('odeme_yontemi','like','%Nakit%')->first();
                $odemeId = $nakit ? $nakit->id : optional(\App\OdemeYontemleri::first())->id;
            }
        }

        $masraf->salon_id = $request->sube;
        $masraf->masraf_kategori_id = $kategoriId;
        $masraf->tarih = $request->tarih;
        $masraf->odeme_yontemi_id = $odemeId;
        $masraf->harcayan_id = $request->harcayan;
        if(\Schema::hasColumn('masraflar','personel_gideri'))
            $masraf->personel_gideri = $personelGideri;
        $masraf->tutar= str_replace(['.',','],['','.'],$request->masraf_tutari);
        $masraf->aciklama = $request->masraf_aciklama;
        // Notlar alani formdan kaldirildi; sadece gonderildiyse guncelle (edit'te mevcut notu silme)
        if($request->has('masraf_notlari')) $masraf->notlar = $request->masraf_notlari;
        $masraf->save();
        $returntext = '';
        $butontext = '';
        if(!isset($request->masraf_sayfasi))
            $butontext = "<p><a href='/isletmeyonetim/masraflar?sube='".$request->sube." class='btn btn-primary btn-lg btn-block'>Masraf Listeme Git</a></p>";
        $kayitAdi = $personelGideri ? 'Personel gideri' : 'Masraf';
        if($guncelleme)
            $returntext = $kayitAdi.' başarıyla güncellendi';
        else
            $returntext = $kayitAdi.' başarıyla kaydedildi';
        // Audit
        SalonAudit::log($masraf->salon_id, $guncelleme ? 'masraf_guncelle' : 'masraf_ekle', 'masraf', $masraf->id,
            ($masraf->aciklama ?: 'Masraf').' — '.number_format((float)$masraf->tutar,2,',','.').' ₺',
            $guncelleme ? 'Masraf güncellendi' : 'Yeni masraf kaydedildi',
            ['tarih'=>$masraf->tarih, 'kategori'=>$masraf->masraf_kategori_id, 'odeme'=>$masraf->odeme_yontemi_id]);
        return array(
            'mesaj' => $returntext,
            'masraflar' => self::masrafgetir($request),
            'kasa_raporu' =>self::kasa_raporu_getir($request,'')
        );
    }
    public function masraf_sil(Request $request)
    {
        // Eger bu masraf bir personel odemesi (maas/prim/avans) olarak yaratildiysa,
        // baglı PersonelMaasOdemesi kaydını da otomatik sil — boylelikle prim
        // hakedis sayfasındaki "ödendi" durumu da geri alinir.
        $masraf = Masraflar::where('id',$request->masraf_id)->first();
        // Audit
        if ($masraf) {
            SalonAudit::log($masraf->salon_id, 'masraf_sil', 'masraf', $masraf->id,
                ($masraf->aciklama ?: 'Masraf').' — '.number_format((float)$masraf->tutar,2,',','.').' ₺',
                'Masraf silindi',
                ['tarih'=>$masraf->tarih, 'tutar'=>$masraf->tutar, 'personel_odeme_id'=>$masraf->personel_maas_odemesi_id]);
        }
        if ($masraf && $masraf->personel_maas_odemesi_id) {
            try {
                PersonelMaasOdemesi::where('id', $masraf->personel_maas_odemesi_id)->delete();
            } catch (\Exception $e) {
                \Log::warning('Masraf silinirken bagli personel odemesi silinemedi: ' . $e->getMessage());
            }
        }
        Masraflar::where('id',$request->masraf_id)->delete();
        return array(
            'mesaj' => 'Masraf kaydı başarıyla kaldırıldı',
            'masraflar' => self::masrafgetir($request),
            'kasa_raporu'=>self::kasa_raporu_getir($request,'')
        );
    }
    public function masrafSil(Request $request)
    {
        if($r = self::yetkiYoksa403($request, 'finans.masraf_ekle')) return $r;
