        $alacak = "";
        if(isset($request->alacak_id))
            $alacak = Alacaklar::where('id',$request->alacak_id)->first();
        else
            $alacak = new Alacaklar();
        if(isset($request->randevu_id))
            $alacak->randevu_id = $request->randevu_id;
