    public function bildirimkontrolet(Request $request)
    {
        $personel = Auth::guard('isletmeyonetim')->check() ? Personeller::where('salon_id',self::mevcutsube($request) )->where('yetkili_id',Auth::guard('isletmeyonetim')->user()->id)->value('id') : 0;
        $salonId = self::mevcutsube($request);

        // Sayaclar TUM tablo uzerinden hesaplanir; liste limiti ile karistirilmaz.
        // (Aksi halde badge yalnizca yuklenen satirlar icinde sayilip dusuyordu.)
        $okunmamisSayi = Bildirimler::where('personel_id',$personel)
            ->where('salon_id',$salonId)
            ->where('okundu',false)
            ->count();
        $toplamSayi = Bildirimler::where('personel_id',$personel)
            ->where('salon_id',$salonId)
            ->count();

        // Liste SADECE dropdown acilinca (liste=1) uretilir; 30sn poll yalnizca sayac
        // doner -> her poll'de HTML uretip yollama yuku biter. Dropdown'da son 300 kayit
        // (eski bildirimler de gorunsun; on-demand oldugu icin limit yuksek tutulabilir).
        $html = "";
        if ($request->liste == 1) {
        $bildirimler = Bildirimler::setEagerLoads([])
            ->select('id','aciklama','tarih_saat','url','img_src','okundu','randevu_id')
            ->where('personel_id',$personel)
            ->where('salon_id',$salonId)
            ->orderBy('id','desc')
            ->limit(300)
            ->get();
        foreach($bildirimler as $bildirim) {
            $to_time = strtotime(date('Y-m-d H:i:s'));
            $from_time = strtotime($bildirim->tarih_saat);
            $diff = round(abs($to_time - $from_time) / 60, 0) . " dakika önce";
            if ($diff >= 60) {
                $diff = round(abs($to_time - $from_time) / 3600, 0) . " saat önce";
                if (round(abs($to_time - $from_time) / 3600, 0) >= 24) {
                    $diff = date('d.m.Y H:i', strtotime($bildirim->tarih_saat));
                }
            }

            $okunduClass = $bildirim->okundu ? 'is-read' : 'is-unread';
            $imgSrc = !empty($bildirim->img_src) ? $bildirim->img_src : '/public/isletmeyonetim_assets/img/avatar.png';
            $aciklama = e($bildirim->aciklama);
            $url = e($bildirim->url);
            $imgSrcEsc = e($imgSrc);

            $html .= '<div class="rc-notif-item '.$okunduClass.'" data-bildirim-id="'.$bildirim->id.'">';
            $html .=   '<a href="'.$url.'" name="bildirim" data-index-number="'.$bildirim->id.'" data-value="'.$bildirim->randevu_id.'" class="rc-notif-link">';
            $html .=     '<div class="rc-notif-avatar">';
            $html .=       '<img src="'.$imgSrcEsc.'" alt="" loading="lazy" decoding="async">';
            if (!$bildirim->okundu) {
                $html .=   '<span class="rc-notif-dot"></span>';
            }
            $html .=     '</div>';
            $html .=     '<div class="rc-notif-body">';
            $html .=       '<p class="rc-notif-text">'.$aciklama.'</p>';
            $html .=       '<span class="rc-notif-time"><i class="fa fa-clock-o"></i> '.$diff.'</span>';
            $html .=     '</div>';
            $html .=   '</a>';
            $html .=   '<button type="button" class="rc-notif-del" name="bildirim-sil" data-bildirim-id="'.$bildirim->id.'" title="Sil" aria-label="Bildirimi sil"><i class="fa fa-times"></i></button>';
            $html .= '</div>';
        }

        if ($bildirimler->count() == 0) {
            $html .= '<div class="rc-notif-empty"><div class="rc-notif-empty-icon"><i class="icon-copy dw dw-notification"></i></div><p>Bildiriminiz bulunmamaktadır</p></div>';
        }
        } // if ($request->liste == 1)

        return array(
            'bildirim_sayisi' => $okunmamisSayi,
            'toplam_bildirim' => $toplamSayi,
            'bildirimler' => $html
        );
    }
    public function bildirimokundu(Request $request)
    {
        $bildirim = Bildirimler::where('id',$request->bildirim_id)->first();
        $bildirim->okundu = true;
        $bildirim->save();
        return $bildirim->url;
    }
    public function bildirimgit(Request $request, $id)
    {
        $bildirim = Bildirimler::setEagerLoads([])->find($id);
        $sube = self::mevcutsube($request);
        $subeQS = $sube ? ('?sube='.$sube) : '';

        if(!$bildirim) {
            return redirect('/isletmeyonetim/randevular'.$subeQS);
        }

        $bildirim->okundu = true;
        $bildirim->save();

        $url = is_string($bildirim->url) ? trim($bildirim->url) : '';

        if($url && strpos($url, '#not-') === 0) {
            return redirect('/isletmeyonetim/ajanda'.$subeQS);
        }
        if($url && strpos($url, '#form-') === 0) {
            return redirect('/isletmeyonetim/randevular'.$subeQS);
        }
        if($url && $url !== '#' && substr($url, 0, 1) !== '#') {
            return redirect($url);
        }

        if(!empty($bildirim->randevu_id)) {
            $randevu = Randevular::where('id', $bildirim->randevu_id)->first();
            if($randevu && !empty($randevu->user_id)) {
                return redirect('/isletmeyonetim/musteridetay/'.$randevu->user_id.$subeQS);
            }
        }
        if(!empty($bildirim->user_id)) {
            return redirect('/isletmeyonetim/musteridetay/'.$bildirim->user_id.$subeQS);
        }
        return redirect('/isletmeyonetim/randevular'.$subeQS);
    }
    public function bildirimsil(Request $request)
    {
        $personel = Auth::guard('isletmeyonetim')->check()
            ? Personeller::where('salon_id', self::mevcutsube($request))
                ->where('yetkili_id', Auth::guard('isletmeyonetim')->user()->id)
                ->value('id')
            : 0;

        $silinen = Bildirimler::where('id', $request->bildirim_id)
            ->where('personel_id', $personel)
            ->where('salon_id', self::mevcutsube($request))
            ->delete();

        $okunmamis = Bildirimler::where('personel_id', $personel)
            ->where('salon_id', self::mevcutsube($request))
            ->where('okundu', false)
            ->count();
        $toplam = Bildirimler::where('personel_id', $personel)
            ->where('salon_id', self::mevcutsube($request))
            ->count();

        return array(
            'success' => $silinen > 0,
            'bildirim_sayisi' => $okunmamis,
            'toplam_bildirim' => $toplam,
        );
    }
    public function bildirimtumusil(Request $request)
    {
        $personel = Auth::guard('isletmeyonetim')->check()
            ? Personeller::where('salon_id', self::mevcutsube($request))
                ->where('yetkili_id', Auth::guard('isletmeyonetim')->user()->id)
                ->value('id')
            : 0;

        Bildirimler::where('personel_id', $personel)
            ->where('salon_id', self::mevcutsube($request))
            ->delete();

        return array(
            'success' => true,
            'bildirim_sayisi' => 0,
            'toplam_bildirim' => 0,
        );
    }
    public function randevu_liste_filtre(Request $request)
    {
        $tariharaligi = "";
        $web = '';
        $uygulama = '';
        $salon = '';
        $tarih = array();
        if($request->ozeltarih != ''){
            $tariharaligi = $request->ozeltarih;
            $tarih = explode(' / ',$tariharaligi);
        }
        else{
            $tariharaligi = $request->zaman;
            if($tariharaligi != '')
                $tarih = explode(' / ',$tariharaligi);
            else{
                $tarih[0] = '';
                $tarih[1] = '';
            }
        }
        if($request->olusturulma == "web")
            $web = true;
        if($request->olusturulma == "salon")
            $salon = true;
        if($request->olusturulma == "uygulama")
            $uygulama = true;
        // Musteri kartindaki "Randevular" sekmesi bu uc noktayi musteriid ile cagirir;
        // o durumda sadece ilgili musterinin randevulari donsun (aksi halde tum salon gelir).
        // Genel randevu listesi sayfasinda musteriid gonderilmez => '' => filtre uygulanmaz.
        $userid = is_numeric($request->musteriid) ? $request->musteriid : '';
        return self::randevu_liste_getir($request,$tarih[0],$tarih[1],$salon,$web,$uygulama,$request->durum,$request->salon_id,$userid);
    }
    public function liste_deneme(Request $request)
    {
       return self::randevu_liste_getir($request,'2025-02-01','2025-02-28',true,null,null,1,182,'');
    }
  public function randevu_liste_getir(Request $request, $tarih1, $tarih2, $salon, $web, $uygulama, $durum, $salon_id, $userid)
{
    // Start with a base query on the main table to reduce initial dataset
    $baseQuery = DB::table('randevular')
        ->where('randevular.salon_id', $salon_id);

    // "Saati geçen randevular görünmesin" ayari (sadece randevu.randevumcepte.com.tr girisleri):
    // alt siniri bugune cek (indeks) + bugunun saati gecmis randevularini ele.
    // Musteri kartindaki "Randevular" sekmesine ($userid dolu) de uygulanir — istege gore
    // orada da saati gecmis randevular gizlenir.
    if (self::gecmisRandevuGizlensinMi($salon_id)) {
        if ($tarih1 == '' || $tarih1 < date('Y-m-d')) {
            $tarih1 = date('Y-m-d');
        }
        $baseQuery->whereRaw(
            "CONCAT(randevular.tarih,' ',randevular.saat) >= ?",
            [date('Y-m-d H:i:s')]
        );
    }

    // Apply filters early to reduce the dataset before joins
    if ($tarih1 != '') {
        $baseQuery->where('randevular.tarih', '>=', $tarih1);
    }
    if ($tarih2 != '') {
        $baseQuery->where('randevular.tarih', '<=', $tarih2);
    }

    if ($salon != '' || $web != '' || $uygulama != '') {
        $baseQuery->where(function($q) use ($salon, $web, $uygulama) {
            if ($salon != '') $q->where('randevular.salon', $salon);
            if ($web != '') $q->orWhere('randevular.web', $web);
            if ($uygulama != '') $q->orWhere('randevular.uygulama', $uygulama);
        });
    }

    if ($durum != '') {
        $baseQuery->where('randevular.durum', $durum);
    }

    if ($userid != '') {
        $baseQuery->where('randevular.user_id', $userid);
    }

    // Get only the appointment IDs first (much smaller dataset)
    $randevuIds = $baseQuery->pluck('id');

    // If no appointments found, return empty collection early
    if ($randevuIds->isEmpty()) {
        return collect();
    }

    // Detay query: randevular'dan basla, randevu_hizmetler leftJoin (hizmetsiz randevular da gozuksun)
    $query = DB::table('randevular')
        ->leftJoin('randevu_hizmetler', 'randevu_hizmetler.randevu_id', '=', 'randevular.id')
        ->leftJoin('hizmetler', 'randevu_hizmetler.hizmet_id', '=', 'hizmetler.id')
        ->join('users', 'randevular.user_id', '=', 'users.id')
        ->leftJoin('salon_personelleri', 'randevu_hizmetler.personel_id', '=', 'salon_personelleri.id')
        ->leftJoin('isletmeyetkilileri as y1', 'randevular.olusturan_personel_id', '=', 'y1.id')
        ->leftJoin('cihazlar', 'randevu_hizmetler.cihaz_id', '=', 'cihazlar.id')
        ->leftJoin('odalar', 'randevu_hizmetler.oda_id', '=', 'odalar.id')
        ->whereIn('randevular.id', $randevuIds);

    // Staff-specific filter
    if (self::personelmi($request, 'randevu.tum_personel_gor')) {
        $personelId = Personeller::where('salon_id', $salon_id)
            ->where('yetkili_id', Auth::guard('isletmeyonetim')->user()->id)
            ->value('id');
            
        // yardimci_personel NULL tuzagi: normal (asil) randevu kalemlerinde bu kolon
        // hic set edilmez (yalniz yardimci personel satirlarinda true). Eski kosul
        // "!= true" (yani != 1) MySQL'de NULL satirlar icin de NULL (=false) dondugu
        // icin personelin KENDI asil randevulari da listeden dusuyor ve liste komple
        // bos gorunuyordu (takvim sorgusunda bu kosul yok, o yuzden takvim doluyordu).
        // NULL/0 = asil kalem, yalniz 1/true = yardimci -> COALESCE ile NULL'i 0 say.
        $query->whereRaw('COALESCE(randevu_hizmetler.yardimci_personel,0) != 1')
              ->where('randevu_hizmetler.personel_id', $personelId);
    }

    // Optimized select columns
    $selectColumns = [
        'users.name as musteri',
        DB::raw('CASE
            WHEN randevular.randevuya_geldi = 1 AND EXISTS(SELECT 1 FROM adisyon_paket_seanslar aps_x WHERE aps_x.randevu_id = randevular.id) THEN
                COALESCE((SELECT GROUP_CONCAT(DISTINCT sp.personel_adi SEPARATOR ", ")
                        FROM adisyon_paket_seanslar aps1
                        LEFT JOIN salon_personelleri sp ON sp.id = aps1.personel_id
                        WHERE aps1.randevu_id = randevular.id AND aps1.geldi = 1 AND sp.personel_adi IS NOT NULL),"")
            ELSE
                COALESCE((SELECT GROUP_CONCAT(DISTINCT sp2.personel_adi SEPARATOR ", ")
                        FROM randevu_hizmetler rh2
                        LEFT JOIN salon_personelleri sp2 ON sp2.id = rh2.personel_id
                        WHERE rh2.randevu_id = randevular.id AND sp2.personel_adi IS NOT NULL),"")
        END as personelcihazoda'),
        'odalar.oda_adi as odalar',
        'salon_personelleri.personel_adi as personel_adi',
        'cihazlar.cihaz_adi as cihaz_adi',
        DB::raw('DATE_FORMAT(randevular.saat, "%H:%i") as saat'),
        DB::raw('CONCAT(COALESCE(SUM(randevu_hizmetler.fiyat),0) ," ₺") as toplam'),
        DB::raw('CASE WHEN randevular.web=1 THEN "Web" WHEN randevular.uygulama=1 THEN "Uygulama" ELSE y1.name END as olusturan'),
        DB::raw('CONCAT("<span style=\"display:none\">",UNIX_TIMESTAMP(randevular.created_at),"</span>",DATE_FORMAT(randevular.created_at, "%d.%m.%Y %H:%i")) as olusturulma'),
        DB::raw('CASE
            WHEN randevular.randevuya_geldi = 1 AND EXISTS(SELECT 1 FROM adisyon_paket_seanslar aps_h WHERE aps_h.randevu_id = randevular.id) THEN
                (SELECT GROUP_CONCAT(DISTINCT h.hizmet_adi SEPARATOR ",")
                 FROM adisyon_paket_seanslar aps
                 LEFT JOIN hizmetler h ON h.id = aps.hizmet_id
                 WHERE aps.randevu_id = randevular.id AND aps.geldi = 1)
            ELSE GROUP_CONCAT(DISTINCT
                CASE WHEN randevu_hizmetler.dusum_miktari > 1
                     THEN CONCAT(hizmetler.hizmet_adi, " x", randevu_hizmetler.dusum_miktari)
                     ELSE hizmetler.hizmet_adi
                END SEPARATOR ", ")
        END as hizmetler'),
        DB::raw('CONCAT("<span style=\"display:none\">",UNIX_TIMESTAMP(randevular.tarih),UNIX_TIMESTAMP(randevular.saat),"</span>",DATE_FORMAT(randevular.tarih, "%d.%m.%Y")) as tarih'),
        DB::raw('CASE WHEN randevular.randevuya_geldi=1 THEN "Geldi" ELSE "Gelmedi" END as geldimi'),
    ];

    // Add conditional selects based on user type
    if (self::personelmi($request, 'randevu.tum_personel_gor')) {
        $selectColumns[] = DB::raw('COALESCE(CONCAT(LEFT(REGEXP_REPLACE(users.cep_telefon,"[0-9]","X"),6), RIGHT(users.cep_telefon,4)),"") as telefon');
    } else {
        $selectColumns[] = 'users.cep_telefon as telefon';
        $selectColumns[] = 'randevu_hizmetler.yardimci_personel';
    }

    // Status and action buttons HTML - simplified
    $statusHtml = <<<SQL
    CASE 
        WHEN randevular.durum=1 AND randevular.randevuya_geldi=true THEN '<button class="btn btn-success btn-block" style="line-height:5px">Geldi</button>' 
        WHEN randevular.durum=1 AND randevular.randevuya_geldi=0 THEN '<button class="btn btn-danger btn-block" style="line-height:5px">Gelmedi</button>' 
        WHEN randevular.durum=1 AND randevular.randevuya_geldi IS null THEN '<button class="btn btn-primary btn-block" style="line-height:5px">Onaylı</button>' 
        WHEN randevular.durum=2 THEN '<button class="btn btn-dark btn-block" style="line-height:5px">İptal</button>' 
        WHEN randevular.durum=3 THEN '<button class="btn btn-dark btn-block">Müşteri Tarafından İptal</button>' 
        WHEN randevular.durum=0 THEN '<button class="btn btn-warning btn-block" style="line-height:5px">Beklemede</button>' 
    END AS durum
    SQL;
    $selectColumns[] = DB::raw($statusHtml);

    $actionsHtml = <<<SQL
    CASE 
        WHEN randevular.durum = 0 THEN CONCAT('<div class="dropdown">
            <a class="btn btn-link font-24 p-0 line-height-1 no-arrow dropdown-toggle" href="#" role="button" data-toggle="dropdown"><i class="dw dw-more"></i>
            </a>
            <div class="dropdown-menu dropdown-menu-right dropdown-menu-icon-list">
                <a class="dropdown-item" data-value="',randevular.id,'" name="randevu_duzenle" data-index-number="',COALESCE(randevu_hizmetler.hizmet_id, 0),'" href="#"> <i class="fa fa-edit"></i> Düzenle</a>
                <a class="dropdown-item randevuonayla" data-value="',randevular.id,'" href="#"> <i class="fa fa-check"></i> Onayla</a>
                <a class="dropdown-item randevuiptalet" data-value="',randevular.id,'" href="#"> <i class="fa fa-times"></i> İptal Et</a>
            </div></div>')
        WHEN randevular.durum = 1 AND randevular.randevuya_geldi IS NOT TRUE THEN
            CONCAT('<div class="dropdown">
            <a class="btn btn-link font-24 p-0 line-height-1 no-arrow dropdown-toggle" href="#" role="button" data-toggle="dropdown"><i class="dw dw-more"></i>
            </a>
            <div class="dropdown-menu dropdown-menu-right dropdown-menu-icon-list">
                <a class="dropdown-item" data-value="',randevular.id,'" name="randevu_duzenle" data-index-number="',COALESCE(randevu_hizmetler.hizmet_id, 0),'" href="#"> <i class="fa fa-edit"></i> Düzenle</a>
                <a class="dropdown-item randevuiptalet" data-value="',randevular.id,'" href="#"> <i class="fa fa-times"></i> İptal Et</a>
            </div></div>') 
        WHEN randevular.durum = 1 AND randevular.randevuya_geldi IS TRUE THEN
            CONCAT('<div class="dropdown">
            <a class="btn btn-link font-24 p-0 line-height-1 no-arrow dropdown-toggle" href="#" role="button" data-toggle="dropdown"><i class="dw dw-more"></i>
            </a>
            <div class="dropdown-menu dropdown-menu-right dropdown-menu-icon-list">
                <a class="dropdown-item" data-value="',randevular.id,'" name="randevu_sonrasi_islem_notu" href="#"> <i class="fa fa-plus"></i> İşlem Not Ekle</a>
            </div></div>')
        WHEN randevular.durum IN (2,3) THEN CONCAT('<div class="dropdown">
            <a class="btn btn-link font-24 p-0 line-height-1 no-arrow dropdown-toggle" href="#" role="button" data-toggle="dropdown"><i class="dw dw-more"></i>
            </a>
            <div class="dropdown-menu dropdown-menu-right dropdown-menu-icon-list">
                <a class="dropdown-item" data-value="',randevular.id,'" name="randevu_duzenle" data-index-number="',COALESCE(randevu_hizmetler.hizmet_id, 0),'" href="#"> <i class="fa fa-edit"></i> Düzenle</a>
            </div></div>')
    END AS islemler
    SQL;
    $selectColumns[] = DB::raw($actionsHtml);

    // Execute the optimized query (groupBy randevular.id - hizmetsiz randevular icin de calisir)
    return $query->select($selectColumns)
        ->groupBy('randevular.id')
        ->orderBy('randevular.id', 'desc')
        ->get();
}
    public function senetler(Request $request){
         $isletmeler = '';
        $isletme='';
        if(Auth::guard('satisortakligi')->check())
        {
            $isletmeler = [15];
            $isletme = Salonlar::where('id',15)->first();
        }
        else{
            $isletmeler = Auth::guard('isletmeyonetim')->user()->yetkili_olunan_isletmeler->where('aktif',1)->pluck('salon_id')->toArray();
            $isletme= Salonlar::where('id',self::mevcutsube($request))->first();
        }


        if(!in_array(self::mevcutsube($request),$isletmeler ) || $_SERVER["HTTP_HOST"]=="randevu.randevumcepte.com.tr")
        {
            return view('isletmeadmin.yetkisizerisim');
            exit(0);
        }
        if(str_contains(self::lisans_sure_kontrol($request),'-'))
        {
            return view('isletmeadmin.lisanssurebitti',['isletme'=>$isletme]);
            exit(0);
        }
        // Yetki: bu sayfanin gerektirdigi yetki yoksa 403
        $_authUser = Auth::guard('isletmeyonetim')->user();
        if ($_authUser && !(
            \App\Services\PersonelYetkiServisi::yetkiliYetkiVar($_authUser->id, self::mevcutsube($request), 'satis.senet_olustur')
            || \App\Services\PersonelYetkiServisi::yetkiliYetkiVar($_authUser->id, self::mevcutsube($request), 'finans.alacak_yonet')
        )) {
            return view('isletmeadmin.yetkisizerisim');
            exit(0);
        }
        if(!Auth::guard('satisortakligi')->check()){
             if(self::personelmi($request, 'finans.alacak_yonet'))
            {
                    return redirect()->route('isletmeadmin.randevular');
                    exit(0);
            }
        }
       
        if(count($isletmeler)>1 && !isset($_GET['sube']))
        {
            return view('isletmeadmin.isletmesec',['isletmeler'=>$isletmeler,'isletme'=>$isletme]);
            exit(0);
        }
        $isletme = Salonlar::where('id',self::mevcutsube($request))->first();
        $senetler = self::senetleri_getir($request,'','');
        $senetler_acik = self::senetleri_getir($request,0,'');
        $senetler_kapali = self::senetleri_getir($request,1,'');
        $senetler_odenmemis = self::senetleri_getir($request,2,'');
         return view('isletmeadmin.senetler',['pageindex'=>17,'sayfa_baslik'=>'Senet Takibi','bildirimler'=>self::bildirimgetir($request),'paketler'=> self::paket_liste_getir('',true,$request),'isletme'=>$isletme,'senetler'=>$senetler,'senetler_acik'=>$senetler_acik,'senetler_kapali'=>$senetler_kapali,'senetler_odenmemis'=>$senetler_odenmemis, 'kalan_uyelik_suresi' => self::lisans_sure_kontrol($request),'urun_drop'=>self::urundropliste($request),'yetkiliolunanisletmeler'=>$isletmeler]);
    }
    public function senetfiltre(Request $request)
    {
        return self::senetleri_getir($request,$request->sorgu,'');
    }
    public function senetleri_getir(Request $request,$sorgu,$musteriid)
    {
        if($sorgu===''){
            return DB::table('senetler')->join('senet_vadeleri','senet_vadeleri.senet_id','=','senetler.id')->join('users','senetler.user_id','=','users.id')->select(
            DB::raw('CASE WHEN (select count(*) from senet_vadeleri where senet_vadeleri.odendi=false) > 0 THEN "Açık" ELSE "Kapalı" END as durum'),
            'users.name as ad_soyad',
            DB::raw('CONCAT ("<button class=\"btn btn-primary\">", COUNT(senet_vadeleri.id),"</button>" ) as vade_sayisi'),
            DB::raw('CASE WHEN (SELECT COUNT(*) FROM senet_vadeleri
                                WHERE senet_vadeleri.odendi = true AND senet_vadeleri.senet_id = senetler.id) > 0 THEN CONCAT("<button class=\"btn btn-success\">",(SELECT COUNT(*) FROM senet_vadeleri
                                WHERE senet_vadeleri.odendi = true AND senet_vadeleri.senet_id = senetler.id),"</button>") END as odenmis'),
            DB::raw('CASE WHEN (SELECT COUNT(*) FROM senet_vadeleri
                                WHERE senet_vadeleri.odendi = false  AND senet_vadeleri.senet_id = senetler.id) > 0 THEN CONCAT("<button class=\"btn btn-danger\">", (SELECT COUNT(*) FROM senet_vadeleri
                                WHERE senet_vadeleri.odendi = false  AND senet_vadeleri.senet_id = senetler.id),"</button>" ) END as odenmemis'),
           DB::raw('CASE WHEN (SELECT senet_vadeleri.vade_tarih FROM senet_vadeleri WHERE senet_vadeleri.odendi=false AND senet_vadeleri.senet_id = senetler.id
                                order by senet_vadeleri.id asc  LIMIT 1) IS NULL THEN "<button class=\"btn btn-warning\">Kapalı Senet</button>" ELSE CONCAT("<p style=\"display:none\">",DATE_FORMAT(
                        (SELECT senet_vadeleri.vade_tarih FROM senet_vadeleri WHERE senet_vadeleri.odendi=false AND senet_vadeleri.senet_id = senetler.id
                                order by senet_vadeleri.id asc  LIMIT 1),"%Y%m%d"
                    ),"</p><span class=\"", CASE WHEN (SELECT senet_vadeleri.vade_tarih FROM senet_vadeleri WHERE senet_vadeleri.odendi=false AND senet_vadeleri.senet_id = senetler.id
                                order by senet_vadeleri.id asc  LIMIT 1) < NOW() THEN "btn btn-danger" ELSE "" END ," \">",DATE_FORMAT(
