    public function yeniisletmeekle(Request $request)
    {
        $mevcutisletme = Salonlar::where('id',self::mevcutsube($request))->first();
        $isletme = new Salonlar();
        $isletme->salon_adi = $request->firma_adi;
        $isletme->telefon_1 = $request->telefon;
        $isletme->sms_apikey = $mevcutisletme->sms_apikey;
        $isletme->sms_baslik = $mevcutisletme->sms_baslik;
        $isletme->il_id = $request->firma_il;
        $isletme->ilce_id = $request->firma_ilce;
        $isletme->adres = $request->firma_adresi;
        $isletme->aktif = false;
        $isletme->save();
        if(isset($request->yonetici_ekle))
        {
            $yetkili = '';
            if(IsletmeYetkilileri::where('gsm1',$request->telefon)->count()>0)
                $yetkili = IsletmeYetkilileri::where('gsm1',$request->telefon)->first();
            else
                $yetkili = new IsletmeYetkilileri();
            $yetkili->name = $request->yetkili_adi;
            $yetkili->gsm1 = $request->telefon;
            $random = str_shuffle('abcdefghjklmnopqrstuvwxyzABCDEFGHJKLMNOPQRSTUVWXYZ1234567890');
            $olusturulansifre = substr($random, 0, 6);
            $yetkili->password = Hash::make($olusturulansifre);
            $yetkili->save();
            DB::insert('insert into model_has_roles (role_id, model_type,model_id,salon_id) values (3, "App\\\IsletmeYetkilileri",'.$yetkili->id.','.$isletme->id.')');
            $personel = new Personeller();
            $personel->personel_adi = $request->yetkili_adi;
            $personel->cep_telefon = $request->telefon;
            $personel->salon_id = $isletme->id;
            $personel->renk = 2;
            $personel->takvimde_gorunsun = true;
            $personel->takvim_sirasi = 2;
            $personel->aktif = true;
            $personel->role_id = 3;
            $personel->yetkili_id = $yetkili->id;
            $personel->save();
            self::sms_gonder_bildirimli($request,array(array("to"=>$yetkili->gsm1,"message"=>"RandevumCepte hesabınız oluşturulmuş olup ".$olusturulansifre." şifrenizle giriş yapabilirsiniz.")),false,1,false);
        }
        $supervisorler = Personeller::join('model_has_roles','salon_personelleri.yetkili_id','=','model_has_roles.model_id')->where(function($q) use($request){$q->where('model_has_roles.role_id',2);$q->orWhere('salon_personelleri.role_id',2);})->where('salon_personelleri.salon_id',$mevcutisletme->id)->get();
        $renkindex = 3;
        foreach($supervisorler as $supervisor)
        {
            DB::insert('insert into model_has_roles (role_id, model_type,model_id,salon_id) values (3, "App\\\IsletmeYetkilileri",'.$supervisor->id.','.$isletme->id.')');
            $personel_s = new Personeller();
            $personel_s->personel_adi = $supervisor->personel_adi;
            $personel_s->cep_telefon = $supervisor->cep_telefon;
            $personel_s->role_id = 2;
            $personel_s->renk = $renkindex;
            $personel_s->takvimde_gorunsun = true;
            $personel_s->takvim_sirasi = $renkindex;
            $personel_s->aktif = true;
            $personel_s->salon_id = $isletme->id;
            $personel_s->yetkili_id = $supervisor->yetkili_id;
            $personel_s->save();
            $renkindex++;
        }
        DB::insert('insert into model_has_roles (role_id, model_type,model_id,salon_id) values (1, "App\\\IsletmeYetkilileri",'.Auth::guard('isletmeyonetim')->user()->id.','.$isletme->id.')');
        $_personel = new Personeller();
        $_personel->personel_adi = Auth::guard('isletmeyonetim')->user()->name;
        $_personel->cep_telefon = Auth::guard('isletmeyonetim')->user()->gsm1;
        $_personel->salon_id = $isletme->id;
        $_personel->renk = 1;
        $_personel->takvimde_gorunsun = true;
        $_personel->takvim_sirasi = 1;
        $_personel->aktif = true;
        $_personel->role_id = 1;
        $_personel->yetkili_id = Auth::guard('isletmeyonetim')->user()->id;
        $_personel->save();
        return array(
            'mesaj' => 'Şube bilgileri başarıyla kaydedildi. Yönlendiriliyorsunuz...',
            'sube' => $isletme->id
        );
    }
    public function odeme_sayfasi(Request $request)
    {
       $isletmeler = '';
        $isletme='';
        if(Auth::guard('satisortakligi')->check())
        {
            $isletmeler = [15];
            $isletme = Salonlar::where('id',15)->first();
        }
        else{
            $isletmeler = Auth::guard('isletmeyonetim')->user()->yetkili_olunan_isletmeler->where('aktif',1)->pluck('salon_id')->toArray();
            $isletme= Salonlar::where('id',self::mevcutsube($request))->first();
        }
        
        
        if(!in_array(self::mevcutsube($request),$isletmeler ))
        {
            return view('isletmeadmin.yetkisizerisim');
            exit(0);
        }
        if(str_contains(self::lisans_sure_kontrol($request),'-'))
        {
            return view('isletmeadmin.lisanssurebitti',['isletme'=>$isletme]);
            exit(0);
        }
        if(!Auth::guard('satisortakligi')->check()){
             if(self::personelmi($request))
            {
                    return redirect()->route('isletmeadmin.randevular');
                    exit(0);
            }
        }
       
        if(count($isletmeler)>1 && !isset($_GET['sube']))
        {
            return view('isletmeadmin.isletmesec',['isletmeler'=>$isletmeler,'isletme'=>$isletme]);
            exit(0);
        }
        $urunler = self::urun_liste_getir($request,"");
        $hizmetler = self::hizmet_liste_getir($request,"","");
        $paketler = self::paket_liste_getir("",false,$request);
        $bildirimler = self::bildirimgetir($request);
        $musteri_bilgileri = Auth::user();
        $uyelik = Uyelik::where('id',$request->uyelikturu)->first();
        return view('isletmeadmin.odeme',['sayfa_baslik'=>'Ödeme','urunler'=>$urunler,'hizmetler'=>$hizmetler,'paketler'=>$paketler,'pageindex'=>70,'musteri_bilgileri'=>$musteri_bilgileri,'isletme'=>$isletme,'bildirimler'=>$bildirimler, 'kalan_uyelik_suresi' => self::lisans_sure_kontrol($request),'portfoy_drop'=>self::musteriportfoydropliste($request),'urun_drop'=>self::urundropliste($request),'hizmet_drop'=>self::hizmetdropliste($request),
            'request'=>$request,
            'uyelik'=>$uyelik,
            'personel_drop'=>self::personeldropliste($request,array()),'yetkiliolunanisletmeler'=>$isletmeler]);
    }
    /** gecmisRandevuGizlensinMi() icin istek basina salon_id => bool onbellegi */
    protected static $_gecmisGizleCache = [];

    /**
     * "Saati geçen randevular görünmesin" (salonlar.gecmis_randevulari_gizle) akisi
     * bu istek icin gecerli mi?
     *
     * Ayar salon bazlidir; AMA akis SADECE randevu.randevumcepte.com.tr uzerinden
     * yapilan web panel girislerinde uygulanir (domain flag). Diger hostlarda
     * (app./demoapp./mobil API) randevular her zamanki gibi tam listelenir.
     */
    public static function gecmisRandevuGizlensinMi($salon_id)
    {
        $host = strtolower($_SERVER['HTTP_HOST'] ?? ($_SERVER['SERVER_NAME'] ?? ''));
        if (strpos($host, ':') !== false) $host = explode(':', $host)[0];
        if ($host !== 'randevu.randevumcepte.com.tr') return false;

        $salon_id = (int) $salon_id;
        if ($salon_id <= 0) return false;
        if (array_key_exists($salon_id, self::$_gecmisGizleCache)) {
            return self::$_gecmisGizleCache[$salon_id];
        }
        return self::$_gecmisGizleCache[$salon_id] =
            (bool) Salonlar::where('id', $salon_id)->value('gecmis_randevulari_gizle');
    }

    public function randevuayarguncelle(Request $request)
    {
        if($r = self::yetkiYoksa403($request, 'randevu.online_ayar')) return $r;
        $isletme = Salonlar::where('id',$request->salon_id)->first();
        $isletme->randevu_saat_araligi=$request->randevu_saat_araligi;
        $isletme->randevu_takvim_turu = $request->randevu_takvim_turu;
        $isletme->musteri_online_randevu_aktif = $request->has('musteri_online_randevu_aktif') ? 1 : 0;
        $isletme->gecmis_randevulari_gizle = $request->has('gecmis_randevulari_gizle') ? 1 : 0;
        $isletme->save();
        // Ayar degistiginde host bazli cache'i dusur (ayni istek icinde tekrar okunursa taze olsun)
        self::$_gecmisGizleCache = [];
        return 'Randevu ayarları başarıyla kaydedildi';
    }

    /**
     * Online randevu AÇIK saatleri (salon sahibi kürasyonu):
     *   - online_saat_kisitlama_aktif : ana anahtar
     *   - online_gunluk_slot_limiti   : günde en fazla N online slot (0/bos = limitsiz)
     *   - haftalık pencereler          : pencere_gun[]/pencere_bas[]/pencere_bit[] paralel diziler
     *   - tarihe özel istisnalar       : istisna_tarih[]/istisna_tip[]/istisna_bas[]/istisna_bit[]
     * Kayıt "tümünü sil + yeniden yaz" mantığıyla yapılır.
     */
    public function onlineRandevuSaatGuncelle(Request $request)
    {
        if($r = self::yetkiYoksa403($request, 'randevu.online_ayar')) return $r;

        if (!\Illuminate\Support\Facades\Schema::hasTable('salon_online_randevu_saatleri')) {
            return response('Veritabanı güncellemesi uygulanmamış (php artisan migrate).', 422);
        }

        $salonId = (int) $request->salon_id;
        $isletme = Salonlar::where('id', $salonId)->first();
        if (!$isletme) return response('Salon bulunamadı', 422);

        $hhmm = function ($v) {
            $v = trim((string) $v);
            return preg_match('/^([01]\d|2[0-3]):[0-5]\d$/', $v) ? $v : null;
        };

        $isletme->online_saat_kisitlama_aktif = $request->has('online_saat_kisitlama_aktif') ? 1 : 0;
        $limit = (int) $request->online_gunluk_slot_limiti;
        $isletme->online_gunluk_slot_limiti = $limit > 0 ? $limit : null;
        $isletme->save();

        // ── Haftalık pencereler ────────────────────────────────────────────────
        \App\SalonOnlineRandevuSaatleri::where('salon_id', $salonId)->delete();
        $gunler = (array) $request->input('pencere_gun', []);
        $baslar = (array) $request->input('pencere_bas', []);
        $bitler = (array) $request->input('pencere_bit', []);
        foreach ($gunler as $i => $g) {
            $g = (int) $g;
            $bas = $hhmm($baslar[$i] ?? '');
            $bit = $hhmm($bitler[$i] ?? '');
            if ($g < 1 || $g > 7 || !$bas || !$bit) continue;
            if (strtotime($bit) <= strtotime($bas)) continue; // bitiş başlangıçtan sonra olmalı
            \App\SalonOnlineRandevuSaatleri::create([
                'salon_id' => $salonId,
                'haftanin_gunu' => $g,
                'baslangic_saati' => $bas,
                'bitis_saati' => $bit,
            ]);
        }

        // ── Tarihe özel istisnalar ─────────────────────────────────────────────
        \App\SalonOnlineRandevuIstisnasi::where('salon_id', $salonId)->delete();
        $tarihler = (array) $request->input('istisna_tarih', []);
        $tipler = (array) $request->input('istisna_tip', []);
        $isBas = (array) $request->input('istisna_bas', []);
        $isBit = (array) $request->input('istisna_bit', []);
        foreach ($tarihler as $i => $t) {
            $t = trim((string) $t);
            if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $t)) continue;
            $tip = (($tipler[$i] ?? 'kapali') === 'ozel') ? 'ozel' : 'kapali';
            $bas = null; $bit = null;
            if ($tip === 'ozel') {
                $bas = $hhmm($isBas[$i] ?? '');
                $bit = $hhmm($isBit[$i] ?? '');
                if (!$bas || !$bit || strtotime($bit) <= strtotime($bas)) continue; // geçersiz özel aralık atlanır
            }
            \App\SalonOnlineRandevuIstisnasi::create([
                'salon_id' => $salonId,
                'tarih' => $t,
                'tip' => $tip,
                'baslangic_saati' => $bas,
                'bitis_saati' => $bit,
            ]);
        }

        SalonAudit::log($salonId, 'online_saat_guncelle', 'salon', $salonId,
            'Online randevu saatleri güncellendi',
            $isletme->online_saat_kisitlama_aktif ? 'Kısıtlama aktif' : 'Kısıtlama kapalı',
            ['limit' => $isletme->online_gunluk_slot_limiti]);

        return 'Online randevu saatleri başarıyla kaydedildi';
    }
   public function etkinlikekleduzenle(Request $request)
    {
        $etkinlik = "";
        $_yeniEtkinlik = false;
        if(isset($request->etkinlik_id))
            $etkinlik = Etkinlikler::where('id',$request->etkinlik_id)->first();
        else {
            $etkinlik = new Etkinlikler();
            $_yeniEtkinlik = true;
        }
        $etkinlik->etkinlik_adi = $request->etkinlik_adi;
        $etkinlik->tarih_saat = $request->etkinlik_tarihi ." ".$request->etkinlik_saati;
        $etkinlik->fiyat = $request->etkinlik_fiyati;
        $etkinlik->salon_id = self::mevcutsube($request);
        $etkinlik->aktifmi=1;
        $etkinlik->mesaj=$request->etkinlik_sms;
        $etkinlik->save();
        // Audit
        SalonAudit::log($etkinlik->salon_id, $_yeniEtkinlik ? 'etkinlik_ekle' : 'etkinlik_guncelle', 'etkinlik', $etkinlik->id,
            $etkinlik->etkinlik_adi.' — '.$etkinlik->tarih_saat,
            $_yeniEtkinlik ? 'Yeni etkinlik oluşturuldu' : 'Etkinlik güncellendi',
            ['fiyat'=>$etkinlik->fiyat]);
        $katilimcilar = EtkinlikKatilimcilari::where('id',$etkinlik->id)->delete();
         $gsm = array();
        $mesajlar=array();
        if (isset($request->etkinlik_katilimci_musteriler)) {
            foreach($request->etkinlik_katilimci_musteriler as $key=>$katilimci)
            {
                $yenikatilimci = new EtkinlikKatilimcilari();
                $yenikatilimci->etkinlik_id = $etkinlik->id;
                $yenikatilimci->user_id = $katilimci;
                $yenikatilimci->save();
                $toplumusteri = User::where('id',$katilimci)->first();
                $katilim_link = '';
                if(SalonSMSAyarlari::where('ayar_id',10)->where('salon_id',$etkinlik->salon_id)->value('musteri')==1 )
                    $katilim_link = ' Katılım için : https://'.$_SERVER['HTTP_HOST'].'/etkinlikkatilim/'.$etkinlik->id.'/'.$toplumusteri->id;
                if(MusteriPortfoy::where('user_id',$toplumusteri->id)->where('salon_id',$etkinlik->salon_id)->value('kara_liste')!=1)
                    array_push($mesajlar, array("to"=>$toplumusteri->cep_telefon,"message"=> $request->etkinlik_sms.$katilim_link));
            }
        }
        if (isset($request->etkinlik_grup_katilimci_musteriler)) {
            foreach($request->etkinlik_grup_katilimci_musteriler as $grupkatilimci)
            {
                $grupkatilimcilar=GrupSmsKatilimcilari::where('grup_id',$grupkatilimci)->get();
                foreach ($grupkatilimcilar as $grup) {
                    $yenikatilimci = new EtkinlikKatilimcilari();
                    $yenikatilimci->etkinlik_id = $etkinlik->id;
                    $yenikatilimci->user_id = $grup->user_id;
                    $yenikatilimci->save();
                    $toplumusteri = User::where('id',$grup->user_id)->first();
                    $katilim_link = '';
                    if (SalonSMSAyarlari::where('ayar_id',10)->where('salon_id',$etkinlik->salon_id)->value('musteri')==1)
                        $katilim_link = ' Katılım için : https://'.$_SERVER['HTTP_HOST'].'/etkinlikkatilim/'.$etkinlik->id.'/'.$toplumusteri->id;
                    if(MusteriPortfoy::where('user_id',$toplumusteri->id)->where('salon_id',$etkinlik->salon_id)->value('kara_liste')!=1)
                        array_push($mesajlar, array("to"=>$toplumusteri->cep_telefon,"message"=> $request->etkinlik_sms.$katilim_link));
                }
            }
       }
        $gonder=self::sms_gonder_bildirimli($request,$mesajlar,true,6,false);
        return array(
          "mesaj" => "Etklinlik başarıyla kaydedildi",
           "gonder"=>$gonder,
           "katilimci"=>self::etkinlikyukle($request)
        );
    }
   public function etkinlikbeklenensms(Request $request){
      $etkinlikbeklenen= Etkinlikler::where('id',$request->etkinlikid)->first();
      $mesajlar=array();
       foreach ($etkinlikbeklenen->katilimcilar as  $katilimci) {
