    public function sistemeyenihizmetekle(Request $request){
        if($r = self::yetkiYoksa403($request, 'hizmet.tanim_olustur')) return $r;
        $yenihizmet = new Hizmetler();
        $yenihizmet->hizmet_kategori_id = $request->hizmet_kategorisi;
        $yenihizmet->hizmet_adi = $request->hizmet_adi;
        $yenihizmet->ozel_hizmet = true;
        $yenihizmet->salon_id = $request->sube;
        $yenihizmet->cinsiyet = $request->cinsiyet;
        $yenihizmet->sure_dk = $request->hizmet_sure;
        $yenihizmet->save();
        $sunulanhizmet = new SalonHizmetler();
        $sunulanhizmet->hizmet_id = $yenihizmet->id;
        $sunulanhizmet->hizmet_kategori_id = $request->hizmet_kategorisi;
        $sunulanhizmet->bolum = $request->cinsiyet;
        $sunulanhizmet->baslangic_fiyat = self::parseFiyat($request->hizmet_fiyati);
        $sunulanhizmet->aktif = true;
        $sunulanhizmet->sure_dk = $request->hizmet_sure;
        $sunulanhizmet->salon_id = $request->sube;
        $sunulanhizmet->save();
        if(SalonHizmetKategoriRenkleri::where('hizmet_kategori_id',$request->hizmet_kategorisi)->where('salon_id',$request->sube)->count() == 0)
        {
                $kategori_son_renk = SalonHizmetKategoriRenkleri::where('salon_id',$request->sube)->orderBy('renk_id','desc')->first();
                $yeni_kategori_renk = '';
                if($kategori_son_renk===null)
                    $yeni_kategori_renk = 1;
                else
                {
                    if($kategori_son_renk->renk_id == 10)
                        $yeni_kategori_renk = 1;
                    else
                        $yeni_kategori_renk = $kategori_son_renk->renk_id + 1;
                }
                $yeni_renk = new SalonHizmetKategoriRenkleri();
                $yeni_renk->salon_id = $request->sube;
                $yeni_renk->renk_id = $yeni_kategori_renk;
                $yeni_renk->hizmet_kategori_id = $request->hizmet_kategorisi;
                $yeni_renk->save();
        }
        if(is_array($request->personeller))
        {
            foreach($request->personeller as $personel){
                if(str_contains($personel,'cihaz')){
                    $str = explode('-',$personel);
                    $personelhizmet = new CihazHizmetler();
                    $personelhizmet->cihaz_id = $str[1];
                    $personelhizmet->hizmet_id = $yenihizmet->id;
                    $personelhizmet->save();
                }
                else
                {
                    $personelhizmet = new PersonelHizmetler();
                    $personelhizmet->personel_id = $personel;
                    $personelhizmet->hizmet_id = $yenihizmet->id;
                    $personelhizmet->save();
                }
            }
        }
        $secilmeyenhizmetler = self::secilmeyen_hizmet_liste_getir($request);
        return self::hizmet_liste_getir($request,"Hizmet başarıyla eklendi",$secilmeyenhizmetler);
    }
    public function secilmeyen_hizmet_liste_getir(Request $request)
    {
        $liste = '';
        foreach(Hizmet_Kategorisi::all() as $hizmet_kategorisi){
            if(Hizmetler::whereNotIn('id',\App\SalonHizmetler::where('salon_id',self::mevcutsube($request))->where('aktif',true)->pluck('hizmet_id'))->where('hizmet_kategori_id',$hizmet_kategorisi->id)->where('id','!=',463)->count()>0){
                $liste.='<tr style="background: #e2e2e2;">
                            <td> </td>
                                          <td>
                                             <strong>'.$hizmet_kategorisi->hizmet_kategorisi_adi.'</strong>
                                          </td></tr>';
                foreach(Hizmetler::whereNotIn('id',\App\SalonHizmetler::where('salon_id',self::mevcutsube($request))->where('aktif',true)->pluck('hizmet_id'))->where('hizmet_kategori_id',$hizmet_kategorisi->id)->where('id','!=',463)->get() as $secilmeyenhizmetler)
                    $liste.='<tr>
                                          <td><input type="checkbox" name="salon_hizmetleri[]" value="'.$secilmeyenhizmetler->id.'"></td>
                                          <td>'.$secilmeyenhizmetler->hizmet_adi.'</td>
                    </tr>';
            }
        }
        return $liste;
    }
    /**
     * PERF lazy-load: Takvimde bir randevuya tiklayinca/hover'da o randevunun
     * detay/hover/buton HTML'ini tek seferde dondurur. Toplu randevuyukle artik
     * bu agir partial'lari render etmiyor (randevu basina 3 Blade render x poll).
     */
    public function randevuEventDetay(Request $request)
    {
        $rhId = (int) $request->id;
        if (!$rhId) return response()->json(['hata' => 'id yok'], 400);

        $rh = RandevuHizmetler::with([
            'hizmetler',
            'personeller.trenk',
            'cihaz',
            'oda',
            'randevu.users',
            'randevu.olusturan_personel',
            'randevu.ongorusme.paket',
            'randevu.ongorusme.hizmet',
            'randevu.ongorusme.urun',
            'randevu.ongorusme.personel',
            'randevu.hizmetler',
        ])->find($rhId);

        if (!$rh || !$rh->randevu) return response()->json(['hata' => 'bulunamadi'], 404);

        // Guvenlik: randevu, kullanicinin mevcut salonuna ait olmali
        $isletmeId = self::mevcutsube($request);
        if (!Auth::guard('satisortakligi')->check() && (int) $rh->randevu->salon_id !== (int) $isletmeId) {
            return response()->json(['hata' => 'yetkisiz'], 403);
        }

        $rol = Personeller::where('salon_id', $isletmeId)
            ->where('yetkili_id', Auth::guard('isletmeyonetim')->user()->id ?? 0)
            ->value('role_id');

        // paketAdi + hasPaketTahsilat — tek randevu icin (toplu yuklemedeki ayni mantik)
        $seanslar = AdisyonPaketSeanslar::where('randevu_id', $rh->randevu_id)->get();
        $paketAdi = '';
        $apId = $seanslar->pluck('adisyon_paket_id')->filter()->first();
        if ($apId) {
            $ap = AdisyonPaketler::with('paket')->find($apId);
            if ($ap && $ap->paket) $paketAdi = $ap->paket->paket_adi;
        }
        $hasPaketTahsilat = $seanslar->isNotEmpty()
            || AdisyonHizmetler::where('randevu_id', $rh->randevu_id)->exists();

        // Bu randevuya ait adisyonu cozumle (POPUP YERINE ilgili adisyona yonlendirmek icin).
        // Oncelik sirasi:
        //   (1) Dogrudan bu randevu_id'ye baglanmis adisyon kalemi -> en guvenilir (randevu uzerinden satis).
        //   (2) Ayni musteri + ayni hizmet + randevu tarihli satis -> randevu disinda (manuel) acilmis,
        //       randevu_id tasimadigi halde bu randevuya ait olan ayni-gun satisi (or. 565377/529004).
        //   (3) Seans -> SADECE gercek paket (adisyon_paket_id) -> adisyon -> son care (paket tuketimi randevulari).
        //       NOT: seansin adisyon_hizmet_id dali BILEREK kullanilmiyor. O dal gozlemlenen tum vakalarda
        //       (1757538, 1761922) ESKI/alakasiz bir adisyona goturdu. Boyle randevular adisyonId=null kalip
        //       normal tahsil_et akisina duser (gerekirse yeni adisyon olusturur), eski adisyona yanlis gitmez.
        $adisyonId = AdisyonHizmetler::where('randevu_id', $rh->randevu_id)->value('adisyon_id');

        if (!$adisyonId && $rh->randevu) {
            $randevuTarih = date('Y-m-d', strtotime($rh->randevu->tarih));
            $adisyonId = DB::table('adisyon_hizmetler as ah')
                ->join('adisyonlar as a', 'ah.adisyon_id', '=', 'a.id')
                ->where('a.user_id', $rh->randevu->user_id)
                ->where('a.salon_id', $rh->randevu->salon_id)
                ->where('ah.hizmet_id', $rh->hizmet_id)
                ->whereDate('ah.islem_tarihi', $randevuTarih)
                ->orderBy('ah.id', 'desc')
                ->value('ah.adisyon_id');
        }

        if (!$adisyonId) {
            $seansBilgi = $seanslar->firstWhere('hizmet_id', $rh->hizmet_id) ?: $seanslar->first();
            if ($seansBilgi && $seansBilgi->adisyon_paket_id) {
                $adisyonId = AdisyonPaketler::where('id', $seansBilgi->adisyon_paket_id)->value('adisyon_id');
            }
        }

        return response()->json([
            'eventbuttons' => view('partials.randevuDetayiButonlar', ['randevu' => $rh, 'hasPaketTahsilat' => $hasPaketTahsilat, 'adisyonId' => $adisyonId])->render(),
            'description'  => view('partials.randevuDetayi', ['randevu' => $rh, 'rol' => $rol, 'paketAdi' => $paketAdi])->render(),
            'hoverHtml'    => view('partials.randevuHoverDetayi', ['randevu' => $rh, 'rol' => $rol, 'paketAdi' => $paketAdi])->render(),
        ]);
    }

    public function takvim_degistir(Request $request)
    {
        // Onceki kod 'monday this week' / 'Y-m-01' icin bugunun tarihini baz
        // aliyordu; takvim ileri/geri sayfalandiginda bile bugunun haftasini
        // donuyordu — sonraki haftalardaki randevular bos gorunuyordu. Artik
        // frontend'in gonderdigi takvimtarih'i baz aliyoruz.
        $tarih = trim(str_replace('T',' ',(string)$request->takvimtarih));
        try {
            $tarihObj = new \DateTime($tarih !== '' ? $tarih : 'now');
        } catch (\Exception $e) {
            $tarihObj = new \DateTime();
        }

        $tarih1 = $tarihObj->format('Y-m-d');
        $tarih2 = $tarihObj->format('Y-m-d');

        if($request->takvimgorunum=='agendaDay')
        {
            $tarih1 = $tarihObj->format('Y-m-d');
            $tarih2 = $tarihObj->format('Y-m-d');
        }
        if($request->takvimgorunum=='agendaWeek')
        {
            $ilk = clone $tarihObj;
            $ilk->modify('monday this week');
            $son = clone $tarihObj;
            $son->modify('sunday this week');
            $tarih1 = $ilk->format('Y-m-d');
            $tarih2 = $son->format('Y-m-d');
        }
        if($request->takvimgorunum=='month')
        {
            $tarih1 = $tarihObj->format('Y-m-01');
            $tarih2 = $tarihObj->format('Y-m-t');
        }

        return self::randevuyukle($request,$request->ayar,$tarih1,$tarih2);
    }
    /**
     * Takvim KOSULLU POLLING icin ucuz degisiklik imzasi.
     * Frontend bunu sik cagirir (cok ucuz); imza degismediyse AGIR randevuyukle
     * tetiklenmez. Online randevu / iptal / duzenleme oldugunda imza degisir ->
     * takvim otomatik yenilenir (refresh'siz, tazelik ~ayni). takvim_degistir ile
     * BIREBIR ayni salon + tarih araligi + randevuyukle ile ayni filtre.
     */
    public function randevuversiyon(Request $request)
    {
        $salonId = self::mevcutsube($request);

        $tarih = trim(str_replace('T',' ',(string)$request->takvimtarih));
        try {
            $tarihObj = new \DateTime($tarih !== '' ? $tarih : 'now');
        } catch (\Exception $e) {
            $tarihObj = new \DateTime();
        }
        $tarih1 = $tarihObj->format('Y-m-d');
        $tarih2 = $tarihObj->format('Y-m-d');
        if ($request->takvimgorunum == 'agendaWeek') {
            $ilk = clone $tarihObj; $ilk->modify('monday this week');
            $son = clone $tarihObj; $son->modify('sunday this week');
            $tarih1 = $ilk->format('Y-m-d');
            $tarih2 = $son->format('Y-m-d');
        } elseif ($request->takvimgorunum == 'month') {
            $tarih1 = $tarihObj->format('Y-m-01');
            $tarih2 = $tarihObj->format('Y-m-t');
        }

        // randevuyukle ile AYNI clamp: gecmis gizliyse imza da sadece bugun ve sonrasini kapsasin,
        // aksi halde gorunmeyen bir gecmis randevu degistiginde bosuna takvim yenilenir.
        $_gecmisGizle = self::gecmisRandevuGizlensinMi($salonId);
        if ($_gecmisGizle && $tarih1 < date('Y-m-d')) {
            $tarih1 = date('Y-m-d');
        }

        // randevuyukle ile AYNI filtre: randevu_hizmetler -> randevu (salon + tarih).
        // Indeksli (rand_salon_tarih_idx + rh_randevu_idx) + buffer pool RAM'de -> ~ms.
        // c: yeni/silme, MAX(rh.id)/MAX(r.id): yeni satir, MAX(updated_at): duzenleme.
        $s = DB::table('randevu_hizmetler as rh')
            ->join('randevular as r', 'r.id', '=', 'rh.randevu_id')
            ->where('r.salon_id', $salonId)
            ->where('r.tarih', '>=', $tarih1)
            ->where('r.tarih', '<=', $tarih2)
            ->selectRaw('COUNT(*) c, COALESCE(MAX(rh.id),0) hmx, COALESCE(MAX(rh.updated_at),0) hmu, COALESCE(MAX(r.id),0) rmx, COALESCE(MAX(r.updated_at),0) rmu')
            ->first();

        $v = $s->c.'|'.$s->hmx.'|'.$s->hmu.'|'.$s->rmx.'|'.$s->rmu;

        // Saati gecen randevu gizlenirken takvimin SADECE zaman ilerledigi icin de
        // tazelenmesi gerekir (hicbir kayit degismese bile). Imzaya 5 dakikalik zaman
        // kovasi ekle: en gec 5 dk icinde saati gecen randevu takvimden dusor.
        if ($_gecmisGizle) {
            $v .= '|t'.floor(time() / 300);
        }

        return response()->json(['v' => $v]);
    }
    public function sistemeyenihizmetkategorisiekle(Request $request)
    {
        $kategori = '';
