    public function odaekleduzenle(Request $request){
        if($r = self::yetkiYoksa403($request, 'ayar.cihaz_oda_yonet')) return $r;
        $enSonOda = Odalar::where('salon_id',$request->sube)->where('aktifmi',1)->orderBy('takvim_sirasi','desc')->first();

        $odalar = "";
        if(isset($request->oda_id)){
            $odalar= Odalar::where('id',$request->oda_id)->first();
            OdaPersonelleri::where('oda_id',$request->oda_id)->delete();
            \App\OdaHizmetler::where('oda_id',$request->oda_id)->delete();
        }
        else
            $odalar = new Odalar();
        $returntext="";
        $odalar->salon_id = $request->sube;
        $odalar->oda_adi = $request->oda_adi;
        // takvim_sirasi yalnizca YENI oda eklenirken atanir; duzenlemede
        // mevcut sira korunur (aksi halde her duzenlemede oda en alta duser).
        if(!isset($request->oda_id)){
            $odalar->takvim_sirasi = $enSonOda ? $enSonOda->takvim_sirasi+1 : 1;
        }
        $odalar->aktifmi = true;
        $odalar->durum = true;
        $secilenPersoneller = $request->oda_personeli ?? [];
        $odalar->personel_id = !empty($secilenPersoneller) ? $secilenPersoneller[0] : null;
        $odalar->save();
        foreach($secilenPersoneller as $personel){
            $odaPersoneli = new OdaPersonelleri();
            $odaPersoneli->oda_id = $odalar->id;
            $odaPersoneli->salon_id =$request->sube;
            $odaPersoneli->personel_id = $personel;
            $odaPersoneli->save();
        }
        $secilenHizmetler = $request->oda_hizmetleri ?? [];
        foreach($secilenHizmetler as $hizmetId){
            if(!$hizmetId) continue;
            \App\OdaHizmetler::create([
                'salon_id' => $request->sube,
                'oda_id' => $odalar->id,
                'hizmet_id' => $hizmetId,
            ]);
        }
        if(!isset($request->oda_id))
        {
            $kategori_son_renk = OdaRenkleri::where('salon_id',$request->sube)->orderBy('id','desc')->first();
            $yeni_kategori_renk = '';
            if($kategori_son_renk === null)
            {
                $yeni_kategori_renk = 1;
            }
            else
            {
                if($kategori_son_renk->renk_id == 10)
                    $yeni_kategori_renk = 1;
                else
                    $yeni_kategori_renk = $kategori_son_renk->renk_id + 1;
            }
            $yeni_renk = new OdaRenkleri();
            $yeni_renk->salon_id = $request->sube;
            $yeni_renk->renk_id = $yeni_kategori_renk;
            $yeni_renk->oda_id = $odalar->id;
            $yeni_renk->save();   
        }
        SalonAudit::log($request->sube, isset($request->oda_id) ? 'oda_guncelle' : 'oda_ekle', 'oda', $odalar->id,
            $odalar->oda_adi, isset($request->oda_id) ? 'Oda bilgileri güncellendi' : 'Yeni oda eklendi');
        return self::oda_liste_getir($request,$returntext);
    }
