    public function odadetayigetir(Request $request)
    {
        $oda = Odalar::where('id',$request->oda_id)->first();
        $odaPersonelleri = OdaPersonelleri::where('oda_id',$request->oda_id)->get();
        $personeller = [];
        $personel_idler = [];
        foreach($odaPersonelleri as $op){
            if($op->personel){
                $personeller[] = [
                    'id' => $op->personel_id,
                    'ad_soyad' => $op->personel->personel_adi
                ];
                $personel_idler[] = $op->personel_id;
            }
        }
        $hizmet_idler = \App\OdaHizmetler::where('oda_id',$request->oda_id)->pluck('hizmet_id')->toArray();
        return array(
            'oda_adi' => $oda->oda_adi,
            'personeller' => $personeller,
            'personel_idler' => $personel_idler,
            'hizmet_idler' => $hizmet_idler,
            'id' => $oda->id
        );
    }
    public function oda_liste_getir(Request $request,$returntext){

        $odalar = Odalar::where('salon_id',self::mevcutsube($request))->where('aktifmi',true)
            ->orderBy('takvim_sirasi','asc')->orderBy('id','asc')->get();

        // Self-heal: takvim_sirasi degerlerini 0..n-1 olarak yeniden numaralandir.
        // Kalip kalmis duplicate/NULL/bosluklar boylece temizlenir; siralama
        // butonlarinin "degismeme/atlama" hatasini onler.
        foreach($odalar as $i => $o){
            if((int)$o->takvim_sirasi !== $i){
                Odalar::where('id',$o->id)->update(['takvim_sirasi'=>$i]);
                $o->takvim_sirasi = $i;
            }
        }

