    public function oda_sil(Request $request){
        if($r = self::yetkiYoksa403($request, 'ayar.cihaz_oda_yonet')) return $r;
        $oda = Odalar::where('id',$request->oda_id)->first();
        $oda->aktifmi = false;
        $silinen_sira = $oda->takvim_sirasi;
        $oda->save();
        Odalar::where('aktifmi', true)
        ->where('takvim_sirasi', '>', $silinen_sira)
        ->orderBy('takvim_sirasi')
        ->get()
        ->each(function ($oda) {
            $oda->takvim_sirasi -= 1;
            $oda->save();
        });
        OdaRenkleri::where('oda_id',$request->oda_id)->delete();
        SalonAudit::log($oda->salon_id, 'oda_sil', 'oda', $oda->id,
            $oda->oda_adi, 'Oda kaldırıldı');
        return self::oda_liste_getir($request,"Oda başarıyla kaldırıldı");
    }
    public function cihaz_sil(Request $request){
        if($r = self::yetkiYoksa403($request, 'ayar.cihaz_oda_yonet')) return $r;
        $cihaz = Cihazlar::where('id',$request->cihaz_id)->first();
        Cihazlar::where('id',$request->cihaz_id)->update(['aktifmi'=>false]);
        SalonCihazRenkleri::where('cihaz_id',$request->cihaz_id)->delete();
        if($cihaz){
            SalonAudit::log($cihaz->salon_id, 'cihaz_sil', 'cihaz', $cihaz->id,
                $cihaz->cihaz_adi, 'Cihaz kaldırıldı');
        }
        return self::cihaz_liste_getir($request,"Cihaz başarıyla kaldırıldı");
    }
    public function randevu_dogrulama_kodu_gonder(Request $request)
    {
        $randevu = Randevular::where('id',$request->randevuid)->first();
    
        $random = str_shuffle('1234567890');
        $kod = substr($random, 0, 4);
        $randevu->dogrulama = $kod;
        $randevu->save();
        $mesaj = array(
            // urgent=true: dogrulama kodu antiban kuyrugunda beklemeden anlik gider.
            array("to"=>$randevu->users->cep_telefon,"message"=>"Doğrulama kodunuz : ".$kod,"urgent"=>true),
        );
        $sms = self::sms_gonder_bildirimli($request,$mesaj,true,1,true);
        if(is_array($sms) && ($sms['status'] ?? null) == 'success')
        {
            $randevu->dogrulama_sms_gonderildi = 1;
            $randevu->save();

        }
        elseif(!is_array($sms))
        {
            // sms_gonder_bildirimli beklenmedik bir deger dondu (null/string).
            // Cagiran metodun status kontrolu patlamasin diye normalize ediyoruz.
            $sms = array(
                'title'  => 'Hata',
                'status' => 'error',
                'text'   => 'Doğrulama kodu gönderilemedi. SMS veya WhatsApp bağlantınızı kontrol edin.',
            );
        }
        return $sms;
    }
    public function adisyonhizmetguncelle(Request $request)
    {
        $hizmet = AdisyonHizmetler::where('id',$request->hizmet_id)->first();
        $dogrulama_kodu_ayari = SalonSMSAyarlari::where('salon_id',Adisyonlar::where('id',$hizmet->adisyon_id)->value('salon_id'))->where('ayar_id',16)->value('musteri');
        if(($dogrulama_kodu_ayari && $hizmet->dogrulama_kodu == $request->dogrulama_kodu) || (!$dogrulama_kodu_ayari || $request->geldimi!==1))
        {
            $hizmet->geldi = $request->geldimi;
            $hizmet->save();
            return self::adisyon_hizmet_getir($hizmet->id);
            exit;
        }
        else
        {
            return 'Doğrulama kodu hatalı, lütfen yeniden deneyiniz.';
            exit;
        }
    }
    public function adisyonhizmetpersonelguncelle(Request $request)
    {
        $hizmet = AdisyonHizmetler::where('id',$request->hizmet_id)->first();
        $hizmet->personel_id = $request->personel_id;
        $hizmet->save();
        return self::adisyon_hizmet_getir($hizmet->id);
    }
    public function adisyonhizmethizmetguncelle(Request $request)
    {
        $hizmet = AdisyonHizmetler::where('id',$request->hizmet_id)->first();
        $hizmet->hizmet_id = $request->adisyon_hizmet_id;
        $hizmet->save();
        return self::adisyon_hizmet_getir($hizmet->id);
    }
    public function adisyonhizmetfiyatguncelle(Request $request)
    {
        $hizmet = AdisyonHizmetler::where('id',$request->hizmet_id)->first();
        $hizmet->fiyat = $request->tutar;
        $hizmet->save();
        $adisyon = Adisyonlar::where('id',$hizmet->adisyon_id)->first();
        return array(
            'hizmet_liste'=>self::adisyon_hizmet_getir($hizmet->id),
            'adisyon_detay'=>self::adisyon_detay($request,$adisyon,false,''),
        );
    }
    public function hizmetdogrulamakodugonder(Request $request)
    {
        $hizmet = AdisyonHizmetler::where('id',$request->hizmet_id)->first();
        $random = str_shuffle('1234567890');
        $kod = substr($random, 0, 4);
        $hizmet->dogrulama_kodu = $kod;
        $hizmet->save();
        $musteri = User::where('id',Adisyonlar::where('id',$hizmet->adisyon_id)->value('user_id'))->first();
        $mesaj = array(
            array("to"=>$musteri->cep_telefon,"message"=>"Doğrulama kodunuz : ".$kod),
        );
          self::sms_gonder_bildirimli($request,$mesaj,false,1,true);
        return '';
    }
    public function seans_dogrulama_kodu_gonder(Request $request)
    {
        $seans = AdisyonPaketSeanslar::where('id',$request->seans_id)->first();
        $adisyon_paket = AdisyonPaketler::where('id',$seans->adisyon_paket_id)->first();
        $random = str_shuffle('1234567890');
        $kod = substr($random, 0, 4);
        $seans->dogrulama_kodu = $kod;
        $seans->save();
        if(Randevular::where('seans_id',$seans->id)->count()==1)
        {
            $randevu = Randevular::where('seans_id',$seans->id)->first();
            $randevu->dogrulama = $kod;
            $randevu->save();
        }
        $mesaj = array(
            array("to"=>$adisyon_paket->adisyon->musteri->cep_telefon,"message"=>"Doğrulama kodunuz : ".$kod),
        );
         self::sms_gonder_bildirimli($request,$mesaj,false,1,true);
        return '';
    }
   public function randevugeldiisaretle(Request $request)
  {
     // REQUEST'TEN GELEN DEĞERLERİ AL
    $dogrulamaSoruldu = $request->dogrulamaSoruldu ?? false;
    $dogrulamaSorulduGonderilecek = $request->dogrulamaSorulduGonderilecek ?? false;
    
    $randevu = Randevular::where('id', $request->randevuid)->first();

    // YETIM/HAYALET SEANS TEMIZLIGI: Paket randevusu olmadigi halde, kazara olusmus
    // adisyon_paket_seanslar kayitlari "paketten dus / seans secim" popup'ini yanlis
    // tetikliyor. Ne gecerli bir adisyon_paket'e ne de gecerli bir adisyon_hizmet'e
    // bagli olan seanslari (hicbir seyden dusulemez) geldi isaretlemeden once sil.
    // Gecerli seanslar (paket VEYA gercek hizmet seansi) korunur.
    $gecersizSeansIdler = [];
    foreach (AdisyonPaketSeanslar::where('randevu_id', $request->randevuid)->get() as $__s) {
        $paketGecerli  = $__s->adisyon_paket_id  && AdisyonPaketler::where('id', $__s->adisyon_paket_id)->exists();
        $hizmetGecerli = $__s->adisyon_hizmet_id && AdisyonHizmetler::where('id', $__s->adisyon_hizmet_id)->exists();
        if (!$paketGecerli && !$hizmetGecerli) $gecersizSeansIdler[] = $__s->id;
    }
    if (!empty($gecersizSeansIdler)) {
        \Log::warning('[YETIM-SEANS] gecersiz seans temizlendi', [
            'randevu_id' => $request->randevuid,
            'ids'        => $gecersizSeansIdler,
        ]);
        AdisyonPaketSeanslar::whereIn('id', $gecersizSeansIdler)->delete();
    }

    $seansVar = AdisyonPaketSeanslar::where('randevu_id',$request->randevuid)->count();
 Log::info('Seans var mı? ' . $seansVar);
    if($seansVar>0)
    {
        $dogrulama_kodu_ayari = SalonSMSAyarlari::where('salon_id', $randevu->salon_id)
            ->where('ayar_id', 16)
            ->value('musteri');
        Log::info('doğrulama ayarı (bool): ' . ($dogrulama_kodu_ayari ? 'true' : 'false'));
        // Doğrulama gerekiyor mu? - DÜZELTİLDİ

            Log::info('doğrulama soruldu '.$dogrulamaSoruldu);
             Log::info('doğrulama gönder '.$dogrulamaSorulduGonderilecek);
              Log::info('doğrulama ayarı '.$dogrulama_kodu_ayari);

        $kontrol = ($dogrulama_kodu_ayari == 1 || ($dogrulamaSoruldu && $dogrulamaSorulduGonderilecek));
        Log::info('IF koşulu sonucu: ' . ($kontrol ? 'TRUE' : 'FALSE'));
    
        if ($kontrol) {
            
        Log::info('IF bloğuna girdi');    
            
            if(!$randevu->dogrulama_sms_gonderildi){
                $gonderim = self::randevu_dogrulama_kodu_gonder($request);
                // Kod gonderilemediyse (SMS/WhatsApp bagli degil) personele net mesaj don;
                // aksi halde personel asla dogru kodu giremez ve islem sonsuza dek tikanir.
                if(is_array($gonderim) && ($gonderim['status'] ?? null) === 'error'){
                    return array(
                        'dogrulamaGerekli' => 1,
                        'hatamesaj' => $gonderim['text'] ?? 'Doğrulama kodu gönderilemedi. İşletmenize ait SMS veya WhatsApp bağlantısı bulunmuyor.'
                    );
                }

            }
                
            if ($request->isKvkkProcess && $request->dogrulama_kodu == '') {
                return array(   
                    'dogrulamaGerekli' => 1,
                    'hatamesaj' => 'Lütfen doğrulama kodunu giriniz'
                );
            }
            
            if ($randevu->dogrulama != $request->dogrulama_kodu) {


                return array(
                    'dogrulamaGerekli' => 1,
                    'hatamesaj' => 'Doğrulama kodu hatalı, lütfen yeniden deneyiniz'
                );
            }
        }
        else{
              Log::info('ELSE bloğuna girdi');
            if(!$dogrulamaSoruldu)  // DÜZELTİLDI
            {
                 Log::info('dogrulamaSorulsun dönecek');
                return array(
                    'dogrulamaSorulsun' => 1,
                    'hatamesaj' => 'Müşteriye doğrulama kodu gönderilsin mi?'
                );
            }
        }
    }
    $kvkkOnayiAktif = SalonSMSAyarlari::where('salon_id', $request->sube)
        ->where('ayar_id', 22)
        ->value('musteri');
    
    $portfoy = MusteriPortfoy::where('user_id', $randevu->user_id)
        ->where('salon_id', $randevu->salon_id)
        ->first();

    $olusturulanOnayKodu = $portfoy->onay_kodu;
    
    // KVKK kontrolü - sadece ilk defa geliyorsa
    if ($kvkkOnayiAktif && !$portfoy->kvkk_onay_alindi) {
        // Eğer doğrulama kodu henüz girilmemişse
        if (!$request->isKvkkProcess && $request->dogrulama_kodu == '' && $request->kvkkOnayKodu == '') {
            // Önce doğrulama kodunu iste
            $dogrulama_kodu_ayari = SalonSMSAyarlari::where('salon_id', $randevu->salon_id)
                ->where('ayar_id', 16)
                ->value('musteri');
            
            if ($dogrulama_kodu_ayari) {
                return array(
                    'dogrulamaGerekli' => 1,
                    'hatamesaj' => 'Lütfen önce doğrulama kodunu giriniz'
                );
            }
        }
        
        // KVKK kodu kontrolü
        if ($request->isKvkkProcess && $request->kvkkOnayKodu == '') {
            // KVKK kodu gönder
            $onayMesaji = "Sn. ".$randevu->users->name.", ".$olusturulanOnayKodu." numarali onay kodunu ilgiliye soyleyerek, ".$randevu->salonlar->kvkk_link." kvkk linkinde yer alan KVKK Aydinlatma Metni'ne gore kisisel verilerinizin islenmesine ve sistemlerimizde kayitli iletisim adresleriniz uzerinden SMS, e-posta ve aramalar vasitasiyla ticari elektronik ileti gonderimine izin vermis olacaksiniz";
            
            Log::info('KVKK SMS gönderilecek');
            self::sms_gonder_bildirimli($request, array(array(
                "to" => $randevu->users->cep_telefon,
                "message" => $onayMesaji
            )), false, 1, false);
            
            return array(
                'detailtext' => '',
                'title' => 'Uyarı',
                'mesaj' => '<p>Müşteri bilgilerini sisteme kaydetmeden önce verilerinin işlenmesine ve kayıtlı iletişim adresleri üzerinden SMS, e-posta ve aramalar vasıtasıyla ticari elektronik ileti gönderimine izin verdiğine dair cep telefonuna gönderilen onay kodunu girmeniz gerekmektedir.<p>',
                'onayGerekli' => true,
                'status' => 'warning',
                'showCloseButton' => false,
                'showCancelButton' => true,
                'showConfirmButton' => true,
            );
        } 
        elseif ($request->isKvkkProcess && $request->kvkkOnayKodu != '' && $request->kvkkOnayKodu != $olusturulanOnayKodu) {
            Log::info('KVKK yanlış girildi tekrar uyarı');
            return array(
                'detailtext' => '',
                'title' => 'Uyarı',
                'mesaj' => '<p>Girilen onay kodu hatalı. Lütfen müşteriye gönderilen doğru onay kodunu giriniz.<p>',
                'onayGerekli' => true,
                'status' => 'warning',
                'showCloseButton' => false,
                'showCancelButton' => true,
                'showConfirmButton' => true,
            );
        }
        
        // KVKK kodu doğru girildiyse kaydet
        if ($request->kvkkOnayKodu == $olusturulanOnayKodu) {
            $portfoy->kvkk_onay_alindi = true;
            $portfoy->save();
        }
    }


        // Seans secim modu (web): randevuda paket seansi varsa kullaniciya
        // hangi seanslarin dusulecegini sorar. Mobil ApiController'daki
        // 'seans_secim_destek' bayragiyla ayni mantik — Flutter app icin daha
        // once eklenmisti, web'e de tasidik. Eski cagrilar (bayrak gondermeyen)
        // backward compat (hepsi geldi=true) korur.
        // NOT: bu Laravel surumunde Request::boolean() yok; filter_var kullaniyoruz.
        $seansSecimDestek = filter_var($request->input('seans_secim_destek', false), FILTER_VALIDATE_BOOLEAN);
        $secilenSeansIdler = $request->input('secilen_seans_idler');
        // 'secim_yapildi' bayragi: kullanici popup'ta hicbir seans secmese bile
        // (bos liste) secim yapilmis sayilir. Aksi halde is_array(null)=false olur
        // ve backend tekrar seansSecimGerekli doner -> sonsuz dongu.
        $secimYapildi = filter_var($request->input('secim_yapildi', false), FILTER_VALIDATE_BOOLEAN);
        $secilenVerildi = $secimYapildi || is_array($secilenSeansIdler);

        $seansSayisi = AdisyonPaketSeanslar::where('randevu_id', $randevu->id)->count();
        if ($seansSayisi > 0 && $seansSecimDestek && !$secilenVerildi) {
            $seanslarListe = AdisyonPaketSeanslar::where('randevu_id', $randevu->id)->get();
            $list = [];
            foreach ($seanslarListe as $s) {
                $ap = AdisyonPaketler::where('id', $s->adisyon_paket_id)->first();
                $paketAdi = '';
                $toplamSeans = 0;
                $kullanilan = 0;
                if ($ap) {
                    $paketObj = Paketler::where('id', $ap->paket_id)->first();
                    $paketAdi = $paketObj ? $paketObj->paket_adi : '';
                    $toplamSeans = (int) $ap->seans_sayisi;
                    // dusulen_miktar destegi: her satir kendi miktari kadar duser.
                    // Eski default 1 oldugu icin eski paketler bozulmaz.
                    $kullanilan = (int) AdisyonPaketSeanslar::where('adisyon_paket_id', $ap->id)
                        ->where('geldi', true)
                        ->sum('dusulen_miktar');
                }
                $kalan = max(0, $toplamSeans - $kullanilan);
                // Default miktar: randevu modalinda salon girmisse o, yoksa 1
                $rhRow = RandevuHizmetler::where('randevu_id', $randevu->id)
                    ->where('hizmet_id', $s->hizmet_id)
                    ->first();
                $sureDk = (int) ($rhRow->sure_dk ?? 0);
                $defaultMiktar = ($rhRow && $rhRow->dusum_miktari) ? (int) $rhRow->dusum_miktari : 1;
                $list[] = [
                    'id'               => (int) $s->id,
                    'hizmet_adi'       => $s->hizmet ? $s->hizmet->hizmet_adi : '',
                    'paket_adi'        => $paketAdi,
                    'personel_adi'     => $s->personel ? $s->personel->personel_adi : '',
                    'adisyon_paket_id' => (int) $s->adisyon_paket_id,
                    'kalan_seans'      => $kalan,
                    'toplam_seans'     => $toplamSeans,
                    'seans_no'         => (int) ($s->seans_no ?? 0),
                    'sure_dk'          => $sureDk,
                    'default_miktar'   => $defaultMiktar,
                    'dusulen_miktar'   => (int) ($s->dusulen_miktar ?? 1),
                    'simdi_geldi'      => $s->geldi == true,
                ];
            }
            return array(
                'seansSecimGerekli' => 1,
                'seanslar'          => $list,
                'musteri_adi'       => $randevu->users->name ?? '',
                'tarih'             => $randevu->tarih ?? '',
                'saat'              => $randevu->saat ?? '',
            );
        }


        $randevu->randevuya_geldi = true;

        $randevu->save();

        // Audit
        $_audit_musteriAdi = optional($randevu->users)->name ?? 'Müşteri #'.$randevu->user_id;
        $_audit_label = $_audit_musteriAdi.' — '.date('d.m.Y',strtotime($randevu->tarih)).' '.date('H:i',strtotime($randevu->saat));
        SalonAudit::log($randevu->salon_id, 'randevu_geldi', 'randevu', $randevu->id, $_audit_label,
            'Müşteri randevuya geldi olarak işaretlendi');

        $seanslar = AdisyonPaketSeanslar::where('randevu_id',$randevu->id);

        if ($secilenVerildi) {
            $secilenIds = array_map('intval', (array) $secilenSeansIdler);
            $miktarlar = (array) $request->input('seans_miktarlari', []);
            \Log::info('[SEANS-REPLICATE] in', [
                'randevu_id'  => $randevu->id,
                'secilen_ids' => $secilenIds,
                'miktarlar'   => $miktarlar,
            ]);
            foreach ($secilenIds as $sid) {
                $m = 1;
                if (isset($miktarlar[$sid]))            $m = max(1, (int) $miktarlar[$sid]);
                elseif (isset($miktarlar[(string)$sid])) $m = max(1, (int) $miktarlar[(string)$sid]);

                $orijinal = AdisyonPaketSeanslar::where('id', $sid)
                    ->where('randevu_id', $randevu->id)
                    ->first();
                \Log::info('[SEANS-REPLICATE] foreach', [
                    'sid' => $sid, 'm' => $m,
                    'orijinal_bulundu' => $orijinal ? true : false,
                    'ap_id' => $orijinal->adisyon_paket_id ?? null,
                ]);
                if (!$orijinal) continue;

                $orijinal->geldi = true;
                $orijinal->dusulen_miktar = 1;
                $orijinal->save();

                // Replika kosulu: paket seansi (adisyon_paket_id) VEYA hizmet seansi
                // (adisyon_hizmet_id). Eskiden sadece adisyon_paket_id kontrol ediliyordu;
                // hizmet-adisyonu seanslari adisyon_paket_id NULL oldugu icin replika atlanip
                // dusum_miktari kadar yerine 1 kayit ekleniyordu.
                if ($m > 1 && ($orijinal->adisyon_paket_id || $orijinal->adisyon_hizmet_id)) {
                    $maxQ = AdisyonPaketSeanslar::query();
                    if ($orijinal->adisyon_paket_id) $maxQ->where('adisyon_paket_id', $orijinal->adisyon_paket_id);
                    else                              $maxQ->where('adisyon_hizmet_id', $orijinal->adisyon_hizmet_id);
                    $maxSeansNo = (int) $maxQ->max('seans_no');
                    \Log::info('[SEANS-REPLICATE] ekleme baslayacak', [
                        'sid' => $sid, 'm' => $m, 'eklenecek_adet' => $m - 1, 'max_seans_no' => $maxSeansNo,
                        'ap_id' => $orijinal->adisyon_paket_id, 'ah_id' => $orijinal->adisyon_hizmet_id,
                    ]);
                    for ($i = 1; $i < $m; $i++) {
                        $maxSeansNo++;
                        try {
                            $yeni = $orijinal->replicate();
                            $yeni->geldi = true;
                            $yeni->dusulen_miktar = 1;
                            $yeni->seans_no = $maxSeansNo;
                            $yeni->save();
                            // Yeni satiri korumali id listesine ekle — delete asamasinda silinmesin
                            $secilenIds[] = (int) $yeni->id;
                            \Log::info('[SEANS-REPLICATE] yeni satir eklendi', [
                                'yeni_id' => $yeni->id, 'seans_no' => $maxSeansNo,
                            ]);
                        } catch (\Throwable $e) {
                            \Log::error('[SEANS-REPLICATE] save hata', ['err' => $e->getMessage()]);
                        }
                    }
                } else {
                    \Log::info('[SEANS-REPLICATE] ekleme atlandi', [
                        'sid' => $sid, 'm' => $m, 'ap_id' => $orijinal->adisyon_paket_id, 'ah_id' => $orijinal->adisyon_hizmet_id,
                    ]);
                }
            }
            // Isaretlenmeyenleri sil — yeni replikalar zaten $secilenIds'e eklendigi icin korunur
            AdisyonPaketSeanslar::where('randevu_id', $randevu->id)
                ->whereNotIn('id', $secilenIds)
                ->delete();
            // Paket bazli DB durumu — gosterim sorunu teshisi icin
            try {
                $apIds = \DB::table('adisyon_paket_seanslar')
                    ->whereIn('id', $secilenIds)
                    ->pluck('adisyon_paket_id')->filter()->unique()->values()->all();
                foreach ($apIds as $apId) {
                    $rows = \DB::table('adisyon_paket_seanslar')
                        ->where('adisyon_paket_id', $apId)
                        ->select('id','hizmet_id','adisyon_hizmet_id','randevu_id','geldi','dusulen_miktar','seans_no')
                        ->orderBy('id')->get();
                    \Log::info('[SEANS-REPLICATE] paket_satirlari', ['ap_id' => $apId, 'rows' => $rows->toArray()]);
                    $cnt = $rows->where('geldi', 1)->count();
                    $sum = (int) $rows->where('geldi', 1)->sum('dusulen_miktar');
                    $hizmetGruplari = $rows->where('geldi', 1)->groupBy('hizmet_id')->map->count();
                    \Log::info('[SEANS-REPLICATE] paket_ozet', [
                        'ap_id' => $apId, 'count_geldi' => $cnt, 'sum_dusulen' => $sum,
                        'hizmet_bazli_count' => $hizmetGruplari,
                    ]);
                }
            } catch (\Throwable $e) {
                \Log::error('[SEANS-REPLICATE] db_after_err', ['err' => $e->getMessage()]);
            }
        } else {
            foreach($seanslar->get() as $seans)
            {

                $seans->geldi = true;
                $seans->save();
            }
        }

        // Musteriye seans kullanim bilgilendirme push'u — ApiController'daki
        // aynı akıs (SeansBildirimService merkezi). Hata fail olsa bile
        // "Geldi" akışı bozulmasın diye try/catch.
        if ($seanslar->count() > 0) {
            try {
                app(\App\Services\SeansBildirimService::class)->bilgilendir($randevu);
            } catch (\Throwable $e) {
                \Log::warning('[SEANS-KULLANIM] push fail (web)', [
                    'randevu_id' => $randevu->id,
                    'err' => $e->getMessage(),
                ]);
            }
        }

        // Dakika paketi otomatik dusumu (solaryum vb. sure satislari).
        // randevu_hizmetler.musteri_dakika_paketi_id dolu olan satirlardan
        // paket_dakika kadar musterinin paket bakiyesinden dusulur.
        try {
            app(\App\Services\MusteriDakikaPaketService::class)
                ->randevuGeldiUygula($randevu, \Auth::id());
        } catch (\Throwable $e) {
            \Log::warning('[DAKIKA-PAKETI] web hook hata', [
                'randevu_id' => $randevu->id,
                'err' => $e->getMessage(),
            ]);
        }

 
    
    $mesajlar = array();
    foreach ($randevu->hizmetler as $hizmet) {
        $mesaj = $randevu->users->name . " isimli müşteriniz " . date('H:i', strtotime($hizmet->saat)) . " " . $hizmet->hizmetler->hizmet_adi . " randevusu için işletmenize gelmiştir.";
        if (SalonSMSAyarlari::where('salon_id', $randevu->salon_id)
            ->where('ayar_id', 21)
            ->value('personel') == 1) {
            
            Log::info('Geldi bildirimi personele gidecek');
            
            
            $yetkiliid = Personeller::where('id', $hizmet->personel_id)->value('yetkili_id');
            array_push($mesajlar, array(
                "to" => IsletmeYetkilileri::where('id', $yetkiliid)->value('gsm1'),
                "message" => $mesaj
            ));
        }

        self::bildirimekle($request, $randevu->salon_id, $mesaj, "#", $hizmet->personel_id, null, Auth::guard('isletmeyonetim')->user()->profil_resim, $randevu->id);

        if($hizmet->personel_id){
            try {
                NotificationService::toStaff((int)$hizmet->personel_id, (int)$randevu->salon_id)
                    ->type(NotificationTypes::APPOINTMENT_CREATED)
                    ->title('Yeni Randevu')
                    ->body($mesaj)
                    ->randevu((int)$randevu->id)
                    ->deepLink('appointment_detail', ['randevu_id' => $randevu->id])
                    ->send();
            } catch (\Throwable $e) { \Log::warning('yeni randevu push: '.$e->getMessage()); }
        }
    }
    
    if (count($mesajlar) > 0) {
        Log::info('Geldi bildirimi personele gönder');
        self::sms_gonder_bildirimli($request, $mesajlar, false, 1, false);
    }
    
    return array('mesaj' => 'Başarılı', 'geldiIsaretlendi' => true);
}
