    public function randevutahsilet(Request $request)
    {
        $randevu = Randevular::where('id',$request->randevuid)->first();
        //$randevu->randevuya_geldi = true;
        $adisyonvar = false;
        $adisyon = '';
        foreach($randevu->hizmetler as $hizmet)
        {
            $hizmetlernonexp = explode('+',$hizmet->hizmetler->hizmet_adi);
            foreach($hizmetlernonexp as $hizmetlerexp)
            {
                $adisyon_var = DB::table('adisyonlar')
                ->join('adisyon_hizmetler','adisyonlar.id','=','adisyon_hizmetler.adisyon_id')
                ->join('adisyon_paketler','adisyonlar.id','=','adisyon_paketler.adisyon_id')
                ->join('adisyon_paket_seanslar','adisyon_paketler.id','=','adisyon_paket_seanslar.adisyon_paket_id')
                ->join('paketler','adisyon_paketler.paket_id','=','paketler.id')
                ->join('paket_hizmetler','paketler.id','=','paket_hizmetler.paket_id')
                ->join('hizmetler','paket_hizmetler.hizmet_id','=','hizmetler.id')

                ->select('adisyonlar.id as adisyon_id',DB::raw('(SELECT COUNT(*) from adisyon_paket_seanslar where adisyon_paket_seanslar.geldi is null and adisyon_paket_seanslar.adisyon_paket_id = adisyon_paketler.id) as gelinmeyen_seans_sayisi'))
                ->where('adisyonlar.salon_id',$randevu->salon_id)
                ->where('adisyonlar.user_id',$randevu->user_id)->having(DB::raw('gelinmeyen_seans_sayisi') ,'>',0)->first();
                if($adisyon_var && !$adisyonvar)
                {
                    $adisyon = Adisyonlar::where('id',$adisyon_var->adisyon_id)->first();
                    $adisyonvar = true;
                    break;
                }
            }
        }
        if(AdisyonPaketSeanslar::where('id',$randevu->seans_id)->count()==1)
        {
            $seans = AdisyonPaketSeanslar::where('id',$randevu->seans_id)->first();
            $paket = AdisyonPaketler::where('id',$seans->adisyon_paket_id)->first();
            $adisyon = $paket->adisyon;
            $adisyonvar = true;
        }
        /*$dogrulama_kodu_ayari = SalonSMSAyarlari::where('salon_id',$randevu->salon_id)->where('ayar_id',16)->value('musteri');
        if(($dogrulama_kodu_ayari && $randevu->dogrulama == $request->dogrulama_kodu) || !$dogrulama_kodu_ayari)
        {*/
            $adisyon_id = '';
            if(!$adisyonvar) {
                // AYNI GUN + AYNI MUSTERI ADISYON BIRLESTIRMESI (kullanici geri
                // bildirimi): ayni gunde ayni musteride ONCEDEN acilmis randevu-tahsilat
                // adisyonu varsa, YENI adisyon acmak yerine oraya ekle. Ornek: kadin
                // 2 farkli saatte randevu aldi (paket disi), her ikisi de tahsilat butonu
                // ile ayri adisyona giriyordu -> tek adisyonda birleser.
                $ayniGunAdisyonId = DB::table('adisyonlar')
                    ->join('adisyon_hizmetler', 'adisyon_hizmetler.adisyon_id', '=', 'adisyonlar.id')
                    ->join('randevular', 'randevular.id', '=', 'adisyon_hizmetler.randevu_id')
                    ->where('adisyonlar.user_id', $randevu->user_id)
                    ->where('adisyonlar.salon_id', $randevu->salon_id)
                    ->where('randevular.tarih', $randevu->tarih)
                    ->where('randevular.id', '!=', $randevu->id) // kendisi degil
                    ->whereNotNull('adisyon_hizmetler.randevu_id')
                    ->value('adisyonlar.id');
                if ($ayniGunAdisyonId) {
                    $adisyon_id = $ayniGunAdisyonId;
                } else {
                    $adisyon_id = self::yeni_adisyon_olustur($randevu->user_id,$randevu->salon_id,date('d.m.Y',strtotime($randevu->tarih)).' tarihli randevuda alınan hizmetlerin ödemesi',date('Y-m-d'));
                }
            } else {
                $adisyon_id=$adisyon->id;
            }
            //$randevu->save();
            // FIX (karisik paket + paketsiz): eskiden !$adisyonvar tum hizmet
            // loop'unu atliyor, paket seansi olan bir randevuda paketsiz
            // hizmetler icin adisyon_hizmet acilmayip tahsilat gorulmuyordu.
            // Yeni davranis: her hizmet icin ayri kontrol —
            //   * yardimci personel satiri => atla (eskisi gibi)
            //   * bu randevu icin AdisyonPaketSeanslar'da hizmet_id eslesmesi
            //     varsa (paketten dusuluyor) => atla
            //   * bu randevu icin bu hizmet_id'de zaten adisyon_hizmet varsa
            //     => atla (idempotency)
            //   * degilse adisyon_id'ye (paketin adisyonu veya yeni acilan)
            //     paketsiz hizmet olarak ekle
            foreach($randevu->hizmetler as $hizmet) {
                if($hizmet->yardimci_personel) continue;
                $paketSeansiVar = AdisyonPaketSeanslar::where('randevu_id', $randevu->id)
                    ->where('hizmet_id', $hizmet->hizmet_id)
                    ->exists();
                if($paketSeansiVar) continue;
                $adisyonHizmetiVar = AdisyonHizmetler::where('randevu_id', $randevu->id)
                    ->where('hizmet_id', $hizmet->hizmet_id)
                    ->exists();
                if($adisyonHizmetiVar) continue;
                self::adisyon_hizmet_ekle(
                    $adisyon_id,
                    $hizmet->hizmet_id,
                    $randevu->tarih,
                    $hizmet->saat,
                    $hizmet->sure_dk,
                    $hizmet->fiyat,
                    true,
                    $hizmet->personel_id,
                    $hizmet->cihaz_id,
                    null,
                    null,
                    $randevu->id
                );
            }

            // AYNI GUN AYNI MUSTERI DIGER RANDEVULARINI DA BIRLESTIR (paketsiz olanlar).
            // Kullanici geri bildirimi: 'ayni gunde 2 ayri randevu var, birinin
            // tahsilat butonuna basinca hepsi tek adisyonda birlessin (paket olmayanlar)'.
            // Ayni akis: paket seansi olan hizmet satirlarini atla, mevcut adisyon_hizmet
            // varsa idempotency icin skip.
            try {
                $digerRandevular = Randevular::where('user_id', $randevu->user_id)
                    ->where('salon_id', $randevu->salon_id)
                    ->where('tarih', $randevu->tarih)
                    ->where('id', '!=', $randevu->id)
                    ->where('durum', '<', 2) // iptal olmayan
                    ->with('hizmetler')
                    ->get();
                foreach ($digerRandevular as $dr) {
                    foreach ($dr->hizmetler as $dh) {
                        if ($dh->yardimci_personel) continue;
                        $_paketSeansiVar = AdisyonPaketSeanslar::where('randevu_id', $dr->id)
                            ->where('hizmet_id', $dh->hizmet_id)
                            ->exists();
                        if ($_paketSeansiVar) continue; // paket hizmeti — atla
                        $_adisyonHizmetiVar = AdisyonHizmetler::where('randevu_id', $dr->id)
                            ->where('hizmet_id', $dh->hizmet_id)
                            ->exists();
                        if ($_adisyonHizmetiVar) continue; // zaten ekli
                        self::adisyon_hizmet_ekle(
                            $adisyon_id,
                            $dh->hizmet_id,
                            $dr->tarih,
                            $dh->saat,
                            $dh->sure_dk,
                            $dh->fiyat,
                            true,
                            $dh->personel_id,
                            $dh->cihaz_id,
                            null,
                            null,
                            $dr->id
                        );
                    }
                }
            } catch (\Throwable $e) {
                \Log::warning('randevutahsilet ayni gun birlestirme hata: '.$e->getMessage(), [
                    'randevu_id' => $randevu->id ?? null,
                ]);
            }

            return $randevu->user_id."/".$adisyon_id;
            exit;
        /*}
        else
        {
            return 'Doğrulama kodu hatalı, lütfen yeniden deneyiniz';
            exit;
        }*/
    }
    public function yeni_adisyon(Request $request)
    {
        $adisyon_id = self::yeni_adisyon_olustur($request->musteri,$request->sube,$request->adisyon_not,$request->adisyon_tarihi);
        if(isset($request->adisyon_hizmet_id)){
            foreach($request->adisyon_hizmet_id as $key => $hizmet){
                self::adisyon_hizmet_ekle(
                    $adisyon_id,
                    $hizmet,
                    $request->adisyon_hizmet_tarih[$key],
                    $request->adisyon_hizmet_saat[$key],
                    $request->adisyon_hizmet_sure[$key],
                    $request->adisyon_hizmet_fiyat[$key],
                    false,
                    $request->adisyon_hizmet_personel[$key],
                    $request->adisyon_hizmet_personel[$key],
                    null,
                    null,
                    null);
            }
        }
        if(isset($request->urun_id_adisyon)){
            foreach($request->urun_id_adisyon as $key => $urun)
            {
                $adisyon_urun = new AdisyonUrunler();
                $adisyon_urun->islem_tarihi = $request->adisyon_tarihi;
                $adisyon_urun->adisyon_id= $adisyon_id;
                $adisyon_urun->urun_id = $urun;
                $adisyon_urun->adet = $request->urun_adet_adisyon[$key];
                $adisyon_urun->fiyat = $request->urun_fiyat_adisyon[$key];
                $adisyon_urun->personel_id = $request->urun_satan_adisyon[$key];
                $adisyon_urun->save();
            }
        }
        if(isset($request->paket_id_adisyon))
        {
            foreach($request->paket_id_adisyon as $key=>$paket){
                $adisyon_paket_id = self::adisyona_paket_ekle($request,$adisyon_id,$paket,$request->paket_fiyat_adisyon[$key],$request->paket_baslangic_tarihi_adisyon[$key],$request->sens_aralik_gun_adisyon[$key],$request->paket_satan_adisyon[$key],null,null);
                $seanstarih = $request->paket_baslangic_tarihi_adisyon[$key];
                $paket = Paketler::where('id',$paket)->first();
                $toplam_seans_sayilari = $paket->hizmetler->sum('seans');
                for($i=1;$i<=$toplam_seans_sayilari;$i++)
                {
                        if($i>1)
                            $seanstarih = date('Y-m-d',strtotime('+'.$request->paket_seans_aralik_gun_adisyon[$key].' days',strtotime($seanstarih)));
                        $seans = new AdisyonPaketSeanslar();
                        $seans->adisyon_paket_id = $adisyon_paket_id;
                        $seans->seans_tarih = $seanstarih;
                        $seans->save();
                }
            }
        }
        $personelid = '';
        if(self::personelmi($request, 'satis.tum_satis_gor'))
            $pesonelid=Auth::guard('isletmeyonetim')->user()->id;
        return array(
            'tum_adisyonlar'=>self::adisyon_yukle_tahsilat($request,'','','1970-01-01 00:00:00',date('Y-m-d 23:59:59'),'',$personelid,''),
            'hizmet_adisyonlar' => self::adisyon_yukle_tahsilat($request,1,'','1970-01-01 00:00:00',date('Y-m-d 23:59:59'),'',$personelid,''),
            'urun_adisyonlar' => self::adisyon_yukle_tahsilat($request,3,'','1970-01-01 00:00:00',date('Y-m-d 23:59:59'),'',$personelid,''),
            'paket_adisyonlar' => self::adisyon_yukle_tahsilat($request,2,'','1970-01-01 00:00:00',date('Y-m-d 23:59:59'),'',$personelid,''),
            'user_id'=>$request->musteri,
            'adisyon_id'=> $adisyon_id,
        );
    }
    public function yeni_adisyon_olustur($musteriid,$salonid,$adisyonnotu,$tarih)
    {
        $adisyon = new Adisyonlar();
        $adisyon->user_id = $musteriid;
        $adisyon->salon_id =  $salonid;
        $adisyon->olusturan_id = Auth::guard('isletmeyonetim')->user()->id;
        $adisyon->tarih = $tarih;
        $adisyon->save();
        return $adisyon->id;
    }
    public function adisyon_hizmet_ekle($adisyon_id,$hizmet_id,$islem_tarihi,$islem_saati,$sure,$fiyat,$geldi,$personel_id,$cihaz_id,$senet_id,$taksitli_tahsilat_id,$randevuId)
    {
        $cihazid=null;
            if(str_contains($cihaz_id,'cihaz'))
            {
                $str = explode('-',$cihaz_id);
                $cihazid = $str[1];
            }
            else{
                $cihazid=$cihaz_id;
            }
        $adisyon_hizmet = new AdisyonHizmetler();
        $adisyon_hizmet->adisyon_id = $adisyon_id;
        $adisyon_hizmet->personel_id = $personel_id;
        $adisyon_hizmet->cihaz_id = $cihazid;
        $adisyon_hizmet->geldi = $geldi;
        $adisyon_hizmet->hizmet_id = $hizmet_id;
        $adisyon_hizmet->islem_tarihi = $islem_tarihi;
        $adisyon_hizmet->islem_saati = $islem_saati;
        $adisyon_hizmet->sure = $sure;
        $adisyon_hizmet->fiyat = $fiyat;
        $adisyon_hizmet->senet_id = $senet_id;
        $adisyon_hizmet->randevu_id = $randevuId;
        $adisyon_hizmet->taksitli_tahsilat_id = $taksitli_tahsilat_id;
        // NULL seans alanlari: randevu tahsilatinda acilan adisyon_hizmet paket
        // satisi DEGIL (tek seferlik hizmet). paketVarmiKontrolu ve APS insert
        // mantigimiz seans_sayisi > 0 sartina bakiyor; NULL/0 olan satirlar
        // 'paket satisi degil' olarak dogru sekilde islenir. DB kolon default'u
        // 0 olabilir, EXPLICIT NULL ile netlestiriyoruz.
        $adisyon_hizmet->seans_sayisi = null;
        $adisyon_hizmet->bekleyen_seans = null;
        $adisyon_hizmet->kullanilan_seans = null;
        $adisyon_hizmet->kullanilmayan_seans = null;
        $adisyon_hizmet->save();

        // Sarf recetesi varsa otomatik dus (internal helper)
        $salonId = \App\Adisyonlar::where('id', $adisyon_id)->value('salon_id');
        if ($salonId) {
            StokController::receteyiUygula(
                (int) $salonId,
                (int) $hizmet_id,
                'islem',
                $randevuId ? (int) $randevuId : null,
                $personel_id ? (int) $personel_id : null
            );
        }

        return $adisyon_hizmet->id;
    }
    public function adisyona_paket_ekle($request,$adisyon_id,$paket_id,$fiyat,$baslangic_tarihi,$seans_araligi,$personel_id,$senet_id,$taksitli_tahsilat_id,$seansSayisi){
        $paketBilgi = Paketler::where('id',$paket_id)->first();
        $adisyon_paket = new AdisyonPaketler();
        $adisyon_paket->adisyon_id = $adisyon_id;
        $adisyon_paket->paket_id = $paket_id;
        $adisyon_paket->fiyat = $fiyat;
        $adisyon_paket->baslangic_tarihi = $baslangic_tarihi;
        $adisyon_paket->seans_araligi = $seans_araligi;
        $adisyon_paket->personel_id = $personel_id;
        $adisyon_paket->senet_id = $senet_id;
        $adisyon_paket->seans_sayisi = $seansSayisi;
        $adisyon_paket->kullanilan_seans = 0;
        $adisyon_paket->bekleyen_seans = $seansSayisi;
        $adisyon_paket->kullanilmayan_seans = 0;
        $adisyon_paket->taksitli_tahsilat_id = $taksitli_tahsilat_id;
        if(isset($request->paketRandevuOlustur))
            $adisyon_paket->otomatik_randevu_olusturuldu = true;
        else
            $adisyon_paket->otomatik_randevu_olusturuldu = false;
        $adisyon_paket->save();
        return $adisyon_paket->id;
    }
    public function seansgirdiguncelle(Request $request)
    {
        $seans = AdisyonPaketSeanslar::where('id',$request->id)->first();
        $adisyon_id = AdisyonPaketler::where('id',$seans->adisyon_paket_id)->value('adisyon_id');
        $salon_id = Adisyonlar::where('id',$adisyon_id)->value('salon_id');
        if(isset($request->tarih))
            $seans->seans_tarih = $request->tarih;
        if(isset($request->hizmet))
            $seans->hizmet_id = $request->hizmet;
        if(isset($request->personelcihaz)){
            if(str_contains($request->personelcihaz,'cihaz'))
            {
                $str = explode('-',$request->personelcihaz);
                $seans->cihaz_id = $str[1];
                $seans->personel_id = null;
            }
            else{
                $seans->personel_id = $request->personelcihaz;
                $seans->cihaz_id = null;
            }
        }
        if(isset($request->geldi)){
            $dogrulama_kodu_ayari = SalonSMSAyarlari::where('salon_id',$salon_id)->where('ayar_id',16)->value('musteri');
            if(($dogrulama_kodu_ayari &&$request->geldi==1 && $request->dogrulama_kodu == $seans->dogrulama_kodu)||(!$dogrulama_kodu_ayari || $request->geldi!==1)){
                if($request->geldi == 2)
                    $seans->geldi = null;
                else
                    $seans->geldi = $request->geldi;
            }
            else{
                if($request->dogrulama_kodu != $seans->dogrulama_kodu){
                    return 'hatalikod';
                    exit;
                }
            }
        }
        if(isset($request->oda))
            $seans->oda_id = $request->oda;
        $seans->save();
        if($request->seans_sayfa=='true'){
            return self::guncellemesonrasiseansdetaygetir($request,$seans->adisyon_paket_id,$request->musteri_id);
            exit;
        }
        else
        {
            return self::adisyon_paket_satis_getir($adisyon_id,true,$seans->adisyon_paket_id);
            exit;
        }
    }
    public function senetekleguncelle(Request $request)
    {
        if($r = self::satisYetkiYoksa403($request, 'satis.senet_olustur')) return $r;
        $adisyon_id = '';
        if(isset($request->adisyon_id)){
            $adisyon_id = Adisyonlar::where('id',$request->adisyon_id)->first();
            AdisyonHizmetler::where('adisyon_id',$adisyon_id)->delete();
            AdisyonUrunler::where('adisyon_id',$adisyon_id)->delete();
            $adisyon_paketler = AdisyonPaketler::where('adisyon_id',$adisyon_id)->get();
            foreach($adisyon_paketler as $adisyon_paket)
            {
                AdisyonPaketSeanslar::where('adisyon_paket_id',$adisyon_paket->id)->delete();
            }
            AdisyonPaketler::where('adisyon_id',$adisyon_id)->delete();
            $eskitahsilatlar = Tahsilatlar::where('adisyon_id',$adisyon_id)->get();
            foreach($eskitahsilatlar as $tahsilat)
            {
                TahsilatHizmetler::where('tahsilat_id',$tahsilat->id)->delete();
                TahsilatUrunler::where('tahsilat_id',$tahsilat->id)->delete();
                TahsilatPaketler::where('tahsilat_id',$tahsilat->id)->delete();
            }
            Tahsilatlar::where('adisyon_id',$adisyon_id)->delete();
        }
        else
            $adisyon_id = self::yeni_adisyon_olustur($request->ad_soyad,$request->sube,'Senetle Ödeme',date('Y-m-d'));
        $on_odeme_tutari = str_replace(['.',','],
        ['','.'],$request->on_odeme_tutari); $on_odeme_var  = false; if
        ($on_odeme_tutari != 0) $on_odeme_var  = true; $tahsilat = '';
        if($on_odeme_var)
        {
            $tahsilat = new Tahsilatlar();
            $tahsilat->adisyon_id = $adisyon_id;
            $tahsilat->user_id = $request->ad_soyad;
            $tahsilat->tutar = $on_odeme_tutari;
            $tahsilat->odeme_tarihi = date('Y-m-d');
            $tahsilat->olusturan_id = Personeller::where('salon_id',$request->sube)->where('yetkili_id',Auth::guard('isletmeyonetim')->user()->id)->value('id');
            $tahsilat->salon_id = $request->sube;
            $tahsilat->yapilan_odeme = $on_odeme_tutari;
            $tahsilat->odeme_yontemi_id = $request->on_odeme_turu;
            $tahsilat->save();
        }
        Alacaklar::where('adisyon_id',$adisyon_id)->delete();
        $senet = '';
        if(is_numeric($request->senet_id))
            $senet = Senetler::where('id',$request->senet_id)->first();
        else
            $senet = new Senetler();
        $musteri = User::where('id',$request->ad_soyad)->first();
        $musteri->tc_kimlik_no = $request->tc_kimlik_no;
        $musteri->adres = $request->adres;
        $musteri->save();
        $senet->kefil_adi = $request->kefil_adi;
        $senet->kefil_adres = $request->kefil_adres;
        $senet->kefil_tc_vergi_no = $request->kefil_tc_vergi_no;
        $senet->user_id = $request->ad_soyad;
        $senet->adisyon_id = $adisyon_id;
        $senet->vade_sayisi = $request->vade;
        $senet->salon_id = $request->sube;
        $senet->olusturan_id = Auth::guard('isletmeyonetim')->user()->id;
        $senet->senet_turu = $request->senet_turu;
        $senet->save();
        if(isset($request->senet_hizmet_id)){
            foreach($request->senet_hizmet_id as $key => $hizmet){
                $adisyon_hizmet_id = self::adisyon_hizmet_ekle(
                    $adisyon_id,
                    $hizmet,$request->senet_hizmet_tarih[$key],
                    $request->senet_hizmet_saat[$key],
                    $request->senet_hizmet_sure[$key],
                    $request->senet_hizmet_fiyat[$key],
                    false,
                    $request->senet_hizmet_personel[$key],
                    $request->senet_hizmet_personel[$key],
                    $senet->id,
                    null,
                    null,
                    null
                );
                if($on_odeme_var)
                {
                    $odeme = new TahsilatHizmetler();
                    $odeme->adisyon_hizmet_id = $adisyon_hizmet_id;
                    $odeme->tahsilat_id = $tahsilat->id;
                    $odeme->tutar = round(
                                str_replace(['.',','],['','.'],$request->senet_hizmet_fiyat[$key])
                                /($on_odeme_tutari+str_replace(['.',','],['','.'],$request->senet_tutar))*$on_odeme_tutari,2
                            );
                    $odeme->save();
                }
            }
        }
        if(isset($request->urun_id_senet)){
            foreach($request->urun_id_senet as $key => $urun)
            {
                $adisyon_urun = new AdisyonUrunler();
                $adisyon_urun->islem_tarihi = date('Y-m-d');
                $adisyon_urun->adisyon_id= $adisyon_id;
                $adisyon_urun->urun_id = $urun;
                $adisyon_urun->adet = $request->urun_adet_senet[$key];
                $adisyon_urun->fiyat = $request->urun_fiyat_senet[$key];
                $adisyon_urun->personel_id = $request->urun_satan_senet[$key];
                $adisyon_urun->senet_id = $senet->id;
                $adisyon_urun->save();
                if($on_odeme_var)
                {
                    $odeme = new TahsilatUrunler();
                    $odeme->adisyon_urun_id = $adisyon_urun->id;
                    $odeme->tahsilat_id = $tahsilat->id;
                    $odeme->aciklama = "round((str_replace(['.',','],['','.'],".$request->urun_fiyat_senet[$key].")/(str_replace(['.',','],['','.'],".$on_odeme_tutari.")+str_replace(['.',','],['','.'],".$request->senet_tutar.")))*str_replace(['.',','],['','.'],".$on_odeme_tutari.") ,2 )";
$odeme->tutar = round((str_replace(['.',','],['','.'],$request->urun_fiyat_senet[$key])/($on_odeme_tutari+str_replace(['.',','],['','.'],$request->senet_tutar)))*$on_odeme_tutari ,2 );
                    $odeme->save();
                }
            }
        }
        if(isset($request->paket_id_senet))
        {
            foreach($request->paket_id_senet as $key=>$paket){
                $adisyon_paket_id = self::adisyona_paket_ekle(
                    $request,
                    $adisyon_id,
                    $paket,
                    $request->paket_fiyat_senet[$key],
                    $request->paket_baslangic_tarihi_senet[$key],
                    $request->paket_seans_aralik_gun_senet[$key],
                    $request->paket_satan_senet[$key],
                    $senet->id,
                    null,0);
                $seanstarih = $request->paket_baslangic_tarihi_senet[$key];
                $paket = Paketler::where('id',$paket)->first();
                $toplam_seans_sayilari = $paket->hizmetler->sum('seans');
                for($i=1;$i<=$toplam_seans_sayilari;$i++)
                {
                        if($i>1)
                            $seanstarih = date('Y-m-d',strtotime('+'.$request->paket_seans_aralik_gun_senet[$key].' days',strtotime($seanstarih)));
                        $seans = new AdisyonPaketSeanslar();
                        $seans->adisyon_paket_id = $adisyon_paket_id;
                        $seans->seans_tarih = $seanstarih;
                        $seans->save();
                }
                if($on_odeme_var)
                {
                    $odeme = new TahsilatPaketler();
                    $odeme->adisyon_paket_id = $adisyon_paket_id;
                    $odeme->tahsilat_id = $tahsilat->id;
                    $odeme->tutar = round(
                                str_replace(['.',','],['','.'],$request->paket_fiyat_senet[$key])
                                /($on_odeme_tutari+str_replace(['.',','],['','.'],$request->senet_tutar))*$on_odeme_tutari,2
                    );
                    $odeme->save();
                }
            }
        }
        $vadeler = SenetVadeleri::where('senet_id',$senet->id)->delete();
        $vade_tarihi = $request->vade_baslangic_tarihi;
        $tutar = str_replace(['.',','],['','.'],$request->senet_tutar)/$request->vade;
        for($i=1;$i<=$request->vade;$i++){
            $yeni_vadeler = new SenetVadeleri();
            $yeni_vadeler->senet_id = $senet->id;
            if($i==1)
                $yeni_vadeler->vade_tarih = $request->vade_baslangic_tarihi;
            else{
                $vade_tarihi = date("Y-m-d", strtotime("+1 month", strtotime($vade_tarihi)));
                $yeni_vadeler->vade_tarih = $vade_tarihi;
            }
            $yeni_vadeler->odendi = false;
            $yeni_vadeler->tutar = number_format($tutar,2,'.','');
            $yeni_vadeler->save();
            $alacak = new Alacaklar();
            $alacak->adisyon_id= $adisyon_id;
            $alacak->salon_id = $request->sube;
            $alacak->tutar = $yeni_vadeler->tutar;
            $alacak->planlanan_odeme_tarihi = $yeni_vadeler->vade_tarih;
            $alacak->olusturan_id = Auth::guard('isletmeyonetim')->user()->id;
            $alacak->user_id = $musteri->id;
            $alacak->senet_id = $senet->id;
            $alacak->senet_vade_id = $yeni_vadeler->id;
            $alacak->save();
        }
        /*self::sms_gonder_bildirimli($request,array(array("to"=>$senet->musteri->cep_telefon,"message"=>date('d.m.Y',strtotime($request->vade_baslangic_tarihi))." vade başlangıç tarihli ve tutarı ".number_format(str_replace(['.',','],['','.'],$request->senet_tutar),2,',','.')." TL olan ".$request->vade. " adet vadeden oluşan senediniz oluşturulmuştur. Detaylı bilgi için bize ulaşın. 0".$senet->salon->telefon_1 )),false,1,false);
        $yetkili_liste = self::yetkili_telefonlari($request);
        foreach($yetkili_liste as $_yetkili)
        {
            self::sms_gonder_bildirimli($request,array(array("to"=>$_yetkili,"message"=>$senet->musteri->name." isimli müşteri için ".Auth::guard('isletmeyonetim')->user()->name .' tarafından '.date('d.m.Y',strtotime($request->vade_baslangic_tarihi))." vade başlangıç tarihli ve tutarı ".number_format(str_replace(['.',','],['','.'],$request->senet_tutar),2,',','.')." TL olan ".$request->vade. " adet vadeden oluşan senet oluşturulmuştur.")),false,1,false);
        }*/
        return array(
            'senet_id' => $senet->id,
            'senetler'=>self::senetleri_getir($request,'',''),
            'senetler_acik'=>self::senetleri_getir($request,0,''),
            'senetler_kapali'=>self::senetleri_getir($request,1,''),
            'senetler_odenmemis'=>self::senetleri_getir($request,2,''),
            'adisyon_id' => $adisyon_id
        );
    }
    public function taksitekleguncelle(Request $request)
    {
        if($r = self::satisYetkiYoksa403($request, 'satis.senet_olustur')) return $r;
        if(isset($request->senet_vade_id))
            foreach($request->senet_vade_id as $senetvadesi)
                Alacaklar::where('senet_vade_id',$senetvadesi)->delete();
        if(isset($request->taksit_vade_id))
            foreach($request->taksit_vade_id as $taksitvadesi)
                Alacaklar::where('taksit_vade_id',$taksitvadesi)->delete();
        $taksitlitahsilat = '';
        if(is_numeric($request->taksitli_tahsilat_id))
            $taksitlitahsilat = TaksitliTahsilatlar::where('id',$request->taksitli_tahsilat_id)->first();
        else
            $taksitlitahsilat = new TaksitliTahsilatlar();
        $musteri = User::where('id',$request->tahsilat_musteri_id)->first();
        $taksitlitahsilat->user_id = $request->tahsilat_musteri_id;
        if(isset($request->adisyon_id))
            $taksitlitahsilat->adisyon_id = $request->adisyon_id;
        $taksitlitahsilat->vade_sayisi = $request->vade;
        $taksitlitahsilat->salon_id = $request->sube;
        $taksitlitahsilat->olusturan_id = Auth::guard('isletmeyonetim')->user()->id;
        $taksitlitahsilat->save();
        $vadeler = TaksitVadeleri::where('taksitli_tahsilat_id',$taksitlitahsilat->id)->delete();
        $vade_tarihi = $request->vade_baslangic_tarihi;
        $tutar = str_replace(['.',','],['','.'],$request->taksit_tutar)/$request->vade;
        for($i=1;$i<=$request->vade;$i++){
            $yeni_vadeler = new TaksitVadeleri();
            $yeni_vadeler->taksitli_tahsilat_id = $taksitlitahsilat->id;
            if($i==1)
                $yeni_vadeler->vade_tarih = $request->vade_baslangic_tarihi;
            else{
                $vade_tarihi = date("Y-m-d", strtotime("+1 month", strtotime($vade_tarihi)));
                $yeni_vadeler->vade_tarih = $vade_tarihi;
            }
            $yeni_vadeler->odendi = false;
            $yeni_vadeler->tutar = number_format($tutar,2,'.','');
            $yeni_vadeler->save();
            $alacak = new Alacaklar();
            $alacak->adisyon_id= $request->adisyon_id;
            $alacak->salon_id = $request->sube;
            $alacak->tutar = $yeni_vadeler->tutar;
            $alacak->taksitli_tahsilat_id = $taksitlitahsilat->id;
            $alacak->taksit_vade_id= $yeni_vadeler->id;
            $alacak->planlanan_odeme_tarihi = $yeni_vadeler->vade_tarih;
            $alacak->olusturan_id = Auth::guard('isletmeyonetim')->user()->id;
            $alacak->user_id = $musteri->id;
            $alacak->save();
        }
        $hizmet_kalem_sayisi = isset($request->adisyon_hizmet_id) ? AdisyonHizmetler::whereIn('id',$request->adisyon_hizmet_id)->count() : 0;
        $urun_kalem_sayisi = isset($request->adisyon_urun_id) ? AdisyonUrunler::whereIn('id',$request->adisyon_urun_id)->count() : 0;
        $paket_kalem_sayisi = isset($request->adisyon_paket_id) ? AdisyonPaketler::whereIn('id',$request->adisyon_paket_id)->count() : 0;
        $kalem_sayisi = $hizmet_kalem_sayisi+$urun_kalem_sayisi+$paket_kalem_sayisi;
        $kalem_basina_indirim_tutari = round((str_replace(['.',','],['','.'],$request->indirim_tutari)+$request->musteri_indirimi)/ $kalem_sayisi,2);
        if(isset($request->adisyon_hizmet_id)){
            foreach($request->adisyon_hizmet_id as $hizmet_id)
            {
                $adisyonhizmet = AdisyonHizmetler::where('id',$hizmet_id)->first();
                if($adisyonhizmet->senet_id === null && $adisyonhizmet->taksitli_tahsilat_id === null)
                    $adisyonhizmet->taksitli_tahsilat_id = $taksitlitahsilat->id;
                if($adisyonhizmet->indirim_tutari === null)
                    $adisyonhizmet->indirim_tutari = $kalem_basina_indirim_tutari;
                $adisyonhizmet->save();
            }
        }
        if(isset($request->adisyon_urun_id)){
            foreach($request->adisyon_urun_id as $urun_id)
            {
                $adisyonurun = AdisyonUrunler::where('id',$urun_id)->first();
                if($adisyonurun->senet_id === null && $adisyonurun->taksitli_tahsilat_id === null)
                    $adisyonurun->taksitli_tahsilat_id = $taksitlitahsilat->id;
                if($adisyonurun->indirim_tutari === null)
                    $adisyonurun->indirim_tutari = $kalem_basina_indirim_tutari;
                $adisyonurun->save();
            }
        }
        if(isset($request->adisyon_paket_id)){
            foreach($request->adisyon_paket_id as $paket_id)
            {
                $adisyonpaket = AdisyonPaketler::where('id',$paket_id)->first();
                if($adisyonpaket->senet_id === null && $adisyonpaket->taksitli_tahsilat_id === null)
                    $adisyonpaket->taksitli_tahsilat_id = $taksitlitahsilat->id;
                if($adisyonpaket->indirim_tutari === null)
                    $adisyonpaket->indirim_tutari = $kalem_basina_indirim_tutari;
                $adisyonpaket->save();
            }
        }
        $onOdemeTutari = str_replace(['.',','],['','.'],$request->onOdemeTutari);
        if($onOdemeTutari > 0)
        {
            // Toplam tahsilat tutarını al
            $toplamTahsilat = str_replace(['.',','],['','.'], $request->indirimli_toplam_tahsilat_tutari);
            
            $tahsilat = new Tahsilatlar();
            if(isset($request->adisyon_id))
                $tahsilat->adisyon_id = $request->adisyon_id;
            $tahsilat->user_id = $request->tahsilat_musteri_id;
            $tahsilat->tutar = $onOdemeTutari;
            $tahsilat->odeme_tarihi = $request->tahsilat_tarihi;
            $tahsilat->olusturan_id = Personeller::where('salon_id',$request->sube)->where('yetkili_id',Auth::guard('isletmeyonetim')->user()->id)->value('id');
            $tahsilat->salon_id = $request->sube;
            $tahsilat->yapilan_odeme = $onOdemeTutari;
            $tahsilat->odeme_yontemi_id = $request->onOdemeTuru;
            $tahsilat->notlar = $request->tahsilat_notlari;
            $tahsilat->save();
            
            if(isset($request->adisyon_hizmet_id) && isset($request->adisyon_hizmet_senet_id) && isset($request->adisyon_hizmet_taksitli_tahsilat_id))
            {
                foreach($request->adisyon_hizmet_id as $key=>$hizmet_id)
                {
                    if($request->adisyon_hizmet_senet_id[$key] == '' && $request->adisyon_hizmet_taksitli_tahsilat_id[$key] == '')
                    {
                        $kalemNetTutar = str_replace(['.',','],['','.'], $request->himzet_tahsilat_tutari_girilen[$key] ?? '0') - $kalem_basina_indirim_tutari;
                        $odeme = new TahsilatHizmetler();
                        $odeme->adisyon_hizmet_id = $hizmet_id;
                        $odeme->tahsilat_id = $tahsilat->id;
                        $odeme->tutar = ($kalemNetTutar / $toplamTahsilat) * $onOdemeTutari;
                        $odeme->aciklama = null;
                        $odeme->save();
                    }
                }
            }
            
            // Ürünler ve paketler için de aynı mantık uygulanmalı
            if(isset($request->adisyon_urun_id) && isset($request->adisyon_urun_senet_id) && isset($request->adisyon_urun_taksitli_tahsilat_id))
            {
                foreach($request->adisyon_urun_id as $key2=>$urun_id)
                {
                    if($request->adisyon_urun_senet_id[$key2] == '' && $request->adisyon_urun_taksitli_tahsilat_id[$key2] == '')
                    {
                        $kalemNetTutar = str_replace(['.',','],['','.'], $request->urun_tahsilat_tutari_girilen[$key2] ?? '0') - $kalem_basina_indirim_tutari;
                        $odeme = new TahsilatUrunler();
                        $odeme->adisyon_urun_id = $urun_id;
                        $odeme->tahsilat_id = $tahsilat->id;
                        $odeme->tutar = ($kalemNetTutar / $toplamTahsilat) * $onOdemeTutari;
                        $odeme->aciklama = null;
                        $odeme->save();
                    }
                }
            }
             if(isset($request->adisyon_paket_id) && isset($request->adisyon_paket_senet_id) && isset($request->adisyon_paket_taksitli_tahsilat_id))
            {
                foreach($request->adisyon_paket_id as $key2=>$paket_id)
                {
                    if($request->adisyon_paket_senet_id[$key2] == '' && $request->adisyon_paket_taksitli_tahsilat_id[$key2] == '')
                    {
                        $kalemNetTutar = str_replace(['.',','],['','.'], $request->paket_tahsilat_tutari_girilen[$key2] ?? '0') - $kalem_basina_indirim_tutari;
                        $odeme = new TahsilatPaketler();
                        $odeme->adisyon_paket_id = $paket_id;
                        $odeme->tahsilat_id = $tahsilat->id;
                        $odeme->tutar = ($kalemNetTutar / $toplamTahsilat) * $onOdemeTutari;
                        $odeme->aciklama = null;
                        $odeme->save();
                    }
                }
            }
            
            
            // Paketler için de aynı şekilde düzeltin
        }
        /*self::sms_gonder_bildirimli($request,array(array("to"=>$senet->musteri->cep_telefon,"message"=>date('d.m.Y',strtotime($request->vade_baslangic_tarihi))." vade başlangıç tarihli ve tutarı ".number_format($request->senet_tutar,2,',','.')." TL olan ".$request->vade. " adet vadeden oluşan senediniz oluşturulmuştur. Detaylı bilgi için bize ulaşın. 0".$senet->salon->telefon_1 )),false,1,false);
        $yetkili_liste = self::yetkili_telefonlari($request);
        foreach($yetkili_liste as $_yetkili)
        {
            self::sms_gonder_bildirimli($request,array(array("to"=>$_yetkili,"message"=>$senet->musteri->name." isimli müşteri için ".Auth::guard('isletmeyonetim')->user()->name .' tarafından '.date('d.m.Y',strtotime($request->vade_baslangic_tarihi))." vade başlangıç tarihli ve tutarı ".number_format($request->senet_tutar,2,',','.')." TL olan ".$request->vade. " adet vadeden oluşan senet oluşturulmuştur.")),false,1,false);
        }*/
        try {
            SalonAudit::log($request->sube, is_numeric($request->taksitli_tahsilat_id) ? 'taksit_guncelle' : 'taksit_olustur', 'taksitli_tahsilat', optional($taksitlitahsilat)->id, 'Vade: ' . ($request->vade ?? '') . ' - Tutar: ' . ($request->taksit_tutar ?? ''), is_numeric($request->taksitli_tahsilat_id) ? 'Taksitli tahsilat güncellendi' : 'Taksitli tahsilat oluşturuldu', ['adisyon_id' => $request->adisyon_id]);
        } catch (\Throwable $e) {}
        return self::musteri_tahsilatlari($request,$musteri->id,$request->adisyon_id,false);
        exit;
    }
    public function kampanya_yonetimi_liste(Request $request){
        $isletmeler = '';
        $isletme='';
        if(Auth::guard('satisortakligi')->check())
        {
            $isletmeler = [15];
            $isletme = Salonlar::where('id',15)->first();
        }
        else{
            $isletmeler = Auth::guard('isletmeyonetim')->user()->yetkili_olunan_isletmeler->where('aktif',1)->pluck('salon_id')->toArray();
            $isletme= Salonlar::where('id',self::mevcutsube($request))->first();
        }


        if(!in_array(self::mevcutsube($request),$isletmeler ))
        {
            return view('isletmeadmin.yetkisizerisim');
            exit(0);
        }
        if(str_contains(self::lisans_sure_kontrol($request),'-'))
        {
            return view('isletmeadmin.lisanssurebitti',['isletme'=>$isletme]);
            exit(0);
        }
        // Yetki: bu sayfanin gerektirdigi yetki yoksa 403
        $_authUser = Auth::guard('isletmeyonetim')->user();
        if ($_authUser && !\App\Services\PersonelYetkiServisi::yetkiliYetkiVar($_authUser->id, self::mevcutsube($request), 'pazarlama.kampanya_yonet')) {
            return view('isletmeadmin.yetkisizerisim');
            exit(0);
        }
        if(!Auth::guard('satisortakligi')->check()){
             if(self::personelmi($request, 'pazarlama.kampanya_yonet'))
            {
                    return redirect()->route('isletmeadmin.randevular');
                    exit(0);
            }
        }
       
        if(count($isletmeler)>1 && !isset($_GET['sube']))
        {
            return view('isletmeadmin.isletmesec',['isletmeler'=>$isletmeler,'isletme'=>$isletme]);
            exit(0);    
        }
        $paketler = self::paket_liste_getir('',true,$request);
        $isletme= Salonlar::where('id',self::mevcutsube($request))->first();


        return view('isletmeadmin.kampanya_yonetimi',[ 'paketler'=>$paketler,'pageindex'=>22,'sayfa_baslik'=>'Reklam Yönetimi','isletme'=>$isletme,'bildirimler'=>self::bildirimgetir($request),'kampanya_yonetimi'=>self::paket_kampanyalar($request), 'kalan_uyelik_suresi' => self::lisans_sure_kontrol($request),'urun_drop'=>self::urundropliste($request),
            'yetkiliolunanisletmeler'=>$isletmeler,'gruplar'=>self::grup_sms_liste_getir($request)]);
    }
    public function paket_kampanyalar(Request $request)
{
    return DB::table('kampanya_yonetimi')
        ->leftJoin('kampanya_katilimcilari', 'kampanya_yonetimi.id', '=', 'kampanya_katilimcilari.kampanya_id')
        ->leftJoin('hizmetler', 'kampanya_yonetimi.hizmet_id', '=', 'hizmetler.id')
        ->leftJoin('urunler', 'kampanya_yonetimi.urun_id', '=', 'urunler.id')
        ->select(
            DB::raw('DATE_FORMAT(kampanya_yonetimi.baslangic_tarihi, "%d.%m.%Y") as baslangic_tarihi'),
            DB::raw('DATE_FORMAT(kampanya_yonetimi.bitis_tarihi, "%d.%m.%Y") as bitis_tarihi'),

            DB::raw('CASE
                WHEN kampanya_yonetimi.gorev_turu = 2 THEN DATE_FORMAT(kampanya_yonetimi.sms_tarih_saat, "%H:%i")
                WHEN kampanya_yonetimi.gorev_turu = 1 THEN DATE_FORMAT(kampanya_yonetimi.asistan_tarih_saat, "%H:%i")
                WHEN kampanya_yonetimi.gorev_turu = 3 OR kampanya_yonetimi.gorev_turu = 4 THEN DATE_FORMAT(kampanya_yonetimi.bildirim_tarih_saat, "%H:%i")
                END as arama_saati'),

            'kampanya_yonetimi.indirim_turu as indirim_turu',
            'kampanya_yonetimi.musteri_turu as musteri_turu',

            DB::raw('CONCAT(COALESCE(hizmetler.hizmet_adi, ""), COALESCE(urunler.urun_adi, "")) as hizmet_adi'),

            DB::raw('CASE
                WHEN kampanya_yonetimi.gorev_turu = 2 THEN "SMS"
                WHEN kampanya_yonetimi.gorev_turu = 1 THEN "Arama"
                WHEN kampanya_yonetimi.gorev_turu = 3 THEN "Bildirim"
                WHEN kampanya_yonetimi.gorev_turu = 4 THEN "Bilgilendirme"
                WHEN kampanya_yonetimi.gorev_turu IS NULL THEN ""
                END as gorev_turu'),

            'kampanya_yonetimi.paket_isim as kampanya',
            'kampanya_yonetimi.seans as seans',

            DB::raw("CONCAT(FORMAT(kampanya_yonetimi.fiyat, 2, 'tr_TR'), ' ₺') as fiyat"),

            DB::raw('COUNT(kampanya_yonetimi.id) as katilimci_sayisi'),

            DB::raw('CONCAT(
                "<div class=\"dropdown\">
                    <a class=\"btn btn-link font-24 p-0 line-height-1 no-arrow dropdown-toggle\"
                      href=\"#\"
                      role=\"button\"
                      data-toggle=\"dropdown\">
                        <i class=\"dw dw-more\"></i>
                    </a>
                    <div class=\"dropdown-menu dropdown-menu-right dropdown-menu-icon-list\">
                        <a class=\"dropdown-item\" href=\"#\" data-toggle=\"modal\" name=\"kampanya_detay\" data-target=\"#kampanya_detay_modal\" data-value=\"", kampanya_yonetimi.id, "\">
                            <i class=\"fa fa-eye\"></i> Reklam Raporu
                        </a>
                        <a class=\"dropdown-item\" href=\"#\" name=\"kampanya_sil\" data-value=\"", kampanya_yonetimi.id, "\" >
                            <i class=\"dw dw-delete-3\"></i> Sil
                        </a>
                    </div>
                </div>") AS islemler'),

            DB::raw('CONCAT(
                "<a title=\"Reklam Raporu\" style=\"color:white; margin-right: 5px;\" data-toggle=\"modal\" name=\"kampanya_detay\" data-target=\"#kampanya_detay_modal\" data-value=\"", kampanya_yonetimi.id, "\" class=\"btn btn-primary btn-sm\">
                    <i class=\"fa fa-eye\"></i>
                </a>
                <a title=\"Sil\" style=\"color:white;\" href=\"#\" name=\"kampanya_sil\" data-value=\"", kampanya_yonetimi.id, "\"  class=\"btn btn-danger btn-sm\">
                    <i class=\"fa fa-trash\"></i>
                </a>") as islemler_buton')
        )
        ->where('kampanya_yonetimi.salon_id', self::mevcutsube($request))
        ->groupBy('kampanya_yonetimi.id')
        ->where('kampanya_yonetimi.aktifmi', true)
        ->get();
}
    public function kampanyadetay(Request $request)
    {
    $kampanyaId = $request->kampanyaid;
    $salonId    = $request->sube;

    $page    = $request->input('page', 1);
    $perPage = $request->input('perPage', 100);
    $search  = trim($request->search ?? '');
    $query = KampanyaKatilimcilari::where('kampanya_id', $kampanyaId);

    if ($request->katilimDurumu == 2) {
        $query->where('indirim_kodu_kullanildi', 1);
    } elseif ($request->katilimDurumu == 3) {
        $query->where('indirim_kodu_kullanildi', 0);
    } elseif ($request->katilimDurumu == 4) {
        $query->whereNull('indirim_kodu_kullanildi');
    }

    if ($search !== '') {
        $query->whereHas('musteri', function ($q) use ($search) {
            $q->where('name', 'like', "%{$search}%");
        });
    }

    $query->join('users', 'users.id', '=', 'kampanya_katilimcilari.user_id')
          ->select('kampanya_katilimcilari.*')
          ->orderBy('users.name', 'asc');

    $query->with('musteri');

    $total = (clone $query)->count();

    $katilimcilar = $query
        ->skip(($page - 1) * $perPage)
        ->take($perPage)
        ->get();

    $katilimcilarDatasi = $katilimcilar->map(function ($item) use ($salonId) {
        $telefon = $item->musteri->cep_telefon ?? '';
        $telefonGizlenmis = $telefon;

        $rol = self::kullaniciRolu(
            request()->sube,
            Auth::guard('isletmeyonetim')->user()->id
        );

        if ($telefonGizlenmis !== '' && $rol == 5) {
            $telefonGizlenmis = self::telefonGizle($telefon);
        }

        if ($item->indirim_kodu_kullanildi === null) {
            $katilimDurumu = '<button class="btn btn-warning btn-sm">Beklemede</button>';
        } elseif ($item->indirim_kodu_kullanildi === 1) {
            $katilimDurumu = '<button class="btn btn-success btn-sm">Kod Kullanıldı</button>';
        } else {
            $katilimDurumu = '<button class="btn btn-danger btn-sm">Kod Kullanılmadı</button>';
        }

        return [
            'id'       => $item->id,
            'ad_soyad' => $item->musteri->name ?? '',
            'telefon'  => $telefonGizlenmis,
            'durum'    => $katilimDurumu,
        ];
    });

    $kampanya = DB::table('kampanya_yonetimi')
        ->join('kampanya_katilimcilari', 'kampanya_yonetimi.id', '=', 'kampanya_katilimcilari.kampanya_id')
        ->leftJoin('hizmetler', 'kampanya_yonetimi.hizmet_id', '=', 'hizmetler.id')
        ->leftJoin('urunler', 'kampanya_yonetimi.urun_id', '=', 'urunler.id')
        ->select(
            DB::raw('COUNT(kampanya_katilimcilari.kampanya_id) as katilimci_sayisi'),
            'kampanya_yonetimi.seans',
            DB::raw('CONCAT(COALESCE(hizmetler.hizmet_adi,""), COALESCE(urunler.urun_adi,"")) as hizmet_adi'),
            DB::raw('CASE
                WHEN kampanya_yonetimi.gorev_turu = 2 THEN "SMS"
                WHEN kampanya_yonetimi.gorev_turu = 1 THEN "Arama"
                ELSE ""
            END as gorev_turu'),
            'kampanya_yonetimi.paket_isim',
            'kampanya_yonetimi.fiyat',
            'kampanya_yonetimi.mesaj as mesaj',
        )
        ->where('kampanya_yonetimi.id', $kampanyaId)
        ->groupBy('kampanya_katilimcilari.kampanya_id')
        ->first();

    return response()->json([
        'kampanya'   => $kampanya,
        'kampanyaid'=> $kampanyaId,
        'data'       => $katilimcilarDatasi,
        'total'      => $total,
        'page'       => $page,
        'perPage'    => $perPage
    ]);
}

