    public function kampanyaekleduzenle(Request $request)
    {
        if($r = self::yetkiYoksa403($request, 'pazarlama.kampanya_yonet')) return $r;
        $gonder = "";
        $kampanya_yonetimi = "";
        $_yeniKampanya = false;
        if(isset($request->kampanya_id))
            $kampanya_yonetimi = KampanyaYonetimi::where('id',$request->kampanya_id)->first();
        else {
            $kampanya_yonetimi = new KampanyaYonetimi();
            $_yeniKampanya = true;
        }
        $hizmetUrunPaket ='';
        if($request->hizmetUrunPaket != '')
        {
            if(str_contains($request->hizmetUrunPaket,'urun'))
            {
                $hupArr = explode('-',$request->hizmetUrunPaket);
                $urunAdi = Urunler::where('id',$hupArr[1])->first();
                $kampanya_yonetimi->paket_isim = $urunAdi->urun_adi;
                $kampanya_yonetimi->urun_id = $urunAdi->id;

            }
            elseif(str_contains($request->hizmetUrunPaket,'hizmet'))
            {
                $hupArr = explode('-',$request->hizmetUrunPaket);
                $hizmetAdi = Hizmetler::where('id',$hupArr[1])->first();
                $kampanya_yonetimi->paket_isim = $hizmetAdi->hizmet_adi;
                $kampanya_yonetimi->hizmet_id = $hizmetAdi->id;

            }
            else
            {
                $paketAdi = Paketler::where('id',$request->hizmetUrunPaket)->first();
                $kampanya_yonetimi->paket_isim = $paketAdi->paket_adi;
                $kampanya_yonetimi->paket_id = $paketAdi->id;
            }
        }


        $kampanya_yonetimi->salon_id = self::mevcutsube($request);

        $kampanya_yonetimi->gorev_turu = $request->gorevTuru;
        if($request->etkinlikRandevuTarihi!='')
            $kampanya_yonetimi->randevu_tarihi = $request->etkinlikRandevuTarihi;

        $kampanya_yonetimi->aktifmi=1;
        $cinsiyet = '';
        $grup = '';
        $tarih = '';
        if($request->katilimciTuru== 'erkekler')
            $cinsiyet = '1';
        else if($request->katilimciTuru=='kadinlar')
            $cinsiyet = '0' ;


        $request->merge([
            'salonId' => $request->sube,
            'filtre' => $request->gelenGelmeyenMusteri ?? '',
            'musteriAdi' => '',
            'cinsiyet' => $cinsiyet,
            'kampanyaYayinlaniyor'=>true,
            'sablonId'=>$request->seciliSablonId,
            'grup'=>$request->musteriGruplari,
        ]);


        $katilimcilar = self::musteriportfoydropliste($request);


        $musteriData = $katilimcilar->getData(true);
        $kampanya_yonetimi->indirim_kodu = $request->kampanyaKodu;


        $kampanyaMetinSMS = self::kampanyaIceriginiGoruntule($request);

        $kampanya_yonetimi->mesaj = $request->gorevTuru==1 ?  preg_replace('/^([^.!?]*[.!?]\s*){2}/u', '', $request->kampanya_sms) : $kampanyaMetinSMS['promptStr'];
        $kampanya_yonetimi->musteri_turu = $musteriData['musteriTuru'];
        $kampanya_yonetimi->baslangic_tarihi = $request->asistan_tarih;
        $kampanya_yonetimi->bitis_tarihi = $request->kampanyaGecerlilikTarihi;
        $indirimTuru = '';
        if($request->gorevTuru != 4 && $request->etkinlikRandevuTarihi == '')
            $kampanya_yonetimi->indirim_turu = $request->indirimTuruYazili;

        $kampanya_yonetimi->randevu_tarihi = $request->etkinlikRandevuTarihi;

        $seciliSablon = KampanyaSablonlari::where('id',$request->seciliSablonId)->first();
        if($seciliSablon)
            $kampanya_yonetimi->paket_isim = $seciliSablon->baslik;


        if($request->gorevTuru == 1)
            $kampanya_yonetimi->arama_ile_gonderim= true;
        if($request->gorevTuru == 2)
            $kampanya_yonetimi->sms_ile_gonderim= true;
        if($request->gorevTuru == 3 || $request->gorevTuru == 4)
            $kampanya_yonetimi->bildirim_ile_gonderim= true;
        $kampanya_yonetimi->asistan_tarih_saat = date('Y-m-d H:i:s', strtotime($request->asistan_tarih." ".$request->asistan_saat));
        $kampanya_yonetimi->sms_tarih_saat = date('Y-m-d H:i:s', strtotime($request->asistan_tarih." ".$request->asistan_saat));
        $kampanya_yonetimi->bildirim_tarih_saat = date('Y-m-d H:i:s', strtotime($request->asistan_tarih." ".$request->asistan_saat));
        $kampanya_yonetimi->save();
        $katilimcilar = KampanyaKatilimcilari::where('id',$kampanya_yonetimi->id)->delete();
        $gsm = array();
        $mesajlar=array();



       $insertData = [];

        $now = now();

        foreach ($musteriData['musteriIdler'] as $katilimci) {
            $insertData[] = [
                'kampanya_id' =>  $kampanya_yonetimi->id,
                'user_id' => $katilimci,
                'indirim_kodu'=>$request->kampanyaKodu,
                'created_at' => $now,
                'updated_at' => $now,
            ];
        }

        $chunks = array_chunk($insertData, 1000);
        foreach ($chunks as $chunk) {
            KampanyaKatilimcilari::insert($chunk);
        }
        $controller = app(\App\Http\Controllers\BildirimController::class);
        $personeller = Personeller::where('salon_id',$kampanya_yonetimi->salon_id)->pluck('id')->toArray();
        $bildirimKimlikleri = BildirimKimlikleri::whereIn('isletme_yetkili_id',$personeller)->whereNotNull('bildirim_id')->where('salon_id',$kampanya_yonetimi->salon_id)->get();

        foreach($bildirimKimlikleri  as $token)
        {
             $data = [
                    'category' => 'reklam',
                    'buttons' => json_encode([  ]),
                    'userInfo'=>'',
                    'salonId'=>$kampanya_yonetimi->salon_id,
                    'bildirimlereGitYonetici'=>"1",
                    'kullaniciRolu'=>Personeller::where('id',$token->isletme_yetkili_id)->value('role_id'),
                    'type'=>'',
            ];
            $controller->bildirimGonder(
                    'app/firebase/randevumcepte-uygulamala-5ff4d-8a85c43832c1.json',
                    $token->bildirim_id,
                    "Yeni Reklam Kampanyası Oluşturma",
                    "Sisteme ".$kampanya_yonetimi->paket_isim." ile ilgili reklam kaydını başarıyla olşturdunuz.",
                    $data,
                     $kampanya_yonetimi->salon_id,
                    null,
                    '/public/yeni_panel/vendors/images/eczane24-icon.jpg',
                    'kampanya',
                    null,
                    null,
                    null,
                    null,
                    $token->isletme_yetkili_id,
                    $kampanya_yonetimi->id,
            );
        }


        // Audit
        SalonAudit::log($kampanya_yonetimi->salon_id, $_yeniKampanya ? 'kampanya_olustur' : 'kampanya_guncelle', 'kampanya', $kampanya_yonetimi->id,
            ($kampanya_yonetimi->paket_isim ?: 'Kampanya').' — '.count($musteriData['musteriIdler']).' kişi',
            $_yeniKampanya ? 'Yeni kampanya/reklam oluşturuldu' : 'Kampanya/reklam güncellendi',
            ['gorev_turu'=>$request->gorevTuru, 'katilimci_sayisi'=>count($musteriData['musteriIdler']), 'kod'=>$request->kampanyaKodu]);

        return array(
          "mesaj" => "Kampanya başarıyla kaydedildi",
          "gonder"=>$gonder,
          "kampanya_yonetimi"=>self::paket_kampanyalar($request)
        );
    }
    public function kampanya_sil(Request $request){
        if($r = self::yetkiYoksa403($request, 'pazarlama.kampanya_yonet')) return $r;
        $_audit_kampanyaAdi = KampanyaYonetimi::where('id',$request->kampanya_id)->value('paket_isim');
        $_audit_salonId = KampanyaYonetimi::where('id',$request->kampanya_id)->value('salon_id') ?: self::mevcutsube($request);
        KampanyaYonetimi::where('id',$request->kampanya_id)->update(['aktifmi'=>false]);
        // Audit
        SalonAudit::log($_audit_salonId, 'kampanya_sil', 'kampanya', $request->kampanya_id,
            $_audit_kampanyaAdi ?: ('Kampanya #'.$request->kampanya_id),
            'Kampanya pasif yapıldı');
        return self::paket_kampanyalar($request);
    }

    // ======================================================================
    // BILDIRIM REKLAMLARI — resimli/tiklanabilir, sade reklam modulu
    // (mevcut kampanya_yonetimi'nden AYRI). SADECE hesap sahibi (role_id=1).
    // ======================================================================

    /**
     * Bildirim Reklamlari erisim kontrolu.
     * TEST ASAMASI: panele giris yapmis herkese acik. Ileride owner/yetki
     * kisiti gerekince burada role_id=1 veya PersonelYetkiServisi kontrolu ekle.
     */
    private function bildirimReklamSahipMi(Request $request)
    {
        return Auth::guard('isletmeyonetim')->check();
    }

    public function bildirim_reklam_liste(Request $request)
    {
        if (!Auth::guard('isletmeyonetim')->check())
            return redirect('/isletmeyonetim/girisyap');

        $isletmeler = Auth::guard('isletmeyonetim')->user()->yetkili_olunan_isletmeler->where('aktif', 1)->pluck('salon_id')->toArray();
        $isletme = Salonlar::where('id', self::mevcutsube($request))->first();

        if (!in_array(self::mevcutsube($request), $isletmeler))
            return view('isletmeadmin.yetkisizerisim');

        // SADECE hesap sahibi gorebilir
        if (!self::bildirimReklamSahipMi($request))
            return view('isletmeadmin.yetkisizerisim');

        if (str_contains(self::lisans_sure_kontrol($request), '-'))
            return view('isletmeadmin.lisanssurebitti', ['isletme' => $isletme]);

        if (count($isletmeler) > 1 && !isset($_GET['sube']))
            return view('isletmeadmin.isletmesec', ['isletmeler' => $isletmeler, 'isletme' => $isletme]);

        $reklamlar = \App\BildirimReklamlari::where('salon_id', self::mevcutsube($request))
            ->orderBy('id', 'desc')->get();

        $hizmetler = \App\SalonHizmetler::where('salon_id', self::mevcutsube($request))->where('aktif', true)->get();

        // "Belirli kişi" hedeflemesi icin salonun musterileri (isim + telefon)
        $musteriler = \DB::table('musteri_portfoy')
            ->join('users', 'users.id', '=', 'musteri_portfoy.user_id')
            ->where('musteri_portfoy.salon_id', self::mevcutsube($request))
            ->where('musteri_portfoy.aktif', 1)
            ->select('users.id', 'users.name', 'users.cep_telefon')
            ->orderBy('users.name')
            ->get();

        return view('isletmeadmin.bildirim_reklamlari', [
            'pageindex'    => 122,
            'sayfa_baslik' => 'Bildirim Reklamları',
            'isletme'      => $isletme,
            'reklamlar'    => $reklamlar,
            'hizmetler'    => $hizmetler,
            // layout_isletmeadmin'in bekledigi ortak degiskenler
            'kalan_uyelik_suresi'     => self::lisans_sure_kontrol($request),
            'bildirimler'             => self::bildirimgetir($request),
            'yetkiliolunanisletmeler' => $isletmeler,
            'paketler'                => self::paket_liste_getir('', true, $request),
            'portfoy_drop'            => self::musteriportfoydropliste($request),
            'urun_drop'               => self::urundropliste($request),
            'hizmet_drop'             => self::hizmetdropliste($request),
            'musteriler'              => $musteriler,
        ]);
    }

    public function bildirim_reklam_kaydet(Request $request)
    {
        if (!self::bildirimReklamSahipMi($request))
            return response()->json(['durum' => 'hata', 'mesaj' => 'Bu islem icin yetkiniz yok.'], 403);

        $salonId = self::mevcutsube($request);

        if (!empty($request->id))
            $reklam = \App\BildirimReklamlari::where('salon_id', $salonId)->where('id', $request->id)->first();
        else
            $reklam = new \App\BildirimReklamlari();

        if (!$reklam)
            return response()->json(['durum' => 'hata', 'mesaj' => 'Reklam bulunamadi.'], 404);

        if (trim((string)$request->baslik) === '')
            return response()->json(['durum' => 'hata', 'mesaj' => 'Baslik zorunlu.'], 422);

        $reklam->salon_id     = $salonId;
        $reklam->baslik       = trim($request->baslik);
        $reklam->mesaj        = $request->mesaj;
        $reklam->tur          = $request->tur ?: 'kampanya';
        $reklam->kanal_push   = filter_var($request->input('kanal_push'), FILTER_VALIDATE_BOOLEAN);
        $reklam->kanal_inapp  = filter_var($request->input('kanal_inapp'), FILTER_VALIDATE_BOOLEAN);
        $reklam->tam_ekran    = filter_var($request->input('tam_ekran'), FILTER_VALIDATE_BOOLEAN);
        $reklam->aksiyon_tipi = $request->aksiyon_tipi ?: 'kupon';
        $reklam->aksiyon_hedef = $request->aksiyon_hedef;

        // En az bir kanal/gosterim secili olmali
        if (!$reklam->kanal_push && !$reklam->kanal_inapp && !$reklam->tam_ekran)
            return response()->json(['durum' => 'hata', 'mesaj' => 'En az bir kanal (Push / Uygulama-ici / Tam ekran) secili olmali.'], 422);

        // Gorsel: ayri base64 endpoint'inden gelen /public/... yolunu formdan al
        if (!empty($request->gorsel))
            $reklam->gorsel = $request->gorsel;

        // Kupon ayarlari: aksiyon 'kupon' VEYA 'randevu' (bos slot indirimi opsiyonel kupon)
        if ($reklam->aksiyon_tipi === 'kupon' || $reklam->aksiyon_tipi === 'randevu') {
            $reklam->kupon_indirim_tipi   = $request->kupon_indirim_tipi ?: 'yuzde';
            $reklam->kupon_deger          = $request->kupon_deger ?: 0;
            $reklam->kupon_hizmet_id      = $request->kupon_hizmet_id ?: null;
            $reklam->kupon_baslik         = $request->kupon_baslik ?: null;
            $reklam->kupon_gecerlilik_gun = ($request->kupon_gecerlilik_gun !== null && $request->kupon_gecerlilik_gun !== '') ? (int)$request->kupon_gecerlilik_gun : null;
            $reklam->kupon_kisi_limit     = $request->kupon_kisi_limit ?: 1;
            $reklam->kupon_toplam_adet    = ($request->kupon_toplam_adet !== null && $request->kupon_toplam_adet !== '') ? (int)$request->kupon_toplam_adet : null;
        }

        // Randevu (bos slot) penceresi: aksiyon 'randevu' ise tarih ARALIGI + saat araligi
        if ($reklam->aksiyon_tipi === 'randevu') {
            $reklam->randevu_tarih     = !empty($request->randevu_tarih) ? $request->randevu_tarih : null;         // baslangic
            $reklam->randevu_tarih_bit = !empty($request->randevu_tarih_bit) ? $request->randevu_tarih_bit : null; // bitis
            $reklam->randevu_saat_bas  = !empty($request->randevu_saat_bas) ? $request->randevu_saat_bas : null;
            $reklam->randevu_saat_bit  = !empty($request->randevu_saat_bit) ? $request->randevu_saat_bit : null;
        } else {
            $reklam->randevu_tarih = null;
            $reklam->randevu_tarih_bit = null;
            $reklam->randevu_saat_bas = null;
            $reklam->randevu_saat_bit = null;
        }

        // Hedef kitle: tumu | segment (+ segment kosulu JSON)
        if ($request->hedef_kitle === 'segment') {
            $reklam->hedef_kitle = 'segment';
            $segTip = in_array($request->segment_tip, ['gelmeyen', 'dogum_gunu', 'hizmet', 'cinsiyet', 'kisi'])
                ? $request->segment_tip : 'gelmeyen';
            $kosul = ['tip' => $segTip];
            if ($segTip === 'gelmeyen')  $kosul['gun'] = (int)($request->segment_gun ?: 60);
            if ($segTip === 'hizmet')    $kosul['hizmet_id'] = (int)($request->segment_hizmet_id ?: 0);
            if ($segTip === 'cinsiyet')  $kosul['cinsiyet'] = ($request->segment_cinsiyet === '1' ? '1' : '0');
            if ($segTip === 'kisi')      $kosul['user_id'] = (int)($request->segment_user_id ?: 0);
            $reklam->hedef_kosul = json_encode($kosul);
        } else {
            $reklam->hedef_kitle = 'tumu';
            $reklam->hedef_kosul = null;
        }

        $reklam->durum = $request->durum ?: 'taslak';
        $reklam->yayin_baslangic = !empty($request->yayin_baslangic) ? $request->yayin_baslangic : null;
        $reklam->yayin_bitis     = !empty($request->yayin_bitis) ? $request->yayin_bitis : null;

        // Çoklu şube: reklam seçilen şube grubuna uygulanır (push o gruba gider, kupon
        // grubu miras alır). Grup YALNIZCA açık seçim varsa veya yeni reklamda yazılır.
        if (\Schema::hasColumn('bildirim_reklamlari', 'gecerli_salonlar')) {
            $secili = \App\Personeller::salonIdListesiCoz($request->input('salon_ids'));
            $yeniMi = empty($request->id);
            if (!empty($secili) || $yeniMi) {
                // Yetki: yalnızca giriş yapanın yetkili olduğu şubeler (yoksa owner grubu).
                $yetkili = $this->yetkiliSubeIdler() ?: \App\Personeller::kardesSalonIdler($salonId);
                $hedef = !empty($secili) ? array_values(array_intersect($secili, $yetkili)) : [(int) $salonId];
                if (empty($hedef)) $hedef = [(int) $salonId];
                $reklam->gecerli_salonlar = json_encode($hedef);
            }
        }

        $reklam->save();

        SalonAudit::log($salonId, !empty($request->id) ? 'bildirim_reklam_guncelle' : 'bildirim_reklam_olustur', 'bildirim_reklam', $reklam->id,
            $reklam->baslik, !empty($request->id) ? 'Bildirim reklami guncellendi' : 'Bildirim reklami olusturuldu');

        return response()->json(['durum' => 'basarili', 'mesaj' => 'Reklam kaydedildi.', 'id' => $reklam->id]);
    }

    /** Base64 gorsel yukle -> /public/reklam_gorselleri/ altina kaydet, yolu don. */
    public function bildirim_reklam_gorsel(Request $request)
    {
        if (!self::bildirimReklamSahipMi($request))
            return response()->json(['durum' => 'hata', 'mesaj' => 'Yetkiniz yok.'], 403);

        $data = $request->input('gorsel');
        if (!$data)
            return response()->json(['durum' => 'hata', 'mesaj' => 'Gorsel yok.'], 422);

        $folderPath = public_path('reklam_gorselleri') . '/';
        if (!is_dir($folderPath)) @mkdir($folderPath, 0755, true);

        $ext = 'jpg';
        if (preg_match('/^data:image\/(\w+);base64,/', $data, $m)) {
            $ext = strtolower($m[1]) === 'jpeg' ? 'jpg' : strtolower($m[1]);
            if (!in_array($ext, ['jpg', 'png', 'webp'])) $ext = 'jpg';
            $data = substr($data, strpos($data, ',') + 1);
        }
        $binary = base64_decode($data);
        if ($binary === false)
            return response()->json(['durum' => 'hata', 'mesaj' => 'Gorsel cozulemedi.'], 422);

        $filename = 'reklam_' . self::mevcutsube($request) . '_' . uniqid() . '.' . $ext;
        file_put_contents($folderPath . $filename, $binary);

        return response()->json(['durum' => 'basarili', 'yol' => '/public/reklam_gorselleri/' . $filename]);
    }

    public function bildirim_reklam_durum(Request $request)
    {
        if (!self::bildirimReklamSahipMi($request))
            return response()->json(['durum' => 'hata', 'mesaj' => 'Yetkiniz yok.'], 403);
        $reklam = \App\BildirimReklamlari::where('salon_id', self::mevcutsube($request))->where('id', $request->id)->first();
        if (!$reklam) return response()->json(['durum' => 'hata', 'mesaj' => 'Bulunamadi.'], 404);
        $yeni = in_array($request->durum, ['aktif', 'pasif', 'taslak', 'bitti']) ? $request->durum : 'pasif';
        $reklam->durum = $yeni;
        $reklam->save();
        return response()->json(['durum' => 'basarili', 'yeni_durum' => $reklam->durum]);
    }

    public function bildirim_reklam_sil(Request $request)
    {
        if (!self::bildirimReklamSahipMi($request))
            return response()->json(['durum' => 'hata', 'mesaj' => 'Yetkiniz yok.'], 403);
        $reklam = \App\BildirimReklamlari::where('salon_id', self::mevcutsube($request))->where('id', $request->id)->first();
        if (!$reklam) return response()->json(['durum' => 'hata', 'mesaj' => 'Bulunamadi.'], 404);
        $baslik = $reklam->baslik;
        $reklam->delete();
        SalonAudit::log(self::mevcutsube($request), 'bildirim_reklam_sil', 'bildirim_reklam', $request->id, $baslik, 'Bildirim reklami silindi');
        return response()->json(['durum' => 'basarili']);
    }

    /** Reklami aktif et + salonun musterilerine push gonder (v1: hedef = tum aktif musteriler). */
    public function bildirim_reklam_gonder(Request $request)
    {
        if (!self::bildirimReklamSahipMi($request))
            return response()->json(['durum' => 'hata', 'mesaj' => 'Yetkiniz yok.'], 403);

        $salonId = self::mevcutsube($request);
        $reklam = \App\BildirimReklamlari::where('salon_id', $salonId)->where('id', $request->id)->first();
        if (!$reklam) return response()->json(['durum' => 'hata', 'mesaj' => 'Bulunamadi.'], 404);

        if (!$reklam->kanal_push)
            return response()->json(['durum' => 'hata', 'mesaj' => 'Bu reklamda Push kanali kapali.'], 422);

        try {
            // Yayina al + gonderim isaretle
            if ($reklam->durum !== 'aktif') $reklam->durum = 'aktif';
            $reklam->push_gonderildi = true;
            $reklam->save();

            // Gercek alici sayisi = hedef kitle ∩ aktif FCM token'i olanlar.
            $alicilar = \App\Jobs\BildirimReklamGonderJob::alicilar($reklam);
            $hedefMetin = $reklam->hedef_kitle === 'segment' ? 'segment' : 'tum musteriler';

            if (empty($alicilar)) {
                SalonAudit::log($salonId, 'bildirim_reklam_gonder', 'bildirim_reklam', $reklam->id,
                    $reklam->baslik, 'Alici bulunamadi (hedef: ' . $hedefMetin . ')');
                return response()->json([
                    'durum' => 'basarili',
                    'gonderilen' => 0,
                    'mesaj' => 'Gönderildi ama alıcı bulunamadı. Seçtiğin kişi uygulamaya giriş yapmış ve bildirime izin vermiş olmalı (FCM token yoksa push gidemez).',
                ]);
            }

            // Her alici icin FCM'e ayri HTTP istegi gidiyor (~0.3-1 sn). Kalabalik
            // gonderimi web istegi icinde yaparsak PHP-FPM/nginx zaman asimina
            // ugrar ve kullaniciya 500 doner. Bu yuzden esik ustunde KUYRUGA
            // atiyoruz (prod worker 'hatirlatmalar' kuyrugunu dinliyor).
            if (count($alicilar) > 100 && config('queue.default') !== 'sync') {
                \App\Jobs\BildirimReklamGonderJob::dispatch($reklam->id);
                SalonAudit::log($salonId, 'bildirim_reklam_gonder', 'bildirim_reklam', $reklam->id,
                    $reklam->baslik, count($alicilar) . ' kisiye push kuyruga alindi (hedef: ' . $hedefMetin . ')');
                return response()->json([
                    'durum' => 'basarili',
                    'gonderilen' => count($alicilar),
                    'kuyruk' => true,
                    'mesaj' => count($alicilar) . ' kişiye gönderim arka planda başlatıldı. Birkaç dakika içinde tamamlanır.',
                ]);
            }

            // Kucuk gonderim: aninda gonder, sonucu hemen dondur.
            // dispatchNow() DEGIL, dogrudan handle(): boylece Bus dispatcher
            // baglantisina hic ihtiyac duymadan calisir (bkz. config/app.php'de
            // BusServiceProvider notu — kapali kaldiginda dispatchNow patliyordu).
            @set_time_limit(0);
            $gonderilen = (int) (new \App\Jobs\BildirimReklamGonderJob($reklam->id))->handle();

            SalonAudit::log($salonId, 'bildirim_reklam_gonder', 'bildirim_reklam', $reklam->id,
                $reklam->baslik, $gonderilen . ' kisiye push gonderildi (hedef: ' . $hedefMetin . ')');

            return response()->json([
                'durum' => 'basarili',
                'gonderilen' => $gonderilen,
                'mesaj' => $gonderilen > 0
                    ? ($gonderilen . ' kişiye push gönderildi.')
                    : 'Gönderildi ama alıcı bulunamadı. Seçtiğin kişi uygulamaya giriş yapmış ve bildirime izin vermiş olmalı (FCM token yoksa push gidemez).',
            ]);
        } catch (\Throwable $e) {
            // Ciplak 500 yerine sebebi panelde goster (APP_DEBUG=false oldugu icin
            // aksi halde kullaniciya hicbir ipucu ulasmiyordu).
            \Log::error('[REKLAM-PUSH] gonderim hatasi', [
                'reklam_id' => $reklam->id,
                'salon_id'  => $salonId,
                'err'       => $e->getMessage(),
                'yer'       => $e->getFile() . ':' . $e->getLine(),
            ]);
            return response()->json([
                'durum' => 'hata',
                'mesaj' => 'Gönderim hatası: ' . $e->getMessage(),
            ], 500);
        }
    }

    public function kampanyakatilimcisil(Request $request){
        try {
            $katilimci = KampanyaKatilimcilari::where('id', $request->id)->first();
            if (!$katilimci) {
                return response()->json(['success' => false, 'message' => 'Katılımcı bulunamadı.']);
            }
            $_audit_salonId = KampanyaYonetimi::where('id',$katilimci->kampanya_id)->value('salon_id');
            $_audit_musteriAdi = \App\User::where('id',$katilimci->user_id)->value('name');
            $katilimci->delete();
            // Audit
            if ($_audit_salonId) {
                SalonAudit::log($_audit_salonId, 'kampanya_katilimci_sil', 'kampanya_katilimci', $request->id,
                    ($_audit_musteriAdi ?: 'Müşteri #'.$katilimci->user_id),
                    'Kampanyadan katılımcı çıkarıldı',
                    ['kampanya_id'=>$katilimci->kampanya_id]);
            }
            return response()->json(['success' => true, 'message' => 'Katılımcı başarıyla silindi.']);
        } catch (\Exception $e) {
            return response()->json(['success' => false, 'message' => 'Silme işlemi sırasında bir hata oluştu: ' . $e->getMessage()]);
        }
    }
    public function kampanyakatilimciekle(Request $request)
    {
        try {
            $request->validate(['kampanyaid' => 'required|integer', 'musteriid' => 'required|integer']);
            $mevcutKatilimci = KampanyaKatilimcilari::where('kampanya_id', $request->kampanyaid)
                ->where('user_id', $request->musteriid)->first();
            if ($mevcutKatilimci) {
                return response()->json(['success' => false, 'message' => 'Bu müşteri zaten kampanyaya kayıtlıdır.', 'type' => 'warning']);
            }
            $ilkKatilimci = KampanyaKatilimcilari::where('kampanya_id', $request->kampanyaid)->first();
            if (!$ilkKatilimci) {
                return response()->json(['success' => false, 'message' => 'Kampanya bulunamadı veya geçersiz.', 'type' => 'error']);
            }
            $katilimci = new KampanyaKatilimcilari();
            $katilimci->kampanya_id = $request->kampanyaid;
            $katilimci->user_id = $request->musteriid;
            $katilimci->indirim_kodu = $ilkKatilimci->indirim_kodu;
            if ($request->has('durum')) {
                $katilimci->durum = $request->durum;
            }
            $katilimci->save();
            // Audit
            $_audit_salonId = KampanyaYonetimi::where('id',$request->kampanyaid)->value('salon_id') ?: self::mevcutsube($request);
            $_audit_musteriAdi = \App\User::where('id',$request->musteriid)->value('name');
            SalonAudit::log($_audit_salonId, 'kampanya_katilimci_ekle', 'kampanya_katilimci', $katilimci->id,
                ($_audit_musteriAdi ?: 'Müşteri #'.$request->musteriid),
                'Kampanyaya katılımcı eklendi',
                ['kampanya_id'=>$request->kampanyaid]);
            return response()->json([
                'success' => true, 'message' => 'Katılımcı başarıyla eklendi.', 'type' => 'success',
                'data' => ['id' => $katilimci->id, 'ad_soyad' => $katilimci->musteri->name ?? 'Müşteri', 'telefon' => $katilimci->musteri->cep_telefon ?? '']
            ]);
        } catch (\Exception $e) {
            return response()->json(['success' => false, 'message' => 'Katılımcı eklenirken bir hata oluştu: ' . $e->getMessage(), 'type' => 'error']);
        }
    }
    public function etkinlik_sil(Request $request){
        $_audit_etkinlikAdi = Etkinlikler::where('id',$request->etkinlik_id)->value('etkinlik_adi') ?? '';
        $_audit_salonId = Etkinlikler::where('id',$request->etkinlik_id)->value('salon_id') ?: self::mevcutsube($request);
        Etkinlikler::where('id',$request->etkinlik_id)->update(['aktifmi'=>false]);
        // Audit
        SalonAudit::log($_audit_salonId, 'etkinlik_sil', 'etkinlik', $request->etkinlik_id,
            $_audit_etkinlikAdi ?: ('Etkinlik #'.$request->etkinlik_id),
            'Etkinlik pasif yapıldı');
        return self::etkinlikyukle($request);
    }
    public function seanstanrandevuolustur(Request $request)
    {
        $adisyon = Adisyonlar::where('id',$request->adisyonid)->first();
        $randevu = new Randevular();
        $randevu->user_id = $adisyon->user_id;
        $randevu->salon_id = $adisyon->salon_id;
        $tarih = explode(' ',$request->tarih_saat);
        $randevu->tarih = $request->tarih;
        $randevu->saat = $request->saat;
        $randevu->salon = true;
        $randevu->sms_hatirlatma = true;
        $randevu->seans_id = $request->seansid;
        $randevu->durum = 1;
        $randevu->olusturan_personel_id = Auth::guard('isletmeyonetim')->user()->id;
        $randevu->adisyon_paket_uzerinden_olusturma = true;
        $hizmet = Hizmetler::where('id',$request->hizmetid)->value('hizmet_adi');
        $randevu->save();
        $yenirandevuhizmetpersonel = new RandevuHizmetler();
        $yenirandevuhizmetpersonel->randevu_id = $randevu->id;
        $yenirandevuhizmetpersonel->hizmet_id = $request->hizmetid;
        if(str_contains($request->personelid,'cihaz'))
        {
                $str = explode('-',$request->personelid);
                $yenirandevuhizmetpersonel->cihaz_id = $str[1];
        }
        else{
                $yenirandevuhizmetpersonel->personel_id = $request->personelid;
        }
        if($request->odaid != '')
            $yenirandevuhizmetpersonel->oda_id = $request->odaid;
        $sure_dk = SalonHizmetler::where('hizmet_id',$request->hizmetid)->where('salon_id',$adisyon->salon_id)->value('sure_dk');
        $yenirandevuhizmetpersonel->sure_dk = $sure_dk;
        $yenirandevuhizmetpersonel->fiyat = SalonHizmetler::where('hizmet_id',$request->hizmetid)->where('salon_id',$adisyon->salon_id)->value('baslangic_fiyat');
        $yenirandevuhizmetpersonel->saat = $request->saat;
        $yenirandevuhizmetpersonel->saat_bitis = date("H:i", strtotime('+'.$sure_dk.' minutes', strtotime($request->saat)));
        $yenirandevuhizmetpersonel->save();
        $seans = AdisyonPaketSeanslar::where('id',$request->seansid)->first();
        $seans->randevu_olusturuldu = true;
        $seans->randevu_id = $randevu->id;
        $seans->save();
        if(SalonSMSAyarlari::where('ayar_id',12)->where('salon_id',$randevu->salon_id)->value('musteri')){
            $mesajlar = array(
                array("to"=>$randevu->users->cep_telefon,"message"=>$randevu->salonlar->salon_adi . " tarafından ".date('d.m.Y',strtotime($randevu->tarih)) .'-'.date('H:i',
                    strtotime($randevu->saat)).' olarak randevunuz oluşturulmuştur. Randevunuza 15 dk önce gelmenizi rica ederiz. Detaylı bilgi için bize ulaşın. 0'.$randevu->salonlar->telefon_1 ),
            );
            self::sms_gonder_bildirimli($request,$mesajlar,false,1,false);
        }
        if(SalonSMSAyarlari::where('ayar_id',12)->where('salon_id',$randevu->salon_id)->value('personel')){
            if(is_numeric($request->personelid)){
                $yetkiliid=Personeller::where('id',$request->personel_id)->value('yetkili_id');
                $gsm = IsletmeYetkilileri::where('id',$yetkiliid)->value('gsm1');
                $mesajlar = array(
                    array("to"=>$gsm,"message"=> $randevu->users->name .' isimli müşterinin '. $hizmet . " için ".date('d.m.Y',strtotime($randevu->tarih)) .'-'.date('H:i',
                        strtotime($randevu->saat)) .' tarihli randevusu oluşturulmuştur.'),
                );
            }
            self::sms_gonder_bildirimli($request,$mesajlar,false,1,false);
            $mesaj = $randevu->users->name .' isimli müşterinin '. $hizmet . " için ".date('d.m.Y',strtotime($randevu->tarih)) .'-'.date('H:i',
                        strtotime($randevu->saat)) .' tarihli randevusu oluşturulmuştur.';
            self::bildirimekle($request,$randevu->salon_id,$mesaj,"#",$request->personel_id,null, Auth::guard('isletmeyonetim')->user()->profil_resim,$randevu->id);
            if($request->personel_id){
                try {
                    NotificationService::toStaff((int)$request->personel_id, (int)$randevu->salon_id)
                        ->type(NotificationTypes::APPOINTMENT_CREATED)
                        ->title('Randevu Oluşturuldu')
                        ->body($mesaj)
                        ->randevu((int)$randevu->id)
                        ->deepLink('appointment_detail', ['randevu_id' => $randevu->id])
                        ->send();
                } catch (\Throwable $e) { \Log::warning('randevu olustu push: '.$e->getMessage()); }
            }
        }
        return self::adisyon_paket_satis_getir($adisyon->id,true,$seans->adisyon_paket_id);
    }
