    public function randevuyagelmedi(Request $request)
    {

        $randevu = Randevular::where('id',$request->randevuid)->first();
        $seansVar = AdisyonPaketSeanslar::where('randevu_id',$randevu->id)->get();
        // NOT: $seansVar Collection'dir; bos olsa bile 'if($seansVar)' TRUE donerdi
        // -> APS'siz randevularda da 'seansdan dusulsun mu?' popup gosteriliyordu.
        // Fix: count > 0 kontrolu (yani gercek paket randevusu ise).
        if($seansVar->count() > 0)
        {


             
            if($request->seansDusumuYap == '1')
            {
                   
                    foreach($seansVar as $seansVar1)
                    {
                        $seansVar1->geldi = false;
                        $seansVar1->save();
                        
                    }
                    foreach($randevu->hizmetler as $randevuHizmet)
                    {
                        $randevuHizmet->seansa_geldi = false;
                        $randevuHizmet->save();
                    }
            }

            
            else if($request->seansDusumuYap=='')
            {
                $hizmetler = '';
                foreach($seansVar as $key=>$seans)
                {
                    $hizmetler.= $seans->hizmet->hizmet_adi;
                    if($key < $seansVar->count()-2)
                        $hizmetler .= ', ';
                    else
                    {
                        if($key == $seansVar->count()-2)
                            $hizmetler .= ' ve ';
                        
                    }
                }
                return array('mesaj'=>$hizmetler.' seansından düşülsün mü? ', 'seansDusmeOnayi'=>true);
            }
        }

       

        
        $randevu->randevuya_geldi = false;

        $randevu->save();

        // Daha onceden dakika paketinden dusulen miktarlari iade et.
        try {
            app(\App\Services\MusteriDakikaPaketService::class)
                ->randevuGelmediIade($randevu, \Auth::id());
        } catch (\Throwable $e) {
            \Log::warning('[DAKIKA-PAKETI] web iade hook hata', [
                'randevu_id' => $randevu->id,
                'err' => $e->getMessage(),
            ]);
        }

        // Audit
        $_audit_musteriAdi = optional($randevu->users)->name ?? 'Müşteri #'.$randevu->user_id;
        $_audit_label = $_audit_musteriAdi.' — '.date('d.m.Y',strtotime($randevu->tarih)).' '.date('H:i',strtotime($randevu->saat));
        SalonAudit::log($randevu->salon_id, 'randevu_gelmedi', 'randevu', $randevu->id, $_audit_label,
            'Müşteri randevuya gelmedi olarak işaretlendi',
            ['seans_dusumu'=>$request->seansDusumuYap]);

        return array('mesaj'=>'Başarılı');
    }
     public function grupsmsekle(Request $request)
    {
        $grupsms = "";
        if(isset($request->grup_id))
            $grupsms = GrupSms::where('id',$request->grup_id)->first();
        else
            $grupsms = new GrupSms();
        $grupsms->grup_adi = $request->grup_adi;
        $grupsms->salon_id = self::mevcutsube($request);
        $grupsms->aktif_mi = true;
        $grupsms->save();
        $grup_katilimcilar = GrupSmsKatilimcilari::where('grup_id',$grupsms->id)->delete();

        // Yeni format: musteri_idler JSON olarak geliyor
        $musteriIdler = [];
        \Log::info('grupsmsekle request:', $request->all());
        if($request->has('musteri_idler')) {
            $decoded = json_decode($request->musteri_idler, true);
            $musteriIdler = is_array($decoded) ? $decoded : [];
            \Log::info('musteri_idler decoded:', ['count' => count($musteriIdler), 'ids' => array_slice($musteriIdler, 0, 5)]);
        } elseif($request->has('duallistbox_demo1')) {
            $musteriIdler = $request->duallistbox_demo1;
        }

        $insertData = [];
        $now = now();
        foreach($musteriIdler as $grup_katilimci)
        {
            $insertData[] = [
                'grup_id' => $grupsms->id,
                'user_id' => $grup_katilimci,
                'created_at' => $now,
                'updated_at' => $now,
            ];
        }
        $chunks = array_chunk($insertData, 1000);
        foreach ($chunks as $chunk) {
            GrupSmsKatilimcilari::insert($chunk);
        }

        return response()->json([
          'success' => true,
          'mesaj' => 'Grup Başarıyla Oluşturuldu',
          'id' => $grupsms->id,
          'grupAdi' => $grupsms->grup_adi,
          'grup' => self::grup_sms_liste_getir($request)
        ]);
    }
    public function santral_ayar_kaydet(Request $request)
    {
        if(isset($request->santralayar_1_musteri))
            SalonSantralAyarlari::where('salon_id',$request->sube)->where('ayar_id',1)->update(['musteri'=>true]);
        else
            SalonSantralAyarlari::where('salon_id',$request->sube)->where('ayar_id',1)->update(['musteri'=>false]);
        if(isset($request->santralayar_1_personel))
            SalonSantralAyarlari::where('salon_id',$request->sube)->where('ayar_id',1)->update(['personel'=>true]);
        else
            SalonSantralAyarlari::where('salon_id',$request->sube)->where('ayar_id',1)->update(['personel'=>false]);
        $salon = Salonlar::where('id',$request->sube)->first();
        $salon->randevu_cagri_hatirlatma = $request->randevu_hatirlatama_saat_once;
        $salon->save();
        // Audit
        SalonAudit::log($request->sube, 'santral_ayar_kaydet', 'santral_ayar', null,
            'Santral ayarları',
            'Sesli arama / santral ayarları güncellendi',
            ['hatirlatma_saat'=>$request->randevu_hatirlatama_saat_once,
             'musteri'=>isset($request->santralayar_1_musteri)?1:0,
             'personel'=>isset($request->santralayar_1_personel)?1:0]);
        return 'Santral ayarları başarıyla kaydedildi';
    }
