    public function haftanin_gunu($tarih)
    {
        $day = 0;
        if(date('D', strtotime($tarih))=='Mon') $day=1;
        else if(date('D', strtotime($tarih))=='Tue') $day=2;
        else if(date('D', strtotime($tarih))=='Wed') $day=3;
        else if(date('D', strtotime($tarih))=='Thu') $day=4;
        else if(date('D', strtotime($tarih))=='Fri') $day=5;
        else if(date('D', strtotime($tarih))=='Sat') $day=6;
        else if(date('D', strtotime($tarih))=='Sun') $day=7;
        return $day;
    }
   public function grup_sms_liste_getir(Request $request){
        $isletmeId = self::mevcutsube($request);
         $pasifMusteriSayisi = DB::table('musteri_portfoy')
            ->join('users', 'musteri_portfoy.user_id', '=', 'users.id')
            ->where('musteri_portfoy.salon_id', $isletmeId)
            ->where('musteri_portfoy.aktif', true)
            ->whereNotExists(function ($q) use ($isletmeId) {
                $q->select(DB::raw(1))
                    ->from('tahsilatlar')
                    ->whereRaw('tahsilatlar.user_id = users.id')
                    ->where('tahsilatlar.salon_id', $isletmeId);
            })->count();
            
        $aktifMusteriSayisi = DB::table('musteri_portfoy')
            ->join('users', 'musteri_portfoy.user_id', '=', 'users.id')
            ->where('musteri_portfoy.salon_id', $isletmeId)
            ->where('musteri_portfoy.aktif', true)
            ->whereExists(function ($q) use ($isletmeId) {
                $q->select(DB::raw(1))
                    ->from('tahsilatlar')
                    ->whereRaw('tahsilatlar.user_id = users.id')
                    ->where('tahsilatlar.salon_id', $isletmeId)
                    ->groupBy('tahsilatlar.user_id')
                    ->havingRaw('COUNT(*) <= 2');
            })->count();
            
        $sadikMusterilerSayisi = DB::table('musteri_portfoy')
            ->join('users', 'musteri_portfoy.user_id', '=', 'users.id')
            ->where('musteri_portfoy.salon_id', $isletmeId)
            ->where('musteri_portfoy.aktif', true)
            ->whereExists(function ($q) use ($isletmeId) {
                $q->select(DB::raw(1))
                    ->from('tahsilatlar')
                    ->whereRaw('tahsilatlar.user_id = users.id')
                    ->where('tahsilatlar.salon_id', $isletmeId)
                    ->groupBy('tahsilatlar.user_id')
                    ->havingRaw('COUNT(*) >= 3');
            })->count();

        $grup =  GrupSMS::where('salon_id',$isletmeId)->where('aktif_mi',1)->get();
