    /**
     * Musteri kartindan / randevu detayindan salon sahibinin elle yazdigi
     * serbest metni musteriye WhatsApp ile gonderir.
     * Ban guvenligi: urgent=false => normal kuyruk (typing simulasyonu, gunluk limit,
     * connected kontrolu otomatik uygulanir). Bypass YOK.
     */
    public function musterimanuelwhatsappgonder(Request $request)
    {
        if($r = self::yetkiYoksa403($request, 'pazarlama.whatsapp_gonder')) return $r;
        $salonId = self::mevcutsube($request);
        $isletme = Salonlar::where('id',$salonId)->first();
        if(!$isletme){
            return response()->json(['ok'=>false,'mesaj'=>'Salon bulunamadi.'],404);
        }

        // Mesaj kontrolu
        $mesaj = trim((string)$request->input('mesaj',''));
        if($mesaj === ''){
            return response()->json(['ok'=>false,'mesaj'=>'Mesaj bos olamaz.'],422);
        }
        if(mb_strlen($mesaj) > 1000){
            return response()->json(['ok'=>false,'mesaj'=>'Mesaj en fazla 1000 karakter olabilir.'],422);
        }

        // Yetki: musteri bu salonun portfoyunde mi?
        $portfoy = MusteriPortfoy::where('user_id',$request->user_id)->where('salon_id',$isletme->id)->first();
        if(!$portfoy){
            return response()->json(['ok'=>false,'mesaj'=>'Bu musteri salonunuza ait degil.'],403);
        }

        $musteri = User::where('id',$request->user_id)->first();
        if(!$musteri || !$musteri->cep_telefon){
            return response()->json(['ok'=>false,'mesaj'=>'Musteri telefon numarasi bulunamadi.'],422);
        }

        // Baileys ise bagli olmali (net hata mesaji icin on-kontrol)
        // Paylasilan oturum: 416 icin 246'nin durumu kontrol edilir.
        $waIsletme = \App\Services\WhatsAppService::resolveWaSalon($isletme);
        $saglayici = $waIsletme->whatsapp_saglayici ?? 'baileys';
        if($saglayici === 'baileys' && (!$waIsletme->whatsapp_aktif || $waIsletme->whatsapp_durum !== 'connected')){
            return response()->json(['ok'=>false,'mesaj'=>'WhatsApp bagli degil. Once WhatsApp ayarlarindan QR okutun.'],409);
        }

        $wa = app(\App\Services\WhatsAppService::class);
        $sonuc = $wa->sendReminder($isletme, $musteri->cep_telefon, $mesaj, null, $musteri->id, null, false, 'manuel_musteri');

        if(!empty($sonuc['ok'])){
            return response()->json(['ok'=>true,'mesaj'=>'Mesaj gonderim kuyruguna alindi. Birazdan musteriye ulasacak.']);
        }

        $hataKodu = $sonuc['error'] ?? 'unknown';
        $hataMetin = [
            'invalid-phone'         => 'Musteri telefon numarasi gecersiz.',
            'daily-cap-reached'     => 'Gunluk WhatsApp mesaj limitiniz doldu.',
            'outside-business-hours'=> 'Su an calisma saatleri disinda, mesaj gonderilemedi.',
            'service-unreachable'   => 'WhatsApp servisine ulasilamadi, lutfen tekrar deneyin.',
        ][$hataKodu] ?? 'Mesaj gonderilemedi. Lutfen tekrar deneyin.';

        return response()->json(['ok'=>false,'mesaj'=>$hataMetin],422);
    }

    /**
     * Salonun Google Maps konum linkini kaydeder (WhatsApp mesajinda "Konum Ekle" butonu icin).
     */
    public function whatsappKonumKaydet(Request $request)
    {
        try {
            $subeId  = self::mevcutsube($request);
            $isletme = Salonlar::where('id', $subeId)->first();
            if(!$isletme){
                return response()->json(['ok'=>false,'mesaj'=>'Salon bulunamadi (sube: '.$subeId.').'],404);
            }

            $guncelle = [];

            // Link alanlari (URL) — https:// zorunlu, max 500
            $urlAlanlar = ['konum_linki', 'instagram_linki', 'web_linki'];
            foreach($urlAlanlar as $kolon){
                if(!$request->has($kolon)) continue;
                $link = trim((string)$request->input($kolon, ''));
                if($link !== '' && !preg_match('~^https?://~i', $link)){
                    return response()->json(['ok'=>false,'mesaj'=>'Geçerli bir bağlantı girin (https:// ile başlamalı).'],422);
                }
                if(mb_strlen($link) > 500){
                    return response()->json(['ok'=>false,'mesaj'=>'Bağlantı çok uzun (en fazla 500 karakter).'],422);
                }
                if(!\Schema::hasColumn('salonlar', $kolon)){
                    try { DB::statement("ALTER TABLE salonlar ADD COLUMN {$kolon} VARCHAR(500) NULL"); } catch(\Throwable $e){}
                }
                $guncelle[$kolon] = ($link !== '' ? $link : null);
            }

            // Baslik alanlari (salon kendi yaziyor) — URL degil, sadece uzunluk (max 60)
            $baslikAlanlar = ['instagram_baslik', 'web_baslik'];
            foreach($baslikAlanlar as $kolon){
                if(!$request->has($kolon)) continue;
                $val = trim((string)$request->input($kolon, ''));
                if(mb_strlen($val) > 60){
                    return response()->json(['ok'=>false,'mesaj'=>'Başlık çok uzun (en fazla 60 karakter).'],422);
                }
                if(!\Schema::hasColumn('salonlar', $kolon)){
                    try { DB::statement("ALTER TABLE salonlar ADD COLUMN {$kolon} VARCHAR(60) NULL"); } catch(\Throwable $e){}
                }
                $guncelle[$kolon] = ($val !== '' ? $val : null);
            }

            // Eloquent save() yerine direkt UPDATE — model event/cast/timestamps risklerini bypass eder
            if(!empty($guncelle)){
                DB::table('salonlar')->where('id', $isletme->id)->update($guncelle);
            }

            return response()->json(['ok'=>true]);
        } catch(\Throwable $e){
            \Log::error('whatsappKonumKaydet hata: '.$e->getMessage().' @ '.$e->getFile().':'.$e->getLine());
            return response()->json(['ok'=>false,'mesaj'=>'Konum kaydedilemedi: '.$e->getMessage()],500);
        }
    }

    /**
     * Salon "Kontör Al"a basinca sistem sahibine (Ferdi) WhatsApp + SMS talep bildirimi gonderir.
     * Kanal: SistemBildirim (sistem WhatsApp oturumu + SMS yedek) — demo bildirimiyle ayni PROVEN yol.
     */
    public function whatsappKontorTalep(Request $request)
    {
        try {
            $isletme = Salonlar::where('id', self::mevcutsube($request))->first();
            if(!$isletme){
                return response()->json(['ok'=>false,'mesaj'=>'Salon bulunamadi.'],404);
            }

            // Fiyatlar sunucuda otoriter — frontend spoof edemez
            $paketler = [
                'kontor_10000'  => ['ad'=>'10.000 Kontör',  'fiyat'=>'2.850 TL'],
                'kontor_20000'  => ['ad'=>'20.000 Kontör',  'fiyat'=>'5.300 TL'],
                'kontor_40000'  => ['ad'=>'40.000 Kontör',  'fiyat'=>'9.800 TL'],
                'kontor_60000'  => ['ad'=>'60.000 Kontör',  'fiyat'=>'13.800 TL'],
                'kontor_80000'  => ['ad'=>'80.000 Kontör',  'fiyat'=>'17.000 TL'],
                'kontor_100000' => ['ad'=>'100.000 Kontör', 'fiyat'=>'20.000 TL'],
            ];
            $key = (string) $request->input('paket', '');
            if(!isset($paketler[$key])){
                return response()->json(['ok'=>false,'mesaj'=>'Geçersiz paket.'],422);
            }
            $p = $paketler[$key];
            $iletisim = trim((string) $request->input('iletisim', ''));
            $tel = $isletme->yetkili_telefon ?: ($isletme->telefon_1 ?: '');

            $mesaj = "💰 KONTÖR TALEBİ\n"
                . "Salon: " . ($isletme->salon_adi ?? '-') . "\n"
                . "Paket: " . $p['ad'] . " (" . $p['fiyat'] . ")\n"
                . ($isletme->yetkili_adi ? ("Yetkili: " . $isletme->yetkili_adi . "\n") : '')
                . ($tel ? ("Tel: " . $tel . "\n") : '')
                . ($iletisim !== '' ? ("İletişim/Not: " . mb_substr($iletisim, 0, 120) . "\n") : '')
                . "ID: " . $isletme->id . "\n"
                . date('d.m.Y H:i');

            $r = \App\Services\SistemBildirim::gonder($mesaj);

            // Teşhis: bildirimin GERÇEK sonucu (Test butonuyla ayni mantik)
            if (empty($r['ok'])) {
                $teshis = 'Bildirim kanalı kapalı veya numara yok — Sistem Yönetimi → Sistem WhatsApp\'tan ayarla.';
            } else {
                $wa  = $r['detay']['wa'] ?? [];
                $sms = $r['detay']['sms'] ?? [];
                $waMsg  = !empty($wa['ok'])  ? 'WA kuyruğa alındı ✓' : ('WA gitmedi (' . ($wa['error'] ?? ('http ' . ($wa['status'] ?? '?'))) . ')');
                $smsMsg = !empty($sms['ok']) ? 'SMS gönderildi ✓'     : ('SMS gitmedi (' . ($sms['durum'] ?? 'hata') . ')');
                $teshis = $waMsg . ' | ' . $smsMsg;
            }

            \Log::info('[KONTOR-TALEP]', [
                'salon_id' => $isletme->id, 'paket' => $key,
                'bildirim_ok' => $r['ok'] ?? false, 'teshis' => $teshis,
            ]);

            // Bildirim kanali kapali olsa bile talep loglandi — salona her halukarda 'alindi' de.
            return response()->json([
                'ok' => true,
                'mesaj' => 'Talebiniz alındı. En kısa sürede sizinle iletişime geçeceğiz. 🙌',
                'teshis' => $teshis,
            ]);
        } catch(\Throwable $e){
            \Log::error('whatsappKontorTalep hata: '.$e->getMessage().' @ '.$e->getFile().':'.$e->getLine());
            return response()->json(['ok'=>false,'mesaj'=>'Talep gönderilemedi, lütfen tekrar deneyin.'],500);
        }
    }

    public function sms_raporlari(Request $request)
    {

        $isletme = Salonlar::where('id',self::mevcutsube($request))->first();

        if ($isletme && $isletme->yeni_sms == 1) {
            $smsController = app()->make(SMSController::class);
            return $smsController->voiceTelekomRaporlariGetir($isletme->id);
        }

        $legacyKolonlar = [
            'rapor_id as id',
            DB::raw('CONCAT("<span style=\"display:none\">",DATE_FORMAT(updated_at,"%Y%m%d%H%i%s"),"</span>",DATE_FORMAT(updated_at,"%d.%m.%Y %H:%i:%s")) as date'),
            'adet as count',
            'kredi as price',
            'aciklama as msgdetails',
            'durum as status',
        ];
        $salonIdLegacy = self::mevcutsube($request);
        $smsraportoplu = DB::table('sms_iletim_raporlari')->select($legacyKolonlar)->where('salon_id',$salonIdLegacy)->where('tur',4)->orderBy('updated_at','desc')->get();
        $smsraporbildirim = DB::table('sms_iletim_raporlari')->select($legacyKolonlar)->where('salon_id',$salonIdLegacy)->where(function($q){$q->where('tur',1); $q->orWhere('tur',''); $q->orWhere('tur',null);})->orderBy('updated_at','desc')->get();
        $smsraporgrup = DB::table('sms_iletim_raporlari')->select($legacyKolonlar)->where('salon_id',$salonIdLegacy)->where('tur',2)->orderBy('updated_at','desc')->get();
        $smsraporfiltre = DB::table('sms_iletim_raporlari')->select($legacyKolonlar)->where('salon_id',$salonIdLegacy)->where('tur',3)->orderBy('updated_at','desc')->get();
        $smsraporkampanya = DB::table('sms_iletim_raporlari')->select($legacyKolonlar)->where('salon_id',$salonIdLegacy)->where('tur',5)->orderBy('updated_at','desc')->get();
        $smsraporetkinlik = DB::table('sms_iletim_raporlari')->select($legacyKolonlar)->where('salon_id',$salonIdLegacy)->where('tur',6)->orderBy('updated_at','desc')->get();
        return array(
            'toplu' => $smsraportoplu,
            'bildirim' => $smsraporbildirim,
            'grup' => $smsraporgrup,
            'filtre' => $smsraporfiltre,
            'kampanya' => $smsraporkampanya,
            'etkinlik' => $smsraporetkinlik,
        );
    }

    public function sms_raporlari_sayfali(Request $request)
    {
        $isletme = Salonlar::where('id', self::mevcutsube($request))->first();
        $tur = $request->input('tur', 'bildirim');
        $draw = intval($request->input('draw', 1));
        $start = intval($request->input('start', 0));
        $length = intval($request->input('length', 10));

        $aramaDegeri = $request->input('search.value', $request->input('search', ''));
        if (is_array($aramaDegeri)) {
            $aramaDegeri = isset($aramaDegeri['value']) ? $aramaDegeri['value'] : '';
        }
        $aramaDegeri = trim((string)$aramaDegeri);

        $orderDir = $request->input('order.0.dir');
        if (empty($orderDir)) {
            $order = $request->input('order', []);
            if (is_array($order) && isset($order[0]['dir'])) $orderDir = $order[0]['dir'];
        }
        $yon = strtolower((string)$orderDir) === 'asc' ? 'asc' : 'desc';

        $length = ($length <= 0) ? 10 : min($length, 500);

        $bosYanit = [
            'draw' => $draw,
            'recordsTotal' => 0,
            'recordsFiltered' => 0,
            'data' => [],
        ];

        if (!$isletme) {
            return response()->json($bosYanit);
        }

        if ($isletme->yeni_sms == 1) {
            $smsController = app()->make(SMSController::class);
            $raporlar = $smsController->voiceTelekomRaporlariGetir($isletme->id);
            $tumListe = isset($raporlar[$tur]) ? $raporlar[$tur]->values()->all() : [];
            $toplam = count($tumListe);

            if ($aramaDegeri !== '') {
                $tumListe = array_values(array_filter($tumListe, function($satir) use ($aramaDegeri) {
                    return stripos($satir['msgdetails'] ?? '', $aramaDegeri) !== false;
                }));
            }
            $filtreli = count($tumListe);

            if ($yon === 'asc') {
                $tumListe = array_reverse($tumListe);
            }

            \Log::info('sms_raporlari_sayfali yeni_sms=1', [
                'salon' => $isletme->id, 'tur' => $tur, 'toplam' => $toplam,
                'filtreli' => $filtreli, 'start' => $start, 'length' => $length,
            ]);

            return response()->json([
                'draw' => $draw,
                'recordsTotal' => $toplam,
                'recordsFiltered' => $filtreli,
                'data' => array_slice($tumListe, $start, $length),
            ]);
        }

        $turMap = ['bildirim' => 1, 'grup' => 2, 'filtre' => 3, 'toplu' => 4, 'kampanya' => 5, 'etkinlik' => 6];
        $turNum = $turMap[$tur] ?? 1;

        $sorgu = DB::table('sms_iletim_raporlari')->where('salon_id', $isletme->id);
        if ($tur === 'bildirim') {
            $sorgu->where(function($q){ $q->where('tur', 1)->orWhere('tur', '')->orWhereNull('tur'); });
        } else {
            $sorgu->where('tur', $turNum);
        }

        $toplam = (clone $sorgu)->count();

        if ($aramaDegeri !== '') {
            $sorgu->where('aciklama', 'LIKE', '%' . $aramaDegeri . '%');
        }
        $filtreli = (clone $sorgu)->count();

        $satirlar = $sorgu
            ->select([
                'rapor_id as id',
                DB::raw('CONCAT("<span style=\"display:none\">",DATE_FORMAT(updated_at,"%Y%m%d%H%i%s"),"</span>",DATE_FORMAT(updated_at,"%d.%m.%Y %H:%i:%s")) as date'),
                'adet as count',
                'kredi as price',
                'aciklama as msgdetails',
                'durum as status',
            ])
            ->orderBy('updated_at', $yon)
            ->skip($start)
            ->take($length)
            ->get();

        \Log::info('sms_raporlari_sayfali legacy', [
            'salon' => $isletme->id, 'tur' => $tur, 'toplam' => $toplam,
            'filtreli' => $filtreli, 'start' => $start, 'length' => $length, 'donen' => $satirlar->count(),
        ]);

        return response()->json([
            'draw' => $draw,
            'recordsTotal' => intval($toplam),
            'recordsFiltered' => intval($filtreli),
            'data' => $satirlar,
        ]);
    }

    public function sms_karaliste_sayfali(Request $request)
    {
        $isletme = Salonlar::where('id', self::mevcutsube($request))->first();
        $draw = intval($request->input('draw', 1));
        $start = intval($request->input('start', 0));
        $length = intval($request->input('length', 10));
        $aramaDegeri = trim((string)$request->input('search.value', ''));

        $length = ($length <= 0) ? 10 : min($length, 200);

        if (!$isletme) {
            return response()->json(['draw' => $draw, 'recordsTotal' => 0, 'recordsFiltered' => 0, 'data' => []]);
        }

        $temel = DB::table('users')
            ->join('musteri_portfoy', 'musteri_portfoy.user_id', '=', 'users.id')
            ->where('musteri_portfoy.salon_id', $isletme->id)
            ->where('musteri_portfoy.kara_liste', 1);

        $toplam = (clone $temel)->count();

        if ($aramaDegeri !== '') {
            $temel->where(function($q) use ($aramaDegeri) {
                $q->where('users.name', 'LIKE', '%' . $aramaDegeri . '%')
                  ->orWhere('users.cep_telefon', 'LIKE', '%' . $aramaDegeri . '%');
            });
        }
        $filtreli = (clone $temel)->count();

        $yon = strtolower((string)$request->input('order.0.dir', 'desc')) === 'asc' ? 'asc' : 'desc';
        $satirlar = $temel
            ->select(
                'users.name as ad_soyad',
                'users.cep_telefon as telefon',
                DB::raw('DATE_FORMAT(musteri_portfoy.updated_at,"%d.%m.%Y") as eklenme_tarihi'),
                DB::raw('CONCAT("<button class=\"btn btn-primary\" name=\"numara_karalisteden_kaldir\" data-value=\"",users.id,"\">Numarayı Listeden Kaldır</button>") AS islemler')
            )
            ->orderBy('musteri_portfoy.updated_at', $yon)
            ->skip($start)
            ->take($length)
            ->get();

        // Personel "musteri.telefon_gor" yetkisi yoksa telefon maskeli
        $satirlar = $satirlar->map(function ($r) {
            if (isset($r->telefon)) {
                $r->telefon = \App\PersonelYetkiSabitleri::telefonGoster($r->telefon);
            }
            return $r;
        });

        return response()->json([
            'draw' => $draw,
            'recordsTotal' => $toplam,
            'recordsFiltered' => $filtreli,
            'data' => $satirlar,
        ]);
    }

    public function sms_rapor_detay(Request $request)
    {
        $isletme = Salonlar::where('id', self::mevcutsube($request))->first();
        if (!$isletme) {
            return response()->json(['basarili' => false, 'mesaj' => 'Isletme bulunamadi', 'kayitlar' => []]);
        }
        $paketId = $request->input('pkg_id');
        if (empty($paketId)) {
            return response()->json(['basarili' => false, 'mesaj' => 'Paket kimligi bulunamadi', 'kayitlar' => []]);
