    public function sms_rapor_getir($raporid,$isletme)
    {
        $headers = array(
                     'Authorization: Key '.$isletme->sms_apikey,
                     'Content-Type: application/json',
                     'Accept: application/json'
        );
        $postData = json_encode( array( "originator"=> $isletme->sms_baslik, "id"=> $raporid) );
        $ch=curl_init();
        curl_setopt($ch,CURLOPT_URL,'https://api.efetech.net.tr/v2/get/report');
        curl_setopt($ch,CURLOPT_POSTFIELDS,$postData);
        curl_setopt($ch,CURLOPT_POST,1);
        curl_setopt($ch,CURLOPT_TIMEOUT,5);
        curl_setopt($ch,CURLOPT_RETURNTRANSFER,1);
        curl_setopt($ch,CURLOPT_HTTPHEADER,$headers);
        $response = curl_exec($ch);
        curl_close($ch);
        return json_decode($response,true);
    }
    public function personelsifregonder(Request $request)
    {
        if($r = self::yetkiYoksa403($request, 'personel.ekle_duzenle')) return $r;
        $personel = Personeller::where('id',$request->personelid)->first();
        $yetkili = IsletmeYetkilileri::where('id',$personel->yetkili_id)->first();
        $random = str_shuffle('ABCDEFGHJKLMNOPQRSTUVWXYZ1234567890');
        $kod = substr($random, 0, 6);
        $yetkili->password = Hash::make($kod);
        $yetkili->save();
        $personel->sifre = $kod;
        $personel->save();
        $mesajlar = array(array("to"=>$yetkili->gsm1,"message"=> "Sayın ".$yetkili->name.". Randevumcepte yeni şifreniz : ".$kod. ' olarak '.Auth::guard('isletmeyonetim')->user()->name.' tarafından belirlenmiştir.'));
        self::sms_gonder_bildirimli($request,$mesajlar,false,1,false);
        return $yetkili->name.' isimli kullanıcının şifresi başarıyla değiştirilip telefon numarasına iletilmiştir';
    }
    public function personelaktifpasifyap(Request $request)
    {
        if($r = self::yetkiYoksa403($request, 'personel.ekle_duzenle')) return $r;
        $yetkili = Personeller::where('id',$request->personelid)->first();
        if(!$yetkili){
            return array('mesaj'=>'Personel bulunamadi','personeller'=>self::personel_liste_getir($request));
        }
        $newAktif = ((int)$request->aktif === 1);
        $yetkili->aktif = $newAktif;
        // Pasif yapilanlar listenin en altina, aktif yapilanlar aktiflerin sonuna gider.
        // takvim_sirasi'na buyuk bir "guard" deger yaziyoruz; personel_liste_getir
        // bir sonraki cagrida 0..n-1 olarak normalize eder.
        $isletmeId = $yetkili->salon_id;
        $toplam = Personeller::where('salon_id',$isletmeId)->count();
        if($newAktif){
            // Aktiflerin sonu icin: kendisi haric aktif sayisini kullan; pasiflerin
            // takvim_sirasi'lari normalize edilmis olsa bile bu deger pasiflerin onunde kalir.
            $aktifSayisi = Personeller::where('salon_id',$isletmeId)->where('aktif',1)
                ->where('id','!=',$yetkili->id)->count();
            $yetkili->takvim_sirasi = $aktifSayisi;
        } else {
            // En altta tutmak icin toplamdan buyuk bir deger; normalize sonrasi son siraya duser.
            $yetkili->takvim_sirasi = $toplam + 999;
        }
        $yetkili->save();
        $returntext = $newAktif ? 'aktif' : 'pasif';
        $isim = $yetkili->personel_adi ?: 'Personel';
        // Audit
        SalonAudit::log($isletmeId, $newAktif ? 'personel_aktif_et' : 'personel_pasif_et', 'personel', $yetkili->id,
            $isim,
            'Personel '.$returntext.' edildi');
        return array(
            'mesaj'=>$isim.' isimli personel başarıyla '.$returntext.' edildi',
            'personeller'=>self::personel_liste_getir($request)
        );
    }
    public function grupsmsekleduzenle(Request $request)
    {
        $grupsms = "";
        $_yeniGrup = false;
        if(isset($request->grup_id))
            $grupsms = GrupSms::where('id',$request->grup_id)->first();
        else {
            $grupsms = new GrupSms();
            $_yeniGrup = true;
        }
        $grupsms->grup_adi = $request->grup_ad;
        $grupsms->salon_id = self::mevcutsube($request);
        $grupsms->aktif_mi = true;
        $grupsms->save();
        $grup_katilimcilar = GrupSmsKatilimcilari::where('grup_id',$grupsms->id)->delete();
        foreach($request->duallistbox_demo1 as $key => $grup_katilimci)
        {
            $grup_yenikatilimci = new GrupSmsKatilimcilari();
            $grup_yenikatilimci->grup_id = $grupsms->id;
            $grup_yenikatilimci->user_id = $grup_katilimci;
            $grup_yenikatilimci->save();
        }
        // Audit
        SalonAudit::log($grupsms->salon_id, $_yeniGrup ? 'sms_grup_ekle' : 'sms_grup_guncelle', 'sms_grup', $grupsms->id,
            $grupsms->grup_adi.' — '.count((array)$request->duallistbox_demo1).' kişi',
            $_yeniGrup ? 'Yeni SMS grubu oluşturuldu' : 'SMS grubu güncellendi',
            ['katilimci_sayisi'=>count((array)$request->duallistbox_demo1)]);
        return array(
          "mesaj" => "Grup Başarıyla Oluşturuldu",
          'grup' => self::grup_sms_liste_getir($request)
        );
    }

    /**
     * Grup Düzenle modalı için müşteri dual-listbox'ını (select + option) döner.
     * Grup üyeleri "selected" işaretlenir. JS (#grup_musteri_liste_duzenle) bu HTML'i
     * append edip bootstrapDualListbox başlatır.
     */
    public function grupduzenle(Request $request){
        $grup = GrupSms::where('id',$request->grup_id)->first();
        $gmusteri = MusteriPortfoy::where('salon_id',self::mevcutsube($request))->where('aktif',1)->get();

        // Grup üyelerinin user_id'lerini tek seferde topla (N+1 önle)
        $uyeIdler = [];
        if($grup){
            $uyeIdler = GrupSmsKatilimcilari::where('grup_id',$grup->id)->pluck('user_id')->toArray();
        }
        $uyeIdler = array_flip($uyeIdler);

        $html = '<select multiple="multiple" name="duallistbox_demo1[]" title="duallistbox_demo1[]">';
        foreach($gmusteri as $musteri){
            if(!$musteri->users) continue;
            $ad = htmlspecialchars($musteri->users->name);
            $selected = isset($uyeIdler[$musteri->user_id]) ? ' selected' : '';
            $html .= '<option'.$selected.' value="'.$musteri->user_id.'">'.$ad.'</option>';
        }
        $html .= '</select>';

        return $html;
    }

    /**
     * Yeni "Grup Düzenle" modalı (tablo tasarımı) için grup bilgisi + katılımcılar +
     * aday müşteriler. JS (musteriSecimiDuzenle.js) bu uçtan tabloyu ve ekleme
     * dropdown'ını doldurur.
     */
    public function grupBilgileriGetir(Request $request){
        $grup = GrupSms::where('id',$request->grup_id)->first();
        if(!$grup){
            return response()->json(['success'=>false,'message'=>'Grup bulunamadı']);
        }
        $salonId = self::mevcutsube($request);

        $uyeSet = array_flip(GrupSmsKatilimcilari::where('grup_id',$grup->id)->pluck('user_id')->toArray());

        $katilimcilar = [];
        $adaylar = [];
        MusteriPortfoy::where('salon_id',$salonId)->where('aktif',1)
            ->with('users:id,name,cep_telefon')
            ->chunk(500, function($portfoy) use (&$katilimcilar,&$adaylar,$uyeSet){
                foreach($portfoy as $p){
                    if(!$p->users) continue;
                    $satir = ['id'=>$p->user_id,'ad_soyad'=>$p->users->name,'telefon'=>$p->users->cep_telefon];
                    if(isset($uyeSet[$p->user_id])) $katilimcilar[] = $satir;
                    else $adaylar[] = $satir;
                }
            });

        return response()->json([
            'success'=>true,
            'grup_adi'=>$grup->grup_adi,
            'katilimcilar'=>$katilimcilar,
            'adaylar'=>$adaylar,
        ]);
    }
    public function urun_guncelle(Request $request){
        $yeni = false;
        if($request->urun_id_duzenle == 0){
            $urun = new Urunler();
            $yeni = true;
            $returntext = "Ürün başarıyla eklendi";
        }
        else{
            $urun = Urunler::where('id',$request->urun_id_duzenle)->first();
            $returntext = "Ürün başarıyla güncellendi";
        }
        $oncekiStok = (float) ($urun->stok_adedi ?? 0);
        $salonId = self::mevcutsube($request);

        $urun->urun_adi          = $request->urun_ad;
        $urun->fiyat             = $request->fiyat_duzenle;
        $urun->barkod            = $request->barkod_duzenle;
        $urun->dusuk_stok_siniri = $request->dusuk_stok_siniri;
        $urun->salon_id          = $salonId;

        $depo = StokController::varsayilanDepoyuGetirVeyaOlustur((int) $salonId);
        if (empty($urun->varsayilan_depo_id)) {
            $urun->varsayilan_depo_id = $depo->id;
        }
        $urun->save();

        $istenenStok = (float) ($request->stok_aded ?? $oncekiStok);
        $fark = $istenenStok - $oncekiStok;
        if ($yeni && $istenenStok != 0) {
            StokController::hareketKaydet([
                'salon_id'     => $salonId,
                'urun_id'      => $urun->id,
                'depo_id'      => $urun->varsayilan_depo_id,
                'miktar'       => $istenenStok,
                'hareket_tipi' => 'acilis',
                'aciklama'     => 'Web panel - urun olusturuldu (duzenle)',
            ]);
        } elseif (!$yeni && abs($fark) > 0.0001) {
            StokController::hareketKaydet([
                'salon_id'     => $salonId,
                'urun_id'      => $urun->id,
                'depo_id'      => $urun->varsayilan_depo_id,
                'miktar'       => $fark,
                'hareket_tipi' => 'manuel',
                'aciklama'     => 'Web panel - stok duzeltme',
            ]);
        }

        return self::urun_liste_getir($request,$returntext);
    }
    public function bildirimekle(Request $request,$salonid,$mesaj,$url,$personelid,$musteriid,$imgurl,$randevuid)
    {
        $bildirim = new Bildirimler();
        $bildirim->aciklama = $mesaj;
        $bildirim->salon_id = $salonid;
        $bildirim->personel_id = $personelid;
        $bildirim->url = $url;
        $bildirim->tarih_saat = date('Y-m-d H:i:s');
        $bildirim->okundu = false;
        $bildirim->user_id = $musteriid;
        $bildirim->img_src = $imgurl;
