    /**
     * Eski OneSignal cagrilarinin koprusu. Imza degismeden, ic kisim FCM v1'e
     * (NotificationService) yonlenir. $channelid/$appid/$key parametreleri
     * geri uyum icin tutulur ama kullanilmaz.
     */
    public function bildirimgonder($bildirimkimlikleri, $baslik, $mesaj, $salonid = null, $channelid = null, $appid = null, $key = null)
    {
        if (empty($bildirimkimlikleri)) return null;
        try {
            return \App\Services\NotificationService::forTokens((array)$bildirimkimlikleri, $salonid ? (int)$salonid : null)
                ->type(\App\Services\NotificationTypes::SYSTEM_ANNOUNCEMENT)
                ->title((string)$baslik)
                ->body((string)$mesaj)
                ->send();
        } catch (\Throwable $e) {
            \Log::warning('bildirimgonder bridge fail: ' . $e->getMessage());
            return null;
        }
    }
    public function isletmegorselekle(Request $request)
    {
        if($r = self::yetkiYoksa403($request, 'ayar.salon_bilgi')) return $r;
        if(isset($_FILES["isletmegorselleri"]["name"])){
            $mevcutSayi = SalonGorselleri::where('salon_id',$request->sube)->where('kapak_fotografi','!=',1)->count();
            $kalanSlot = max(0, 12 - $mevcutSayi);
            $yuklenecek = min(count($_FILES["isletmegorselleri"]["name"]), $kalanSlot);
            for($i=0;$i<$yuklenecek;$i++){
                $salongorselleri = new SalonGorselleri();
                $image = $request->isletmegorselleri[$i];
                $filename = strtotime(date('H:i:s')). '-' .$_FILES["isletmegorselleri"]["name"][$i] . '.' . $image->getClientOriginalExtension();
                Image::make($image)->resize(null, 720, function ($constraint) {
                    $constraint->aspectRatio();
                })->save( public_path('/salon_gorselleri/' . $filename) );
                $salongorselleri->salon_gorseli = "/public/salon_gorselleri/".$filename;
                $salongorselleri->salon_id = $request->sube;
                $salongorselleri->kapak_fotografi = 0;
                $salongorselleri->save();
            }
        }
        $gorselsayisi = SalonGorselleri::where('salon_id',$request->sube)->where('kapak_fotografi','!=',1)->count();
        $kalan = 12-$gorselsayisi;
        return array(
            'eklemetext' => 'İşletme Görsellerini Ekleyin (Max:'.$kalan.' adet)',
            'gorseller_html' => self::salon_gorselleri($request),
        );
    }
