  public function adisyon_sil(Request $request)
   {
            if($r = self::satisYetkiYoksa403($request, 'satis.adisyon_sil')) return $r;
            // Audit (silmeden once kayit al)
            $_audit_adisyon = Adisyonlar::where('id',$request->adisyon_id)->first();
            if ($_audit_adisyon) {
                $_audit_musteriAdi = \App\User::where('id',$_audit_adisyon->user_id)->value('name') ?? 'Müşteri #'.$_audit_adisyon->user_id;
                SalonAudit::log($_audit_adisyon->salon_id, 'adisyon_sil', 'adisyon', $_audit_adisyon->id,
                    $_audit_musteriAdi.' — Adisyon #'.$_audit_adisyon->id,
                    'Adisyon ve tüm kalemleri silindi',
                    ['user_id'=>$_audit_adisyon->user_id]);
            }
            $adisyonhizmetler = AdisyonHizmetler::where('adisyon_id',$request->adisyon_id)->get();
            $adisyonurunler = AdisyonUrunler::where('adisyon_id',$request->adisyon_id)->get();
            $adisyonpaketler = AdisyonPaketler::where('adisyon_id',$request->adisyon_id)->get();
            $senet_idler = array();
            $taksitlitahsilat_idler = array();
            $tahsilat_idler = array();
            foreach($adisyonhizmetler as $adisyonhizmet)
            {
                array_push($senet_idler,$adisyonhizmet->senet_id);
                array_push($taksitlitahsilat_idler,$adisyonhizmet->taksitli_tahsilat_id);
                foreach(TahsilatHizmetler::where('adisyon_hizmet_id',$adisyonhizmet->id)->get() as $hizmettahsilat)
                {
                    array_push($tahsilat_idler,$hizmettahsilat->tahsilat_id);
                    $hizmettahsilat->delete();
                }
                $adisyonhizmet->delete();
            }
            foreach($adisyonurunler as $adisyonurun)
            {
                array_push($senet_idler,$adisyonurun->senet_id);
                array_push($taksitlitahsilat_idler,$adisyonurun->taksitli_tahsilat_id);
                foreach(TahsilatUrunler::where('adisyon_urun_id',$adisyonurun->id)->get() as $uruntahsilat)
                {
                    array_push($tahsilat_idler,$uruntahsilat->tahsilat_id);
                    $uruntahsilat->delete();
                }
                $adisyonurun->delete();
            }
            foreach($adisyonpaketler as $adisyonpaket)
            {
                array_push($senet_idler,$adisyonpaket->senet_id);
                array_push($taksitlitahsilat_idler,$adisyonpaket->taksitli_tahsilat_id);
                foreach(TahsilatPaketler::where('adisyon_paket_id',$adisyonpaket->id)->get() as $pakettahsilat)
                {
                    array_push($tahsilat_idler,$pakettahsilat->tahsilat_id);
                    $pakettahsilat->delete();
                }
                $adisyonpaket->delete();
            }
            $taksitler = TaksitliTahsilatlar::whereIn('id',$taksitlitahsilat_idler)->get();
            foreach($taksitler as $taksit)
            {
                foreach($taksit->vadeler as $vade)
                    $vade->delete();
                $taksit->delete();
            }
            $senetler = Senetler::whereIn('id',$senet_idler)->get();
            foreach($senetler as $senet)
            {
                foreach($senet->vadeler as $vade)
                    $vade->delete();
                $senet->delete();
            }
            Tahsilatlar::whereIn('id',$tahsilat_idler)->delete();
            // Guvenlik agi: adisyon_id ile bagli ama breakdown (tahsilat_hizmetler/
            // urunler/paketler) satiri olmayan tahsilatlar yukaridaki whereIn ile
            // yakalanmaz (orn. import edilmis dagilim satiri olusmamis kayitlar).
            // Bunlar adisyon silinince oksuz kalip ciroya/musteri bakiyesine
            // "hayalet" tutar olarak yansiyordu; burada birlikte temizleniyor.
            $oksuzTahsilatIdler = Tahsilatlar::where('adisyon_id',$request->adisyon_id)->pluck('id')->toArray();
            if(count($oksuzTahsilatIdler) > 0){
                TahsilatHizmetler::whereIn('tahsilat_id',$oksuzTahsilatIdler)->delete();
                TahsilatUrunler::whereIn('tahsilat_id',$oksuzTahsilatIdler)->delete();
                TahsilatPaketler::whereIn('tahsilat_id',$oksuzTahsilatIdler)->delete();
                Tahsilatlar::whereIn('id',$oksuzTahsilatIdler)->delete();
            }
            // Taksit/senet kalintisi: vadeler yukarida silindi ama bu vadelere
            // (taksit_vade_id/senet_vade_id) ve adisyona bagli Alacaklar kayitlari
            // siliniyordu DEGIL -> alacaklar listesinde silinmis vadeye isaret eden
            // "hayalet borc" olarak kaliyordu. Diger silme yollariyla ayni sekilde
            // adisyon_id uzerinden temizleniyor (her Alacaklar kaydinda adisyon_id dolu).
            Alacaklar::where('adisyon_id',$request->adisyon_id)->delete();
            Adisyonlar::where('id',$request->adisyon_id)->delete();
            $musteriid = '';
            if($request->musteri_id!='')
                $musteriid = $request->musteri_id;
            $tarih1 = '';
            $tarih2 = '';
            if($request->tariharaligi!=''){
                $tarih = explode(' / ',$request->tariharaligi);
                $tarih1 = $tarih[0].' 00:00:00';
                $tarih2 = $tarih[1].' 23:59:59';
            }
            else{
                $tarih1 = '1970-01-01 00:00:00';
                $tarih2 = date('Y-m-d 23:59:59');
            }
           $personelid='';
            if(self::personelmi($request, 'satis.tum_satis_gor'))
                $personelid = Auth::guard('isletmeyonetim')->user()->personel_id;
            return array(
                'mesaj' => 'Adisyon kaydı başarıyla kaldırıldı',
               
                 
            );
    }
    // Performans: ayni sayfada bircok kez cagriliyor (e_asistan'da 2 defa).
    // Salon ID basina cache; bir request icinde lisans degismez.
    private static $_lisansCache = [];
    public function lisans_sure_kontrol(Request $request)
    {
        $salonId = self::mevcutsube($request);
        if (array_key_exists($salonId, self::$_lisansCache)) {
            return self::$_lisansCache[$salonId];
        }
        $isletme = Salonlar::where('id',$salonId)->first();
        $from_time = strtotime(date('Y-m-d H:i:s'));
        $to_time = strtotime(date($isletme->uyelik_bitis_tarihi.' 23:59:59'));
        $diff = round(($to_time - $from_time) / (3600*24),0);
        if($isletme->uyelik_bitis_tarihi == null||$isletme->uyelik_bitis_tarihi == '' )
            $diff .= '-';
        return self::$_lisansCache[$salonId] = $diff;
    }
    public function senetlitahsilatekle(Request $request){
        $tahsilat = '';
        if($request->tahsilat_id != '')
            $tahsilat = Tahsilatlar::where('id',$request->tahsilat_id)->first();
        else
            $tahsilat = new Tahsilatlar();
        $tahsilat->adisyon_id = $request->adisyon_id;
        $tahsilat->tutar = str_replace('.','',$request->indirimli_toplam_tahsilat_tutari);
        $tahsilat->odeme_tarihi = $request->tahsilat_tarihi;
         $tahsilat->olusturan_id = Personeller::where('salon_id',$request->sube)->where('yetkili_id',Auth::guard('isletmeyonetim')->user()->id)->value('id');
        $tahsilat->salon_id = $request->sube;
        $tahsilat->yapilan_odeme = str_replace('.','',$request->indirimli_toplam_tahsilat_tutari);
        $tahsilat->odeme_yontemi_id = $request->odeme_yontemi;
        $tahsilat->notlar = $request->tahsilat_notlari;
        $adisyon = Adisyonlar::where('id',$request->adisyon_id)->first();
        $adisyon->indirim_tutari = str_replace('.','',$request->indirim_tutari);
        $adisyon->save();
        $tahsilat->save();
        if(isset($request->adisyon_hizmet_id))
        {
            foreach($request->adisyon_hizmet_id as $key=>$hizmet_id)
            {
                if($request->tahsilat_id != '')
                    TahsilatHizmetler::where('adisyon_hizmet_id',$hizmet_id)->delete();
                if($request->hizmet_odeme_secili[$key]=='true'){
                    $odeme = new TahsilatHizmetler();
                    $odeme->adisyon_hizmet_id = $hizmet_id;
                    $odeme->tahsilat_id = $tahsilat->id;
                    $odeme->tutar = (str_replace(['.',','],['','.'],$request->adisyon_hizmet_tahsilat_tutari[$key])/str_replace(['.',','],['','.'],$request->tahsilat_tutari))*str_replace(['.',','],['','.'],$request->indirimli_toplam_tahsilat_tutari);
                    $odeme->save();
                }
            }
        }
        if(isset($request->adisyon_urun_id))
        {
            foreach($request->adisyon_urun_id as $key2=>$urun_id)
            {
                if($request->tahsilat_id != '')
                    TahsilatUrunler::where('adisyon_urun_id',$urun_id)->delete();
                if($request->urun_odeme_secili[$key2]=='true'){
                    $odeme = new TahsilatUrunler();
                    $odeme->adisyon_urun_id = $urun_id;
                    $odeme->tahsilat_id = $tahsilat->id;
                    $odeme->tutar = (str_replace(['.',','],['','.'],$request->adisyon_urun_tahsilat_tutari[$key2])/str_replace(['.',','],['','.'],$request->tahsilat_tutari))*str_replace(['.',','],['','.'],$request->indirimli_toplam_tahsilat_tutari);
                    $odeme->save();
                }
            }
        }
        if(isset($request->adisyon_paket_id))
        {
            foreach($request->adisyon_paket_id as $key3=>$paket_id)
            {
                if($request->tahsilat_id != '')
                    TahsilatPaketler::where('adisyon_paket_id',$paket_id)->delete();
                if($request->paket_odeme_secili[$key3]=='true'){
                    $odeme = new TahsilatPaketler();
                    $odeme->adisyon_paket_id = $paket_id;
                    $odeme->tahsilat_id = $tahsilat->id;
                    $odeme->tutar = (str_replace(['.',','],['','.'],$request->adisyon_paket_tahsilat_tutari[$key3])/str_replace(['.',','],['','.'],$request->tahsilat_tutari))*str_replace(['.',','],['','.'],$request->indirimli_toplam_tahsilat_tutari);
                    $odeme->save();
                }
            }
        }
        $alacak = str_replace('.','',$request->odenecek_tutar);
        Alacaklar::where('adisyon_id',$request->adisyon_id)->delete();
        if($alacak != 0)
        {
            $alacak_kaydi = new Alacaklar();

            $alacak_kaydi->salon_id = $request->sube;
            $alacak_kaydi->adisyon_id = $request->adisyon_id;
            $alacak_kaydi->tutar = $alacak;
            $alacak_kaydi->aciklama = $request->tahsilat_notlari;
            $alacak_kaydi->planlanan_odeme_tarihi = $request->planlanan_alacak_tarihi;
            $alacak_kaydi->olusturan_id = Auth::guard('isletmeyonetim')->user()->id;
            $alacak_kaydi->salon_id = $request->sube;
            $alacak_kaydi->user_id = $adisyon->user_id;
            $alacak_kaydi->save();
        }
        return self::adisyon_tahsilatlari($request,'Tahsilat kaydı başarıyla eklendi');
    }
    public function personelcihazhizmetlerinigetir(Request $request)
    {
        $html = '';
        $hizmetidler = array();
        if($request->personel_id != '')
        {
            $personelsunulanhizmetler = PersonelHizmetler::where('personel_id',$request->personel_id)->get();
            foreach($personelsunulanhizmetler as $personelsunulanhizmet)
                array_push($hizmetidler,$personelsunulanhizmet->hizmet_id);
        }
        if($request->cihaz_id != '')
        {
            $cihazsunulanhizmetler = CihazHizmetler::where('cihaz_id',$request->cihaz_id)->get();
            foreach($cihazsunulanhizmetler as $cihazsunulanhizmet)
                array_push($hizmetidler,$cihazsunulanhizmet->hizmet_id);
        }
        $secilihizmetler = Hizmetler::whereIn('id',array_unique($hizmetidler))->get();
        foreach($secilihizmetler as $secilihizmet)
            $html .= '<option value="'.$secilihizmet->id.'">'.$secilihizmet->hizmet_adi.'</option>';
        return $html;
    }

    // Randevu duzenle modali icin: randevu + hizmetleri JSON formatinda doner (ekleme modal template'i ile uyumlu)
    public function randevuDuzenleJson(Request $request)
    {
        try {
            $randevu_id = $request->randevu_id;
            if(!$randevu_id) return response()->json(['error' => 'randevu_id gerekli'], 400);

            $randevu = Randevular::where('id', $randevu_id)->first();
            if(!$randevu) return response()->json(['error' => 'Randevu bulunamadı'], 404);

            $hizmetler = RandevuHizmetler::with('hizmetler')->where('randevu_id', $randevu_id)->get()->map(function($rh){
                // Hizmet_id=0 (on gorusme) veya silinmis hizmet -> fallback ad uret
                $adi = '';
                if ($rh->hizmetler) {
                    $adi = $rh->hizmetler->hizmet_adi;
                } elseif ((int) $rh->hizmet_id === 0) {
                    $adi = 'Ön Görüşme';
                } else {
                    $adi = 'Hizmet #' . $rh->hizmet_id;
                }
                return [
                    'randevu_hizmet_id' => $rh->id,
                    'hizmet_id' => $rh->hizmet_id,
                    'hizmet_adi' => $adi,
                    'personel_id' => $rh->personel_id,
                    'cihaz_id' => $rh->cihaz_id,
                    'oda_id' => $rh->oda_id,
                    'saat' => $rh->saat ?? null,
                    'sure_dk' => (int) ($rh->sure_dk ?? 0),
                    'fiyat' => (float) ($rh->fiyat ?? 0),
                    'dusum_miktari' => (int) ($rh->dusum_miktari ?? 1),
                ];
            })->values();

            $musteri_adi = '';
            if($randevu->user_id){
                $musteri = \App\User::where('id', $randevu->user_id)->first();
                if($musteri) $musteri_adi = $musteri->name;
            }

            return response()->json([
                'randevu_id' => $randevu->id,
                'musteri_id' => $randevu->user_id,
                'musteri_adi' => $musteri_adi,
                'tarih' => $randevu->tarih,
                'saat' => $randevu->saat,
                'personel_notu' => $randevu->personel_notu ?? '',
                'sms_hatirlatma' => (bool) ($randevu->sms_hatirlatma ?? false),
                'hizmetler' => $hizmetler,
            ]);
        } catch (\Exception $e) {
            return response()->json(['error' => 'Sunucu hatası: ' . $e->getMessage()], 500);
        }
    }

    // Randevu modali icin: tum hizmetler + personel/cihaz eslemeleri (tek AJAX)
    public function randevuModalHizmetVerisi(Request $request)
    {
        $isletmeid = self::mevcutsube($request);
        $salon_hizmetler = SalonHizmetler::with('hizmetler:id,hizmet_adi,hizmet_kategori_id')
            ->where('salon_id',$isletmeid)
            ->where('aktif',1)
            ->whereNull('santral_hizmeti')
            ->get();

        $kategori_idleri = $salon_hizmetler->pluck('hizmet_kategori_id')->filter()->unique()->values()->all();
        $kategoriler = Hizmet_Kategorisi::whereIn('id',$kategori_idleri)->pluck('hizmet_kategorisi_adi','id')->toArray();

        $tum_hizmetler = $salon_hizmetler->filter(function($sh){ return $sh->hizmetler !== null; })
            ->map(function($sh) use ($kategoriler){
                $kat_id = $sh->hizmet_kategori_id ?: ($sh->hizmetler ? $sh->hizmetler->hizmet_kategori_id : null);
                return [
                    'id' => $sh->hizmet_id,
                    'ad' => $sh->hizmetler->hizmet_adi,
                    'sure' => (int) $sh->sure_dk,
                    'fiyat' => (float) $sh->baslangic_fiyat,
                    'kategori' => ($kat_id && isset($kategoriler[$kat_id])) ? $kategoriler[$kat_id] : '',
                ];
            })->values();

        $hizmet_idleri = $salon_hizmetler->pluck('hizmet_id')->toArray();
        $personel_hizmet_map = new \stdClass();
        $cihaz_hizmet_map = new \stdClass();

        if(!empty($hizmet_idleri)){
            $pm = [];
            $rows = \DB::table('personel_sunulan_hizmetler')
                ->join('salon_personelleri','personel_sunulan_hizmetler.personel_id','=','salon_personelleri.id')
                ->where('salon_personelleri.salon_id',$isletmeid)
                ->whereIn('personel_sunulan_hizmetler.hizmet_id',$hizmet_idleri)
                ->select('personel_sunulan_hizmetler.personel_id','personel_sunulan_hizmetler.hizmet_id')
                ->get();
            foreach($rows as $r){
                if(!isset($pm[$r->personel_id])) $pm[$r->personel_id] = [];
                $pm[$r->personel_id][] = (int)$r->hizmet_id;
            }
            $personel_hizmet_map = (object) $pm;

            $cm = [];
            $rows = \DB::table('cihaz_sunulan_hizmetler')
                ->join('cihazlar','cihaz_sunulan_hizmetler.cihaz_id','=','cihazlar.id')
                ->where('cihazlar.salon_id',$isletmeid)
                ->whereIn('cihaz_sunulan_hizmetler.hizmet_id',$hizmet_idleri)
                ->select('cihaz_sunulan_hizmetler.cihaz_id','cihaz_sunulan_hizmetler.hizmet_id')
                ->get();
            foreach($rows as $r){
                if(!isset($cm[$r->cihaz_id])) $cm[$r->cihaz_id] = [];
                $cm[$r->cihaz_id][] = (int)$r->hizmet_id;
            }
            $cihaz_hizmet_map = (object) $cm;
        }

        // Oda -> hizmet eslesmesi (v2 modal filtresi icin gerekli; blade'den de aliniyordu ama
        // ensureHizmetVerisi cagrilarinda dinamik yenilenebilsin diye burada da donduruyoruz).
        $oda_hizmet_map = new \stdClass();
        if (\Schema::hasTable('oda_sunulan_hizmetler')) {
            $om = [];
            $rows = \DB::table('oda_sunulan_hizmetler')
                ->where('salon_id', $isletmeid)
                ->select('oda_id','hizmet_id')
                ->get();
            foreach($rows as $r){
                if(!isset($om[$r->oda_id])) $om[$r->oda_id] = [];
                $om[$r->oda_id][] = (int)$r->hizmet_id;
            }
            $oda_hizmet_map = (object) $om;
        }

        // Oda -> personel eslesmesi (Odaya gore takvimde oda secince personel filtresi)
        // NOT: salon_id filtresi yerine salonun oda_id'lerini sinir olarak kullaniyoruz.
        // oda_personelleri.salon_id NULL olabilir; diger sistem sorgulari (ApiController
        // getOdaPersoneli) sadece oda_id ile filtreliyor.
        $oda_personel_map = new \stdClass();
        if (\Schema::hasTable('oda_personelleri')) {
            $salonOdaIds = \DB::table('odalar')->where('salon_id', $isletmeid)->pluck('id')->toArray();
            if(count($salonOdaIds) > 0){
                $opm = [];
                $rows = \DB::table('oda_personelleri')
                    ->whereIn('oda_id', $salonOdaIds)
                    ->select('oda_id','personel_id')
                    ->get();
                foreach($rows as $r){
                    if(!isset($opm[$r->oda_id])) $opm[$r->oda_id] = [];
                    $opm[$r->oda_id][] = (int)$r->personel_id;
                }
                $oda_personel_map = (object) $opm;
                \Log::info('[v2 oda_personel_map]', ['salon_id'=>$isletmeid, 'oda_count'=>count($salonOdaIds), 'row_count'=>count($rows), 'map_keys'=>array_keys($opm)]);
            }
        }

        return response()->json([
            'tum_hizmetler' => $tum_hizmetler,
            'personel_hizmet_map' => $personel_hizmet_map,
            'cihaz_hizmet_map' => $cihaz_hizmet_map,
            'oda_hizmet_map' => $oda_hizmet_map,
            'oda_personel_map' => $oda_personel_map,
        ]);
    }

    // Randevu modali icin: personel/cihaz'a atanmis hizmetleri sure+fiyat ile JSON doner
    // Fallback: personel/cihaz filtresi var ama sonuc bossa, ya da hepsi=1 ise tum aktif hizmetler doner
    public function personelCihazHizmetleriJson(Request $request)
    {
        $isletmeid = self::mevcutsube($request);
        $hepsi = $request->hepsi == 1 || $request->hepsi === '1' || $request->hepsi === true;
        $hizmet_idleri = [];
        $filtre_verildi = false;

        if(!$hepsi && $request->personel_id != ''){
            $filtre_verildi = true;
            $hizmet_idleri = array_merge($hizmet_idleri, PersonelHizmetler::where('personel_id',$request->personel_id)->pluck('hizmet_id')->toArray());
        }
        if(!$hepsi && $request->cihaz_id != ''){
            $filtre_verildi = true;
            $hizmet_idleri = array_merge($hizmet_idleri, CihazHizmetler::where('cihaz_id',$request->cihaz_id)->pluck('hizmet_id')->toArray());
        }
        $hizmet_idleri = array_values(array_unique($hizmet_idleri));

        $query = SalonHizmetler::with('hizmetler:id,hizmet_adi,hizmet_kategori_id')
            ->where('salon_id',$isletmeid)
            ->where('aktif',1)
            ->whereNull('santral_hizmeti');

        // Filtre verilmediyse veya filtre sonucu bossa (fallback) -> tum aktif hizmetler
        if($filtre_verildi && !empty($hizmet_idleri)){
            $query->whereIn('hizmet_id', $hizmet_idleri);
        }
        $salon_hizmetler = $query->get();

        // Kategori adlari tek sorguda
        $kategori_idleri = $salon_hizmetler->pluck('hizmet_kategori_id')->filter()->unique()->values()->all();
        $kategoriler = Hizmet_Kategorisi::whereIn('id',$kategori_idleri)->pluck('hizmet_kategorisi_adi','id')->toArray();

        $results = $salon_hizmetler->filter(function($sh){ return $sh->hizmetler !== null; })
            ->map(function($sh) use ($kategoriler){
                $kat_id = $sh->hizmet_kategori_id ?: ($sh->hizmetler ? $sh->hizmetler->hizmet_kategori_id : null);
                return [
                    'id' => $sh->hizmet_id,
                    'ad' => $sh->hizmetler->hizmet_adi,
                    'sure' => (int) $sh->sure_dk,
                    'fiyat' => (float) $sh->baslangic_fiyat,
                    'kategori' => ($kat_id && isset($kategoriler[$kat_id])) ? $kategoriler[$kat_id] : '',
                ];
            })->values();

        return response()->json([
            'results' => $results,
            'fallback' => !($filtre_verildi && !empty($hizmet_idleri)), // frontend'e fallback durumu bildir
        ]);
    }

    public function taksitleri_getir(Request $request,$filtre,$musteriid)
    {
           
         $subeId = self::mevcutsube($request);
    
    $sql = "
        SELECT 
            t.id,
            t.user_id,
            t.adisyon_id,
            t.salon_id,
            u.name as ad_soyad,
            COUNT(v.id) as toplam_vade_sayisi,
            SUM(CASE WHEN v.odendi = 1 THEN 1 ELSE 0 END) as odenen_sayisi,
            SUM(CASE WHEN v.odendi = 0 THEN 1 ELSE 0 END) as odenmeyen_sayisi,
            MIN(CASE WHEN v.odendi = 0 THEN v.vade_tarih END) as en_yakin_vade_tarihi,
            (SELECT v2.vade_tarih FROM taksit_vadeleri v2 
             WHERE v2.taksitli_tahsilat_id = t.id AND v2.odendi = 0 
             ORDER BY v2.vade_tarih ASC LIMIT 1) as en_yakin_tarih
        FROM taksitli_tahsilatlar t
        INNER JOIN users u ON t.user_id = u.id
        LEFT JOIN taksit_vadeleri v ON t.id = v.taksitli_tahsilat_id
        WHERE t.salon_id = ?
    ";
    
    $params = [$subeId];
    
    if ($musteriid) {
        $sql .= " AND t.user_id = ?";
        $params[] = $musteriid;
    }
    
    $sql .= " GROUP BY t.id, t.user_id, t.adisyon_id, t.salon_id, u.name";
    
    // Filtreleri HAVING ile ekle
    if ($filtre === 0) {
        $sql .= " HAVING odenmeyen_sayisi > 0";
    } elseif ($filtre === 1) {
        $sql .= " HAVING odenmeyen_sayisi = 0";
    } elseif ($filtre === 2) {
        $sql .= " HAVING odenmeyen_sayisi > 0 AND en_yakin_vade_tarihi <= CURDATE()";
    }
    
    $results = DB::select($sql, $params);
    
    // HTML formatlama
    return collect($results)->map(function($item) {
        $durum = $item->odenmeyen_sayisi > 0 ? 'Açık' : 'Kapalı';
        
        if ($item->en_yakin_tarih) {
            $tarih = \Carbon\Carbon::parse($item->en_yakin_tarih);
            $gecikmis = $tarih->isPast();
            $yaklasanVadeHtml = $gecikmis ? 
                sprintf('<span class="btn btn-danger">%s</span>', $tarih->format('d.m.Y')) :
                sprintf('<span>%s</span>', $tarih->format('d.m.Y'));
            $yaklasanVadeTarihi = $tarih->format('d.m.Y');
        } else {
            $yaklasanVadeHtml = '<button class="btn btn-warning">Kapalı Senet</button>';
            $yaklasanVadeTarihi = 'Kapalı Senet';
        }
        
        return (object)[
            'durum' => $durum,
            'ad_soyad' => $item->ad_soyad,
            'vade_sayisi' => sprintf('<button class="btn btn-primary">%d</button>', $item->toplam_vade_sayisi),
            'odenmis' => $item->odenen_sayisi > 0 ? sprintf('<button class="btn btn-success">%d</button>', $item->odenen_sayisi) : null,
            'odenmemis' => $item->odenmeyen_sayisi > 0 ? sprintf('<button class="btn btn-danger">%d</button>', $item->odenmeyen_sayisi) : null,
            'yaklasan_vade' => $yaklasanVadeHtml,
            'yaklasan_vade_tarihi' => $yaklasanVadeTarihi,
            'islemler' => sprintf(
                '<a href="#" name="taksit_vadeleri" data-value="%d" class="btn btn-primary">Detaylar</a> 
                 <a title="Tahsil Et" href="/isletmeyonetim/tahsilat/%d/%d/?sube=%d" class="btn btn-success">
                 <i class="fa fa-money"></i></a>',
                $item->id, $item->user_id, $item->adisyon_id, $item->salon_id
            )
        ];
    });
    }
