    public function whatsapp(Request $request)
    {
        $isletmeler = '';
        $isletme = '';

        if (Auth::guard('satisortakligi')->check()) {
            $isletmeler = [15];
            $isletme = Salonlar::where('id', 15)->first();
        } else {
            $isletmeler = Auth::guard('isletmeyonetim')->user()->yetkili_olunan_isletmeler->where('aktif',1)->pluck('salon_id')->toArray();
            $isletme = Salonlar::where('id', self::mevcutsube($request))->first();
        }

        if (!in_array(self::mevcutsube($request), $isletmeler)) {
            return view('isletmeadmin.yetkisizerisim');
        }
        // WhatsApp yonetimi tum uyelik turlerine acik (uyelik_turu kisitlamasi kaldirildi)
        // WhatsApp ekrani: pazarlama.whatsapp_gonder zorunlu
        $_waAu = Auth::guard('isletmeyonetim')->user();
        if($_waAu && !\App\Services\PersonelYetkiServisi::yetkiliYetkiVar($_waAu->id, self::mevcutsube($request), 'pazarlama.whatsapp_gonder')){
            return view('isletmeadmin.yetkisizerisim');
        }

        if (str_contains(self::lisans_sure_kontrol($request), '-')) {
            return view('isletmeadmin.lisanssurebitti', ['isletme' => $isletme]);
        }

        if (count($isletmeler) > 1 && !isset($_GET['sube'])) {
            return view('isletmeadmin.isletmesec', ['isletmeler' => $isletmeler, 'isletme' => $isletme]);
        }

        $paketler = self::paket_liste_getir('', true, $request);
        $kalan_uyelik_suresi = self::lisans_sure_kontrol($request);

        return view('isletmeadmin.whatsapp', [
            'bildirimler' => self::bildirimgetir($request),
            'paketler' => $paketler,
            'sayfa_baslik' => 'WhatsApp Yönetimi',
            'pageindex' => 65,
            'isletme' => $isletme,
            'kalan_uyelik_suresi' => $kalan_uyelik_suresi,
            'portfoy_drop' => self::musteriportfoydropliste($request),
            'urun_drop' => self::urundropliste($request),
            'hizmet_drop' => self::hizmetdropliste($request),
            'personel_drop' => self::personeldropliste($request, []),
            'yetkiliolunanisletmeler' => $isletmeler,
        ]);
    }

    public function whatsappBaslat(Request $request)
    {
        $salonId = $this->whatsappYetkiliSalon($request);
        if (!$salonId) return response()->json(['error' => 'yetkisiz'], 403);

        $svc = app(\App\Services\WhatsAppService::class);

        // AKILLI BASLAT: gercekten connected degilse eski cached credentials'i
        // sil, fresh QR uret. Aksi halde "Bagli" gozukup numara bos kaliyordu
        // (bridge cached'e reconnect deneyip fail oluyor, QR uretmiyordu).
        $statusRes = $svc->status($salonId);
        $curStatus = $statusRes['body']['status'] ?? '';
        $curPhone  = $statusRes['body']['phone'] ?? null;
        // Gercekten bagliysa (status=connected VE numara var) dokunma
        if ($curStatus !== 'connected' || empty($curPhone)) {
            $svc->logout($salonId);
            usleep(400 * 1000); // 0.4sn bridge'in state temizlemesi icin
        }

        $res = $svc->startSession($salonId);

        if ($res['ok'] ?? false) {
            Salonlar::where('id', $salonId)->update([
                'whatsapp_aktif' => 1,
                'whatsapp_durum' => $res['body']['status'] ?? 'connecting',
                'whatsapp_bridge_tipi' => 'whatsmeow', // whatsmeow-only: bağlantılar yeni köprüden
            ]);
            // Audit
            SalonAudit::log($salonId, 'whatsapp_baglanti_baslat', 'whatsapp', $salonId,
                'WhatsApp oturumu',
                'WhatsApp bağlantı oturumu başlatıldı (QR aşaması)',
                ['durum'=>$res['body']['status'] ?? 'connecting']);
        }
        return response()->json($res['body'] ?? ['error' => 'servis-erisilemiyor'], $res['status'] ?: 502);
    }

    /**
     * QR alternatifi — telefon numarasi ile pair kodu urettir. iPhone bagli
     * cihaz "baglantiyi kontrol edip tekrar deneyin" sorunlarini bypass eder.
     * Kullanici bridge'ten donen 8 haneli kodu telefonun WA Business
     * "Telefon numarasiyla baglan" ekranina girer.
     */
    public function whatsappPairPhone(Request $request)
    {
        $salonId = $this->whatsappYetkiliSalon($request);
        if (!$salonId) return response()->json(['error' => 'yetkisiz'], 403);

        $phone = trim((string) $request->input('phone', ''));
        if ($phone === '') return response()->json(['error' => 'phone-required'], 422);

        $svc = app(\App\Services\WhatsmeowService::class);
        $res = $svc->pairPhone($salonId, $phone);
        return response()->json($res['body'] ?? ['error' => 'servis-erisilemiyor'], $res['status'] ?: 502);
    }

    public function whatsappDurum(Request $request)
    {
        $salonId = $this->whatsappYetkiliSalon($request);
        if (!$salonId) return response()->json(['error' => 'yetkisiz'], 403);

        $svc = app(\App\Services\WhatsAppService::class);
        $res = $svc->status($salonId);
        $body = $res['body'] ?? ['status' => 'servis-kapali'];

        if (($res['ok'] ?? false) && isset($body['status'])) {
            $update = ['whatsapp_durum' => $body['status']];
            if ($body['status'] === 'connected') {
                $salon = Salonlar::find($salonId);
                if ($salon && !$salon->whatsapp_baglanti_tarihi) {
                    $update['whatsapp_baglanti_tarihi'] = now();
                    $update['whatsapp_warmup_baslangic'] = now();
                }
                if (!empty($body['phone'])) $update['whatsapp_numara'] = $body['phone'];
            }
            Salonlar::where('id', $salonId)->update($update);
        }
        return response()->json($body);
    }

    public function whatsappQR(Request $request)
    {
        $salonId = $this->whatsappYetkiliSalon($request);
        if (!$salonId) return response()->json(['error' => 'yetkisiz'], 403);

        $svc = app(\App\Services\WhatsAppService::class);
        $res = $svc->qr($salonId);
        return response()->json($res['body'] ?? ['error' => 'qr-yok'], $res['status'] ?: 404);
