    public function whatsappCikis(Request $request)
    {
        $salonId = $this->whatsappYetkiliSalon($request);
        if (!$salonId) return response()->json(['error' => 'yetkisiz'], 403);

        $_audit_numara = Salonlar::where('id',$salonId)->value('whatsapp_numara');
        $svc = app(\App\Services\WhatsAppService::class);
        $svc->logout($salonId);
        Salonlar::where('id', $salonId)->update([
            'whatsapp_aktif' => 0,
            'whatsapp_durum' => 'cikis-yapildi',
            'whatsapp_numara' => null,
            'whatsapp_baglanti_tarihi' => null,
            'whatsapp_warmup_baslangic' => null,
        ]);
        // Audit
        SalonAudit::log($salonId, 'whatsapp_baglanti_kapat', 'whatsapp', $salonId,
            $_audit_numara ?: 'WhatsApp oturumu',
            'WhatsApp oturumu sonlandırıldı',
            ['eski_numara'=>$_audit_numara]);
        return response()->json(['ok' => true]);
    }

    protected function whatsappYetkiliSalon(Request $request)
    {
        if (Auth::guard('satisortakligi')->check()) return 15;
        $current = self::mevcutsube($request);
        $yetkili = Auth::guard('isletmeyonetim')->user()
            ->yetkili_olunan_isletmeler->where('aktif', 1)
            ->pluck('salon_id')->toArray();
        return in_array($current, $yetkili) ? $current : null;
    }

    // ─── Salon kendi WhatsApp istatistikleri (sadece kendi verisi) ───

    public function whatsappOzetData(Request $request)
    {
        $salonId = $this->whatsappYetkiliSalon($request);
        if (!$salonId) return response()->json(['error' => 'yetkisiz'], 403);

        $today = \Carbon\Carbon::today();
        $weekStart = \Carbon\Carbon::today()->subDays(6);
        $monthStart = \Carbon\Carbon::today()->subDays(29);

        $base = DB::table('whatsapp_gonderim_loglari')->where('salon_id', $salonId);
        $bugunToplam = (clone $base)->whereDate('created_at', $today)->count();
        $bugunBasari = (clone $base)->whereDate('created_at', $today)->where('durum', 1)->count();
        $bugunFail = (clone $base)->whereDate('created_at', $today)->where('durum', 2)->count();
        $bugunFallback = (clone $base)->whereDate('created_at', $today)->where('durum', 3)->count();

        $haftaToplam = (clone $base)->whereDate('created_at', '>=', $weekStart)->count();
        $haftaBasari = (clone $base)->whereDate('created_at', '>=', $weekStart)->where('durum', 1)->count();

        $ayToplam = (clone $base)->whereDate('created_at', '>=', $monthStart)->count();
        $ayBasari = (clone $base)->whereDate('created_at', '>=', $monthStart)->where('durum', 1)->count();

        $basariOrani = $haftaToplam > 0 ? round(($haftaBasari / $haftaToplam) * 100, 1) : 0;

        $salon = Salonlar::find($salonId);

        // Son 30 gün günlük trend
        $start = \Carbon\Carbon::today()->subDays(29);
        $trend = DB::table('whatsapp_gonderim_loglari')
            ->select(DB::raw('DATE(created_at) as tarih'), 'durum', DB::raw('COUNT(*) as adet'))
            ->where('salon_id', $salonId)
            ->whereDate('created_at', '>=', $start)
            ->groupBy('tarih', 'durum')->get();

        $gunler = [];
        for ($i = 0; $i < 30; $i++) {
            $g = \Carbon\Carbon::today()->subDays(29 - $i)->format('Y-m-d');
            $gunler[$g] = ['gun' => $g, 'basari' => 0, 'fail' => 0, 'fallback' => 0];
        }
        foreach ($trend as $r) {
            $key = $r->tarih;
            if (!isset($gunler[$key])) continue;
            if ((int) $r->durum === 1) $gunler[$key]['basari'] = (int) $r->adet;
            if ((int) $r->durum === 2) $gunler[$key]['fail'] = (int) $r->adet;
            if ((int) $r->durum === 3) $gunler[$key]['fallback'] = (int) $r->adet;
        }

        return response()->json([
            'durum' => $salon->whatsapp_durum,
            'numara' => $salon->whatsapp_numara,
            'gunluk_limit' => (int) ($salon->whatsapp_gunluk_limit ?: 150),
            'bugun' => ['toplam' => $bugunToplam, 'basari' => $bugunBasari, 'fail' => $bugunFail, 'fallback' => $bugunFallback],
            'hafta' => ['toplam' => $haftaToplam, 'basari' => $haftaBasari],
            'ay' => ['toplam' => $ayToplam, 'basari' => $ayBasari],
            'basariOrani' => $basariOrani,
            'gunler' => array_values($gunler),
        ]);
    }

    public function whatsappLoglarData(Request $request)
    {
        $salonId = $this->whatsappYetkiliSalon($request);
        if (!$salonId) return response()->json(['error' => 'yetkisiz'], 403);

        // Musteri adi cozumlemesi (oncelik sirasi):
        //   1) wl.user_id -> users.name  (direkt log'a yazilmissa)
        //   2) wl.randevu_id -> randevular.user_id -> users.name (cogu randevu akisi user_id'yi log'a koymaz)
        //   3) wl.telefon -> users.cep_telefon -> users.name (son care, son kaydedilen user)
        // Telefon -> isim eslestirmesi icin alt sorgu (ayni telefonla birden fazla user'da
        // satir cogalmasini onler). MAX(name) -> deterministik tek isim.
        $telefonSubq = '(SELECT cep_telefon, MAX(name) as name FROM users WHERE cep_telefon IS NOT NULL AND cep_telefon != \'\' GROUP BY cep_telefon)';

        $q = DB::table('whatsapp_gonderim_loglari as wl')
            ->leftJoin('users as u', 'u.id', '=', 'wl.user_id')
            ->leftJoin('randevular as r', 'r.id', '=', 'wl.randevu_id')
            ->leftJoin('users as ru', 'ru.id', '=', 'r.user_id')
            ->leftJoin(DB::raw($telefonSubq . ' as pu'), 'pu.cep_telefon', '=', 'wl.telefon')
            ->select('wl.id', 'wl.user_id', 'wl.randevu_id', 'wl.telefon', 'wl.mesaj',
                'wl.durum', 'wl.hata', 'wl.mesaj_id', 'wl.gonderim_tarihi', 'wl.created_at',
                DB::raw('COALESCE(NULLIF(u.name, \'\'), NULLIF(ru.name, \'\'), NULLIF(pu.name, \'\')) as musteri_adi'))
            ->where('wl.salon_id', $salonId);

        if ($durum = $request->input('durum')) $q->where('wl.durum', $durum);
        if ($telefon = $request->input('telefon')) $q->where('wl.telefon', 'like', '%' . $telefon . '%');
        if ($baslangic = $request->input('baslangic')) $q->whereDate('wl.created_at', '>=', $baslangic);
        if ($bitis = $request->input('bitis')) $q->whereDate('wl.created_at', '<=', $bitis);
        if ($arama = $request->input('arama')) $q->where('wl.mesaj', 'like', '%' . $arama . '%');

        $perPage = min((int) $request->input('per_page', 50), 200);
        $page = max((int) $request->input('page', 1), 1);
        $toplam = (clone $q)->count();
        $rows = $q->orderByDesc('wl.id')->offset(($page - 1) * $perPage)->limit($perPage)->get();

        return response()->json([
            'rows' => $rows, 'toplam' => $toplam,
            'page' => $page, 'per_page' => $perPage,
            'son_sayfa' => (int) ceil($toplam / $perPage),
        ]);
    }

    public function whatsappAlicilarData(Request $request)
    {
        $salonId = $this->whatsappYetkiliSalon($request);
        if (!$salonId) return response()->json(['error' => 'yetkisiz'], 403);

        // Telefon -> isim eslestirmesi: user_id bos olan kayitlar icin telefon uzerinden COALESCE.
        $telefonSubq = '(SELECT cep_telefon, MAX(name) as name FROM users WHERE cep_telefon IS NOT NULL AND cep_telefon != \'\' GROUP BY cep_telefon)';

        $rows = DB::table('whatsapp_gonderim_loglari as wl')
            ->leftJoin('users as u', 'u.id', '=', 'wl.user_id')
            ->leftJoin(DB::raw($telefonSubq . ' as pu'), 'pu.cep_telefon', '=', 'wl.telefon')
            ->select(
                'wl.telefon',
                DB::raw('COALESCE(NULLIF(MAX(u.name), \'\'), NULLIF(MAX(pu.name), \'\')) as musteri_adi'),
                DB::raw('COUNT(*) as toplam'),
                DB::raw('SUM(CASE WHEN wl.durum = 1 THEN 1 ELSE 0 END) as basari'),
                DB::raw('SUM(CASE WHEN wl.durum = 2 THEN 1 ELSE 0 END) as fail'),
                DB::raw('SUM(CASE WHEN wl.durum = 3 THEN 1 ELSE 0 END) as fallback'),
                DB::raw('MAX(wl.created_at) as son_mesaj'),
                DB::raw('MIN(wl.created_at) as ilk_mesaj')
            )
            ->where('wl.salon_id', $salonId)
            ->groupBy('wl.telefon')
            ->orderByDesc('son_mesaj')
            ->limit(500)
            ->get();

        return response()->json(['rows' => $rows, 'toplam' => $rows->count()]);
    }

    public function whatsappAliciGecmisData(Request $request, $telefon)
    {
        $salonId = $this->whatsappYetkiliSalon($request);
        if (!$salonId) return response()->json(['error' => 'yetkisiz'], 403);

        $rows = DB::table('whatsapp_gonderim_loglari')
            ->where('salon_id', $salonId)
            ->where('telefon', $telefon)
            ->orderByDesc('created_at')
            ->limit(100)
            ->get(['id', 'mesaj', 'durum', 'hata', 'mesaj_id', 'gonderim_tarihi', 'created_at', 'randevu_id']);

        return response()->json(['rows' => $rows]);
    }

    public function whatsappPaketDurum(Request $request)
    {
        $salonId = $this->whatsappYetkiliSalon($request);
        if (!$salonId) return response()->json(['error' => 'yetkisiz'], 403);

        $salon = Salonlar::find($salonId);
        $bitis = $salon->whatsapp_paket_bitis;
        $kalanGun = null;
        if ($bitis) {
            $kalanGun = max(0, \Carbon\Carbon::now()->diffInDays(\Carbon\Carbon::parse($bitis), false));
        }

        return response()->json([
            'paket' => $salon->whatsapp_paket ?: 'baslangic',
            'periyot' => $salon->whatsapp_paket_periyot,
            'baslangic' => optional($salon->whatsapp_paket_baslangic)->format('Y-m-d'),
            'bitis' => optional($salon->whatsapp_paket_bitis)->format('Y-m-d'),
            'deneme' => (bool) $salon->whatsapp_paket_deneme,
            'kalan_gun' => $kalanGun,
        ]);
    }

    public function whatsappPaketTalep(Request $request)
    {
        $paket = $request->input('paket');

        // ── KONTÖR talebi (yeni model) — 'kontor_XXXX' ise sistem sahibine WA+SMS bildirim gönder.
        // YETKİ KONTROLÜNDEN ÖNCE + esnek salon çözümü (mevcutsube) — impersonation/test'te de çalışsın.
        // Mevcut (route-cache'te kayıtlı) endpoint'e bindirildi, yeni rota yok.
        if (is_string($paket) && strpos($paket, 'kontor_') === 0) {
            $salonId = (int) self::mevcutsube($request);
            $paketler = [
                'kontor_10000'  => ['ad'=>'10.000 Kontör',  'fiyat'=>'2.850 TL'],
                'kontor_20000'  => ['ad'=>'20.000 Kontör',  'fiyat'=>'5.300 TL'],
                'kontor_40000'  => ['ad'=>'40.000 Kontör',  'fiyat'=>'9.800 TL'],
                'kontor_60000'  => ['ad'=>'60.000 Kontör',  'fiyat'=>'13.800 TL'],
                'kontor_80000'  => ['ad'=>'80.000 Kontör',  'fiyat'=>'17.000 TL'],
                'kontor_100000' => ['ad'=>'100.000 Kontör', 'fiyat'=>'20.000 TL'],
            ];
            if (!isset($paketler[$paket])) {
                return response()->json(['ok'=>false,'mesaj'=>'Geçersiz paket.'],422);
            }
            $salonK    = Salonlar::find($salonId);
            $p         = $paketler[$paket];
            $iletisimK = trim((string) $request->input('iletisim', ''));
            $telK      = $salonK ? ($salonK->yetkili_telefon ?: ($salonK->telefon_1 ?: '')) : '';
            $mesajK = "💰 KONTÖR TALEBİ\n"
                . "Salon: " . ($salonK->salon_adi ?? '-') . "\n"
                . "Paket: " . $p['ad'] . " (" . $p['fiyat'] . ")\n"
                . ($salonK && $salonK->yetkili_adi ? ("Yetkili: " . $salonK->yetkili_adi . "\n") : '')
                . ($telK ? ("Tel: " . $telK . "\n") : '')
                . ($iletisimK !== '' ? ("İletişim/Not: " . mb_substr($iletisimK, 0, 120) . "\n") : '')
                . "ID: " . $salonId . "\n"
                . date('d.m.Y H:i');

            $rK = \App\Services\SistemBildirim::gonder($mesajK);
            if (empty($rK['ok'])) {
                $teshisK = 'Bildirim kanalı kapalı/numara yok — Sistem WhatsApp ayarını kontrol et.';
            } else {
                $waK  = $rK['detay']['wa'] ?? [];
                $smsK = $rK['detay']['sms'] ?? [];
                $teshisK = (!empty($waK['ok']) ? 'WA kuyruğa alındı ✓' : ('WA gitmedi (' . ($waK['error'] ?? ('http ' . ($waK['status'] ?? '?'))) . ')'))
                    . ' | ' . (!empty($smsK['ok']) ? 'SMS gönderildi ✓' : ('SMS gitmedi (' . ($smsK['durum'] ?? 'hata') . ')'));
            }
            \Log::info('[KONTOR-TALEP]', ['salon_id'=>$salonId, 'paket'=>$paket, 'bildirim_ok'=>$rK['ok'] ?? false, 'teshis'=>$teshisK]);
            return response()->json(['ok'=>true, 'mesaj'=>'Talebiniz alındı. En kısa sürede sizinle iletişime geçeceğiz. 🙌', 'teshis'=>$teshisK]);
        }

        // Abonelik talebi (eski model) — strict yetki kontrolü
        $salonId = $this->whatsappYetkiliSalon($request);
        if (!$salonId) return response()->json(['error' => 'yetkisiz'], 403);

        $periyot = $request->input('periyot');
        $iletisim = trim((string) $request->input('iletisim', ''));

        if (!in_array($paket, ['pro', 'premium'])) {
            return response()->json(['error' => 'gecersiz-paket'], 400);
        }
        if (!in_array($periyot, ['aylik', 'yillik'])) {
            return response()->json(['error' => 'gecersiz-periyot'], 400);
        }

        $salon = Salonlar::find($salonId);
        $user = Auth::guard('isletmeyonetim')->user();

        try {
            $bildirim = new \App\Bildirimler();
            $bildirim->aciklama = "📦 PAKET YÜKSELTME TALEBİ — {$salon->salon_adi} (#{$salon->id}) → "
                . strtoupper($paket) . ' / ' . ucfirst($periyot)
                . ' — İletişim: ' . ($iletisim ?: ($user->email ?? '-'));
            $bildirim->salon_id = $salonId;
            $bildirim->url = '/sistemyonetim/isletmedetay/' . $salonId;
            $bildirim->tarih_saat = date('Y-m-d H:i:s');
            $bildirim->okundu = false;
            $bildirim->save();
        } catch (\Throwable $e) {
            \Illuminate\Support\Facades\Log::warning('Paket talep bildirimi yazılamadı', ['err' => $e->getMessage()]);
        }

        \Illuminate\Support\Facades\Log::info('[WA Paket] talep alındı', [
            'salon_id' => $salonId,
            'paket' => $paket,
            'periyot' => $periyot,
            'iletisim' => $iletisim,
        ]);

        return response()->json([
            'ok' => true,
            'mesaj' => 'Talebiniz alındı. Müşteri temsilcimiz en kısa sürede sizinle iletişime geçecek.',
        ]);
    }

    /**
     * Randevu hareketlerinde (iptal, güncelleme, onay vs.) mesaj kuyruğuna ekleme helper'i.
     * Toggle (musteri/personel) açıksa $mesajlar'a yazar. WhatsApp yonlendirmesi
     * sms_gonder_bildirimli icinde otomatik yapilir (salon WA aktif+connected ise).
     */
    protected function smsVeyaWhatsappGonder($salon, $to, $message, $ayarId, $alanAdi, $randevuId, $userId, array &$mesajlar)
    {
        if (!$to || !$salon) return;

        $ayar = SalonSMSAyarlari::where('salon_id', $salon->id)->where('ayar_id', $ayarId)->first();
        if (!$ayar) return;

        if ((int) ($ayar->{$alanAdi} ?? 0) === 1) {
            $mesajlar[] = ['to' => $to, 'message' => $message, 'randevu_id' => $randevuId, 'user_id' => $userId];
        }
    }

    public function whatsappKanalDurum(Request $request)
    {
        $salonId = $this->whatsappYetkiliSalon($request);
        if (!$salonId) return response()->json(['error' => 'yetkisiz'], 403);

        $ayar1 = \App\SalonSMSAyarlari::where('salon_id', $salonId)->where('ayar_id', 1)->first();
        $ayar6 = \App\SalonSMSAyarlari::where('salon_id', $salonId)->where('ayar_id', 6)->first();

        $aktif = ($ayar1 && (int) $ayar1->whatsapp_musteri === 1)
              || ($ayar6 && (int) $ayar6->whatsapp_musteri === 1);

        return response()->json([
            'aktif' => $aktif,
            'sms_aktif_aynigun' => $ayar1 ? (int) $ayar1->musteri === 1 : false,
            'sms_aktif_24sa' => $ayar6 ? (int) $ayar6->musteri === 1 : false,
        ]);
    }

    public function whatsappKanalToggle(Request $request)
    {
        $salonId = $this->whatsappYetkiliSalon($request);
        if (!$salonId) return response()->json(['error' => 'yetkisiz'], 403);

        $yeniDeger = (int) $request->input('aktif', 0) === 1 ? 1 : 0;

        foreach ([1, 6] as $ayarId) {
            $ayar = \App\SalonSMSAyarlari::where('salon_id', $salonId)->where('ayar_id', $ayarId)->first();
            if (!$ayar) {
                $ayar = new \App\SalonSMSAyarlari();
                $ayar->salon_id = $salonId;
                $ayar->ayar_id = $ayarId;
                $ayar->musteri = 0;
                $ayar->personel = 0;
            }
            $ayar->whatsapp_musteri = $yeniDeger;
            $ayar->save();
        }

        return response()->json([
            'ok' => true,
            'aktif' => $yeniDeger === 1,
        ]);
    }
    

