        if(self::haftanin_gunu(date('Y-m-d'))==1)
            $interval = '-3 days';*/
        $rol = self::kullaniciRolu(self::mevcutsube($request),Auth::guard('isletmeyonetim')->user()->id);
        $santral_raporlari="";
        if($rol < 5)
            $santral_raporlari = self::santral_raporlari($isletme->id,date('Y-m-d'),date('Y-m-d'),'',$request);
        $kalan_uyelik_suresi = self::lisans_sure_kontrol($request);
        $santral_ayarlari = SalonSantralAyarlari::where('salon_id',self::mevcutsube($request))->get();
        return view('isletmeadmin.santral',['kullaniciRolu'=>$rol,'bildirimler'=>self::bildirimgetir($request),'paketler'=>$paketler,'sayfa_baslik'=>'Santral Sistemi & Aramalar','pageindex' => 43,'isletme'=>$isletme,'kalan_uyelik_suresi'=>$kalan_uyelik_suresi, 'santral_raporlari'=>$santral_raporlari,
            'santral_ayarlari' => $santral_ayarlari,'urun_drop'=>self::urundropliste($request),'hizmet_drop'=>self::hizmetdropliste($request),
            'personel_drop'=>self::personeldropliste($request,array()),'yetkiliolunanisletmeler'=>$isletmeler
    ]);
    }
    public function cdr_rapor_filtre(Request $request)
    {
        $baslangic = date('Y-m-d');
        $bitis = date('Y-m-d');
        if(isset($request->cdr_baslangic_tarihi))
        {
            if($request->cdr_baslangic_tarihi!='')
                $baslangic = $request->cdr_baslangic_tarihi;
        }
        if(isset($request->cdr_bitis_tarihi)){
            if($request->cdr_bitis_tarihi!='')
                $bitis = $request->cdr_bitis_tarihi;
        }
        return self::santral_raporlari($request->sube,$baslangic,$bitis,'',$request);
    }


    public function santral_raporlari($salon_id,$tarih1,$tarih2,$durum,$request)
    {
         
        $dahililer = Personeller::where('salon_id',$salon_id)->where('dahili_no','!=',null)->pluck('dahili_no')->toArray();
        $trunk = SabitNumaralar::where('salon_id',$salon_id)->value('numara');
        $queryStr = '?offset='.$request->offset.'&';
        foreach($dahililer as $key=>$dahili)
        {
            $queryStr .= 'dahililer[]='.$dahili;
            if($key+1 < count($dahililer))
                $queryStr .= '&';
                
        }

        //$queryStr .= 'trunk='.SabitNumaralar::where('salon_id',$salon_id)->value('numara');
        if($tarih1 != '')
            $queryStr .= '&tarih1='.$tarih1;
        if($tarih2 != '')
            $queryStr .= '&tarih2='.$tarih2;
        if($trunk)
            $queryStr .= '&did='.$trunk;
        $gelen_arama=0;
        $giden_arama =0;
        $basarisiz_arama=0;
        $cevapsiz_arama=0;
        
        $endpoint = "https://santral.randevumcepte.com.tr/monitor/api/freepbxapi.php".$queryStr;
        
        Log::info('santral endpoint '.$endpoint);
        $ch = curl_init();
        curl_setopt($ch, CURLOPT_URL, $endpoint);
        curl_setopt($ch, CURLOPT_RETURNTRANSFER, true); // çıktıyı string döndürsün
        $results = json_decode(curl_exec($ch), true);
         
       
        if (curl_errno($ch)) {
            return 'Curl error: ' . curl_error($ch);
        } else {
          
            $rapor = array();
            $cdrListesi = isset($results['data']) && is_array($results['data']) ? $results['data'] : (is_array($results) ? $results : []);
            foreach($cdrListesi as $key=>$result){
                if(!is_array($result)) continue;
                // GUVENLI ayiklama: SADECE bizim originate'te koydugumuz "cmerkezi" etiketini
                // tasiyan cagrilar atlanir (agent-first cagri merkezi aramalari). Normal aramalarda
                // bu etiket olmadigi icin onlara DOKUNMAZ; etiket CDR'a yansimazsa filtre no-op.
                if ((($result['accountcode'] ?? '') === 'cmerkezi') || (($result['userfield'] ?? '') === 'cmerkezi')) {
                    continue;
                }
                $raporaEkle = false;
                $durum = '';
                $musteriAdi = '';
                $dahili = '';
                $telefon = '';
                $avatar = '';
                $channel = $result['channel'] ?? '';
                $aramaButonu = '';
                $sesKaydi = '';
                $dahili = '';
                if ($channel && preg_match('/^[^\/]+\/([^-\s]+)/', $channel, $m)) {
                    $dahili = preg_replace('/\D/', '', $m[1]); // sadece rakamları alır
                }

                if(($result['dcontext'] ?? '')=='from-internal')
                {
                    // Hedef bir personel mi (dahili-dahili) yoksa dis numara mi?
                    $hedefDahili = Personeller::where('dahili_no', $result['dst'] ?? '')->first();

                    if(($result['disposition'] ?? '')=='NO ANSWER' || ($result['disposition'] ?? '')=='BUSY'){
                        $durum = '<button class="btn btn-danger">ULAŞILAMADI</button>';
                        $basarisiz_arama++;
                    }
                    else{
                        // GIDEN rozeti dahili-dahili'yi de kapsar (DataTables 'GİDEN' filtresi
                        // sekmesinde gozuksun diye). Dahili-dahili oldugu musteri sutununda
                        // 'Personel Adi (Dahili)' formatiyla zaten ayirt ediliyor.
                        $durum = '<button class="btn btn-primary">GİDEN</button>'
                            . ($hedefDahili ? ' <small class="text-muted">(dahili)</small>' : '');
                        $giden_arama++;
                        if (!empty($result['recording_path'])) {
                            $sesKaydi = '<button name="ses_kaydi_cal" data-value="'.$result['recording_path'].'" class="btn btn-danger"><i class="fa fa-play"></i></button>';
                        }
                    }

                    if ($hedefDahili) {
                        $musteriAdi = $hedefDahili->personel_adi.' ('.$hedefDahili->dahili_no.')';
                        $telefon = $hedefDahili->dahili_no;
                        $avatar = '/public/isletmeyonetim_assets/img/avatar.png';
                    } else {
                        $musteri = User::where('cep_telefon',str_replace(["(",")"," "],["","",""],preg_replace('/^\+?90/', '', $result['dst'] ?? '')))->first();
                        if($musteri){
                            $musteriAdi = $musteri->name.' ('.$musteri->cep_telefon.')';
                            $aramaButonu = '<button title="Ara" class="btn btn-success" name="musteriyi_ara" style="margin-right:2px" data-value="0'.$musteri->cep_telefon.'"><i class="fa fa-phone"></i></button>';
                            $telefon = $musteri->cep_telefon;
                            $avatar = $musteri->profil_resim ?  $musteri->profil_resim : '/public/isletmeyonetim_assets/img/avatar.png' ;
                        }
                        else{
                            $musteriAdi = ltrim($result['dst'] ?? '', "0");
                            $telefon = ltrim($result['dst'] ?? '', "0");
                            $aramaButonu = '<button title="Ara" class="btn btn-success" name="musteriyi_ara" style="margin-right:2px" data-value="0'.$telefon.'"><i class="fa fa-phone"></i></button>';
                            $avatar = '/public/isletmeyonetim_assets/img/avatar.png' ;
                        }
                    }

                    // Aramayi yapan personel (channel'dan cikarilan dahili)
                    $kaynakPersonel = $dahili !== '' ? Personeller::where('dahili_no', $dahili)->first() : null;
                    $dahili = $kaynakPersonel ? $kaynakPersonel->personel_adi.' ('.$kaynakPersonel->dahili_no.')' : ($dahili !== '' ? 'Dahili '.$dahili : '');

                    $raporaEkle = true;
                }
                else{
                     
                    if($result['dcontext']=='ana-menu' )
                    {
                        $durum = '<button class="btn btn-dark">SONUÇSUZ</button>';
                        $cevapsiz_arama++;
                        $raporaEkle = true;
                    }
                    if($result['dcontext'] == 'yol-tarifi')
                    {
                            $durum = '<button class="btn btn-info">YOL TARİFİ</button>';
                            $gelen_arama++;
                            $raporaEkle = true;
                    }
                    if($result['dcontext']=='kampanya-tanitimyeni')
                    {
                        $durum = '<button class="btn btn-warning">KAMPANYA TANITIMI</button>';
                        $gelen_arama++;
                        $raporaEkle = true;
                            

                    }
                    if($result['dcontext']=='yeni-randevu-menusu')
                    {
                        $durum = '<button class="btn btn-primary">RANDEVU ALMA</button>';
                        $gelen_arama++;
                        $raporaEkle = true;
                            

                    }
                    if($result['dcontext']=='randevu-guncelleme-menusu')
                    {
                        $durum = '<button class="btn btn-primary">RANDEVU GÜNCELLEME</button>';
                        $gelen_arama++;
                        $raporaEkle = true;
                            

                    }
                    if($result['dcontext']=='randevu-iptal-menusu')
                    {
                        $durum = '<button class="btn btn-primary">RANDEVU İPTALİ</button>';
                        $gelen_arama++;
                        $raporaEkle = true;
                            

                    }
                    if($result['dcontext']=='ext-local')
                    {
                        if($result['disposition']=='NO ANSWER' || $result['disposition']=='BUSY')
                        {
                            $durum = '<button class="btn btn-danger">CEVAPSIZ</button>';
                            $cevapsiz_arama++;
                            $raporaEkle = true;
                        }
                        else
                        {
                            $durum = '<button class="btn btn-success">GELEN</button>';
                             $sesKaydi  = '<button name="ses_kaydi_cal" data-value="'.$result['recording_path'].'" class="btn btn-danger"><i class="fa fa-play"></i></button>';
                            $gelen_arama++;
                            $raporaEkle = true;
                        } 

                    }
                    if($raporaEkle)
                    {
                        $musteri = User::where('cep_telefon',str_replace(["(",")"," "],["","",""],preg_replace('/^\+?90/', '', $result['src'])))->first();
                        if($musteri){
                            $aramaButonu = '<button title="Ara" class="btn btn-success" name="musteriyi_ara" style="margin-right:2px" data-value="0'.$musteri->cep_telefon.'"><i class="fa fa-phone"></i></button>';
                            $musteriAdi = $musteri->name.' ('.$musteri->cep_telefon.')';
                            $telefon = $musteri->cep_telefon;
                            $avatar = $musteri->profil_resim ?  $musteri->profil_resim : '/public/isletmeyonetim_assets/img/avatar.png' ;
                        }
                            
                        else{
                            $musteriAdi = ltrim($result['src'], "0");

                            $telefon = ltrim($result['src'], "0");
                            $aramaButonu = '<button title="Ara" class="btn btn-success" name="musteriyi_ara" style="margin-right:2px" data-value="0'.$telefon.'"><i class="fa fa-phone"></i></button>';
                            $avatar = '/public/isletmeyonetim_assets/img/avatar.png' ;
                        }
                        
                        $personel = Personeller::where('dahili_no',$result['dst'])->first();
                        // İsim bağlıysa "Ad (Dahili)", değilse sadece dahili numarası göster.
                        if ($personel && trim($personel->personel_adi) !== '') {
                            $dahili = $personel->personel_adi.' ('.$personel->dahili_no.')';
                        } else {
                            $dahili = !empty($result['dst']) ? $result['dst'] : '';
                        }
                    }
                 
                } 
                if($raporaEkle)
                    array_push(
                        $rapor,
                        array(
                            'tarih'=>date('d.m.Y',strtotime($result['calldate'])),
                            'saat'=>date('H:i',strtotime($result['calldate'])),
                            'musteri'=>$musteriAdi,
                            'gorusmeyiyapan'=>$dahili,
                            'telefon'=> $telefon,
                            'durum'=>$durum,
                            'seskaydi'=>$aramaButonu.$sesKaydi,
                            'avatar'=>$avatar,
                        ) 
                    ); 
                
            } 
        }
        return  array(
            'rapor'=>$rapor,
            'gelen_arama'=>$gelen_arama,
            'giden_arama'=>$giden_arama,
            'cevapsiz_arama'=>$cevapsiz_arama,
            'basarisiz_arama'=>$basarisiz_arama
        );
    }  

