    public function santral_token_al($salon_id)
    {
         $ch = curl_init();
        curl_setopt($ch, CURLOPT_URL, 'http://34.45.69.65/admin/api/api/token');
        curl_setopt($ch, CURLOPT_RETURNTRANSFER, 1);
        curl_setopt($ch, CURLOPT_POST, 1);
        $post = array(
            'grant_type' => 'client_credentials',
            'client_id' => 'ab6553d9183c664f87b8236a75cb6727f8d333586b8c1607c01426ebd9390add',
            'client_secret' => '9a44c50ba6d572e7263c97120fee00a0'
        );
        curl_setopt($ch, CURLOPT_POSTFIELDS, $post);
        $result = curl_exec($ch);
        if (curl_errno($ch)) {
            echo 'Error:' . curl_error($ch);
        }
         curl_close($ch);
        $result2 = json_decode($result,true);
        $isletme = Salonlar::where('id',$salon_id)->first();
        $isletme->santral_token = $result2['access_token'];
        $isletme->santral_token_expires = date('Y-m-d H:i:s',strtotime('+55 minutes',strtotime(date('Y-m-d H:i:s'))));
        $isletme->save();
        return $result2["access_token"];
    }
    public function arsivyonetimi(Request $request){
        $this->dinamikFormKolonlariOlustur();
         $isletmeler = '';
        $isletme='';
        if(Auth::guard('satisortakligi')->check())
        {
            $isletmeler = [15];
            $isletme = Salonlar::where('id',15)->first();
        }
        else{
            $isletmeler = Auth::guard('isletmeyonetim')->user()->yetkili_olunan_isletmeler->where('aktif',1)->pluck('salon_id')->toArray();
            $isletme= Salonlar::where('id',self::mevcutsube($request))->first();
        }


        if(!in_array(self::mevcutsube($request),$isletmeler ))
        {
            return view('isletmeadmin.yetkisizerisim');
            exit(0);
        }
        if(str_contains(self::lisans_sure_kontrol($request),'-'))
        {
            return view('isletmeadmin.lisanssurebitti',['isletme'=>$isletme]);
            exit(0);
        }
        // Yetki: bu sayfanin gerektirdigi yetki yoksa 403
        $_authUser = Auth::guard('isletmeyonetim')->user();
        if ($_authUser && !(
            \App\Services\PersonelYetkiServisi::yetkiliYetkiVar($_authUser->id, self::mevcutsube($request), 'form.olustur')
            || \App\Services\PersonelYetkiServisi::yetkiliYetkiVar($_authUser->id, self::mevcutsube($request), 'form.gonder')
        )) {
            return view('isletmeadmin.yetkisizerisim');
            exit(0);
        }
        if(!Auth::guard('satisortakligi')->check()){
             if(self::personelmi($request, 'form.olustur'))
            {
                    return redirect()->route('isletmeadmin.randevular');
                    exit(0);
            }
        }
       
        if(count($isletmeler)>1 && !isset($_GET['sube']))
        {
            return view('isletmeadmin.isletmesec',['isletmeler'=>$isletmeler,'isletme'=>$isletme]);
            exit(0);
        }
        $paketler = self::paket_liste_getir('',true,$request);
        $kalan_uyelik_suresi = self::lisans_sure_kontrol($request);
        $arsiv=self::arsiv_liste_getir($request,'','');
        $arsiv_onayli=self::arsiv_liste_getir($request,0,'');
        $arsiv_iptal=self::arsiv_liste_getir($request,1,'');
        $arsiv_beklenen=self::arsiv_liste_getir($request,2,'');
        $arsiv_harici=self::arsiv_liste_getir($request,3,'');
        return view('isletmeadmin.arsivyonetimi',['bildirimler'=>self::bildirimgetir($request),'arsiv'=>$arsiv,'arsiv_onayli'=>$arsiv_onayli, 'arsiv_iptal'=>$arsiv_iptal, 'arsiv_beklenen'=>$arsiv_beklenen, 'arsiv_harici'=>$arsiv_harici,   'paketler'=>$paketler,'sayfa_baslik'=>'Form Yönetimi','pageindex' => 50,'isletme'=>$isletme,'kalan_uyelik_suresi'=>$kalan_uyelik_suresi,'urun_drop'=>self::urundropliste($request),'hizmet_drop'=>self::hizmetdropliste($request),
            'yetkiliolunanisletmeler'=>$isletmeler]);
    }
    public static function arsivIslemlerFormGonderUygula($collection, Request $request){
        try {
            if (Auth::guard('isletmeyonetim')->check()) {
                $userId = Auth::guard('isletmeyonetim')->user()->id;
                $salonId = self::mevcutsube($request);
                $yetki = \App\Services\PersonelYetkiServisi::yetkiliYetkiVar($userId, $salonId, 'form.gonder');
                if (!$yetki) {
                    foreach ($collection as $row) {
                        if (isset($row->islemler) && is_string($row->islemler)) {
                            $row->islemler = preg_replace(
                                '/<a[^>]*formutekrargondermodal[^>]*>.*?<\\/a>\\s*/s',
                                '',
                                $row->islemler
                            );
                        }
                    }
                }
            }
        } catch (\Throwable $e) {}
        return $collection;
    }
