    // ====================================================================
    // Personel yetki yonetimi popup endpoint'leri (web tarafi)
    // ====================================================================
    //
    // Mobile ApiController'daki personelYetkiSemaApi/Getir/Kaydet
    // muadilleri — web guard ile, modal AJAX'i bunlara baglanir.

    public function personelYetkiSemaWeb()
    {
        return response()->json([
            'basarili'    => true,
            'tanimlar'    => \App\PersonelYetkiSabitleri::tanimlar(),
            'kategoriler' => \App\PersonelYetkiSabitleri::kategoriEtiketleri(),
            'sablonlar'   => collect(\App\PersonelYetkiSabitleri::sablonlar())->map(function ($s, $k) {
                return [
                    'key'      => $k,
                    'ad'       => $s['ad'],
                    'aciklama' => $s['aciklama'],
                    'ikon'     => $s['ikon'],
                    'ayarlar'  => $s['ayarlar'],
                ];
            })->values(),
        ]);
    }

    public function personelYetkiGetirWeb(Request $request)
    {
        $personelId = $request->personel_id;
        $salonId    = $request->sube ?? $this->mevcutsube($request);
        if (!$personelId || !$salonId) {
            return response()->json(['basarili' => false, 'mesaj' => 'Eksik parametre.']);
        }
        $personelRolunde = \App\Services\PersonelYetkiServisi::personelRolundeMi($personelId, $salonId);
        $ayarlar = \App\Services\PersonelYetkiServisi::ayarlariGetir($personelId, $salonId);
        return response()->json([
            'basarili'         => true,
            'personel_rolunde' => $personelRolunde,
            'sablon'           => $ayarlar['sablon'],
            'ayarlar'          => $ayarlar['ayarlar'],
        ]);
    }

    public function personelYetkiKaydetWeb(Request $request)
    {
        try {
            $personelId = $request->personel_id;
            $salonId    = $request->sube ?? $this->mevcutsube($request);

            // Auth user'in 'personel.yetki_yonet' yetkisi olmali
            $authUser = Auth::guard('isletmeyonetim')->user();
            if (!$authUser || !\App\Services\PersonelYetkiServisi::yetkiliYetkiVar(
                $authUser->id, $salonId, 'personel.yetki_yonet'
            )) {
                return response()->json(['basarili' => false, 'mesaj' => 'Bu işlem için yetkiniz yok.'], 403);
            }

            $sablon  = (string)($request->sablon ?? 'ozel');
            $ayarlar = $request->ayarlar;
            if (is_string($ayarlar)) {
                $decoded = json_decode($ayarlar, true);
                $ayarlar = is_array($decoded) ? $decoded : [];
            }
            if (!is_array($ayarlar)) $ayarlar = [];
            if (!$personelId || !$salonId) {
                return response()->json(['basarili' => false, 'mesaj' => 'Eksik parametre.']);
            }

            \App\Services\PersonelYetkiServisi::ayarlariKaydet($personelId, $salonId, $sablon, $ayarlar);

            try {
                SalonAudit::log($salonId, 'personel_yetki_kaydet', 'personel', $personelId, optional(\App\Personeller::find($personelId))->personel_adi, 'Personel yetkileri güncellendi', ['sablon' => $sablon]);
            } catch (\Throwable $e) {}

            // Personele push gonder (mobile cihazindan yansisin)
            try {
                \App\Services\NotificationService::toStaff((int)$personelId, (int)$salonId)
                    ->type(\App\Services\NotificationTypes::YETKI_DEGISTI)
                    ->title('Yetkileriniz Güncellendi')
                    ->body('Yöneticiniz yetkilerinizi güncelledi. Devam etmek için tekrar giriş yapmanız gerekiyor.')
                    ->extra(['force_logout' => '1'])
                    ->send();
            } catch (\Throwable $e) {
                \Log::warning('Yetki push (web) hatasi: ' . $e->getMessage());
            }

            return response()->json(['basarili' => true]);
        } catch (\Exception $e) {
            \Log::warning('Web personelYetkiKaydet: ' . $e->getMessage());
            return response()->json(['basarili' => false, 'mesaj' => $e->getMessage()]);
        }
    }

    /**
     * Giris yapan kullanici personel rolunde mi?
     *
     * $bypassYetki parametresi geriye uyumlu sekilde opsiyoneldir:
     *   - Verilmezse eski davranis: sadece role_id=5 kontrolu.
     *   - Verilirse: personel rolundeyse VE bu yetki acikSA false doner
     *     (kisitlama uygulanmaz). Yani 'tum_personel_gor' / 'tum_portfoy_gor'
     *     gibi bypass anahtarlariyla yetkili personel tum kayitlari gorur.
     *
     * Cagri ornekleri:
     *   if(self::personelmi($request))                         // eski (rol)
     *   if(self::personelmi($request, 'randevu.tum_personel_gor')) // yeni (yetki bypass)
     */
    public function personelmi(Request $request, string $bypassYetki = null)
    {

        $userSatis = Auth::guard('satisortakligi')->user();
        $userIsletme = Auth::guard('isletmeyonetim')->user();
        $salonId = self::mevcutsube($request);

        $isPersonel = DB::table('model_has_roles')
        ->where('role_id', 5)
        ->where(function($q) use ($userSatis, $userIsletme, $request) {
            // SatisOrtakligi guard'ından gelen kullanıcı varsa
            if ($userSatis) {
                $q->where('model_id', $userSatis->id);
            }

            // IsletmeYonetim guard'ından gelen kullanıcı varsa
            if ($userIsletme) {
                $q->orWhere('model_id', $userIsletme->id);
            }
        })
        ->where('salon_id', $salonId)
        ->count() > 0;

        if (!$isPersonel) return false;

        // Personel rolu + bypass yetki kontrolu
        if ($bypassYetki) {
            $userId = $userIsletme ? $userIsletme->id : ($userSatis ? $userSatis->id : null);
            if ($userId && \App\Services\PersonelYetkiServisi::yetkiliYetkiVar($userId, $salonId, $bypassYetki)) {
                return false; // yetki var → kisitlama uygulama
            }
        }
        return true;
    }
    public function musteridanisantext($salon_id)
    {
        if(Salonlar::where('id',$salon_id)->value('salon_turu_id') == 15 ||Salonlar::where('id',$salon_id)->value('salon_turu_id') == 28|| Salonlar::where('id',$salon_id)->value('salon_turu_id') == 29)
        {
            return array(
                'kelime'=>'danışan',
                'ek'=>'ın'
            );
            exit;
        }
        else
        {
            return array(
                'kelime'=>'müşteri',
                'ek'=>'nin'
            );
            exit;
        }
    }
    public function easistandata(Request $request,$bugunYarin)
    {

        $isletmeId = self::mevcutsube($request);

        // Tarihleri tek seferde hesapla (her where closure'unda yeniden hesaplama yok)
        $today = date('Y-m-d');
        $randevuDate  = date('Y-m-d', strtotime('+'.($bugunYarin+1).' days', strtotime($today)));
        $alacakDate   = date('Y-m-d', strtotime('+'.($bugunYarin+2).' days', strtotime($today)));
        $kampanyaDate = date('Y-m-d', strtotime('+'.($bugunYarin).' days',   strtotime($today)));

        // Randevular: musteri + salon iliskilerini eager load et (N+1 onleme).
        // Onceden her randevu icin 2 ek query atiliyordu (users + salonlar).
        // 100+ randevuda yuzlerce gereksiz sorgu olusuyordu.
        $randevular = Randevular::has('hizmetler')
            ->with(['users:id,name', 'salonlar:id,salon_turu_id'])
            ->where('salon_id',$isletmeId)
            ->where('durum',1)
            ->where(function($q){
                $q->where('randevuya_geldi',null);
                $q->orWhere('randevuya_geldi','!=',0);
            })
            ->where(function($q) use($randevuDate){
                $q->where('tarih', $randevuDate);
                $q->orWhere('onceki_tarih', $randevuDate);
            })
            ->get();

        // Alacaklar: default $with array'i 7 belongsTo iliskisini her sorguda yukluyor.
        // Bu sayfada sadece musteri + salon kullaniliyor; gerisini bypass et.
        $alacaklar = Alacaklar::without(['paketsatis','olusturan','randevu','senet','urunsatisi'])
            ->where('salon_id',$isletmeId)
            ->where(function ($q) use($alacakDate) {
                $q->where('planlanan_odeme_tarihi', $alacakDate);
                $q->orWhere('onceki_planlanan_odeme_tarihi', $alacakDate);
            })
            ->get();

        // KampanyaYonetimi: LIKE '%tarih%' yerine indekslenebilir whereDate.
        $kampanyalar = KampanyaYonetimi::where('salon_id',$isletmeId)
            ->whereDate('asistan_tarih_saat', $kampanyaDate)
            ->get();


        $formattedRandevular = $randevular->map(function($randevu){
            $baslik = $randevu->users->name." isimli ";
            $sonuc = "";
            $islemler = "";
            $durum = "";
              $saat = "";
            if($randevu->salonlar->salon_turu_id == 15||$randevu->salonlar->salon_turu_id == 28||$randevu->salonlar->salon_turu_id == 29 )
                $baslik .=" danışanın ";
            else
                $baslik .=" müşterinin ";
            $baslik .= date('d.m.Y', strtotime($randevu->tarih))." randevu hatırlatmasını ";
            if($randevu->hatirlatma_aramasi_yapildi)
                $baslik .= " yaptım.";
            else
                $baslik .= " yapacağım."; 
            if($randevu->hatirlatma_aramasi_yapildi == 1 && $randevu->randevuya_gelecek == 1)
                $sonuc = "Randevuya gelecek.";
            elseif($randevu->hatirlatma_aramasi_yapildi == null)
                $sonuc = "Hatırlatma araması yapılacak.";
            elseif($randevu->hatirlatma_ulasilamadi == 1 && $randevu->tekrar_arandi != 1)
                $sonuc = "Ulaşılamadı. ".date('H:i',strtotime($randevu->tekrar_arama_tarih_saat))." de tekrar arayacağım.";
            elseif($randevu->asistan_guncelledi == 1)
                $sonuc = "Asistan tarafından ".date('d.m.Y',strtotime($randevu->tarih))." ".date('H:i',strtotime($randevu->saat))." olarak güncellendi.";
            else
                $sonuc = date('H:i',strtotime($randevu->tekrar_arama_tarih_saat))." saatinde tekrar aradım, ulaşılamadı";
            if(
                ($randevu->hatirlatma_gorevi_iptal != 1 || $randevu->hatirlatma_gorevi_iptal == null) &&
                (
                    ($randevu->hatirlatma_aramasi_yapildi == 1 && $randevu->hatirlatma_ulasilamadi == 1) ||
                    ($randevu->hatirlatma_aramasi_yapildi == null || $randevu->hatirlatma_aramasi_yapildi != 1)

                )&&($randevu->tekrar_arandi != 1 || $randevu->tekrar_arandi == null)

            )
                $islemler = '<button name="gorev_iptal_et_randevu" class="btn btn-primary btn-block" data-value="'. $randevu->id.'" style="white-space:normal;line-height:1.4;padding:6px 12px;min-width:0;word-break:keep-all">Görevi İptal Et</button>';
            if($randevu->hatirlatma_ulasilamadi == 1)
                $durum = '<button class="btn btn-danger btn-block" style="white-space:normal;line-height:1.4;padding:6px 12px;min-width:0;word-break:keep-all">Ulaşılamadı</button>';
           

            if($randevu->hatirlatma_aramasi_yapildi === null)
                $saat = date('H:i',strtotime($randevu->saat));
            else
                $saat = date('H:i',strtotime($randevu->arama_saat));
             


            return [
                'baslik'=>"Randevu Hatırlatması",
                'mesaj'=>$baslik,
                'sonuc'=>$sonuc,
                'islemler'=>$islemler,
                'durum'=>$durum,
                'saat'=>$saat,
                'randevu_id'=>$randevu->id,
            ];
        });
        $formattedAlacaklar = $alacaklar->map(function($alacak){
            $baslik = $alacak->musteri->name." isimli ";
            $sonuc = "";
            $islemler = "";
            $durum = "";
            if($alacak->salon->salon_turu_id == 15||$alacak->salon->salon_turu_id == 28||$alacak->salon->salon_turu_id == 29 )
                $baslik .=" danışanın ";
            else
                $baslik .=" müşterinin ";
            $baslik .= date('d.m.Y', strtotime($alacak->planlanan_odeme_tarihi))." tarihindeki ".number_format($alacak->tutar,2,',','.')." ₺ tutarındaki ";
            if($alacak->taksitli_tahsilat_id !== null)
                $baslik .= "taksidinin ";
            else
                $baslik .= "senedinin ";
            $baslik.=" ödeme hatırlatmasını";
            if($alacak->hatirlatma_aramasi_yapildi)
                $baslik .= " yaptım.";
            else
                $baslik .= " yapacağım."; 
            if($alacak->hatirlatma_aramasi_yapildi == 1 && $alacak->odenecek == null && $alacak->hatirlatma_ulasilamadi == 0)
                $sonuc = "Hatırlatma araması yapıldı.";
            elseif($alacak->hatirlatma_aramasi_yapildi == null)
                $sonuc = "Hatırlatma araması yapılacak.";
            elseif($alacak->odenecek == 1)
                $sonuc = "Zamanında ödenecek.";
            elseif($alacak->asistan_guncelledi == 1)
                $sonuc = "Asistan tarafından ".date('d.m.Y',strtotime($alacak->planlanan_alacak_tarihi))." olarak güncellendi.";
            elseif($alacak->tekrar_arandi != 1 && $alacak->tekrar_arandi !== null)
                $sonuc = "Ulaşılamadı. ".date('H:i',strtotime($alacak->tekrar_arama_tarih_saat))." saatinde tekrar arayacağım";
            else
                $sonuc = date('H:i',strtotime($alacak->tekrar_arama_tarih_saat))." saatinde tekrar aradım, ulaşılamadı";
            if($alacak->hatirlatma_ulasilamadi == 1 )
                $durum = '<button class="btn btn-success btn-block" style="white-space:normal;line-height:1.4;padding:6px 12px;min-width:0;word-break:keep-all">Ulaşıldı</button>';

             

            if(
                ($alacak->hatirlatma_gorevi_iptal != 1 || $alacak->hatirlatma_gorevi_iptal == null) &&
                (
                    ($alacak->hatirlatma_aramasi_yapildi == 1 && $alacak->hatirlatma_ulasilamadi == 1) ||
                    ($alacak->hatirlatma_aramasi_yapildi == null || $alacak->hatirlatma_aramasi_yapildi != 1)

                )&&($alacak->tekrar_arandi != 1 || $alacak->tekrar_arandi == null)

            )
                $islemler = '<button name="gorev_iptal_et_alacak" class="btn btn-primary btn-block" data-value="'. $alacak->id.'" style="white-space:normal;line-height:1.4;padding:6px 12px;min-width:0;word-break:keep-all">Görevi İptal Et</button>';


            return [
                'baslik'=>'Alacak Hatırlatması',
                'mesaj'=>$baslik,
                'sonuc'=>$sonuc,
                'islemler'=>$islemler,
                'durum'=>$durum,
                'saat'=>date('H:i',strtotime($alacak->arama_saat)),
                'alacak_id'=>$alacak->id,
            ];

        });
        $formattedKampanyalar = $kampanyalar->map(function($kampanya){
            $baslik = $kampanya->paket_isim." kampanya ";
            $sonuc = "";
            $durum = '<a style="color:#fff;white-space:normal;line-height:1.4;padding:6px 12px" class="btn btn-primary" data-value="'.$kampanya->id.'" data-toggle="modal" name="kampanya_detay" data-target="#kampanya_detay_modal">Rapor Detayı &raquo;</a>';
            $islemler = "";
              
            if($kampanya->arama_ile_gonderim == 1 && $kampanya->sms_ile_gonderm != 1)
                $baslik = "arama ";
            elseif($kampanya->arama_ile_gonderim != 1 && $kampanya->sms_ile_gonderm == 1)
                $baslik = "SMS ";
            else
                $baslik = "arama ve SMS ";
            $baslik = "ile tanıtımını";
            if($kampanya->arama_yapildi || $kampanya->sms_gonderildi)
                $baslik = "yaptım.";
            else
                $baslik = "yapacağım.";

            return [
                'baslik'=>'Kampanya Hatırlatması',
                'mesaj'=>$baslik,
                'sonuc'=>$sonuc,
                'islemler'=>$islemler,
                'durum'=>$durum,
                'saat'=>date('H:i',strtotime($kampanya->asistan_tarih_saat)),
                'kampanya_id'=>$kampanya->id,
            ];
        });
        $merged = collect()
    ->merge($formattedRandevular)
    ->merge($formattedAlacaklar)
    ->merge($formattedKampanyalar);
        return $merged;

     
           
               
    }
