    public function adisyonOdemeDetaylari(Request $request)
    {
        $adisyon = Adisyonlar::where('id',$request->adisyon_id)->first();
        $tahsilatIdler = array();
        foreach($adisyon->hizmetler as $hizmet)
        {
            foreach($hizmet->tahsilatlar as $hizmetTahsilat)
                array_push($tahsilatIdler,$hizmetTahsilat->tahsilat_id);

        }
        foreach($adisyon->urunler as $urun)
        {
            foreach($urun->tahsilatlar as $urunTahsilat)
                array_push($tahsilatIdler,$urunTahsilat->tahsilat_id);

        }
        foreach($adisyon->paketler as $paket)
        {
            foreach($paket->tahsilatlar as $paketTahsilat)
                array_push($tahsilatIdler,$paketTahsilat->tahsilat_id);

        }
        $html = "<table class='table'><thead><tr><td style='text-align:center'>Ödeme Tarihi</td><td style='text-align:center'>Tutar (₺)</td><td style='text-align:center'>Ödeme Yöntemi</td></tr></thead></tbody>";
        $tahsilatlar = Tahsilatlar::whereIn('id',$tahsilatIdler)->orderBy('odeme_tarihi','asc')->get();
        foreach($tahsilatlar as $tahsilat){
             $html .= "<tr><td style='text-align:center'>".date('d.m.Y',strtotime($tahsilat->odeme_tarihi))."</td>
            <td style='text-align:center'>".number_format($tahsilat->tutar,2,',','.')."</td>
            <td style='text-align:center'>".$tahsilat->odeme_yontemi->odeme_yontemi."</td>";
        }
           
        
        $html .= "</tbody></table>";
        return $html;

    }
    public function paketTahsilatlari(Request $request)
    {
        $seansBilgi = AdisyonPaketSeanslar::where('hizmet_id',$request->hizmetId)->where('randevu_id',$request->randevuId)->first();
        $paketHizmetId = "";
        $seansli = false;
        $paketVar = false;
        $adisyonBilgi = '';
        $tahsilatUrl = '';
        if(!$seansBilgi){
            $adisyonHizmetBilgi =  AdisyonHizmetler::where('randevu_id',$request->randevuId)->first();
            $adisyonBilgi = Adisyonlar::where('id',$adisyonHizmetBilgi->adisyon_id)->first();
            $paketHizmetId = $adisyonHizmetBilgi->id;
        }
        else   {
            $paketVar = true;
            $paketHizmetId = $seansBilgi->adisyon_paket_id ? $seansBilgi->adisyon_paket_id : $seansBilgi->adisyon_hizmet_id;
        }
         
        $tahsilatIdler = array();
        $tahsilatBilgileri = '';
        if($seansBilgi){
             if($seansBilgi->adisyon_paket_id){
                    $tahsilatBilgileri = TahsilatPaketler::where('adisyon_paket_id',$paketHizmetId)->get();
            }
            else{
                $tahsilatBilgileri = TahsilatHizmetler::where('adisyon_hizmet_id',$paketHizmetId)->get();
             
            }
           
        }
        else{

            $tahsilatBilgileri = TahsilatHizmetler::where('adisyon_hizmet_id',$paketHizmetId)->get();

        }
        $tahsilatTutari = 0;
       

        $html = "<table class='table'><thead><tr><td style='text-align:center'>Ödeme Tarihi</td><td style='text-align:center'>Tutar (₺)</td><td style='text-align:center'>Ödeme Yöntemi</td></tr></thead></tbody>";
        foreach($tahsilatBilgileri as $tahsilatBilgi)
        { 

            $tahsilatlar = Tahsilatlar::where('id',$tahsilatBilgi->tahsilat_id)->orderBy('odeme_tarihi','asc')->get();

            foreach($tahsilatlar as $tahsilat)
            {
                        $html .= "<tr><td style='text-align:center'>".date('d.m.Y',strtotime($tahsilat->odeme_tarihi))."</td>
                        <td style='text-align:center'>".number_format($tahsilatBilgi->tutar,2,',','.')."</td>
                        <td style='text-align:center'>".$tahsilat->odeme_yontemi->odeme_yontemi."</td>";
            }
            $html .= "</tbody></table>";
        }
        
        
        return  array('odemeler'=>$html);
       

    }
    public function personelSiralamaAzalt(Request $request)
    {
        // 1 yukari tasi (sadece aktif personeller arasinda)
        $this->_personelSirayiKaydir($request, -1);
        return self::personel_liste_getir($request);
    }
    public function personelSiralamaArtir(Request $request)
    {
        // 1 asagi tasi (sadece aktif personeller arasinda)
        $this->_personelSirayiKaydir($request, +1);
        return self::personel_liste_getir($request);
    }
    private function _personelSirayiKaydir(Request $request, int $delta)
    {
        try {
            $isletmeId = $request->sube;
            // Aktif personelleri konum sirasiyla cek; takvim_sirasi'da olasi tekrar/bosluga
            // karsi id ASC tie-breaker kullan. Index tabanli swap, deger tabanli arama yerine
            // dogrudan komsu kaydi alir; "atlama" hatasini tamamen kaldirir.
            $aktifler = Personeller::where('salon_id',$isletmeId)
                ->where('aktif',1)
                ->orderBy('takvim_sirasi','asc')
                ->orderBy('id','asc')
                ->get()
                ->values();
            $idx = $aktifler->search(function($p) use($request){ return (int)$p->id === (int)$request->personelid; });
            if($idx === false) return;
            $hedefIdx = $idx + $delta;
            if($hedefIdx < 0 || $hedefIdx >= $aktifler->count()) return;
            $cur  = $aktifler[$idx];
            $komsu = $aktifler[$hedefIdx];
            $this->_personelSiraSwap($cur, $komsu);
            SalonAudit::log($isletmeId, 'personel_siralama_degistir', 'personel', $cur->id,
                $cur->personel_adi, 'Personel takvim sırası bir '.($delta < 0 ? 'yukarı' : 'aşağı').' taşındı');
        } catch(\Exception $e){ \Log::warning('_personelSirayiKaydir: '.$e->getMessage()); }
    }
    public function personelArsivle(Request $request)
    {
        if($r = self::yetkiYoksa403($request, 'personel.sil')) return $r;
        // Soft archive: personeli "sil" — listeden gizle, ama DB'de kalsin.
        // Iliskili randevu/tahsilat/prim kayitlari zarar gormesin.
        try {
            $personel = Personeller::where('id',$request->personelid)
                ->where('salon_id',$request->sube)->first();
            if($personel){
                $personel->arsivli = true;
                $personel->aktif = false; // randevuda gozukmesin
                $personel->takvimde_gorunsun = false; // her yerden gizle
                $personel->save();
            }
        } catch(\Exception $e){ \Log::warning('personelArsivle: '.$e->getMessage()); }
        return self::personel_liste_getir($request);
    }

    public function personelTakvimdeGorunsunToggle(Request $request)
    {
        try {
            $personel = Personeller::where('id',$request->personelid)
                ->where('salon_id',$request->sube)->first();
            if($personel){
                $personel->takvimde_gorunsun = !((bool)$personel->takvimde_gorunsun);
                $personel->save();
            }
        } catch(\Exception $e){ \Log::warning('personelTakvimdeGorunsunToggle: '.$e->getMessage()); }
        return self::personel_liste_getir($request);
    }
    private function _personelSiraSwap($a, $b)
    {
        // Olasi UNIQUE constraint icin 3 adimli swap (negatif temp deger araci)
        $aSira = $a->takvim_sirasi;
        $bSira = $b->takvim_sirasi;
        if($aSira == $bSira) return;
        // Step 1: a'yi temp negatif degere al
        $a->takvim_sirasi = -1 * abs($a->id);
        $a->save();
        // Step 2: b'yi a'nin eski yerine
        $b->takvim_sirasi = $aSira;
        $b->save();
        // Step 3: a'yi b'nin eski yerine
        $a->takvim_sirasi = $bSira;
        $a->save();
    }
