        }
        if ((int) optional($isletme)->uyelik_turu !== 3) {
            abort(403);
        }
        $lisansSure = self::lisans_sure_kontrol($request);
        if (str_contains($lisansSure, '-')) {
            return view('isletmeadmin.lisanssurebitti', ['isletme' => $isletme]);
        }
        if (count($isletmeler) > 1 && !isset($_GET['sube'])) {
