    /** Dashboard JSON: personel bazli arama metrikleri (kart verileri). */
    public function arama_dashboard_verileri(Request $request)
    {
        $salonId = self::mevcutsube($request);
        if ((int) optional(Salonlar::where('id', $salonId)->first())->uyelik_turu !== 3) {
            abort(403);
        }

        // Aranacak musteri durum metrikleri (personel = arama_listesi.personel_id)
        $rows = DB::table('aranacak_musteriler as am')
            ->join('arama_listesi as al', 'al.id', '=', 'am.arama_id')
            ->where('al.salon_id', $salonId)
            ->select(
                'al.personel_id',
                DB::raw('COUNT(*) as atanan'),
                DB::raw('SUM(CASE WHEN am.durum IS NOT NULL THEN 1 ELSE 0 END) as aranan'),
                DB::raw('SUM(CASE WHEN am.durum IN (2,5) THEN 1 ELSE 0 END) as cevapsiz'),
                DB::raw('SUM(CASE WHEN am.durum IN (1,4) THEN 1 ELSE 0 END) as konusulan'),
                DB::raw('SUM(CASE WHEN am.durum=0 THEN 1 ELSE 0 END) as ulasilamadi'),
                DB::raw('SUM(CASE WHEN am.durum=3 THEN 1 ELSE 0 END) as randevu'),
                DB::raw('SUM(CASE WHEN am.durum=6 THEN 1 ELSE 0 END) as ongorusme'),
                DB::raw('SUM(CASE WHEN am.durum=7 THEN 1 ELSE 0 END) as satis')
            )
            ->groupBy('al.personel_id')
            ->get()
            ->keyBy('personel_id');

        // Gorusme notu metrikleri (toplam sure + gorusme sayisi + satis cirosu)
        $gn = collect();
        if (Schema::hasTable('gorusme_notlari')) {
            $satisSql = Schema::hasColumn('gorusme_notlari', 'satis_tutari')
                ? 'SUM(CASE WHEN sonuc=7 THEN COALESCE(satis_tutari,0) ELSE 0 END) as satis_cirosu'
                : '0 as satis_cirosu';
            $gn = DB::table('gorusme_notlari')
                ->where('salon_id', $salonId)
                ->select('personel_id', DB::raw('SUM(sure_dk) as toplam_dk'), DB::raw('COUNT(*) as gorusme_sayisi'), DB::raw($satisSql))
                ->groupBy('personel_id')
                ->get()
                ->keyBy('personel_id');
        }

        // Personel adlarini TEK sorguda al (N+1 onleme)
        $personelIdler = $rows->keys()->filter()->all();
        $personelAdlari = $personelIdler
            ? Personeller::whereIn('id', $personelIdler)->pluck('personel_adi', 'id')
            : collect();

        $kartlar = [];
        foreach ($rows as $pid => $r) {
            if (!$pid) continue;
            $g = $gn[$pid] ?? null;
            $kartlar[] = [
                'personel_id'    => (int) $pid,
                'ad'             => $personelAdlari[$pid] ?? 'Bilinmeyen Personel',
                'atanan'         => (int) $r->atanan,
                'aranan'         => (int) $r->aranan,
                'kalan'          => (int) $r->atanan - (int) $r->aranan,
                'cevapsiz'       => (int) $r->cevapsiz,
                'konusulan'      => (int) $r->konusulan,
                'ulasilamadi'    => (int) $r->ulasilamadi,
                'randevu'        => (int) $r->randevu,
                'ongorusme'      => (int) $r->ongorusme,
                'satis'          => (int) $r->satis,
                'toplam_dk'      => $g ? (int) $g->toplam_dk : 0,
                'gorusme_sayisi' => $g ? (int) $g->gorusme_sayisi : 0,
                'satis_cirosu'   => $g ? (float) $g->satis_cirosu : 0,
            ];
        }

        // Atanan datasi cok olan ustte
        usort($kartlar, function ($a, $b) { return $b['atanan'] <=> $a['atanan']; });

        return response()->json(['kartlar' => $kartlar]);
    }

    /** Dashboard JSON: bir personelin gorusme notlari/ses kayitlari (detay). */
    public function arama_dashboard_personel_detay(Request $request)
    {
        $salonId = self::mevcutsube($request);
        if ((int) optional(Salonlar::where('id', $salonId)->first())->uyelik_turu !== 3) {
            abort(403);
        }
        $personelId = $request->personel_id;

        if (!Schema::hasTable('gorusme_notlari')) {
            return response()->json(['notlar' => []]);
        }

        // Kategori kolonlari prod'da schema-ensure calismadan once olmayabilir -> savunmaci.
        $katVar = Schema::hasColumn('gorusme_notlari', 'kategori_id') && Schema::hasTable('cagri_kategorileri');

        $q = DB::table('gorusme_notlari as g')
            ->leftJoin('users as u', 'u.id', '=', 'g.user_id');
        if ($katVar) {
            $q->leftJoin('cagri_kategorileri as k', 'k.id', '=', 'g.kategori_id')
              ->leftJoin('cagri_kategorileri as ak', 'ak.id', '=', 'g.alt_kategori_id');
        }
        $q->where('g.salon_id', $salonId)
            ->where('g.personel_id', $personelId)
            ->orderBy('g.id', 'desc')
            ->limit(300);

        $satisVar = Schema::hasColumn('gorusme_notlari', 'satis_tutari');
        $sel = ['g.not', 'g.ses_kaydi', 'g.sonuc', 'g.sure_dk', 'g.created_at', 'u.name'];
        if ($katVar) { $sel[] = 'k.ad as kategori_ad'; $sel[] = 'ak.ad as alt_kategori_ad'; }
        if ($satisVar) { $sel[] = 'g.satis_tutari'; }

        $notlar = $q->select($sel)->get()->map(function ($n) use ($katVar, $satisVar) {
            return [
                'musteri'      => $n->name ?? '-',
                'not'          => $n->not ?? '',
                'sonuc'        => self::aranacakDurumMetin($n->sonuc),
                'sonuc_kod'    => is_null($n->sonuc) ? null : (int) $n->sonuc,
                'sure_dk'      => (int) $n->sure_dk,
                'kategori'     => $katVar ? ($n->kategori_ad ?? '') : '',
                'alt_kategori' => $katVar ? ($n->alt_kategori_ad ?? '') : '',
                'satis_tutari' => ($satisVar && $n->satis_tutari !== null) ? (float) $n->satis_tutari : null,
                'ses'          => self::sesKaydiUrl($n->ses_kaydi),
                'tarih'        => $n->created_at ? date('d.m.Y H:i', strtotime($n->created_at)) : '',
            ];
        });

        return response()->json(['notlar' => $notlar]);
    }
    public function arama_liste_detay_getir(Request $request)
    {
        $aramaDetayId = $request->arama_detay_id;
        $salonId = AramaListesi::where('id', $aramaDetayId)->value('salon_id');

        $page = $request->input('page', 1);
        $perPage = $request->input('perPage', 50);

        $query = AranacakMusteriler::where('arama_id', $aramaDetayId)
            ->with('musteri');

        $total = $query->count();

        $aranacaklar = $query->skip(($page - 1) * $perPage)
            ->take($perPage)
            ->get();

        // Rol bir kez hesaplanir (map icinde her satirda DB sorgusu yapmamak icin).
        $rol = self::kullaniciRolu($salonId, $this->cmAuthId());
        $personelMi = ($rol == 5);

        $data = $aranacaklar->map(function ($item) use ($aramaDetayId, $personelMi) {
            $telefon = $item->musteri->cep_telefon ?? '';
            $ad = $item->musteri->name ?? '';

            // KVKK: personel (rol 5) ham numarayi ve tam soyadi GORMEZ.
            if ($personelMi) {
                $ad = self::adSoyadMaskele($ad);
                $telefonCikti = $telefon !== '' ? self::telefonGizle($telefon) : '';
                $telefonHam = null; // ham numara personel frontend'ine ASLA gonderilmez
            } else {
                $telefonCikti = $telefon;
                $telefonHam = $telefon;
            }

            $durumMetin = self::aranacakDurumMetin($item->durum);

            return [
                'aramaListesi'        => $aramaDetayId,
                'aranacak_musteri_id' => $item->id,
                'ad'                  => $ad,
                // Geriye donuk uyumluluk: 'telefon' sadece yoneticiye (personele null) gider
                'telefon'             => $telefonHam,
                'telefonGizlenmis'    => $telefonCikti,
                'durum'               => $durumMetin,
                'durum_kod'           => $item->durum,
                'not'                 => $item->musteri_not ?? '',
                'not_tarih'           => $item->tarih ?? '',
                'not_saat'            => $item->saat ?? '',
                'ses'                 => self::sesKaydiUrl($item->ses_kaydi),
            ];
        });

        return response()->json([
            'data' => $data,
            'total' => $total,
            'page' => $page,
            'perPage' => $perPage
        ]);
    }
    /** Aranacak musteri durum kodunu metne cevirir. */
    public static function aranacakDurumMetin($kod)
    {
        switch ((int) $kod) {
            case 1: return 'Arandı';
            case 0: return 'Ulaşılamadı';
            case 2: return 'Cevapsız';
            case 3: return 'Tekrar Aranacak';
            case 4: return 'Görüşüldü';
            case 5: return 'Meşgul';
            case 6: return 'Ön Görüşme Randevusu';
            case 7: return 'Telefonda Satış';
            default: return is_null($kod) ? 'Bekliyor' : 'Bekliyor';
        }
    }

    /**
     * ses_kaydi -> oynatilabilir kaynak. Kayitlar santral sunucusunda servis edilir:
     * https://santral.randevumcepte.com.tr<recording_path> (ornek calisan src bu host'la dogrulandi).
     * Zaten tam URL ise oldugu gibi birakilir.
     */
    public static function sesKaydiUrl($p)
    {
        $p = trim((string) $p);
        if ($p === '') return '';
        if (stripos($p, 'http') === 0) return $p;
        return 'https://santral.randevumcepte.com.tr' . (substr($p, 0, 1) === '/' ? '' : '/') . $p;
    }

    /** Giris yapan yetkilinin bu salondaki personel (salon_personelleri) kaydinin id'sini doner. */
    private function aktifPersonelId($salonId)
    {
        return Personeller::where('yetkili_id', $this->cmAuthId())
            ->where('salon_id', $salonId)
            ->value('id');
    }

    public function santral_not_ekle(Request $request)
    {
        $aramaDetayId = $request->arama_detay_id;
        $notIcerik = $request->noticerik;

        // KIRILGAN index-bazli bulma yerine aranacak_musteri_id ile bul.
        $kayit = null;
        if ($request->filled('aranacak_musteri_id')) {
            $kayit = AranacakMusteriler::where('id', $request->aranacak_musteri_id)
                ->where('arama_id', $aramaDetayId)
                ->first();
        } elseif ($request->filled('not_id')) {
            // Geriye donuk uyumluluk: eski index tabanli cagrilar
            $aranacaklar = AranacakMusteriler::where('arama_id', $aramaDetayId)->get();
            $kayit = $aranacaklar[$request->not_id] ?? null;
        }

        if (!$kayit) {
            return response()->json(['success' => false, 'message' => 'Kayıt bulunamadı']);
        }

        $liste = AramaListesi::where('id', $aramaDetayId)->first();
        $salonId = $liste ? $liste->salon_id : self::mevcutsube($request);

        $tekrarTarih = $request->santralnottarih;
        $tekrarSaat  = $request->santralnotsaat;
        $randevuMu = (!empty($tekrarTarih) && !empty($tekrarSaat));

        // Agent gorusme sonucu: 0 Ulasilamadi, 2 Cevapsiz, 4 Gorusuldu, 5 Mesgul,
        // 6 On Gorusme Randevusu, 7 Telefonda Satis. (3 = Tekrar Aranacak -> "sonra ara" checkbox'i)
        $sonucKod = $request->filled('sonuc') ? (int) $request->sonuc : null;
        $gecerliSonuc = in_array($sonucKod, [0, 2, 4, 5, 6, 7], true);

        // Nihai durum: ACIK secilen sonuc onceliklidir; yoksa "sonra ara" (randevu); o da yoksa eski.
        if ($gecerliSonuc) {
            $kayitDurum = $sonucKod;     // 6/7 dahil — tarih/saat olsa bile sonuc korunur
        } elseif ($randevuMu) {
            $kayitDurum = 3;             // Tekrar Aranacak (sonra ara)
        } elseif (is_null($kayit->durum)) {
            $kayitDurum = 4;             // Görüşüldü (not eklendi)
        } else {
            $kayitDurum = (int) $kayit->durum;
        }

        // Telefonda satis tutari (sonuc=7)
        $satisTutari = ($kayitDurum === 7 && $request->filled('satis_tutari'))
            ? round((float) str_replace(',', '.', $request->satis_tutari), 2) : null;

        // Mevcut tablo: tekrar arama randevusu tarih/saat alanlari (TekrarAramaHatirlat bunu okur)
        $kayit->musteri_not = $notIcerik;
        $kayit->tarih = $tekrarTarih;
        $kayit->saat  = $tekrarSaat;
        $kayit->durum = $kayitDurum;
        if (Schema::hasColumn('aranacak_musteriler', 'son_arama_zamani')) {
            $kayit->son_arama_zamani = date('Y-m-d H:i:s');
        }
        // NOT: Ses kaydi burada SENKRON cekilmez (kaydetmeyi bekletmemek icin). Kaydi bu
        // gorusmeye baglama isi, sonuc kaydedilince otomatik tazelenen "cagri-musteri-gecmisi"
        // ucunda (ve "Yenile" butonunda) AGENT DAHILISI ile yapilir — CDR gecikmesine de dayanikli.
        $kayit->save();

        // Gorusme sonucu kategorisi (opsiyonel, ayni salona ait olmali). Kategori semasi
        // prod'da schema-ensure calismadan once olmayabilir -> savunmaci.
        $kategoriId = null; $altKategoriId = null;
        $katSema = Schema::hasTable('cagri_kategorileri') && Schema::hasColumn('gorusme_notlari', 'kategori_id');
        if ($katSema) {
            $kategoriId = $request->filled('kategori_id') ? (int) $request->kategori_id : null;
            $altKategoriId = $request->filled('alt_kategori_id') ? (int) $request->alt_kategori_id : null;
            if ($kategoriId && !\App\CagriKategori::where('id', $kategoriId)->where('salon_id', $salonId)->exists()) {
                $kategoriId = null; $altKategoriId = null;
            }
            if ($altKategoriId && !\App\CagriKategori::where('id', $altKategoriId)->where('salon_id', $salonId)->where('ust_id', $kategoriId)->exists()) {
                $altKategoriId = null;
            }
        }

        // Cogul gorusme notu gecmisi (musteriye kalici bag)
        try {
            $gnVeri = [
                'aranacak_musteri_id' => $kayit->id,
                'arama_id'            => $aramaDetayId,
                'salon_id'            => $salonId,
                'user_id'             => $kayit->user_id,
                'personel_id'         => $this->aktifPersonelId($salonId),
                'not'                 => $notIcerik,
                'sonuc'               => $kayitDurum,
                'ses_kaydi'           => $kayit->ses_kaydi,
            ];
            if ($katSema) {
                $gnVeri['kategori_id'] = $kategoriId;
                $gnVeri['alt_kategori_id'] = $altKategoriId;
            }
            if (Schema::hasColumn('gorusme_notlari', 'satis_tutari')) {
                $gnVeri['satis_tutari'] = $satisTutari;
            }
            \App\GorusmeNotlari::create($gnVeri);
        } catch (\Throwable $e) {
            \Log::warning('[CAGRI-MERKEZI] gorusme_notlari yazilamadi: ' . $e->getMessage());
        }

        return response()->json(['success' => true]);
    }

    /**
     * Cagri Merkezi — musteriye manuel WhatsApp mesaji.
     * Web'deki musterimanuelwhatsappgonder ile AYNI davranis; tek fark: musteri
     * aranacak_musteri_id ile cozulur, boylece personel ham numarayi GORMEDEN
     * (KVKK) backend mesaji gonderir. sendReminder -> WhatsAppRouterService (salon
     * basina Baileys/whatsmeow). gonderim tipi 'manuel_musteri'.
     */
    public function cagri_whatsapp_gonder(Request $request)
    {
        $kayit = AranacakMusteriler::where('id', $request->aranacak_musteri_id)->first();
        if (!$kayit) {
            return response()->json(['ok' => false, 'mesaj' => 'Kayıt bulunamadı.'], 404);
        }

        $liste = AramaListesi::where('id', $kayit->arama_id)->first();
        $salonId = $liste ? $liste->salon_id : self::mevcutsube($request);
        $isletme = Salonlar::where('id', $salonId)->first();
        if (!$isletme) {
            return response()->json(['ok' => false, 'mesaj' => 'Salon bulunamadı.'], 404);
        }

        $mesaj = trim((string) $request->input('mesaj', ''));
        if ($mesaj === '') {
            return response()->json(['ok' => false, 'mesaj' => 'Mesaj boş olamaz.'], 422);
        }
        if (mb_strlen($mesaj) > 1000) {
            return response()->json(['ok' => false, 'mesaj' => 'Mesaj en fazla 1000 karakter olabilir.'], 422);
        }

        $musteri = User::where('id', $kayit->user_id)->first();
        if (!$musteri || !$musteri->cep_telefon) {
            return response()->json(['ok' => false, 'mesaj' => 'Müşteri telefon numarası bulunamadı.'], 422);
        }

        // Baileys ise bagli olmali (net hata mesaji icin on-kontrol)
        // Paylasilan oturum: 416 icin 246'nin durumu kontrol edilir.
        $waIsletme = \App\Services\WhatsAppService::resolveWaSalon($isletme);
        $saglayici = $waIsletme->whatsapp_saglayici ?? 'baileys';
        if ($saglayici === 'baileys' && (!$waIsletme->whatsapp_aktif || $waIsletme->whatsapp_durum !== 'connected')) {
            return response()->json(['ok' => false, 'mesaj' => 'WhatsApp bağlı değil. Önce WhatsApp ayarlarından QR okutun.'], 409);
        }

        $wa = app(\App\Services\WhatsAppService::class);
        $sonuc = $wa->sendReminder($isletme, $musteri->cep_telefon, $mesaj, null, $musteri->id, null, false, 'manuel_musteri');

        if (!empty($sonuc['ok'])) {
            return response()->json(['ok' => true, 'mesaj' => 'Mesaj gönderim kuyruğuna alındı. Birazdan müşteriye ulaşacak.']);
        }

        $hataKodu = $sonuc['error'] ?? 'unknown';
        $hataMetin = [
            'invalid-phone'          => 'Müşteri telefon numarası geçersiz.',
            'daily-cap-reached'      => 'Günlük WhatsApp mesaj limitiniz doldu.',
            'outside-business-hours' => 'Şu an çalışma saatleri dışında, mesaj gönderilemedi.',
            'service-unreachable'    => 'WhatsApp servisine ulaşılamadı, lütfen tekrar deneyin.',
        ][$hataKodu] ?? 'Mesaj gönderilemedi. Lütfen tekrar deneyin.';

        return response()->json(['ok' => false, 'mesaj' => $hataMetin], 422);
    }

    /**
     * Cagri Merkezi — musteriye memnuniyet anketi (tek tik).
     * Web'deki anketHizliGonder ile AYNI; tek fark: musteri aranacak_musteri_id ile
     * cozulur. Sablon secimi YOK — salonun aktif/varsayilan sablonu kullanilir (yoksa
     * otomatik olusturulur). Link WhatsApp-first + SMS fallback ile gonderilir.
     */
    public function cagri_anket_gonder(Request $request)
    {
        try {
            $kayit = AranacakMusteriler::where('id', $request->aranacak_musteri_id)->first();
            if (!$kayit) {
                return response()->json(['basarili' => false, 'mesaj' => 'Kayıt bulunamadı.']);
            }

            $liste = AramaListesi::where('id', $kayit->arama_id)->first();
            $sube = $liste ? $liste->salon_id : self::mevcutsube($request);

            $musteri = User::where('id', $kayit->user_id)->first();
            if (!$musteri) {
                return response()->json(['basarili' => false, 'mesaj' => 'Müşteri bulunamadı.']);
            }
            if (empty($musteri->cep_telefon)) {
                return response()->json(['basarili' => false, 'mesaj' => 'Müşterinin telefon numarası kayıtlı değil.']);
            }

            $sablon = self::varsayilanAnketSablonuGetirYaOlustur($sube);
            $gonderim = self::anketGonderimOlustur($sube, $sablon, $musteri, $musteri->cep_telefon, [
                'kanal'       => 'manuel',
                'personel_id' => $this->aktifPersonelId($sube),
            ]);
            self::anketSmsGonder($request, $gonderim, $sablon, $musteri);

            SalonAudit::log($sube, 'anket_hizli_gonder', 'anket_gonderim', $gonderim->id,
                ($musteri->name ?: 'Müşteri') . ' — ' . $musteri->cep_telefon,
                'Çağrı merkezinden hızlı anket gönderimi',
                ['sablon_id' => $sablon->id, 'sablon_adi' => $sablon->ad, 'user_id' => $musteri->id]);

            return response()->json([
                'basarili'    => true,
                'mesaj'       => 'Anket gönderildi.',
                'gonderim_id' => $gonderim->id,
                'kanal'       => $gonderim->gonderim_kanali ?: 'sms',
            ]);
        } catch (\Exception $e) {
            \Log::error('cagri_anket_gonder hata: ' . $e->getMessage());
            return response()->json(['basarili' => false, 'mesaj' => $e->getMessage()]);
        }
    }

    /**
     * KVKK uyumlu arama baslatma: personel ham numarayi GORMEZ; sadece bu uc-nokta
     * aranacak_musteri_id ile gercek numarayi doner, JS dogrudan arar (ekrana yazmadan).
     */
    /**
     * Cagri Merkezi click-to-call (agent-first, context-free).
     * Originate: personelin dahilisi (Bria) calar -> acinca santral musteriyi trunk'tan arar
     * (Application: Dial). Ozel dialplan context'i (from-internal-custom) GEREKTIRMEZ.
     * Numara tarayiciya/personele GITMEZ.
     */
    private function cagriMerkeziOriginate($salonId, $tel, $dahili)
    {
        if (empty($dahili)) {
            return ['success' => false, 'message' => 'Arama için size bir dahili numara atanmamış. (Personel ayarlarından dahili tanımlayın.)'];
        }
        $sabitno = \App\SabitNumaralar::where('salon_id', $salonId)->first();
        if (!$sabitno || empty($sabitno->numara)) {
            return ['success' => false, 'message' => 'Salon için santral (trunk) numarası tanımlı değil.'];
        }
        $salon = Salonlar::where('id', $salonId)->first();

        // Santral AMI sunucusu
        $amiHost = '89.252.140.61';
        $errno = 0; $errstr = '';
        $socket = @stream_socket_client('tcp://' . $amiHost . ':5038', $errno, $errstr, 10);
        if (!$socket) {
            \Log::warning('[CAGRI-MERKEZI] AMI baglanti hatasi: (' . $errno . ') ' . $errstr . ' host=' . $amiHost);
            return ['success' => false, 'message' => 'Santrale bağlanılamadı. [' . $errno . ' ' . $errstr . ']'];
        }

        $auth = "Action: Login\r\nUsername: cxpanel\r\nSecret: cxmanager*con\r\nEvents: off\r\n\r\n";
        stream_socket_sendto($socket, $auth);
        usleep(300000);
        if (strpos((string) fread($socket, 8192), 'Success') === false) {
            fclose($socket);
            return ['success' => false, 'message' => 'Santral kimlik doğrulaması başarısız.'];
        }

        // AGENT-FIRST arama: ONCE personelin dahilisi (Bria) calar; agent acinca santral
        // musteriyi SALONUN outbound peer'inden arar -> agent calma sesini / mesgul tonunu /
        // acilmayi KENDI kulagiyla duyar ve dogru sonucu isaretler.
        // - Local/<dahili>@from-internal: agent'i caldiran CALISAN dialplan yolu (eski Exten ile ayni).
        // - Dial SIP/<salon>-out/0<no>: musteriyi salon peer'inden arar (CallerID = salon no, KVKK).
        // (Eski "musteri-first" format git gecmisinde; geri donulmek istenirse oradan alinabilir.)
        $req  = "Action: Originate\r\n";
        $req .= "Channel: Local/" . $dahili . "@from-internal\r\n";            // once personelin dahilisi calar
        $req .= "Callerid: " . $sabitno->numara . "\r\n";                      // Bria'da salon no gorunur (musteri no DEGIL)
        $req .= "Account: cmerkezi\r\n";                                       // CDR etiketi: santral raporu bu cagrilari ayiklar
        $req .= "Application: Dial\r\n";
        $req .= "Data: SIP/" . $sabitno->numara . "-out/0" . $tel . ",60\r\n"; // acinca musteri salon peer'inden aranir
        $req .= "Async: yes\r\n\r\n";

        stream_socket_sendto($socket, $req);
        usleep(400000);
        $resp = (string) fread($socket, 8192);
        @stream_socket_sendto($socket, "Action: Logoff\r\n\r\n");
        fclose($socket);
        \Log::info('[CAGRI-MERKEZI] Originate (agent-first). Channel=Local/' . $dahili . '@from-internal -> Dial SIP/' . $sabitno->numara . '-out/0' . $tel . ' | Yanit: ' . trim(preg_replace('/\s+/', ' ', $resp)));

        if (strpos($resp, 'Success') !== false) {
            return ['success' => true, 'message' => 'Telefonunuz (Bria) çalıyor — açın; ardından müşteri aranacak ve çalma sesini duyacaksınız.'];
        }
        return [
            'success' => false,
            'message' => 'Santral aramayı başlatamadı. ' . mb_substr(trim(preg_replace('/\s+/', ' ', $resp)), 0, 160),
        ];
    }

    public function arama_baslat(Request $request)
    {
        $kayit = AranacakMusteriler::where('id', $request->aranacak_musteri_id)->first();
        if (!$kayit) {
            return response()->json(['success' => false, 'message' => 'Kayıt bulunamadı'], 404);
        }

        $liste = AramaListesi::where('id', $kayit->arama_id)->first();
        if (!$liste) {
            return response()->json(['success' => false, 'message' => 'Liste bulunamadı'], 404);
        }
        $salonId = $liste->salon_id;

        // Yetki: yonetici (rol<5) ya da listenin atandigi personel arayabilir.
        $rol = self::kullaniciRolu($salonId, $this->cmAuthId());
        if ($rol == 5) {
            $benimPersonelId = $this->aktifPersonelId($salonId);
            if ((int) $liste->personel_id !== (int) $benimPersonelId) {
                return response()->json(['success' => false, 'message' => 'Bu listeyi arama yetkiniz yok'], 403);
            }
        }

        $numara = $kayit->musteri->cep_telefon ?? '';
        if ($numara === '') {
            return response()->json(['success' => false, 'message' => 'Müşteri telefonu yok'], 422);
        }
        $tel = ltrim($numara, '0');

        // Arayan kullanicinin (personel/yonetici) dahilisi — Bria bu dahiliye kayitli.
        $dahili = \App\Personeller::where('yetkili_id', $this->cmAuthId())
            ->where('salon_id', $salonId)->value('dahili_no');

        // Santral originate (agent-first, context-free). Numara tarayiciya GITMEZ.
        $sonuc = $this->cagriMerkeziOriginate($salonId, $tel, $dahili);

        if (!empty($sonuc['success'])) {
            // Arama randevusu (durum=3) ise arandi olarak isaretle ki popup tekrar nag yapmasin.
            if ((int) $kayit->durum === 3) {
                $kayit->durum = 1;
            }
            if (Schema::hasColumn('aranacak_musteriler', 'son_arama_zamani')) {
                $kayit->son_arama_zamani = date('Y-m-d H:i:s');
            }
            $kayit->save();
        }

        return response()->json([
            'success'      => !empty($sonuc['success']),
            'message'      => $sonuc['message'] ?? '',
            'aramaListeId' => $kayit->arama_id,
        ]);
    }

    /**
     * Santral raporlari (ve kayitli-olmayan numaralar) icin click-to-call.
     * arama_baslat'in AYNISI ama aranacak_musteri_id yerine HAM TELEFON numarasi alir.
     * Agent-first originate: once arayan kullanicinin dahilisi (Bria) calar, acinca
     * musteri salonun outbound peer'inden aranir. Numara tarayiciya/cihaza GITMEZ.
     */
    public function arama_baslat_numara(Request $request)
    {
        $salonId = self::mevcutsube($request);
        if (empty($salonId)) {
            return response()->json(['success' => false, 'message' => 'Şube bulunamadı'], 422);
        }

        // Yetki: ROL'e DEGIL, bu isletmeye (salon) yetkili olmaya bakilir.
        // Hesap sahibi/yoneticinin model_has_roles satiri olmayabilir; asil olcut
        // kullanicinin yetkili_olunan_isletmeler listesinde bu salonun bulunmasidir.
        $user = $this->cmUser();
        $yetkiliSalonlar = $user
            ? $user->yetkili_olunan_isletmeler->pluck('salon_id')->map(function ($v) { return (int) $v; })->toArray()
            : [];
        if (!in_array((int) $salonId, $yetkiliSalonlar, true)) {
            return response()->json(['success' => false, 'message' => 'Bu işletmede arama yetkiniz yok'], 403);
        }

        $numara = preg_replace('/\D/', '', (string) $request->numara);
        if ($numara === '') {
            return response()->json(['success' => false, 'message' => 'Telefon numarası geçersiz'], 422);
        }
        // Son 10 hane (90 / 0 onekleri temizlenir) -> originate icin 0<no> formatina cevrilir.
        $tel = substr($numara, -10);

        // Arayan kullanicinin (personel/yonetici) dahilisi — Bria bu dahiliye kayitli.
        $dahili = \App\Personeller::where('yetkili_id', $this->cmAuthId())
            ->where('salon_id', $salonId)->value('dahili_no');

        $sonuc = $this->cagriMerkeziOriginate($salonId, $tel, $dahili);

        return response()->json([
            'success' => !empty($sonuc['success']),
            'message' => $sonuc['message'] ?? '',
        ]);
    }

    /**
     * Cagri Merkezi: bir musteriyle yapilan TUM gorusme ses kayitlari (cdr tablosundan,
     * telefon eslestirmesiyle). Detay ekranindaki "Ses Kayitlari" butonu kullanir.
     */
    public function musteri_ses_kayitlari(Request $request)
    {
        $kayit = AranacakMusteriler::where('id', $request->aranacak_musteri_id)->first();
        if (!$kayit) {
            return response()->json(['kayitlar' => []]);
        }
        $cepHam = preg_replace('/\D/', '', (string) optional($kayit->musteri)->cep_telefon);
        $son10 = substr($cepHam, -10); // format farkindan bagimsiz: son 10 hane
        if ($son10 === '') {
            return response()->json(['kayitlar' => []]);
        }

        $liste = AramaListesi::where('id', $kayit->arama_id)->first();
        $salonId = $liste ? $liste->salon_id : self::mevcutsube($request);

        // Santralin CALISAN canli CDR API'si (santral raporlariyla AYNI kaynak) — cdr DB
        // tablosuna bagimli degil; yeni santralin kayitlarini da gosterir.
        $dahililer = Personeller::where('salon_id', $salonId)
            ->whereNotNull('dahili_no')->where('dahili_no', '!=', '')
            ->pluck('dahili_no')->toArray();
        $trunk = \App\SabitNumaralar::where('salon_id', $salonId)->value('numara');

        $qs = '?offset=0';
        foreach ($dahililer as $d) $qs .= '&dahililer[]=' . urlencode($d);
        $qs .= '&tarih1=' . date('Y-m-d', strtotime('-120 days'));
        $qs .= '&tarih2=' . date('Y-m-d', strtotime('+1 day'));
        if ($trunk) $qs .= '&did=' . urlencode($trunk);

        $kayitlar = [];
        try {
            $ch = curl_init();
            curl_setopt($ch, CURLOPT_URL, 'https://santral.randevumcepte.com.tr/monitor/api/freepbxapi.php' . $qs);
            curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
            curl_setopt($ch, CURLOPT_TIMEOUT, 15);
            $raw = curl_exec($ch);
            curl_close($ch);
            $results = json_decode($raw, true);
            $satirlar = (isset($results['data']) && is_array($results['data'])) ? $results['data'] : (is_array($results) ? $results : []);

            foreach ($satirlar as $r) {
                if (!is_array($r) || empty($r['recording_path'])) continue;
                // Musteri numarasi src/dst'de OLMAYABILIR (cagri merkezi aramasinda channel
                // icinde: SIP/<salon>-out/0<musteri>). Tum ilgili alanlarin rakamlarinda ara.
                $samanlik = preg_replace('/\D/', '', ($r['channel'] ?? '') . '|' . ($r['dstchannel'] ?? '') . '|' . ($r['src'] ?? '') . '|' . ($r['dst'] ?? ''));
                if (strpos($samanlik, $son10) === false) continue;

                $url = $r['recording_path'];
                if (stripos($url, 'http') !== 0) {
                    $url = 'https://voicerecords.randevumcepte.com.tr' . (substr($url, 0, 1) === '/' ? '' : '/') . $url;
                }
                $ts = isset($r['calldate']) ? strtotime($r['calldate']) : 0;
                $kayitlar[] = [
                    '_ts'   => $ts,
                    'tarih' => $ts ? date('d.m.Y H:i', $ts) : '',
                    'url'   => $url,
                ];
            }
            usort($kayitlar, function ($a, $b) { return $b['_ts'] <=> $a['_ts']; });
            foreach ($kayitlar as &$k) unset($k['_ts']);
            unset($k);
        } catch (\Throwable $e) {
            \Log::warning('[CAGRI-MERKEZI] ses kayitlari freepbxapi hata: ' . $e->getMessage());
        }

        return response()->json(['kayitlar' => array_values($kayitlar)]);
    }

    /**
     * Bir DAHILIYE ait santral ses-kayit ADAYLARINI doner: [['path'=>..., 'ts'=>YYYYMMDDHHMMSS], ...]
     * ts DESC (en yeni once). Zaman damgasi ONCE DOSYA ADINDAN (-YYYYMMDD-HHMMSS-) okunur; bu santral
     * raporundaki saatle birebir ayni ve timezone'dan bagimsizdir. calldate yedek.
     */
    private function cagriMerkeziKayitAdaylari($salonId, $dahili)
    {
        $out = [];
        if (empty($dahili)) return $out;
        $trunk = \App\SabitNumaralar::where('salon_id', $salonId)->value('numara');
        $qs = '?offset=0&dahililer[]=' . urlencode($dahili)
            . '&tarih1=' . date('Y-m-d', strtotime('-2 day'))
            . '&tarih2=' . date('Y-m-d', strtotime('+1 day'));
        if ($trunk) $qs .= '&did=' . urlencode($trunk);

        try {
            $ch = curl_init();
            curl_setopt($ch, CURLOPT_URL, 'https://santral.randevumcepte.com.tr/monitor/api/freepbxapi.php' . $qs);
            curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
            curl_setopt($ch, CURLOPT_TIMEOUT, 15);
            $raw = curl_exec($ch);
            curl_close($ch);
            $results = json_decode($raw, true);
            $satirlar = (isset($results['data']) && is_array($results['data'])) ? $results['data'] : (is_array($results) ? $results : []);

            $gorulen = [];
            foreach ($satirlar as $r) {
                if (!is_array($r) || empty($r['recording_path'])) continue;
                $kanalDahili = '';
                if (preg_match('/^[^\/]+\/([^-\s]+)/', ($r['channel'] ?? ''), $m)) {
                    $kanalDahili = preg_replace('/\D/', '', $m[1]);
                }
                if ($kanalDahili !== (string) $dahili) continue;

                $rp = $r['recording_path'];
                if (isset($gorulen[$rp])) continue; // ayni kayit birden fazla CDR satirinda olabilir
                $gorulen[$rp] = true;

                $ts = 0;
                if (preg_match('/-(\d{8})-(\d{6})/', $rp, $mm)) {
                    $ts = (int) ($mm[1] . $mm[2]); // YYYYMMDDHHMMSS
                } elseif (!empty($r['calldate'])) {
                    $ts = (int) date('YmdHis', strtotime($r['calldate']));
                }
                $out[] = ['path' => $rp, 'ts' => $ts];
            }
            usort($out, function ($a, $b) { return $b['ts'] <=> $a['ts']; }); // en yeni once
        } catch (\Throwable $e) {
            \Log::warning('[CAGRI-MERKEZI] kayit adaylari getirilemedi: ' . $e->getMessage());
        }
        return $out;
    }

    /**
     * Agent calisma ekrani — bir musterinin AYRIK gorusme gecmisi (santral havuzundan degil,
     * dogrudan bu arama listesinin gorusme_notlari kayitlarindan). Her satir: tarih, sonuc,
     * not, kategori, ses kaydi. Ses kaydi eksik+yeni satirlar icin dahili ile bagla (CDR gecikmesi).
     */
    public function cagri_musteri_gecmisi(Request $request)
    {
        $kayit = AranacakMusteriler::where('id', $request->aranacak_musteri_id)->first();
        if (!$kayit || !Schema::hasTable('gorusme_notlari')) {
            return response()->json(['gecmis' => []]);
        }
        $liste = AramaListesi::where('id', $kayit->arama_id)->first();
        $salonId = $liste ? $liste->salon_id : self::mevcutsube($request);

        $notlar = \App\GorusmeNotlari::where('aranacak_musteri_id', $kayit->id)
            ->orderBy('id', 'desc')->limit(50)->get(); // en yeni once

        // Her gorusmeye KENDI ses kaydini bagla (hepsine ayni kayit gelme sorununu cozer):
        // - Adaylar dahili bazinda santralden cekilir, zaman damgasina gore en yeni once siralanir.
        // - En yeni gorusme -> en yeni (kullanilmamis) kayit ... seklinde sirayla, TEKRARSIZ eslesir.
        // - Son 2 gunden eski notlar yeniden atanmaz; sadece kayitlari rezerve edilir (cakisma olmasin).
        $esikTs = time() - 2 * 86400;
        $kullanilan = [];
        foreach ($notlar as $n) { // eski notlarin mevcut kayitlarini rezerve et
            $oTs = $n->created_at ? strtotime($n->created_at) : 0;
            if ($oTs < $esikTs && !empty($n->ses_kaydi)) $kullanilan[] = $n->ses_kaydi;
        }
        $adayCache = [];
        foreach ($notlar as $n) { // en yeniden eskiye dogru ata
            $oTs = $n->created_at ? strtotime($n->created_at) : 0;
            if ($oTs < $esikTs) continue; // eski not: dokunma
            $dahili = $n->personel_id ? Personeller::where('id', $n->personel_id)->value('dahili_no') : null;
            if (empty($dahili)) { if (!empty($n->ses_kaydi)) $kullanilan[] = $n->ses_kaydi; continue; }
            if (!isset($adayCache[$dahili])) $adayCache[$dahili] = $this->cagriMerkeziKayitAdaylari($salonId, $dahili);

            $sec = '';
            foreach ($adayCache[$dahili] as $c) {
                if (!in_array($c['path'], $kullanilan, true)) { $sec = $c['path']; break; }
            }
            if ($sec !== '') {
                $kullanilan[] = $sec;
                if ($n->ses_kaydi !== $sec) { $n->ses_kaydi = $sec; $n->save(); }
            } elseif (!empty($n->ses_kaydi)) {
                $kullanilan[] = $n->ses_kaydi; // uygun yeni aday yok, mevcudu koru
            }
        }
        // aranacak_musteriler.ses_kaydi: en son gorusmenin kaydi (geriye donuk uyumluluk)
        $enSon = $notlar->first();
        if ($enSon && !empty($enSon->ses_kaydi) && $kayit->ses_kaydi !== $enSon->ses_kaydi) {
            $kayit->ses_kaydi = $enSon->ses_kaydi; $kayit->save();
        }

        // Randevu (durum=3) satirlarinda gosterilecek aranacak tarih/saat (aranacak_musteriler).
        $randevuTarih = $kayit->tarih ? date('d.m.Y', strtotime($kayit->tarih)) : '';
        $randevuSaat  = $kayit->saat ? date('H:i', strtotime($kayit->saat)) : '';

        $gecmis = $notlar->map(function ($n) use ($randevuTarih, $randevuSaat) {
            $kod = is_null($n->sonuc) ? null : (int) $n->sonuc;
            return [
                'tarih'         => $n->created_at ? date('d.m.Y H:i', strtotime($n->created_at)) : '',
                'sonuc_kod'     => $kod,
                'sonuc'         => self::aranacakDurumMetin($n->sonuc),
                'not'           => $n->not ?? '',
                'ses'           => self::sesKaydiUrl($n->ses_kaydi),
                'randevu_tarih' => ($kod === 3 || $kod === 6) ? $randevuTarih : '',
                'randevu_saat'  => ($kod === 3 || $kod === 6) ? $randevuSaat : '',
                'satis_tutari'  => ($kod === 7 && isset($n->satis_tutari) && $n->satis_tutari !== null) ? (float) $n->satis_tutari : null,
            ];
        });

        return response()->json(['gecmis' => $gecmis]);
    }

    /**
     * Agent calisma ekrani — ZAMANI GELEN arama randevulari (durum=3, tarih+saat <= simdi).
     * Personel ise kendi listeleri; yonetici ise salonun tum listeleri. Popup hatirlatma kullanir.
     */
    public function cagri_yaklasan_randevular(Request $request)
    {
        $salonId = self::mevcutsube($request);
        $rol = self::kullaniciRolu($salonId, $this->cmAuthId());

        $q = AramaListesi::where('salon_id', $salonId);
        if ($rol == 5) {
            $q->where('personel_id', $this->aktifPersonelId($salonId));
        }
        $listeIds = $q->pluck('id')->all();
        if (empty($listeIds)) {
            return response()->json(['randevular' => []]);
        }

        $now = date('Y-m-d H:i:s');
        $altSinir = date('Y-m-d H:i:s', strtotime('-12 hours')); // cok eski randevulari gosterme

        $kayitlar = AranacakMusteriler::whereIn('arama_id', $listeIds)
            ->whereIn('durum', [3, 6])
            ->whereNotNull('tarih')->where('tarih', '!=', '')
            ->whereNotNull('saat')->where('saat', '!=', '')
            ->whereRaw("CONCAT(tarih,' ',saat) <= ?", [$now])
            ->whereRaw("CONCAT(tarih,' ',saat) >= ?", [$altSinir])
            ->with('musteri')
            ->orderByRaw("CONCAT(tarih,' ',saat) desc")
            ->limit(20)->get();

        $personelMi = ($rol == 5);
        $out = $kayitlar->map(function ($k) use ($personelMi) {
            $ad = optional($k->musteri)->name ?? 'Müşteri';
            if ($personelMi) $ad = self::adSoyadMaskele($ad);
            return [
                'id'       => $k->id,
                'arama_id' => $k->arama_id,
                'ad'       => $ad,
                'tarih'    => $k->tarih ? date('d.m.Y', strtotime($k->tarih)) : '',
                'saat'     => $k->saat ? date('H:i', strtotime($k->saat)) : '',
            ];
        });

        return response()->json(['randevular' => $out]);
    }

    /**
     * Ön Görüşme Randevusu için müşteri bilgisi (user_id + GERÇEK ad + telefon).
     * KVKK: agent normalde maskeli görür; ön görüşme randevusu OLUSTURMAK icin gercek bilgi gerekir
     * (kullanici bu davranisi acikca sececek). Sadece kendi salonunun listesindeki musteri icin.
     */
    public function cagri_musteri_ongorusme_bilgi(Request $request)
    {
        $kayit = AranacakMusteriler::where('id', $request->aranacak_musteri_id)->with('musteri')->first();
        if (!$kayit) {
            return response()->json(['success' => false], 404);
        }
        $liste = AramaListesi::where('id', $kayit->arama_id)->first();
        if (!$this->cagriListeYetkiliMi($liste)) {
            return response()->json(['success' => false, 'message' => 'Yetkiniz yok'], 403);
        }
        return response()->json([
            'success' => true,
            'user_id' => $kayit->user_id,
            'ad'      => optional($kayit->musteri)->name ?? '',
            'telefon' => optional($kayit->musteri)->cep_telefon ?? '',
        ]);
    }

    /**
     * Cagri Merkezi — Telefonda Satis (Hizli Satis): GERCEK satis kaydi olusturur.
     * Adisyon + kalem (hizmet/urun/paket) + tahsilat -> kasa & satis takibine yansir.
     * Paket icin paket_hizmetler seanslariyla adisyon_hizmetler'e acilir (SEANS verilir).
     * Tum islem TRANSACTION icinde — hata olursa hicbir sey yazilmaz (bozuk veri yok).
     */
    public function cagri_hizli_satis(Request $request)
    {
        $sube = $request->sube;
        $authUser = $this->cmUser();
        if ($authUser && !\App\Services\PersonelYetkiServisi::yetkiliYetkiVar($authUser->id, $sube, 'satis.tahsilat_al')) {
            return response()->json(['success' => false, 'message' => 'Satış için yetkiniz yok.'], 403);
        }
        $musteri_id = $request->musteri_id;
        $tip = $request->kalem_tip;                 // hizmet | urun | paket
        $itemId = $request->kalem_id;
        $fiyat = round((float) str_replace(',', '.', (string) $request->fiyat), 2);
        $odeme = $request->odeme_yontemi;
        $adet = max(1, (int) ($request->adet ?? 1));

        if (empty($musteri_id) || empty($itemId) || $fiyat <= 0 || empty($odeme) || !in_array($tip, ['hizmet', 'urun', 'paket'], true)) {
            return response()->json(['success' => false, 'message' => 'Müşteri, kalem (hizmet/ürün/paket), fiyat ve ödeme yöntemi zorunludur.']);
        }
        $tarih = date('Y-m-d');

        DB::beginTransaction();
        try {
            $adisyon_id = self::yeni_adisyon_olustur($musteri_id, $sube, 'Telefonda Satış (Çağrı Merkezi)', $tarih);

            if ($tip === 'hizmet') {
                $ah = new AdisyonHizmetler();
                $ah->adisyon_id = $adisyon_id; $ah->hizmet_id = $itemId; $ah->fiyat = $fiyat;
                $ah->islem_tarihi = $tarih; $ah->islem_saati = date('H:i:s');
                $ah->seans_sayisi = 1; $ah->bekleyen_seans = 1; $ah->kullanilan_seans = 0; $ah->kullanilmayan_seans = 0;
                $ah->indirim_tutari = 0; $ah->otomatik_randevu_olusturuldu = false;
                $ah->save();
                try { StokController::receteyiUygula((int) $sube, (int) $itemId, 'islem', null, null); } catch (\Throwable $e) {}
            } elseif ($tip === 'urun') {
                $au = new AdisyonUrunler();
                $au->adisyon_id = $adisyon_id; $au->urun_id = $itemId; $au->adet = $adet; $au->fiyat = $fiyat; $au->indirim_tutari = 0;
                $au->save();
            } else { // paket -> AdisyonPaketler + paket hizmetlerini SEANSLARIYLA ac
                $ap = new AdisyonPaketler();
                $ap->adisyon_id = $adisyon_id; $ap->paket_id = $itemId; $ap->fiyat = $fiyat; $ap->indirim_tutari = 0;
                $ph = DB::table('paket_hizmetler')->where('paket_id', $itemId)->get();
                $toplamSeans = 0;
                foreach ($ph as $h) { $toplamSeans += (int) ($h->seans ?? 0); }
                $ap->seans_sayisi = $toplamSeans; $ap->bekleyen_seans = $toplamSeans;
                $ap->kullanilan_seans = 0; $ap->kullanilmayan_seans = 0; $ap->otomatik_randevu_olusturuldu = false;
                $ap->save();
                foreach ($ph as $h) {
                    $seans = (int) ($h->seans ?? 1); if ($seans < 1) $seans = 1;
                    $ah = new AdisyonHizmetler();
                    $ah->adisyon_id = $adisyon_id; $ah->hizmet_id = $h->hizmet_id; $ah->fiyat = 0;
                    $ah->islem_tarihi = $tarih; $ah->islem_saati = date('H:i:s');
                    $ah->seans_sayisi = $seans; $ah->bekleyen_seans = $seans; $ah->kullanilan_seans = 0; $ah->kullanilmayan_seans = 0;
                    $ah->indirim_tutari = 0; $ah->otomatik_randevu_olusturuldu = false;
                    $ah->save();
                }
            }

            // Tahsilat (kasaya yansir)
            $t = new Tahsilatlar();
            $t->adisyon_id = $adisyon_id; $t->user_id = $musteri_id; $t->odeme_tarihi = $tarih;
            $t->olusturan_id = Personeller::where('salon_id', $sube)->where('yetkili_id', $authUser->id)->value('id');
            $t->salon_id = $sube; $t->tutar = $fiyat; $t->yapilan_odeme = $fiyat;
            $t->odeme_yontemi_id = $odeme; $t->notlar = 'Telefonda satış (çağrı merkezi)';
            if (!empty($request->banka)) $t->banka_id = $request->banka;
            $t->save();

            try {
                SalonAudit::log($sube, 'cagri_hizli_satis', 'adisyon', $adisyon_id,
                    (\App\User::where('id', $musteri_id)->value('name') ?: ('Müşteri #' . $musteri_id)) . ' — ' . number_format($fiyat, 2, ',', '.') . ' ₺',
                    'Telefonda satış (çağrı merkezi)');
            } catch (\Throwable $e) {}

            DB::commit();
            return response()->json(['success' => true, 'message' => 'Satış oluşturuldu ve kasaya işlendi.', 'adisyon_id' => $adisyon_id]);
        } catch (\Throwable $e) {
            DB::rollBack();
            \Log::warning('[CAGRI-MERKEZI] hizli satis hatasi: ' . $e->getMessage());
            return response()->json(['success' => false, 'message' => 'Satış oluşturulamadı: ' . $e->getMessage()]);
        }
    }

    /* ============================================================
     * Cagri Merkezi — Liste Segmentasyonu (sonuca gore ayikla, indir, personele tasi)
     * ============================================================ */

    /** Giris yapan yetkili, bu listenin salonuna yetkili mi? (sube parametresinden bagimsiz) */
    private function cagriListeYetkiliMi($liste)
    {
        if (!$liste) return false;
        return $this->cmUser()->yetkili_olunan_isletmeler
            ->where('aktif', 1)->pluck('salon_id')->map(function ($v) { return (int) $v; })
            ->contains((int) $liste->salon_id);
    }

    /** Bir arama listesini sonuca (durum) gore gruplar: her segment + adet + atanan personel. */
    public function cagri_liste_segmentler(Request $request)
    {
        $liste = AramaListesi::where('id', $request->arama_id)->first();
        if (!$this->cagriListeYetkiliMi($liste)) {
            return response()->json(['baslik' => '', 'segmentler' => []], 403);
        }
        $rows = DB::table('aranacak_musteriler')
            ->where('arama_id', $liste->id)
            ->select('durum', DB::raw('COUNT(*) as adet'))
            ->groupBy('durum')->get();

        $sayim = [];
        foreach ($rows as $r) {
            $key = is_null($r->durum) ? 'bekleyen' : (string) (int) $r->durum;
            $sayim[$key] = ($sayim[$key] ?? 0) + (int) $r->adet;
        }

        // SABIT kategori seti — buton olarak hep gosterilir (0 olsa da). Arandi yalnizca varsa.
        $tanim = [
            ['kod' => '6', 'ad' => 'Ön Görüşme Randevusu'],
            ['kod' => '7', 'ad' => 'Telefonda Satış'],
            ['kod' => '4', 'ad' => 'Görüşüldü'],
            ['kod' => '2', 'ad' => 'Cevapsız'],
            ['kod' => '5', 'ad' => 'Meşgul'],
            ['kod' => '0', 'ad' => 'Ulaşılamadı'],
            ['kod' => '3', 'ad' => 'Tekrar Aranacak'],
            ['kod' => 'bekleyen', 'ad' => 'Bekleyen'],
        ];
        if (($sayim['1'] ?? 0) > 0) {
            $tanim[] = ['kod' => '1', 'ad' => 'Arandı'];
        }
        $segmentler = [];
        foreach ($tanim as $t) {
            $segmentler[] = ['kod' => $t['kod'], 'ad' => $t['ad'], 'adet' => $sayim[$t['kod']] ?? 0];
        }
        $personelAd = $liste->personel_id ? Personeller::where('id', $liste->personel_id)->value('personel_adi') : '';
        return response()->json([
            'baslik'      => $liste->arama_baslik,
            'personel_id' => $liste->personel_id,
            'personel_ad' => $personelAd,
            'segmentler'  => $segmentler,
        ]);
    }

    /** Segment indir (CSV, Excel uyumlu). arama_id + kod (durum veya 'bekleyen'). */
    public function cagri_segment_indir(Request $request)
    {
        $salonId = self::mevcutsube($request);
        $liste = AramaListesi::where('id', $request->arama_id)->first();
        if (!$liste || (int) $liste->salon_id !== (int) $salonId) abort(403);
        $kod = (string) $request->kod;

        $q = AranacakMusteriler::where('arama_id', $liste->id)->with('musteri');
        if ($kod === 'bekleyen') $q->whereNull('durum'); else $q->where('durum', (int) $kod);
        $kayitlar = $q->get();

        $csv = "\xEF\xBB\xBF"; // UTF-8 BOM (Excel Turkce karakter)
        $csv .= "Ad Soyad;Telefon;Durum;Gorusme Notu;Randevu Tarih;Randevu Saat\n";
        $temizle = function ($s) { return str_replace(["\r", "\n", ";"], [' ', ' ', ' '], (string) $s); };
        foreach ($kayitlar as $k) {
            $csv .= $temizle(optional($k->musteri)->name) . ';'
                  . $temizle(optional($k->musteri)->cep_telefon) . ';'
                  . self::aranacakDurumMetin($k->durum) . ';'
                  . $temizle($k->musteri_not) . ';'
                  . $temizle($k->tarih) . ';'
                  . $temizle($k->saat) . "\n";
        }
        $adEtiket = $kod === 'bekleyen' ? 'Bekleyen' : self::aranacakDurumMetin((int) $kod);
        $dosya = 'liste-' . $liste->id . '-' . preg_replace('/[^a-zA-Z0-9]/', '', $this->trChar($adEtiket)) . '.csv';
        return response($csv)
            ->header('Content-Type', 'text/csv; charset=utf-8')
            ->header('Content-Disposition', 'attachment; filename="' . $dosya . '"');
    }

    /** Turkce karakterleri dosya adi icin sadelestir. */
    private function trChar($s)
    {
        return strtr((string) $s, ['ç'=>'c','Ç'=>'C','ğ'=>'g','Ğ'=>'G','ı'=>'i','İ'=>'I','ö'=>'o','Ö'=>'O','ş'=>'s','Ş'=>'S','ü'=>'u','Ü'=>'U']);
    }

    /** Segmenti yeni bir listeye TASI ve baska personele ata (gecmis/kayitlar da tasinir). */
    public function cagri_segment_ata(Request $request)
    {
        $liste = AramaListesi::where('id', $request->arama_id)->first();
        if (!$liste) {
            return response()->json(['success' => false, 'message' => 'Liste bulunamadı.']);
        }
        // Yetki: salon DOGRUDAN listeden alinir (sube parametresine bagimli degil).
        $salonId = (int) $liste->salon_id;
        $yetkiliMi = $this->cmUser()->yetkili_olunan_isletmeler
            ->where('aktif', 1)->pluck('salon_id')->map(function ($v) { return (int) $v; })->contains($salonId);
        if (!$yetkiliMi) {
            return response()->json(['success' => false, 'message' => 'Bu listeye yetkiniz yok.']);
        }
        $personelId = $request->personel_id;
        $hedef = $personelId ? Personeller::where('id', $personelId)->where('salon_id', $salonId)->first() : null;
        if (!$hedef) {
            return response()->json(['success' => false, 'message' => 'Geçerli bir personel seçin.']);
        }
        $kod = (string) $request->kod;

        $q = AranacakMusteriler::where('arama_id', $liste->id);
        if ($kod === 'bekleyen') $q->whereNull('durum'); else $q->where('durum', (int) $kod);
        $ids = $q->pluck('id')->all();
        if (empty($ids)) {
            return response()->json(['success' => false, 'message' => 'Bu segmentte müşteri yok.']);
        }

        $adEtiket = $kod === 'bekleyen' ? 'Bekleyen' : self::aranacakDurumMetin((int) $kod);
        $baslik = trim((string) $request->baslik);
        if ($baslik === '') $baslik = $liste->arama_baslik . ' — ' . $adEtiket;

        $yeni = new AramaListesi();
        $yeni->salon_id = $salonId;
        $yeni->arama_baslik = $baslik;
        $yeni->personel_id = $personelId;
        $yeni->aranacak_tarih = null;
        $yeni->olusturan_yetkili_id = $this->cmAuthId();
        $yeni->durum = 1;
        $yeni->save();

        // TASI: kayitlar yeni listeye gecer (orijinalden cikar). Gecmis/ses kayitlari da gider.
        AranacakMusteriler::whereIn('id', $ids)->update(['arama_id' => $yeni->id, 'updated_at' => date('Y-m-d H:i:s')]);
        if (Schema::hasTable('gorusme_notlari')) {
            \App\GorusmeNotlari::whereIn('aranacak_musteri_id', $ids)->update(['arama_id' => $yeni->id]);
        }

        return response()->json([
            'success' => true,
            'message' => count($ids) . ' müşteri "' . $hedef->personel_adi . '" personeline taşındı (yeni liste: ' . $baslik . ').',
            'yeni_liste_id' => $yeni->id,
        ]);
    }

    /**
     * Listenin TAMAMINI baska personele ata, ya da atamayi GERI AL (personel_id=null).
     * Atamayi geri alinca liste hicbir personelin kuyrugunda gorunmez (sahip geri cekmis olur).
     */
    public function cagri_liste_personel_degistir(Request $request)
    {
        $liste = AramaListesi::where('id', $request->arama_id)->first();
        if (!$this->cagriListeYetkiliMi($liste)) {
            return response()->json(['success' => false, 'message' => 'Bu listeye yetkiniz yok.']);
        }
        $salonId = (int) $liste->salon_id;
        $personelId = $request->filled('personel_id') ? $request->personel_id : null;

        if ($personelId) {
            $hedef = Personeller::where('id', $personelId)->where('salon_id', $salonId)->first();
            if (!$hedef) {
                return response()->json(['success' => false, 'message' => 'Geçerli bir personel seçin.']);
            }
            $liste->personel_id = $personelId;
            $liste->save();
            return response()->json(['success' => true, 'message' => 'Liste "' . $hedef->personel_adi . '" personeline atandı.']);
        }

        // Atamayi geri al
        $liste->personel_id = null;
        $liste->save();
        return response()->json(['success' => true, 'message' => 'Atama geri alındı — bu liste artık hiçbir personelde görünmüyor.']);
    }

    /** Bir arama listesini ve icindeki tum musteri/gorusme kayitlarini SILER (geri alinamaz). */
    public function cagri_liste_sil(Request $request)
    {
        $liste = AramaListesi::where('id', $request->arama_id)->first();
        if (!$this->cagriListeYetkiliMi($liste)) {
            return response()->json(['success' => false, 'message' => 'Bu listeye yetkiniz yok.']);
        }
        try {
            $ids = AranacakMusteriler::where('arama_id', $liste->id)->pluck('id')->all();
            if (Schema::hasTable('gorusme_notlari')) {
                \App\GorusmeNotlari::where('arama_id', $liste->id)->delete();
                if (!empty($ids)) {
                    \App\GorusmeNotlari::whereIn('aranacak_musteri_id', $ids)->delete();
                }
            }
            AranacakMusteriler::where('arama_id', $liste->id)->delete();
            $baslik = $liste->arama_baslik;
            $liste->delete();
            return response()->json(['success' => true, 'message' => '"' . $baslik . '" listesi ve ' . count($ids) . ' müşteri kaydı silindi.']);
        } catch (\Throwable $e) {
            \Log::warning('[CAGRI-MERKEZI] liste silinemedi (id=' . $liste->id . '): ' . $e->getMessage());
            return response()->json(['success' => false, 'message' => 'Liste silinemedi: ' . $e->getMessage()]);
        }
    }

    /* ============================================================
     * Cagri Merkezi — Scriptler & Kategoriler (yonetici tanimlar, agent kullanir)
     * ============================================================ */

    /** Yonetici ayar sayfasi: gorusme scriptleri + sonuc kategorileri yonetimi. */
    public function cagri_ayarlari(Request $request)
    {
        $salonId = self::mevcutsube($request);
        $isletmeler = Auth::guard('isletmeyonetim')->user()->yetkili_olunan_isletmeler->where('aktif', 1)->pluck('salon_id')->toArray();
        $isletme = Salonlar::where('id', $salonId)->first();

        if (!in_array($salonId, $isletmeler)) {
            return view('isletmeadmin.yetkisizerisim');
        }
        $rol = self::kullaniciRolu($salonId, Auth::guard('isletmeyonetim')->user()->id);
        if ($rol == 5) {
            return view('isletmeadmin.yetkisizerisim'); // personel goremez
        }

        // Sema garantisi: prod migrate calistirmadigi icin tablolari burada da garanti et (idempotent).
        try { \App\Services\CagriMerkeziSchema::ensure(); } catch (\Throwable $e) {}

        return view('isletmeadmin.cagri_ayarlari', [
            'kullaniciRolu'           => $rol,
            'bildirimler'             => self::bildirimgetir($request),
            'sayfa_baslik'            => 'Çağrı Merkezi Ayarları',
            'pageindex'               => 46,
            'isletme'                 => $isletme,
            'kalan_uyelik_suresi'     => self::lisans_sure_kontrol($request),
            'yetkiliolunanisletmeler' => $isletmeler,
        ]);
    }

    /** Salonun tum scriptleri (yonetici listesi). */
    public function cagri_script_liste(Request $request)
    {
        if (!Schema::hasTable('cagri_scriptleri')) {
            return response()->json(['scriptler' => []]);
        }
        $salonId = self::mevcutsube($request);
        $scriptler = \App\CagriScript::where('salon_id', $salonId)->orderBy('id', 'desc')->get(['id', 'baslik', 'icerik', 'aktif']);
        return response()->json(['scriptler' => $scriptler]);
    }

    /** Script ekle/guncelle. */
    public function cagri_script_kaydet(Request $request)
    {
        $salonId = self::mevcutsube($request);
        if (self::kullaniciRolu($salonId, Auth::guard('isletmeyonetim')->user()->id) == 5) {
            return response()->json(['success' => false, 'message' => 'Yetkiniz yok'], 403);
        }
        $baslik = trim((string) $request->baslik);
        if ($baslik === '') {
            return response()->json(['success' => false, 'message' => 'Başlık zorunlu']);
        }
        $script = $request->filled('id')
            ? \App\CagriScript::where('id', $request->id)->where('salon_id', $salonId)->first()
            : new \App\CagriScript();
        if (!$script) {
            return response()->json(['success' => false, 'message' => 'Kayıt bulunamadı']);
        }
        $script->salon_id = $salonId;
        $script->baslik = $baslik;
        $script->icerik = (string) $request->icerik;
        $script->aktif = $request->filled('aktif') ? (int) $request->aktif : 1;
        $script->save();
        return response()->json(['success' => true, 'id' => $script->id]);
    }

    /** Script sil. */
    public function cagri_script_sil(Request $request)
    {
        $salonId = self::mevcutsube($request);
        if (self::kullaniciRolu($salonId, Auth::guard('isletmeyonetim')->user()->id) == 5) {
            return response()->json(['success' => false, 'message' => 'Yetkiniz yok'], 403);
        }
        \App\CagriScript::where('id', $request->id)->where('salon_id', $salonId)->delete();
        return response()->json(['success' => true]);
    }

    /** Salonun kategori agaci (ana + alt). Yonetici ve agent ayni veriyi okur. */
    public function cagri_kategori_liste(Request $request)
    {
        if (!Schema::hasTable('cagri_kategorileri')) {
            return response()->json(['kategoriler' => []]);
        }
        $salonId = self::mevcutsube($request);
        $hepsi = \App\CagriKategori::where('salon_id', $salonId)->where('aktif', 1)
            ->orderBy('sira')->orderBy('id')->get(['id', 'ust_id', 'ad']);

        // NOT: Laravel 5.6 Collection'da whereNull yok -> filter ile null kontrolu.
        $analar = $hepsi->filter(function ($x) { return is_null($x->ust_id); });
        $agac = [];
        foreach ($analar as $ana) {
            $altlar = $hepsi->filter(function ($a) use ($ana) { return (int) $a->ust_id === (int) $ana->id; })
                ->map(function ($a) { return ['id' => $a->id, 'ad' => $a->ad]; })
                ->values();
            $agac[] = [
                'id'     => $ana->id,
                'ad'     => $ana->ad,
                'altlar' => $altlar,
            ];
        }
        return response()->json(['kategoriler' => $agac]);
    }

    /** Kategori veya alt kategori ekle/guncelle (ust_id bos => ana kategori). */
    public function cagri_kategori_kaydet(Request $request)
    {
        $salonId = self::mevcutsube($request);
        if (self::kullaniciRolu($salonId, Auth::guard('isletmeyonetim')->user()->id) == 5) {
            return response()->json(['success' => false, 'message' => 'Yetkiniz yok'], 403);
        }
        $ad = trim((string) $request->ad);
        if ($ad === '') {
            return response()->json(['success' => false, 'message' => 'Ad zorunlu']);
        }
        $kat = $request->filled('id')
            ? \App\CagriKategori::where('id', $request->id)->where('salon_id', $salonId)->first()
            : new \App\CagriKategori();
        if (!$kat) {
            return response()->json(['success' => false, 'message' => 'Kayıt bulunamadı']);
        }
        $kat->salon_id = $salonId;
        $kat->ad = $ad;
        // ust_id sadece yeni kayitta belirlenir; gecerli ve ayni salona ait olmali
        if (!$request->filled('id')) {
            $ustId = $request->filled('ust_id') ? (int) $request->ust_id : null;
            if ($ustId) {
                $ust = \App\CagriKategori::where('id', $ustId)->where('salon_id', $salonId)->whereNull('ust_id')->first();
                $ustId = $ust ? $ust->id : null;
            }
            $kat->ust_id = $ustId;
        }
        $kat->aktif = 1;
        $kat->save();
        return response()->json(['success' => true, 'id' => $kat->id]);
    }

    /** Kategori sil (ana kategori silinirse alt kategorileri de gider). */
    public function cagri_kategori_sil(Request $request)
    {
        $salonId = self::mevcutsube($request);
        if (self::kullaniciRolu($salonId, Auth::guard('isletmeyonetim')->user()->id) == 5) {
            return response()->json(['success' => false, 'message' => 'Yetkiniz yok'], 403);
        }
        $kat = \App\CagriKategori::where('id', $request->id)->where('salon_id', $salonId)->first();
        if ($kat) {
            \App\CagriKategori::where('ust_id', $kat->id)->where('salon_id', $salonId)->delete(); // alt kategoriler
            $kat->delete();
        }
        return response()->json(['success' => true]);
    }

