    public function hizmetRaporlari($salonId)
    {
        $tahsilatlar = Tahsilatlar::with(['hizmet_odemeleri.adisyon_hizmet.hizmet'])
            ->where('salon_id', $salonId)
            ->get()
            ->map(function($adisyon) {
                return $adisyon->hizmet_odemeleri
                    ->groupBy('hizmet_id')
                    ->map(function($items) {
                        return [
                            'adet' => $items->count(),
                            'toplam_tutar' => $items->sum('tutar'),
                            'hizmet_adi' => $items->first()->adisyon_hizmet->hizmet->hizmet_adi ?? null
                        ];
                    })
                    ->values(); // indexleri 0,1,2... yapmak için
            });


        return $adisyonlar;
    }
      public function hizmetRaporlari3($salonId)
    {
        // 1. Adisyonları çek
        $adisyonlar = Adisyonlar::with(['hizmetler.hizmet'])
            ->where('salon_id', $salonId)
            ->get();

        // 2. Tüm hizmetleri tek koleksiyonda birleştir
        $tumHizmetler = $adisyonlar->flatMap(function ($adisyon) {
            return $adisyon->hizmetler;
        });
        $tumUrunler = $adisyonlar->flatMap(function ($adisyon) {
            return $adisyon->urunler;
        });
        $tumPaketler = $adisyonlar->flatMap(function ($adisyon) {
            return $adisyon->paketler;
        });
        // 3. Hizmet_id üzerinden grupla
        $hizmetRaporu = $tumHizmetler->groupBy('hizmet_id')->map(function($items) {
            $adisyonHizmetIds = $items->pluck('id');
            $toplamKazanc = TahsilatHizmetler::whereIn('adisyon_hizmet_id', $adisyonHizmetIds)->sum('tutar');

            return [
                'id' => $items->first()->hizmet_id,
                'adet' => $items->count(),
                'toplam_tutar' => $items->sum('fiyat'),
                'hizmet_adi' => $items->first()->hizmet->hizmet_adi ?? null,
                'toplamKazanc' => $toplamKazanc,
            ];
        })->values();
        $urunRaprou = $tumUrunler->groupBy('urun_id')->map(function($items) {
            $adisyonUrunIds = $items->pluck('id');
            $toplamKazanc = TahsilatUrunler::whereIn('adisyon_urun_id', $adisyonUrunIds)->sum('tutar');

            return [
                'id' => $items->first()->hizmet_id,
                'adet' => $items->count(),
                'toplam_tutar' => $items->sum('fiyat'),
                'hizmet_adi' => $items->first()->urun->urun_adi ?? null,
                'toplamKazanc' => $toplamKazanc,
            ];
        })->values();
        $paketRaporu = $tumPaketler->groupBy('paket_id')->map(function($items) {
            $adisyonPaketIds = $items->pluck('id');
            $toplamKazanc = TahsilatPaketler::whereIn('adisyon_paket_id', $adisyonPaketIds)->sum('tutar');

            return [
                'id' => $items->first()->hizmet_id,
                'adet' => $items->count(),
                'toplam_tutar' => $items->sum('fiyat'),
                'hizmet_adi' => $items->first()->paket->paket_adi ?? null,
                'toplamKazanc' => $toplamKazanc,
            ];
        })->values();

        return [
            'hizmetler' => $hizmetRaporu,
            'urunler' => $urunRaporu,
            'paketler' => $paketRaporu,
        ];
    }
