    public function hizmetRaporlari2($salonId,$tarih1,$tarih2,$personel)
    {
        // 1. Adisyonları çek
        $adisyonlar = Adisyonlar::with(['hizmetler.hizmet'])
            ->where('salon_id', $salonId)->where(function($q) use($personel){
                if($personel != '')
                    $q->whereHas('hizmetler',function($q2) use($personel){
                        $q2->where('personel_id',$personel);
                    });
            })->whereBetween('tarih',[$tarih1,$tarih2])->get();

        // 2. Tüm hizmetleri tek koleksiyonda birleştir
        $tumHizmetler = $adisyonlar->flatMap(function ($adisyon) use($personel) { 

           if ($personel != '') {
                return $adisyon->hizmetler->where('personel_id', $personel);
            }

            return $adisyon->hizmetler;
        });

        // 3. Hizmet_id üzerinden grupla
        $raporlar = $tumHizmetler->groupBy('hizmet_id')->map(function ($items) {


            $adisyonHizmetIds = $items->pluck('id');

            $toplamKazanc = TahsilatHizmetler::whereIn('adisyon_hizmet_id', $adisyonHizmetIds)
                ->sum('tutar');

            return (object)[
                'id'=>$items->first()->hizmet_id,
                'adet' => $items->count(),
                'toplam_tutar' => number_format($items->sum('fiyat'),'2',',','.'),

                
                'hizmet_adi' => $items->first()->hizmet->hizmet_adi ?? null,
                'toplamKazanc' => number_format($toplamKazanc,'2',',','.'),
                
                'borc' => number_format($items->sum('fiyat') - $toplamKazanc,'2',',','.'),
                'toplamTutarNumeric'=>$items->sum('fiyat'),
                'toplamKazancNumeric'=>$toplamKazanc,
                'borcNumeric'=>$items->sum('fiyat') - $toplamKazanc,
                'islemler'=> ' <a title="Detaylı Bilgi" name="hizmeti_alan_musteriler" data-value="'.($items->first()->hizmet_id).'" data-adi="'.htmlspecialchars($items->first()->hizmet->hizmet_adi ?? '', ENT_QUOTES).'" href="javascript:void(0)" class="btn btn-info"><i class="dw dw-eye"></i> </a>'
            ];
        })->values();

        return $raporlar;
    }

    public function hizmetiAlanMusteriler(Request $request)
    {
        $salonId  = $request->salonId;
        $hizmetId = $request->hizmetId;
        $personel = $request->personel ?? '';

        $tarih1 = date('Y-m-01');
        $tarih2 = date('Y-m-d');
        if($request->zaman == 'ozel'){
            if($request->baslangicTarihi != '') $tarih1 = $request->baslangicTarihi;
            if($request->bitisTarihi    != '') $tarih2 = $request->bitisTarihi;
        } else if($request->zaman) {
            $parcalar = explode(' / ', $request->zaman);
            if(count($parcalar) == 2){
                $tarih1 = $parcalar[0];
                $tarih2 = $parcalar[1];
            }
        }

        if(!$salonId || !$hizmetId){
            return response()->json(['hata'=>'Eksik parametre'], 422);
        }

        $isletmeler = [];
        if(Auth::guard('satisortakligi')->check()){
            $isletmeler = [15];
        } else {
            $isletmeler = Auth::guard('isletmeyonetim')->user()
                ->yetkili_olunan_isletmeler->where('aktif',1)->pluck('salon_id')->toArray();
        }
        if(!in_array($salonId, $isletmeler)){
            return response()->json(['hata'=>'Yetkisiz erişim'], 403);
        }

        $adisyonlar = Adisyonlar::with(['musteri'])
            ->where('salon_id', $salonId)
            ->whereBetween('tarih', [$tarih1, $tarih2])
            ->whereHas('hizmetler', function($q) use($hizmetId, $personel){
                $q->where('hizmet_id', $hizmetId);
                if($personel != '') $q->where('personel_id', $personel);
            })
            ->get();

        $sonuc = collect();
        foreach($adisyonlar as $adisyon){
            $kalemler = $adisyon->hizmetler->where('hizmet_id', $hizmetId);
            if($personel != ''){
                $kalemler = $kalemler->where('personel_id', $personel);
            }
            foreach($kalemler as $h){
                $odenen = TahsilatHizmetler::where('adisyon_hizmet_id', $h->id)->sum('tutar');
                $tarihRaw = $h->islem_tarihi ?: $adisyon->tarih;
                $personelAdi = optional($h->personel)->personel_adi ?: '-';
                $sonuc->push([
                    'tarih_sirala' => $tarihRaw,
                    'tarih'        => $tarihRaw ? date('d.m.Y', strtotime($tarihRaw)) : '-',
                    'musteri_adi'  => optional($adisyon->musteri)->name ?: '-',
                    'telefon'      => optional($adisyon->musteri)->cep_telefon ?: '-',
                    'personel'     => $personelAdi,
                    'fiyat'        => number_format($h->fiyat, 2, ',', '.'),
                    'odenen'       => number_format($odenen, 2, ',', '.'),
                    'kalan'        => number_format($h->fiyat - $odenen, 2, ',', '.'),
                ]);
            }
        }

        $sonuc = $sonuc->sortByDesc('tarih_sirala')->values()->map(function($r){
            unset($r['tarih_sirala']);
            return $r;
        });

        return response()->json($sonuc);
    }

     public function urunRaporlari($salonId,$tarih1,$tarih2,$personel)
    {
        // 1. Adisyonları çek
        $adisyonlar = Adisyonlar::with(['urunler.urun'])
            ->where('salon_id', $salonId)->where(function($q) use($personel){
                if($personel != '')
                    $q->whereHas('urunler',function($q2) use($personel){
                        $q2->where('personel_id',$personel);
                    });
            })->whereBetween('tarih',[$tarih1,$tarih2])
            ->get();

        
        $tumUrunler = $adisyonlar->flatMap(function ($adisyon) use($personel) {
             if ($personel != '') {
                return $adisyon->urunler
                    ->where('personel_id', $personel);
            }

            return $adisyon->urunler;
        });



         
        $raporlar = $tumUrunler->groupBy('urun_id')->map(function ($items) {
            $adisyonUrunIds = $items->pluck('id');

            $toplamKazanc = TahsilatUrunler::whereIn('adisyon_urun_id', $adisyonUrunIds)
                ->sum('tutar');

            return (object)[
                'id'=>$items->first()->urun_id,
                'adet' => $items->count(),
                'toplam_tutar' => number_format($items->sum('fiyat'),'2',',','.'),
                'urun_adi' => $items->first()->urun->urun_adi ?? null,
                 'toplamKazanc' => number_format($toplamKazanc,'2',',','.'),
                'borc' => number_format($items->sum('fiyat') - $toplamKazanc,'2',',','.'),
                'islemler'=> ' <a title="Detaylı Bilgi" name="urunu_alan_musteriler" data-value""  href="" class="btn btn-info"><i class="dw dw-eye"></i> </a>',
                 'toplamTutarNumeric'=>$items->sum('fiyat'),
                'toplamKazancNumeric'=>$toplamKazanc,
                'borcNumeric'=>$items->sum('fiyat') - $toplamKazanc,

            ];
        })->values();

        return $raporlar;
    }
     public function paketRaporlari($salonId,$tarih1,$tarih2,$personel)
    {
        // 1. Adisyonları çek
        $adisyonlar = Adisyonlar::with(['paketler.paket'])
            ->where('salon_id', $salonId)->where(function($q) use($personel){
                if($personel != '')
                    $q->whereHas('paketler',function($q2) use($personel){
                        $q2->where('personel_id',$personel);
                    });
            })->whereBetween('tarih',[$tarih1,$tarih2])
            ->get();

        // 2. Tüm hizmetleri tek koleksiyonda birleştir
        $tumPaketler = $adisyonlar->flatMap(function ($adisyon)  use($personel){
             if ($personel != '') {
                return $adisyon->paketler
                    ->where('personel_id', $personel);
            }

            return $adisyon->paketler;
        });

        // 3. Hizmet_id üzerinden grupla
        $raporlar = $tumPaketler->groupBy('paket_id')->map(function ($items) {
            $adisyonPaketIds = $items->pluck('id');

            $toplamKazanc = TahsilatPaketler::whereIn('adisyon_paket_id', $adisyonPaketIds)
                ->sum('tutar');

            return (object)[
                'id'=>$items->first()->paket_id,
                'adet' => $items->count(),
                'toplam_tutar' => number_format($items->sum('fiyat'),'2',',','.'),
                'paket_adi' => $items->first()->paket->paket_adi ?? null,
                 'toplamKazanc' => number_format($toplamKazanc,'2',',','.'),
                'borc' => number_format($items->sum('fiyat') - $toplamKazanc,'2',',','.'),
                'islemler'=> ' <a title="Detaylı Bilgi" name="paketi_alan_musteriler" data-value""  href="" class="btn btn-info"><i class="dw dw-eye"></i> </a>',
                 'toplamTutarNumeric'=>$items->sum('fiyat'),
                'toplamKazancNumeric'=>$toplamKazanc,
                'borcNumeric'=>$items->sum('fiyat') - $toplamKazanc,
            ];
        })->values();

        return $raporlar;
    }
    // Hizmet + Urun + Paket satislarini tek listede birlestirir (Tumu sekmesi)
    public function tumRaporlari($salonId,$tarih1,$tarih2,$personel='')
    {
        $birlestir = function($koleksiyon,$tur,$adAnahtar){
            return $koleksiyon->map(function($r) use($tur,$adAnahtar){
                return (object)[
                    'tur'                => $tur,
                    'ad'                 => $r->{$adAnahtar} ?? '-',
                    'adet'               => $r->adet,
                    'toplam_tutar'       => $r->toplam_tutar,
                    'toplamKazanc'       => $r->toplamKazanc,
                    'borc'               => $r->borc,
                    'toplamTutarNumeric' => $r->toplamTutarNumeric,
                    'toplamKazancNumeric'=> $r->toplamKazancNumeric,
                    'borcNumeric'        => $r->borcNumeric,
                ];
            });
        };

        $hizmet = $birlestir(self::hizmetRaporlari2($salonId,$tarih1,$tarih2,$personel),'Hizmet','hizmet_adi');
        $urun   = $birlestir(self::urunRaporlari($salonId,$tarih1,$tarih2,$personel),'Ürün','urun_adi');
        $paket  = $birlestir(self::paketRaporlari($salonId,$tarih1,$tarih2,$personel),'Paket','paket_adi');

        return $hizmet->concat($urun)->concat($paket)->values();
    }
    public function personelRaporlari($salonId,$tarih1,$tarih2)
    {

         
       $adisyonlar = Adisyonlar::with([
                'hizmetler.personel',
                'hizmetler.hizmet',
                'urunler.personel',
                'urunler.urun',
                'paketler.personel',
                'paketler.paket',
            ])
            ->where('salon_id', $salonId)->whereBetween('tarih',[$tarih1,$tarih2])
            ->get();

        // Detayli (kalem bazli) prim oranlari
        $detayHarita = $this->detayliPrimHaritasi($salonId);

        // 1. Hizmet gelir ve prim
        $hizmetPersonel = $adisyonlar->flatMap(fn($adisyon) => $adisyon->hizmetler)
            ->filter(fn($item) => $item->personel && $item->personel->aktif == 1)
            ->groupBy('personel_id')
            ->mapWithKeys(function($items, $personel_id) use($detayHarita) {
                $personel = $items->first()->personel;
                $toplamKazanc = TahsilatHizmetler::whereIn('adisyon_hizmet_id', $items->pluck('id'))->sum('tutar');
                if(!empty($personel->hizmet_prim_detayli)){
                    $oranlar = $detayHarita[$personel_id]['hizmet'] ?? [];
                    $prim = 0;
                    foreach($items->groupBy('hizmet_id') as $hizmetId => $grup){
                        $gKazanc = TahsilatHizmetler::whereIn('adisyon_hizmet_id', $grup->pluck('id'))->sum('tutar');
                        $prim += (float)$gKazanc * (float)($oranlar[$hizmetId] ?? 0)/100;
                    }
                } else {
                    $prim = $toplamKazanc * ($personel->hizmet_prim_yuzde ?? 0)/100;
                }
                return [$personel_id => [
                    'personel_adi' => $personel->personel_adi ?? null,
                    'hizmet_geliri' => $toplamKazanc,
                    'hizmet_primi' => $prim
                ]];
            })->toArray();

        // 2. Ürün gelir ve prim
        $urunPersonel = $adisyonlar->flatMap(fn($adisyon) => $adisyon->urunler)
            ->filter(fn($item) => $item->personel && $item->personel->aktif == 1)
            ->groupBy('personel_id')
            ->mapWithKeys(function($items, $personel_id) use($detayHarita) {
                $personel = $items->first()->personel;
                $toplamKazanc = TahsilatUrunler::whereIn('adisyon_urun_id', $items->pluck('id'))->sum('tutar');
                if(!empty($personel->urun_prim_detayli)){
                    $oranlar = $detayHarita[$personel_id]['urun'] ?? [];
                    $prim = 0;
                    foreach($items->groupBy('urun_id') as $urunId => $grup){
                        $gKazanc = TahsilatUrunler::whereIn('adisyon_urun_id', $grup->pluck('id'))->sum('tutar');
                        $prim += (float)$gKazanc * (float)($oranlar[$urunId] ?? 0)/100;
                    }
                } else {
                    $prim = $toplamKazanc * ($personel->urun_prim_yuzde ?? 0)/100;
                }
                return [$personel_id => [
                    'urun_geliri' => $toplamKazanc,
                    'urun_primi' => $prim
                ]];
            })->toArray();

        // 3. Paket gelir ve prim
        $paketPersonel = $adisyonlar->flatMap(fn($adisyon) => $adisyon->paketler)
            ->filter(fn($item) => $item->personel && $item->personel->aktif == 1)
            ->groupBy('personel_id')
            ->mapWithKeys(function($items, $personel_id) use($detayHarita) {
                $personel = $items->first()->personel;
                $toplamKazanc = TahsilatPaketler::whereIn('adisyon_paket_id', $items->pluck('id'))->sum('tutar');
                if(!empty($personel->paket_prim_detayli)){
                    $oranlar = $detayHarita[$personel_id]['paket'] ?? [];
                    $prim = 0;
                    foreach($items->groupBy('paket_id') as $paketId => $grup){
                        $gKazanc = TahsilatPaketler::whereIn('adisyon_paket_id', $grup->pluck('id'))->sum('tutar');
                        $prim += (float)$gKazanc * (float)($oranlar[$paketId] ?? 0)/100;
                    }
                } else {
                    $prim = $toplamKazanc * ($personel->paket_prim_yuzde ?? 0)/100;
                }
                return [$personel_id => [
                    'paket_geliri' => $toplamKazanc,
                    'paket_primi' => $prim
                ]];
            })->toArray();

        // 4. Hepsini birleştir
        $personelRaporu = [];
        $personelIds = array_unique(array_merge(array_keys($hizmetPersonel), array_keys($urunPersonel), array_keys($paketPersonel)));

        foreach($personelIds as $id) {
            $personelRaporu[] = [
                'personel_adi' => $hizmetPersonel[$id]['personel_adi'] ?? $urunPersonel[$id]['personel_adi'] ?? $paketPersonel[$id]['personel_adi'] ?? null,
                'hizmet_geliri' => $hizmetPersonel[$id]['hizmet_geliri'] ?? 0,
                'hizmet_primi' => $hizmetPersonel[$id]['hizmet_primi'] ?? 0,
                'urun_geliri' => $urunPersonel[$id]['urun_geliri'] ?? 0,
                'urun_primi' => $urunPersonel[$id]['urun_primi'] ?? 0,
                'paket_geliri' => $paketPersonel[$id]['paket_geliri'] ?? 0,
                'paket_primi' => $paketPersonel[$id]['paket_primi'] ?? 0,
            ];
        }
        return $personelRaporu;
         
    }
    public function personelYonetimi(Request $request)
    {
        $isletmeler = '';
        $isletme='';
        if(Auth::guard('satisortakligi')->check())
        {
            $isletmeler = [15];
            $isletme = Salonlar::where('id',15)->first();
        }
        else{
            $isletmeler = Auth::guard('isletmeyonetim')->user()->yetkili_olunan_isletmeler->where('aktif',1)->pluck('salon_id')->toArray();
            $isletme= Salonlar::where('id',self::mevcutsube($request))->first();
        }


        if(!in_array(self::mevcutsube($request),$isletmeler ))
        {
            return view('isletmeadmin.yetkisizerisim');
            exit(0);
        }
        if(str_contains(self::lisans_sure_kontrol($request),'-'))
        {
            return view('isletmeadmin.lisanssurebitti',['isletme'=>$isletme]);
            exit(0);
        }
        // Yetki: bu sayfanin gerektirdigi yetki yoksa 403
        $_authUser = Auth::guard('isletmeyonetim')->user();
        if ($_authUser && !\App\Services\PersonelYetkiServisi::yetkiliYetkiVar($_authUser->id, self::mevcutsube($request), 'personel.liste_gor')) {
            return view('isletmeadmin.yetkisizerisim');
            exit(0);
        }

        $personeller = self::personel_liste_getir($request);

        // Prim & Hak Edis sekmesi icin veri (ay/yil veya gunluk mod query param'lariyla)
        $yil = (int)($request->yil ?? date('Y'));
        $ay  = (int)($request->ay ?? date('n'));
        if($ay < 1 || $ay > 12) $ay = (int)date('n');
        $mod = $request->mod === 'gunluk' ? 'gunluk' : 'aylik';
        $gun = ($mod==='gunluk' && preg_match('/^\d{4}-\d{2}-\d{2}$/', (string)$request->gun)) ? $request->gun : date('Y-m-d');
        if($mod==='gunluk'){
            $tarih1 = $tarih2 = $gun;
            $rapor  = $this->primHakedisVerisi($isletme->id, $tarih1, $tarih2, $gun);
        } else {
            $tarih1 = sprintf('%04d-%02d-01', $yil, $ay);
            $tarih2 = date('Y-m-t', strtotime($tarih1));
            $rapor  = $this->primHakedisVerisi($isletme->id, $tarih1, $tarih2);
        }

        return view('isletmeadmin.personelyonetimi',['bildirimler'=>self::bildirimgetir($request),'sayfa_baslik' => 'Personel Yönetimi','pageindex' => 401,'personeller' => $personeller, 'kalan_uyelik_suresi' => self::lisans_sure_kontrol($request),'urun_drop'=>self::urundropliste($request),
            'yetkiliolunanisletmeler'=>$isletmeler,'isletme'=>$isletme,'roller'=>Role::all(),
            'rapor'=>$rapor,'yil'=>$yil,'ay'=>$ay,'tarih1'=>$tarih1,'tarih2'=>$tarih2,'mod'=>$mod,'gun'=>$gun]);
    }
