    public function kampanyaIceriginiGoruntule(Request $request)
    {
        $ilkMusteri = '';
        if(!isset($request->katilimciId))
            $ilkMusteri = MusteriPortfoy::where('salon_id',$request->salonId)->where('aktif',1)->orderBy('id','desc')->first();
        
        $isletme = Salonlar::where('id',$request->salonId)->value('santral_telaffuz_hatirlatma_aramasi');
        
        $ornekMusteri = isset($request->katilimciId) ? User::where('id',$request->katilimciId)->first() : User::where('id',$ilkMusteri->user_id)->first();
        $musteriAdi = $ornekMusteri->name;
        $beyBayanStr = '';
        if($ornekMusteri->cinsiyet == 0){
            $beyBayanStr = 'hanım';
            $ornekMusteriArr = explode(' ',$musteriAdi);
            $musteriAdi = $ornekMusteriArr[0].' '.$beyBayanStr;
        }
        if($ornekMusteri->cinsiyet == 1){
            $beyBayanStr = 'bey';
            $ornekMusteriArr = explode(' ',$musteriAdi);
            $musteriAdi = $ornekMusteriArr[0].' '.$beyBayanStr;
        }
         

        // Şablon ID'si "sablon-X" prefix'liyse kullanıcının kendi SMS taslağı,
        // değilse sistem KampanyaSablonlari kaydı.
        $sablonIdRaw = $request->sablonId;
        if (is_string($sablonIdRaw) && strpos($sablonIdRaw, 'senaryo-') === 0) {
            // Senaryo Sihirbazı ile oluşturulan senaryo: Santral Arama'da açılış + ilk
            // soru seslendirilir (dallanma santralde), diğer kanallarda tek metin.
            $senaryo = KampanyaSenaryolari::where('id', (int) substr($sablonIdRaw, 8))->first();
            $sablon  = '';
            if ($senaryo) {
                $ad = $senaryo->adimlar ?: [];
                $sablon = ((int) $senaryo->gorev_turu === 1)
                    ? trim(($ad['acilis'] ?? '').' '.($ad['soru_kod'] ?? ''))
                    : (string) ($ad['acilis'] ?? '');
            }
        } elseif (is_string($sablonIdRaw) && strpos($sablonIdRaw, 'sablon-') === 0) {
            $smsTaslakId = (int) substr($sablonIdRaw, 7);
            $sablon = SMSTaslaklari::where('id', $smsTaslakId)->value('taslak_icerik') ?: '';
        } else {
            $sablon = KampanyaSablonlari::where('id', $sablonIdRaw)->value('icerik') ?: '';
        }

        $promptStr = str_replace('{müşteri}',$musteriAdi,$sablon);
        $promptStr = str_replace('{işletmeden}',$isletme,$promptStr);
        $promptStr = str_replace('{indirim}',$request->kampanyaIndirim,$promptStr);
        $promptStr = str_replace('{gün}',self::kampanyaKalanGun($request->gecerlilikTarihi),$promptStr);
        $hizmetUrunPaket = '';
        if(str_contains($request->hizmetUrunPaket,'urun'))
        {
             $urun = explode('-',$request->hizmetUrunPaket);
             $hizmetUrunPaket = Urunler::where('id',$urun[1])->value('urun_adi');
        }
        elseif(str_contains($request->hizmetUrunPaket,'hizmet'))
        {
            $hizmet = explode('-',$request->hizmetUrunPaket);
            $hizmetUrunPaket = Hizmetler::where('id',$hizmet[1])->value('hizmet_adi');
        }
        else
            $hizmetUrunPaket = Paketler::where('id',$request->hizmetUrunPaket)->value('paket_adi');
        if($hizmetUrunPaket != '')
            $promptStr = str_replace('{ürün_hizmet_paket}',$hizmetUrunPaket,$promptStr);
        $calinacakMetin  ='';
        if(!isset($request->kampanyaYayinlaniyor))
            $calinacakMetin =  self::metniSeseDonustur($promptStr);
        return array(
            'calinacakMetin' => $calinacakMetin,
            'promptStr'=>$promptStr,
        );

    }
    function metniSeseDonustur($metin)
    {
        $metinDuzeltimis = str_replace('SMS','esemes',$metin);
        $url = "https://santral.randevumcepte.com.tr/monitor/kampanyaMetniniSeseDonustur2.php";
        $payload = json_encode(['kampanyaMetin' => $metinDuzeltimis], JSON_UNESCAPED_UNICODE);

        $ch = curl_init();
        curl_setopt_array($ch, [
            CURLOPT_URL => $url,
            CURLOPT_POST => true,
            CURLOPT_RETURNTRANSFER => true,
            CURLOPT_TIMEOUT => 30,
            CURLOPT_HTTPHEADER => ['Content-Type: application/json; charset=utf-8'],
            CURLOPT_POSTFIELDS => $payload
        ]);

        $response  = curl_exec($ch);
        $errno     = curl_errno($ch);
        $errMsg    = curl_error($ch);
        $http_code = curl_getinfo($ch, CURLINFO_HTTP_CODE);
        curl_close($ch);

        if ($errno || $http_code !== 200) {
            \Log::warning('metniSeseDonustur failed', ['errno'=>$errno,'msg'=>$errMsg,'http'=>$http_code,'resp'=>substr((string)$response,0,200)]);
            return '';
        }

        $sesUrl = trim((string)$response);
        // Mixed content: HTTPS site'ta HTTP audio engellenir → protocol-relative yap
        if (strpos($sesUrl, 'http://') === 0) {
            $sesUrl = '//' . substr($sesUrl, 7);
        }
        return $sesUrl;
    }
    public function sablonSil(Request $request)
    {
        SMSTaslaklari::where('id',$request->sablonId)->delete();
        return 'başarılı';
    }

