                ['kod'=>'{müşteri}',           'aciklama'=>'Müşterinin adı (Ferdi Bey / Ayşe Hanım)'],
                ['kod'=>'{işletmeden}',        'aciklama'=>'İşletmenizin adı'],
                ['kod'=>'{indirim}',           'aciklama'=>'İndirim oranı / tutarı'],
                ['kod'=>'{gün}',               'aciklama'=>'Kampanyanın kalan gün sayısı'],
