    /** Senaryo listesi: sistem (hazır) + bu salonun kendi senaryoları. */
    public function senaryoListe(Request $request)
    {
        $salonId = self::mevcutsube($request);

        $sorgu = KampanyaSenaryolari::where('aktif', 1)
            ->where(function($q) use ($salonId){
                $q->whereNull('salon_id')->orWhere('salon_id', $salonId);
            });

        if ($request->gorevTuru !== null && $request->gorevTuru !== '') {
            $sorgu->where('gorev_turu', (int) $request->gorevTuru);
        }

        $senaryolar = $sorgu->orderBy('salon_id')->orderBy('ad')->get()->map(function($s) use ($salonId){
            return [
                'id'           => $s->id,
                'ad'           => $s->ad,
                'senaryo_tipi' => $s->senaryo_tipi,
                'gorev_turu'   => $s->gorev_turu,
                'adimlar'      => $s->adimlar ?: [],
                'aksiyonlar'   => $s->aksiyonlar ?: [],
                'sistem_mi'    => $s->salon_id === null,
                'duzenlenebilir' => $s->salon_id == $salonId,
            ];
        });

        return response()->json(['success'=>true, 'senaryolar'=>$senaryolar]);
    }

    /** Senaryo kaydet (yeni / güncelle). */
    public function senaryoKaydet(Request $request)
    {
        if($r = self::yetkiYoksa403($request, 'pazarlama.kampanya_yonet')) return $r;

        $salonId = self::mevcutsube($request);
        $ad      = trim((string) $request->ad);
        if ($ad === '') {
            return response()->json(['success'=>false, 'message'=>'Senaryo adı zorunludur.']);
        }

        $adimlar    = json_decode((string) $request->adimlar, true);
        $aksiyonlar = json_decode((string) $request->aksiyonlar, true);
        if (!is_array($adimlar))    $adimlar = [];
        if (!is_array($aksiyonlar)) $aksiyonlar = [];

        $senaryo = null;
        if ($request->senaryo_id) {
            // Yalnızca kendi senaryosunu düzenleyebilir (sistem senaryosu salt-okunur).
            $senaryo = KampanyaSenaryolari::where('id', $request->senaryo_id)
                ->where('salon_id', $salonId)->first();
            if (!$senaryo) {
                return response()->json(['success'=>false, 'message'=>'Bu senaryoyu düzenleme yetkiniz yok.']);
            }
        } else {
            $senaryo = new KampanyaSenaryolari();
            $senaryo->salon_id = $salonId;
        }

        $senaryo->ad           = $ad;
        $senaryo->senaryo_tipi = $request->senaryo_tipi ?: 'ozel';
        $senaryo->gorev_turu   = (int) ($request->gorev_turu ?: 1);
        $senaryo->adimlar      = $adimlar;
        $senaryo->aksiyonlar   = $aksiyonlar;
        $senaryo->aktif        = true;
        $senaryo->save();

        SalonAudit::log($salonId, $request->senaryo_id ? 'senaryo_guncelle' : 'senaryo_olustur', 'kampanya_senaryo', $senaryo->id,
            $senaryo->ad, $request->senaryo_id ? 'Kampanya senaryosu güncellendi' : 'Yeni kampanya senaryosu oluşturuldu',
            ['senaryo_tipi'=>$senaryo->senaryo_tipi, 'gorev_turu'=>$senaryo->gorev_turu]);

        return response()->json(['success'=>true, 'mesaj'=>'Senaryo kaydedildi', 'id'=>$senaryo->id]);
    }

    /** Senaryo sil (yalnızca salonun kendi senaryosu). */
    public function senaryoSil(Request $request)
    {
        if($r = self::yetkiYoksa403($request, 'pazarlama.kampanya_yonet')) return $r;

        $salonId = self::mevcutsube($request);
        $senaryo = KampanyaSenaryolari::where('id', $request->senaryo_id)->where('salon_id', $salonId)->first();
        if (!$senaryo) {
            return response()->json(['success'=>false, 'message'=>'Senaryo bulunamadı veya silme yetkiniz yok.']);
        }
        $ad = $senaryo->ad;
        $senaryo->aktif = false;
        $senaryo->save();

        SalonAudit::log($salonId, 'senaryo_sil', 'kampanya_senaryo', $request->senaryo_id, $ad, 'Kampanya senaryosu pasif yapıldı');
        return response()->json(['success'=>true, 'mesaj'=>'Senaryo silindi']);
    }

    /**
     * Sihirbaz önizlemesi: adım metinlerindeki placeholder'ları örnek verilerle
     * çözer ve konuşma balonlarını (bot/müşteri) sırayla döner.
     */
    public function senaryoOnizle(Request $request)
    {
        $salonId = self::mevcutsube($request);
        $isletmeAdi = Salonlar::where('id',$salonId)->value('santral_telaffuz_hatirlatma_aramasi');
        if (!$isletmeAdi) $isletmeAdi = Salonlar::where('id',$salonId)->value('salon_adi');

        $adimlar    = json_decode((string) $request->adimlar, true);
        $aksiyonlar = json_decode((string) $request->aksiyonlar, true);
        if (!is_array($adimlar))    $adimlar = [];
        if (!is_array($aksiyonlar)) $aksiyonlar = [];

        $coz = function($metin) use ($isletmeAdi, $request) {
            $metin = str_replace('{müşteri}', 'Ferdi Bey', (string) $metin);
            $metin = str_replace('{işletmeden}', $isletmeAdi, $metin);
            $metin = str_replace('{indirim}', ($request->indirim ?: '20'), $metin);
            $metin = str_replace('{gün}', ($request->gun ?: '7'), $metin);
            $metin = str_replace('{ürün_hizmet_paket}', ($request->hizmet ?: 'Cilt Bakımı'), $metin);
            return trim($metin);
        };

        $gorevTuru = (int) ($request->gorev_turu ?: 1);
        $diyalog   = [];

        // SMS / Bildirim / Bilgilendirme: tek metin
        if ($gorevTuru !== 1) {
            $diyalog[] = ['kim'=>'bot', 'metin'=>$coz($adimlar['acilis'] ?? '')];
            return response()->json(['success'=>true, 'diyalog'=>$diyalog, 'tek_metin'=>$coz($adimlar['acilis'] ?? '')]);
        }

        // Santral Arama: adım adım konuşma
        $ekle = function($kim, $metin) use (&$diyalog) {
            $metin = trim((string) $metin);
            if ($metin !== '') $diyalog[] = ['kim'=>$kim, 'metin'=>$metin];
        };

        $ekle('bot', $coz($adimlar['acilis'] ?? ''));

        $kodAksiyonu = !empty($aksiyonlar['indirim_kodu_sms']) || !empty($aksiyonlar['yol_tarifi_sms']);
        if ($kodAksiyonu && !empty($adimlar['soru_kod'])) {
            $ekle('bot', $coz($adimlar['soru_kod']));
            $ekle('musteri', 'Evet, olur.');
            $ekle('bot', $coz($adimlar['onay_kod'] ?? ''));
        }

        if (!empty($aksiyonlar['randevu_olustur']) && !empty($adimlar['soru_randevu'])) {
            $ekle('bot', $coz($adimlar['soru_randevu']));
            $ekle('musteri', 'Evet.');
            $ekle('bot', $coz($adimlar['soru_gun_saat'] ?? 'Hangi gün ve saat olsun?'));
            $ekle('musteri', 'Çarşamba öğleden sonra olsun.');
            $ekle('bot', 'Memnuniyetle, hemen kontrol ediyorum. Çarşamba saat 13:00 uygun mu efendim?');
            $ekle('musteri', 'Evet.');
        }

        $ekle('bot', $coz($adimlar['kapanis'] ?? ''));

        return response()->json([
            'success' => true,
            'diyalog' => $diyalog,
            // Santral Arama kampanyasında "Kampanya Metni" alanına yazılacak açılış metni
            'tek_metin' => trim($coz($adimlar['acilis'] ?? '').' '.$coz($adimlar['soru_kod'] ?? '')),
        ]);
    }

    /**
     * Reklam önizleme için TTS proxy.
     * Browser 3rd party TTS API'sine direkt istek atınca CORS/SSL/availability
     * sorunları yaşıyor. Bu endpoint sunucudan istek yapıp audio'yu kullanıcıya
     * stream eder. Birden fazla sağlayıcı dener, ilki başarılı olanı döner.
     */
    public function ttsProxy(Request $request)
    {
        $metin = trim((string) $request->q);
        if ($metin === '') return response('', 400);
        if (mb_strlen($metin) > 1500) $metin = mb_substr($metin, 0, 1500);

        $voiceKey = strtolower(preg_replace('/[^A-Za-z_]/', '', (string) $request->voice));
        if ($voiceKey === '') $voiceKey = 'filiz_normal';

        // Voice ID -> sağlayıcı + parametre eşleştirmesi
        $providers = [];

        if ($voiceKey === 'google') {
            $kisa = mb_substr($metin, 0, 200);
            $providers[] = ['name'=>'googletts','url'=>'https://translate.google.com/translate_tts?ie=UTF-8&client=tw-ob&tl=tr&q='.urlencode($kisa)];
        } else {
            // Polly Filiz — SSML ile rate/pitch ayarı (baygın okuma sorununu çözmek için)
            $rate  = '105%'; $pitch = '+0%';
            if ($voiceKey === 'filiz_fast')   { $rate = '120%'; $pitch = '+5%'; }
            elseif ($voiceKey === 'filiz_slow'){ $rate = '95%';  $pitch = '+0%'; }
            elseif ($voiceKey === 'filiz_high'){ $rate = '110%'; $pitch = '+15%'; }
            elseif ($voiceKey === 'filiz_low') { $rate = '100%'; $pitch = '-15%'; }
            $safeMetin = htmlspecialchars($metin, ENT_XML1 | ENT_QUOTES, 'UTF-8');
            $ssml      = '<speak><prosody rate="'.$rate.'" pitch="'.$pitch.'">'.$safeMetin.'</prosody></speak>';
            $providers[] = ['name'=>'streamelements_ssml','url'=>'https://api.streamelements.com/kappa/v2/speech?voice=Filiz&text='.urlencode($ssml)];
            $providers[] = ['name'=>'streamelements_plain','url'=>'https://api.streamelements.com/kappa/v2/speech?voice=Filiz&text='.urlencode($metin)];
        }
        // Son fallback: her durumda Google
        $providers[] = ['name'=>'googletts_fallback','url'=>'https://translate.google.com/translate_tts?ie=UTF-8&client=tw-ob&tl=tr&q='.urlencode(mb_substr($metin,0,200))];

        foreach ($providers as $p) {
            $ch = curl_init();
            curl_setopt_array($ch, [
                CURLOPT_URL            => $p['url'],
                CURLOPT_RETURNTRANSFER => true,
                CURLOPT_TIMEOUT        => 15,
                CURLOPT_CONNECTTIMEOUT => 6,
                CURLOPT_FOLLOWLOCATION => true,
                CURLOPT_USERAGENT      => 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120 Safari/537.36',
                CURLOPT_SSL_VERIFYPEER => false,
                CURLOPT_HTTPHEADER     => ['Accept: audio/mpeg, audio/*, */*'],
            ]);
            $body = curl_exec($ch);
            $code = curl_getinfo($ch, CURLINFO_HTTP_CODE);
            $type = curl_getinfo($ch, CURLINFO_CONTENT_TYPE);
            $err  = curl_error($ch);
            curl_close($ch);

            if ($code === 200 && $body && strlen($body) > 1000 && stripos((string)$type, 'audio') !== false) {
                return response($body, 200)
                    ->header('Content-Type', $type ?: 'audio/mpeg')
                    ->header('Cache-Control', 'private, max-age=600')
                    ->header('Content-Length', (string) strlen($body))
                    ->header('X-TTS-Provider', $p['name']);
            }
            \Log::info('ttsProxy provider fail', ['voice'=>$voiceKey,'provider'=>$p['name'],'code'=>$code,'type'=>$type,'err'=>$err,'len'=>strlen((string)$body)]);
        }

        return response('TTS sağlayıcıları yanıt vermedi', 502);
    }

    public function kampanyaSablonFiltre(Request $request)
    {
        // Eski tablolarda gorev_turu / tur kolonu olmayabilir — varsa filtrele.
        $sablonTablo  = (new KampanyaSablonlari)->getTable();
        $hasGorevTuru = Schema::hasColumn($sablonTablo, 'gorev_turu');
        $hasTur       = Schema::hasColumn($sablonTablo, 'tur');

        $sablonlar = KampanyaSablonlari::where(function($q) use ($request, $hasGorevTuru){
            if($hasGorevTuru && $request->gorevTuru !='') {
                $q->where('gorev_turu',$request->gorevTuru);
            }
        })->where(function($q) use ($request, $hasTur){
            if($hasTur && $request->kampanyaTuru != '')
            {
                $q->where('tur',$request->kampanyaTuru);
            }
        })->get();
        //$hariciSablonlar = '';

        //if(($request->gorevTuru==2 ||$request->gorevTuru==3 ||$request->gorevTuru==4 || $request->gorevTuru=='')&& ($request->kampanyaTuru=='' || $request->kampanyaTuru == 3))
            $hariciSablonlar = SMSTaslaklari::where('salon_id',$request->salonId)->orderBy('id','desc')->get();

        $html = '';

        // Senaryo Sihirbazı ile oluşturulan senaryolar (sistem + bu salon), kanala göre
        $senaryolar = KampanyaSenaryolari::where('aktif',1)
            ->where(function($q) use ($request){
                $q->whereNull('salon_id')->orWhere('salon_id',$request->salonId);
            })
            ->where(function($q) use ($request){
                if($request->gorevTuru != '') $q->where('gorev_turu',(int)$request->gorevTuru);
            })
            ->orderBy('ad')->get();

        foreach($senaryolar as $senaryo)
        {
            $silBtn = '';
            if($senaryo->salon_id == $request->salonId){
                $silBtn = '<a name="senaryoSil" title="Senaryo Sil" data-value="'.$senaryo->id.'" style="float:right;z-index:9999999;font-size: 22px;color: red;margin-left: 5px;font-weight: 100;margin-top: -2px;"><i class="fa fa-remove"></i></a>'
                        . '<a name="senaryoDuzenle" title="Senaryo Düzenle" data-value="'.$senaryo->id.'" style="float:right;z-index:9999999;font-size: 20px; color: #0055B4;"><i class="fa fa-edit"></i></a>';
            }
            $html .= '<div class="kampanyaSablonSecim" title="Metni Seç" data-value="senaryo-'.$senaryo->id.'" style="position:relative; cursor:pointer; margin-bottom:8px;" name="kampanyaSablonSecim">
                        <p style="padding:5px;background-color:#ede9fe; border-radius:20px;border-bottom-left-radius:0;color:#4c1d95;font-size:15px;overflow:hidden;">
                           <i class="fa fa-magic" style="margin-right:4px;"></i>'.e($senaryo->ad).' '.$silBtn.'
                        </p>
                      </div>';
        }

        if($hariciSablonlar !='')
        {
            foreach($hariciSablonlar as $sablon)
            {
                $html .= '<div class="kampanyaSablonSecim" title="Metni Seç" data-value="sablon-'.$sablon->id.'" style="position:relative; cursor: pointer" name="kampanyaSablonSecim">
                           <p style="padding:5px;background-color: #f2f2f2; border-radius: 20px;border-bottom-left-radius: 0;color:black;font-size:15px; overflow: hidden;">
                              '.$sablon->baslik.' <a name="sablonSil" title="Şablon Sil" data-value="'.$sablon->id.'" style="float:right;z-index:9999999;font-size: 22px;color: red;margin-left: 5px;font-weight: 100;margin-top: -2px;"><i class="fa fa-remove"></i></a>  &nbsp;<a name="smsTaslakDuzenle" data-text="'.$sablon->baslik.'|'.$sablon->taslak_icerik.'" title="Şablon Düzenle" data-value="'.$sablon->id.'" style="float:right;z-index:9999999;font-size: 20px; color: #0055B4;"><i class="fa fa-edit"></i></a>
                           </p>
                        </div> ';
            }
        }

        foreach($sablonlar as $sablon)
        {
            $html .= '<div class="kampanyaSablonSecim" title="Metni Seç" data-value="'.$sablon->id.'" style="position:relative; cursor: pointer;" name="kampanyaSablonSecim">
                           <p style="padding:5px;background-color: #f2f2f2; border-radius: 20px;border-bottom-left-radius: 0;color:black;font-size:15px; overflow: hidden;">
                              '.$sablon->baslik.'
                           </p>
                        </div>';
        }

        $secimMenusu = '';
        if($request->kategori == '1')
            $secimMenusu = self::hizmet_secimi_2($request);
        if($request->kategori == '2')
            $secimMenusu = self::urun_secimi($request);
        if($request->kategori == '3')
            $secimMenusu = self::paket_secimi($request);
        return array(
            'secimMenusu'=>$secimMenusu,
            'sablonlar'=>$html,
        );
    }
    function kampanyaKalanGun($validUntil) {
        $today = Carbon::today();
        $endDate = Carbon::parse($validUntil);

        $diff = $today->diffInDays($endDate, false); // false => geçmişse negatif
         
        return $diff;
        
    }
    public function satisDetaylariveDuzenleme(Request $request)
    {

        $adisyonDetay =  self::musteri_tahsilatlari($request,$request->musteriId,$request->adisyonId,true);
        $adisyon = Adisyonlar::where('id',$request->adisyonId)->first();
        if($adisyon){
            $tarih = $adisyon->tarih ?: $adisyon->created_at;
            $adisyonDetay['satisTarihi'] = $tarih ? date('Y-m-d',strtotime($tarih)) : '';
        } else {
            $adisyonDetay['satisTarihi'] = '';
        }
        $adisyonDetay['kullanilanKupon'] = null;
        if(\Schema::hasColumn('carkifelek_odulleri','adisyon_id') && $request->adisyonId){
            $k = CarkifelekOdulleri::where('adisyon_id',$request->adisyonId)->where('kullanildi',1)->first();
            if($k){
                $tipAd = $k->tip == 'hizmet_indirimi' ? 'Hizmet' : ($k->tip == 'urun_indirimi' ? 'Ürün' : 'Paket');
                $adisyonDetay['kullanilanKupon'] = [
                    'kod'   => $k->kod,
                    'deger' => (int)$k->deger,
                    'tip'   => $k->tip,
                    'tipAd' => $tipAd,
                    'tarih' => $k->kullanim_tarihi ? date('d.m.Y', strtotime($k->kullanim_tarihi)) : '',
                ];
            }
        }
        return $adisyonDetay;

    }
    public function satisTarihiGuncelle(Request $request)
    {
        $adisyon = Adisyonlar::where('id',$request->adisyon_id)
            ->where('salon_id',$request->sube)
            ->first();
        if(!$adisyon)
            return response()->json(['durum'=>'hata','mesaj'=>'Adisyon bulunamadı.'], 404);
        if(!$request->satis_tarihi)
            return response()->json(['durum'=>'hata','mesaj'=>'Tarih boş.'], 422);
        $adisyon->tarih = date('Y-m-d',strtotime($request->satis_tarihi));
        $adisyon->save();
        return response()->json(['durum'=>'ok','tarih'=>$adisyon->tarih]);
    }
    public function kullaniciKuponlari(Request $request)
    {
        $bugun = date('Y-m-d');
        $sube  = (int) $request->sube;
        // Kaba on-filtre: owner kardes sube grubu (sorguyu daraltir). Kesin kontrol
        // asagida gecerliSubeler() ile: kupon yalnizca uygulandigi grup subelerinde listelenir.
        $kardesler = \App\Personeller::kardesSalonIdler($sube);
        $adaylar = CarkifelekOdulleri::where('user_id', $request->user_id)
            ->whereIn('salon_id', $kardesler)
            ->where('kullanildi', 0)
            ->whereIn('tip', ['hizmet_indirimi','urun_indirimi','paket_indirimi'])
            ->where(function($q) use($bugun){
                $q->whereNull('gecerlilik_tarihi')->orWhere('gecerlilik_tarihi', '>=', $bugun);
            })
            ->orderBy('id','desc')
            ->get();
        $kuponlar = $adaylar
            ->filter(function($k) use($sube){ return in_array($sube, $k->gecerliSubeler(), true); })
            ->map(function($k){
                return [
                    'id' => $k->id, 'kod' => $k->kod, 'tip' => $k->tip,
                    'deger' => $k->deger, 'baslik' => $k->baslik,
                    'gecerlilik_tarihi' => $k->gecerlilik_tarihi,
                ];
            })->values();
        return response()->json(['kuponlar' => $kuponlar]);
    }
    public function kuponUygula(Request $request)
    {
        // Çoklu şube: kupon yalnızca uygulandığı şube grubunda (gecerli_salonlar) kullanılır.
        $sube = (int) $request->sube;
        $kupon = CarkifelekOdulleri::where('kod', strtoupper(trim($request->kod)))
            ->where('user_id', $request->musteri_id)
            ->where('kullanildi', 0)
            ->whereIn('tip', ['hizmet_indirimi','urun_indirimi','paket_indirimi'])
            ->first();
        if(!$kupon || !in_array($sube, $kupon->gecerliSubeler(), true))
            return response()->json(['durum'=>'hata','mesaj'=>'Kupon bulunamadı, müşteriye ait değil veya zaten kullanılmış.'], 404);
        if($kupon->gecerlilik_tarihi && $kupon->gecerlilik_tarihi < date('Y-m-d'))
            return response()->json(['durum'=>'hata','mesaj'=>'Kuponun süresi dolmuş.'], 422);

        $adisyon = Adisyonlar::where('id', $request->adisyon_id)->where('salon_id', $request->sube)->first();
        if(!$adisyon)
            return response()->json(['durum'=>'hata','mesaj'=>'Önce sepete bir hizmet/ürün/paket ekleyin.'], 422);

        // Indirim tipi: 'tutar' -> sabit ₺ (kalemlere dagitilir), aksi halde 'yuzde' (% oran).
        $tutarMi = (isset($kupon->indirim_tipi) && $kupon->indirim_tipi === 'tutar');
        $oran    = ((float) $kupon->deger) / 100.0;
        $kalanTutar = (float) $kupon->deger; // tutar modunda kalemlere dagitilacak bakiye
        // Kupon belirli bir hizmete kisitli mi? (sadece hizmet_indirimi'nde anlamli)
        $hizmetFiltre = ($kupon->tip == 'hizmet_indirimi' && !empty($kupon->hizmet_id)) ? (int) $kupon->hizmet_id : null;
        $uygula = 0;
        \DB::transaction(function() use($kupon, $adisyon, $oran, $tutarMi, &$kalanTutar, $hizmetFiltre, &$uygula){
            // Bir kaleme uygulanacak indirimi hesaplar (₺ modunda bakiyeden duser).
            $indirimHesapla = function($fiyat) use($tutarMi, $oran, &$kalanTutar){
                if($tutarMi){
                    if($kalanTutar <= 0) return null; // bakiye bitti
                    $ind = min($kalanTutar, (float)$fiyat);
                    $kalanTutar -= $ind;
                    return round($ind, 2);
                }
                return round(((float)$fiyat) * $oran, 2);
            };
            if($kupon->tip == 'hizmet_indirimi'){
                foreach($adisyon->hizmetler as $h){
                    if($h->senet_id !== null || $h->taksitli_tahsilat_id !== null) continue;
                    if($hizmetFiltre !== null && (int)$h->hizmet_id !== $hizmetFiltre) continue;
                    $ind = $indirimHesapla($h->fiyat);
                    if($ind === null) break;
                    $h->indirim_tutari = $ind;
                    $h->save();
                    $uygula++;
                }
            } elseif($kupon->tip == 'urun_indirimi'){
                foreach($adisyon->urunler as $u){
                    if($u->senet_id !== null || $u->taksitli_tahsilat_id !== null) continue;
                    $ind = $indirimHesapla($u->fiyat);
                    if($ind === null) break;
                    $u->indirim_tutari = $ind;
                    $u->save();
                    $uygula++;
                }
            } elseif($kupon->tip == 'paket_indirimi'){
                foreach($adisyon->paketler as $p){
                    if($p->senet_id !== null || $p->taksitli_tahsilat_id !== null) continue;
                    $ind = $indirimHesapla($p->fiyat);
                    if($ind === null) break;
                    $p->indirim_tutari = $ind;
                    $p->save();
                    $uygula++;
                }
            }
            if($uygula > 0){
                $kupon->kullanildi = 1;
                $kupon->kullanim_tarihi = date('Y-m-d H:i:s');
                if(\Schema::hasColumn('carkifelek_odulleri','adisyon_id'))
                    $kupon->adisyon_id = $adisyon->id;
                $kupon->save();
            }
        });
        if($uygula == 0){
            $tipAd = $kupon->tip == 'hizmet_indirimi' ? 'hizmet' : ($kupon->tip == 'urun_indirimi' ? 'ürün' : 'paket');
            $ek = $hizmetFiltre !== null ? ' (bu kupon yalnizca belirli bir hizmette gecerli)' : '';
            return response()->json(['durum'=>'hata','mesaj'=>"Sepette uygun {$tipAd} bulunmadığı için kupon uygulanamadı.".$ek], 422);
        }
        $indirimMetni = $tutarMi
            ? (rtrim(rtrim(number_format((float)$kupon->deger, 2, ',', '.'), '0'), ',').' ₺')
            : '%'.((int)$kupon->deger);
        $tahsilatData = self::musteri_tahsilatlari($request, $request->musteri_id, $request->adisyon_id, $request->satisDuzenle);
        return response()->json([
            'durum'        => 'ok',
            'mesaj'        => $indirimMetni.' indirim ' . $uygula . ' kaleme uygulandı.',
            'baslik'       => $kupon->baslik,
            'tahsilatData' => $tahsilatData,
        ]);
    }
   public function paketVarmiKontrolu(Request $request)
{
    $user = User::where('id', $request->userId)->first();
    
    if (!$user) {
        return response()->json([
            'paketRandevuOnayiGerekli' => false,
            'onayMetni' => 'Kullanıcı bulunamadı.',
            'paketHizmetleri' => [],
            'paketDetaylari' => [],
            'toplamSeans' => 0,
            'paketVarMi' => false
        ]);
    }

    // HİZMETLER için sorgu.
    // NOT: 'bekleyen_seans > 0' filtresi KALDIRILDI — bu kolon guvenilir degil (asagidaki
    // kalan-seans formulu de bu yuzden var). Bayat bekleyen_seans=0 yuzunden gercekte seansi
    // olan paket/hizmetler yanlislikla eleniyor, modal acilmiyordu. Tukenmisleri asagidaki
    // formul ($kalanSeans <= 0 continue) zaten eliyor.
    // NOT: 'otomatik_randevu_olusturuldu != 1' TEK BASINA NULL satirlari da eler (SQL'de
    // NULL != 1 -> unknown). Kolon cogu kayitta NULL oldugundan, paketi olan musteride
    // adisyon yanlislikla elenip "paket yok" gibi gozukuyordu. NULL'i da dahil ediyoruz.
    $randevuOlusturulmamisHizmetAdisyonuVarmi = Adisyonlar::whereHas('hizmetler', function($q) {
        $q->where(function($qq){
            $qq->whereNull('otomatik_randevu_olusturuldu')->orWhere('otomatik_randevu_olusturuldu', '!=', 1);
        });
    })->where('user_id', $user->id)
      ->where('salon_id', $request->sube)
      ->with(['hizmetler.hizmet']) // İlişkileri yükle
      ->get();

    // PAKETLER için sorgu (ayni NULL duzeltmesi + bekleyen_seans filtresi kaldirildi).
    $randevuOlusturulmamisPaketAdisyonuVarmi = Adisyonlar::whereHas('paketler', function($q) {
        $q->where(function($qq){
            $qq->whereNull('otomatik_randevu_olusturuldu')->orWhere('otomatik_randevu_olusturuldu', '!=', 1);
        });
    })->where('user_id', $user->id)
      ->where('salon_id', $request->sube)
      ->with(['paketler.paket.hizmetler.hizmet']) // İlişkileri yükle
      ->get();
    
    // Paket var mı kontrolü
    $paketVarMi = ($randevuOlusturulmamisHizmetAdisyonuVarmi->count() > 0 ||
                   $randevuOlusturulmamisPaketAdisyonuVarmi->count() > 0);

    // Paket yoksa direkt false döndür
    if (!$paketVarMi) {
        return response()->json([
            'paketRandevuOnayiGerekli' => false,
            'onayMetni' => '',
            'paketHizmetleri' => [],
            'paketDetaylari' => [],
            'toplamSeans' => 0,
            'paketVarMi' => false
        ]);
    }
    
    $paketHizmetleri = []; // Bu sadece hizmetleri tutacak
    $paketDetaylari = []; // Bu paket/hizmet detaylarını tutacak
    $onayVar = filter_var($request->paketRandevuOnayiVar, FILTER_VALIDATE_BOOLEAN);
    $onayGerekli = $onayVar ? false : true;
    $onayMetni = '';
    $paketIndex = 0;
    
    if($onayGerekli) {
        $onayMetni = '<div class="customer-info mb-3"><i class="fa fa-user mr-2"></i><strong>' . 
                     $user->name . '</strong> isimli müşteriye ait paket/hizmetler:</div>';
    }
    
    // TEK HİZMETLER - kalan seans seans takibindeki formulle hesaplanir (bekleyen_seans kolonu guvenilir degil)
    foreach($randevuOlusturulmamisHizmetAdisyonuVarmi as $hizmetSeanslari) {
        foreach($hizmetSeanslari->hizmetler as $hizmetA) {
            if (!$hizmetA->hizmet) continue;
            // KALAN = toplam - adisyon_paket_seanslar KAYIT SAYISI (her kayit 1 seans; geldi/beklemede farketmez).
            $toplamSeansHizmet = (int)($hizmetA->seans_sayisi ?? $hizmetA->bekleyen_seans ?? 0);
            $kullanilanHizmet = (int) DB::table('adisyon_paket_seanslar')
                ->where('adisyon_hizmet_id', $hizmetA->id)
                ->count();
            $kalanSeansHizmet = max(0, $toplamSeansHizmet - $kullanilanHizmet);
            if ($kalanSeansHizmet <= 0) continue; // Tukenmis hizmetleri popup'a hic dahil etme

            $hizmetAdi = $hizmetA->hizmet->hizmet_adi;
            $seansSayisi = $kalanSeansHizmet;

            $onayMetni .= '- ' . $seansSayisi . ' seans ' . $hizmetAdi . '<br>';

            // PAKET HİZMETLERİ DİZİSİNE EKLE (hizmet bazlı)
            $paketHizmetleri[] = [
                'id' => $hizmetA->hizmet_id,
                'text' => $hizmetAdi,
                'seans' => $seansSayisi,
                'tur' => 'hizmet',
                'sure' => $hizmetA->sure ?? 0,
                'original_seans' => $seansSayisi,
                'paket_adi' => null,
                'adisyon_hizmet_id' => $hizmetA->id
            ];

            // PAKET DETAYLARI DİZİSİNE EKLE (paket/hizmet bazlı)
            $paketDetaylari[] = [
                'index' => $paketIndex++,
                'adi' => $hizmetAdi,
                'seans' => $seansSayisi,
                'tur' => 'Tek Hizmet',
                'sure' => $hizmetA->sure ?? 0,
                'hizmet_id' => $hizmetA->hizmet_id,
                'type' => 'hizmet',
                'adisyon_hizmet_id' => $hizmetA->id,
                'paket_id' => null,
                'toplamSeans' => $seansSayisi,
                'icerik' => [[
                    'id' => $hizmetA->hizmet_id,
                    'text' => $hizmetAdi,
                    'seans' => $seansSayisi,
                    'sure' => $hizmetA->sure ?? 0
                ]]
            ];
        }
    }

    // PAKETLER - BOLGE bazli kalan seans hesaplanir.
    // ESKI FORMUL (HATALI): kalan = floor((toplam - kullanilan) / hizmet_sayisi)
    // Sorun: bolgeler esit kullanilmiyor. Or: 5 bolge x 8 = 40 kapasite, 37 kullanilmis,
    // 3 farkli bolgede 1'er seans kalmis. Eski formul floor(3/5)=0 verip paketi
    // 'tukenmis' sayiyor (Seans Takibi sayfasi ise her bolge icin ayri saydigindan
    // dogru 1'er kalan goruyor). DOGRU MANTIK: her bolge icin ayri sayim, kalan>0
    // olanlar popup'a girer.
    foreach($randevuOlusturulmamisPaketAdisyonuVarmi as $paketSeanslari) {
        foreach($paketSeanslari->paketler as $paketA) {
            if (!$paketA->paket) continue;
            $hizmetSayisi = $paketA->paket->hizmetler ? count($paketA->paket->hizmetler) : 0;
            if ($hizmetSayisi <= 0) continue;

            // Bolge (hizmet) basina satin alinan seans sayisi
            $seansPerHizmet = (int)($paketA->seans_sayisi ?? $paketA->bekleyen_seans ?? 0);
            if ($seansPerHizmet <= 0) continue;

            // Her bolge icin kullanilan APS sayisini tek sorguda al
            $kullanilanByHizmet = DB::table('adisyon_paket_seanslar')
                ->where('adisyon_paket_id', $paketA->id)
                ->select('hizmet_id', DB::raw('COUNT(*) as c'))
                ->groupBy('hizmet_id')
                ->pluck('c', 'hizmet_id')
                ->toArray();

            \Log::info('[paketVarmi/PAKET]', [
                'adisyon_paket_id' => $paketA->id,
                'paket_id' => $paketA->paket_id,
                'paket_adi' => $paketA->paket->paket_adi ?? null,
                'seans_per_hizmet' => $seansPerHizmet,
                'hizmet_sayisi' => $hizmetSayisi,
                'kullanilan_by_hizmet' => $kullanilanByHizmet,
            ]);

            $paketAdi = $paketA->paket->paket_adi;
            $paketHizmetleriArray = [];
            $hizmetIdleri = [];
            $toplamKalan = 0;
            $maxKalan = 0; // Detay 'seans' alani icin temsili deger (en yuksek bolge kalani)

            foreach ($paketA->paket->hizmetler as $hizmetP) {
                if (!$hizmetP->hizmet) {
                    \Log::info('[paketVarmi/SKIP-no-hizmet]', ['paket_hizmet_id' => $hizmetP->id ?? null, 'hizmet_id' => $hizmetP->hizmet_id ?? null]);
                    continue;
                }
                $kullanilan = (int)($kullanilanByHizmet[$hizmetP->hizmet_id] ?? 0);
                $kalan = max(0, $seansPerHizmet - $kullanilan);
                \Log::info('[paketVarmi/BOLGE]', [
                    'adisyon_paket_id' => $paketA->id,
                    'hizmet_id' => $hizmetP->hizmet_id,
                    'hizmet_adi' => $hizmetP->hizmet->hizmet_adi,
                    'kullanilan' => $kullanilan,
                    'seans_per_hizmet' => $seansPerHizmet,
                    'kalan' => $kalan,
                ]);
                if ($kalan <= 0) continue; // Bu bolgede seans yok -> popup'a dahil etme

                $toplamKalan += $kalan;
                if ($kalan > $maxKalan) $maxKalan = $kalan;

                $paketHizmetleri[] = [
                    'id' => $hizmetP->hizmet_id,
                    'text' => $hizmetP->hizmet->hizmet_adi,
                    'seans' => $kalan,
                    'paket_adi' => $paketAdi,
                    'tur' => 'paket',
                    'sure' => $hizmetP->sure ?? 0,
                    'original_seans' => $kalan,
                    'adisyon_paket_id' => $paketA->id
                ];
                $paketHizmetleriArray[] = [
                    'id' => $hizmetP->hizmet_id,
                    'text' => $hizmetP->hizmet->hizmet_adi,
                    'seans' => $kalan,
                    'sure' => $hizmetP->sure ?? 0
                ];
                $hizmetIdleri[] = $hizmetP->hizmet_id;
            }

            // Hicbir bolgede kalan yoksa paketi popup'a dahil etme
            if (empty($paketHizmetleriArray)) continue;

            $onayMetni .= '<div class="package-group mt-2"><strong>📦 ' .
                         $paketAdi . '</strong> (' . $toplamKalan . ' seans)</div>';

            // Musteriye satilan paket fiyati (adisyon_paketler.fiyat).
            // Randevu ekleme modalinda paket kartinin fiyat input'una default olarak
            // basilir (kullanici "0 gozukuyor, satis fiyati gelmeli" diye rapor etti).
            $paketSatisFiyati = (float) ($paketA->fiyat ?? 0);
            $paketDetaylari[] = [
                'index' => $paketIndex++,
                'adi' => $paketAdi,
                'seans' => $maxKalan, // Bolgeler arasi farkli olabilir; en yuksek temsili
                'tur' => 'Paket: ' . $paketAdi,
                'sure' => $paketA->paket->sure ?? 0,
                'hizmet_id' => $hizmetIdleri,
                'paket_id' => $paketA->paket_id,
                'type' => 'paket',
                'adisyon_paket_id' => $paketA->id,
                'toplamSeans' => $toplamKalan,
                'paket_fiyat' => $paketSatisFiyati,
                'icerik' => $paketHizmetleriArray
            ];
        }
    }

    // Tukenmis filtre sonrasi hicbir paket/hizmet kalmadiysa popup'i ac(tirma)ma
    $paketVarMi = !empty($paketDetaylari);

    Log::info(json_encode($paketDetaylari));
    return response()->json([
        'paketRandevuOnayiGerekli' => $paketVarMi ? $onayGerekli : false,
        'onayMetni' => $onayMetni,
        'paketHizmetleri' => $paketHizmetleri,
        'paketDetaylari' => $paketDetaylari,
        'toplamSeans' => count($paketHizmetleri),
        'userName' => $user->name,
        'paketVarMi' => $paketVarMi
    ]);
}
    public function seansEkle(Request $request)
    {

         
        // Seans tarihi disaridan gelebilir (gecmise donuk kayit icin); gelmezse bugun.
        $seansTarih = date('Y-m-d');
        if(!empty($request->seansTarihi))
        {
            $gelen = \DateTime::createFromFormat('Y-m-d', $request->seansTarihi);
            if($gelen && $gelen->format('Y-m-d') === $request->seansTarihi)
                $seansTarih = $request->seansTarihi;
        }

        $seans = new AdisyonPaketSeanslar();
        if($request->paket==1)
        {


                $seans->seans_tarih = $seansTarih;
                $seans->adisyon_paket_id = $request->paketId;
                $seans->hizmet_id = $request->hizmetId;

        }
        if($request->paket==0)
        {


                $seans->seans_tarih = $seansTarih;
                $seans->adisyon_hizmet_id = $request->paketId;
                $seans->hizmet_id = $request->hizmetId;

        }
        $seans->geldi = $request->geldi;
        $seans->save();
        
        return 'Başarılı';//self::seans_getir($request,0,$request->musteriId);
    }
    public function seansGuncelle(Request $request)
    {

        $seans = AdisyonPaketSeanslar::where('id',$request->seansId)->first();
        if($seans->geldi == '')
            $seans->delete();
        else{
             $seans->geldi = $request->geldi;
            $seans->save();
        }
       
        return 'Başarılı';//self::seans_getir($request,0,$request->musteriId);
    }

    // ================= SEANS CİHAZ VERİLERİ (lazer parametreleri) =================
    // Bir seansta uygulanan cihaz parametreleri (Enerji/Jül, Hız, MS, Atış sayısı)
    // bolge bazinda tutulur: bir seansta N bolge -> N satir (hasMany).

    // Seansin musteri/hizmet/salon/varsayilan personel bilgisini cozer.
    private function seansCihazMeta($seans, $request)
    {
        $adisyonId = null;
        $hizmetAdi = optional($seans->hizmet)->hizmet_adi;
        if ($seans->adisyon_paket_id) {
            $ap = DB::table('adisyon_paketler')->where('id', $seans->adisyon_paket_id)->first();
            $adisyonId = $ap->adisyon_id ?? null;
        } elseif ($seans->adisyon_hizmet_id) {
            $ah = DB::table('adisyon_hizmetler')->where('id', $seans->adisyon_hizmet_id)->first();
            $adisyonId = $ah->adisyon_id ?? null;
        }
        $adisyon    = $adisyonId ? DB::table('adisyonlar')->where('id', $adisyonId)->first() : null;
        $salonId    = $adisyon->salon_id ?? self::mevcutsube($request);
        $musteriAdi = $adisyon ? DB::table('users')->where('id', $adisyon->user_id)->value('name') : '';

        // Varsayilan "uygulamayi yapan": once seansin personeli, yoksa randevunun personeli
        $varsayilanPersonel = $seans->personel_id;
        if (!$varsayilanPersonel && $seans->randevu_id) {
            $varsayilanPersonel = DB::table('randevu_hizmetler')
                ->where('randevu_id', $seans->randevu_id)
                ->where('hizmet_id', $seans->hizmet_id)
                ->value('personel_id');
        }
        return [$salonId, $musteriAdi, $hizmetAdi, $varsayilanPersonel];
    }

    // Cihaz takibi SADECE lazer epilasyon icin: paket/hizmet adinda "lazer"
    // (veya "laser") geciyorsa true. Lazer paketleri adinda daima lazer gecer.
    public static function isimdeLazerVar($ad)
    {
        $ad = (string) $ad;
        return $ad !== '' && (stripos($ad, 'lazer') !== false || stripos($ad, 'laser') !== false);
    }

    private function seansLazerMi($seans)
    {
        if (self::isimdeLazerVar(optional($seans->hizmet)->hizmet_adi)) {
            return true;
        }
        if ($seans->adisyon_paket_id) {
            $paketAdi = DB::table('adisyon_paketler')
                ->join('paketler', 'adisyon_paketler.paket_id', '=', 'paketler.id')
                ->where('adisyon_paketler.id', $seans->adisyon_paket_id)
                ->value('paketler.paket_adi');
            if (self::isimdeLazerVar($paketAdi)) {
                return true;
            }
        }
        return false;
    }

    public function seansCihazVeriGetir(Request $request)
    {
        $seans = AdisyonPaketSeanslar::where('id', $request->seansId)->first();
        if (!$seans) {
            return response()->json(['hatali' => 1, 'mesaj' => 'Seans bulunamadı']);
        }
        if (!self::seansLazerMi($seans)) {
            return response()->json(['hatali' => 1, 'lazer' => false, 'mesaj' => 'Bu hizmet lazer epilasyon değil; cihaz takibi yapılmaz.']);
        }
        list($salonId, $musteriAdi, $hizmetAdi, $varsayilanPersonel) = self::seansCihazMeta($seans, $request);

        $personeller = Personeller::where('salon_id', $salonId)
            ->whereRaw('COALESCE(arsivli,0) = 0')
            ->orderBy('personel_adi')
            ->get(['id', 'personel_adi']);

        $bolgeler = SeansCihazVerileri::where('seans_id', $seans->id)
            ->orderBy('id')
            ->get(['id', 'uygulama_bolgesi', 'enerji', 'hiz', 'ms', 'atis_sayisi', 'personel_id', 'notlar']);

        return response()->json([
            'hatali' => 0,
            'seans'  => [
                'id'          => $seans->id,
                'seans_no'    => $seans->seans_no,
                'seans_tarih' => $seans->seans_tarih,
                'hizmet_adi'  => $hizmetAdi,
                'musteri_adi' => $musteriAdi,
                'varsayilan_personel_id' => $varsayilanPersonel,
            ],
            'personeller' => $personeller,
            'bolgeler'    => $bolgeler,
        ]);
    }

    public function seansCihazVeriKaydet(Request $request)
    {
        $seans = AdisyonPaketSeanslar::where('id', $request->seansId)->first();
        if (!$seans) {
            return response()->json(['hatali' => 1, 'mesaj' => 'Seans bulunamadı']);
        }
        if (!self::seansLazerMi($seans)) {
            return response()->json(['hatali' => 1, 'mesaj' => 'Bu hizmet lazer epilasyon değil; cihaz takibi yapılmaz.']);
        }
        list($salonId) = self::seansCihazMeta($seans, $request);

        $bolgeler = $request->bolgeler;
        if (is_string($bolgeler)) {
            $bolgeler = json_decode($bolgeler, true);
        }
        if (!is_array($bolgeler)) {
            $bolgeler = [];
        }

        // Bolge = kartin (hizmetin) adi; her seans tek bolgeye aittir, otomatik gelir
        $bolgeAdi = optional($seans->hizmet)->hizmet_adi;

        // Tam yenile: mevcut satirlari sil, gelenleri yeniden yaz
        SeansCihazVerileri::where('seans_id', $seans->id)->delete();

        foreach ($bolgeler as $b) {
            $bolge  = trim((string) ($b['uygulama_bolgesi'] ?? ''));
            if ($bolge === '') { $bolge = (string) $bolgeAdi; } // otomatik bolge adi
            $enerji = trim((string) ($b['enerji'] ?? ''));
            $hiz    = trim((string) ($b['hiz'] ?? ''));
            $ms     = trim((string) ($b['ms'] ?? ''));
            $atis   = trim((string) ($b['atis_sayisi'] ?? ''));
            $not    = trim((string) ($b['notlar'] ?? ''));
            // Parametrelerin tamami bossa satir yazma (bolge adi otomatik oldugu icin ona bakma)
            if ($enerji === '' && $hiz === '' && $ms === '' && $atis === '' && $not === '') {
                continue;
            }
            SeansCihazVerileri::create([
                'seans_id'         => $seans->id,
                'salon_id'         => $salonId,
                'personel_id'      => !empty($b['personel_id']) ? $b['personel_id'] : null,
                'uygulama_bolgesi' => $bolge !== '' ? $bolge : null,
                'enerji'           => $enerji !== '' ? $enerji : null,
                'hiz'              => $hiz !== '' ? $hiz : null,
                'ms'               => $ms !== '' ? $ms : null,
                'atis_sayisi'      => $atis !== '' ? $atis : null,
                'tarih'            => $seans->seans_tarih,
                'notlar'           => $not !== '' ? $not : null,
            ]);
        }

        return response()->json(['hatali' => 0, 'mesaj' => 'Cihaz bilgileri kaydedildi']);
    }

    // A4 "Seans Dökümü" PDF — paket/hizmet bazinda tum seanslar + cihaz verileri
    public function seansDokumuPdf(Request $request)
    {
        $paketMi = isset($request->adisyonpaketid) && $request->adisyonpaketid != '';
        if ($paketMi) {
            $seanslar = AdisyonPaketSeanslar::where('adisyon_paket_id', $request->adisyonpaketid)
                ->with('hizmet')
                ->orderBy('seans_tarih')->orderBy('seans_no')->get();
            $ap = DB::table('adisyon_paketler')->where('id', $request->adisyonpaketid)->first();
            $baslik      = $ap ? DB::table('paketler')->where('id', $ap->paket_id)->value('paket_adi') : '';
            $seansAdedi  = $ap->seans_sayisi ?? null;
            $baslangic   = $ap->baslangic_tarihi ?? null;
            $adisyonId   = $ap->adisyon_id ?? null;
        } else {
            $seanslar = AdisyonPaketSeanslar::where('adisyon_hizmet_id', $request->adisyonhizmetid)
                ->with('hizmet')
                ->orderBy('seans_tarih')->orderBy('seans_no')->get();
            $ah = DB::table('adisyon_hizmetler')->where('id', $request->adisyonhizmetid)->first();
            $baslik      = $ah ? DB::table('hizmetler')->where('id', $ah->hizmet_id)->value('hizmet_adi') : '';
            $seansAdedi  = $ah->seans_sayisi ?? null;
            $baslangic   = $ah->islem_tarihi ?? null;
            $adisyonId   = $ah->adisyon_id ?? null;
        }

        $adisyon  = $adisyonId ? DB::table('adisyonlar')->where('id', $adisyonId)->first() : null;
        $salonId  = $adisyon->salon_id ?? self::mevcutsube($request);
        $musteri  = $adisyon ? DB::table('users')->where('id', $adisyon->user_id)->first() : null;
        $isletme  = Salonlar::where('id', $salonId)->first();

        // Her kart (hizmet) = bir bolge. Seanslari bolgeye gore grupla; her bolgenin
        // cihaz verisi girilmis seanslarini listele.
        $gruplar = [];
        foreach ($seanslar as $seans) {
            $hid = $seans->hizmet_id;
            if (!isset($gruplar[$hid])) {
                $gruplar[$hid] = ['ad' => optional($seans->hizmet)->hizmet_adi ?: '-', 'seanslar' => []];
            }
            $gruplar[$hid]['seanslar'][] = $seans;
        }

        // Performans: her seans icin ayri sorgu (N+1) yerine tum cihaz verilerini
        // TEK sorguda cek + personel'i eager-load et, seans_id'ye gore grupla.
        $verilerBySeans = SeansCihazVerileri::whereIn('seans_id', $seanslar->pluck('id'))
            ->with('personel')
            ->orderBy('id')
            ->get()
            ->groupBy('seans_id');

        $bolgeler = [];
        foreach ($gruplar as $g) {
            $sirali = collect($g['seanslar'])->sortBy('seans_tarih')->values();
            $rows = [];
            $no = 0;
            foreach ($sirali as $seans) {
                $no++;
                $veriler = $verilerBySeans[$seans->id] ?? collect();
                if ($veriler->isEmpty()) { continue; }
                foreach ($veriler as $v) {
                    $rows[] = [
                        'no'       => $seans->seans_no ?: $no,
                        'tarih'    => $seans->seans_tarih ? date('d.m.Y', strtotime($seans->seans_tarih)) : '-',
                        'enerji'   => $v->enerji ?: '-',
                        'hiz'      => $v->hiz ?: '-',
                        'ms'       => $v->ms ?: '-',
                        'atis'     => $v->atis_sayisi ?: '-',
                        'personel' => optional($v->personel)->personel_adi ?: '-',
                    ];
                }
            }
            if (count($rows)) {
                $bolgeler[] = ['ad' => $g['ad'], 'satirlar' => $rows];
            }
        }

        // Toplam seans: paket ise (seans_sayisi x hizmet adedi), degilse seans_sayisi
        if ($paketMi && $ap) {
            $hizmetSayisi = DB::table('paket_hizmetler')->where('paket_id', $ap->paket_id)->count();
            $toplam = $hizmetSayisi > 0 ? ($seansAdedi * $hizmetSayisi) : $seansAdedi;
        } else {
            $toplam = $seansAdedi;
        }
        $kullanilan = $seanslar->where('geldi', 1)->count();

        // Baslangic tarihi bozuksa (0000-00-00 vb.) '-' goster
        $baslangicStr = '-';
        if ($baslangic && substr($baslangic, 0, 4) !== '0000' && substr($baslangic, 0, 1) !== '-') {
            $ts = strtotime($baslangic);
            if ($ts && $ts > 0) { $baslangicStr = date('d.m.Y', $ts); }
        }
        // Paket baslangic tarihi yoksa: ilk (en erken) seans tarihini kullan
        if ($baslangicStr === '-') {
            $ilkTarih = null;
            foreach ($seanslar as $s) {
                $t = $s->seans_tarih;
                if ($t && substr($t, 0, 4) !== '0000' && strtotime($t) > 0) {
                    if ($ilkTarih === null || $t < $ilkTarih) { $ilkTarih = $t; }
                }
            }
            if ($ilkTarih) { $baslangicStr = date('d.m.Y', strtotime($ilkTarih)); }
        }

        $logoDataUri = self::seansDokumuLogo($isletme);

        $pdf = PDF::loadView('isletmeadmin.seans_dokumu_pdf', [
            'isletme'    => $isletme,
            'logo'       => $logoDataUri,
            'musteri'    => $musteri,
            'baslik'     => $baslik,
            'toplam'     => $toplam,
            'kullanilan' => $kullanilan,
            'baslangic'  => $baslangicStr,
            'bolgeler'   => $bolgeler,
        ]);
        $pdf->setPaper('a4', 'portrait');
        $ad = preg_replace('/[^A-Za-z0-9_-]+/', '-', self::trSlug(($musteri->name ?? 'musteri') . '-' . $baslik));
        return $pdf->stream('seans-dokumu-' . trim($ad, '-') . '.pdf');
    }

    // Salon logosunu PDF icin base64 data-uri'ye cevir (yoksa null).
    // ONEMLI: logo once KUCULTULUR. Aksi halde tam cozunurluklu (birkac MB) logo
    // PDF'e gomulunce dompdf render'i ~20 sn suruyor + PDF ~3 MB oluyordu.
    private static function seansDokumuLogo($isletme)
    {
        $logo = trim((string) optional($isletme)->logo);
        if ($logo === '') return null;
        $cands = [base_path($logo), public_path($logo), public_path(ltrim($logo, '/')), public_path(preg_replace('#^public/#', '', $logo))];
        foreach ($cands as $cand) {
            if (is_file($cand)) {
                // PERFORMANS: GD ile kucultme her PDF isteginde tekrarlanmasin.
                // Anahtar dosya yolu + son degistirme zamani + boyut → logo
                // degisirse onbellek kendiliginden gecersizlesir.
                $ck = 'seansdokumu_logo_' . md5($cand . '|' . @filemtime($cand) . '|' . @filesize($cand));
                $onbellek = Cache::get($ck);
                if (is_string($onbellek) && $onbellek !== '') return $onbellek;
                // Once kucultulmus surumu dene (GD varsa), olmazsa ham dosyaya dus.
                $kucuk = self::gorseliKucultDataUri($cand, 160);
                if ($kucuk !== null) { Cache::put($ck, $kucuk, 60 * 24 * 7); return $kucuk; }
                $bin = @file_get_contents($cand);
                if ($bin !== false) {
                    $mime = @getimagesize($cand)['mime'] ?? 'image/png';
                    $uri  = 'data:' . $mime . ';base64,' . base64_encode($bin);
                    Cache::put($ck, $uri, 60 * 24 * 7);
                    return $uri;
                }
            }
        }
        return null;
    }

    // Bir gorsel dosyasini en fazla $maxBoyut px'e kucultup PNG data-uri dondurur.
    // GD yoksa veya cozulemezse null (cagiran ham dosyaya duser).
    private static function gorseliKucultDataUri($path, $maxBoyut)
    {
        if (!function_exists('imagecreatetruecolor')) return null;
        $info = @getimagesize($path);
        if (!$info || empty($info[0]) || empty($info[1])) return null;
        [$w, $h] = $info;
        $mime = $info['mime'] ?? '';
        switch ($mime) {
            case 'image/jpeg': $src = @imagecreatefromjpeg($path); break;
            case 'image/png':  $src = @imagecreatefrompng($path); break;
            case 'image/gif':  $src = @imagecreatefromgif($path); break;
            case 'image/webp': $src = function_exists('imagecreatefromwebp') ? @imagecreatefromwebp($path) : false; break;
            default: return null;
        }
        if (!$src) return null;
        $olcek = min(1, $maxBoyut / max($w, $h));
        $nw = max(1, (int) round($w * $olcek));
        $nh = max(1, (int) round($h * $olcek));
        $dst = imagecreatetruecolor($nw, $nh);
        imagealphablending($dst, false);
        imagesavealpha($dst, true);
        $seffaf = imagecolorallocatealpha($dst, 0, 0, 0, 127);
        imagefilledrectangle($dst, 0, 0, $nw, $nh, $seffaf);
        imagecopyresampled($dst, $src, 0, 0, 0, 0, $nw, $nh, $w, $h);
        ob_start();
        imagepng($dst, null, 6);
        $bin = ob_get_clean();
        imagedestroy($src);
        imagedestroy($dst);
        if (!$bin) return null;
        return 'data:image/png;base64,' . base64_encode($bin);
    }

    public function randevuGeldiGelmediIsaretiKaldir(Request $request)
    {
        $randevu = Randevular::where('id',$request->randevuid)->first();
        if(!$randevu){
            return response()->json(['ok' => false, 'message' => 'Randevu bulunamadı'], 404);
        }
        $randevu->randevuya_geldi = null;
        $randevu->save();
        foreach($randevu->hizmetler as $hizmet)
        {
            if($hizmet->hizmet_id == $request->hizmetid){
                $hizmet->seansa_geldi = null;
                $hizmet->save();
            }
        }
        $seanslar = AdisyonPaketSeanslar::where('randevu_id',$request->randevuid)->get();
        foreach($seanslar as $seans)
        {
            $seans->geldi = null;
            $seans->save();
        }
        // AJAX (dataType:'json') parse hatasi yememesi icin gecerli JSON yaniti dondur;
        // success callback artik modal'i kapatabilir + takvimi yenileyebilir.
        return response()->json(['ok' => true, 'message' => 'Geldi işareti kaldırıldı']);
    }

    public function hizmetYonetimiGuncelle(Request $request){
        if($r = self::yetkiYoksa403($request, 'hizmet.tanim_olustur')) return $r;
        $isletmeid = self::mevcutsube($request);
        $sh = SalonHizmetler::where('id',$request->salon_hizmet_id)->where('salon_id',$isletmeid)->first();
        if(!$sh) return response()->json(['status'=>'error','message'=>'Hizmet bulunamadı']);

        $hizmet = Hizmetler::where('id',$sh->hizmet_id)->first();
        // Havuz hizmeti (ozel_hizmet=false veya baska salona ait) ise ad ve kategori degisemez;
        // cinsiyet, sure, fiyat ve personel atamasi her hizmet icin degistirilebilir.
        $is_ozel_duzenlenebilir = $hizmet && ($hizmet->ozel_hizmet == 1 || $hizmet->ozel_hizmet === true) && $hizmet->salon_id == $isletmeid;

        // Cinsiyet her zaman guncellenebilir
        if($hizmet && $request->has('cinsiyet')){
            $hizmet->cinsiyet = $request->cinsiyet;
        }
        if($is_ozel_duzenlenebilir){
            if($request->has('hizmet_adi') && $request->hizmet_adi != ''){
                $hizmet->hizmet_adi = $request->hizmet_adi;
            }
            if($request->has('kategori_id')) $sh->hizmet_kategori_id = $request->kategori_id;
        }
        if($hizmet) $hizmet->save();

        // Sure, fiyat ve personel atamasi her hizmet icin degistirilebilir
        if($request->has('fiyat')) $sh->baslangic_fiyat = self::parseFiyat($request->fiyat);
        if($request->has('sure_dk')) $sh->sure_dk = $request->sure_dk;
        $sh->save();

        if($request->has('personel_ids')){
            PersonelHizmetler::where('hizmet_id',$sh->hizmet_id)->whereHas('personeller',function($q) use($isletmeid){$q->where('salon_id',$isletmeid);})->delete();
            CihazHizmetler::where('hizmet_id',$sh->hizmet_id)->whereHas('cihaz',function($q) use($isletmeid){$q->where('salon_id',$isletmeid);})->delete();
            if(is_array($request->personel_ids)){
                foreach($request->personel_ids as $pid){
                    if(str_contains($pid,'cihaz')){
                        $str = explode('-',$pid);
                        $ch = new CihazHizmetler();
                        $ch->cihaz_id = $str[1];
                        $ch->hizmet_id = $sh->hizmet_id;
                        $ch->save();
                    } else {
                        $ph = new PersonelHizmetler();
                        $ph->personel_id = $pid;
                        $ph->hizmet_id = $sh->hizmet_id;
                        $ph->save();
                    }
                }
            }
        }

        // Guncel personel/cihaz adlari (DOM refresh icin)
        $personelAdlari = PersonelHizmetler::where('hizmet_id', $sh->hizmet_id)
            ->whereHas('personeller', function($q) use($isletmeid){ $q->where('salon_id', $isletmeid); })
            ->with('personeller')
            ->get()->pluck('personeller.personel_adi')->filter()->values()->all();
        $cihazAdlari = CihazHizmetler::where('hizmet_id', $sh->hizmet_id)
            ->whereHas('cihaz', function($q) use($isletmeid){ $q->where('salon_id', $isletmeid); })
            ->with('cihaz')
            ->get()->pluck('cihaz.cihaz_adi')->filter()->values()->all();
        $personellerStr = implode(', ', array_merge($personelAdlari, $cihazAdlari));

        // Audit
        $_audit_hizmetAdi = optional($hizmet)->hizmet_adi ?? 'Hizmet #'.$sh->hizmet_id;
        SalonAudit::log($isletmeid, 'hizmet_yonetim_guncelle', 'salon_hizmet', $sh->id,
            $_audit_hizmetAdi.' — '.number_format((float)$sh->baslangic_fiyat,2,',','.').' ₺',
            'Hizmet yönetimi güncellendi (fiyat / süre / personel / kategori)',
            ['hizmet_id'=>$sh->hizmet_id, 'fiyat'=>$sh->baslangic_fiyat, 'sure_dk'=>$sh->sure_dk, 'kategori_id'=>$sh->hizmet_kategori_id]);

        return response()->json([
            'status' => 'success',
            'message' => 'Hizmet başarıyla güncellendi',
            'personeller' => $personellerStr,
            'kategori_id' => $sh->hizmet_kategori_id,
        ]);
    }

    public function hizmetKategoriEkle(Request $request){
        if($r = self::yetkiYoksa403($request, 'hizmet.kategori_yonet')) return $r;
        $kategori = new Hizmet_Kategorisi();
        $kategori->hizmet_kategorisi_adi = $request->kategori_adi;
        $kategori->save();
        // Audit
        SalonAudit::log(self::mevcutsube($request), 'hizmet_kategori_ekle', 'hizmet_kategori', $kategori->id,
            $kategori->hizmet_kategorisi_adi,
            'Yeni hizmet kategorisi eklendi');
        return response()->json(['status'=>'success','message'=>'Kategori başarıyla eklendi','kategori_id'=>$kategori->id,'kategori_adi'=>$kategori->hizmet_kategorisi_adi]);
