    public function hizmetKategoriSil(Request $request){
        if($r = self::yetkiYoksa403($request, 'hizmet.kategori_yonet')) return $r;
        $isletmeid = self::mevcutsube($request);
        $kategori_hizmetler = SalonHizmetler::where('salon_id',$isletmeid)->where('hizmet_kategori_id',$request->kategori_id)->where('aktif',1)->count();
        if($kategori_hizmetler > 0){
            return response()->json(['status'=>'error','message'=>'Bu kategoride hizmetler bulunmaktadır. Önce hizmetleri siliniz.']);
        }
        // Audit
        $_audit_katAdi = \App\Hizmet_Kategorisi::where('id',$request->kategori_id)->value('hizmet_kategorisi_adi') ?? ('Kategori #'.$request->kategori_id);
        SalonAudit::log($isletmeid, 'hizmet_kategori_sil', 'hizmet_kategori', $request->kategori_id,
            $_audit_katAdi,
            'Hizmet kategorisi silindi');
        return response()->json(['status'=>'success','message'=>'Kategori başarıyla silindi']);
    }

    // ── Dinamik Form Şablonları ──────────────────────────────────────────────

    private function dinamikFormKolonlariOlustur(){
        try {
            $cols = array_column(\DB::select("SHOW COLUMNS FROM formtaslaklari"), 'Field');
            if(!in_array('is_dinamik',$cols)){
                \DB::statement("ALTER TABLE formtaslaklari ADD COLUMN aciklama TEXT NULL AFTER form_adi");
                \DB::statement("ALTER TABLE formtaslaklari ADD COLUMN sorular_json TEXT NULL AFTER aciklama");
                \DB::statement("ALTER TABLE formtaslaklari ADD COLUMN is_dinamik TINYINT(1) NOT NULL DEFAULT 0 AFTER sorular_json");
            }
            if(!in_array('sira',$cols)){
                \DB::statement("ALTER TABLE formtaslaklari ADD COLUMN sira INT NOT NULL DEFAULT 0");
            }
            if(!in_array('is_sozlesme_tipi',$cols)){
                \DB::statement("ALTER TABLE formtaslaklari ADD COLUMN is_sozlesme_tipi TINYINT(1) NOT NULL DEFAULT 0");
            }
            $arsivCols = array_column(\DB::select("SHOW COLUMNS FROM arsiv"), 'Field');
            if(!in_array('cevaplar_json',$arsivCols)){
                \DB::statement("ALTER TABLE arsiv ADD COLUMN cevaplar_json TEXT NULL AFTER dogrulama_kodu");
            }
            if(!in_array('musteri_imza',$arsivCols)){
                \DB::statement("ALTER TABLE arsiv ADD COLUMN musteri_imza MEDIUMTEXT NULL AFTER cevaplar_json");
            }
            if(!in_array('is_sozlesme',$arsivCols)){
                \DB::statement("ALTER TABLE arsiv ADD COLUMN is_sozlesme TINYINT(1) NOT NULL DEFAULT 0");
                \DB::statement("ALTER TABLE arsiv ADD COLUMN seans_sayisi INT NULL");
                \DB::statement("ALTER TABLE arsiv ADD COLUMN paket_id INT NULL");
                \DB::statement("ALTER TABLE arsiv ADD COLUMN sozlesme_notu TEXT NULL");
            }
            if(!in_array('imza_ip',$arsivCols)){
                \DB::statement("ALTER TABLE arsiv ADD COLUMN imza_ip VARCHAR(45) NULL");
                \DB::statement("ALTER TABLE arsiv ADD COLUMN imza_cihaz VARCHAR(255) NULL");
                \DB::statement("ALTER TABLE arsiv ADD COLUMN kvkk_onay TINYINT(1) NOT NULL DEFAULT 0");
                \DB::statement("ALTER TABLE arsiv ADD COLUMN imza_zaman DATETIME NULL");
            }
            if(!in_array('sozlesme_metni',$arsivCols)){
                \DB::statement("ALTER TABLE arsiv ADD COLUMN sozlesme_metni TEXT NULL");
            }
            if(!in_array('salon_imza',$arsivCols)){
                \DB::statement("ALTER TABLE arsiv ADD COLUMN salon_imza MEDIUMTEXT NULL");
                \DB::statement("ALTER TABLE arsiv ADD COLUMN salon_yetkili_ad VARCHAR(255) NULL");
                \DB::statement("ALTER TABLE arsiv ADD COLUMN salon_yetkili_telefon VARCHAR(30) NULL");
                \DB::statement("ALTER TABLE arsiv ADD COLUMN salon_imza_ip VARCHAR(45) NULL");
                \DB::statement("ALTER TABLE arsiv ADD COLUMN salon_imza_zaman DATETIME NULL");
            }
            if(!in_array('odeme_sekli',$arsivCols)){
                \DB::statement("ALTER TABLE arsiv ADD COLUMN odeme_sekli VARCHAR(20) NULL");
                \DB::statement("ALTER TABLE arsiv ADD COLUMN taksit_sayisi INT NULL");
                \DB::statement("ALTER TABLE arsiv ADD COLUMN taksit_tutari DECIMAL(12,2) NULL");
                \DB::statement("ALTER TABLE arsiv ADD COLUMN ilk_taksit_tarihi DATE NULL");
                \DB::statement("ALTER TABLE arsiv ADD COLUMN odeme_plani_json TEXT NULL");
                \DB::statement("ALTER TABLE arsiv ADD COLUMN gecerlilik_tarihi DATE NULL");
            }
            $salonCols = array_column(\DB::select("SHOW COLUMNS FROM salonlar"), 'Field');
            if(!in_array('sozlesme_varsayilan_metin',$salonCols)){
                \DB::statement("ALTER TABLE salonlar ADD COLUMN sozlesme_varsayilan_metin TEXT NULL");
            }
        } catch(\Exception $e){
            \Log::error('Dinamik form kolon oluşturma hatası: '.$e->getMessage());
        }
    }

    public function formSablonlari(Request $request){
        $this->dinamikFormKolonlariOlustur();
        $isletmeler = '';
        $isletme = '';
        if(Auth::guard('satisortakligi')->check()){
            $isletmeler = [15];
            $isletme = Salonlar::where('id',15)->first();
        } else {
            $isletmeler = Auth::guard('isletmeyonetim')->user()->yetkili_olunan_isletmeler->where('aktif',1)->pluck('salon_id')->toArray();
            $isletme = Salonlar::where('id',self::mevcutsube($request))->first();
        }
        if(!in_array(self::mevcutsube($request),$isletmeler)){
            return view('isletmeadmin.yetkisizerisim');
        }
        if(!Auth::guard('satisortakligi')->check()){
            if(self::personelmi($request, 'form.olustur')){
                return redirect()->route('isletmeadmin.randevular');
            }
        }
        $paketler = self::paket_liste_getir('',true,$request);
        $kalan_uyelik_suresi = self::lisans_sure_kontrol($request);
        $formlar = FormTaslaklari::where('is_dinamik',1)->where('salon_id',self::mevcutsube($request))->orderBy('sira','asc')->orderByDesc('id')->get();
        return view('isletmeadmin.form_sablonlari',[
            'bildirimler' => self::bildirimgetir($request),
            'paketler' => $paketler,
            'sayfa_baslik' => 'Form Şablonları',
            'pageindex' => 51,
            'isletme' => $isletme,
            'kalan_uyelik_suresi' => $kalan_uyelik_suresi,
            'yetkiliolunanisletmeler' => $isletmeler,
            'formlar' => $formlar,
        ]);
    }

