        return response()->json($sablon);
    }

    /**
     * Anket sablonu odul ayarlarini request'ten okuyup sablona uygular (kaydet+guncelle ortak).
     *  odul_tipi: yok | kupon | puan
     *  kupon -> indirim_tipi (yuzde|tutar), deger, gecerlilik_gun, hizmet_id (null=tum), baslik
     *  puan  -> odul_puan
     */
    private static function anketOdulAyarlariUygula($sablon, Request $request){
        $tip = in_array($request->odul_tipi, ['kupon','puan']) ? $request->odul_tipi : 'yok';
        $sablon->odul_tipi = $tip;
        // Once hepsini temizle; sadece secili tipe ait alanlari doldur.
        $sablon->odul_kupon_indirim_tipi   = null;
        $sablon->odul_kupon_deger          = null;
        $sablon->odul_kupon_gecerlilik_gun = null;
        $sablon->odul_kupon_hizmet_id      = null;
        $sablon->odul_puan                 = null;
        $sablon->odul_baslik               = null;
        if ($tip === 'kupon') {
            $sablon->odul_kupon_indirim_tipi   = $request->odul_kupon_indirim_tipi === 'tutar' ? 'tutar' : 'yuzde';
            $sablon->odul_kupon_deger          = max(0, (float) ($request->odul_kupon_deger ?? 0));
            $g = (int) ($request->odul_kupon_gecerlilik_gun ?? 0);
            $sablon->odul_kupon_gecerlilik_gun = $g > 0 ? $g : null; // 0/bos = suresiz
            $h = (int) ($request->odul_kupon_hizmet_id ?? 0);
            $sablon->odul_kupon_hizmet_id      = $h > 0 ? $h : null; // null = tum hizmetler
            $sablon->odul_baslik               = trim($request->odul_baslik ?? '') ?: null;
        } elseif ($tip === 'puan') {
            $sablon->odul_puan   = max(0, (float) ($request->odul_puan ?? 0));
            $sablon->odul_baslik = trim($request->odul_baslik ?? '') ?: null;
        }
    }

    public function anketSablonKaydet(Request $request){
        if($r = self::yetkiYoksa403($request, 'pazarlama.anket_yonet')) return $r;
        try {
            $sube = self::mevcutsube($request);
            $sablon = new AnketSablon();
            $sablon->salon_id          = $sube;
            $sablon->ad                = trim($request->ad);
            $sablon->aciklama          = $request->aciklama;
            $sablon->sorular_json      = $request->sorular_json;
            $sablon->otomatik_gonder   = $request->otomatik_gonder ? 1 : 0;
            $sablon->gonder_saat_sonra = max(0, (int) ($request->gonder_saat_sonra ?? 0));
            self::anketOdulAyarlariUygula($sablon, $request);
            $sablon->aktif             = 1;
            $sablon->varsayilan        = $request->varsayilan ? 1 : 0;
            if($sablon->varsayilan){
                AnketSablon::where('salon_id',$sube)->update(['varsayilan'=>0]);
            }
            $sablon->save();
            // Audit
            SalonAudit::log($sube, 'anket_sablon_ekle', 'anket_sablon', $sablon->id,
                $sablon->ad,
                'Yeni memnuniyet anketi şablonu oluşturuldu',
                ['otomatik'=>$sablon->otomatik_gonder, 'saat_sonra'=>$sablon->gonder_saat_sonra]);
            return response()->json(['basarili'=>true,'id'=>$sablon->id]);
        } catch(\Exception $e){
            \Log::error('anketSablonKaydet hata: '.$e->getMessage());
            return response()->json(['basarili'=>false,'mesaj'=>$e->getMessage()]);
        }
    }

    public function anketSablonGuncelle(Request $request){
        if($r = self::yetkiYoksa403($request, 'pazarlama.anket_yonet')) return $r;
        try {
            $sube = self::mevcutsube($request);
            $sablon = AnketSablon::where('id',$request->sablon_id)->where('salon_id',$sube)->first();
            if(!$sablon) return response()->json(['basarili'=>false,'mesaj'=>'Şablon bulunamadı.']);
            $sablon->ad                = trim($request->ad);
            $sablon->aciklama          = $request->aciklama;
            $sablon->sorular_json      = $request->sorular_json;
            $sablon->otomatik_gonder   = $request->otomatik_gonder ? 1 : 0;
            $sablon->gonder_saat_sonra = max(0, (int) ($request->gonder_saat_sonra ?? 0));
            self::anketOdulAyarlariUygula($sablon, $request);
            if($request->has('aktif')) $sablon->aktif = $request->aktif ? 1 : 0;
            if($request->has('varsayilan')){
                $sablon->varsayilan = $request->varsayilan ? 1 : 0;
                if($sablon->varsayilan){
                    AnketSablon::where('salon_id',$sube)->where('id','!=',$sablon->id)->update(['varsayilan'=>0]);
                }
            }
            $sablon->save();
            // Audit
            SalonAudit::log($sube, 'anket_sablon_guncelle', 'anket_sablon', $sablon->id,
                $sablon->ad,
                'Anket şablonu güncellendi',
                ['otomatik'=>$sablon->otomatik_gonder, 'aktif'=>$sablon->aktif, 'varsayilan'=>$sablon->varsayilan]);
            return response()->json(['basarili'=>true]);
        } catch(\Exception $e){
            \Log::error('anketSablonGuncelle hata: '.$e->getMessage());
            return response()->json(['basarili'=>false,'mesaj'=>$e->getMessage()]);
        }
    }

    public function anketSablonSil(Request $request){
        if($r = self::yetkiYoksa403($request, 'pazarlama.anket_yonet')) return $r;
        try {
            $sube = self::mevcutsube($request);
            $sablon = AnketSablon::where('id',$request->sablon_id)->where('salon_id',$sube)->first();
            if(!$sablon) return response()->json(['basarili'=>false,'mesaj'=>'Şablon bulunamadı.']);
            $kullanim = AnketGonderim::where('sablon_id',$sablon->id)->count();
            if($kullanim > 0){
                $sablon->aktif = 0;
                $sablon->save();
                // Audit
                SalonAudit::log($sube, 'anket_sablon_pasifle', 'anket_sablon', $sablon->id,
                    $sablon->ad,
                    'Anket şablonu kullanımda olduğu için pasifleştirildi',
                    ['kullanim_sayisi'=>$kullanim]);
                return response()->json(['basarili'=>true,'mesaj'=>'Şablon '.$kullanim.' anket gönderiminde kullanılmış, pasifleştirildi.']);
            }
            // Audit
            SalonAudit::log($sube, 'anket_sablon_sil', 'anket_sablon', $sablon->id,
                $sablon->ad,
                'Anket şablonu silindi');
            $sablon->delete();
            return response()->json(['basarili'=>true]);
        } catch(\Exception $e){
            return response()->json(['basarili'=>false,'mesaj'=>$e->getMessage()]);
        }
    }

    public function anketWebGizleToggle(Request $request){
