    public function anketManuelGonder(Request $request){
        if($r = self::yetkiYoksa403($request, 'pazarlama.anket_yonet')) return $r;
        try {
            $sube = self::mevcutsube($request);
            $userId = (int) $request->user_id;
            $cepTel = trim($request->cep_telefon);
            $sablonId = (int) $request->sablon_id;
            $adSoyad = trim($request->ad_soyad ?: '');

            if(!$cepTel) return response()->json(['basarili'=>false,'mesaj'=>'Telefon zorunlu.']);

            $sablon = AnketSablon::where('id',$sablonId)->where('salon_id',$sube)->where('aktif',1)->first();
            if(!$sablon) return response()->json(['basarili'=>false,'mesaj'=>'Aktif anket şablonu bulunamadı.']);

            // Test/manuel gönderim: user_id varsa kullan, yoksa ad_soyad input'u kullan (test için anonim)
            $musteri = $userId ? User::where('id',$userId)->first() : null;
            if(!$musteri){
                // Sahte musteri objesi oluştur (DB'ye kaydetmez, anketGonderimOlustur'a name/id geçirmek için)
                $musteri = (object) ['id' => null, 'name' => $adSoyad ?: 'Test'];
            }
            $gonderim = self::anketGonderimOlustur($sube, $sablon, $musteri, $cepTel, [
                'randevu_id' => $request->randevu_id ?: null,
                'personel_id' => $request->personel_id ?: null,
                'kanal' => 'manuel',
            ]);

            self::anketSmsGonder($request, $gonderim, $sablon, $musteri);

            // Audit
            SalonAudit::log($sube, 'anket_manuel_gonder', 'anket_gonderim', $gonderim->id,
                ($musteri->name ?: 'Müşteri').' — '.$cepTel,
                'Manuel memnuniyet anketi gönderildi',
                ['sablon_id'=>$sablon->id, 'sablon_adi'=>$sablon->ad]);
            return response()->json(['basarili'=>true,'gonderim_id'=>$gonderim->id]);
        } catch(\Exception $e){
            \Log::error('anketManuelGonder hata: '.$e->getMessage());
            return response()->json(['basarili'=>false,'mesaj'=>$e->getMessage()]);
        }
    }

    /**
     * Hizli anket gonderimi — musteri detay ve musteriler listesinden
     * tek-tik ile manuel anket linki gonderir. Sadece user_id ister,
     * salon'un ilk aktif sablonunu ve musteri'nin kayitli cep telefonunu
     * DB'den kendisi cozer.
     *
     * WA-first (whatsmeow/baileys otomatik) + SMS fallback zaten
     * anketSmsGonder icinde. Bu endpoint sadece wrapper.
     */
    public function anketHizliGonder(Request $request){
        if($r = self::yetkiYoksa403($request, 'pazarlama.anket_yonet')) return $r;
        try {
            $sube = self::mevcutsube($request);
            $userId = (int) $request->user_id;
            if(!$userId) return response()->json(['basarili'=>false,'mesaj'=>'Musteri ID zorunlu.']);

            // Musteri kaydi + telefon
            $musteri = User::where('id', $userId)->first();
            if(!$musteri) return response()->json(['basarili'=>false,'mesaj'=>'Musteri bulunamadi.']);
            if(empty($musteri->cep_telefon)) {
                return response()->json(['basarili'=>false,'mesaj'=>'Musterinin telefon numarasi kayitli degil.']);
            }

            // Salonun ilk aktif anket sablonu — yoksa otomatik olusturur
            $sablon = self::varsayilanAnketSablonuGetirYaOlustur($sube);

            $gonderim = self::anketGonderimOlustur($sube, $sablon, $musteri, $musteri->cep_telefon, [
                'kanal' => 'manuel',
            ]);

            self::anketSmsGonder($request, $gonderim, $sablon, $musteri);

            // Audit
            SalonAudit::log($sube, 'anket_hizli_gonder', 'anket_gonderim', $gonderim->id,
                ($musteri->name ?: 'Musteri').' — '.$musteri->cep_telefon,
                'Musteri kartindan hizli anket gonderimi',
                ['sablon_id'=>$sablon->id, 'sablon_adi'=>$sablon->ad, 'user_id'=>$userId]);

            return response()->json([
                'basarili'=>true,
                'mesaj'=>'Anket gonderildi.',
                'gonderim_id'=>$gonderim->id,
                'kanal'=>$gonderim->gonderim_kanali ?: 'sms',
            ]);
        } catch(\Exception $e){
            \Log::error('anketHizliGonder hata: '.$e->getMessage());
            return response()->json(['basarili'=>false,'mesaj'=>$e->getMessage()]);
        }
    }

    public function anketSonuclari(Request $request){
        $isletmeler = '';
        $isletme = '';
        if(Auth::guard('satisortakligi')->check()){
            $isletmeler = [15];
            $isletme = Salonlar::where('id',15)->first();
        } else {
            $isletmeler = Auth::guard('isletmeyonetim')->user()->yetkili_olunan_isletmeler->where('aktif',1)->pluck('salon_id')->toArray();
            $isletme = Salonlar::where('id',self::mevcutsube($request))->first();
        }
        if(!in_array(self::mevcutsube($request),$isletmeler)){
            return view('isletmeadmin.yetkisizerisim');
        }
        // Yetki: bu sayfanin gerektirdigi yetki yoksa 403
        $_authUser = Auth::guard('isletmeyonetim')->user();
        if ($_authUser && !\App\Services\PersonelYetkiServisi::yetkiliYetkiVar($_authUser->id, self::mevcutsube($request), 'pazarlama.anket_yonet')) {
            return view('isletmeadmin.yetkisizerisim');
            exit(0);
        }
        if(!Auth::guard('satisortakligi')->check()){
            if(self::personelmi($request, 'pazarlama.anket_yonet')){
                return redirect()->route('isletmeadmin.randevular');
            }
        }
        $paketler = self::paket_liste_getir('',true,$request);
        $kalan_uyelik_suresi = self::lisans_sure_kontrol($request);
        $sube = self::mevcutsube($request);

        $bas = $request->bas ? date('Y-m-d 00:00:00', strtotime($request->bas)) : date('Y-m-d 00:00:00', strtotime('-30 days'));
        $bit = $request->bit ? date('Y-m-d 23:59:59', strtotime($request->bit)) : date('Y-m-d 23:59:59');

        $tum = AnketGonderim::where('salon_id',$sube)
            ->whereBetween('gonderim_zamani',[$bas,$bit])
            ->orderByDesc('id')->get();

        $cevaplananlar = $tum->where('cevaplandi',1);
        $toplamGonderim = $tum->count();
        $toplamCevap    = $cevaplananlar->count();
        $cevapOrani     = $toplamGonderim ? round($toplamCevap*100/$toplamGonderim, 1) : 0;

        // NPS = (% promoters 9-10) - (% detractors 0-6)
        $npsCevaplari = $cevaplananlar->filter(function($g){ return !is_null($g->nps_skoru); });
        $promoter  = $npsCevaplari->filter(function($g){ return $g->nps_skoru >= 9; })->count();
        $passive   = $npsCevaplari->filter(function($g){ return $g->nps_skoru >= 7 && $g->nps_skoru <= 8; })->count();
        $detractor = $npsCevaplari->filter(function($g){ return $g->nps_skoru <= 6; })->count();
        $npsToplam = $npsCevaplari->count();
        $npsSkor   = $npsToplam ? round((($promoter - $detractor) / $npsToplam) * 100) : null;

        $csatCevaplari = $cevaplananlar->filter(function($g){ return !is_null($g->csat_skoru); });
        $csatOrt = $csatCevaplari->count() ? round($csatCevaplari->avg('csat_skoru'),2) : null;

        $sablonlar = AnketSablon::where('salon_id',$sube)->orderByDesc('aktif')->orderBy('ad')->get();

        // Premium istatistikler
        $googleTiklamalar = $cevaplananlar->filter(function($g){ return $g->google_yonlendirildi; })->count();
        // Dusuk puan veren: esik altinda NPS veya CSAT (flag bagimsiz, gercek sayi)
        $esikNpsK = $isletme->kotu_puan_uyari_esik_nps ?? 6;
        $esikCsatK = $isletme->kotu_puan_uyari_esik_csat ?? 2.5;
        $kotuPuanUyarilari = $cevaplananlar->filter(function($g) use ($esikNpsK, $esikCsatK){
            $npsDusuk = $g->nps_skoru !== null && $g->nps_skoru <= $esikNpsK;
            $csatDusuk = $g->csat_skoru !== null && $g->csat_skoru <= $esikCsatK;
            return $npsDusuk || $csatDusuk;
        })->count();

        return view('isletmeadmin.anket_sonuclari',[
            'bildirimler' => self::bildirimgetir($request),
            'paketler' => $paketler,
            'sayfa_baslik' => 'Memnuniyet Anketi Sonuçları',
            'pageindex' => 53,
            'isletme' => $isletme,
            'kalan_uyelik_suresi' => $kalan_uyelik_suresi,
            'yetkiliolunanisletmeler' => $isletmeler,
            'gonderimler' => $tum,
            'sablonlar' => $sablonlar,
            'bas' => date('Y-m-d', strtotime($bas)),
            'bit' => date('Y-m-d', strtotime($bit)),
            'salon' => $isletme,
            'google_tiklamalar' => $googleTiklamalar,
            'kotu_puan_uyarilari' => $kotuPuanUyarilari,
            'istatistik' => [
                'toplam_gonderim' => $toplamGonderim,
                'toplam_cevap'    => $toplamCevap,
                'cevap_orani'     => $cevapOrani,
                'nps_skor'        => $npsSkor,
                'nps_promoter'    => $promoter,
                'nps_passive'     => $passive,
                'nps_detractor'   => $detractor,
                'csat_ortalama'   => $csatOrt,
            ],
        ]);
    }

    public function anketGonderimDetay(Request $request){
        $sube = self::mevcutsube($request);
        $g = AnketGonderim::where('id',$request->id)->where('salon_id',$sube)->first();
        if(!$g) return response()->json(['hata'=>true]);
        $sablon = AnketSablon::where('id',$g->sablon_id)->first();
        $sorular = $sablon && $sablon->sorular_json ? json_decode($sablon->sorular_json, true) : [];
        $cevaplar = $g->cevaplar_json ? json_decode($g->cevaplar_json, true) : [];
        $musteri = $g->user_id ? User::where('id',$g->user_id)->first() : null;
        return response()->json([
            'gonderim'=>$g,
            'sorular'=>$sorular,
            'cevaplar'=>$cevaplar,
            'sablon_ad'=>$sablon->ad ?? '',
            'musteri_ad'=>$musteri->name ?? $g->ad_soyad,
        ]);
    }

    /**
     * Kısa token üret (base62, çakışma kontrolü ile). 8 char = 218 trilyon kombinasyon.
     * SMS karakter tasarrufu için kritik (32 hex → 8 char, 24 char URL kazancı).
     */
    private static function anketKisaToken($len = 8){
        $chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
        do {
            $token = '';
            for ($i = 0; $i < $len; $i++) {
                $token .= $chars[random_int(0, 61)];
            }
            $exists = AnketGonderim::where('token', $token)->exists();
        } while ($exists);
        return $token;
    }

    /**
     * Yardımcı: yeni anket gönderim kaydı oluşturur (token + son gecerlilik dahil).
     */
    /**
     * Salonun aktif anket sablonunu doner; yoksa varsayilan bir tane olusturur.
     * Boylece manuel hizli gonderimde kullanicidan sablon secmesi/olusturmasi
     * beklenmez, uygulama arka planda otomatik yapilandirir.
     */
    public static function varsayilanAnketSablonuGetirYaOlustur($salonId)
    {
        $sablon = AnketSablon::where('salon_id', $salonId)->where('aktif', 1)->orderBy('id')->first();
        if ($sablon) return $sablon;

        $sablon = new AnketSablon();
        $sablon->salon_id = $salonId;
        $sablon->ad = 'Varsayilan Memnuniyet Anketi';
        $sablon->aciklama = 'Sistem tarafindan ilk manuel gonderim sirasinda otomatik olusturuldu.';
        $sablon->sorular_json = json_encode([
            ['tip' => 'nps',  'soru' => 'Bizi bir arkadasiniza tavsiye eder misiniz? (0-10)'],
            ['tip' => 'csat', 'soru' => 'Hizmetimizden ne kadar memnun kaldiniz? (1-5)'],
            ['tip' => 'metin','soru' => 'Bize onerileriniz veya yorumlariniz nelerdir?'],
        ], JSON_UNESCAPED_UNICODE);
        $sablon->otomatik_gonder = 0;
        $sablon->gonder_saat_sonra = 24;
        $sablon->aktif = 1;
        $sablon->varsayilan = 1;
        $sablon->save();
        return $sablon;
    }

    public static function anketGonderimOlustur($salonId, $sablon, $musteri, $telefon, $opts = []){
        $token = self::anketKisaToken(8);
        $g = new AnketGonderim();
        $g->salon_id        = $salonId;
        $g->sablon_id       = $sablon->id;
        $g->randevu_id      = $opts['randevu_id'] ?? null;
        $g->arsiv_id        = $opts['arsiv_id'] ?? null;
        $g->user_id         = $musteri->id ?? null;
        $g->personel_id     = $opts['personel_id'] ?? null;
        $g->token           = $token;
        $g->ad_soyad        = $musteri->name ?? null;
        $g->telefon         = $telefon;
        $g->gonderim_kanali = $opts['kanal'] ?? 'sms';
        $g->gonderim_zamani = now();
        $g->son_gecerlilik  = now()->addDays(30);
        $g->save();
        return $g;
    }

    /**
     * Yardımcı: anket linkini WhatsApp-first mantığıyla gönderir.
     *  1) Salon WA aktif+connected ise WhatsApp'a dene
     *  2) WA fail olursa (veya kapaliysa) SMS'e düşür
     *
     * WhatsAppRouterService salon whatsapp_bridge_tipi'ne göre otomatik
     * Baileys (port 3001) veya whatsmeow (port 3002) seçer.
     *
     * Hem web (Request var) hem cron (Request null) konteksinden çağrılır.
     */
    public static function anketSmsGonder($request, $gonderim, $sablon, $musteri){
        $salon = Salonlar::where('id',$gonderim->salon_id)->first();
        $host = ($_SERVER['HTTP_HOST'] ?? null) ?: ($salon->domain ?? 'apptest.randevumcepte.com.tr');
        $link = 'https://'.$host.'/anket/'.$gonderim->token;
        // Sadece ilk ad — soyad SMS karakter tasarrufu için atlanir
        $adSoyad = $musteri->name ?? '';
        $ilkAd = $adSoyad ? trim(explode(' ', $adSoyad)[0]) : '';
        $salonAd = $salon->salon_adi ?? '';

        // Sablonda odul (kupon/puan) tanimliysa daveti odul-vurgulu yap — linke tiklama/tamamlama oranini artirir.
        $odulIfade = null;
        if ($sablon) {
            if (($sablon->odul_tipi ?? 'yok') === 'kupon' && (float) $sablon->odul_kupon_deger > 0) {
                $d = (float) $sablon->odul_kupon_deger;
                $odulIfade = ($sablon->odul_kupon_indirim_tipi === 'tutar')
                    ? (rtrim(rtrim(number_format($d, 2, ',', '.'), '0'), ',') . ' ₺ indirim kuponu')
                    : (intval($d) . '% indirim kuponu');
            } elseif (($sablon->odul_tipi ?? 'yok') === 'puan' && (float) $sablon->odul_puan > 0) {
                $p = (float) $sablon->odul_puan;
                $odulIfade = rtrim(rtrim(number_format($p, 2, ',', '.'), '0'), ',') . ' puan';
            }
        }

        // Not: Turkce karakter icerir; WhatsApp'ta sorunsuz, SMS fallback'te UCS-2 (cok parcali) gonderilir.
        if ($odulIfade) {
            // Odullu davet — odulu basa cikar, kisa tut, net CTA.
            $mesaj = "Merhaba Sn. ".$ilkAd." 🎁"."\n\n"
                .$salonAd." deneyiminizi değerlendirin, size özel ".$odulIfade." hediyemiz olsun!"."\n\n"
                ."Anketi doldurmak (30 sn):"."\n".$link."\n\n"
                ."Görüşleriniz bizim için çok değerli, teşekkür ederiz.";
        } else {
            // Nazik/kurumsal anket daveti — musteri adi + salon adi + dinamik anket linki.
            $mesaj = "Merhaba Sn. ".$ilkAd.","."\n\n"
                .$salonAd."'da yaşadığınız deneyim bizim için çok değerli. Hizmet kalitemizi geliştirebilmemiz adına görüşlerinizi birkaç dakikanızı ayırarak bizimle paylaşabilir misiniz?"."\n\n"
                ."Anketi doldurmak için:"."\n".$link."\n\n"
                ."Değerli geri bildiriminiz için şimdiden teşekkür eder, sizi yeniden ağırlamaktan mutluluk duyarız.";
        }

        // 1) WhatsApp-first — salon WA aktif+connected ise once WA dene
        // Paylasilan oturum: 416 icin 246'nin durumu kontrol edilir.
        $waSalonKontrol = $salon ? \App\Services\WhatsAppService::resolveWaSalon($salon) : null;
        $waKanaliAcik = $waSalonKontrol
            && !empty($waSalonKontrol->whatsapp_aktif)
            && ($waSalonKontrol->whatsapp_durum ?? null) === 'connected';

        if ($waKanaliAcik) {
            try {
                $wa = app(\App\Services\WhatsAppService::class);
                $sonuc = $wa->sendReminder(
                    $salon,
                    $gonderim->telefon,
                    $mesaj,
                    $gonderim->randevu_id ?? null,
                    $musteri->id ?? null,
                    null,
                    false,
                    'anket'
                );
                if (!empty($sonuc['ok'])) {
                    // WA kuyruğa girdi/iletildi — kanal alanını güncelle
                    try {
                        $gonderim->gonderim_kanali = 'whatsapp';
                        $gonderim->save();
                    } catch (\Throwable $e) { /* yoksay */ }
                    \Log::info('[ANKET-WA] gonderildi', [
                        'salon_id' => $salon->id,
                        'gonderim_id' => $gonderim->id,
                        'to' => $gonderim->telefon,
                        'provider' => $sonuc['provider'] ?? null,
                        'logId' => $sonuc['logId'] ?? null,
                    ]);
                    return;
                }
                \Log::warning('[ANKET-WA] basarisiz → SMS fallback', [
                    'salon_id' => $salon->id,
                    'gonderim_id' => $gonderim->id,
                    'err' => $sonuc['error'] ?? 'unknown',
                ]);
            } catch (\Throwable $e) {
                \Log::warning('[ANKET-WA] istisna → SMS fallback: '.$e->getMessage(), [
                    'salon_id' => $salon->id ?? null,
                    'gonderim_id' => $gonderim->id ?? null,
                ]);
            }
        }

        // 2) SMS fallback (WA kapali veya basarisiz)
        $mesajlar = [['to'=>$gonderim->telefon, 'message'=>$mesaj]];
        try {
            // Base Controller::sms_gonder($salon_id, $mesajlar) — request gerektirmez, cron'dan da çağrılabilir
            $ctrl = app()->make(\App\Http\Controllers\Controller::class);
            $ctrl->sms_gonder($gonderim->salon_id, $mesajlar);
        } catch(\Exception $e){
            \Log::error('anketSmsGonder hata: '.$e->getMessage());
        }
    }

    /**
     * Yardımcı: Google Maps/g.page URL'sinden DOĞRUDAN yorum yazma URL'i üretir.
     * Desteklediği formatlar (sıralı, ilk eşleşene göre):
     *  1. Doğrudan Place ID (ChIJ... ile başlar)            → writereview?placeid=
     *  2. writereview?placeid=...                            → değişmeden kullan
     *  3. g.page/r/{short}[/review]                          → /review eksikse ekle
     *  4. Maps URL'sinde !1s0x...:0x... (FID embedded)       → writereview?ftid=
     *  5. maps.app.goo.gl/{short} veya goo.gl/maps/{short}   → curl ile genişlet, sonra 1-4 dene
     *  6. Diğer Google Maps URL'leri                          → fallback olarak ham URL (uyarı ile)
     *
     * Returns: ['place_id' => string|null, 'review_url' => string|null, 'uyari' => string|null]
     */
    public static function googlePlaceIdParse($input){
        $input = trim((string)$input);
        if (!$input) return ['place_id' => null, 'review_url' => null, 'uyari' => null];

        // 1) Doğrudan Place ID
        if (preg_match('/^(ChIJ|GhIJ|EhIJ|EkIJ)[A-Za-z0-9_-]{20,}$/', $input)) {
            return [
                'place_id'   => $input,
                'review_url' => 'https://search.google.com/local/writereview?placeid=' . $input,
                'uyari'      => null,
            ];
        }

        // 2) writereview URL'si: placeid query parametresi (en doğru, doğrudan yorum yazma)
        if (preg_match('/placeid=([A-Za-z0-9_-]+)/', $input, $m)) {
            return [
                'place_id'   => $m[1],
                'review_url' => 'https://search.google.com/local/writereview?placeid=' . $m[1],
                'uyari'      => null,
            ];
        }

        // 3) g.page kısa form — /review suffix yoksa ekle
        if (preg_match('#g\.page/r/([A-Za-z0-9_-]+)#', $input, $m)) {
            return [
                'place_id'   => null,
                'review_url' => 'https://g.page/r/' . $m[1] . '/review',
                'uyari'      => null,
            ];
        }

        // 5) Kısa URL ise önce genişlet (maps.app.goo.gl, goo.gl/maps)
        $expanded = $input;
        if (preg_match('#^https?://(maps\.app\.goo\.gl|goo\.gl/maps|maps\.google\.com/url)#i', $input)) {
            $expanded = self::googleKisaUrlGenislet($input) ?: $input;
        }

        // 4) Genişletilmiş URL'de FID var mı? (!1s0x...:0x... format)
        if (preg_match('#!1s(0x[a-f0-9]+):(0x[a-f0-9]+)#i', $expanded, $m)) {
            $ftid = $m[1] . ':' . $m[2];
            return [
                'place_id'   => null,
                'review_url' => 'https://search.google.com/local/writereview?ftid=' . $ftid,
                'uyari'      => null,
            ];
        }

        // CID parametresi (cid=12345...)
        if (preg_match('#[?&]cid=(\d+)#', $expanded, $m)) {
            // CID'yi FID'e dönüştür: 0x0:0x{hex}
            $ftid = '0x0:0x' . dechex((int)$m[1]);
            return [
                'place_id'   => null,
                'review_url' => 'https://search.google.com/local/writereview?ftid=' . $ftid,
                'uyari'      => null,
            ];
        }

        // 6) Hâlâ tanımlanamayan URL — fallback (uyarı ile döner)
        if (preg_match('#^https?://#', $input)) {
            return [
                'place_id'   => null,
                'review_url' => $input,
                'uyari'      => 'Bu link harita sayfasını açar, doğrudan yorum yazma diyaloğunu açmayabilir. En güvenli yol: Google Business hesabınızdan "Yorum Bağlantısı"nı kopyalayıp yapıştırın (g.page/r/... formatında olmalı).',
            ];
        }

        return ['place_id' => null, 'review_url' => null, 'uyari' => 'Geçerli bir URL veya Place ID bulunamadı.'];
    }

    /**
     * Kısa Google URL'sini takip ederek gerçek hedef URL'i döner (maps.app.goo.gl genişletme).
     * Hata durumunda null döner.
     */
    private static function googleKisaUrlGenislet($url){
        try {
            if (!function_exists('curl_init')) return null;
            $ch = curl_init();
            curl_setopt($ch, CURLOPT_URL, $url);
            curl_setopt($ch, CURLOPT_NOBODY, true);
            curl_setopt($ch, CURLOPT_FOLLOWLOCATION, true);
            curl_setopt($ch, CURLOPT_MAXREDIRS, 5);
            curl_setopt($ch, CURLOPT_TIMEOUT, 4);
            curl_setopt($ch, CURLOPT_CONNECTTIMEOUT, 3);
            curl_setopt($ch, CURLOPT_SSL_VERIFYPEER, false);
            curl_setopt($ch, CURLOPT_USERAGENT, 'Mozilla/5.0 (Linux) GoogleMapsExpander');
            curl_exec($ch);
            $final = curl_getinfo($ch, CURLINFO_EFFECTIVE_URL);
            curl_close($ch);
            return $final ?: null;
        } catch (\Exception $e) {
            return null;
        }
    }

    public function reputationPremiumAc(Request $request){
        try {
            $sube = self::mevcutsube($request);
            $salon = Salonlar::where('id', $sube)->first();
            if (!$salon) return response()->json(['basarili'=>false,'mesaj'=>'Salon bulunamadı.']);

            if (!\Schema::hasColumn('salonlar', 'reputation_premium_aktif')) {
                return response()->json(['basarili'=>false,'mesaj'=>'reputation_premium_aktif sütunu yok. Migration çalıştırın.']);
            }

            $salon->reputation_premium_aktif = true;
            $salon->save();

            return response()->json(['basarili'=>true]);
        } catch(\Exception $e) {
            \Log::error('reputationPremiumAc hata: '.$e->getMessage());
            return response()->json(['basarili'=>false,'mesaj'=>$e->getMessage()]);
        }
    }

    public function googleReviewKaydet(Request $request){
        try {
            $sube = self::mevcutsube($request);
            $salon = Salonlar::where('id', $sube)->first();
            if (!$salon) return response()->json(['basarili'=>false,'mesaj'=>'Salon bulunamadı.']);

            $input = trim($request->google_input ?: '');
            $parsed = self::googlePlaceIdParse($input);

            if ($input && !$parsed['review_url']) {
                return response()->json(['basarili'=>false,'mesaj'=>($parsed['uyari'] ?? 'Bağlantı çözümlenemedi. Google Maps URL\'si veya g.page linki yapıştırın.')]);
            }

            $salon->google_review_url        = $parsed['review_url'];
            $salon->google_place_id          = $parsed['place_id'];
            $salon->google_review_esik_nps   = max(0, min(10, (int) ($request->google_review_esik_nps ?? 9)));
            $salon->google_review_esik_csat  = max(1, min(5, (float) ($request->google_review_esik_csat ?? 4.5)));
            $salon->kotu_puan_uyari_telefon  = trim($request->kotu_puan_uyari_telefon ?: '') ?: null;
            $salon->kotu_puan_uyari_esik_nps = max(0, min(10, (int) ($request->kotu_puan_uyari_esik_nps ?? 6)));
            $salon->kotu_puan_uyari_esik_csat= max(1, min(5, (float) ($request->kotu_puan_uyari_esik_csat ?? 2.5)));

            // Google yorumu ödülü (tıklayana kupon/puan)
            $gTip = in_array($request->google_odul_tipi, ['kupon','puan']) ? $request->google_odul_tipi : 'yok';
            $salon->google_odul_tipi                = $gTip;
            $salon->google_odul_kupon_indirim_tipi  = null;
            $salon->google_odul_kupon_deger         = null;
            $salon->google_odul_kupon_gecerlilik_gun= null;
            $salon->google_odul_puan                = null;
            $salon->google_odul_baslik              = null;
            if ($gTip === 'kupon') {
                $salon->google_odul_kupon_indirim_tipi   = $request->google_odul_kupon_indirim_tipi === 'tutar' ? 'tutar' : 'yuzde';
                $salon->google_odul_kupon_deger          = max(0, (float) ($request->google_odul_kupon_deger ?? 0));
                $gg = (int) ($request->google_odul_kupon_gecerlilik_gun ?? 0);
                $salon->google_odul_kupon_gecerlilik_gun = $gg > 0 ? $gg : null;
                $salon->google_odul_baslik               = trim((string) $request->google_odul_baslik) ?: null;
            } elseif ($gTip === 'puan') {
                $salon->google_odul_puan   = max(0, (float) ($request->google_odul_puan ?? 0));
                $salon->google_odul_baslik = trim((string) $request->google_odul_baslik) ?: null;
            }
            $salon->save();

            return response()->json([
                'basarili'   => true,
                'review_url' => $parsed['review_url'],
                'uyari'      => $parsed['uyari'] ?? null,
            ]);
        } catch(\Exception $e) {
            \Log::error('googleReviewKaydet hata: '.$e->getMessage());
            return response()->json(['basarili'=>false,'mesaj'=>$e->getMessage()]);
        }
    }

    public function googleYonlendirmeKaydet(Request $request){
        // Public endpoint — anket teşekkür sayfasından "Google'da Yorum Yaz" tıklanınca tracking
        try {
            $token = $request->token;
            $g = AnketGonderim::where('token', $token)->first();
            if ($g && !$g->google_yonlendirildi) {
                $g->google_yonlendirildi = true;
                $g->save();
            }
            return response()->json(['basarili'=>true]);
        } catch(\Exception $e) {
            return response()->json(['basarili'=>false]);
        }
    }

    public function sozlesmeOlustur(Request $request){
        if($r = self::yetkiYoksa403($request, 'form.gonder')) return $r;
        try {
            $this->dinamikFormKolonlariOlustur();
            $sube = self::mevcutsube($request);
            $userId = (int) $request->user_id;
            $cepTel = trim($request->cep_telefon);
            if(!$userId || !$cepTel){
                return response()->json(['basarili'=>false,'mesaj'=>'Müşteri ve cep telefon zorunlu.']);
            }
            $salonImza = (string) $request->salon_imza;
            if(strpos($salonImza,'data:') !== 0 || strlen($salonImza) < 500){
                return response()->json(['basarili'=>false,'mesaj'=>'Salon yetkilisi imzası zorunludur. Lütfen imza alanına imzanızı atın.']);
            }
            $kod = substr(str_shuffle('1234567890'),0,4);
            $arsiv = new Arsiv();
            $arsiv->user_id        = $userId;
            $arsiv->salon_id       = $sube;
            $arsiv->form_id        = 0;
            $arsiv->personel_id    = Personeller::where('salon_id',$sube)->where('yetkili_id',Auth::guard('isletmeyonetim')->user()->id)->value('id') ?: 0;
            $arsiv->dogrulama_kodu = $kod;
            $arsiv->is_sozlesme    = 1;
            $arsiv->hizmet_id      = $request->hizmet_id ?: null;
            $arsiv->paket_id       = $request->paket_id ?: null;
            $arsiv->seans_sayisi   = $request->seans_sayisi ?: null;
            $arsiv->toplam_ucret   = $request->toplam_ucret ?: 0;
            $arsiv->kapora         = $request->kapora ?: 0;
            $arsiv->sozlesme_notu  = $request->sozlesme_notu ?: null;
            $arsiv->sozlesme_metni = $request->sozlesme_metni ?: null;
            $arsiv->cevapladi      = false;
            // Odeme sekli / taksit plani (opsiyonel)
            $odemeSekli  = in_array($request->odeme_sekli, ['pesin','taksit','kredi_karti']) ? $request->odeme_sekli : 'pesin';
            $taksitSayisi = (int) $request->taksit_sayisi;
            $ilkTaksit   = $request->ilk_taksit_tarihi ?: null;
            $taksitTutari = $request->taksit_tutari !== null ? (float) str_replace(',', '.', $request->taksit_tutari) : null;
            $arsiv->odeme_sekli       = $odemeSekli;
            $arsiv->gecerlilik_tarihi = $request->gecerlilik_tarihi ?: null;
            if($odemeSekli === 'taksit' && $taksitSayisi >= 1){
                $plan = self::sozlesmeOdemePlaniUret((float)($request->toplam_ucret ?: 0), (float)($request->kapora ?: 0), $taksitSayisi, $taksitTutari, $ilkTaksit);
                $arsiv->taksit_sayisi     = $taksitSayisi;
                $arsiv->taksit_tutari     = $plan['taksit_tutari'];
                $arsiv->ilk_taksit_tarihi = $ilkTaksit;
                $arsiv->odeme_plani_json  = json_encode($plan['plan'], JSON_UNESCAPED_UNICODE);
            } else {
                $arsiv->taksit_sayisi     = null;
                $arsiv->taksit_tutari     = null;
                $arsiv->ilk_taksit_tarihi = null;
                $arsiv->odeme_plani_json  = null;
            }
            // Salon yetkilisi sozlesmeyi olusturma aninda panel uzerinden imzalar (cift tarafli imza)
            $arsiv->salon_imza            = $salonImza;
            $arsiv->salon_yetkili_ad      = trim((string)$request->salon_yetkili_ad) ?: null;
            $arsiv->salon_yetkili_telefon = trim((string)$request->salon_yetkili_telefon) ?: null;
            $arsiv->salon_imza_ip         = $request->ip();
            $arsiv->salon_imza_zaman      = now();
            $arsiv->cevapladi2            = true;
            $arsiv->harici_belge   = 'Hizmet Sözleşmesi';
            $arsiv->form_olusturan = Personeller::where('salon_id',$sube)->where('yetkili_id',Auth::guard('isletmeyonetim')->user()->id)->value('id');
            $arsiv->save();

            $link = 'https://'.$_SERVER['HTTP_HOST'].'/sozlesme/'.$arsiv->id.'/'.$arsiv->user_id;
            $mesaj = ' Hizmet Sözleşmenizi imzalamak için: '.$link.' | Onay Kodu: '.$kod;
            $mesajlar = [['to'=>$cepTel, 'message'=>$mesaj]];
            try {
                $this->sms_gonder_bildirimli($request, $mesajlar, true, 6, true);
            } catch(\Exception $e){
                \Log::error('Sözleşme SMS hatası: '.$e->getMessage());
            }
            return response()->json(['basarili'=>true,'arsiv_id'=>$arsiv->id]);
        } catch(\Exception $e){
            \Log::error('sozlesmeOlustur hata: '.$e->getMessage());
            return response()->json(['basarili'=>false,'mesaj'=>$e->getMessage()]);
        }
    }

    // Sozlesme taksit odeme plani uretir (kapora dusulmus kalan bakiyeyi taksitlere boler).
    // Yuvarlamadan kaynakli fark son taksite eklenir. Tarih verilmediyse tarihsiz plan doner.
    // Donus: ['taksit_tutari'=>float, 'plan'=>[['sira','tarih','tutar'], ...]]
    public static function sozlesmeOdemePlaniUret($toplam, $kapora, $taksitSayisi, $taksitTutari = null, $ilkTarih = null){
        $taksitSayisi = max(1, (int)$taksitSayisi);
        $kalan = round(max(0, (float)$toplam - (float)$kapora), 2);
        // Taksit tutari verilmediyse (ya da 0 ise) esit bol.
        $birim = ($taksitTutari && $taksitTutari > 0) ? round((float)$taksitTutari, 2) : round($kalan / $taksitSayisi, 2);
        $plan = [];
        $tarih = null;
        try { $tarih = $ilkTarih ? \Carbon\Carbon::parse($ilkTarih) : null; } catch(\Exception $e){ $tarih = null; }
        $toplananOncekiler = 0;
        for($i = 1; $i <= $taksitSayisi; $i++){
            // Son taksit: yuvarlama farkini kapatir (kalan - onceki taksitler toplami).
            $tutar = ($i === $taksitSayisi) ? round($kalan - $toplananOncekiler, 2) : $birim;
            if($tutar < 0) $tutar = 0;
            $toplananOncekiler = round($toplananOncekiler + $tutar, 2);
            $plan[] = [
                'sira'  => $i,
                'tarih' => $tarih ? $tarih->copy()->addMonths($i - 1)->format('Y-m-d') : null,
                'tutar' => $tutar,
            ];
        }
        return ['taksit_tutari' => $birim, 'plan' => $plan];
    }

    // Salon icin varsayilan sozlesme sartlari metnini kaydeder; bir defa girilir,
    // sonraki sozlesmelerde otomatik dolu gelir.
    public function sozlesmeVarsayilanKaydet(Request $request){
        if($r = self::yetkiYoksa403($request, 'form.gonder')) return $r;
        try {
            $this->dinamikFormKolonlariOlustur();
            $sube = self::mevcutsube($request);
            $metin = trim((string)$request->sozlesme_metni);
            \DB::table('salonlar')->where('id',$sube)->update(['sozlesme_varsayilan_metin'=>($metin !== '' ? $metin : null)]);
            return response()->json(['basarili'=>true]);
        } catch(\Exception $e){
            \Log::error('sozlesmeVarsayilanKaydet hata: '.$e->getMessage());
            return response()->json(['basarili'=>false,'mesaj'=>$e->getMessage()]);
        }
    }

    // ============================================================
    // PRIM & HAK EDIS RAPORU
    // ============================================================

    public function primRaporu(Request $request)
    {
        // Guard'a gore isletme listesi (satisortakligi'nde isletmeyonetim->user() null olur).
        if(Auth::guard('satisortakligi')->check()){
            $isletmeler = [15];
            $isletme = Salonlar::where('id',15)->first();
        } else {
            $isletmeler = Auth::guard('isletmeyonetim')->user()->yetkili_olunan_isletmeler->where('aktif',1)->pluck('salon_id')->toArray();
            $isletme = Salonlar::where('id',self::mevcutsube($request))->first();
        }

        if(!in_array(self::mevcutsube($request),$isletmeler)){
            return view('isletmeadmin.yetkisizerisim');
        }
        // Prim & Hak Edis ekrani: personel.prim_hakedis_gor zorunlu (Sekreter vb. ozel
        // yetkili hesaplar da dahil; personelmi() sadece rol-5'i engelliyordu).
        $_primAu = Auth::guard('isletmeyonetim')->user();
        if($_primAu && !\App\Services\PersonelYetkiServisi::yetkiliYetkiVar($_primAu->id, self::mevcutsube($request), 'personel.prim_hakedis_gor')){
            return view('isletmeadmin.yetkisizerisim');
        }
        if(str_contains(self::lisans_sure_kontrol($request),'-')){
            return view('isletmeadmin.lisanssurebitti',['isletme'=>$isletme]);
        }
        if(!Auth::guard('satisortakligi')->check() && self::personelmi($request)){
            return redirect()->route('isletmeadmin.randevular');
        }

        $yil = (int)($request->yil ?? date('Y'));
        $ay  = (int)($request->ay ?? date('n'));
        if($ay < 1 || $ay > 12) $ay = (int)date('n');
        $mod = $request->mod === 'gunluk' ? 'gunluk' : 'aylik';
        $gun = ($mod==='gunluk' && preg_match('/^\d{4}-\d{2}-\d{2}$/', (string)$request->gun)) ? $request->gun : date('Y-m-d');

        if($mod==='gunluk'){
            $tarih1 = $tarih2 = $gun;
            $rapor = $this->primHakedisVerisi($isletme->id, $tarih1, $tarih2, $gun);
        } else {
            $tarih1 = sprintf('%04d-%02d-01', $yil, $ay);
            $tarih2 = date('Y-m-t', strtotime($tarih1));
            $rapor = $this->primHakedisVerisi($isletme->id, $tarih1, $tarih2);
        }

        return view('isletmeadmin.primraporu', [
            'bildirimler'         => self::bildirimgetir($request),
            'sayfa_baslik'        => 'Prim & Hak Ediş',
            'pageindex'           => 402,
            'kalan_uyelik_suresi' => self::lisans_sure_kontrol($request),
            'yetkiliolunanisletmeler' => $isletmeler,
            'isletme'             => $isletme,
            'rapor'               => $rapor,
            'yil'                 => $yil,
            'ay'                  => $ay,
            'tarih1'              => $tarih1,
            'tarih2'              => $tarih2,
            'mod'                 => $mod,
            'gun'                 => $gun,
        ]);
    }

    /**
     * Detayli (kalem bazli) prim oranlarini salon icin haritalar.
     * Donus: [personel_id => ['hizmet'=>[kalem_id=>yuzde], 'urun'=>[...], 'paket'=>[...]]]
     * Oran bulunamayan kalem icin deger yoktur (cagiran taraf 0 varsayar).
     */
    private function detayliPrimHaritasi($salonId)
    {
        $harita = [];
        if (!\Schema::hasTable('personel_prim_oranlari')) return $harita;

        $satirlar = PersonelPrimOrani::where('salon_id', $salonId)->get();
        foreach ($satirlar as $s) {
            if (!isset($harita[$s->personel_id])) {
                $harita[$s->personel_id] = ['hizmet' => [], 'urun' => [], 'paket' => []];
            }
            if (isset($harita[$s->personel_id][$s->tur])) {
                $harita[$s->personel_id][$s->tur][$s->kalem_id] = (float)$s->yuzde;
            }
        }
        return $harita;
    }

    private function primHakedisVerisi($salonId, $tarih1, $tarih2, $primGun = null)
    {
        $personeller = Personeller::where('salon_id', $salonId)
            ->where('aktif', 1)
            ->where(function($q){ $q->where('arsivli',false)->orWhereNull('arsivli'); })
            ->orderBy('takvim_sirasi','asc')->get();

        // Tarih araligi: gun-kapsamli (00:00:00 - 23:59:59). adisyonlar.tarih datetime
        // olabildigi icin tek gun (gunluk mod) veya ay sonu kayiplarini onler.
        $tarihBas = substr($tarih1, 0, 10) . ' 00:00:00';
        $tarihBit = substr($tarih2, 0, 10) . ' 23:59:59';
        $adisyonlar = Adisyonlar::with([
                'hizmetler.personel','urunler.personel','paketler.personel',
            ])
            ->where('salon_id', $salonId)
            ->whereBetween('tarih',[$tarihBas,$tarihBit])
            ->get();

        // Personelleri ID ile mapla — yuzdeyi DAIMA Personeller objesinden direk al,
        // adisyon_hizmet'in eager-loaded personel ilişkisinden değil (lazy load veya eski cache riski yok).
        $primMap = [];
        $persById = [];
        foreach($personeller as $p){
            $persById[$p->id] = $p;
            $primMap[$p->id] = [
                'hizmet_geliri'=>0,'hizmet_primi'=>0,
                'urun_geliri'=>0,'urun_primi'=>0,
                'paket_geliri'=>0,'paket_primi'=>0,
            ];
        }

        // Detayli (kalem bazli) prim oranlari
        $detayHarita = $this->detayliPrimHaritasi($salonId);

        $hizmetItems = $adisyonlar->flatMap(fn($a)=>$a->hizmetler)->filter(fn($i)=>$i->personel_id);

        // PAKET satisi = randevu_id NULL (randevusuz) VE seans_sayisi > 0. Gelir de prim de
        // paket kovasina gider, duz paket_prim_yuzde ile. Randevudan gelen seans kullanimi
        // (randevu_id dolu) NORMAL hizmet sayilir.
        $paketMi = fn($i) => is_null($i->randevu_id) && (int)$i->seans_sayisi > 0;
        foreach($hizmetItems->groupBy('personel_id') as $pid => $items){
            if(!isset($primMap[$pid]) || !isset($persById[$pid])) continue;
            // Seansli (paket) ve normal hizmet kalemlerini ayir
            $normal  = $items->reject($paketMi)->values();
            $seansli = $items->filter($paketMi)->values();

            // --- Normal hizmet satislari ---
            if($normal->isNotEmpty()){
                $ids = $normal->pluck('id')->unique()->values();
                $kazanc = TahsilatHizmetler::whereIn('adisyon_hizmet_id', $ids)->sum('tutar');
                $primMap[$pid]['hizmet_geliri'] += (float)$kazanc;

                if(!empty($persById[$pid]->hizmet_prim_detayli)){
                    // Detayli: her hizmet_id grubu icin kendi orani
                    $oranlar = $detayHarita[$pid]['hizmet'] ?? [];
                    $prim = 0;
                    foreach($normal->groupBy('hizmet_id') as $hizmetId => $grup){
                        $gIds = $grup->pluck('id')->unique()->values();
                        $gKazanc = TahsilatHizmetler::whereIn('adisyon_hizmet_id', $gIds)->sum('tutar');
                        $gYuzde = (float)($oranlar[$hizmetId] ?? 0);
                        $prim += (float)$gKazanc * $gYuzde/100;
                    }
                    $primMap[$pid]['hizmet_primi'] += round($prim, 2);
                } else {
                    $yuzde = (float)($persById[$pid]->hizmet_prim_yuzde ?? 0);
                    $primMap[$pid]['hizmet_primi']  += round((float)$kazanc * $yuzde/100, 2);
                }
            }

            // --- Seansli hizmet satislari => PAKET (duz paket_prim_yuzde) ---
            if($seansli->isNotEmpty()){
                $ids = $seansli->pluck('id')->unique()->values();
                $kazanc = TahsilatHizmetler::whereIn('adisyon_hizmet_id', $ids)->sum('tutar');
                $primMap[$pid]['paket_geliri'] += (float)$kazanc;
                $yuzde = (float)($persById[$pid]->paket_prim_yuzde ?? 0);
                $primMap[$pid]['paket_primi']  += round((float)$kazanc * $yuzde/100, 2);
            }
        }

        $urunItems = $adisyonlar->flatMap(fn($a)=>$a->urunler)->filter(fn($i)=>$i->personel_id);
        foreach($urunItems->groupBy('personel_id') as $pid => $items){
            if(!isset($primMap[$pid]) || !isset($persById[$pid])) continue;
            $ids = $items->pluck('id')->unique()->values();
            $kazanc = TahsilatUrunler::whereIn('adisyon_urun_id', $ids)->sum('tutar');
            $primMap[$pid]['urun_geliri'] = (float)$kazanc;

            if(!empty($persById[$pid]->urun_prim_detayli)){
                $oranlar = $detayHarita[$pid]['urun'] ?? [];
                $prim = 0;
                foreach($items->groupBy('urun_id') as $urunId => $grup){
                    $gIds = $grup->pluck('id')->unique()->values();
                    $gKazanc = TahsilatUrunler::whereIn('adisyon_urun_id', $gIds)->sum('tutar');
                    $gYuzde = (float)($oranlar[$urunId] ?? 0);
                    $prim += (float)$gKazanc * $gYuzde/100;
                }
                $primMap[$pid]['urun_primi'] = round($prim, 2);
            } else {
                $yuzde = (float)($persById[$pid]->urun_prim_yuzde ?? 0);
                $primMap[$pid]['urun_primi']  = round((float)$kazanc * $yuzde/100, 2);
            }
        }

        $paketItems = $adisyonlar->flatMap(fn($a)=>$a->paketler)->filter(fn($i)=>$i->personel_id);
        foreach($paketItems->groupBy('personel_id') as $pid => $items){
            if(!isset($primMap[$pid]) || !isset($persById[$pid])) continue;
            $ids = $items->pluck('id')->unique()->values();
            $kazanc = TahsilatPaketler::whereIn('adisyon_paket_id', $ids)->sum('tutar');
            // += : seansli hizmetler yukarida paket kovasina eklenmis olabilir, uzerine yazma
            $primMap[$pid]['paket_geliri'] += (float)$kazanc;

            if(!empty($persById[$pid]->paket_prim_detayli)){
                $oranlar = $detayHarita[$pid]['paket'] ?? [];
                $prim = 0;
                foreach($items->groupBy('paket_id') as $paketId => $grup){
                    $gIds = $grup->pluck('id')->unique()->values();
                    $gKazanc = TahsilatPaketler::whereIn('adisyon_paket_id', $gIds)->sum('tutar');
                    $gYuzde = (float)($oranlar[$paketId] ?? 0);
                    $prim += (float)$gKazanc * $gYuzde/100;
                }
                $primMap[$pid]['paket_primi'] += round($prim, 2);
            } else {
                $yuzde = (float)($persById[$pid]->paket_prim_yuzde ?? 0);
                $primMap[$pid]['paket_primi']  += round((float)$kazanc * $yuzde/100, 2);
            }
        }

        $hareketler = PersonelPrimHareketi::where('salon_id',$salonId)
            ->whereBetween('tarih',[$tarih1,$tarih2])
            ->get()
            ->groupBy('personel_id');

        // Personel bazli PERSONEL GIDERI toplami (masraflar.personel_gideri=1):
        // personel kasadan aldigi tutar. Net hak edisten DUSULUR ve "Masraf" sutununda
        // gosterilir. Normal salon masraflari (personel_gideri=0) buraya girmez.
        // Tarih araligi gun-kapsamli.
        $masrafBas = substr($tarih1, 0, 10) . ' 00:00:00';
        $masrafBit = substr($tarih2, 0, 10) . ' 23:59:59';
        $masrafToplamlari = collect();
        if(\Schema::hasColumn('masraflar','personel_gideri')){
            $masrafToplamlari = \DB::table('masraflar')
                ->where('salon_id',$salonId)
                ->where('personel_gideri',1)
                ->whereNotNull('harcayan_id')
                ->whereBetween('tarih',[$masrafBas,$masrafBit])
                ->groupBy('harcayan_id')
                ->select('harcayan_id', \DB::raw('SUM(tutar) as toplam'))
                ->pluck('toplam','harcayan_id');
        }

        $donem = substr($tarih1, 0, 7);
        $odemelerGruplu = PersonelMaasOdemesi::where('salon_id',$salonId)
            ->where('donem',$donem)
            ->orderBy('odeme_tarihi','desc')
            ->orderBy('id','desc')
            ->get()
            ->groupBy('personel_id');

        // Gunluk prim modu: o gune ait odenmis prim toplamlari (prim_gun ile isaretli)
        $gunlukOdenenPrim = collect();
        if($primGun && \Schema::hasColumn('personel_maas_odemeleri','prim_gun')){
            $gunlukOdenenPrim = PersonelMaasOdemesi::where('salon_id',$salonId)
                ->where('odeme_tipi','prim')
                ->whereDate('prim_gun',$primGun)
                ->get()
                ->groupBy('personel_id');
        }

        $sonuc = [];
        foreach($personeller as $p){
            $primRow = $primMap[$p->id];
            $primToplam = $primRow['hizmet_primi'] + $primRow['urun_primi'] + $primRow['paket_primi'];

            $bonus = 0; $kesinti = 0;
            $persHareketler = $hareketler->get($p->id, collect());
            foreach($persHareketler as $h){
                if($h->tip === 'bonus') $bonus += (float)$h->tutar;
                else $kesinti += (float)$h->tutar;
            }

            // Personelin donem ici personel gideri toplami — NET'ten DUSULUR
            $masraf = (float)($masrafToplamlari[$p->id] ?? 0);

            $maas = (float)($p->maas ?? 0);
            $toplam = $maas + $primToplam + $bonus - $kesinti - $masraf;
            // Net eksiye duserse personel salona borclu demektir
            $borclu = $toplam < 0;

            $persOdemeler = $odemelerGruplu->get($p->id, collect());
            $odenenToplam = (float)$persOdemeler->sum('tutar');
            $odemeSayisi = $persOdemeler->count();

            // Tip bazli odenen miktarlar
            $odenenMaas = (float)$persOdemeler->where('odeme_tipi','maas')->sum('tutar');
            $odenenPrim = (float)$persOdemeler->where('odeme_tipi','prim')->sum('tutar');
            $odenenDiger = (float)$persOdemeler->whereNotIn('odeme_tipi',['maas','prim'])->sum('tutar');

            // Net etkili bonus/kesinti tutar (bonus ekler, kesinti dusurur)
            $bonusKesintiNet = $bonus - $kesinti;

            // Tip bazli kalan
            $kalanMaas = max(0, $maas - $odenenMaas);
            $kalanPrim = max(0, $primToplam - $odenenPrim);
            $kalanDiger = $bonusKesintiNet - $odenenDiger; // negatif olabilir
            $kalan = max(0, $toplam - $odenenToplam);

            $sonOdeme = $persOdemeler->first();

            if($toplam <= 0)                   $durum = 'tam'; // odenecek yok (0 ya da borclu)
            elseif($odenenToplam <= 0)         $durum = 'bekliyor';
            elseif($odenenToplam < $toplam)    $durum = 'kismi';
            elseif($odenenToplam == $toplam)   $durum = 'tam';
            else                               $durum = 'fazla';

            // === Gunluk prim modu alanlari ===
            // gun_prim = o gunun prim toplami; gun_odenen = o gune isaretli odenmis prim
            $gunPrim   = (float)$primToplam;
            $gunOdenen = (float)$gunlukOdenenPrim->get($p->id, collect())->sum('tutar');
            $gunKalan  = max(0, $gunPrim - $gunOdenen);
            if($gunPrim <= 0)               $gunDurum = 'bekliyor';
            elseif($gunOdenen <= 0)         $gunDurum = 'bekliyor';
            elseif($gunOdenen < $gunPrim)   $gunDurum = 'kismi';
            elseif($gunOdenen == $gunPrim)  $gunDurum = 'tam';
            else                            $gunDurum = 'fazla';

            $sonuc[] = [
                'personel_id'   => $p->id,
                'personel_adi'  => $p->personel_adi,
                'maas'          => $maas,
                'hizmet_primi'  => (float)$primRow['hizmet_primi'],
                'urun_primi'    => (float)$primRow['urun_primi'],
                'paket_primi'   => (float)$primRow['paket_primi'],
                'prim_toplam'   => (float)$primToplam,
                'bonus'         => (float)$bonus,
                'kesinti'       => (float)$kesinti,
                'masraf'        => (float)$masraf,
                'borclu'        => $borclu,
                'net_hakedis'   => (float)$toplam,
                'hizmet_geliri' => (float)$primRow['hizmet_geliri'],
                'urun_geliri'   => (float)$primRow['urun_geliri'],
                'paket_geliri'  => (float)$primRow['paket_geliri'],
                'hareket_sayisi'=> $persHareketler->count(),
                'durum'         => $durum,
                'odenen_toplam' => $odenenToplam,
                'odenen_maas'   => $odenenMaas,
                'odenen_prim'   => $odenenPrim,
                'odenen_diger'  => $odenenDiger,
                'kalan'         => (float)$kalan,
                'kalan_maas'    => (float)$kalanMaas,
                'kalan_prim'    => (float)$kalanPrim,
                'kalan_diger'   => (float)$kalanDiger,
                'odeme_sayisi'  => $odemeSayisi,
                'son_odeme_tarihi' => $sonOdeme ? optional($sonOdeme->odeme_tarihi)->format('Y-m-d') : null,
                // Gunluk prim modu
                'gun_prim'      => $gunPrim,
                'gun_odenen'    => $gunOdenen,
                'gun_kalan'     => $gunKalan,
                'gun_durum'     => $gunDurum,
            ];
        }

        return $sonuc;
    }

    public function primHareketEkle(Request $request)
    {
        if($r = self::yetkiYoksa403($request, 'personel.odeme_yap')) return $r;
        try{
            $salonId = self::mevcutsube($request);
            $personel = Personeller::where('id',$request->personel_id)->where('salon_id',$salonId)->first();
            if(!$personel){
                return response()->json(['basarili'=>false,'mesaj'=>'Personel bulunamadı.']);
            }

            $tip = $request->tip === 'kesinti' ? 'kesinti' : 'bonus';
            $tutar = (float)str_replace([','], ['.'], $request->tutar);
            if($tutar <= 0){
                return response()->json(['basarili'=>false,'mesaj'=>'Tutar 0\'dan büyük olmalı.']);
            }

            $tarih = $request->tarih ?: date('Y-m-d');
            if(!preg_match('/^\d{4}-\d{2}-\d{2}$/', $tarih)) $tarih = date('Y-m-d');

            PersonelPrimHareketi::create([
                'personel_id'       => $personel->id,
                'salon_id'          => $salonId,
                'tarih'             => $tarih,
                'tip'               => $tip,
                'tutar'             => $tutar,
                'aciklama'          => mb_substr((string)$request->aciklama, 0, 300),
                'ekleyen_yetkili_id'=> Auth::guard('isletmeyonetim')->user()->id ?? null,
            ]);

            return response()->json(['basarili'=>true]);
        } catch(\Exception $e){
            return response()->json(['basarili'=>false,'mesaj'=>$e->getMessage()]);
        }
    }

    public function primHareketSil(Request $request)
    {
        if($r = self::yetkiYoksa403($request, 'personel.odeme_yap')) return $r;
        try{
            $salonId = self::mevcutsube($request);
            $hareket = PersonelPrimHareketi::where('id',$request->id)->where('salon_id',$salonId)->first();
            if(!$hareket){
                return response()->json(['basarili'=>false,'mesaj'=>'Kayıt bulunamadı.']);
            }
            $hareket->delete();
            return response()->json(['basarili'=>true]);
        } catch(\Exception $e){
            return response()->json(['basarili'=>false,'mesaj'=>$e->getMessage()]);
        }
    }

    public function primHareketListesi(Request $request)
    {
        if($r = self::yetkiYoksa403($request, 'personel.prim_hakedis_gor')) return $r;
        $salonId = self::mevcutsube($request);
        $personelId = (int)$request->personel_id;
        $tarih1 = $request->tarih1 ?: date('Y-m-01');
        $tarih2 = $request->tarih2 ?: date('Y-m-t');
        $donem = substr($tarih1, 0, 7);

        $hareketler = PersonelPrimHareketi::where('salon_id',$salonId)
            ->where('personel_id',$personelId)
            ->whereBetween('tarih',[$tarih1,$tarih2])
            ->orderBy('tarih','desc')
            ->orderBy('id','desc')
            ->get();

        $odemeler = PersonelMaasOdemesi::where('salon_id',$salonId)
            ->where('personel_id',$personelId)
            ->where('donem',$donem)
            ->orderBy('odeme_tarihi','desc')
            ->orderBy('id','desc')
            ->get()
            ->map(function($o){
                return [
                    'id'            => $o->id,
                    'tarih'         => optional($o->odeme_tarihi)->format('Y-m-d'),
                    'tutar'         => (float)$o->tutar,
                    'odeme_yontemi' => $o->odeme_yontemi,
                    'aciklama'      => $o->aciklama,
                ];
            });

        return response()->json([
            'basarili'  => true,
            'hareketler'=> $hareketler,
            'odemeler'  => $odemeler,
        ]);
    }

    public function primOde(Request $request)
    {
        if($r = self::yetkiYoksa403($request, 'personel.odeme_yap')) return $r;
        try{
            $salonId = self::mevcutsube($request);
            $personel = Personeller::where('id',$request->personel_id)->where('salon_id',$salonId)->first();
            if(!$personel){
                return response()->json(['basarili'=>false,'mesaj'=>'Personel bulunamadı.']);
            }

            $donem = $request->donem;
            if(!preg_match('/^\d{4}-\d{2}$/', $donem)){
                return response()->json(['basarili'=>false,'mesaj'=>'Geçersiz dönem.']);
            }

            $tutar = (float)str_replace([','], ['.'], $request->tutar);
            if($tutar <= 0){
                return response()->json(['basarili'=>false,'mesaj'=>'Tutar 0\'dan büyük olmalı.']);
            }

            $odemeTarihi = $request->odeme_tarihi ?: date('Y-m-d');
            if(!preg_match('/^\d{4}-\d{2}-\d{2}$/', $odemeTarihi)) $odemeTarihi = date('Y-m-d');

            // Odeme tipi: maas | prim | diger (default: diger)
            $odemeTipi = in_array($request->odeme_tipi, ['maas','prim','diger']) ? $request->odeme_tipi : 'diger';

            // Gunluk prim odemesi: hangi gune ait oldugunu isaretle (opsiyonel)
            $primGun = null;
            if($odemeTipi==='prim' && preg_match('/^\d{4}-\d{2}-\d{2}$/', (string)$request->prim_gun)){
                $primGun = $request->prim_gun;
            }

            // Coklu odeme destegi: her zaman yeni kayit ekle
            $odemeVerisi = [
                'personel_id'        => $personel->id,
                'salon_id'           => $salonId,
                'donem'              => $donem,
                'tutar'              => $tutar,
                'odeme_tipi'         => $odemeTipi,
                'odeme_tarihi'       => $odemeTarihi,
                'odeme_yontemi'      => mb_substr((string)$request->odeme_yontemi, 0, 60),
                'aciklama'           => mb_substr((string)$request->aciklama, 0, 300),
                'ekleyen_yetkili_id' => Auth::guard('isletmeyonetim')->user()->id ?? null,
            ];
            if($primGun && \Schema::hasColumn('personel_maas_odemeleri','prim_gun')){
                $odemeVerisi['prim_gun'] = $primGun;
            }
            $pmo = PersonelMaasOdemesi::create($odemeVerisi);

            // === OTOMATIK KASA/MASRAF KAYDI ===
            // Personel ödemesi yapılınca kasa raporuna gider olarak da yazılır.
            // Salon sahibi tek yerden girer, sistem her iki tabloya da kaydeder.
            try {
                $kategori = MasrafKategorisi::firstOrCreate(
                    ['kategori' => 'Personel Ödemeleri']
                );
                // Ödeme tipi -> Türkçe açıklama (kasa raporundaki "Açıklama"
                // kolonunda görünür, salon sahibi ne ödemesi olduğunu görsün).
                $tipMap = [
                    'maas'  => 'Maaş Ödemesi',
                    'prim'  => 'Prim Ödemesi',
                    'diger' => 'Avans/Bonus',
                ];
                $tipText = isset($tipMap[$odemeTipi]) ? $tipMap[$odemeTipi] : 'Personel Ödemesi';

                $masraf = new Masraflar();
                $masraf->personel_maas_odemesi_id = $pmo->id;
                $masraf->salon_id            = $salonId;
                $masraf->harcayan_id         = $personel->id;
                $masraf->masraf_kategori_id  = $kategori->id;
                $masraf->tarih               = $odemeTarihi;
                $masraf->tutar               = $tutar;
                $masraf->odeme_yontemi_id    = (int)($request->odeme_yontemi_id ?? 1);
                $masraf->aciklama            = $tipText . ' (' . $donem . ')' .
                    ($request->aciklama ? ' — ' . mb_substr((string)$request->aciklama, 0, 80) : '');
                $masraf->notlar              = "Personel: " . ($personel->personel_adi ?? '') .
                    " — " . ucfirst($odemeTipi) . " ($donem)";
                $masraf->save();
            } catch (\Exception $e) {
                // Kasa kaydı hata verse bile personel ödemesi başarılı sayılır.
                // (loglara yazılır ama kullanıcıya bildirilmez)
                \Log::warning('Personel ödemesi otomatik masraf kaydı başarısız: ' . $e->getMessage());
            }

            return response()->json(['basarili'=>true]);
        } catch(\Exception $e){
            return response()->json(['basarili'=>false,'mesaj'=>$e->getMessage()]);
        }
    }

    public function personelPrimDetayi(Request $request)
    {
        if($r = self::yetkiYoksa403($request, 'personel.prim_hakedis_gor')) return $r;
        try {
            $salonId = self::mevcutsube($request);
            $personelId = (int)$request->personel_id;
            $donem = $request->donem ?: date('Y-m');
            if(!preg_match('/^\d{4}-\d{2}$/', $donem)) $donem = date('Y-m');
            $tarih1 = $donem.'-01';
            $tarih2 = date('Y-m-t', strtotime($tarih1));

            $personel = Personeller::where('id',$personelId)->where('salon_id',$salonId)->first();
            if(!$personel){
                return response()->json(['basarili'=>false,'mesaj'=>'Personel bulunamadı.']);
            }

            $hizmetYuzde = (float)($personel->hizmet_prim_yuzde ?? 0);
            $urunYuzde   = (float)($personel->urun_prim_yuzde ?? 0);
            $paketYuzde  = (float)($personel->paket_prim_yuzde ?? 0);

            // Detayli (kalem bazli) prim oranlari + flag'ler
            $hizmetDetayli = !empty($personel->hizmet_prim_detayli);
            $urunDetayli   = !empty($personel->urun_prim_detayli);
            $paketDetayli  = !empty($personel->paket_prim_detayli);
            $detayHarita   = $this->detayliPrimHaritasi($salonId);
            $detayOranlar  = $detayHarita[$personelId] ?? ['hizmet'=>[],'urun'=>[],'paket'=>[]];

            // Bu personelin yer aldigi adisyonlar (tarih araliginda)
            $adisyonlar = Adisyonlar::with([
                    'hizmetler.personel','hizmetler.hizmet',
                    'urunler.personel','urunler.urun',
                    'paketler.personel','paketler.paket',
                    'musteri',
                ])
                ->where('salon_id', $salonId)
                // Ana rapor (primHakedisVerisi) ile ayni gun-kapsamli aralik:
                // adisyonlar.tarih datetime olabilir; ay sonu kayiplarini onler.
                ->whereBetween('tarih',[substr($tarih1,0,10).' 00:00:00', substr($tarih2,0,10).' 23:59:59'])
                ->get();

            $hizmetSatislari = [];
            $urunSatislari = [];
            $paketSatislari = [];
            $musteriOzeti = [];

            $musteriEkle = function($musteriId, $musteriAdi, $tutar, $primTutar) use(&$musteriOzeti){
                if(!$musteriId) $musteriId = 'misafir-'.($musteriAdi ?: 'X');
                if(!isset($musteriOzeti[$musteriId])){
                    $musteriOzeti[$musteriId] = [
                        'musteri_id' => $musteriId,
                        'musteri_adi'=> $musteriAdi ?: 'Misafir',
                        'islem_sayisi'=> 0,
                        'toplam_tutar'=> 0,
                        'toplam_prim' => 0,
                    ];
                }
                $musteriOzeti[$musteriId]['islem_sayisi']++;
                $musteriOzeti[$musteriId]['toplam_tutar'] += (float)$tutar;
                $musteriOzeti[$musteriId]['toplam_prim']  += (float)$primTutar;
            };

            foreach($adisyonlar as $a){
                $musteriId  = $a->musteri_id;
                $musteriAdi = optional($a->musteri)->name ?? ($a->misafir_adi ?? 'Misafir');
                $tarih      = $a->tarih;

                foreach(($a->hizmetler ?? []) as $h){
                    if(!$h->personel || $h->personel->id != $personelId) continue;
                    $tahsilEdilen = (float)TahsilatHizmetler::where('adisyon_hizmet_id',$h->id)->sum('tutar');

                    // PAKET satisi (randevu_id NULL VE seans_sayisi>0) = ana rapor ile ayni
                    // sekilde duz paket_prim_yuzde uygulanir ve PAKET listesine yazilir.
                    // Randevudan gelen seans kullanimi (randevu_id dolu) NORMAL hizmettir.
                    if(is_null($h->randevu_id) && (int)$h->seans_sayisi > 0){
                        $primTutar = $tahsilEdilen * $paketYuzde / 100;
                        $paketSatislari[] = [
                            'tarih'        => $tarih,
                            'musteri_adi'  => $musteriAdi,
                            'urun'         => optional($h->hizmet)->hizmet_adi ?? '—',
                            'fiyat'        => (float)$h->fiyat,
                            'tahsil_edilen'=> $tahsilEdilen,
                            'prim_yuzdesi' => $paketYuzde,
                            'prim_tutari'  => $primTutar,
                        ];
                        $musteriEkle($musteriId, $musteriAdi, $tahsilEdilen, $primTutar);
                        continue;
                    }

                    $satirYuzde   = $hizmetDetayli ? (float)($detayOranlar['hizmet'][$h->hizmet_id] ?? 0) : $hizmetYuzde;
                    $primTutar    = $tahsilEdilen * $satirYuzde / 100;
                    $hizmetSatislari[] = [
                        'tarih'        => $tarih,
                        'musteri_adi'  => $musteriAdi,
                        'urun'         => optional($h->hizmet)->hizmet_adi ?? '—',
                        'fiyat'        => (float)$h->fiyat,
                        'tahsil_edilen'=> $tahsilEdilen,
                        'prim_yuzdesi' => $satirYuzde,
                        'prim_tutari'  => $primTutar,
                    ];
                    $musteriEkle($musteriId, $musteriAdi, $tahsilEdilen, $primTutar);
                }
                foreach(($a->urunler ?? []) as $u){
                    if(!$u->personel || $u->personel->id != $personelId) continue;
                    $tahsilEdilen = (float)TahsilatUrunler::where('adisyon_urun_id',$u->id)->sum('tutar');
                    $satirYuzde   = $urunDetayli ? (float)($detayOranlar['urun'][$u->urun_id] ?? 0) : $urunYuzde;
                    $primTutar    = $tahsilEdilen * $satirYuzde / 100;
                    $urunSatislari[] = [
                        'tarih'        => $tarih,
                        'musteri_adi'  => $musteriAdi,
                        'urun'         => optional($u->urun)->urun_adi ?? '—',
                        'fiyat'        => (float)$u->fiyat,
                        'tahsil_edilen'=> $tahsilEdilen,
                        'prim_yuzdesi' => $satirYuzde,
                        'prim_tutari'  => $primTutar,
                    ];
                    $musteriEkle($musteriId, $musteriAdi, $tahsilEdilen, $primTutar);
                }
                foreach(($a->paketler ?? []) as $pk){
                    if(!$pk->personel || $pk->personel->id != $personelId) continue;
                    $tahsilEdilen = (float)TahsilatPaketler::where('adisyon_paket_id',$pk->id)->sum('tutar');
                    $satirYuzde   = $paketDetayli ? (float)($detayOranlar['paket'][$pk->paket_id] ?? 0) : $paketYuzde;
                    $primTutar    = $tahsilEdilen * $satirYuzde / 100;
                    $paketSatislari[] = [
                        'tarih'        => $tarih,
                        'musteri_adi'  => $musteriAdi,
                        'urun'         => optional($pk->paket)->paket_adi ?? '—',
                        'fiyat'        => (float)$pk->fiyat,
                        'tahsil_edilen'=> $tahsilEdilen,
                        'prim_yuzdesi' => $satirYuzde,
                        'prim_tutari'  => $primTutar,
                    ];
                    $musteriEkle($musteriId, $musteriAdi, $tahsilEdilen, $primTutar);
                }
            }

            // Tarihe gore yeniden sirala (en yeni en ustte)
            $sortByTarih = function($a,$b){ return strcmp($b['tarih'],$a['tarih']); };
            usort($hizmetSatislari, $sortByTarih);
            usort($urunSatislari,   $sortByTarih);
            usort($paketSatislari,  $sortByTarih);
            $musteriList = array_values($musteriOzeti);
            usort($musteriList, function($a,$b){ return $b['toplam_prim'] <=> $a['toplam_prim']; });

            return response()->json([
                'basarili' => true,
                'personel_adi' => $personel->personel_adi,
                'donem' => $donem,
                'oranlar' => [
                    'hizmet' => $hizmetYuzde,
                    'urun'   => $urunYuzde,
                    'paket'  => $paketYuzde,
                ],
                'hizmet_satislari' => $hizmetSatislari,
                'urun_satislari'   => $urunSatislari,
                'paket_satislari'  => $paketSatislari,
                'musteriler'       => $musteriList,
                'ozet' => [
                    'hizmet_count' => count($hizmetSatislari),
                    'urun_count'   => count($urunSatislari),
                    'paket_count'  => count($paketSatislari),
                    'hizmet_prim'  => array_sum(array_column($hizmetSatislari,'prim_tutari')),
                    'urun_prim'    => array_sum(array_column($urunSatislari,'prim_tutari')),
                    'paket_prim'   => array_sum(array_column($paketSatislari,'prim_tutari')),
                    'musteri_sayisi' => count($musteriList),
                ],
            ]);
        } catch(\Exception $e){
            \Log::warning('personelPrimDetayi: '.$e->getMessage());
            return response()->json(['basarili'=>false,'mesaj'=>$e->getMessage()]);
        }
    }

    public function primOdemeListesi(Request $request)
    {
        if($r = self::yetkiYoksa403($request, 'personel.prim_hakedis_gor')) return $r;
        $salonId = self::mevcutsube($request);
        $personelId = (int)$request->personel_id;
        $donem = $request->donem ?: date('Y-m');
        if(!preg_match('/^\d{4}-\d{2}$/', $donem)) $donem = date('Y-m');
        $tarih1 = $donem.'-01';
        $tarih2 = date('Y-m-t', strtotime($tarih1));

        $odemeler = PersonelMaasOdemesi::where('salon_id',$salonId)
            ->where('personel_id',$personelId)
            ->where('donem',$donem)
            ->orderBy('odeme_tarihi','desc')
            ->orderBy('id','desc')
            ->get()
            ->map(function($o){
                $tip = $o->odeme_tipi ?: 'diger';
                if(!in_array($tip, ['maas','prim','diger'])) $tip = 'diger';
                return [
                    'id'            => $o->id,
                    'odeme_tarihi'  => $o->odeme_tarihi ? (is_string($o->odeme_tarihi) ? $o->odeme_tarihi : $o->odeme_tarihi->format('Y-m-d')) : null,
                    'tutar'         => (float)$o->tutar,
                    'odeme_tipi'    => $tip,
                    'odeme_yontemi' => $o->odeme_yontemi,
                    'aciklama'      => $o->aciklama,
                ];
            });

        // Ayni donemdeki bonus/kesinti hareketleri
        $hareketler = PersonelPrimHareketi::where('salon_id',$salonId)
            ->where('personel_id',$personelId)
            ->whereBetween('tarih',[$tarih1,$tarih2])
            ->orderBy('tarih','desc')
            ->orderBy('id','desc')
            ->get()
            ->map(function($h){
                return [
                    'id'       => $h->id,
                    'tarih'    => $h->tarih ? (is_string($h->tarih) ? substr($h->tarih,0,10) : $h->tarih->format('Y-m-d')) : null,
                    'tip'      => $h->tip,
                    'tutar'    => (float)$h->tutar,
                    'aciklama' => $h->aciklama,
                ];
            });

        $toplamlar = [
            'maas'    => (float)$odemeler->where('odeme_tipi','maas')->sum('tutar'),
            'prim'    => (float)$odemeler->where('odeme_tipi','prim')->sum('tutar'),
            'diger'   => (float)$odemeler->where('odeme_tipi','diger')->sum('tutar'),
            'bonus'   => (float)$hareketler->where('tip','bonus')->sum('tutar'),
            'kesinti' => (float)$hareketler->where('tip','kesinti')->sum('tutar'),
        ];
        $toplam = (float)$odemeler->sum('tutar');

        return response()->json([
            'basarili'      => true,
            'odemeler'      => $odemeler,
            'hareketler'    => $hareketler,
            'odenen_toplam' => $toplam,
            'odeme_sayisi'  => $odemeler->count(),
            'toplamlar'     => $toplamlar,
        ]);
    }

    public function primOdemeSil(Request $request)
    {
        if($r = self::yetkiYoksa403($request, 'personel.odeme_yap')) return $r;
        try{
            $salonId = self::mevcutsube($request);
            $kayit = PersonelMaasOdemesi::where('id',$request->id)->where('salon_id',$salonId)->first();
            if(!$kayit){
                return response()->json(['basarili'=>false,'mesaj'=>'Ödeme kaydı bulunamadı.']);
            }

            // Bağlı kasa/masraf kaydını da sil (otomatik oluşturulduysa)
            try {
                Masraflar::where('personel_maas_odemesi_id', $kayit->id)
                    ->where('salon_id', $salonId)
                    ->delete();
            } catch (\Exception $e) {
                \Log::warning('Personel ödemesi silinirken bağlı masraf kaydı silinemedi: ' . $e->getMessage());
            }

            $kayit->delete();
            return response()->json(['basarili'=>true]);
        } catch(\Exception $e){
            return response()->json(['basarili'=>false,'mesaj'=>$e->getMessage()]);
        }
    }

    /* ============================================================
     * LOG HAREKETLERİ (Aktivite Log)
     * ============================================================ */
    public function logHareketleri(Request $request)
    {
        // Self-heal: salon_aktivite_log tablosu yoksa olustur (migration kosulmamis olabilir)
        if (!\Schema::hasTable('salon_aktivite_log')) {
            try {
                \Schema::create('salon_aktivite_log', function ($table) {
                    $table->bigIncrements('id');
                    $table->unsignedInteger('salon_id');
                    $table->unsignedInteger('user_id')->nullable();
                    $table->string('user_type', 30)->nullable();
                    $table->string('user_name', 150)->nullable();
                    $table->string('user_rol', 80)->nullable();
                    $table->string('action', 80);
                    $table->string('target_type', 80)->nullable();
                    $table->unsignedBigInteger('target_id')->nullable();
                    $table->string('target_label', 220)->nullable();
                    $table->text('aciklama')->nullable();
                    $table->text('meta')->nullable();
                    $table->string('ip', 45)->nullable();
                    $table->string('user_agent', 255)->nullable();
                    $table->timestamps();
                    $table->index(['salon_id', 'created_at'], 'idx_salon_created');
                    $table->index('action', 'idx_action');
                    $table->index(['salon_id', 'user_id'], 'idx_salon_user');
                });
                $migName = '2026_04_26_000001_create_salon_aktivite_log_table';
                if (!DB::table('migrations')->where('migration', $migName)->count()) {
                    $batch = (int) DB::table('migrations')->max('batch');
                    DB::table('migrations')->insert(['migration' => $migName, 'batch' => $batch ?: 1]);
                }
            } catch (\Exception $e) {}
        }

        $isletmeler = '';
        $isletme = '';
        if (Auth::guard('satisortakligi')->check()) {
            $isletmeler = [15];
            $isletme = Salonlar::where('id', 15)->first();
        } else {
            $isletmeler = Auth::guard('isletmeyonetim')->user()->yetkili_olunan_isletmeler->where('aktif', 1)->pluck('salon_id')->toArray();
            $isletme = Salonlar::where('id', self::mevcutsube($request))->first();
        }

        if (!in_array(self::mevcutsube($request), $isletmeler) || $_SERVER['HTTP_HOST'] == 'randevu.randevumcepte.com.tr') {
            return view('isletmeadmin.yetkisizerisim');
        }
        if (str_contains(self::lisans_sure_kontrol($request), '-')) {
            return view('isletmeadmin.lisanssurebitti', ['isletme' => $isletme]);
        }
        // Sadece Hesap Sahibi (rol_id=1) ve rol atamasi olmayan yetkililer logu gorebilir.
        // role_id=4 (Yonetici) ve role_id=5 (Personel) icin yetkisiz.
        if (!Auth::guard('satisortakligi')->check()) {
            $userId = Auth::guard('isletmeyonetim')->user()->id;
            $kisitliRol = DB::table('model_has_roles')
                ->whereIn('role_id', [4, 5])
                ->where('model_id', $userId)
                ->where('salon_id', $isletme->id)
                ->count();
            if ($kisitliRol > 0) {
                return view('isletmeadmin.yetkisizerisim');
            }
        }

        $salonId = $isletme->id;
        $q = trim($request->get('q', ''));
        $action = $request->get('action');
        $userId = $request->get('user_id');
        $tarih = $request->get('tarih');

        $query = SalonAktiviteLog::where('salon_id', $salonId)->orderBy('id', 'desc');
        if ($q !== '') {
            $query->where(function ($w) use ($q) {
                $w->where('target_label', 'like', "%$q%")
                  ->orWhere('aciklama', 'like', "%$q%")
                  ->orWhere('user_name', 'like', "%$q%");
            });
        }
        if ($action) $query->where('action', $action);
        if ($userId) $query->where('user_id', $userId);
        if ($tarih) $query->whereDate('created_at', $tarih);

        $loglar = $query->paginate(50)->appends($request->all());

        $kullanicilar = SalonAktiviteLog::where('salon_id', $salonId)
            ->whereNotNull('user_id')
            ->select('user_id', 'user_name')
            ->groupBy('user_id', 'user_name')
            ->orderBy('user_name')
            ->get();

        $aksiyonlar = SalonAktiviteLog::where('salon_id', $salonId)
            ->distinct()->pluck('action')->filter()->values();

        return view('isletmeadmin.log-hareketleri', [
            'sayfa_baslik' => 'Log Hareketleri',
            'title'        => 'Log Hareketleri | '.($isletme->salon_adi ?? '').' İşletme Yönetim Paneli',
            'bildirimler'  => self::bildirimgetir($request),
            'kalan_uyelik_suresi' => self::lisans_sure_kontrol($request),
            'urun_drop'    => self::urundropliste($request),
            'yetkiliolunanisletmeler' => $isletmeler,
            'isletme'      => $isletme,
            'loglar'       => $loglar,
            'kullanicilar' => $kullanicilar,
            'aksiyonlar'   => $aksiyonlar,
            'q'            => $q,
            'action'       => $action,
            'user_id'      => $userId,
            'tarih'        => $tarih,
            'pageindex'    => 999,
        ]);
    }

    /**
     * Firebase Messaging service worker — config env'den render edilir.
     * Browser /firebase-messaging-sw.js'yi root scope'tan register eder.
     */
    public function firebaseMessagingSw()
    {
        $cfg = config('firebase_web');
        $initJson = json_encode([
            'apiKey'            => $cfg['apiKey'],
            'authDomain'        => $cfg['authDomain'],
            'projectId'         => $cfg['projectId'],
            'storageBucket'     => $cfg['storageBucket'],
            'messagingSenderId' => $cfg['messagingSenderId'],
            'appId'             => $cfg['appId'],
        ]);
        $js = "importScripts('https://www.gstatic.com/firebasejs/10.13.2/firebase-app-compat.js');\n"
            . "importScripts('https://www.gstatic.com/firebasejs/10.13.2/firebase-messaging-compat.js');\n"
            . "firebase.initializeApp({$initJson});\n"
            . "const messaging = firebase.messaging();\n"
            . "messaging.onBackgroundMessage(function(payload){\n"
            . "  const title = (payload.notification && payload.notification.title) || 'Randevumcepte';\n"
            . "  const body  = (payload.notification && payload.notification.body)  || '';\n"
            . "  const icon  = (payload.notification && payload.notification.icon)  || '/public/img/logo.png';\n"
            . "  self.registration.showNotification(title, { body: body, icon: icon, data: payload.data || {} });\n"
            . "});\n";
        return response($js, 200, [
            'Content-Type'           => 'application/javascript; charset=utf-8',
            'Service-Worker-Allowed' => '/',
            'Cache-Control'          => 'no-cache',
        ]);
    }

    /**
     * Tarayicidan gelen FCM token'i BildirimKimlikleri'ne yazar.
     * auth:isletmeyonetim guard'i ile yetkili oturumlu olmali.
     */
    public function bildirimCihazKaydet(Request $request)
    {
        $token = $request->input('token');
        if (empty($token) || strlen($token) < 20) {
            return response()->json(['ok' => false, 'error' => 'token gecersiz'], 422);
        }
        $yetkiliId = Auth::guard('isletmeyonetim')->id();
        if (!$yetkiliId) {
            return response()->json(['ok' => false, 'error' => 'oturum yok'], 401);
        }
        $salonId = (int) $request->input('salon_id');
        // Personeller.yetkili_id -> Personeller.id donusumu (BildirimKimlikleri.isletme_yetkili_id = Personeller.id)
        $personelId = Personeller::where('yetkili_id', $yetkiliId)
            ->when($salonId, function($q) use($salonId){ $q->where('salon_id', $salonId); })
            ->value('id');
        if (!$personelId) {
            $personelId = Personeller::where('yetkili_id', $yetkiliId)->value('id');
        }
        if (!$personelId) {
            return response()->json(['ok' => false, 'error' => 'personel kaydi bulunamadi'], 404);
        }

        $cihaz    = substr((string)$request->input('cihaz', ''), 0, 64);
        $tarayici = substr((string)$request->input('tarayici', ''), 0, 64);
        if ($cihaz === '') $cihaz = null;

        // 1) Ayni (yetkili, cihaz) icin eski tokenlar gecersizdir; sil
        if ($cihaz) {
            BildirimKimlikleri::where('isletme_yetkili_id', $personelId)
                ->where('cihaz', $cihaz)
                ->where('bildirim_id', '!=', $token)
                ->delete();
        }

        // 2) Bu token icin mevcut satir varsa onu kullan, yoksa diger sahipleri sil
        $row = BildirimKimlikleri::where('bildirim_id', $token)->first();
        if ($row) {
            BildirimKimlikleri::where('bildirim_id', $token)
                ->where('id', '!=', $row->id)->delete();
        } else {
            $row = new BildirimKimlikleri();
        }

        $row->isletme_yetkili_id = $personelId;
        $row->bildirim_id        = $token;
        if (Schema::hasColumn('bildirim_kimlikleri', 'cihaz') && $cihaz)         $row->cihaz = $cihaz;
        if (Schema::hasColumn('bildirim_kimlikleri', 'app_bundle') && $tarayici) $row->app_bundle = $tarayici;
        if (Schema::hasColumn('bildirim_kimlikleri', 'platform'))                $row->platform = 'web';
        if (Schema::hasColumn('bildirim_kimlikleri', 'token_tipi'))              $row->token_tipi = 'fcm';
        if (Schema::hasColumn('bildirim_kimlikleri', 'kullanici_tipi'))          $row->kullanici_tipi = 'yetkili';
        if (Schema::hasColumn('bildirim_kimlikleri', 'aktif'))                   $row->aktif = 1;
        if (Schema::hasColumn('bildirim_kimlikleri', 'gonderim_hatalari'))       $row->gonderim_hatalari = 0;
        $row->save();

        return response()->json(['ok' => true, 'id' => $row->id]);
    }

    // ============================================================
    // FATURA ISARETLEME / FATURASIZ GIZLE (gizli muhasebe modu)
    // ============================================================

    /**
     * Sadece hesap sahibi (role_id=1) icin: belirli bir adisyonun
     * fatura/fis durumunu toggle eder.
     */
    public function adisyonFaturaIsaretle(Request $request)
    {
        $sube = self::mevcutsube($request);
        $rol = Personeller::where('salon_id', $sube)
            ->where('yetkili_id', Auth::guard('isletmeyonetim')->user()->id)
            ->value('role_id');
        if ((int) $rol !== 1) {
            return response()->json(['ok' => false], 403);
        }
        $adisyon = Adisyonlar::where('id', $request->adisyon_id)
            ->where('salon_id', $sube)
            ->first();
        if (!$adisyon) {
            return response()->json(['ok' => false], 404);
        }
        $personelId = Personeller::where('salon_id', $sube)
            ->where('yetkili_id', Auth::guard('isletmeyonetim')->user()->id)
            ->value('id');
        $yeniDurum = !((bool) $adisyon->fatura_kesildi);
        $adisyon->fatura_kesildi = $yeniDurum;
        $adisyon->fatura_kesildi_tarihi = $yeniDurum ? now() : null;
        $adisyon->fatura_kesen_personel_id = $yeniDurum ? $personelId : null;
        $adisyon->save();
        return response()->json(['ok' => true, 'fatura_kesildi' => $yeniDurum ? 1 : 0]);
    }

    /**
     * Sadece hesap sahibi (role_id=1) icin: salon-wide faturasiz gizle
     * toggle'ini flip eder. Aktifken sistem genelinde faturasiz adisyonlar
     * tum listelerde + tum toplamlarda gizlenir.
     */
    public function faturasizGizleToggle(Request $request)
    {
        $sube = self::mevcutsube($request);
        $rol = Personeller::where('salon_id', $sube)
            ->where('yetkili_id', Auth::guard('isletmeyonetim')->user()->id)
            ->value('role_id');
        if ((int) $rol !== 1) {
            return response()->json(['ok' => false], 403);
        }
        $salon = Salonlar::where('id', $sube)->first();
        if (!$salon) return response()->json(['ok' => false], 404);
        $salon->faturasiz_gizle = !((bool) $salon->faturasiz_gizle);
        $salon->save();
        return response()->json(['ok' => true, 'faturasiz_gizle' => $salon->faturasiz_gizle ? 1 : 0]);
    }

    /**
     * Salon-wide faturasiz gizle toggle durumunu getirir
     * (Flutter app dashboard ikonu state'i icin).
     */
    public function faturasizGizleDurum(Request $request)
    {
        $sube = self::mevcutsube($request);
        $deger = (int) Salonlar::where('id', $sube)->value('faturasiz_gizle');
        return response()->json(['faturasiz_gizle' => $deger]);
    }

}
